// Kaynak: D:\JSPS Fabrika ... KANUN_MASTER_DOSYALARI/MUSTEREK/*/​*MASTER*.md (📜 Metin blokları).
// Anahtar = "<etiket> m.<no>" → kart.madde_no ile birebir eşleşir.
// maddeMetni() bu registry'yi el-yazımı MADDE_METINLERI'nden SONRA kontrol eder.

export const KART_MADDE_METINLERI: Record<string, string> = {
  "2521 Tüfekler Yön m.1": "Madde 1 - Bu yönetmeliğin amacı; 2521 sayılı Avda ve Sporda Kullanılan Tüfekler, Nişan Tabancaları ve Av Bıçaklarının Yapımı Alımı, Satımı ve Bulundurulmasına Dair Kanunun uygulama şeklini belirlemektedir. Madde 2 - Bu Yönetmelik; yivsiz av tüfekleri ile sporda kullanılan nişan tüfek ve tabancaları ve bunların aksamını imal eden fabrika ve imalathanelerin kurulması ve işletilmesine izin verilmesi, mamullerinin standardizasyonu ve denetlenmesine ilişkin hükümler ile 2521 sayılı Kanun kapsamına giren tüfeklerin alımı satımı, bulundurulması ve bunlar için düzenlenecek belge ve kayıtların tesisiyle ilgili esas ve usûlleri kapsar. Madde 3 - Bu yönetmelik 2521 sayılı Kanunun 15. Maddesine göre düzenlenmiştir.",
  "2521 Tüfekler Yön m.11": "Madde 11 - Av Bıçağı imal eden fabrika veya imalathaneler, imal ettikleri bıçakların namlusunun kabza ile bağlantılı ön kısmına, imalatçı firma adı ya da rumuzunu ve \"T.M.\" harflerini ihtiva eden damga ile damgalatarak zorundadırlar. (...) Bu yönetmelikte tanımı ve özellikleri belirtilen av bıçaklarının işyeri veya meskende bulundurulması belgeye tabi değildir. Ancak, av tezkereleriyle birlikte avlaklarda üstte taşınabilir. Av bıçakları meskun mahalde veya şehir içinde aşağıda gösterildiği şekilde taşınır. a) Av torbası veya çantasında, b) Ani olaylarda kullanılmayı engelleyecek biçimde kağıt veya bezle sarılıp paketlenmiş şekilde üstte, Bu madde hükmüne aykırı olarak av bıçağı taşıyanlar hakkında gerekli yasal işlem yapılır.",
  "2521 Tüfekler Yön m.12": "Madde 12 - (Değişik:RG-22/4/2009-27208) Bu Yönetmelik hükümlerine göre yivsiz tüfek ruhsatnamesi alan kişiler bu belgelerde kayıtlı yivsiz av tüfeklerini sadece yivsiz tüfek ruhsatnamesi olan kişilere satabilir veya hibe yoluyla devredebilir. Devreden ve devralan kişiler en geç bir ay içinde ruhsatname düzenleyen makamlara başvurarak devrettikleri tüfeği belgelerinden sildirmek ve devraldıkları tüfeği belgelerine işletmek zorundadır. (...) Madde 13 - (...) Bu şekilde satın alınan av tüfeklerinin en geç bir ay içerisinde belgenin alındığı makama müracaatla cins, marka, çap ve seri numarasının kaydettirilmesi zorunludur. Ruhsatname üzerine tüfeklerin kaydedilmesi işlemi esnasında tüfeklerin görülerek tespitinin yapılması esastır.",
  "2521 Tüfekler Yön m.14": "Madde 14 - (Değişik:RG-11/06/1998-23369) Aşağıda belirtilen hallerden birine giren kimselere hiçbir şekilde avda ve sporda kullanılan tüfek, nişan tabancası ve av bıçağı yapımı alımı, satımı, taşınması ve bulundurulması izni ve belgesi verilmez. a) Ateşli silahla işlenen cürümlerden hükümlü bulunanlar, (...) h) Uyuşturucu ve psikotrop maddeleri (...) suçlarından biriyle mahkum olanlar, ı) Kısıtlı olanlar ile Kamu hizmetinden yasaklılar, i) Akıl hastası veya psikolojik ve nörolojik rahatsızlıkları olanlar, j) 18 yaşını bitirmemiş olanlar, Yukarıdaki fıkranın (a), (b), (c), (d), (e), (f), (g) ve (h) bentleri kapsamına girenler, affa uğramış olsalar veya mahkumiyetleri bütün neticeleriyle birlikte ortadan kalksa yada mahkemelerce verilen karar üzerine adli sicilden silinmiş olsa bile, kendilerine hiçbir suretle bu Yönetmelik kapsamına giren belge ve izinler verilmez. (...) Bu madde de belirtilen mahkumiyet, kesinleşmiş mahkumiyettir.",
  "2521 Tüfekler Yön m.18": "Madde 18 - (Değişik ibare:RG-22/4/2009-27208) Yivsiz tüfek ruhsatnamesi alan kişiler ve bunların sahip olduğu silahlar için, belgeyi düzenleyen zabıta makamlarınca (Örnek - 6) deki Silah Kayıt Defteri tutulur. Silah kayıt defteri hiçbir şekilde imha edilemez. Kayıt defterleri görev değişikliklerinde görev devralan yetkiliye tutanakla teslim edilir. Silah kayıt defterinden sahife koparılamaz, silinti ve kazıntı yapılamaz. Yanlışlıklar ve hatalı kayıtlar açıklamalar hanesine gerekli şerh verilmek ve sorumlu amirce imzalanıp mühürlendikten sonra kaydın üstü çizilir.",
  "2521 Tüfekler Yön m.4": "Madde 4 - Bu yönetmelikte geçen; a) Yivsiz av tüfekleri: Avda ve atıcılık sporunda kullanılan ve namlularında yiv - set bulunmayan tüfekleri, b) Spor ve nişan tüfek ve tabancaları: Hava ve gaz basıncı ile çalışan ateşsiz, namlusu yivli veya yivsiz olan, uluslararası standartlara uygun tüfek ve tabancaları, c) Av Bıçağı: Sadece avda kullanılan, av hayvanlarını kesmeye, yüzmeye, parçalamaya yarayan oluksuz, sırtı küt veya testereli bıçakları, d) (Ek:RG-11/7/2025-32953) Test Merkezi: Bu Yönetmelik kapsamında imal edilen veya ithal edilen yivsiz av tüfekleri ile spor ve nişan tüfek ve tabancalarının ilgili Türk standartlarına uygunluğunu sertifikalandırmak amacıyla muayene ve deneylerin gerçekleştirildiği, İçişleri Bakanlığı veya Sanayi ve Teknoloji Bakanlığınca kurulan merkezi, ifade eder.",
  "2521 Tüfekler Yön m.5": "Fabrika veya imalathane kurmak isteyenler; kuruluş izni almak için (Değişik ibare:RG-11/7/2025-32953) Sanayi ve Teknoloji Bakanlığına aşağıda belirtilen bilgi ve belgeleri kapsayan üç nüsha olarak hazırlanmış dosya ile müracaat eder. (...) Teknik sorumlunun makine mühendisi olma şartı aranır. Bir teknik sorumlu mühendis, yalnızca bir ikamet adresi geçerli olmak şartıyla ikamet etmiş olduğu il sınırları içerisinde en fazla 20 firmanın teknik sorumluluğunu üstlenebilir. (...) Kuruluş izni, fabrika veya imalathanenin yıllık kapasitesi dikkate alınarak ve herhalde iki yılı geçmemek üzere İçişleri Bakanlığınca belirlenecek süre için geçerlidir. Bu süre ancak, (...) bir seneyi geçmemek ve bir defaya mahsus olmak üzere uzatılabilir.",
  "2521 Tüfekler Yön m.7": "Madde 7 - (Değişik:RG-11/7/2025-32953) Yivsiz av tüfeği imal eden fabrika ve imalathanelerde üretilen tüfeklerin ilgili Türk standartlarına uygun imal edilip edilmediği hususundaki denetimler İçişleri Bakanlığı ile Sanayi ve Teknoloji Bakanlığınca ilgili mevzuat çerçevesinde müştereken yapılır. Namlu basınç testlerine ilişkin kriterler TS 870 standardı kapsamında belirlenir. (...) Test Merkezleri, İçişleri Bakanlığı ile Sanayi ve Teknoloji Bakanlığı temsilcilerinden oluşan komisyon tarafından yılda en az bir defa denetlenir. (...) Bu madde kapsamındaki Türk standartlarına uygunluk testleri, sadece izin verilen Test Merkezlerinde yapılır.",
  "2521 Tüfekler Yön m.8": "Madde 8 - Bu yönetmelik kapsamına giren yivsiz av tüfekleri ile nişan tüfek ve tabancası imal eden kişi ve kuruluşlar, o ay içinde imal ettikleri ve sattıkları mamûllerin cins, marka, çap ve seri numaralarını belirtmek koşulu ile miktarını ve satın alan kişi ve kuruluşun ad ve açık adreslerini belirleyecek tarzda iki nüsha olarak düzenleyecekleri (...) listeleri, (...) ertesi ayın sonuna kadar İlçelerde Kaymakamlığa, İl Merkez İlçelerinde Valiliğe vermek zorundadırlar. (...) Polis teşkilatı bulunmayan yerlerde bu görevi Jandarma Komutanlıkları yapar. Madde 9 - (Değişik birinci fıkra:RG-22/4/2009-27208) Fabrika ve İmalathanelerde yivsiz tüfeklerin satışında; satıcıdan (bayilerden) satıcılık belgesi, alıcıdan yivsiz tüfek satın alma belgesi aranır. Hava ve gaz basıncı ile çalışan ateşsiz tüfek ve tabanca satışlarında bu belge aranmaz.",
  "2521 Tüfekler Yön m.Ek 2": "Ek Madde 2 - (Ek:RG-07/12/2000-24253) Bu Yönetmelikle düzenlenen ve Emniyet Genel Müdürlüğünce yerine getirilen yetki ve görevlerden jandarma sorumluluk bölgesinde ikamet eden gerçek ve tüzel kişilere ilişkin olanlar, aynı esaslara göre Jandarma Genel Komutanlığınca yerine getirilir. Jandarma Genel Komutanlığınca yerine getirilecek işlemlere ilişkin olarak, polis laboratuarlarınca yerine getirilen görevler jandarma kriminal laboratuarınca, Türk Polis Teşkilatını Güçlendirme Vakfınca yerine getirilen görevler Jandarma Asayiş Vakfınca yerine getirilir. (...)",
  "6136 Ateşli Silahlar m.11": "Hatıra teşkil eden veya antika olan ateşli silahlarla bıçakların bulundurulmasına izin verilmesi zorunludur. Ancak, görevleri nedeniyle Devletçe verilen veya kendilerince bu amaçla temin edilen ve bu görevleri sona erdikten sonra meskenlerinde kalan veya kanuni yakınlarına intikal eden kılıç, meç ve benzeri aletler için izin belgesi aranmaz. Antika olan ateşli silahlarla bıçaklar için verilen izin bunların yalnız sahibine bırakılmasına veya nakline müsaadeyi tazammun edip üstte taşımaya cevaz vermez. Antika olan ateşli silahlarla bıçakların izin vesikalarıyla birlikte satışı serbesttir. Bu Kanunun uygulanmasında hatıra silah deyimi: a) Yurt içinde ve yurt dışında yabancı Devlet veya hükümet başkanları ya da hükümet üyeleri tarafından ya da hükümet adına kendilerine hediye edilip, hediye edildiği usulüne göre belgelenmiş olan, b) Devlet Başkanı, Başbakan veya Genelkurmay Başkanı tarafından hediye edilen ve hediye edildiği belgelendirilen (...) ateşli veya ateşsiz silah ve bıçakları ifade eder. Antika silah deyimi; eskiden kalma, değerli belli bir özelliği olan, benzerlerine az rastlanan ve artık imal edilmeyen ateşli, ateşsiz silah ve bıçakları ifade eder.",
  "6136 Ateşli Silahlar m.12": "Her kim bu Kanunun kapsamına giren ateşli silahları, bunlara ait mermileri veya bunlara ait namlu, sürgü, gövde, çerçeve, silindir, mekanizma başı, çıkarıcı, tırnak, ateşleme iğnesinden oluşan ana veya balistik önemi haiz parçaları ülkeye sokar veya sokmaya kalkışır veya bunların ülkeye sokulmasına aracılık eder veya bunları (...) ülkede yapar veya (...) bir yerden diğer bir yere taşır veya yollar veya taşımaya bilerek aracılık eder, satar veya satmaya aracılık ederse veya bu amaçla bulundurursa beş yıldan oniki yıla kadar hapis ve beşyüz günden beşbin güne kadar adlî para cezasıyla cezalandırılır. (...) iki veya daha çok kişinin birlikte işlemeleri halinde (...) sekiz yıldan onbeş yıla kadar hapis ve bin günden onbin güne kadar adlî para cezasına hükmolunur. (...) suç işlemek amacıyla kurulmuş bir örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek cezalar bir kat artırılır. (...) miktar bakımından vahim olması halinde (...) cezalar yarı oranında artırılarak hükmolunur. (Ek fıkra:21/11/2024-7533/11 md.) Kurusıkı tabir edilen ses veya gaz fişeği ya da benzerlerini atabilen silahı, teknik özelliklerinde değişiklik yaparak bu Kanun hükümlerine tabi silah haline dönüştürmek eylemi (...) üretim olarak kabul edilir ve bu madde hükümlerine göre cezalandırılır.\n\nBu Kanun hükümlerine aykırı olarak ateşli silahları, bunlara ait mermileri veya bunlara ait (...) ana veya balistik önemi haiz parçaları ya da ses veya gaz fişeği atabilen silah iken bu Kanun hükümlerine tabi silah vasfına dönüştürülen silahları satın alan veya taşıyanlar veya bulunduranlar hakkında iki yıldan dört yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasına hükmolunur. Ateşli silahın, (...) 12 nci maddesinin dördüncü fıkrasında sayılanlardan olması ya da (...) sayı veya nitelik bakımından vahim olması halinde beş yıldan sekiz yıla kadar hapis (...). (...) ateşli silahın bir adet olması ve mutat sayıdaki mermilerinin (...) ev veya işyerinde bulundurulması halinde verilecek ceza bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasıdır. (...) pek az sayıda bulundurulmasının veya taşınmasının mahkemece vahim olarak takdir edilmemesi durumunda hükmolunacak ceza altı aya kadar hapis ve otuz günden beşyüz güne kadar adlî para cezasıdır. (Değişik beşinci fıkra:21/11/2024-7533/12 md.) Bu madde kapsamındaki bulundurma ve taşıma fiilinin; vefat, sağlık durumu, mahkûmiyet, müsadere, satın alma veya devir nedeniyle yapılan ruhsatlandırma ya da ruhsat yenileme işlemlerinde (...) yükümlülüklere aykırı davranılarak işlenmesi halinde onbin Türk Lirasından yirmibeşbin Türk Lirasına kadar idari para cezasına hükmolunur. (Ek fıkra:21/11/2024-7533/12 md.) Nakil izin belgesi almaksızın, bulundurma izni verilen silahını mesken veya işyeri değişikliği nedeniyle nakledenler hakkında onbin Türk Lirasından yirmibeşbin Türk Lirasına kadar idari para cezasına hükmolunur. (...) idari para cezası vermeye mülki idare amiri yetkilidir.\n\nHer kim bu Kanunun kapsamına giren ateşli silahları, bunlara ait mermileri veya bunlara ait namlu, sürgü, gövde, çerçeve, silindir, mekanizma başı, çıkarıcı, tırnak, ateşleme iğnesinden oluşan ana veya balistik önemi haiz parçaları ülkeye sokar veya sokmaya kalkışır veya bunların ülkeye sokulmasına aracılık eder veya bunları (...) ülkede yapar veya (...) bir yerden diğer bir yere taşır veya yollar veya taşımaya bilerek aracılık eder, satar veya satmaya aracılık ederse veya bu amaçla bulundurursa beş yıldan oniki yıla kadar hapis ve beşyüz günden beşbin güne kadar adlî para cezasıyla cezalandırılır. (...) iki veya daha çok kişinin birlikte işlemeleri halinde (...) sekiz yıldan onbeş yıla kadar hapis (...). (...) suç işlemek amacıyla kurulmuş bir örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek cezalar bir kat artırılır. (...) miktar bakımından vahim olması halinde (...) cezalar yarı oranında artırılarak hükmolunur.",
  "6136 Ateşli Silahlar m.13": "Bu Kanun hükümlerine aykırı olarak ateşli silahları, bunlara ait mermileri veya bunlara ait namlu, sürgü, gövde, çerçeve, silindir, mekanizma başı, çıkarıcı, tırnak, ateşleme iğnesinden oluşan ana veya balistik önemi haiz parçaları (...) satın alan veya taşıyanlar veya bulunduranlar hakkında iki yıldan dört yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasına hükmolunur. Ateşli silahın, (...) 12 nci maddesinin dördüncü fıkrasında sayılanlardan olması ya da silahın, mermilerin (...) sayı veya nitelik bakımından vahim olması halinde beş yıldan sekiz yıla kadar hapis (...). (...) ateşli silahın bir adet olması ve mutat sayıdaki mermilerinin (...) ev veya işyerinde bulundurulması halinde verilecek ceza bir yıldan üç yıla kadar hapis ve yüz günden beşyüz güne kadar adlî para cezasıdır. Ateşli silahlara ait mermilerin veya bunlara ait (...) parçaların pek az sayıda bulundurulmasının veya taşınmasının mahkemece vahim olarak takdir edilmemesi durumunda hükmolunacak ceza altı aya kadar hapis ve otuz günden beşyüz güne kadar adlî para cezasıdır. (Değişik beşinci fıkra:21/11/2024-7533/12 md.) Bu madde kapsamındaki bulundurma ve taşıma fiilinin; vefat, sağlık durumu, mahkûmiyet, müsadere, satın alma veya devir nedeniyle yapılan ruhsatlandırma ya da ruhsat yenileme işlemlerinde bu Kanunda düzenlenen yükümlülüklere aykırı davranılarak işlenmesi halinde onbin Türk Lirasından yirmibeşbin Türk Lirasına kadar idari para cezasına hükmolunur.",
  "6136 Ateşli Silahlar m.15": "Bu Kanun hükümlerine aykırı olarak 4 üncü maddede yazılı olan bıçak veya diğer aletleri veya benzerlerini satanlar, satmaya aracılık edenler, satın alanlar, taşıyanlar veya bulunduranlar hakkında altı aydan bir yıla kadar hapis ve yirmibeş günden az olmamak üzere adlî para cezasına hükmolunur. Bu madde kapsamına giren bıçak veya diğer aletlerin veya benzerlerinin sayı veya nitelik bakımından vahim olması halinde yukarıdaki fıkraya göre hükmolunacak cezalar yarıdan bir katına kadar artırılır. (...) (Bu Kanunun 4 üncü maddesinin üçüncü fıkrasında yazılı olan yivli ve yivsiz silahlarla bıçak ve diğer aletleri, hal ve şartlara göre sırf saldırıda kullanmak amacıyla taşıyanlar, üç aya kadar hapis veya adlî para cezası ile cezalandırılır.)",
  "6136 Ateşli Silahlar m.4": "Ülke içinde kama, hançer, saldırma, şişli baston, sustalı çakı, pala, kılıç, kasatura, süngü, sivri uçlu ve oluklu bıçaklar, topuz, topuzlu kamçı, boğma teli veya zinciri, muşta ile salt saldırı ve savunmada kullanılmak üzere özel nitelikteki benzeri aletlerin yapımı yasaktır. Bunlardan bir sanat veya mesleğin icrası için kullanılması zorunlu bulunanların yapımına İçişleri Bakanlığınca yapılacak bir yönetmelikte belirlenen kurallara göre izin verilir. (...) Yalnız sporda kullanılan yivli ateşsiz silahlar ve mermileri ile yivsiz tüfekler ve mermilerinin, ev gereçlerinden olan veya tababet, sanayi, tarım, spor için kullanılan aletlerle bir meslek veya sanatın icrası için gerekli bıçak, şiş, raspa ve benzerlerinin kullanılması bu Kanun hükümlerine tabi değildir.",
  "6136 Ateşli Silahlar m.5": "Yurda sokulması ve yapımı yasaklanan ve 4 ncü maddenin 1 nci fıkrası kapsamına giren bıçak ve aletlerin satılması, satınalınması, taşınması ve bulundurulması yasaktır. Bir sanat veya mesleğin icrası için kullanılmasına 4 ncü maddeye göre izin verilen bıçaklar bu yasağın dışındadırlar.",
  "6136 Ateşli Silahlar m.Ek 1": "A) Duruşmalarda, mahkeme salonlarında, hastanelerin psikiyatri bölümlerinde, akıl hastanelerinde, ceza ve tutukevleri ile her türlü ıslah ve infaz kurumlarında veya bunların eklentilerinde, B) Öğrencilerin toplu olarak oturdukları yurtlarda, eğitim ve öğretim kurumlarında, siyasi partilerin açık hava ve kapalı yer toplantılarında, izinli veya izinsiz yapılan toplantı ve gösteri yürüyüşlerinde, sendikalarda, derneklerde (...), her türlü spor karşılaşma veya yarışmalarının yapıldığı yerlerde, (...) grev ve lokavt yapılmakta olan iş yerlerinde, C) Türkiye Büyük Millet Meclisi ana binaları ile Meclis Başkanlığınca belirlenen yerlerde, Ateşli silahlar taşınamaz. Yukarıda sayılan yerlerde bu Kanuna aykırı olarak ateşli silahları (...) taşıyan veya bulunduranlar hakkında ilgili kanunlarda belli edilen cezaların iki katı hükmolunur. (A) ve (B) bentlerinde sayılan yerlerde 7 nci maddenin 1, 2, 3 ve 4 numaralı bentlerinde belirtilen kişiler ile bu yerlerin güvenliği için görevli bulunan polis ve jandarma personeli, (C) bendinde sayılan yerlerde ise yalnız bu yerlerin güvenliği ile görevli bulunan polis, jandarma ve Türkiye Büyük Millet Meclisi Muhafız Taburu personeli silahlarını taşıyabilirler. (A), (B) ve (C) bentlerinde sayılan yerlere silahla giren veya buralarda silah taşıyan kişiler, fiilleri daha ağır cezayı gerektiren başka bir suç oluşturmadığı takdirde, elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Ayrıca, bu kişilerin silah ruhsatları bulundurmaya çevrilir. (...)\n\nA) Duruşmalarda, mahkeme salonlarında, hastanelerin psikiyatri bölümlerinde, akıl hastanelerinde, ceza ve tutukevleri ile her türlü ıslah ve infaz kurumlarında veya bunların eklentilerinde, B) Öğrencilerin toplu olarak oturdukları yurtlarda, eğitim ve öğretim kurumlarında, siyasi partilerin açık hava ve kapalı yer toplantılarında, izinli veya izinsiz yapılan toplantı ve gösteri yürüyüşlerinde, sendikalarda, derneklerde (...), her türlü spor karşılaşma veya yarışmalarının yapıldığı yerlerde, (...) grev ve lokavt yapılmakta olan iş yerlerinde, C) Türkiye Büyük Millet Meclisi ana binaları ile Meclis Başkanlığınca belirlenen yerlerde, Ateşli silahlar taşınamaz. Yukarıda sayılan yerlerde bu Kanuna aykırı olarak ateşli silahları (...) taşıyan veya bulunduranlar hakkında ilgili kanunlarda belli edilen cezaların iki katı hükmolunur. (A) ve (B) bentlerinde sayılan yerlerde 7 nci maddenin 1, 2, 3 ve 4 numaralı bentlerinde belirtilen kişiler ile bu yerlerin güvenliği için görevli bulunan polis ve jandarma personeli, (C) bendinde sayılan yerlerde ise yalnız bu yerlerin güvenliği ile görevli bulunan polis, jandarma ve Türkiye Büyük Millet Meclisi Muhafız Taburu personeli silahlarını taşıyabilirler. (A), (B) ve (C) bentlerinde sayılan yerlere silahla giren veya buralarda silah taşıyan kişiler, fiilleri daha ağır cezayı gerektiren başka bir suç oluşturmadığı takdirde, elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Ayrıca, bu kişilerin silah ruhsatları bulundurmaya çevrilir. (...) beş yıllık süre geçmediği takdirde, bu kişilere taşıma ruhsatı verilmez.\n\nKara Avcılığı Kanunu esaslarına göre izin alıp turist olarak avcılık yapmak ya da Gençlik ve Spor Bakanlığınca tertip olunacak atıcılık yarışmalarına katılmak üzere yurda gelen yabancılar beraberlerinde getirdikleri miktarı yönetmelikte belirtilen yivli ve yivsiz tüfekler ile nişan tüfek ve tabancalarını ve bunların aksamı ile mermilerini gümrük makamlarına beyan etmek ve giriş kapısı emniyet makamlarından izin almak koşuluyla geçici olarak yurda sokabilirler. Antlaşmalarla yurdumuza görevli olarak gelen yabancılar ile bilimsel araştırmalar yapmak amacıyla gelen kişiler de beraberlerinde getirecekleri yivli veya yivsiz tüfekler ve aksamı ile mermilerini İçişleri Bakanlığı Emniyet Genel Müdürlüğünden izin almak ve gümrük makamlarına beyan etmek şartıyla yurda sokabilirler. (...) yurda sokulmasına izin verilen silah, silah aksamı ve mermileri ilgili kişilerin pasaportuna kaydolunur. Bu kayıt silah, aksamı ve mermileri için taşıma izin vesikası yerine geçer. (...) sarfedilmeyen mermilerin ülkemiz terkedilirken yolcu beraberinde yurt dışına çıkarılması zorunludur.",
  "6284 Ailenin Korunması m.1": "MADDE 1 – (1) Bu Kanunun amacı; şiddete uğrayan veya şiddete uğrama tehlikesi bulunan kadınların, çocukların, aile bireylerinin ve tek taraflı ısrarlı takip mağduru olan kişilerin korunması ve bu kişilere yönelik şiddetin önlenmesi amacıyla alınacak tedbirlere ilişkin usul ve esasları düzenlemektir. (...) MADDE 2 – (1) Bu Kanunda yer alan; a) Bakanlık: Aile ve Sosyal Politikalar Bakanlığını, c) Hâkim: Aile mahkemesi hâkimini, (...) d) Şiddet: Kişinin, fiziksel, cinsel, psikolojik veya ekonomik açıdan zarar görmesiyle veya acı çekmesiyle sonuçlanan veya sonuçlanması muhtemel hareketleri, buna yönelik tehdit ve baskıyı ya da özgürlüğün keyfî engellenmesini de içeren, toplumsal, kamusal veya özel alanda meydana gelen fiziksel, cinsel, psikolojik, sözlü veya ekonomik her türlü tutum ve davranışı, (...) g) Şiddet uygulayan: Bu Kanunda şiddet olarak tanımlanan tutum ve davranışları uygulayan veya uygulama tehlikesi bulunan kişileri, ğ) Tedbir kararı: Bu Kanun kapsamında, şiddet mağdurları ve şiddet uygulayanlar hakkında hâkim, kolluk görevlileri ve mülkî amirler tarafından, istem üzerine veya resen verilecek tedbir kararlarını, ifade eder.",
  "6284 Ailenin Korunması m.13": "MADDE 13 – (1) Bu Kanun hükümlerine göre hakkında tedbir kararı verilen şiddet uygulayan, bu kararın gereklerine aykırı hareket etmesi hâlinde, fiili bir suç oluştursa bile ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre hâkim kararıyla üç günden on güne kadar zorlama hapsine tabi tutulur. (2) Tedbir kararının gereklerine aykırılığın her tekrarında, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre zorlama hapsinin süresi onbeş günden otuz güne kadardır. Ancak zorlama hapsinin toplam süresi altı ayı geçemez. (3) Zorlama hapsine ilişkin kararlar, Cumhuriyet başsavcılığınca yerine getirilir. Bu kararlar Bakanlığın ilgili il ve ilçe müdürlüklerine bildirilir.",
  "6284 Ailenin Korunması m.3": "MADDE 3 – (1) Bu Kanun kapsamında korunan kişilerle ilgili olarak aşağıdaki tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere mülkî amir tarafından karar verilebilir: a) Kendisine ve gerekiyorsa beraberindeki çocuklara, bulunduğu yerde veya başka bir yerde uygun barınma yeri sağlanması. b) Diğer kanunlar kapsamında yapılacak yardımlar saklı kalmak üzere, geçici maddi yardım yapılması. c) Psikolojik, meslekî, hukukî ve sosyal bakımdan rehberlik ve danışmanlık hizmeti verilmesi. ç) Hayatî tehlikesinin bulunması hâlinde, ilgilinin talebi üzerine veya resen geçici koruma altına alınması. d) Gerekli olması hâlinde, korunan kişinin çocukları varsa çalışma yaşamına katılımını desteklemek üzere dört ay, kişinin çalışması hâlinde ise iki aylık süre ile sınırlı olmak kaydıyla, on altı yaşından büyükler için her yıl belirlenen aylık net asgari ücret tutarının yarısını geçmemek ve belgelendirilmek kaydıyla Bakanlık bütçesinin ilgili tertibinden karşılanmak suretiyle kreş imkânının sağlanması. (2) Gecikmesinde sakınca bulunan hâllerde birinci fıkranın (a) ve (ç) bentlerinde yer alan tedbirler, ilgili kolluk amirlerince de alınabilir. Kolluk amiri evrakı en geç kararın alındığı tarihi takip eden ilk işgünü içinde mülkî amirin onayına sunar. Mülkî amir tarafından kırksekiz saat içinde onaylanmayan tedbirler kendiliğinden kalkar.",
  "6284 Ailenin Korunması m.4": "MADDE 4 – (1) Bu Kanun kapsamında korunan kişilerle ilgili olarak aşağıdaki koruyucu tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere hâkim tarafından karar verilebilir: a) İşyerinin değiştirilmesi. b) Kişinin evli olması hâlinde müşterek yerleşim yerinden ayrı yerleşim yeri belirlenmesi. c) 22/11/2001 tarihli ve 4721 sayılı Türk Medenî Kanunundaki şartların varlığı hâlinde ve korunan kişinin talebi üzerine tapu kütüğüne aile konutu şerhi konulması. ç) Korunan kişi bakımından hayatî tehlikenin bulunması ve bu tehlikenin önlenmesi için diğer tedbirlerin yeterli olmayacağının anlaşılması hâlinde ve ilgilinin aydınlatılmış rızasına dayalı olarak 27/12/2007 tarihli ve 5726 sayılı Tanık Koruma Kanunu hükümlerine göre kimlik ve ilgili diğer bilgi ve belgelerinin değiştirilmesi.",
  "6284 Ailenin Korunması m.5": "MADDE 5 – (1) Şiddet uygulayanlarla ilgili olarak aşağıdaki önleyici tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere hâkim tarafından karar verilebilir: a) Şiddet mağduruna yönelik olarak şiddet tehdidi, hakaret, aşağılama veya küçük düşürmeyi içeren söz ve davranışlarda bulunmaması. b) Müşterek konuttan veya bulunduğu yerden derhâl uzaklaştırılması ve müşterek konutun korunan kişiye tahsis edilmesi. c) Korunan kişilere, bu kişilerin bulundukları konuta, okula ve işyerine yaklaşmaması. ç) Çocuklarla ilgili daha önce verilmiş bir kişisel ilişki kurma kararı varsa, kişisel ilişkinin refakatçi eşliğinde yapılması, kişisel ilişkinin sınırlanması ya da tümüyle kaldırılması. d) Gerekli görülmesi hâlinde korunan kişinin, şiddete uğramamış olsa bile yakınlarına, tanıklarına ve kişisel ilişki kurulmasına ilişkin hâller saklı kalmak üzere çocuklarına yaklaşmaması. e) Korunan kişinin şahsi eşyalarına ve ev eşyalarına zarar vermemesi. f) Korunan kişiyi iletişim araçlarıyla veya sair surette rahatsız etmemesi. g) Bulundurulması veya taşınmasına kanunen izin verilen silahları kolluğa teslim etmesi. ğ) Silah taşıması zorunlu olan bir kamu görevi ifa etse bile bu görevi nedeniyle zimmetinde bulunan silahı kurumuna teslim etmesi. h) Korunan kişilerin bulundukları yerlerde alkol ya da uyuşturucu veya uyarıcı madde kullanmaması ya da bu maddelerin etkisinde iken korunan kişilere ve bunların bulundukları yerlere yaklaşmaması, bağımlılığının olması hâlinde, hastaneye yatmak dâhil, muayene ve tedavisinin sağlanması. ı) Bir sağlık kuruluşuna muayene veya tedavi için başvurması ve tedavisinin sağlanması. (2) Gecikmesinde sakınca bulunan hâllerde birinci fıkranın (a), (b), (c) ve (d) bentlerinde yer alan tedbirler, ilgili kolluk amirlerince de alınabilir. Kolluk amiri evrakı en geç kararın alındığı tarihi takip eden ilk işgünü içinde hâkimin onayına sunar. Hâkim tarafından yirmidört saat içinde onaylanmayan tedbirler kendiliğinden kalkar.",
  "6284 Ailenin Korunması m.8": "MADDE 8 – (1) Tedbir kararı, ilgilinin talebi, Bakanlık veya kolluk görevlileri ya da Cumhuriyet savcısının başvurusu üzerine verilir. Tedbir kararları en çabuk ve en kolay ulaşılabilecek yer hâkiminden, mülkî amirden ya da kolluk biriminden talep edilebilir. (2) Tedbir kararı ilk defasında en çok altı ay için verilebilir. Ancak şiddet veya şiddet uygulanma tehlikesinin devam edeceğinin anlaşıldığı hâllerde, resen, korunan kişinin ya da Bakanlık veya kolluk görevlilerinin talebi üzerine tedbirlerin süresinin veya şeklinin değiştirilmesine, bu tedbirlerin kaldırılmasına veya aynen devam etmesine karar verilebilir. (3) Koruyucu tedbir kararı verilebilmesi için, şiddetin uygulandığı hususunda delil veya belge aranmaz. Önleyici tedbir kararı, geciktirilmeksizin verilir. (...) (4) Tedbir kararı, korunan kişiye ve şiddet uygulayana tefhim veya tebliğ edilir. (...) (5) Tedbir kararının tefhim ve tebliğ işlemlerinde, tedbir kararına aykırılık hâlinde şiddet uygulayan hakkında zorlama hapsinin uygulanacağı ihtarı yapılır. (6) Gerekli bulunması hâlinde, tedbir kararı ile birlikte talep üzerine veya resen, korunan kişi ve diğer aile bireylerinin kimlik bilgileri veya kimliğini ortaya çıkarabilecek bilgileri ve adresleri ile korumanın etkinliği bakımından önem taşıyan diğer bilgileri, tüm resmi kayıtlarda gizli tutulur. (...)",
  "6284 Ailenin Korunması m.9": "MADDE 9 – (1) Bu Kanun hükümlerine göre verilen kararlara karşı tefhim veya tebliğ tarihinden itibaren iki hafta içinde ilgililer tarafından aile mahkemesine itiraz edilebilir. (2) Hâkim tarafından verilen tedbir kararlarına itiraz üzerine dosya, o yerde aile mahkemesinin birden fazla dairesinin bulunması hâlinde, numara olarak kendisini izleyen daireye, son numaralı daire için birinci daireye, o yerde aile mahkemesinin tek dairesi bulunması hâlinde asliye hukuk mahkemesine, aile mahkemesi hâkimi ile asliye hukuk mahkemesi hâkiminin aynı hâkim olması hâlinde ise en yakın asliye hukuk mahkemesine gecikmeksizin gönderilir. (3) İtiraz mercii kararını bir hafta içinde verir. İtiraz üzerine verilen kararlar kesindir.",
  "6284 Uyg. Yön m.12": "MADDE 12 –(1) Kanun kapsamında korunan kişilerle ilgili olarak hâkim tarafından, (...) şiddetin uygulandığı hususunda delil veya belge aranmaksızın aşağıdaki koruyucu tedbirlerden birine, birkaçına veya olayın özelliğine göre mülki amir tarafından alınabilecek tedbirler de dâhil olmak üzere, uygun görülecek benzer tedbirlere karar verilebilir: a) İş yerinin değiştirilmesi. b) Kişinin evli olması hâlinde müşterek yerleşim yerinden ayrı yerleşim yeri belirlenmesi. c) (...) korunan kişinin talebi üzerine tapu kütüğüne aile konutu şerhi konulması. ç) (...) hayatî tehlikenin bulunması ve (...) diğer tedbirlerin yeterli olmayacağının anlaşılması hâlinde ve ilgilinin aydınlatılmış rızasına dayalı olarak (...) Tanık Koruma Kanununa göre kimlik ve ilgili diğer bilgi ve belgelerinin değiştirilmesi.",
  "6284 Uyg. Yön m.17": "MADDE 17 –(1) Hâkim tarafından şiddet uygulayanlarla ilgili olarak aşağıdaki önleyici tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere karar verilebilir: a) Şiddet mağduruna yönelik olarak şiddet tehdidi, hakaret, aşağılama veya küçük düşürmeyi içeren söz ve davranışlarda bulunmaması. b) Müşterek konuttan veya bulunduğu yerden derhâl uzaklaştırılması ve müşterek konutun korunan kişiye tahsis edilmesi. c) Korunan kişilere, bu kişilerin bulundukları konuta, okula ve işyerine yaklaşmaması. ç) Çocuklarla ilgili daha önce verilmiş bir kişisel ilişki kurma kararı varsa, kişisel ilişkinin refakatçi eşliğinde kurulması, kişisel ilişkinin sınırlanması ya da tümüyle kaldırılması. d) Gerekli görülmesi hâlinde korunan kişinin, şiddete uğramamış olsa bile yakınlarına, tanıklarına ve (...) çocuklarına yaklaşmaması. e) Korunan kişinin şahsi eşyalarına ve ev eşyalarına zarar vermemesi. f) Korunan kişiyi iletişim araçlarıyla veya sair surette rahatsız etmemesi. g) Bulundurulması veya taşınmasına kanunen izin verilen silahları kolluğa teslim etmesi. ğ) Silah taşıması zorunlu olan bir kamu görevi ifa etse bile bu görevi nedeniyle zimmetinde bulunan silahı kurumuna teslim etmesi. h) Korunan kişilerin bulundukları yerlerde alkol ya da uyuşturucu veya uyarıcı madde kullanmaması (...) bağımlılığının olması hâlinde, hastaneye yatmak dâhil, muayene ve tedavisinin sağlanması. ı) Bir sağlık kuruluşuna muayene veya tedavi için başvurması ve tedavisinin sağlanması. (3) Şiddet uygulayan, aynı zamanda ailenin geçimini sağlayan (...) kişi ise hâkim, (...) talep edilmese dahi tedbir nafakasına hükmedebilir. Tedbir nafakasının tahsili 43 üncü maddeye göre yapılır.",
  "6284 Uyg. Yön m.29": "MADDE 29 – (1) Mülkî amir tarafından alınabilecek barınma yeri sağlanmasına ve geçici koruma altına alınmasına ilişkin tedbirler, gecikmesinde sakınca bulunan hâllerde ilgili kolluk amirince de alınabilir. Kolluk amiri, evrakı en geç tedbirin alındığı tarihi takip eden ilk işgünü içinde mülkî amirin onayına sunar. Mülkî amir tarafından kırk sekiz saat içinde onaylanmayan tedbirler kendiliğinden kalkar. (2) 18, 19, 20 ve 22 nci maddelerde belirtilen ve hâkim tarafından karar altına alınabilecek önleyici tedbirler, gecikmesinde sakınca bulunan hâllerde ilgili kolluk amirince alınabilir. Kolluk amiri evrakı en geç tedbirin alındığı tarihi takip eden ilk işgünü içinde hâkimin onayına sunar. Hâkim tarafından yirmi dört saat içinde onaylanmayan tedbirler kendiliğinden kalkar. (3) Tatil günleri sürenin hesabına dâhildir. (...)",
  "6284 Uyg. Yön m.3": "m) Şiddet: Kişinin, fiziksel, cinsel, psikolojik veya ekonomik açıdan zarar görmesiyle veya acı çekmesiyle sonuçlanan veya sonuçlanması muhtemel hareketleri, buna yönelik tehdit ve baskıyı ya da özgürlüğün keyfî engellenmesini de içeren, (...) her türlü tutum ve davranışı, n) Şiddet mağduru: (...) uyruğuna bakılmaksızın, Kanunda şiddet olarak tanımlanan tutum ve davranışlara doğrudan veya dolaylı olarak maruz kalan ya da kalma tehlikesi bulunan kişiyi (...), j) Korunan kişi: Tedbir kararı kapsamında korunan şiddet mağdurunu ve varsa beraberindeki çocukları, aile bireylerini ve tek taraflı ısrarlı takip mağdurunu, ş) Tek taraflı ısrarlı takip: Aralarında aile bağı veya ilişki bulunup bulunmadığına bakılmaksızın, şiddet uygulayanın, şiddet mağduruna yönelik olarak, güvenliğinden endişe edecek şekilde (...) korku ve çaresizlik duygularına sebep olacak biçimde, içeriği ne olursa olsun fiili, sözlü, yazılı olarak ya da her türlü iletişim aracını kullanarak (...) her türlü tutum ve davranışı, ifade eder.\n\ne) Hâkim: Aile mahkemesi hâkimini, h) Kolluk: Polis, jandarma ve sahil güvenlik birimlerini, o) Şiddet Önleme ve İzleme Merkezi (ŞÖNİM): Şiddetin önlenmesi ile koruyucu ve önleyici tedbirlerin etkin bir biçimde uygulanmasına yönelik (...) danışmanlık, rehberlik, yönlendirme ve izleme hizmetlerinin verildiği, (...) tercihen kadın personelin istihdam edildiği, çalışmaların yedi gün yirmidört saat esasına göre yürütüldüğü merkezi, c) Gecikmesinde sakınca bulunan hal: Kolluk tarafından yapılacak tahkikat ve risk değerlendirilmesi sonucunda, derhal işlem yapılmadığı takdirde, şiddet eyleminin önlenememesi, kişinin can güvenliği(nin) (...) tehlikeye girmesi, (...) ve resen veya ilgilinin talebi üzerine mülki amirden ya da hâkimden karar almak için yeterince vakit bulunamaması halini, ifade eder.",
  "6284 Uyg. Yön m.30": "MADDE 30 – (1) Tedbir kararı ilgilinin talebi, müdürlük, ŞÖNİM veya kolluk görevlileri ya da Cumhuriyet savcısının başvurusu üzerine verilir. Tedbir kararları en çabuk ve en kolay ulaşılabilecek yer hâkiminden, mülkî amirden ya da kolluktan talep edilebilir. (2) Tedbir kararı ilk defasında en çok altı ay için verilebilir. Ancak şiddet veya şiddet uygulanma tehlikesinin devam edeceğinin anlaşılması hâlinde, (...) tedbirlerin süresinin veya şeklinin değiştirilmesine ya da aynen devam etmesine karar verilebilir. (3) Koruyucu tedbir kararı verilebilmesi için, şiddetin uygulandığı hususunda delil veya belge aranmaz. (...)",
  "6284 Uyg. Yön m.32": "MADDE 32 –(1) Gerekli bulunması hâlinde, tedbir kararı ile birlikte talep üzerine veya resen, korunan kişi ve diğer aile bireylerinin kimlik bilgileri veya kimliğini ortaya çıkarabilecek bilgileri ve adresleri (...) tüm resmi kayıtlarda gizli tutulur. Bu bilgileri hukuka aykırı olarak başkasına veren, ifşa eden veya açıklayan kişi hakkında (...) Türk Ceza Kanununun ilgili hükümleri uygulanır. (...) (5) Korunan kişi hakkında gizlilik kararı verilmesi halinde, karar ŞÖNİM müdürü aracılığıyla (...) nüfus müdürlüklerinde ilgilinin nüfus kaydına işlenir. (...) Gizlilik kararı verilen kayıtlar sadece elektronik ortamda tutulur. (6) Korunan kişinin nüfus kaydına işlenen gizlilik şerhi, tedbir kararının süresinin sona ermesini takip eden onbeşinci gün MERNİS veri tabanından silinir. (...)",
  "6284 Uyg. Yön m.34": "MADDE 33 –(1) (...) mülki amir tarafından verilen koruyucu tedbir kararına karşı, tefhim veya tebliğ tarihinden itibaren iki hafta içinde, ilgililer tarafından aile mahkemesine itiraz edilebilir. (...) (3) İtiraz hakkında duruşma yapılmaksızın karar verilir. (...) Karar bir hafta içinde verilir. İtiraz üzerine verilen karar kesindir. MADDE 34 –(1) (...) hâkim tarafından verilen koruyucu veya önleyici tedbir kararları ile (...) zorlama hapsi kararlarına karşı, tefhim veya tebliğ tarihinden itibaren iki hafta içinde ilgililer tarafından aile mahkemesine itiraz edilebilir. (...) (7) Karar bir hafta içinde verilir. İtiraz üzerine verilen karar kesindir.",
  "6284 Uyg. Yön m.37": "MADDE 37 –(1) Hâkim, tedbir kararlarının uygulanmasında teknik araç ve yöntemler kullanılmasına karar verebilir. Ancak, teknik araçlar kullanılmak suretiyle, kişilerin ses ve görüntü kaydı alınamaz, kişiler dinlenemez ve izlenemez.",
  "6284 Uyg. Yön m.38": "MADDE 38 –(1) Tedbir kararlarının ihlal edildiğinin (...) aile mahkemesince tespit edilmesi halinde (...) resen zorlama hapsine ilişkin karar verilebilir. (...) (3) Zorlama hapsine karar verilebilmesi için şiddet uygulayana, (...) ihtarın da yer aldığı tedbir kararının tefhim veya tebliğ edilmiş olması gerekir. (...) (5) (...) hakkında tedbir kararlarına aykırı hareket eden şiddet uygulayana, fiili bir suç oluştursa bile, ihlal edilen tedbirin niteliğine ve aykırılığın ağırlığına göre hâkim tarafından üç günden on güne kadar zorlama hapsine tâbi tutulmasına karar verilir. (6) Tedbir kararının gereklerine aykırılığın her tekrarında, (...) zorlama hapsinin süresi onbeş günden otuz güne kadardır. Ancak zorlama hapsinin toplam süresi altı ayı geçemez. (7) Zorlama hapsi kararları tekerrüre esas olmaz, koşullu salıverilme hükümleri uygulanmaz ve adli sicil kayıtlarına işlenmez.",
  "6284 Uyg. Yön m.39": "MADDE 39 –(1) Bakanlık, (...) ŞÖNİM'i kurar. MADDE 40 –(1) Kanun hükümlerinin yerine getirilmesinde kurumlararası ve sivil toplum kuruluşları ile koordinasyon Bakanlık tarafından gerçekleştirilir. (...) (3) (...) Materyaller, (...) televizyon kuruluşları ve radyolar tarafından ayda en az doksan dakika yayınlanır. (...) MADDE 41 –(1) Kanunun etkin bir biçimde uygulanması amacıyla tüm kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşları, personel ve üyelerinin (...) eğitim programlarına katılmasını sağlar. (2) İlköğretim ve ortaöğretim müfredatına (...) dersler konulur. (3) (...) öğrencilere mezun oldukları tarihte (...) bir sertifika verilir.",
  "6284 Uyg. Yön m.4": "MADDE 4 –(1) Kişinin, şiddete uğraması veya şiddete uğrama tehlikesi altında bulunması halinde herkes durumu yazılı, sözlü veya başka bir suretle ilgili makam ve mercilere ihbar edebilir. Şiddet veya şiddete uğrama tehlikesinden haberdar olan kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşları ise durumu derhal, şikâyet mercilerine bildirmek zorundadır. (2) Şiddet mağduru, (...) durumu şikâyet mercilerine (...) bildirebilir. (3) Şikâyet mercileri Kanun kapsamındaki görevlerini gecikmeksizin yerine getirmekle yükümlüdür. (4) Müdürlük veya ŞÖNİM'e yapılan şikâyet ve ihbarlar, bunlar tarafından olayın özelliğine göre, kolluğa, mülki amire, Cumhuriyet başsavcılığına veya hâkime gecikmeksizin bildirilir. (5) Sözlü yapılan şikâyet ve ihbarlar derhal tutanağa geçirilir.",
  "6284 Uyg. Yön m.42": "MADDE 42 –(1) Geçici maddi yardımlar için yapılan ödemelerin tahsili için, ödeme tutarı (...) tebliğ tarihinden itibaren bir ay içinde ödenmesi hususu şiddet uygulayana tebliğ edilir. Ödemenin süresinde yapılmaması halinde bu tutar, 6183 sayılı (...) Kanun hükümlerine göre (...) takip ve tahsil edilir. MADDE 43 –(1) (...) nafakaya karar verilmesi hâlinde, kararın bir örneği, resen (...) icra müdürlüğüne gönderilir. (...) (4) (...) Ayrıca harç ve benzeri hiçbir ad altında masraf alınmaz. MADDE 44 –(1) Korunan kişinin sağlık giderleri, genel sağlık sigortası kapsamında karşılanır. (...) MADDE 45 –(1) Kanun kapsamındaki başvurular ile verilen kararların icra ve infazı için yapılan işlemlerden yargılama giderleri, harç, posta gideri ve benzeri hiçbir ad altında masraf alınmaz. (2) Kanunun 17 nci maddesi uyarınca yapılan ödemeler, gelir vergisi ile veraset ve intikal vergisinden (...) müstesnadır. MADDE 46 –(1) Bakanlık, gerekli görmesi hâlinde (...) açılan (...) idarî, cezaî, hukukî her tür davaya ve çekişmesiz yargıya müdahil olarak katılabilir.",
  "6284 Uyg. Yön m.5": "MADDE 5 –(1) Kolluk, kendisine yapılan ihbar veya şikâyet üzerine genel hükümler doğrultusunda gerekli işlemleri yapar. Gecikmesinde sakınca bulunan hallerde Kanun kapsamında almış olduğu koruyucu ve önleyici tedbirleri onaylanmak üzere tedbirin niteliğine göre mülki amire veya hâkime sunar. Kolluk, kendisine intikal eden her olay hakkında gecikmeksizin en seri vasıtalarla ŞÖNİM'e bilgi verir. (2) Cumhuriyet başsavcılığı, yapılan ihbar ve şikâyet üzerine evrakın bir örneğini ivedilikle olayın niteliğine göre uygulanabilecek olan koruyucu veya önleyici tedbir hakkında karar verilmek üzere hâkime veya mülki amire gönderir. (3) Mülki amire yapılan ihbar veya şikâyet üzerine (...) koruyucu tedbirlerden (...) karar verilebilir. (...) (4) Hâkim veya mülki amir tarafından verilen kararlar ivedilikle ŞÖNİM'e bildirilir.",
  "6284 Uyg. Yön m.6": "MADDE 6 – (1) Kanun kapsamında korunan kişilerle ilgili olarak aşağıdaki tedbirlerden birine, birkaçına veya uygun görülecek benzer tedbirlere delil veya belge aranmaksızın mülkî amir tarafından ilgilinin talebi, Bakanlık veya kolluk görevlilerinin başvurusu üzerine ya da resen karar verilebilir: a) (...) uygun barınma yeri sağlanması, b) (...) geçici maddi yardım yapılması, c) Psikolojik, meslekî, hukukî ve sosyal bakımdan rehberlik ve danışmanlık hizmeti verilmesi, ç) Hayatî tehlikesinin bulunması hâlinde, ilgilinin talebi üzerine veya resen geçici koruma altına alınması, d) Gerekli olması hâlinde, (...) kreş imkânının sağlanması.",
  "6284 Uyg. Yön m.7": "MADDE 7 –(1) Hakkında barınma yeri sağlanmasına karar verilen kişiler, Bakanlığa ait veya Bakanlığın gözetim ve denetimi altında bulunan yerlerde; (...) güvenli nakli sağlanıncaya kadar geçici olarak barındırılır. (...) (5) Mülki amirin veya kolluk amirinin kararı ile kamu kurum ve kuruluşlarına ait barınma yerlerine getirilen şiddet mağduru, başka herhangi bir karar veya onay aranmaksızın barınma yerine derhal kabul edilir. (...) MADDE 9 –(1) Korunan kişiye, (...) psikolojik destek sağlamak üzere ilgili kamu kurum ve kuruluşları ile işbirliği içerisinde gerekli hizmetler verilir. (2) Korunan kişinin hukuki rehberliğe ihtiyacı olması halinde (...) gerekli destek ve danışmanlık hizmeti verilir. (3) Bu hizmetlerin yerine getirilmesinde koordinasyon ŞÖNİM tarafından sağlanır.",
  "Adli Kolluk Yön m.11": "Cumhuriyet başsavcıları her yılın sonunda, bu Yönetmeliğin 3 üncü maddesine göre belirlenmiş adlî kolluk sorumluları hakkında değerlendirme raporu düzenleyerek, mülki idare amirlerine gönderir. Değerlendirme raporlarında, adlî kolluk görevlilerinin soruşturma ve kovuşturma işlemlerindeki ehliyetiyle bu işlemlerde gösterdikleri çalışkanlık, iş disiplini ve başarı durumlarına yer verilir. Bu değerlendirme raporları ilgilinin sicilinin düzenlenmesinde dikkate alınır.",
  "Adli Kolluk Yön m.13": "Cumhuriyet başsavcıları ve Cumhuriyet savcıları; a) Adlî kolluk hizmetlerinin etkin ve verimli yürütülebilmesi amacıyla, adlî kolluk görevlilerince ifa edilen adlî işlemleri her zaman denetler. (...) Cumhuriyet başsavcıları veya Cumhuriyet savcıları adlî görevlerinin gereği olarak, gözaltına alınan kişilerin bulundurulacakları nezarethaneleri, varsa ifade alma odalarını, bu kişilerin durumlarını, gözaltına alınma sürelerini, gözaltına alma ile ilgili tüm kayıt ve işlemlerini denetler, sonucunu nezarethaneye alınanların kaydına ait deftere kaydeder.",
  "Adli Kolluk Yön m.3": "Kovuşturma: İddianamenin kabulü ile başlayıp hükmün kesinleşmesine kadar geçen evreyi, Soruşturma: Kanuna göre yetkili mercilerce suç şüphesinin öğrenilmesinden, iddianamenin kabulüne kadar geçen evreyi, Gecikmesinde sakınca bulunan hâl: Derhâl işlem yapılmadığı takdirde suçun delillerinin kaybolması veya şüphelinin kaçması veya kimliğinin saptanamaması ihtimalini, ifade eder.\n\nAdlî kolluk sorumlusu: Mahallin en büyük mülki idare amiri tarafından görevlendirilen adlî kolluğun komutanını, amirini veya sorumlusunu, (...) En üst dereceli kolluk amiri: Emniyet Genel Müdürlüğünde; il emniyet müdürünü, ilçe emniyet müdürünü veya amirini, Jandarma Genel Komutanlığında il jandarma komutanını, ilçe ve merkez ilçe jandarma komutanını, Sahil Güvenlik Komutanlığında; birlik komutanını, Gümrük ve Ticaret Bakanlığında; gümrük muhafaza kaçakçılık ve istihbarat müdürünü, (...) ifade eder.\n\nAdlî kolluk görevlileri: 5271 sayılı Ceza Muhakemesi Kanunu, 4/6/1937 tarihli ve 3201 sayılı Emniyet Teşkilâtı Kanununun 8, 9 ve 12 nci maddeleri, 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilât, Görev ve Yetkileri Kanununun 7 nci maddesi, 2/7/1993 tarihli ve 485 sayılı Gümrük Müsteşarlığının Teşkilât ve Görevleri Hakkında Kanun Hükmünde Kararnamenin 8 inci maddesi, 9/7/1982 tarihli ve 2692 sayılı Sahil Güvenlik Komutanlığı Kanununun 4 üncü maddesi ve 3/11/1983 tarihli ve 83/7362 sayılı Bakanlar Kurulu Kararıyla yürürlüğe konulan Jandarma Teşkilâtı Görev ve Yetkileri Yönetmeliğinde belirtilen soruşturma işlemlerini yapmak üzere, tâbi oldukları atama usulüne göre görevlendirilen komutan, âmir, memur ve diğer görevlileri (...) ifade eder.",
  "Adli Kolluk Yön m.4": "Soruşturma yapmak üzere; a) Emniyet Genel Müdürlüğünce, asgarî tam teşekküllü bir polis karakolu bulunan yerlerde, b) Jandarma Genel Komutanlığınca, asgarî tam teşekküllü bir jandarma karakolu bulunan yerlerde, c) Sahil Güvenlik Komutanlığınca, asgarî sahil güvenlik bot komutanlıklarının bulunduğu yerlerde, d) Gümrük Muhafaza Genel Müdürlüğünce, gümrük muhafaza kaçakçılık ve istihbarat müdürlüğü, gümrük müdürlüğü ile müstakil bölge ve kısım âmirlikleri bulunan yerlerde, mevcut imkanlar ölçüsünde yeterince adlî kolluk personeli görevlendirilir.",
  "Adli Kolluk Yön m.5": "Cumhuriyet başsavcılığı, adlî görevlere ilişkin emir ve talimatlarını öncelikle adlî kolluk sorumlularına veya adlî kolluk görevi ifa eden diğer birim âmirlerine verir. Adlî kolluk, bağlı bulunduğu kolluk teşkilâtının bir parçası olup, öncelikli görevi, karşılaştığı suçun işlenmesini önlemektir. Cumhuriyet savcılarınca, adlî görevler ile ilgili emir ve talimatlar, kolluk birimlerinin aralarındaki işbölümü ile kolluk teşkilâtlarının görev ve yetki alanlarına göre verilir. Adlî kolluk, adlî görevlerin haricindeki hizmetlerde üstlerinin emrindedir. Adlî kolluk görevlilerine, adlî görevi bulunmayan üstleri tarafından, yürütülen soruşturma ile ilgili emir ve talimat verilemez. Yönetmeliğin 7 nci maddesi hükümleri saklıdır.\n\nAdlî kolluk, bağlı bulunduğu kolluk teşkilâtının bir parçası olup, öncelikli görevi, karşılaştığı suçun işlenmesini önlemektir. (...) b) Adlî kolluk görevlilerinin özlük hakları, bağlı oldukları teşkilât tarafından yürütülür. c) En üst dereceli kolluk amiri adlî olayları, suç işlenmesini önlemek, kamu düzen ve güvenini korumakla ve bu konuda gerekli tedbirleri almakla görevli ve yetkili olan mülki idare amirine derhal bildirir.",
  "Adli Kolluk Yön m.6": "Soruşturma işlemleri, Cumhuriyet savcısının emir ve talimatları doğrultusunda öncelikle adlî kolluğa yaptırılır. Adlî kolluk görevlileri Cumhuriyet savcısının adlî görevlere ilişkin emirlerini gecikmeksizin yerine getirir.\n\nAdlî kolluk görevlileri, kendilerine yapılan bir suça ilişkin ihbar veya şikâyetleri; el koydukları olayları, yakalanan kişiler ile uygulanan tedbirleri derhâl Cumhuriyet başsavcılığına ve en üst dereceli kolluk amirine bildirir ve ilgili Cumhuriyet savcısının emri doğrultusunda işin aydınlatılması için gerekli soruşturma işlemlerine başlar.\n\nCumhuriyet savcısı, adlî kolluk görevlilerine emirleri yazılı; acele hâllerde, sözlü olarak verir. Sözlü emir, en kısa sürede yazılı hâle dönüştürülerek (...) ilgili kolluğa bildirir (...). Ancak, kolluk görevlisi emrin yazılı hâle getirilmesini beklemeden sözlü emrin gereğini yerine getirir.\n\nSuçüstü hâli ile gecikmesinde sakınca bulunan hâllerde, Cumhuriyet savcısına erişilemiyorsa veya olay genişliği itibarıyla Cumhuriyet savcısının iş gücünü aşıyorsa, sulh ceza hâkimi de bütün soruşturma işlemlerini yapabilir. Bu durumda adlî kolluk görevlileri, sulh ceza hâkimi tarafından emredilen tedbirleri alır ve araştırmaları yerine getirir.\n\nAdlî kolluk görevlileri, maddî gerçeğin araştırılması ve adil bir yargılamanın yapılabilmesi için, Cumhuriyet savcısının emirleri doğrultusunda şüphelinin lehine veya aleyhine olan tüm delilleri, kanunda ön görülen koşullara uyarak toplamak, muhafaza altına almak ve bunları bir fezleke ile Cumhuriyet savcısına sunmakla yükümlüdür. Hukuka aykırı delil elde edildiğinin tespiti hâlinde, fezlekede bu hususa da yer verilir.\n\nBir ölümün doğal nedenlerden meydana gelmediği kuşkusunu doğuracak bir durumun varlığı veya ölünün kimliğinin belirlenememesi hâlinde; kolluk görevlisi, durumu derhâl Cumhuriyet başsavcılığına bildirmek ve Cumhuriyet savcısının emri doğrultusunda soruşturma işlemlerine başlamak zorundadır.\n\nOlay yerinde görevine ait işlemlere başlayan adlî kolluk görevlisi, bunların yapılmasına engel olan veya yetkisi içinde aldığı tedbirlere aykırı davranan kişileri, işlemler sonuçlanıncaya kadar önce sözlü olarak ikâz eder; uyulmaması hâlinde zor kullanarak olay yerinden uzaklaştırır. İlgilinin ısrarı hâlinde yakalama işlemi uygulanır.",
  "Adli Kolluk Yön m.7": "Gerektiğinde veya Cumhuriyet savcısının talebi hâlinde, diğer kolluk birimleri de adlî kolluk görevini yerine getirmekle yükümlüdür. Bu durumda, kolluk görevlileri hakkında, adlî görevleri dolayısıyla Ceza Muhakemesi Kanunu hükümleri uygulanır.",
  "Aramalar Yön m.10": "Usulüne uygun yapılan aramada; a) Yapılmakta olan soruşturma veya kovuşturmayla ilgisi olmakla birlikte, karar veya yazılı emirde konu edilmeyen, b) Yapılmakta olan soruşturma veya kovuşturmayla ilgisi olmayan ancak, diğer bir suçun işlendiği şüphesini uyandırabilecek, bir delil elde edilirse; bu delil koruma altına alınır ve durum Cumhuriyet başsavcılığına derhâl bildirilerek el koyma işlemini gerçekleştirmek için Cumhuriyet savcısından yeni bir yazılı emir istenir. Cumhuriyet savcısına ulaşılamadığı hâllerde ise kolluk âmirinin yazılı emriyle kolluk görevlileri elkoyma işlemini gerçekleştirebilir. Hâkim kararı olmaksızın elkoyma işlemi, yirmidört saat içinde görevli hâkimin onayına sunulur. Hâkim, kararını elkoymadan itibaren kırksekiz saat içinde açıklar; aksi hâlde elkoyma kendiliğinden kalkar.",
  "Aramalar Yön m.11": "Adlî arama işlemi bir tutanağa bağlanır. Tutanakta; a) Arama kararının tarih ve sayısı, hâkim kararı yoksa verilmiş olan yazılı emrin tarih ve sayısı ile emri veren merci, b) Aramanın yapıldığı yer, tarih ve saat, c) Aramanın konusu, d) Aranan kişinin kimlik bilgileri, adını söylemediği takdirde eşkâl bilgileri, e) Araçta, konutta, işyeri ve eklentilerinde arama yapılmışsa, aracın plaka numarası, markası, konutun, işyerinin ve eklentilerinin açık adresi (...), f) Aramanın sonuçları, el konulan suç eşyasına ilişkin belirleyici bilgiler, g) Aramada yakalanan kişiler varsa kimlik bilgileri (...), h) Arama sonucunda yaralanma veya maddî bir zarar meydana gelip gelmediği, i) Arama işlemini yapanların adı, soyadı, sicili ve unvanı, hususları yer alır. Tutanak arama işlemine katılmış olanlar ve hazır bulunanlarca imzalanır. Tutanağın bir sureti ilgiliye verilir.\n\n7 nci maddeye göre yapılacak arama sonunda, hakkında arama işlemi uygulanan kişiye talebi hâlinde; a) Aramanın (...) hangi sebeple yapıldığını, b) (...) soruşturma veya kovuşturma konusu fiilin niteliğini, c) Aramada el konulan veya koruma altına alınan eşyanın listesini, d) Aramada şüpheyi haklı kılan bir şey elde edilmemiş ise bunu, e) (...) el konulan eşyanın mülkiyetine ilişkin görüş ve iddialarını, içeren belge veya belgeler verilir. Koruma altına alınan veya el konulan eşyanın tam bir listesi yapılarak resmî mühürle mühürlenir. Bu eşyanın resmî mühürle mühürlendiğine dair tutanak tanzim edilerek, bir sureti ilgilisine verilir.",
  "Aramalar Yön m.13": "Cumhuriyet savcısı hazır olmaksızın avukat bürolarında arama yapılamaz. Avukat büroları ancak mahkeme kararı ile ve kararda belirtilen olayla ilgili olarak Cumhuriyet savcısının denetiminde aranabilir. Baro başkanı veya onu temsil eden bir avukat aramada hazır bulundurulur. Arama sonucu elkonulmasına karar verilen şeyler bakımından bürosunda arama yapılan avukat, baro başkanı veya onu temsil eden avukat, bunların avukat ile müvekkili arasındaki meslekî ilişkiye ait olduğunu öne sürerek karşı koyduğunda, bu şey ayrı bir zarf veya paket içerisine konularak hazır bulunanlarca mühürlenir ve bu konuda gerekli kararı vermesi, soruşturma evresinde sulh ceza hâkiminden, kovuşturma evresinde hâkim veya mahkemeden istenir. (...) Bu fıkrada öngörülen kararlar yirmidört saat içinde verilir. Postada el koyma durumunda (...) üçüncü fıkrada belirtilen usuller uygulanır.\n\nAskerî mahallerde yapılacak arama Cumhuriyet savcısının talep ve katılımı ile askerî makamlar tarafından yerine getirilir.",
  "Aramalar Yön m.15": "Arama sonucunda bazı eşyaya elkoyma söz konusu olduğunda, hâkim kararı veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının, Cumhuriyet savcısına ulaşılamadığı hâllerde ise kolluk âmirinin yazılı emri ile elkoyma işlemi gerçekleştirilebilir. İspat aracı olarak yararlı görülen ya da eşya veya kazanç müsaderesinin konusunu oluşturan malvarlığı değerleri, koruma altına alınır. Yanında bulunduran kişinin rızasıyla teslim etmediği bu tür eşyaya elkonulabilir. Yukarıda yazılı eşya veya diğer malvarlığı değerlerini yanında bulunduran kişi, talep üzerine bu şeyi göstermek ve teslim etmekle yükümlüdür. Evsafı belirlenen eşyanın kollukça bulunamaması ve zilyedinin de teslimden kaçınması hâlinde, şüpheli veya sanık ya da tanıklıktan çekinebilecekler dışındaki zilyet hakkında 5271 sayılı Ceza Muhakemesi Kanununun 60 ıncı maddesinde yer alan disiplin hapsine ilişkin hükümlerin uygulanması amacıyla durum Cumhuriyet başsavcılığına bildirilir.",
  "Aramalar Yön m.16": "Hakkında arama işlemi uygulanan kimsenin belge veya kâğıtlarını inceleme yetkisi, Cumhuriyet savcısı ve hâkime aittir. Kolluk, arama sırasında ele geçen belge veya kağıtlara, suçla ilgisi olup olmadığını tespit amacıyla, incelemeksizin bakabilir. Suçla ilgisi olabileceğinden şüphelendiği anda Kanunun öngördüğü şekilde incelenecek belge ve kâğıtları ambalajlayarak mühürler. Belge ve kâğıtların zilyedi veya temsilcisi kendi mührünü de koyabilir veya imzasını atabilir. (...) İnceleme sonucu soruşturma veya kovuşturma konusu suça ilişkin olmadığı anlaşılan belge veya kâğıtlar ilgilisine geri verilir. Şüpheli veya sanık ile 5271 sayılı Ceza Muhakemesi Kanununun 45 ve 46 ncı maddelerine göre tanıklıktan çekinebilecek kimseler arasındaki mektuplara ve belgelere; bu kimselerin nezdinde bulundukça elkonulamaz.\n\nBilgisayar, bilgisayar programları ve bilgisayar kütüklerine şifrenin çözülememesinden dolayı girilememesi veya gizlenmiş bilgilere ulaşılamaması hâlinde çözümün yapılabilmesi ve gerekli kopyaların alınabilmesi için, bu araç ve gereçlere elkonulabilir. Şifrenin çözümünün yapılması ve gerekli kopyaların alınması hâlinde, elkonulan cihazlar gecikme olmaksızın iade edilir. Bilgisayar veya bilgisayar kütüklerine elkoyma işlemi sırasında, sistemdeki bütün verilerin yedeklemesi yapılır. (...) alınan yedekten elektronik ortamda bir kopya çıkarılarak şüpheliye veya vekiline verilir ve bu husus tutanağa geçirilerek imza altına alınır. Bilgisayar veya bilgisayar kütüklerine elkoymaksızın da, sistemdeki verilerin tamamının veya bir kısmının kopyası alınabilir.",
  "Aramalar Yön m.18": "Aşağıda belirtilen denetimler şartları oluştuğunda kolluk tarafından kendiliğinden yapılabilir: a) Umuma açık istirahat ve eğlence yeri sayılan (...) otel, motel, pansiyon (...) gazino, pavyon, meyhane, bar (...) sinema, kahvehane ve kıraathane; (...) internet kafeler ve benzeri yerler (...) genel güvenlik ve asayiş yönünden denetimi, (...) e) Suç işlenmesini önlemek için kişilerden kimlik sorma, (...) g) Motorlu araç trafik belgesi, motorlu araç tescil belgesi ve sürücü belgeleri ile (...) 2918 sayılı Karayolları Trafik Kanununa göre araçlarda bulunması gerekli eşyanın denetimi, (...) i) Elektromanyetik aygıtlar ve dedektör köpekleri aracılığıyla yapılan tarama şeklindeki denetimler, (...) k) Hudut kapılarından giriş çıkış yapanların pasaport denetimleri.",
  "Aramalar Yön m.19": "Önleme araması; a) Millî güvenlik ve kamu düzeninin, genel sağlık ve genel ahlâkın veya başkalarının hak ve hürriyetlerinin korunması, b) Suç işlenmesinin önlenmesi, c) Taşınması veya bulundurulması yasak olan her türlü silâh, patlayıcı madde veya eşyanın tespiti, amacıyla, hâkim kararı veya gecikmesinde sakınca bulunan hâllerde mülkî âmirin yazılı emriyle ikinci fıkrada belirtilen yerlerde, kişilerin üstlerinde, aracında, özel kâğıtlarında ve eşyasında yapılan arama işlemidir. Önleme araması aşağıdaki yerlerde yapılabilir: a) (...) toplantı ve gösteri yürüyüşlerinin yapıldığı yerde veya yakın çevresinde, (...) c) Halkın topluca bulunduğu veya toplanabileceği yerlerde, d) (...) her derecede öğretim ve eğitim kurumlarının ve üniversite binaları (...) içerisinde (...), e) Umumî veya umuma açık yerlerde veya öğrenci yurtlarında (...), f) Yerleşim yerlerinin giriş ve çıkışlarında, g) Her türlü toplu taşıma veya seyreden taşıt araçlarında, (...) Konutta, yerleşim yerinde ve kamuya açık olmayan özel işyerlerinde ve eklentilerinde önleme araması yapılamaz.",
  "Aramalar Yön m.20": "Yönetmeliğin 8 inci maddesi, 9 uncu maddesinin birinci fıkrası ve 25 inci maddesi hükümleri saklı kalmak üzere, önleme aramalarında işlemin yapılacağı kanunda belirtilen umumî ve umuma açık yerlerde makul sebeplerin oluştuğunu (...) gösteren belirlemeler, kolluk tarafından önceden tespit edilir ve aramanın yapılması önerilen yer ve zaman ile birlikte o yer mülkî âmirine, gerekçeleri ile birlikte yazılı olarak iletilir. (...) Yetkili merci, kolluğun talebini uygun bulursa, hâkimden arama kararı talep eder; ancak gecikmesinde sakınca bulunan hâllerde yazılı arama emri verir.",
  "Aramalar Yön m.21": "Özel güvenlik görevlilerinin yetkileri şunlardır: a) Koruma ve güvenliğini sağladıkları alanlara girmek isteyenleri duyarlı kapıdan geçirme, bu kişilerin üstlerini dedektörle kontrol etme, eşyaları X-ray cihazından veya benzeri güvenlik sistemlerinden geçirme, b) Toplantı, konser, spor müsabakası, sahne gösterileri ve benzeri etkinlikler ile cenaze ve düğün törenlerinde kimlik sorma, duyarlı kapıdan geçirme (...) c) Yangın, deprem gibi tabiî afet durumlarında ve imdat istenmesi hâlinde görev alanındaki işyeri ve konutlara girme, d) Hava meydanı, liman, gar, istasyon ve terminal gibi toplu ulaşım tesislerinde kimlik sorma, duyarlı kapıdan geçirme, bu kişilerin üstlerini dedektörle kontrol etme, eşyaları X-ray cihazından veya benzeri güvenlik sistemlerinden geçirme.",
  "Aramalar Yön m.25": "Aşağıdaki hâllerde yapılacak aramalarda ayrıca bir arama emri ya da kararı gerekmez: a) Devletçe kamu hizmetine özgülenmiş bina ve her türlü tesislere giriş ve çıkışın belirli kurallara tâbi tutulduğu hâllerde (...) aranmasında, b) 5442 sayılı İl İdaresi Kanununun ek 1 inci maddesi kapsamında bulunan, sivil hava meydanlarında, limanlarda ve sınır kapılarında (...) X-ray cihazından geçirilerek, gerektiğinde üstünün ve eşyasının aranmasında (...) c) 2935 sayılı Olağanüstü Hâl Kanununun 11 inci maddesi kapsamında, kişilerin üstünün, eşyalarının Olağanüstü Hâl Valisinin emriyle aranmasında, d) 1402 sayılı Sıkıyönetim Kanununun 3 üncü maddesi kapsamında (...) sıkıyönetim komutanının emriyle aranmasında, e) Kanunların, muhafaza altına alınmalarına olanak verdiği kişilerin, üst veya eşyalarının aranmasında, f) (...) 298 sayılı (...) Kanunun 79 uncu maddesindeki silâh taşıma yasağı kapsamında (...) aranmasında.",
  "Aramalar Yön m.27": "Durdurma yetkisinin kullanılabilmesi için, \"umma\" derecesinde makul şüphe bulunmalıdır. Somut emarelerle desteklenen şüphe bulunmadan, süreklilik arz edecek, fiilî durum ve keyfilik oluşturacak şekilde durdurma işlemi yapılamaz. (...) Durdurma süresi, durdurma sebebine esas teşkil eden işlemin gerçekleştirilmesi için zorunlu olan süreden fazla olamaz. Durdurma üzerine aşağıdaki işlemler yapılır: a) Durdurulan kişi üzerinde giysilerinden herhangi birisi çıkarılmaksızın, yoklama biçiminde bir kontrol yapılır. Bu işlem sonucunda, kişide silâh bulunduğu sonucunu çıkarmaya yeterli şüphe meydana gelirse, memur kendiliğinden silâh ve diğer suç eşyası araması yapabilir. b) Yoklama suretiyle kontrol, kişinin cinsiyetinde bulunan görevli tarafından yapılır.",
  "Aramalar Yön m.28": "(...) Üst araması, kişinin cinsiyetinde bulunan görevli tarafından yapılır. Üst ve eşya araması sırasında, yapılan aramanın konusu olan eşyanın ne olduğu veya aramanın yapılmasına temel teşkil eden sebepler ilgiliye açıklanır. Üst araması sırasında, kişinin beraberinde olan eşya da, mümkünse elektromanyetik cihazlarla, değilse beş duyu organı aracılığıyla aranır. (...) Kişi direndiği takdirde üst ve eşya araması orantılı güç kullanılarak gerçekleştirilir. Üst ve eşya araması, kişinin veya aracın ilk durdurulduğu yerde veya o yerin yakınında, mümkün olduğu kadar başkalarının göremeyeceği tarzda yapılır. Başka yere götürülerek arama yapılamaz. Gerektiğinde kolluk aracından veya yakındaki kapalı bir yerden yararlanılabilir.",
  "Aramalar Yön m.29": "Araçlarda aramanın gerçekleştirileceği yerde, öncelikle kişilerin kaçmasını ve saldırmasını engelleyecek şekilde gerekli güvenlik tedbirleri alınır. Araç araması sırasında, yapılan aramanın konusu olan eşyanın ne olduğu veya aramanın yapılmasına temel teşkil eden sebepler ilgiliye açıklanır. Araç araması, kişiye en az sıkıntı verici şekilde ve makul olan en kısa sürede yapılır. Araç araması, aracın ilk durdurulduğu yerde veya o yerin yakınında, mümkün olduğu kadar başkalarının göremeyeceği tarzda yapılır. Detaylı inceleme yapılması gereken hâllerde, başka yere götürülerek arama yapılabilir. (...) Boş araçların aranmasında, arama yapıldığını belirten bir not bırakılır. Bu notta, arama tutanağının bir kopyasının alınabileceği yer belirtilir. Bu maddede yazılı işlemler gece de yapılabilir.",
  "Aramalar Yön m.30": "Kolluk, arama yapılacak kapalı yerlerde ve eklentilerinde gerekli güvenlik önlemlerini alarak kapıyı çalar. (...) mümkünse o yere girme izni verme yetkisine sahip kişilerle iletişim kurulmasına çalışılır (...). Aşağıdaki hâllerde iletişim kurmadan arama amacıyla kapalı yerlere ve eklentilerine girilir: a) Arama yapılacak olan yerin konut veya yerleşim yeri olarak kullanılmadığının bilinmesi, b) Arama esnasında bu yerlerde kimsenin olmadığının anlaşılması, c) Bu yerlerde oturan veya izin vermeye yetkili kişinin arama öncesinde bilgilendirilmesinin, delil karartmasına yol açarak aramanın amacını tehlikeye sokacak veya kolluk memurlarını veya diğer bireyleri tehlikeye düşürebilecek olması. (...) Aramayla görevlendirilenler, aramaya karşı çıkılması hâlinde, durumun haklı kıldığı ölçüde güç kullanarak direnci ortadan kaldırabilirler. (...) Güç, kademeli bir şekilde artarak kullanılabilir. (...) Kasa gibi, açılması özellik isteyen eşya, kolluk tarafından veya masrafları kollukça karşılanmak üzere bu konudaki meslek erbabına açtırılır. Bu işlemin o yerde yapılmasının masraflı, külfetli veya oraya zarar verebilecek nitelikte olması durumunda, eşya kolluk tarafından muhafaza edilen başka bir yere götürülerek de açılabilir. Arama sırasında rastlanan özel kâğıt ve zarflar, içinde müsadereye tâbi bir eşya bulunması ihtimali dışında açılmaz; açılsa dahi yazılı bilgiler okunamaz. Aramada hazır bulundurulacaklarla ilgili: a) Aranacak yerlerin sahibi veya eşyanın zilyedi aramada hazır bulunabilir; kendisi bulunmazsa temsilcisi veya ayırt etme gücüne sahip hısımlarından biri veya kendisiyle birlikte oturmakta olan bir kişi veya komşusu hazır bulundurulur. (...) c) Kişinin avukatının aramada hazır bulunmasına engel olunamaz. d) Geceleyin herkesin girip çıkabileceği lokanta, bar, pavyon, gazino, meyhane gibi yerler ile kıraathane ve oyun oynatılan benzeri yerlerin aranmasında tanık bulundurulması gerekmez.",
  "Aramalar Yön m.31": "(...) Aramanın amacını tehlikeye sokan acil bir durum yoksa, adlî arama gündüz yapılır. Konutta, işyerinde veya diğer kapalı yerlerde adlî arama gece yapılamaz. Ayrıca bu yerlerde kolluk âmirinin yazılı emriyle de arama yapılamaz. Ancak; a) Suçüstü hâlinde, b) Gecikmesinde sakınca bulunan hâlde, c) Firar eden kişi veya tutuklu veya hükümlünün tekrar yakalanması hâlinde, d) Geceleyin herkesin girip çıkabileceği 2559 sayılı Polis Vazife ve Salâhiyet Kanununun 7 nci maddesinde sayılan umuma açık istirahat ve eğlence yerlerinde, gece adlî arama yapılabilir. Önleme aramaları, denetimler ve kontroller her zaman yapılabilir.",
  "Aramalar Yön m.4": "Gece vakti: Güneşin batmasından bir saat sonra başlayan ve doğmasından bir saat evvele kadar devam eden süreyi, Gecikmesinde sakınca bulunan hâl: a) Adlî aramalar bakımından; derhâl işlem yapılmadığı takdirde suçun iz, eser, emare ve delillerinin kaybolması veya şüphelinin kaçması veya kimliğinin tespit edilememesi ihtimâlinin ortaya çıkması ve gerektiğinde hâkimden karar almak için vakit bulunmaması hâlini, b) Önleme aramaları bakımından; derhâl işlem yapılmadığı takdirde, millî güvenlik ve kamu düzeninin, genel sağlık ve genel ahlâkın veya başkalarının hak ve hürriyetlerinin korunmasının tehlikeye girmesi (...) ve gerektiğinde hâkimden karar almak için vakit bulunmaması hâlini, Suçüstü: a) İşlenmekte olan suçu, b) Henüz işlenmiş olan fiil ile fiilin işlenmesinden hemen sonra kolluk, suçtan zarar gören veya başkaları tarafından takip edilerek yakalanan kişinin işlediği suçu, c) Fiilin pek az önce işlendiğini gösteren eşya veya delille yakalanan kimsenin işlediği suçu, ifade eder.",
  "Aramalar Yön m.5": "Adlî arama, bir suç işlemek veya buna iştirak veyahut yataklık etmek makul şüphesi altında bulunan kimsenin, saklananın, şüphelinin, sanığın veya hükümlünün yakalanması ve suçun iz, eser, emare veya delillerinin elde edilmesi için bir kimsenin özel hayatının ve aile hayatının gizliliğinin sınırlandırılarak konutunda, işyerinde, kendisine ait diğer yerlerde, üzerinde, özel kâğıtlarında, eşyasında, aracında 5271 sayılı Ceza Muhakemesi Kanunu ile diğer kanunlara göre yapılan araştırma işlemidir.",
  "Aramalar Yön m.6": "Makul şüphe, hayatın akışına göre somut olaylar karşısında genellikle duyulan şüphedir. Makul şüphe, aramanın yapılacağı zaman, yer ve ilgili kişinin veya onunla birlikte olanların davranış tutum ve biçimleri, kolluk memurunun taşındığından şüphe ettiği eşyanın niteliği gibi sebepler göz önünde tutularak belirlenir. Makul şüphede, ihbar veya şikâyeti destekleyen emarelerin var olması gerekir. Belirtilen konularda şüphenin somut olgulara dayanması şarttır. Arama sonunda belirli bir şeyin bulunacağını veya belirli bir kişinin yakalanacağını öngörmeyi gerektiren somut olgular mevcut bulunmalıdır.",
  "Aramalar Yön m.7": "Adlî aramaya karar vermek yetkisi hâkimindir. Kolluk, arama kararı alınmasını talep ettiği durumlarda, makul şüphe sebeplerini belirten ayrıntılı ve gerekçeli bir rapor hazırlar ve Cumhuriyet savcısına başvurur. Hâkim kararı veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının, Cumhuriyet savcısına ulaşılamadığı hâllerde ise kolluk âmirinin yazılı emriyle arama yapılabilir. (...) Kolluk âmirlerince konutta, iş yerinde ve kamuya açık olmayan kapalı alanlarda arama kararı verilemez. Sayılan bu yerlerde arama ancak hâkim kararı veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının yazılı emriyle yapılabilir.\n\nCumhuriyet başsavcılıklarınca, arama ile ilgili kararları vermek üzere, yirmidört saat süreyle nöbetçi Cumhuriyet savcısı görevlendirilir.\n\nArama talep, karar veya emrinde; a) Aramanın nedenini oluşturan fiil, b) Aranılacak kişi, aramanın yapılacağı konut veya diğer yerin adresi ya da eşya, c) Karar veya emrin geçerli olacağı zaman süresi, d) Aranılacak eşyanın elde edilmesi hâlinde el konulup konulmayacağı, açıkça gösterilir.",
  "Aramalar Yön m.8": "Aşağıdaki hâllerde ayrıca bir arama emri ya da kararı aranmaz: a) Hakkında tutuklama kararı veya yakalama emri veya zorla getirme kararı bulunan kişi (...) yakalandığında üstünde (...) yapılacak aramada, b) (...) yakalanan kişinin, kendisine, başkalarına veya yakalama işlemini yapan kolluk görevlilerine zarar vermesini önlemek amacıyla yapılacak kaba üst aramasında, c) Gözaltına alınan kişinin, nezarethaneye konmadan önce yapılan üst aramasında, d) (...) kaçmakta olan kişilerin veya (...) suçun failinin yakalanması amacıyla takibi sırasında girdikleri araç, bina ve eklentilerinde (...) yapılacak aramalarda, e) (...) 5607 sayılı Kaçakçılıkla Mücadele Kanununun 9 uncu maddesi (...) kapsamında gümrük salonları ve gümrük kapılarında kaçak eşya sakladığından kuşkulanılan kişilerin üzeri, eşyası, yükleri ve araçlarının gümrük kontrolü amacıyla gümrük görevlilerince aranmasında, (...) f) (...) suçüstü hâlinde yapılan aramalarda, toplum için veya kişiler bakımından hayatî tehlikeyi ortadan kaldırmak amacıyla veya kapalı yerlerden gelen yardım çağrıları üzerine, konut, işyeri ve yerleşim yeri ile eklentilerine girmek için.",
  "Aramalar Yön m.9": "Suç işlenen yerlerde, sebep ve sonuç ilişkisini ortaya koyacak delillerin aranması, bulunması ve el koyulması için geliştirilmiş bilimsel ve teknik araştırma işlemlerinin, herkesin girip çıkabileceği kamuya açık alanlarda yapılması için bir emir veya karar gerekmez. Birinci fıkrada belirtilen yerler dışındaki olay yeri inceleme işlemleri, 7 nci madde uyarınca hâkim veya gecikmesinde sakınca bulunan hâllerde de Cumhuriyet savcısının, Cumhuriyet savcısına ulaşılamadığı hâllerde ise konut, işyeri ve kamuya açık olmayan kapalı alanlar dışındaki yerlerde kolluk âmirinin yazılı emri üzerine gerçekleştirilir.",
  "Atatürk Al. Suçlar m.1": "Atatürk'ün hatırasına alenen hakaret eden veya söven kimse bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Atatürk'ü temsil eden heykel, büst ve abideleri veyahut Atatürk'ün kabrini tahrip eden, kıran, bozan veya kirleten kimseye bir yıldan beş yıla kadar ağır hapis cezası verilir. Yukarki fıkralarda yazılı suçları işlemeye başkalarını teşvik eden kimse asıl fail gibi cezalandırılır.",
  "Atatürk Al. Suçlar m.2": "Birinci maddede yazılı suçlar; iki veya daha fazla kimseler tarafından toplu olarak veya umumi veya umuma açık mahallerde yahut basın vasıtasiyle işlenirse hükmolunacak ceza yarı nispetinde artırılır. Birinci maddenin ikinci fıkrasında yazılı suçlar zor kullanılarak işlenir veya bu suretle işlenmesine teşebbüs olunursa verilecek ceza bir misli artırılır.",
  "Atatürk Al. Suçlar m.3": "Bu kanunda yazılı suçlardan dolayı Cumhuriyet savcılıklarınca re'sen takibat yapılır.",
  "Ateşli Silahlar Yön m.10": "Kanunun 7 nci maddesinin (4) numaralı bendinin (A) ve (B) alt bentlerinde sayılan haller dışında emekli olan kamu görevlilerinden: a) Vali, vali yardımcısı, kaymakam ve bucak müdürleri ile mülkiye müfettişi, daire başkanı veya şube müdürü gibi Mülki İdare Amirliği Hizmetleri sınıfına dahil görevlilere, b) Hakim ve Savcılar ile Sayıştay Başkanı, üyeleri ve denetçilerine, c) Büyükelçi, elçi (...), e) Emniyet hizmetleri sınıfı personeli ile MİT hizmetleri mensuplarına, g) (...) demirbaş silahını taşıyan orman muhafaza memurları (...), ı) Gümrükler Muhafaza Genel Müdürlüğünde (...) gümrük muhafaza memurlarına, (...) o) (...) en az bir dönem köy veya mahalle muhtarlığı, belediye başkanlığı ve il genel meclis üyeliği yapmış olanlara, ikamet ettikleri yer valiliğine müracaatları halinde, mevcut veya alacakları zati silahları için taşıma ruhsatı verilir. (Ek ikinci fıkra) Birinci fıkranın (o) bendinde belirtilenler için 2972 sayılı Kanun hükümlerine göre seçilmiş ve bu görevlerde bulunmuş olma şartı aranır. Bu maddede öngörülenlerden durumlarını belirtir kurum yazısı istenir.",
  "Ateşli Silahlar Yön m.11": "Mahkeme kararı ile ya da haklarında verilen mahkumiyet kararının sonucu olarak Türk Silahlı Kuvvetleri, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığından tard veya ihraç edilenler, rütbesinin geri alınmasına hükmolunanlar, (...) disiplinsizlik veya ahlaki durumları sebebiyle ayırma işlemine tabi tutulanlar, (...) hariç olmak üzere emekli Türk Silahlı Kuvvetleri, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı ile mecburi hizmetini tamamlayarak istifa etmek suretiyle Türk Silahlı Kuvvetleri, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığından ayrılan muvazzaf subay, muvazzaf astsubay ve uzman jandarmalar, dokuzuncu fiilî hizmet yılını doldurduktan sonra ayrılan sözleşmeli subay, sözleşmeli astsubaylar ile en az on yıl görev yapıp sözleşmelerinin uzatılmaması sonucu veya kendi isteği ile ayrılan uzman erbaşlara silah taşıma ve bulundurma izni ilgisine göre bağlı bulundukları kuvvet komutanlıkları, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığınca verilir.\" (Kaynak: mevzuat.gov.tr güncel konsolide metin — bu madde branş `_KAYNAK_METIN.txt` kapsam dışıydı.)",
  "Ateşli Silahlar Yön m.16": "Aşağıda belirtilen kişilere ikinci fıkradaki hükümler saklı kalmak kaydıyla ateşli silah ve mermilerini taşıma ya da bulundurma izni verilmez ve verilmiş ruhsatlar iptal edilir. a) Ateşli silahla işlenen suçlardan mahkum olanlara. b) Ruhsatlı silahıyla suç işleyenlere veya silahın muhafazasındaki ihmali ya da kusuru neticesi başkaları tarafından bir suç işlenmesine (...) neden olanlara. c) Taksirli suçlar hariç bir yıldan fazla hapis cezasına mahkum olanlara. (...) g) Ruhsatlı silahını geçici de olsa başkalarına verdikleri için mahkum olanlara. (...) k) Kısıtlı olanlar ile kamu hizmetinden yasaklılara. l) Psikolojik, nörolojik ve fiziki rahatsızlıkları olanlara. m) Yirmibir yaşını bitirmemiş olanlara. n) 8/3/2012 tarihli ve 6284 sayılı Ailenin Korunması ve Kadına Karşı Şiddetin Önlenmesine Dair Kanun kapsamında haklarında tedbir kararı verilenlere tedbir kararı süresince.\n\nBirinci fıkranın (e) bendi kapsamına girenlere affa uğramış olsalar bile ateşli silahlar ile mermilerini taşıma ya da bulundurma izni verilmez. Aynı fıkranın (a), (b), (c), (d), (f), (g), (h) ve (i) bentleri kapsamına girenler için yasaklanmış hakların geri verilmesi kararı alması ve mahkûm olunan cezanın infazının tamamlandığı tarihten itibaren beş yıl geçmesi halinde silah taşıma veya bulundurma ruhsat işlemleri yapılabilir. (...) Bu fıkra hükmü, suç olmaktan çıkan bir fiil nedeniyle hüküm giymiş olanlar hakkında uygulanmaz.\n\nBirinci fıkranın (a), (b), (d), (e) ve (h) bentlerinde belirtilen suçlardan dolayı hakkında kovuşturma yapılan kişiye kovuşturma sonuçlanıncaya kadar, milli güvenliğe tehdit oluşturan terör örgütlerine aidiyeti, iltisakı veya irtibatı nedeniyle görevden uzaklaştırılan kişiye ise tekrar göreve iade edilinceye kadar silah ruhsatı verilmesine ve yenilenmesine ilişkin işlemler bekletilir ve silah ilgili birimce emanete alınır. (...) Bu maddede belirtilen mahkumiyet, kesinleşmiş mahkumiyettir. Mahkemelerce verilen hapis cezaları, adli para cezasına çevrilmiş olsa dahi bu maddenin uygulanmasında hapis cezası esas alınır.",
  "Ateşli Silahlar Yön m.3": "Taşıma ve bulundurma ruhsatları onay tarihinden itibaren beş yıl için geçerli olup, gerekli şartların varlığı halinde her beş yılda bir yenilenir. Ruhsatlar verilirken ruhsatın geçerlilik süresi ve süre bitiminden itibaren en geç altı ay içinde ruhsatın yenilenmesi gerektiği kişiye tebliğ edilir. Beş yıllık geçerlilik süresini müteakip altı ay içinde ruhsatın yenilenmemesi halinde o silaha ait ruhsat başka bir işleme gerek kalmaksızın iptal edilerek bu Yönetmelik hükümlerine göre devri sağlanır. Bu şekilde ruhsatı iptal edilen silah, ancak Kanunun 6 ncı maddesinin birinci fıkrasında belirlenen idari para cezasının ödenmesi kaydıyla aynı şahıs adına tekrar ruhsata bağlanabilir. (...) Süresi biten taşıma ruhsatı, yenisi verilinceye kadar bulundurma ruhsatı yerine geçerlidir.\n\nCumhurbaşkanı, Başbakan, Cumhurbaşkanı Yardımcıları, Bakanlar, Genelkurmay Başkanı, Hükümet Üyeleri, Türkiye Büyük Millet Meclisi Üyeleri, Kuvvet Komutanları, (...) Başbakanlık ve İçişleri Bakanlığı müsteşarları, (...) Emniyet Genel Müdürü, Jandarma Genel Komutanı ile Sahil Güvenlik Komutanı ve bu görevlerde asaleten bulunmuş olanların ruhsatlarında süre kaydı aranmaz.\n\nKanunun 7 nci maddesinin birinci fıkrasının (2) ve (3) numaralı bentleri kapsamına giren ve bu Yönetmeliğin 8 inci maddesinde belirtilen diğer kamu görevlilerinin silah taşıma ruhsatları, verildiği tarihten itibaren, görevin devamı süresince geçerlidir. Bu kişilerin ruhsata esas görev durumları beş yılda bir araştırılır. Kanunun 7 nci maddesinin birinci fıkrasının (4) numaralı bendi kapsamına giren emekli kamu görevlilerine verilen silah taşıma ve bulundurma ruhsatları ile bu maddenin dördüncü fıkrasında belirtilen kamu görevlilerine verilen silah bulundurma ruhsatları süre kaydına tabi tutulmaz. Ancak, bu şahısların silah taşıma ve bulundurma şartlarını koruyup korumadıkları hususu her beş yılda bir araştırılır. Kanunun 7 nci maddesinin birinci fıkrasının (1), (2), (3) ve (4) numaralı bentleri kapsamına giren kişilerin taşıyacakları veya bulunduracakları ateşli silahların taşınmasına veya bulundurulmasına yetki veren kayıt ve belgeler ile ruhsatlar harca tabi değildir. Ruhsata bağlanmış silahlara ait yerli ve yabancı menşeli mermiler için ayrıca ruhsat aranmaz. Ancak, yabancı menşeli mermilerin Kanuna uygun yollardan temin edildiğinin ispatı yetkililerce istenebilir.",
  "Ateşli Silahlar Yön m.4": "Silah ruhsatı alınmasına engel hali bulunmayan, yirmibir yaşını doldurmuş her Türk vatandaşı bulundurmak amacıyla silah satın alabilir. (...) Bulundurma ruhsatı, meskende veya işyerinde olmak üzere iki şekilde düzenlenebilir.\n\nBulundurma ruhsatlı silahların atış poligonu da dahil, zorunlu hallerde bir yerden başka bir yere nakli, mahallin en büyük mülki amirinin vereceği (EK-2)'deki Silah Nakil Belgesi ile mümkündür. Bu belgede belirtilen gün ve güzergah dışında silah, mesken veya işyeri dışına çıkarılamaz. Taşıt araçları işyeri veya mesken sayılmaz.",
  "Ateşli Silahlar Yön m.47": "Yivli spor tüfek ve tabancası olarak kayıtlı bulunan bütün silahlara bulundurma ruhsatı verilir. Bu silahlar, atış poligonlarında veya atış müsabakaları ve antrenmanlarında ancak ruhsatı ile birlikte geçerli amatör sporcu lisansı beraberinde olmak şartıyla kullanılabilir. Atış poligonları veya atış müsabakaları için geçerli olmak kaydıyla, Gençlik ve Spor Genel Müdürlüğünce önceden antrenman ve müsabaka izin belgesi düzenlenir.",
  "Ateşli Silahlar Yön m.54": "Bıçak, diğer aletler ve benzerleri, her ne sebeple olursa olsun üstte taşınamaz. Bunların nakilleri aşağıda gösterildiği şekilde yapılır. a) Bavul, valiz, takım veya el çantalarında, b) Çuval, bez torba veya ambalajlarında, c) Araçların bagaj ve torpido gözlerinde, d) Ani olaylarda kullanılmayı engelleyecek tarzda kağıt veya bezle sarılıp paketlenmiş şekilde üstte. Bu madde hükmüne aykırı olarak bıçak, diğer aletler ve benzerlerini üstlerinde taşıyanlar, kullanım belgeleri olsa dahi, haklarında Kanunun 15 inci maddesi gereğince işlem yapılır.",
  "Ateşli Silahlar Yön m.60": "Kapalı tabanca, açık/yarı açık atış poligonu ve trap-skeet atış alanı kurmak isteyenler; kurmak istedikleri poligonun veya atış alanının özellikleri ile nerede kurulacağına ilişkin bilgileri içeren, ortak ve yöneticilerinin Türkiye Cumhuriyeti kimlik numaralarının belirtildiği başvuru belgesi ile bizzat veya elektronik ortamda müracaat ederek Bakanlıktan ön izin belgesi almak zorundadırlar. Ön izin belgesi isteyenin 16 ncı maddede belirtilen durumlardan birine girmemiş olduğunun ve poligon kurulacağı yerin genel güvenlik bakımından uygun olduğunun Bakanlıkça belirlenmesinden sonra ilgiliye ön izin belgesi verilir.",
  "Ateşli Silahlar Yön m.7": "İçişleri Bakanı; a) (...) can güvenliklerinin ciddi ve harici tehdit ve tehlikelere maruz kalacağı kuvvetle muhtemel olduğu anlaşılan Türk vatandaşları ile karşılıklılık esasına göre ülkemizde çalışma ve ikamet izni sahibi yabancı uyruklu şahıslara, b) Şehit olan kamu görevlilerinin, korucuların, Türk Silahlı Kuvvetleri mensupları ile er ve erbaşların eş ve çocukları ile anne ve babalarına, c) 29/7/2003 tarihli ve 4959 sayılı Topluma Kazandırma Kanunu uyarınca teslim olan veya güvenlik kuvvetlerine yardımcı oldukları için koruma altına alınanlara, ç) Güvenlik korucusu olanlar ile emekli güvenlik korucusu olanlara, talepleri halinde silah taşıma ruhsatı verebilir. Bu ruhsatlar, gerektiğinde veya veriliş sebebinin ortadan kalkması halinde, geçerlilik süresine bakılmaksızın geri alınabilir.",
  "Ateşli Silahlar Yön m.70": "Ruhsata bağlanarak tescil edilmiş tabanca, yivli ve yivsiz tüfekler üzerinde yapılacak basit tamirat, boyama, işleme ve dürbün montajı gibi işlemler izne tabi değildir. Ancak tabanca ve yivli tüfeklerin ana ve balistik önemi haiz parçaları olan namlu, sürgü, çerçeve, çıkarıcı, tırnak, ateşleme iğnesi ve mekanizma başı üzerinde yapılması istenilen tamir veya tadilat için, silah tamir yeri açma ruhsatı bulunan tamirci tarafından bu hususla ilgili düzenlenmiş raporla birlikte valiliğe müracaat edilir. Valilik bu müracaatı silahla birlikte ilgili Kriminal Polis/Jandarma Laboratuvarına gönderir. Buradan alınacak rapora istinaden valilikçe tamir veya tadilat izni verilebilir. b) Silahların parça değişikliği gerektiren tamiratlarında (...) ana parçaların yurt dışından temini Bakanlığın iznine tabidir.",
  "Ateşli Silahlar Yön m.71": "Ateşli ve ateşsiz silahları tamir yeri ve bu yere bağlı şube açma izni, mahalli kolluk tarafından yapılacak tahkikattan sonra tamir yerinin açılacağı yer valiliğince verilebilir. (...) Silah Tamir Yeri Açma Ruhsatları beş yıl geçerli olup, gerekli şartların varlığı halinde her beş yılda bir valilikçe yenilenebilir. Geçerlilik süresi sona eren ruhsatın yenilenmesi için yapılacak yazılı tebligata rağmen idarece kabul edilebilir zorunlu bir mazereti bulunmadığı halde, en geç üç ay içinde müracaat etmeyenler, ruhsatları yenileninceye kadar valilikçe faaliyetten menedilirler.",
  "Ateşli Silahlar Yön m.8": "Kanunun 7 nci maddesinin birinci fıkrasının (1), (2), (3) ve (6) numaralı bentleri uyarınca silah taşımalarına karar verilenler; a) 1) Cumhurbaşkanı, Başbakan, Cumhurbaşkanı Yardımcıları, Bakanlar, Yasama Organı Üyeleri ve Bakan Yardımcıları ile bu görevlerde bulunmuş olanlara, 2) Valiler ile Bakanlık merkez ve taşra teşkilatında görev yapan mülki idare amirliği hizmetleri sınıfına dahil diğer görevlilere, 3) Hakim, cumhuriyet başsavcısı, cumhuriyet savcısı ile bu meslekten sayılanlara, 4) Özel kanunlarına göre silah taşıma yetkisine sahip görevlilere. (...) Bu madde ve 9 uncu madde uyarınca taşıma ruhsatlarının verilmesinde kişinin görevinde asaleten bulunmuş olması şartı aranır.\n\nb) Zabıta görevine ait tasarrufta bulunma yetkisine haiz olanlardan; 1 – Köy ve mahalle muhtarlarına (demirbaşa kayıtlı veya aldırılacak zati silahları için), 2 – Açık denizlerde sefer yapan gemilerin 6762 sayılı Türk Ticaret Kanununun 1467 nci maddesindeki yetkileri bulunan gemi kaptanlarına (bu görevlerinin devamı süresince demirbaşa kayıtlı silahlarını taşıyabilirler), c) Devlet, belediye, özel idare ve kamu iktisadi teşebbüsleri ile sermayesinin tamamı Devlete ait olan anonim şirketlerinde koruma, bakım onarım işlerinde çalışanlardan; 1) Özel güvenlik teşkilatı kurulmayan kurum ve kuruluşlarda görevli bekçilere (görev yerinin dışına çıkarmamak şartıyla, görev sırasında demirbaş silahlarını taşıyabilirler), 2) Elektrik enerjisi yüksek gerilim (enterkonnekte) hatların kontrol, bakım ve onarım işlerinde çalışanlara (meskun bölgeler dışında görev yaptıkları sırada demirbaşa kayıtlı silahları taşıyabilirler), (...) 8) Adalet Bakanlığına bağlı taşradaki adliye binaları ve cezaevlerinin korunması ile görevli bekçiler ve hizmet aracı şoförlerine (görev yerinde ve görev başında demirbaşa kayıtlı silahlarını taşıyabilirler), 9) İnfaz ve koruma başmemurları ile infaz ve koruma memurlarına (ceza ve tevkifevleri dışında demirbaşa kayıtlı veya zati silahlarını taşıyabilirler), (...) 11) Bilfiil görev yaptıkları sırada demirbaşa kayıtlı silahları taşımaları kaydıyla Devlet Demir Yollarına ait trenlerin Doğu ve Güneydoğu Anadolu bölgelerindeki illere gidiş ve gelişlerinde görev yapan makinist, trenşef ve gardfrenlere, 12) (...) Gençlik ve Spor Genel Müdürlüğü Atıcılık ve Avcılık Federasyonu atış malzemelerinin nakil, muhafaza ve dağıtımından sorumlu kadrolu personeline,\n\nd) Paraya vazıülyed olanlardan; 1 – (...) Adalet Bakanlığınca atanan icra müdürleri ile icra müdür yardımcıları ve bunların bulunmadığı yerlerde (...) bu görevi ifa eden kişilere (memuriyet görevlerinin devamı süresince demirbaşa kayıtlı silahları veya varsa zati silahlarını taşıyabilirler), 2 – Veznedarlara (görevleri sırasında ve görev mahallinde demirbaşa kayıtlı silahları taşıyabilirler), 3 – Tahsildarlara (bilfiil görev yaptıkları sırada demirbaşa kayıtlı silahları taşıyabilirler). e) Özellik arzeden görev yapanlardan; 1) Cumhurbaşkanlığı İdari İşler Başkanı, TBMM Genel Sekreteri veya bu görevde bulunmuş olanlara, 2) Sayıştay Başkan ve üyeleri, müsteşar, (...) genel müdür (...) ve bu görevlerde bulunmuş olanlara, (...) 9) Belediye başkanları, il genel meclisi ve büyükşehir belediye meclisi üyelerine, 10) Emniyet Genel Müdürlüğü kadrolarında çalışan emniyet hizmetleri sınıfı personeli dışındaki diğer personele, (...) Birinci fıkranın (b) bendinin (1) numaralı alt bendi ile (e) bendinin (9) numaralı alt bendinde belirtilen görevliler için, 2972 sayılı (...) Kanun hükümlerine göre seçimle bu görevlere gelmiş olma şartı aranır. (...) Bu madde ve 9 uncu madde uyarınca taşıma ruhsatlarının verilmesinde kişinin görevinde asaleten bulunmuş olması şartı aranır.",
  "Ateşli Silahlar Yön m.9": "Kanunun 7 nci maddesinin birinci fıkrasının (5) numaralı bendine istinaden valiler, aşağıda belirtilen kişilere, durumlarının bu Yönetmelik hükümlerinde aranan şartlara uygunluğunun tesbit edilmesi halinde silah taşıma ruhsatı verebilir. (...) c) (...) basın mensuplarına, d) Kuyumcu ve sarraflar ile altın ve gümüş işleyen imalatçı ve toptancılara, (...) en fazla ikisine, f) Bankaların genel müdürleri, (...) müdürlerine, g) Hava yolu nakliye pilotu lisansına sahip yolcu ve para taşımacılığında görevli pilotlara, (...) ş) Barolara kayıtlı bulunan avukatlara, (...) noterlere,\n\nö) Meskun yerler dışında en az 100 adet fenni arılı kovan ile gezginci olarak bilfiil arıcılık yapan yetiştiricilere, (...) m) En az elli sigortalı işçi çalıştıran ve fiilen ve bizzat bu işle iştigal eden iş sahiplerine, şirket ise sorumlu ortaklardan en fazla iki kişiye, işyeri ve iş başında demirbaşa kayıtlı silahları taşımak üzere bu işyerinde çalışan veznedar ve mutemetlere,\n\ne) Patlayıcı maddeleri satın alma ve satış ruhsatı bulunan işyeri sahiplerine, patlayıcı madde deposu sahiplerine, ateşli silah üreten imalathane sahiplerine, şirket ise sorumlu ortaklardan en fazla ikisine, ruhsatlı silah tamirhanesi sahiplerine ve işyerinde ve iş başında demirbaş silahları taşımak şartı ile patlayıcı madde ve fer'ilerini taşıma işlerinde görevli güvenlik belgesi sahiplerine, (...) j) (...) yapı, tesis, inşaat ve büyük onarım işleriyle fiilen ve bizzat uğraşan müteahhitlere (ortaklık veya şirket ise sorumlu ortaklardan en fazla iki kişiye), k) Akaryakıt satışı yapılan istasyonlarda fiilen ve bizzat bulunan sahiplerine (...), n) (...) atış poligonu sahiplerine ve demirbaşa kayıtlı silahları işyeri ve işbaşında taşımak şartıyla atış poligonlarını korumakla görevli bekçilere, o) (...) taşınmaz eski eserlerin, anıtların korunmasıyla görevli, sigorta primleri ödenen bekçilere (işyerinde ve işbaşında demirbaşa kayıtlı silahlarını taşıyabilirler), p) (...) patlayıcı madde depolarının korunması ile görevli bekçilere (demirbaşa kayıtlı silahlarını işyeri ve işbaşında taşıyabilirler), r) Daha önce valilik yapmış olanlar ile (...) Mülki İdare Amirliği Hizmetleri Sınıfına dahil (...) ihraç ve benzeri sebepler dışında tamamen kendi isteğiyle kurumlarından ayrılanlara, s) (...) dövize ilişkin işlemler yapmaya yetkili müesseselerin (...) sorumlu ortaklarından en fazla iki kişiye, t) Kanunla kurulan kamu kurumu niteliğindeki meslek kuruluşlarının birlik, federasyon ve konfederasyon yönetim kurulu başkan ve üyeleri ile ticaret ve sanayi odaları (...) yönetim kurulu başkan ve üyeleri ile meclis üyelerine, v) (...) Esnaf ve Sanatkârlar Meslek Kuruluşları Kanununa göre kurulmuş olan; oda, birlik, federasyon, konfederasyon yönetim kurulu başkan ve üyeleri (...) yönetim kurulu başkan ve üyelerine,",
  "Beden Muayenesi Yön m.16": "Kovuşturmaya yer olmadığı kararına itiraz süresinin dolması, itirazın reddi, beraat veya ceza verilmesine yer olmadığı kararı verilip kesinleşmesi hâllerinde bu Yönetmeliğin 15 inci maddesi hükümleri uyarınca elde edilen veriler, Cumhuriyet savcısının huzurunda ve uygun göreceği usullerle derhâl yok edilir ve bu husus tutanağa geçirilir.",
  "Beden Muayenesi Yön m.3": "Şüpheli: Soruşturma evresinde suç şüphesi altında bulunan kişiyi, Sanık: Kovuşturmanın başlamasından itibaren hükmün kesinleşmesine kadar suç şüphesi altında bulunan kişiyi, (...) Soruşturma: Ceza Muhakemesi Kanununa göre yetkili mercilerce suç şüphesinin öğrenilmesinden iddianamenin kabulüne kadar geçen evreyi, Kovuşturma: İddianamenin kabulü ile başlayıp hükmün kesinleşmesine kadar geçen evreyi (...) ifade eder.\n\nDış beden muayenesi: Vücudun dış yüzeyi ile kulak, burun ve ağız bölgelerinin gözle ve elle yapılan yüzeysel tıbbî incelemesini, İç beden muayenesi: Kafa, göğüs ve karın boşlukları ile cilt altı dokularının incelenmesini, Beden parçası: Bir bedenin tamamlayıcı unsuru olan baş, gövde, kol, el, bacak, ayak gibi uzuv ve iç organları, Moleküler genetik inceleme: Gereken tür ve miktardaki biyolojik materyali kullanarak, kişiyi diğer kişilerden ayıran ve kalıtım kurallarına uygun olarak aktarılan hastalık dışındaki özelliklerinin moleküler düzeyde araştırılmasını ifade eder.",
  "Beden Muayenesi Yön m.4": "Bir suça ilişkin delil elde etmek için, şüpheli veya sanık üzerinde iç beden muayenesi yapılabilmesine Cumhuriyet savcısı veya mağdurun istemiyle ya da resen hâkim veya mahkeme, gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı tarafından karar verilebilir.\n\nCumhuriyet savcısının kararı, yirmidört saat içinde hâkim veya mahkeme onayına sunulur. Hâkim veya mahkeme, yirmidört saat içinde kararını verir. Onaylanmayan kararlar hükümsüz kalır ve elde edilen deliller kullanılamaz.\n\nŞüpheli veya sanığın iç beden muayenesi ancak tabip tarafından yapılır. Muayenenin yapılabilmesi için; müdahalenin, kişinin sağlığına açıkça ve öngörülebilir zarar verme tehlikesinin bulunmaması gerekir. Cinsel organlar veya anüs bölgesinde yapılan muayene de iç beden muayenesi sayılır. Üst sınırı iki yıldan daha az hapis cezasını gerektiren suçlarda kişi üzerinde iç beden muayenesi yapılamaz.",
  "Beden Muayenesi Yön m.5": "Bir suça ilişkin delil elde etmek için, şüpheli veya sanık üzerinde dış beden muayenesi Cumhuriyet savcısı ile, emrindeki adlî kolluk görevlileri veya kovuşturma makamlarının talebiyle yapılabilir. Şüpheli veya sanığın dış beden muayenesi ancak tabip tarafından yapılır. (...) Girişimsel olmayan tıbbî görüntüleme yöntemleri de bedenin dış muayenesi sayılır. Bu tür incelemeler tabip tarafından veya tabip gözetiminde sağlık mesleği mensubu diğer bir kişi tarafından yapılabilir.",
  "Beden Muayenesi Yön m.6": "Bir suça ilişkin delil elde etmek için, şüpheli veya sanığın vücudundan kan veya benzeri biyolojik örneklerle saç, tükürük, tırnak, gibi örnekler alınabilmesine, Cumhuriyet savcısı veya mağdurun istemiyle ya da resen hâkim veya mahkeme, gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı tarafından karar verilebilir. (...) Bu müdahaleler ancak tabip tarafından veya tabip gözetiminde sağlık mesleği mensubu diğer bir kişi tarafından yapılabilir.\n\n(...) Bu örnekler Cumhuriyet savcısının huzurunda ve uygun göreceği usullerle derhâl yok edilerek bu husus tutanağa geçirilir. (...) Üst sınırı iki yıldan daha az hapis cezasını gerektiren suçlarda; kişiden kan, saç, tükürük, tırnak gibi örnekler alınamaz. Özel kanunlardaki alkol muayenesine ve kan örneği alınmasına ilişkin hükümler saklıdır.",
  "Bilgi Edinme Yön m.10": "Madde 10 - Bilgi edinme başvurusu, kişinin kimliğinin ve imzasının veya yazının kimden neşet ettiğinin tespitine yarayacak başka bilgilerin yasal olarak belirlenebilir olması kaydıyla elektronik ortamda veya diğer iletişim araçlarıyla da yapılabilir. Gerçek kişiler tarafından elektronik posta yoluyla yapılacak başvurular, başvuru sahibinin adı ve soyadı, oturma yeri veya iş adresine ilave olarak kimlik doğrulama amacıyla kullanılacak T.C. kimlik numarası belirtilmek suretiyle, (...) EK-1'de yer alan form doldurulmak suretiyle yapılır. Tüzel kişiler tarafından elektronik posta yoluyla yapılacak başvurular, tüzel kişinin unvanı ve adresi ile yetkili kişinin T.C. kimlik numarası belirtilmek suretiyle ve yetki belgesiyle birlikte, (...) EK-2'de yer alan form doldurulmak suretiyle yapılır. (...) Gerçek veya tüzel kişiler tarafından, 5070 sayılı Elektronik İmza Kanunu gereğince elektronik imza kullanılarak gönderilen başvurularda, T.C. kimlik numarası aranmaz.\n\nElektronik posta yoluyla yapılacak başvurularda, başvuru formunun kurum veya kuruluşun bilgi edinme biriminin elektronik posta adresine ulaştığı tarih, başvuru tarihidir. Elektronik posta yoluyla yapılacak başvurular için, kurum ve kuruluşların bilgi edinme birimleri, bu amaçla kurumsal bir elektronik posta adresi oluşturur ve internet sayfalarında yayımlar. (...) Başvuru dilekçeleri faks yoluyla da, kurum ve kuruluşlara gönderilebilir. Ancak faks yoluyla yapılacak başvurularda ayrıca, gerçek kişiler ile tüzel kişiliği temsile yetkili kişilerin T.C. kimlik numaraları belirtilir. (...) Faks yoluyla gelen başvuru dilekçesinin kurum ve kuruluşların bilgi edinme birimlerine ulaştığı tarih, başvuru tarihidir.",
  "Bilgi Edinme Yön m.13": "Madde 13 - Kurum ve kuruluşlarca yayımlanmış veya kitap, broşür, ilan ve benzeri yollarla kamuya açıklanmış bilgi veya belgeler, bilgi edinme başvurusuna konu olamaz. Ancak birinci fıkrada belirtilen yollarla kamuoyuna açıklanmış veya kurum ve kuruluşlarca elektronik ortamda yayımlanmış kamunun erişimine açık bilgi veya belgelerin ne şekilde, ne zaman ve nerede yayımlandığı veya açıklandığı başvurana bildirilir.",
  "Bilgi Edinme Yön m.14": "Madde 14 - Başvuru dilekçeleri veya formları, kurum ve kuruluşların bilgi edinme birimleri tarafından kabul edilir. Bilgi edinme birimleri, başvuru dilekçeleri veya formlarının 9 uncu maddede belirtilen şekilde verilip verilmediğinin kontrolünü yaptıktan sonra bunların evrak kayıtlarını yaparak hazır bulunmaları koşuluyla başvuru sahiplerine, başvurunun tarih ve sayısını gösteren bir makbuz verir. Kurum ve kuruluşların bilgi edinme birimleri dışındaki herhangi bir birimine ulaşan başvuru dilekçeleri veya formlar, işleme konulmadan derhal bilgi edinme birimlerine gönderilir. (...) Başvuru dilekçesi veya formu kaydedildikten sonra, en geç iki iş günü içinde kurum veya kuruluşun ilgili birimlerine gönderilir. Bu yazıda; başvurunun hangi birim tarafından cevaplanacağı ve başvuru sahibine hangi tarihe kadar cevap verilmesi gerektiği belirtilir.\n\n9 uncu maddede belirtilen unsurları içermeyen başvuru dilekçeleri veya formları ile 10 uncu maddede belirtilen unsurları içermeyen elektronik posta yoluyla gönderilmiş başvuru dilekçeleri veya formları işleme konulmaz ve durum başvuru sahibine bildirilir. Gerçeğe aykırı beyanda bulunduğu sonradan anlaşılan başvuru sahiplerinin dilekçeleri veya formları, bu durumun anlaşıldığı tarihte hiç başvuru yapılmamış sayılarak işleme konulmaz. (...) Gerçeğe aykırı ad ve soyadla yapılan başvurular işleme konulmaz.",
  "Bilgi Edinme Yön m.2": "Madde 2 - Bu Yönetmelik; merkezi idare kapsamındaki kamu idareleri ile bunların bağlı, ilgili veya ilişkili kuruluşlarının, köyler hariç olmak üzere mahalli idareler ve bunların bağlı ve ilgili kuruluşları ile birlik veya şirketlerinin, T.C. Merkez Bankası ve üniversiteler de dahil olmak üzere kamu tüzel kişiliğini haiz olarak enstitü, teşebbüs, teşekkül, fon ve sair adlarla kurulmuş olan bütün kamu kurum ve kuruluşlarının ve kamu kurumu niteliğindeki meslek kuruluşlarının faaliyetlerinde uygulanır.",
  "Bilgi Edinme Yön m.3": "Madde 3 - Bu Yönetmelik, 9/10/2003 tarihli ve 4982 sayılı Bilgi Edinme Hakkı Kanununun 31 inci maddesi uyarınca hazırlanmıştır.",
  "Bilgi Edinme Yön m.4": "Madde 4 - Bu Yönetmelikte geçen; a) Kurum ve kuruluş: 2 nci maddede geçen ve kapsama dahil olan bilgi edinme başvurusu yapılacak tüm makam ve mercileri, b) Başvuru sahibi: 4982 sayılı Kanun ve bu Yönetmelik kapsamında bilgi edinme hakkını kullanarak kurum ve kuruluşlara başvuran gerçek ve tüzel kişileri, c) Bilgi: Kurum ve kuruluşların kayıtlarında yer alan 4982 sayılı Kanun kapsamındaki her türlü veriyi, d) Belge: Kurum ve kuruluşların sahip oldukları 4982 sayılı Kanun kapsamındaki yazılı, basılı veya çoğaltılmış dosya, evrak, kitap, dergi, broşür, etüt, mektup, program, talimat, kroki, plan, film, fotoğraf, teyp ve video kaseti, harita, elektronik ortamda kaydedilen her türlü bilgi, haber ve veri taşıyıcılarını, e) Bilgi veya belgeye erişim: İstenen bilgi veya belgenin niteliğine göre, kurum ve kuruluşlarca, başvuru sahibine söz konusu bilgi veya belgenin bir kopyasının verilmesini, kopya verilmesinin mümkün olmadığı hallerde, başvuru sahibinin bilgi veya belgenin aslını inceleyerek not almasına veya içeriğini görmesine veya işitmesine izin verilmesini, f) Kurul: Bilgi Edinme Değerlendirme Kurulunu, g) Kanun: 9/10/2003 tarihli ve 4982 sayılı Bilgi Edinme Hakkı Kanununu, ifade eder.",
  "Bilgi Edinme Yön m.5": "Madde 5 - Herkes, Kanun ve bu Yönetmelikte belirlenen esas ve usuller çerçevesinde bilgi edinme hakkına sahiptir. Türkiye'de ikamet eden yabancılar ile Türkiye'de faaliyette bulunan yabancı tüzel kişiler, isteyecekleri bilgi kendileriyle veya faaliyet alanlarıyla ilgili olmak kaydıyla ve karşılıklılık ilkesi çerçevesinde, Kanun ve bu Yönetmelik hükümlerinden yararlanırlar. Bu kapsamdaki başvurular Türkçe olarak yapılır. Karşılıklılık ilkesi kapsamında bulunan ülkeler Dışişleri Bakanlığınca Resmi Gazetede ilan edilir. Türkiye'nin taraf olduğu uluslararası sözleşmelerden doğan hak ve yükümlülükleri saklıdır.",
  "CMK m.100": "(1) Kuvvetli suç şüphesinin varlığını gösteren somut delillerin ve bir tutuklama nedeninin bulunması halinde, şüpheli veya sanık hakkında tutuklama kararı verilebilir. İşin önemi, verilmesi beklenen ceza veya güvenlik tedbiri ile ölçülü olmaması halinde, tutuklama kararı verilemez. (2) Aşağıdaki hallerde bir tutuklama nedeni var sayılabilir: a) Şüpheli veya sanığın kaçması, saklanması veya kaçacağı şüphesini uyandıran somut olgular varsa. b) Şüpheli veya sanığın davranışları; 1. Delilleri yok etme, gizleme veya değiştirme, 2. Tanık, mağdur veya başkaları üzerinde baskı yapılması girişiminde bulunma hususlarında kuvvetli şüphe oluşturuyorsa. (3) Aşağıdaki suçların işlendiği hususunda somut delillere dayanan kuvvetli şüphe sebeplerinin varlığı halinde, tutuklama nedeni var sayılabilir: a) TCK'da yer alan soykırım/insanlığa karşı suçlar, kasten öldürme, işkence, cinsel saldırı, çocukların cinsel istismarı, hırsızlık/yağma, uyuşturucu ticareti, örgüt kurma, devletin güvenliğine ve anayasal düzene karşı suçlar (...) b) silah kaçakçılığı (...) ile kadına ve sağlık/eğitim personeline karşı kasten yaralama suçu (...). (4) Sadece adlî para cezasını gerektiren suçlarda veya vücut dokunulmazlığına karşı kasten işlenenler hariç olmak üzere hapis cezasının üst sınırı iki yıldan fazla olmayan suçlarda tutuklama kararı verilemez.",
  "CMK m.101": "(1) Soruşturma evresinde şüphelinin tutuklanmasına Cumhuriyet savcısının istemi üzerine sulh ceza hâkimi tarafından, kovuşturma evresinde sanığın tutuklanmasına Cumhuriyet savcısının istemi üzerine veya re'sen mahkemece karar verilir. (...)",
  "CMK m.102": "(1) Ağır ceza mahkemesinin görevine girmeyen işlerde tutukluluk süresi en çok bir yıldır. Ancak bu süre, zorunlu hallerde gerekçeleri gösterilerek altı ay daha uzatılabilir. (2) Ağır ceza mahkemesinin görevine giren işlerde, tutukluluk süresi en çok iki yıldır. Bu süre, zorunlu hallerde, gerekçesi gösterilerek uzatılabilir; uzatma süresi toplam üç yılı, (...) terör (...) suçlarında beş yılı geçemez. (4) Soruşturma evresinde tutukluluk süresi, ağır ceza mahkemesinin görevine girmeyen işler bakımından altı ayı, ağır ceza mahkemesinin görevine giren işler bakımından ise bir yılı geçemez. Ancak, (...) Terörle Mücadele Kanunu kapsamına giren suçlar ve toplu olarak işlenen suçlar bakımından bu süre en çok bir yıl altı ay olup, gerekçesi gösterilerek altı ay daha uzatılabilir. (5) Bu maddede öngörülen tutukluluk süreleri, fiili işlediği sırada on beş yaşını doldurmamış çocuklar bakımından yarı oranında, on sekiz yaşını doldurmamış çocuklar bakımından ise dörtte üç oranında uygulanır.",
  "CMK m.109": "Madde 109 – (1) Bir suç sebebiyle yürütülen soruşturmada, 100 üncü maddede belirtilen tutuklama sebeplerinin varlığı halinde, şüphelinin tutuklanması yerine adlî kontrol altına alınmasına karar verilebilir. (2) Kanunda tutuklama yasağı öngörülen hallerde de, adlî kontrole ilişkin hükümler uygulanabilir. (3) Adlî kontrol, şüphelinin (...) yurt dışına çıkamamak; (...) belirlenen yerlere düzenli başvurmak; (...) silâh bulunduramamak (...); konutunu terk etmemek (...) gibi yükümlülüğe tabi tutulmasını içerir. Madde 110 – (1) Şüpheli, Cumhuriyet savcısının istemi ve sulh ceza hâkiminin kararı ile soruşturma evresinin her aşamasında adlî kontrol altına alınabilir. (3) (...) kovuşturma evresinin her aşamasında (görevli/yetkili mahkemece) uygulanır. (4) (...) en geç dört aylık aralıklarla; soruşturmada savcının istemiyle sulh ceza hâkimi, kovuşturmada resen mahkeme (devamını değerlendirir).",
  "CMK m.110/A": "Madde 110/A – (1) Ağır ceza mahkemesinin görevine girmeyen işlerde adli kontrol süresi en çok iki yıldır; zorunlu hâllerde bir yıl daha uzatılabilir. (2) Ağır ceza işlerinde en çok üç yıldır; uzatma toplam üç yılı, TCK'daki belirli suçlar ile TMK kapsamı suçlarda dört yılı geçemez. (3) Bu süreler çocuklar bakımından yarı oranında uygulanır. Madde 112 – (1) Adlî kontrol hükümlerini isteyerek yerine getirmeyen şüpheli/sanık hakkında, hükmedilebilecek hapis cezasının süresi ne olursa olsun yetkili yargı mercii hemen TUTUKLAMA kararı verebilir.",
  "CMK m.116": "Yakalanabileceği veya suç delillerinin elde edilebileceği hususunda makul şüphe varsa; şüphelinin veya sanığın üstü, eşyası, konutu, işyeri veya ona ait diğer yerler aranabilir.",
  "CMK m.118": "(1) Konutta, işyerinde veya diğer kapalı yerlerde gece vaktinde arama yapılamaz. (2) Suçüstü veya gecikmesinde sakınca bulunan hâller ile yakalanmış veya gözaltına alınmış olup da firar eden kişi veya tutuklu veya hükümlünün tekrar yakalanması amacıyla yapılan aramalarda, birinci fıkra hükmü uygulanmaz.",
  "CMK m.119": "(1) Hâkim kararı üzerine veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının, Cumhuriyet savcısına ulaşılamadığı hallerde ise kolluk amirinin yazılı emri ile kolluk görevlileri arama yapabilirler. Ancak, konutta, işyerinde ve kamuya açık olmayan kapalı alanlarda arama, hâkim kararı veya gecikmesinde sakınca bulunan hallerde Cumhuriyet savcısının yazılı emri ile yapılabilir. Kolluk amirinin yazılı emri ile yapılan arama sonuçları Cumhuriyet Başsavcılığına derhal bildirilir. (...)\n\nMadde 119 – (2) Arama karar veya emrinde; aramanın nedenini oluşturan fiil, aranılacak kişi/adres/eşya, karar veya emrin geçerli olacağı zaman süresi açıkça gösterilir. (3) Arama tutanağına işlemi yapanların açık kimlikleri yazılır. (4) Cumhuriyet savcısı hazır olmaksızın konut, işyeri veya diğer kapalı yerlerde arama yapabilmek için o yer ihtiyar heyetinden veya komşulardan İKİ KİŞİ bulundurulur. (5) Askerî mahallerde arama, Cumhuriyet savcısının nezaretinde askerî makamların katılımıyla adlî kolluk tarafından yapılır.",
  "CMK m.12": "Madde 12 – (1) Davaya bakmak yetkisi, suçun işlendiği yer mahkemesine aittir. (2) Teşebbüste son icra hareketinin yapıldığı, kesintisiz suçlarda kesintinin gerçekleştiği ve zincirleme suçlarda son suçun işlendiği yer mahkemesi yetkilidir. Madde 13 – (1) Suçun işlendiği yer belli değilse, şüpheli veya sanığın yakalandığı yer, yakalanmamışsa yerleşim yeri mahkemesi yetkilidir. Madde 15 – (1) Suç, Türk bayrağını taşıma yetkisine sahip bir gemide veya böyle bir taşıt Türkiye dışında iken işlenmişse, geminin ilk uğradığı Türk limanında veya bağlama limanında bulunan mahkeme yetkilidir. (2) Türk bayrağını taşıyan hava ve demiryolu taşıtları hakkında da yukarıdaki fıkra uygulanır.",
  "CMK m.122": "(1) Hakkında arama işlemi uygulanan kimsenin belge veya kâğıtlarını inceleme yetkisi, Cumhuriyet savcısı ve hâkime aittir. (...) (3) İnceleme sonucu soruşturma veya kovuşturma konusu suça ilişkin olmadığı anlaşılan belge veya kâğıtlar ilgilisine geri verilir.",
  "CMK m.127": "(1) Hâkim kararı üzerine veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının, Cumhuriyet savcısına ulaşılamadığı hallerde ise kolluk amirinin yazılı emri ile kolluk görevlileri, elkoyma işlemini gerçekleştirebilir. (...) (3) Hâkim kararı olmaksızın yapılan elkoyma işlemi, yirmidört saat içinde görevli hâkimin onayına sunulur. Hâkim, kararını elkoymadan itibaren kırksekiz saat içinde açıklar; aksi hâlde elkoyma kendiliğinden kalkar. (...)",
  "CMK m.128/A": "Madde 128/A – (1) Nitelikli hırsızlık, nitelikli dolandırıcılık, banka/kredi kartlarının kötüye kullanılması suçlarında makul şüphe hâlinde hesabın 48 saate kadar askıya alınmasına mali kurumca karar verilebilir; (2) derhal başsavcılığa ve hesap sahibine bildirilir, savcı başvuruyu 24 saatte karara bağlar. Madde 129 – (1) Postadaki gönderilere hâkim, gecikmede savcı kararıyla elkonulabilir; (2) kolluk zarfı açamaz, mühürleyip teslim eder. Madde 130 – (1) Avukat büroları ancak MAHKEME kararıyla, savcı denetiminde, baro başkanı hazırken aranır. Madde 134 – (1) Bilgisayarlarda arama/kopyalama/elkoymaya hâkim, gecikmede savcı karar verir; savcı kararı 24 saatte hâkim onayına, hâkim 24 saatte karar; (3) elkoymada tüm verilerin yedeği alınır.",
  "CMK m.135": "(1) Bir suç dolayısıyla yapılan soruşturma ve kovuşturmada, suç işlendiğine ilişkin somut delillere dayanan kuvvetli şüphe sebeplerinin varlığı ve başka suretle delil elde edilmesi imkânının bulunmaması durumunda, hâkim veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının kararıyla şüpheli veya sanığın telekomünikasyon yoluyla iletişimi dinlenebilir, kayda alınabilir ve sinyal bilgileri değerlendirilebilir. Cumhuriyet savcısı kararını derhâl hâkimin onayına sunar ve hâkim, kararını en geç yirmi dört saat içinde verir. Sürenin dolması veya hâkim tarafından aksine karar verilmesi hâlinde tedbir Cumhuriyet savcısı tarafından derhâl kaldırılır.",
  "CMK m.137": "Madde 137 – (2) 135'e göre tutulan kayıtlar savcılıkça görevlendirilenlerce çözülüp metne dönüştürülür. (3) Kovuşturmaya yer olmadığı ya da hâkim onayı alınamaması halinde kayıtlar savcı denetiminde en geç on gün içinde yok edilir. Madde 138 – (1) Arama veya elkoyma sırasında yürütülen soruşturmayla ilgisi olmayan, başka bir suça ilişkin delil elde edilirse muhafaza altına alınır ve durum derhâl Cumhuriyet Savcılığına bildirilir. (2) İletişimin denetlenmesinde tesadüfen elde edilen delil ancak 135/6'daki katalog suçlardan biriyse kullanılabilir.",
  "CMK m.139": "Madde 139 – (1) Soruşturma konusu suçun işlendiği hususunda somut delillere dayanan kuvvetli şüphe ve başka surette delil elde edilememesi hâlinde, kamu görevlileri gizli soruşturmacı olarak görevlendirilebilir; görevlendirmeye HÂKİM karar verir. (2) Soruşturmacının kimliği değiştirilebilir. (5) Görevini yaparken suç işleyemez. (7) Bu madde ancak örgütlü uyuşturucu ticareti, suç örgütü kurma, silahlı örgüt, silah kaçakçılığı ve kültür varlıkları suçlarında uygulanır.",
  "CMK m.140": "Madde 140 – (1) Sayılan katalog suçlarda somut delillere dayanan kuvvetli şüphe ve başka surette delil elde edilememesi hâlinde, şüpheli/sanığın kamuya açık yerlerdeki faaliyetleri ve işyeri teknik araçlarla izlenebilir, ses/görüntü kaydı alınabilir. (2) İzlemeye hâkim, gecikmesinde sakınca bulunan hâllerde savcı karar verir; savcı kararı 24 saatte hâkim onayına, hâkim 24 saatte karar. (3) Karar en çok üç haftalık; bir hafta uzatılabilir; örgüt suçlarında ek olarak toplam dört haftayı geçmemek üzere. (5) Bu madde kişinin KONUTUNDA uygulanamaz.",
  "CMK m.141": "Madde 141 – (1) Suç soruşturması/kovuşturması sırasında; koşullar dışında yakalanan/tutuklanan, kanunî gözaltı süresinde hâkim önüne çıkarılmayan, hakları hatırlatılmadan tutuklanan, makul sürede yargı önüne çıkarılmayan, sonradan hakkında KYOK/beraat kararı verilen, yakalanma/tutuklanması yakınlarına bildirilmeyen, arama kararı ölçüsüz uygulanan, eşyasına koşulsuz elkonulan (...) kişiler maddî ve manevî zararlarını DEVLETTEN isteyebilir. (3) Hâkim ve savcıların karar/işlemleri nedeniyle tazminat davaları ancak DEVLET aleyhine açılır. (4) Devlet, kusurlu hâkim/savcıya bir yıl içinde rücu eder.",
  "CMK m.145": "Madde 145 – (1) İfadesi alınacak veya sorgusu yapılacak kişi davetiye ile çağrılır; çağrılma nedeni açıkça belirtilir; gelmezse zorla getirileceği yazılır. Madde 146 – (1) Tutuklama/yakalama emri için yeterli neden bulunan veya çağrıldığı halde gelmeyen şüpheli/sanığın zorla getirilmesine karar verilebilir. (4) Zorla getirilen kişi derhal, olanak yoksa yol süresi hariç en geç YİRMİDÖRT SAAT içinde çağıran hâkim, mahkeme veya savcının önüne götürülür.",
  "CMK m.147": "(1) Şüphelinin veya sanığın ifadesinin alınmasında veya sorguya çekilmesinde (...): a) (...) kimliği saptanır. b) Kendisine yüklenen suç anlatılır. c) Müdafi seçme hakkının bulunduğu (...) bildirilir. (...) e) Yüklenen suç hakkında açıklamada bulunmamasının kanunî hakkı olduğu söylenir. f) Şüpheden kurtulması için somut delillerin toplanmasını isteyebileceği hatırlatılır (...).",
  "CMK m.148": "(1) Şüphelinin ve sanığın beyanı özgür iradesine dayanmalıdır. Bunu engelleyici nitelikte kötü davranma, işkence, ilâç verme, yorma, aldatma, cebir veya tehditte bulunma, bazı araçları kullanma gibi bedensel veya ruhsal müdahaleler yapılamaz. (...) (3) Yasak usullerle elde edilen ifadeler rıza ile verilmiş olsa da delil olarak değerlendirilemez. (4) Müdafi hazır bulunmaksızın kollukça alınan ifade, hâkim veya mahkeme huzurunda şüpheli veya sanık tarafından doğrulanmadıkça hükme esas alınamaz. (5) Şüphelinin aynı olayla ilgili olarak yeniden ifadesinin alınması ihtiyacı ortaya çıktığında, bu işlem ancak Cumhuriyet savcısı tarafından yapılabilir.",
  "CMK m.149": "Madde 149 – (1) Şüpheli veya sanık, soruşturma ve kovuşturmanın her aşamasında bir veya birden fazla müdafiin yardımından yararlanabilir; kanunî temsilcisi varsa o da müdafi seçebilir. (2) Soruşturma evresinde, ifade almada en çok ÜÇ avukat hazır bulunabilir. (3) Avukatın şüpheli/sanıkla görüşme, ifade/sorgu boyunca yanında olma ve hukukî yardım hakkı engellenemez, kısıtlanamaz.",
  "CMK m.157": "Madde 157 – (1) Kanunun başka hüküm koyduğu hâller saklı kalmak ve savunma haklarına zarar vermemek koşuluyla soruşturma evresindeki usul işlemleri GİZLİDİR.",
  "CMK m.158": "Madde 158 – (1) Suça ilişkin ihbar veya şikâyet, Cumhuriyet Başsavcılığına veya kolluk makamlarına yapılabilir. (2) Valilik/kaymakamlığa ya da mahkemeye yapılan ihbar/şikâyet ilgili Başsavcılığa gönderilir. (5) İhbar/şikâyet yazılı veya tutanağa geçirilmek üzere sözlü yapılabilir. (6) Fiilin suç oluşturmadığı açıkça anlaşılır ya da ihbar soyut/genel nitelikteyse SORUŞTURMA YAPILMASINA YER OLMADIĞINA karar verilir; kişiye şüpheli sıfatı verilemez.",
  "CMK m.160": "Madde 160 – (1) Cumhuriyet savcısı, ihbar veya başka bir suretle bir suçun işlendiği izlenimini veren bir hâli öğrenir öğrenmez kamu davasını açmaya yer olup olmadığına karar vermek üzere hemen işin gerçeğini araştırmaya başlar. (2) Cumhuriyet savcısı, maddî gerçeğin araştırılması ve adil bir yargılamanın yapılabilmesi için, emrindeki adlî kolluk görevlileri marifetiyle, şüphelinin lehine ve aleyhine olan delilleri toplayarak muhafaza altına almakla ve şüphelinin haklarını korumakla yükümlüdür.",
  "CMK m.161": "Madde 160 – (1) Cumhuriyet savcısı, (...) bir suçun işlendiği izlenimini veren bir hâli öğrenir öğrenmez (...) hemen işin gerçeğini araştırmaya başlar. (2) (...) emrindeki adlî kolluk görevlileri marifetiyle, şüphelinin lehine ve aleyhine olan delilleri toplayarak (...) şüphelinin haklarını korumakla yükümlüdür. Madde 161 – (...) (2) Adlî kolluk görevlileri, elkoydukları olayları, yakalanan kişiler ile uygulanan tedbirleri emrinde çalıştıkları Cumhuriyet savcısına derhâl bildirmek ve bu Cumhuriyet savcısının adliyeye ilişkin bütün emirlerini gecikmeksizin yerine getirmekle yükümlüdür. (3) Cumhuriyet savcısı, adlî kolluk görevlilerine emirleri yazılı; acele hâllerde, sözlü olarak verir. (...)\n\nMadde 160 – (2) Savcı, maddî gerçeğin araştırılması için emrindeki adlî kolluk marifetiyle lehe ve aleyhe delilleri toplar, şüphelinin haklarını korur. Madde 161 – (1) Savcı doğrudan veya adlî kolluk aracılığıyla her türlü araştırmayı yapar, kamu görevlilerinden bilgi ister. (2) Adlî kolluk, elkoyduğu olay/yakalanan/tedbirleri savcıya DERHÂL bildirir. (3) Savcı emirleri yazılı; acele hâlde sözlü verir, sözlü emir en kısa sürede yazıya döner. (4) Diğer kamu görevlileri de istenen bilgi-belgeyi vakit geçirmeksizin verir. (8) TCK 302, 309, 311-316 suçlarında görev sırasında/dolayısıyla olsa bile savcı DOĞRUDAN soruşturur.",
  "CMK m.164": "(1) Adlî kolluk; (...) 3201 sayılı Emniyet Teşkilatı Kanununun 8, 9 ve 12 nci maddeleri, (...) 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 7 nci maddesi, (...) 485 sayılı Gümrük Müsteşarlığının Teşkilat ve Görevleri Hakkında Kanun Hükmünde Kararnamenin 8 inci maddesi ve (...) 2692 sayılı Sahil Güvenlik Komutanlığı Kanununun 4 üncü maddesinde belirtilen soruşturma işlemlerini yapan güvenlik görevlilerini ifade eder. (2) Soruşturma işlemleri, Cumhuriyet savcısının emir ve talimatları doğrultusunda öncelikle adlî kolluğa yaptırılır. (...) (3) Adlî kolluk, adlî görevlerin haricindeki hizmetlerde, üstlerinin emrindedir.",
  "CMK m.165": "(1) Gerektiğinde veya Cumhuriyet savcısının talebi halinde, diğer kolluk birimleri de adlî kolluk görevini yerine getirmekle yükümlüdür. Bu durumda, kolluk görevlileri hakkında, adlî görevleri dolayısıyla bu Kanun hükümleri uygulanır.",
  "CMK m.168": "Madde 168 – (1) Olay yerinde görevine ait işlemlere başlayan adlî kolluk görevlisi, bunların yapılmasına engel olan veya yetkisi içinde aldığı tedbirlere aykırı davranan kişileri, işlemler sonuçlanıncaya kadar ve gerektiğinde zor kullanarak bundan men eder. Madde 169 – (1) Şüphelinin ifadesinin alınması veya sorgusu, tanık ve bilirkişinin dinlenmesi veya bir keşif ve muayene sırasında Cumhuriyet savcısı veya sulh ceza hâkiminin yanında bir zabıt kâtibi bulunur. (2) Her soruşturma işlemi tutanağa bağlanır. Tutanak, adlî kolluk görevlisi, Cumhuriyet savcısı veya sulh ceza hâkimi ile hazır bulunan zabıt kâtibi tarafından imza edilir. (4) Tutanak, işlemin yapıldığı yeri, tarihi, başlama ve bitiş saatini ve işleme katılan veya ilgisi bulunan kimselerin isimlerini içerir. (6) İmzadan kaçınma hâlinde nedenleri tutanağa geçirilir.",
  "CMK m.170": "Madde 170 – (1) Kamu davasını açma görevi Cumhuriyet savcısı tarafından yerine getirilir. (2) Soruşturma sonunda toplanan deliller suçun işlendiği hususunda YETERLİ ŞÜPHE oluşturuyorsa savcı bir İDDİANAME düzenler. Madde 171 – (2) Uzlaştırma/önödeme dışında, üst sınırı üç yıl veya az hapislik suçlarda savcı kamu davasının açılmasını beş yıl erteleyebilir. Madde 172 – (1) Yeterli şüphe oluşturacak delil elde edilemez veya kovuşturma olanağı yoksa savcı KOVUŞTURMAYA YER OLMADIĞINA (KYOK) karar verir. Madde 173 – (1) Suçtan zarar gören, KYOK'a tebliğden itibaren iki hafta içinde SULH CEZA HÂKİMLİĞİNE itiraz edebilir.",
  "CMK m.175": "Madde 175 – (1) İddianamenin kabulüyle, kamu davası açılmış olur ve kovuşturma evresi başlar. (2) Mahkeme, iddianamenin kabulünden sonra duruşma gününü belirler ve duruşmada hazır bulunması gereken kişileri çağırır. Madde 176 – (1) İddianame, çağrı kâğıdı ile birlikte sanığa tebliğ olunur. (2) Tutuklu olmayan sanığa tebliğ olunacak çağrı kâğıdına mazereti olmaksızın gelmediğinde zorla getirileceği yazılır. (4) Çağrı kâğıdının tebliğiyle duruşma günü arasında en az bir hafta süre bulunması gerekir. Madde 177 – (1) Sanık, tanık veya bilirkişinin davetini veya savunma delillerinin toplanmasını istediğinde, bunların ilişkin olduğu olayları göstermek suretiyle bu husustaki dilekçesini duruşma gününden en az beş gün önce mahkeme başkanına veya hâkime verir.",
  "CMK m.182": "Madde 182 – (1) Duruşma herkese açıktır. (2) Genel ahlâkın veya kamu güvenliğinin kesin olarak gerekli kıldığı hâllerde, duruşmanın bir kısmının veya tamamının kapalı yapılmasına mahkemece karar verilebilir. (3) Duruşmanın kapalı yapılması konusundaki gerekçeli karar ile hüküm açık duruşmada açıklanır. Madde 183 – (1) (...) adliye binası içerisinde ve duruşma başladıktan sonra duruşma salonunda her türlü sesli veya görüntülü kayıt veya nakil olanağı sağlayan aletler kullanılamaz. Madde 185 – (1) Sanık, onsekiz yaşını doldurmamış ise duruşma kapalı yapılır; hüküm de kapalı duruşmada açıklanır. Madde 187 – (2) Kapalı duruşmanın içeriği hiçbir iletişim aracıyla yayımlanamaz. Madde 188 – (1) Duruşmada, hükme katılacak hâkimler ve Cumhuriyet savcısı ile zabıt kâtibinin ve Kanunun zorunlu müdafiliği kabul ettiği hâllerde müdafiin hazır bulunması şarttır. Madde 189 – (1) Birden çok Cumhuriyet savcısı ve birden çok avukat aynı zamanda duruşmaya katılabilecekleri gibi aralarında işbölümü de yapabilirler. Madde 193 – (1) Kanunun ayrık tuttuğu hâller saklı kalmak üzere, hazır bulunmayan sanık hakkında duruşma yapılmaz. Gelmemesinin geçerli nedeni olmayan sanığın zorla getirilmesine karar verilir. Madde 196 – (1) Mahkemece sorgusu yapılmış olan sanık veya (...) müdafii isterse, mahkeme sanığı duruşmada hazır bulunmaktan bağışık tutabilir. (2) Sanık, alt sınırı beş yıl ve daha fazla hapis cezasını gerektiren suçlar hariç olmak üzere, istinabe suretiyle sorguya çekilebilir.",
  "CMK m.2": "a) Şüpheli: Soruşturma evresinde, suç şüphesi altında bulunan kişiyi, b) Sanık: Kovuşturmanın başlamasından itibaren hükmün kesinleşmesine kadar, suç şüphesi altında bulunan kişiyi, (...) e) Soruşturma: (...) suç şüphesinin öğrenilmesinden iddianamenin kabulüne kadar geçen evreyi, f) Kovuşturma: İddianamenin kabulüyle başlayıp, hükmün kesinleşmesine kadar geçen evreyi, (...) j) Suçüstü: 1. İşlenmekte olan suçu, 2. Henüz işlenmiş olan fiil ile fiilin işlenmesinden hemen sonra (...) yakalanan kişinin işlediği suçu, 3. Fiilin pek az önce işlendiğini gösteren eşya veya delille yakalanan kimsenin işlediği suçu, k) Toplu suç: Aralarında iştirak iradesi bulunmasa da üç veya daha fazla kişi tarafından işlenen suçu, ifade eder.",
  "CMK m.206": "Madde 206 – (2) Ortaya konulması istenilen bir delil aşağıda yazılı hâllerde reddolunur: a) Delil, kanuna aykırı olarak elde edilmişse. b) Delil ile ispat edilmek istenilen olayın karara etkisi yoksa. c) İstem, sadece davayı uzatmak maksadıyla yapılmışsa. Madde 207 – (1) Delilin ortaya konulması istemi, bunun veya ispat edilmek istenen olayın geç bildirilmiş olması nedeniyle reddedilemez.",
  "CMK m.22": "Madde 22 – (1) Hâkim; suçtan kendisi zarar görmüşse, taraflarla evlilik/vesayet/kayyımlık ilişkisi bulunmuşsa, üstsoy-altsoyundan veya belirli derece kan/kayın hısımıysa, evlât edinme bağı varsa, aynı davada savcılık/adlî kolluk/müdafilik/vekillik yapmışsa, tanık veya bilirkişi olarak dinlenmişse hâkimlik görevini yapamaz. Madde 23 – (1) Bir karara katılan hâkim, yüksek görevli mahkemede o hükme ilişkin karara katılamaz. (2) Soruşturmada görev yapan hâkim, kovuşturmada görev yapamaz. Madde 24 – (1) Davaya bakamayacağı hâllerde reddi istenebileceği gibi, tarafsızlığını şüpheye düşürecek sebeplerden de reddi istenebilir. (2) Savcı, şüpheli/sanık/müdafi, katılan/vekili ret isteyebilir. Madde 25 – (1) Tarafsızlık şüphesiyle ret, sanığın sorgusu başlayıncaya kadar (...) istenebilir. (2) Sonradan öğrenilen sebeplerde, öğrenmeden itibaren yedi gün içinde.",
  "CMK m.231": "Madde 231 – (1) Duruşma sonunda, (...) hüküm fıkrası okunarak gerekçesi ana çizgileriyle anlatılır. (2) Hazır bulunan sanığa ayrıca başvurabileceği kanun yolları, mercii ve süresi bildirilir. (3) Beraat eden sanığa, tazminat isteyebileceği bir hâl varsa bu da bildirilir. (4) Hüküm fıkrası herkes tarafından ayakta dinlenir. (5) Sanığa yüklenen suçtan dolayı yapılan yargılama sonunda hükmolunan ceza, iki yıl veya daha az süreli hapis veya adlî para cezası ise; mahkemece, hükmün açıklanmasının geri bırakılmasına karar verilebilir. (...) (6) (...) için; a) Sanığın daha önce kasıtlı bir suçtan mahkûm olmamış bulunması, b) (...) yeniden suç işlemeyeceği hususunda kanaate varılması, c) (...) mağdurun veya kamunun uğradığı zararın (...) tamamen giderilmesi, gerekir. (8) (...) sanık, beş yıl süreyle denetim süresine tâbi tutulur. (10) Denetim süresi içinde kasten yeni bir suç işlenmediği ve (...) yükümlülüklere uygun davranıldığı takdirde, açıklanması geri bırakılan hüküm ortadan kaldırılarak, davanın düşmesi kararı verilir.",
  "CMK m.234": "Madde 234 – (1) Mağdur ile şikâyetçinin hakları şunlardır: a) Soruşturma evresinde; 1. Delillerin toplanmasını isteme, 2. (...) Cumhuriyet savcısından belge örneği isteme, 3. (...) belirli suçlarda baro tarafından kendisine avukat görevlendirilmesini isteme, 4. (...) vekili aracılığı ile soruşturma belgelerini ve elkonulan (...) eşyayı inceletme, 5. Cumhuriyet savcısının, kovuşturmaya yer olmadığı yönündeki kararına (...) itiraz hakkını kullanma. b) Kovuşturma evresinde; 1. Duruşmadan haberdar edilme, 2. Kamu davasına katılma, 3. Tutanak ve belgelerden örnek isteme, 4. Tanıkların davetini isteme, 5. (...) avukat görevlendirilmesini isteme, 6. Davaya katılmış olma koşuluyla davayı sonuçlandıran kararlara karşı kanun yollarına başvurma. (2) Mağdur, onsekiz yaşını doldurmamış, sağır veya dilsiz ya da meramını ifade edemeyecek derecede malûl olur ve bir vekili de bulunmazsa, istemi aranmaksızın bir vekil görevlendirilir. (3) Bu haklar, suçun mağdurları ile şikâyetçiye anlatılıp açıklanır ve bu husus tutanağa yazılır.",
  "CMK m.253": "Madde 253 – (1) Aşağıdaki suçlarda, şüpheli ile mağdur veya suçtan zarar gören (...) uzlaştırılması girişiminde bulunulur: a) Soruşturulması ve kovuşturulması şikâyete bağlı suçlar. b) Şikâyete bağlı olup olmadığına bakılmaksızın, Türk Ceza Kanununda yer alan; kasten yaralama (...), taksirle yaralama, tehdit (m.106/1), konut dokunulmazlığının ihlali, (...) hırsızlık (m.141), (...) dolandırıcılık (m.157) (...) suçları. (2) (...) diğer kanunlarda yer alan suçlarla ilgili olarak uzlaştırma yoluna gidilebilmesi için, kanunda açık hüküm bulunması gerekir. (3) Soruşturulması ve kovuşturulması şikâyete bağlı olsa bile, cinsel dokunulmazlığa karşı suçlarda, ısrarlı takip suçunda (m.123/A) ve hakaret suçunda (m.125) uzlaştırma yoluna gidilemez. (...) (4) (...) dosya uzlaştırma bürosuna gönderilir. (...) Şüpheli, mağdur veya suçtan zarar gören, kendisine uzlaşma teklifinde bulunulduktan itibaren yedi gün içinde kararını bildirmediği takdirde, teklifi reddetmiş sayılır.",
  "CMK m.268": "Madde 268 – (1) Hâkim veya mahkeme kararına karşı itiraz, kanunun ayrıca hüküm koymadığı hâllerde (...) ilgililerin kararı öğrendiği günden itibaren iki hafta içinde kararı veren mercie verilecek bir dilekçe veya tutanağa geçirilmek koşulu ile zabıt kâtibine beyanda bulunmak suretiyle yapılır. (2) Kararına itiraz edilen hâkim veya mahkeme, itirazı yerinde görürse kararını düzeltir; yerinde görmezse en çok üç gün içinde, itirazı incelemeye yetkili olan mercie gönderir. (3) İtirazı incelemeye yetkili merciler (...): a) Sulh ceza hâkimliği kararlarına yapılan itirazların incelenmesi, (...) numara olarak kendisini izleyen hâkimliğe (...); c) Asliye ceza mahkemesi hâkimi tarafından verilen kararlara yapılacak itirazların incelenmesi, (...) ağır ceza mahkemesine (...) aittir.",
  "CMK m.272": "Madde 272 – (1) İlk derece mahkemelerinden verilen hükümlere karşı istinaf yoluna başvurulabilir. Ancak, onbeş yıl ve daha fazla hapis cezalarına ilişkin hükümler, bölge adliye mahkemesince re'sen incelenir. (3) Ancak; a) (...) onbeşbin Türk Lirası dâhil adlî para cezasına mahkûmiyet hükümlerine, b) Üst sınırı beşyüz günü geçmeyen adlî para cezasını gerektiren suçlardan beraat hükümlerine, c) Kanunlarda kesin olduğu yazılı bulunan hükümlere, karşı istinaf yoluna başvurulamaz. Madde 273 – (1) İstinaf istemi, hükmün gerekçesiyle birlikte tebliğ edildiği tarihten itibaren iki hafta içinde hükmü veren mahkemeye bir dilekçe verilmesi veya zabıt kâtibine bir beyanda bulunulması suretiyle yapılır. Madde 286 – (1) Bölge adliye mahkemesi ceza dairelerinin bozma dışında kalan hükümleri temyiz edilebilir. (2) Ancak; a) İlk derece mahkemelerinden verilen beş yıl veya daha az hapis cezaları ile miktarı ne olursa olsun adlî para cezalarına karşı istinaf başvurusunun esastan reddine dair bölge adliye mahkemesi kararları, (...) temyiz edilemez.",
  "CMK m.38/A": "Madde 38/A – (1) Her türlü ceza muhakemesi işlemlerinde Ulusal Yargı Ağı Bilişim Sistemi (UYAP) kullanılır. (2) Dosyalar güvenli elektronik imza kullanılarak UYAP'tan incelenebilir. (5) Elektronik imzalı belgenin elle atılan imzalı belgeyle çelişmesi halinde UYAP'ta kayıtlı güvenli elektronik imzalı belge geçerli kabul edilir. (9) Elektronik ortamda yapılan işlemlerde süre gün sonunda biter.",
  "CMK m.39": "Madde 39 – (1) Gün ile belirlenen süreler, tebligatın yapıldığının ertesi günü işlemeye başlar. (2) Süre hafta ise, tebligat günün son haftada isim itibarıyla karşılığı olan günün mesai bitiminde sona erer. (3) Süre ay ise, son ayda sayı itibarıyla karşılığı olan günün mesai bitiminde sona erer; karşılığı gün yoksa ayın son günü. (4) Son gün bir tatile rastlarsa süre, tatilin ertesi günü biter.",
  "CMK m.43": "Madde 43 – (1) Tanıklar çağrı kâğıdı ile çağrılır; gelmemenin sonuçları bildirilir. (4) Cumhurbaşkanı kendi takdiri ile tanıklıktan çekinebilir. Madde 44 – (1) Mazeretsiz gelmeyen tanık zorla getirilir, giderler ödettirilir. Madde 45 – (1) Şüpheli/sanığın nişanlısı, eşi (evlilik bitse de), üstsoy-altsoyu, belirli derece kan/kayın hısımları, evlâtlık bağı olanlar tanıklıktan çekinebilir. Madde 46 – (1) Avukat, hekim/eczacı/ebe, malî müşavir ve noterler meslek sırrı sebebiyle çekinebilir. Madde 48 – (1) Tanık, kendisini veya yakınlarını ceza kovuşturmasına uğratacak sorulara cevap vermekten çekinebilir. Madde 50 – (1) 15 yaşını doldurmamışlar, yeminin önemini kavrayamayanlar ve suça iştirak/kayırma şüphelileri YEMİNSİZ dinlenir.",
  "CMK m.74": "Madde 74 – (1) Fiili işlediği yolunda kuvvetli şüpheler bulunan şüpheli veya sanığın akıl hastası olup olmadığını, akıl hastası ise ne zamandan beri hasta olduğunu ve bunun davranışları üzerindeki etkilerini saptamak için; uzman hekimin önerisi üzerine, Cumhuriyet savcısının ve müdafiin dinlenmesinden sonra resmî bir sağlık kurumunda gözlem altına alınmasına, soruşturma evresinde sulh ceza hâkimi, kovuşturma evresinde mahkeme tarafından karar verilebilir. (2) Şüpheli veya sanığın müdafii yoksa hâkim veya mahkemenin istemi üzerine baro tarafından bir müdafi görevlendirilir. (3) Gözlem süresi üç haftayı geçemez; sürenin yetmeyeceği anlaşılırsa her seferinde üç haftayı geçmemek üzere ek süreler verilebilir, ancak sürelerin toplamı üç ayı geçemez. (4) Gözlem altına alınma kararına karşı itiraz yoluna gidilebilir; itiraz, kararın yerine getirilmesini durdurur.",
  "CMK m.75": "Madde 75 – (1) Bir suça ilişkin delil elde etmek için şüpheli veya sanık üzerinde iç beden muayenesi yapılabilmesine ya da vücuttan kan veya benzeri biyolojik örneklerle saç, tükürük, tırnak gibi örnekler alınabilmesine; Cumhuriyet savcısı veya mağdurun istemiyle ya da re'sen hâkim veya mahkeme, gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı tarafından karar verilebilir. Savcının kararı yirmidört saat içinde hâkim veya mahkemenin onayına sunulur; hâkim veya mahkeme yirmidört saat içinde kararını verir; onaylanmayan kararlar hükümsüz kalır. (4) Cinsel organlar veya anüs bölgesinde yapılan muayene de iç beden muayenesi sayılır. (5) Üst sınırı iki yıldan daha az hapis cezasını gerektiren suçlarda kişi üzerinde iç beden muayenesi yapılamaz, kan veya benzeri biyolojik örnekler alınamaz. Madde 76 – (1) Mağdurun vücudu üzerinde dış veya iç beden muayenesi yapılabilmesine ya da örnek alınabilmesine; sağlığını tehlikeye düşürmemek ve cerrahî müdahalede bulunmamak koşuluyla, aynı usulle karar verilebilir. (2) Mağdurun rızası varsa birinci fıkraya göre karar alınmasına gerek yoktur. Madde 77 – (1) Kadının muayenesi, istemi hâlinde ve olanaklar elverdiğinde bir kadın hekim tarafından yapılır. Madde 78 – (1) 75 ve 76 ncı maddelerdeki örnekler üzerinde, soybağının veya bulgunun kime ait olduğunun tespiti zorunlu ise moleküler genetik incelemeler yapılabilir; amaç dışı incelemeler yasaktır.",
  "CMK m.79": "Madde 79 – (1) 78 inci madde uyarınca moleküler genetik incelemeler yapılmasına sadece hâkim karar verebilir; kararda inceleme ile görevlendirilen bilirkişi de gösterilir. (2) İncelenecek bulgu, bilirkişiye ilgilinin adı ve soyadı, adresi, doğum tarihi bildirilmeksizin verilir. Madde 80 – (1) 75, 76 ve 78 inci madde hükümlerine göre alınan örnekler üzerinde yapılan inceleme sonuçları kişisel veri niteliğinde olup başka bir amaçla kullanılamaz; dosya içeriğini öğrenme yetkisine sahip kişilerce bir başkasına verilemez. (2) Bu bilgiler; kovuşturmaya yer olmadığı kararına itiraz süresinin dolması, itirazın reddi, beraat veya ceza verilmesine yer olmadığı kararının kesinleşmesi hâllerinde Cumhuriyet savcısının huzurunda derhâl yok edilir ve tutanağa geçirilir. Madde 81 – (1) Üst sınırı iki yıl veya daha fazla hapis cezasını gerektiren bir suçtan dolayı şüpheli veya sanığın kimliğinin teşhisi için gerekli olması hâlinde, Cumhuriyet savcısının emriyle fotoğrafı, beden ölçüleri, parmak ve avuç içi izi, sesi ve görüntüleri kayda alınarak dosyaya konulur. (2) Bu kayıtlar da beraat veya kovuşturmaya yer olmadığı kararının kesinleşmesi hâlinde Cumhuriyet savcısının huzurunda derhâl yok edilir.",
  "CMK m.8": "Madde 8 – (1) Bir kişi, birden fazla suçtan sanık olur veya bir suçta her ne sıfatla olursa olsun birden fazla sanık bulunursa bağlantı var sayılır. (2) Suçun işlenmesinden sonra suçluyu kayırma, suç delillerini yok etme, gizleme veya değiştirme fiilleri de bağlantılı suç sayılır. Madde 9 – (1) Bağlantılı suçlardan her biri değişik mahkemelerin görevine giriyorsa, bunlar hakkında birleştirilmek suretiyle yüksek görevli mahkemede dava açılabilir. Madde 16 – (1) (...) her biri değişik mahkemelerin yetkisi içinde bulunan bağlantılı ceza davaları, yetkili mahkemelerden herhangi birisinde birleştirilerek görülebilir. (...)",
  "CMK m.83": "Madde 83 – (1) Keşif; hâkim veya mahkeme veya naip hâkim ya da istinabe olunan hâkim veya mahkeme ile gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısı tarafından yapılır. (2) Keşif tutanağına, var olan durum ile olayın özel niteliğine göre varlığı umulup da elde edilemeyen delillerin yokluğu da yazılır. Madde 84 – (1) Keşif yapılması sırasında şüpheli, sanık, mağdur ve bunların müdafii ve vekili hazır bulunabilir. (3) Mağdur, şüpheli veya sanığın huzuru tanıklardan birinin gerçeğe uygun tanıklık etmesine engel olabilecekse, o işte şüpheli veya sanığın bulunmamasına karar verilebilir. (4) Bu işlerde hazır bulunmaya hakkı olanlar, işin geri bırakılmasına neden olmamak koşuluyla, işlerin yapılması gününden önce haberdar edilir. (5) Şüpheli veya sanık tutuklu ise, hâkim veya mahkeme tarafından ancak zorunlu sayılan hâllerde keşifte hazır bulundurulmasına karar verilebilir.",
  "CMK m.85": "Madde 85 – (1) Cumhuriyet savcısı, kendisine yüklenen suç hakkında açıklamada bulunmuş olan şüpheliye yer gösterme işlemi yaptırabilir; 250 nci maddenin birinci fıkrası kapsamına giren suçlarda adli kolluk amiri de yer gösterme işlemi yaptırmaya yetkilidir. (2) Müdafi de yer gösterme işlemi sırasında hazır bulunabilir. (3) Yer gösterme işlemi tutanağa bağlanır. Madde 86 – (1) Engelleyici sebepler olmadıkça ölü muayenesinden veya otopsiden önce ölünün kimliği, özellikle kendisini tanıyanlara gösterilerek belirlenir. (3) Bu muayene, Cumhuriyet savcısının huzurunda ve bir hekim görevlendirilerek yapılır. Madde 87 – (1) Otopsi, Cumhuriyet savcısının huzurunda biri adlî tıp, diğeri patoloji uzmanı olmak üzere iki hekim tarafından yapılır; zorunluluk bulunduğunda otopsi işlemi bir hekim tarafından da yapılabilir ve bu durum raporda açıkça belirtilir. (4) Gömülmüş bulunan bir ceset, soruşturma evresinde Cumhuriyet savcısı, kovuşturma evresinde mahkeme kararıyla mezardan çıkarılabilir.",
  "CMK m.90": "(1) Aşağıda belirtilen hâllerde, herkes tarafından geçici olarak yakalama yapılabilir: a) Kişiye suçu işlerken rastlanması. b) Suçüstü bir fiilden dolayı izlenen kişinin kaçması olasılığının bulunması veya hemen kimliğini belirleme olanağının bulunmaması. (2) Kolluk görevlileri, tutuklama kararı veya yakalama emri düzenlenmesini gerektiren ve gecikmesinde sakınca bulunan hâllerde; Cumhuriyet savcısına veya âmirlerine derhâl başvurma olanağı bulunmadığı takdirde, yakalama yetkisine sahiptirler. (...) (4) Kolluk, yakalandığı sırada kaçmasını, kendisine veya başkalarına zarar vermesini önleyecek tedbirleri aldıktan sonra, yakalanan kişiye kanunî haklarını derhal bildirir. (5) (...) yakalanan kişi ve olay hakkında Cumhuriyet savcısına hemen bilgi verilerek, emri doğrultusunda işlem yapılır.",
  "CMK m.91": "(1) (...) Gözaltı süresi, yakalama yerine en yakın hâkim veya mahkemeye gönderilmesi için zorunlu süre hariç, yakalama anından itibaren yirmidört saati geçemez. Yakalama yerine en yakın hâkim veya mahkemeye gönderilme için zorunlu süre oniki saatten fazla olamaz. (...) (3) Toplu olarak işlenen suçlarda, (...) Cumhuriyet savcısı gözaltı süresinin, her defasında bir günü geçmemek üzere, üç gün süreyle uzatılmasına yazılı olarak emir verebilir. (...) (7) Gözaltına alınan kişi bırakılmazsa, en geç bu süreler sonunda sulh ceza hâkimi önüne çıkarılıp sorguya çekilir.\n\n(4) Suçüstü hâlleriyle sınırlı olmak kaydıyla; kişi hakkında aşağıdaki bentlerde belirtilen suçlarda mülki amirlerce belirlenecek kolluk amirleri tarafından yirmi dört saate kadar, şiddet olaylarının yaygınlaşarak kamu düzeninin ciddi şekilde bozulmasına yol açabilecek toplumsal olaylar sırasında ve toplu olarak işlenen suçlarda kırk sekiz saate kadar gözaltına alınma kararı verilebilir. (...) kişi en geç kırk sekiz saat, toplu olarak işlenen suçlarda dört gün içinde hâkim önüne çıkarılır. (...)",
  "CMK m.93": "Yakalanan veya tutuklanarak bir yerden diğer bir yere nakledilen kişilere, kaçacaklarına ya da kendisi veya başkalarının hayat ve beden bütünlükleri bakımından tehlike arz ettiğine ilişkin belirtilerin varlığı hâllerinde kelepçe takılabilir.",
  "CMK m.94": "(1) Hâkim veya mahkeme tarafından verilen yakalama emri üzerine soruşturma veya kovuşturma evresinde yakalanan kişi, en geç yirmi dört saat içinde yetkili hâkim veya mahkeme önüne çıkarılır. (...) (3) İfadesi alınmak amacıyla düzenlenen yakalama emri üzerine mesai saatleri dışında yakalanan ve belirlenen tarihte yargı mercii önünde hazır bulunmayı taahhüt eden kişinin serbest bırakılması, Cumhuriyet savcısı tarafından emredilebilir. Bu hüküm her yakalama emri için ancak bir kez uygulanabilir. Taahhüdünü yerine getirmeyen kişiye, (...) bin Türk lirası idari para cezası verilir.",
  "CMK m.95": "Madde 95 – (1) Şüpheli veya sanık yakalandığında, gözaltına alındığında veya gözaltı süresi uzatıldığında, Cumhuriyet savcısının emriyle bir yakınına veya belirlediği bir kişiye gecikmeksizin haber verilir. (2) Yakalanan yabancı ise, yazılı olarak karşı çıkmaması halinde durumu vatandaşı olduğu devletin konsolosluğuna bildirilir. Madde 97 – (1) Yakalama işlemi bir tutanağa bağlanır; yakalananın hangi suçtan, hangi koşulda, hangi yer ve zamanda yakalandığı, kimlerin yaptığı ve haklarının anlatıldığı yazılır.",
  "CMK m.98": "(1) Soruşturma evresinde çağrı üzerine gelmeyen veya çağrı yapılamayan şüpheli hakkında, Cumhuriyet savcısının istemi üzerine sulh ceza hâkimi tarafından yakalama emri düzenlenebilir. Ayrıca, tutuklama isteminin reddi kararına itiraz halinde, itiraz mercii tarafından da yakalama emri düzenlenebilir. (2) Yakalanmış iken kolluk görevlisinin elinden kaçan şüpheli veya sanık ya da tutukevi veya ceza infaz kurumundan kaçan tutuklu veya hükümlü hakkında Cumhuriyet savcıları ve kolluk kuvvetleri de yakalama emri düzenleyebilirler. (3) Kovuşturma evresinde kaçak sanık hakkında yakalama emri re'sen veya Cumhuriyet savcısının istemi üzerine hâkim veya mahkeme tarafından düzenlenir.",
  "Çevre m.12": "Bu Kanun hükümlerine uyulup uyulmadığını denetleme yetkisi 9 uncu maddenin birinci fıkrasının (a), (e) ve (f) bentleri bakımından Doğa Koruma ve Milli Parklar Genel Müdürlüğüne, diğer hükümler bakımından Bakanlığa aittir. Gerektiğinde bu yetki, Bakanlıkça; İklim Değişikliği Başkanlığına, il özel idarelerine, çevre denetim birimlerini kuran belediye başkanlıklarına, Denizcilik Müsteşarlığına, Türkiye Çevre Ajansına, Emniyet Genel Müdürlüğüne, Jandarma Genel Komutanlığına ve Sahil Güvenlik Komutanlığına (…) devredilir. Denetimler, Bakanlığın belirlediği denetim usûl ve esasları çerçevesinde yapılır.\n\nAskerî işyerleri, askerî bölgeler ve tatbikatların bu Kanun çerçevesindeki denetimi ve neticelerine ait işlemler; Genelkurmay Başkanlığı, Millî Savunma Bakanlığı, İçişleri Bakanlığı ve Bakanlık tarafından müştereken hazırlanacak yönetmeliğe göre yürütülür.\n\nİlgililer, Bakanlığın veya denetimle yetkili diğer mercilerin isteyecekleri bilgi ve belgeleri vermek, yetkililerin yaptıracakları analiz ve ölçümlerin giderlerini karşılamak, denetim esnasında her türlü kolaylığı göstermek zorundadırlar.\n\nİlgililer, çevre kirliliğine neden olabilecek faaliyetleri ile ilgili olarak, kullandıkları hammadde, yakıt, çıkardıkları ürün ve atıklar ile üretim şemalarını, acil durum plânlarını, izleme sistemleri ve kirlilik raporları ile diğer bilgi ve belgeleri talep edilmesi halinde Bakanlığa veya yetkili denetim birimine vermek zorundadırlar.",
  "Çevre m.15": "Bu Kanun ve bu Kanun uyarınca yayımlanan yönetmeliklere aykırı davrananlara söz konusu aykırı faaliyeti düzeltmek üzere Bakanlıkça ya da 12 nci maddenin birinci fıkrası uyarınca denetim yetkisinin devredildiği kurum ve merciler tarafından bir defaya mahsus olmak üzere esasları yönetmelikle belirlenen ve bir yılı aşmamak üzere süre verilebilir. Faaliyet; süre verilmemesi halinde derhal, süre verilmesi durumunda, bu süre sonunda aykırılık düzeltilmez ise Bakanlıkça ya da 12 nci maddenin birinci fıkrası uyarınca denetim yetkisinin devredildiği kurum ve merciler tarafından kısmen veya tamamen, süreli veya süresiz olarak durdurulur.\n\nSüre verilmesi ve faaliyetin durdurulması, bu Kanunda öngörülen cezaların uygulanmasına engel teşkil etmez.\" (süre/durdurma → idari/adli cezayı kaldırmaz; m.27 ile paralel.)\n\nÇevre ve insan sağlığı yönünden tehlike yaratan faaliyetler ile çevre izni veya çevre izin ve lisansı olmayan faaliyetler süre verilmeksizin durdurulur.\n\nÇevresel Etki Değerlendirmesi incelemesi yapılmaksızın başlanan faaliyetler Bakanlıkça, proje tanıtım dosyası hazırlanmaksızın başlanan faaliyetler ise mahallin en büyük mülkî amiri tarafından süre verilmeksizin durdurulur.",
  "Çevre m.20": "İdarî nitelikteki cezalar şunlardır:\" [madde 20'nin (a)–(ıı) bentleri çeşitli çevre ihlalleri için \"… idarî para cezası verilir.\" biçiminde düzenlenmiştir; örn. (g): \"12 nci maddede öngörülen bildirim ve bilgi verme yükümlülüğünü yerine getirmeyenlere 6.000 Türk Lirası (209.624 TL) idarî para cezası verilir.\" (s): \"Umuma açık yerlerde her ne şekilde olursa olsun çevreyi kirletenlere 1.000 Türk lirası (8.687 TL) idarî para cezası verilir.\"]\n\nBu maddenin uygulamasında Türk Ceza Kanunu ile diğer kanunların, fiilin suç oluşturması haline ilişkin hükümleri saklıdır.\n\nBu Kanunda öngörülen yasaklara ve sınırlamalara aykırı olarak ülkenin egemenlik alanlarındaki denizlerde ve yargılama yetkisine tâbi olan deniz yetki alanlarında ve bunlarla bağlantılı sularda, tabiî veya sunî göller ve baraj gölleri ile akarsularda; [(1) petrol ve petrol türevleri tankerleri, (2) kirli balast tankerleri, (3) petrol türevleri/kirli balast deşarjı yapan gemi ve diğer deniz vasıtaları, (4) evsel atıksu/katı atık boşaltan tanker, gemi ve diğer deniz araçları için groston esasına göre idarî para cezası verilir.]\n\nPetrol ve petrol türevleri (ham petrol, akaryakıt, sintine, slaç, slop, rafine ürün, yağlı atık vb.) tahliyesi veya deşarjı yapan tankerlerden, bin (dahil) grostona kadar olanlar için groston başına 400 Türk lirası (5.752,34 TL), bin ilâ beşbin (dahil) groston arasında olanlara, bu miktar ve ilave her groston başına 100 Türk lirası (1.438,13 TL), beşbin grostondan fazla olanlara ise, yukarıdaki miktarlar ve ilave her groston başına 10 Türk lirası (143,75 TL), (…) idarî para cezası verilir.\n\nAncak yüzbin grostondan büyük tanker, gemi ve diğer deniz araçları için yüzbin groston esas alınarak idarî para cezası verilir.\n\nTehlikeli madde ve atıkların deşarjı durumunda uygulanacak idarî para cezaları, petrol ve türevleri kategorisi esas alınarak on katı verilir.\n\nCezanın derhal ve defaten ödenmemesi veya bu hususta yeterli teminat gösterilmemesi halinde, gemiler ve götürülebilen diğer deniz vasıtaları en yakın liman yetkilisine teslim edilerek seyrüseferden ve faaliyetten men edilir.\n\nKirliliğin oluşmasını müteakip gemi veya deniz aracının kendi imkânları ile neden olduğu kirliliği giderdiğinin tespit edilmesi durumunda, idarî para cezası 1/3 oranında uygulanır.\n\nTehlikeli atıkların her ne şekilde olursa olsun ülkeye girişini sağlayanlara ayrı ayrı 2.000.000 Türk Lirası (69.937.946 TL) idarî para cezası verilir.\n\nTehlikeli atıkları ilgili mercilere ön bildirimde bulunmadan ihraç eden veya transit geçişini yapanlara 2.000.000 Türk Lirası (69.937.946 TL) idarî para cezası verilir.\n\nBu maddenin (ı) bendinin (1), (2), (3) ve (4) numaralı alt bentleri ile (k), (l), (r), (s), (t), (u), (v) ve (y) bentlerinde öngörülen idarî para cezaları kurum, kuruluş ve işletmelere üç katı olarak verilir. (…) Bu maddede öngörülen cezalar Özel Çevre Koruma Bölgelerinde iki kat olarak uygulanır. Bu maddede öngörülen ceza miktarlarını on katına kadar artırmaya Cumhurbaşkanı yetkilidir.",
  "Çevre m.26": "Bu Kanunun 12 nci maddesinde öngörülen bildirim ve bilgi verme yükümlülüğüne aykırı olarak yanlış ve yanıltıcı bilgi verenler, altı aydan bir yıla kadar hapis cezası ile cezalandırılır.\n\nBu Kanunun uygulanmasında yanlış ve yanıltıcı belge düzenleyenler ve kullananlar hakkında 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun belgede sahtecilik suçuna ilişkin hükümleri uygulanır.\n\nBu maddeye göre yargıya intikal eden çevresel etki değerlendirmesine ilişkin ihtilaflarda çevresel etki değerlendirmesi süreci yargılama sonuna kadar durur.",
  "Çevre m.27": "Bu Kanunda yazılı fiiller hakkında verilecek idari nitelikteki cezalar, bu fiiller için diğer kanunlarda yazılı cezaların uygulanmasına engel olmaz.",
  "Çevre m.28": "Çevreyi kirletenler ve çevreye zarar verenler sebep oldukları kirlenme ve bozulmadan doğan zararlardan dolayı kusur şartı aranmaksızın sorumludurlar.\n\nKirletenin, meydana gelen zararlardan ötürü genel hükümlere göre de tazminat sorumluluğu saklıdır.\n\nÇevreye verilen zararların tazminine ilişkin talepler zarar görenin zararı ve tazminat yükümlüsünü öğrendiği tarihten itibaren beş yıl sonra zamanaşımına uğrar.",
  "Çocuk Koruma m.15": "(1) Suça sürüklenen çocuk hakkındaki soruşturma çocuk bürosunda görevli Cumhuriyet savcısı tarafından bizzat yapılır. (2) Çocuğun ifadesinin alınması veya çocuk hakkındaki diğer işlemler sırasında, çocuğun yanında sosyal çalışma görevlisi bulundurulabilir. (3) Cumhuriyet savcısı soruşturma sırasında gerekli görüldüğünde çocuk hakkında koruyucu ve destekleyici tedbirlerin uygulanmasını çocuk hâkiminden isteyebilir.",
  "Çocuk Koruma m.16": "(1) Gözaltına alınan çocuklar, kolluğun çocuk biriminde tutulur. (2) Kolluğun çocuk biriminin bulunmadığı yerlerde çocuklar, gözaltına alınan yetişkinlerden ayrı bir yerde tutulur.",
  "Çocuk Koruma m.17": "(1) Çocukların yetişkinlerle birlikte suç işlemesi hâlinde, soruşturma ve kovuşturma ayrı yürütülür. (2) Bu hâlde de çocuklar hakkında gerekli tedbirler uygulanmakla beraber, mahkeme lüzum gördüğü takdirde çocuk hakkındaki yargılamayı genel mahkemedeki davanın sonucuna kadar bekletebilir. (3) Davaların birlikte yürütülmesinin zorunlu görülmesi hâlinde, genel mahkemelerde, yargılamanın her aşamasında, mahkemelerin uygun bulması şartıyla birleştirme kararı verilebilir. Bu takdirde birleştirilen davalar genel mahkemelerde görülür.",
  "Çocuk Koruma m.18": "(1) Çocuklara zincir, kelepçe ve benzeri aletler takılamaz. Ancak; zorunlu hâllerde çocuğun kaçmasını, kendisinin veya başkalarının hayat veya beden bütünlükleri bakımından doğabilecek tehlikeleri önlemek için kolluk tarafından gerekli önlem alınabilir.",
  "Çocuk Koruma m.19": "(1) Çocuğa yüklenen suçtan dolayı Ceza Muhakemesi Kanunundaki koşulların varlığı halinde, kamu davasının açılmasının ertelenmesi kararı verilebilir. Ancak, bu kişiler açısından erteleme süresi üç yıldır. (2) Ceza Muhakemesi Kanununun 171 inci maddesinin ikinci fıkrasında belirtilen hapis cezasının üst sınırı, on beş yaşını doldurmamış çocuklar bakımından beş yıl olarak uygulanır.",
  "Çocuk Koruma m.20": "(1) Suça sürüklenen çocuklar hakkında soruşturma veya kovuşturma evrelerinde adlî kontrol tedbiri olarak Ceza Muhakemesi Kanununun 109 uncu maddesinde sayılanlar ile aşağıdaki tedbirlerden bir ya da birkaçına karar verilebilir: a) Belirlenen çevre sınırları dışına çıkmamak. b) Belirlenen bazı yerlere gidememek veya ancak bazı yerlere gidebilmek. c) Belirlenen kişi ve kuruluşlarla ilişki kurmamak. (2) Ancak bu tedbirlerden sonuç alınamaması, sonuç alınamayacağının anlaşılması veya tedbirlere uyulmaması durumunda tutuklama kararı verilebilir. (3) Denetimli serbestlik müdürlüğü tarafından takip edilen çocuk için adli kontrol süresince rehberlik edecek bir uzman görevlendirilir (...)",
  "Çocuk Koruma m.21": "(1) Onbeş yaşını doldurmamış çocuklar hakkında üst sınırı beş yılı aşmayan hapis cezasını gerektiren fiillerinden dolayı tutuklama kararı verilemez.",
  "Çocuk Koruma m.23": "(1) Çocuğa yüklenen suçtan dolayı yapılan yargılama sonunda, Ceza Muhakemesi Kanunundaki koşulların varlığı halinde, mahkemece hükmün açıklanmasının geri bırakılmasına karar verilebilir. Ancak, bu kişiler açısından denetim süresi üç yıldır.",
  "Çocuk Koruma m.25": "(1) Çocuk mahkemesi, tek hâkimden oluşur. Bu mahkemeler her il merkezinde kurulur. (...) Çocuk mahkemelerinde yapılan duruşmalarda Cumhuriyet savcısı bulunmaz. Mahkemelerin bulunduğu yerlerdeki Cumhuriyet savcıları, çocuk mahkemeleri kararlarına karşı kanun yoluna başvurabilirler. (2) Çocuk ağır ceza mahkemelerinde bir başkan ile yeteri kadar üye bulunur ve mahkeme bir başkan ve iki üye ile toplanır. (...)",
  "Çocuk Koruma m.26": "(1) Çocuk mahkemesi, asliye ceza mahkemesi ile sulh ceza mahkemesinin görev alanına giren suçlar bakımından, suça sürüklenen çocuklar hakkında açılacak davalara bakar. (2) Çocuk ağır ceza mahkemesi, çocuklar tarafından işlenen ve ağır ceza mahkemesinin görev alanına giren suçlarla ilgili davalara bakar. (3) Mahkemeler ve çocuk hâkimi, bu Kanunda ve diğer kanunlarda yer alan tedbirleri almakla görevlidir. (4) Çocuklar hakkında açılan kamu davaları, Kanunun 17 nci maddesi hükümleri saklı kalmak kaydıyla bu Kanunla kurulan mahkemelerde görülür.",
  "Çocuk Koruma m.3": "(1) Bu Kanunun uygulanmasında; a) Çocuk: Daha erken yaşta ergin olsa bile, onsekiz yaşını doldurmamış kişiyi; bu kapsamda, 1. Korunma ihtiyacı olan çocuk: Bedensel, zihinsel, ahlaki, sosyal ve duygusal gelişimi ile kişisel güvenliği tehlikede olan, ihmal veya istismar edilen ya da suç mağduru çocuğu, 2. Suça sürüklenen çocuk: Kanunlarda suç olarak tanımlanan bir fiili işlediği iddiası ile hakkında soruşturma veya kovuşturma yapılan ya da işlediği fiilden dolayı hakkında güvenlik tedbirine karar verilen çocuğu, b) Mahkeme: Çocuk mahkemeleri ile çocuk ağır ceza mahkemelerini, c) Çocuk hâkimi: Hakkında kovuşturma başlatılmış olanlar hariç, suça sürüklenen çocuklarla korunma ihtiyacı olan çocuklar hakkında uygulanacak tedbir kararlarını veren çocuk mahkemesi hâkimini, d) Kurum: Bu Kanun kapsamındaki çocuğun bakılıp gözetildiği, hakkında verilen tedbir kararlarının yerine getirildiği resmî veya özel kurumları, (...) İfade eder.",
  "Çocuk Koruma m.30": "(1) Çocuk bürosunun görevleri; a) Suça sürüklenen çocuklar hakkındaki soruşturma işlemlerini yürütmek, b) Çocuklar hakkında tedbir alınması gereken durumlarda, gecikmeksizin tedbir alınmasını sağlamak, c) Korunma ihtiyacı olan, suç mağduru veya suça sürüklenen çocuklardan yardıma, eğitime, işe, barınmaya ihtiyacı olan veya uyum güçlüğü çekenlere ihtiyaç duydukları destek hizmetlerini sağlamak üzere, ilgili kamu kurum ve kuruluşları ve sivil toplum kuruluşlarıyla işbirliği içinde çalışmak, bu gibi durumları çocukları korumakla görevli kurum ve kuruluşlara bildirmek, d) Bu Kanunla ve diğer kanunlarla verilen görevleri yerine getirmektir. (2) Gecikmesinde sakınca bulunan hâllerde, bu görevler çocuk bürosunda görevli olmayan Cumhuriyet savcıları tarafından da yerine getirilebilir.",
  "Çocuk Koruma m.31": "(1) Çocuklarla ilgili kolluk görevi, öncelikle kolluğun çocuk birimleri tarafından yerine getirilir. (2) Kolluğun çocuk birimi, korunma ihtiyacı olan veya suça sürüklenen çocuklar hakkında işleme başlandığında durumu, çocuğun veli veya vasisine veya çocuğun bakımını üstlenen kimseye, baroya ve Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna, çocuk resmî bir kurumda kalıyorsa ayrıca kurum temsilcisine bildirir. Ancak, çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınlarına bilgi verilmez. (3) Çocuk, kollukta bulunduğu sırada yanında yakınlarından birinin bulunmasına imkân sağlanır. (5) Çocuğun korunma ihtiyacı içinde bulunduğunun bildirimi (...) veya hakkında acil korunma kararı almak için beklemenin, çocuğun yararına aykırı olacağını gösteren nedenlerin varlığı hâlinde kolluğun çocuk birimi, durumun gerektirdiği önlemleri almak suretiyle çocuğun güvenliğini sağlar ve mümkün olan en kısa sürede Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna teslim eder.",
  "Çocuk Koruma m.37": "(1) Denetim altına alınan çocukla ilgili olarak denetimli serbestlik ve yardım merkezi şube müdürlüğü tarafından bir denetim görevlisi görevlendirilir. Ancak, korunma ihtiyacı olan çocuklar veya suç tarihinde oniki yaşını bitirmemiş suça sürüklenen çocuklar ile çocuğun aileye teslimi yönünde karar verilmesi hâlinde, bu çocuklar hakkında denetim görevi gözetim esaslarına göre Sosyal Hizmetler ve Çocuk Esirgeme Kurumu tarafından yerine getirilir. (2) Görevlendirme sırasında çocuğun kişisel özellik ve ihtiyaçları dikkate alınır ve çocuğa kolay ulaşabilecek olanlar tercih edilir.",
  "Çocuk Koruma m.41/A": "(1) Çocuk teslimi veya çocukla kişisel ilişki kurulmasına dair aile mahkemeleri tarafından verilen ilam veya tedbir kararları, çocuğun üstün yararı esas alınarak, Adalet Bakanlığınca kurulan adli destek ve mağdur hizmetleri müdürlüklerince bu Kısım hükümlerine göre yerine getirilir. (...) (3) Müdürlük bulunmayan yerlerde bu Kısım kapsamında yer alan görevler, Adalet Bakanlığınca belirlenen hukuk mahkemeleri yazı işleri müdürlüğü tarafından yerine getirilir. (4) İlam ve tedbir kararlarının yerine getirilmesinde çocuğun yerleşim yeri müdürlüğü yetkilidir. (5) İlam ve tedbir kararları müdürlük tarafından görevlendirilen psikolog, pedagog, sosyal çalışmacı, çocuk gelişimci ve rehber öğretmen gibi uzmanlar, uzmanın bulunmadığı yerlerde ise öğretmen marifetiyle yerine getirilir.",
  "Çocuk Koruma m.41/B": "(1) Çocuk teslimine dair ilam veya tedbir kararları, yükümlüsü tarafından rızasıyla yerine getirilmediği takdirde hak sahibi, ilam veya tedbir kararının yerine getirilmesi için müdürlüğe başvurabilir. (2) Talebi alan müdürlük, (...) yükümlüyle irtibata geçer ve müdürlük tarafından belirlenen gün ve saatte hak sahibine teslim edilmek üzere çocuğun belirlenen yere getirilmesini derhâl bildirir; (...) (3) Yükümlüyle irtibat kurulamaz veya yükümlü çocuğu getirmeyeceğini beyan ederse yahut yükümlü çocuğu belirlenen yere getirmezse müdürlük, derhâl yükümlüye, çocuğun teslimine dair bir teslim emri gönderir. (...) (5) Yükümlü, emrin gereğini yerine getirmezse, çocuk nerede bulunursa bulunsun müdürlük tarafından alınarak hak sahibine teslim edilir. Bu hâlde kolluktan yardım istenebilir. Kolluk birimleri, zor kullanma dâhil bu konudaki talepleri derhâl yerine getirir.",
  "Çocuk Koruma m.41/C": "(1) Çocukla kişisel ilişki kurulmasına dair ilam veya tedbir kararları, yükümlüsü tarafından rızasıyla yerine getirilmediği takdirde hak sahibi, ilam veya tedbir kararının yerine getirilmesi için müdürlüğe başvurabilir. (2) Talebi alan müdürlük, (...) yükümlüyle irtibata geçer; (...) çocuğun müdürlük tarafından belirlenen yere getirilmesini derhâl bildirir; (...) (3) Yükümlüyle irtibat kurulamaz veya yükümlü çocuğu getirmeyeceğini beyan ederse yahut belirlenen yere getirmezse müdürlük, derhâl yükümlüye, çocukla kişisel ilişki kurulmasına dair bir teslim emri gönderir. (...) (7) Hak sahibi, emrin yükümlüye tebliğinden sonraki dönemde, teslim saatinden en az kırk sekiz saat önce çocuğu teslim almaya geleceğini müdürlüğe (...) bildirmek zorundadır.",
  "Çocuk Koruma m.41/E": "MADDE 41/E- (1) (...) müdürlükçe yapılan işlem ve verilen kararlara karşı, öğrenme veya tebliğ tarihinden itibaren bir hafta içinde, işlemi yapan müdürlüğün bulunduğu yer aile mahkemesine şikâyette bulunulabilir. (...) (3) Şikâyet üzerine verilen karara karşı, tebliğ tarihinden itibaren iki hafta içinde itiraz edilebilir. (...) İtiraz üzerine verilen karar kesindir. — MADDE 41/F- (1) Çocuk teslimine dair ilam veya tedbir kararlarının yerine getirilmesine ilişkin teslim emrine aykırı hareket edenler ile emrin gereğinin yerine getirilmesini engelleyenler, bir ay içinde yapılacak şikâyet üzerine, fiil suç teşkil etse dahi, üç aya kadar disiplin hapsi ile cezalandırılır. (2) Çocukla kişisel ilişki kurulmasına dair (...) teslim emrine aykırı hareket edenler (...) üç günden on güne kadar disiplin hapsiyle cezalandırılır. (...)",
  "Çocuk Koruma m.45": "(1) Bu Kanunun 5 inci maddesinde yer alan koruyucu ve destekleyici tedbirlerden; a) (a) ve (e) bentlerinde yazılı danışmanlık ve barınma tedbirleri Milli Eğitim Bakanlığı, Sosyal Hizmetler ve Çocuk Esirgeme Kurumu ve yerel yönetimler, b) (b) bendinde yazılı eğitim tedbiri Milli Eğitim Bakanlığı ve Çalışma ve Sosyal Güvenlik Bakanlığı, c) (c) bendinde yazılı bakım tedbiri Sosyal Hizmetler ve Çocuk Esirgeme Kurumu, d) (d) bendinde yazılı sağlık tedbiri Sağlık Bakanlığı, Tarafından yerine getirilir. (...) (3) Bu tedbirlerin yerine getirilmesinde kurumların koordinasyonu Adalet Bakanlığınca sağlanır.",
  "Çocuk Koruma m.5": "(1) Koruyucu ve destekleyici tedbirler, çocuğun öncelikle kendi aile ortamında korunmasını sağlamaya yönelik danışmanlık, eğitim, bakım, sağlık ve barınma konularında alınacak tedbirlerdir. Bunlardan; a) Danışmanlık tedbiri, (...) yol göstermeye, b) Eğitim tedbiri, çocuğun bir eğitim kurumuna gündüzlü veya yatılı olarak devamına; (...) yerleştirilmesine, c) Bakım tedbiri, (...) çocuğun resmî veya özel bakım yurdu ya da koruyucu aile hizmetlerinden yararlandırılması veya bu kurumlara yerleştirilmesine, d) Sağlık tedbiri, çocuğun fiziksel ve ruhsal sağlığının korunması ve tedavisi için gerekli (...) tıbbî bakım ve rehabilitasyonuna, (...) e) Barınma tedbiri, barınma yeri olmayan çocuklu kimselere veya hayatı tehlikede olan hamile kadınlara uygun barınma yeri sağlamaya, Yönelik tedbirdir. (2) Hakkında, birinci fıkranın (e) bendinde tanımlanan barınma tedbiri uygulanan kimselerin, talepleri hâlinde kimlikleri ve adresleri gizli tutulur. (3) Tehlike altında bulunmadığının tespiti ya da tehlike altında bulunmakla birlikte veli veya vasisinin ya da bakım ve gözetiminden sorumlu kimsenin desteklenmesi suretiyle tehlikenin bertaraf edileceğinin anlaşılması hâlinde; çocuk, bu kişilere teslim edilir. (...)",
  "Çocuk Koruma m.6": "(1) Adlî ve idarî merciler, kolluk görevlileri, sağlık ve eğitim kuruluşları, sivil toplum kuruluşları, korunma ihtiyacı olan çocuğu Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna bildirmekle yükümlüdür. Çocuk ile çocuğun bakımından sorumlu kimseler çocuğun korunma altına alınması amacıyla Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna başvurabilir. (2) Sosyal Hizmetler ve Çocuk Esirgeme Kurumu kendisine bildirilen olaylarla ilgili olarak gerekli araştırmayı derhâl yapar.",
  "Çocuk Koruma m.7": "(1) Çocuklar hakkında koruyucu ve destekleyici tedbir kararı; çocuğun anası, babası, vasisi, bakım ve gözetiminden sorumlu kimse, Sosyal Hizmetler ve Çocuk Esirgeme Kurumu ve Cumhuriyet savcısının istemi üzerine veya re'sen çocuk hâkimi tarafından alınabilir. (3) Tedbirin türü kararda gösterilir. Bir veya birden fazla tedbire karar verilebilir. (4) Hâkim, hakkında koruyucu ve destekleyici tedbire karar verdiği çocuğun denetim altına alınmasına da karar verebilir. (6) Tedbirin uygulanması, onsekiz yaşın doldurulmasıyla kendiliğinden sona erer. Ancak hâkim, eğitim ve öğrenimine devam edebilmesi için ve rızası alınmak suretiyle tedbirin uygulanmasına belli bir süre daha devam edilmesine karar verebilir.",
  "Çocuk Koruma m.8": "(2) Tedbir kararlarının uygulanması, kararı veren hâkim veya mahkemece en geç üçer aylık sürelerle incelettirilir.",
  "Çocuk Koruma m.9": "(1) Derhâl korunma altına alınmasını gerektiren bir durumun varlığı hâlinde çocuk, Sosyal Hizmetler ve Çocuk Esirgeme Kurumu tarafından bakım ve gözetim altına alındıktan sonra acil korunma kararının alınması için Kurum tarafından çocuğun Kuruma geldiği tarihten itibaren en geç beş gün içinde çocuk hâkimine müracaat edilir. Hâkim tarafından, üç gün içinde talep hakkında karar verilir. Hâkim, çocuğun bulunduğu yerin gizli tutulmasına ve gerektiğinde kişisel ilişkinin tesisine karar verebilir. (2) Acil korunma kararı en fazla otuz günlük süre ile sınırlı olmak üzere verilebilir. (...) Çocuğun, ailesine teslim edilip edilmeyeceğine veya uygun görülen başkaca bir tedbire hâkim tarafından karar verilir.",
  "Çocuk Tedbir Yön m.11": "Hâkim, çocuğun gelişimini göz önünde bulundurarak koruyucu ve destekleyici tedbirin kaldırılmasına karar verebilir. Bu karar acele hâllerde, çocuğun bulunduğu yer hâkimi tarafından da verilebilir. Ancak bu durumda karar, önceki kararı alan hâkim veya mahkemeye bildirilir. (...) Tedbirin uygulanması, onsekiz yaşın doldurulmasıyla ayrıca bir karara gerek kalmaksızın kendiliğinden sona erer. Ancak hâkim, eğitim ve öğrenimine devam edebilmesi için ve çocuğun rızası alınmak suretiyle tedbirin uygulanmasına belli bir süre daha devam edilmesine karar verebilir.",
  "Çocuk Tedbir Yön m.12": "Danışmanlık tedbiri, çocuğun bakımından sorumlu olan kimselere çocuk yetiştirme konusunda; çocuklara da eğitim ve gelişimleri ile ilgili sorunlarının çözümünde yol göstermeye yönelik rehberlik tedbirleridir. (...) Danışmanlık tedbiri, Millî Eğitim Bakanlığı, (...) Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü ve yerel yönetimler tarafından yerine getirilir.",
  "Çocuk Tedbir Yön m.13": "Eğitim tedbiri, çocuğun bir eğitim kurumuna gündüzlü veya yatılı olarak devamına; bu şekilde eğitim alması mümkün olmayan çocukların evde eğitim almalarına, özel eğitim almaları gereken çocukların eğitsel ihtiyaçları doğrultusunda ilgili eğitim kurumuna devamına, (...) çocuğun iş ve meslek edinmesi amacıyla bir meslek veya sanat edinme kursuna gitmesine veya meslek sahibi bir ustanın yanına yahut kamu ya da özel sektöre ait işyerlerine yerleştirilmesine yönelik tedbirlerdir. (...) (5) Eğitim tedbiri kararının verilmesinde onbeş yaşını doldurmamış çocuklar bakımından (...) eğitimlerinin devamına ilişkin tedbir kararı verilebilir. (6) Onbeş yaşını doldurmuş çocuk hakkında, iş ve meslek edinmesi amacıyla bir meslek veya sanat edinme kursuna gitmesine, meslek sahibi bir ustanın yanına yahut kamu ya da özel sektöre ait işyerlerine yerleştirilmesine yönelik (...) tedbir kararı (...) yerine getirilir. (...) (8) Eğitim tedbiri, Millî Eğitim Bakanlığı ile Çalışma ve Sosyal Güvenlik Bakanlığının ilgili birimleri tarafından yerine getirilir.",
  "Çocuk Tedbir Yön m.14": "Bakım tedbiri, çocuğun bakımından sorumlu olan kimsenin herhangi bir nedenle görevini yerine getirememesi hâlinde, (...) Aile ve Sosyal Politikalar Bakanlığı il ve ilçe müdürlükleri tarafından çocuğun resmî veya özel bakım yurduna yerleştirilmesi ya da koruyucu aile hizmetlerinden veya Kurumun bu kapsamda yürüttüğü hizmet modellerinden yararlandırılmasına yönelik tedbirdir. (...) Bakım tedbiri kararı verilen çocukların kolluk kuvvetlerince (...) Aile ve Sosyal Politikalar Bakanlığı il ve ilçe müdürlüklerine teslim edileceği hâllerde, çocuğun ilk sağlık kontrolü yapıldıktan sonra teslimi sağlanır. Bulaşıcı hastalığı olan çocukların tedavisi Sağlık Bakanlığınca gerçekleştirilir.",
  "Çocuk Tedbir Yön m.15": "Barınma tedbiri, yaşamını devam ettirmek için yeterli ve sağlıklı bir barınma yeri olmayan çocuklu kimselere veya hayatı tehlikede olan hamile kadınlar ile bunların çocuklarına uygun barınma yeri sağlamaya yönelik tedbirlerdir. (2) Barınma tedbiri uygulanan kimselerin, talepleri hâlinde kimlikleri ve adresleri gizli tutulur. (3) Barınma tedbiri kararı verilen kimselerin, kolluk kuvvetlerince tedbir kararını uygulayacak Kuruma teslim edileceği hâllerde, bu kimselerin ilk sağlık kontrolü yapıldıktan sonra teslimi sağlanır. (...) (6) Barınma tedbiri, (...) Aile ve Sosyal Politikalar Bakanlığı il ve ilçe müdürlükleri, Millî Eğitim Bakanlığı ve yerel yönetimler tarafından yerine getirilir.",
  "Çocuk Tedbir Yön m.16": "Sağlık tedbiri, çocuğun fiziksel ve ruhsal sağlığının korunması ve tedavisi için gerekli geçici veya sürekli tıbbî bakım ve rehabilitasyonu ile madde bağımlısı olanların tedavilerinin yapılmasına yönelik tedbirdir. (2) Suça sürüklenen veya korunma ihtiyacı olan akıl hastası çocuklar hakkında ruhsal sağlığının tedavisi için öncelikle sağlık tedbirine karar verilmesi esastır. (...) (4) Akıl hastalığı veya madde bağımlılığı sebebiyle sağlık tedbirine hükmetmeye ve kısıtlamaya resmî sağlık kurulu raporu üzerine karar verilir. Ancak, çocuğun akıl hastalığı veya madde bağımlılığının açıkça belli olduğu hallerde; kendisi veya anası, babası, vasisi, bakım ve gözetiminden sorumlu kimsenin tedavi talep etmesi üzerine veya re'sen rapor alınmadan da sağlık tedbirine karar verilebilir. (...) (13) Alkol ya da uyuşturucu veya uyarıcı madde bağımlısı olan çocukların, koruyucu ve destekleyici sağlık tedbiri olarak (...) verilen kararların yerine getirilmesinde tedavi için çocuğun rızası aranmaz. (...) (15) Sağlık tedbiri, Sağlık Bakanlığı tarafından yerine getirilir.",
  "Çocuk Tedbir Yön m.17": "Bakım ve barınma tedbirlerinin yerine getirilmesi sırasında ihtiyaç duyulan kolluk hizmetleri ilgili birimlerden talep edilir. Kolluk birimleri, bu talepleri geciktirmeksizin yerine getirir. (2) Bakım ve barınma tedbir kararı alınan kişiler ile çocukların rehabilitasyonu, eğitimi ve diğer bakanlıkların görev alanına giren hususlarla ilgili olarak (...) yapılan her türlü yardım ve destek talepleri Millî Eğitim Bakanlığı, İçişleri Bakanlığı, Sağlık Bakanlığı, ilgili diğer bakanlıklar ile kamu kurum ve kuruluşları tarafından geciktirilmeksizin yerine getirilir.",
  "Çocuk Tedbir Yön m.18": "Tedbir kararlarını yerine getirmekle görevli kişi, kurum veya kuruluşlarca, bu tedbir kararlarının nasıl yerine getirileceği konusunda bir plân hazırlanarak uygulamaya konulur. Bu plân çocuğun teslim edildiği ya da teslim alındığı tarihten itibaren en geç on gün içerisinde mahkeme veya çocuk hâkiminin onayına sunulur. Mahkeme veya çocuk hâkimi, gerektiğinde uygulama plânının değiştirilmesini isteyebilir. (...) Tedbir kararını veren mahkeme veya çocuk hâkimi, tedbir kararlarının uygulanmasını, tedbirden beklenen gayenin gerçekleşip gerçekleşmediğini, uygulanan tedbirin çocuğun gelişimini hangi yönde etkilediğini en geç üçer aylık sürelerle incelettirir. (...) Ancak bu tedbirlerin yerine getirilmesinde ceza infaz kurumlarına herhangi bir görev yüklenemez.",
  "Çocuk Tedbir Yön m.20": "(1) İllerde koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumlar arasında bağlantı, uyum, düzen ve eşgüdüm; vali veya vali yardımcısının başkanlığında, Cumhuriyet başsavcısı veya görevlendireceği Cumhuriyet başsavcı vekili ya da Cumhuriyet savcısı ile il emniyet müdürü, il jandarma komutanı, il millî eğitim müdürü, il sağlık müdürü, büyükşehir, il ve merkez ilçe belediye başkanları, (...) Aile ve Sosyal Politikalar Bakanlığı il müdürü, (...) denetimli serbestlik ve yardım merkezî şube müdürü ve baro temsilcisi marifetiyle yerine getirilir. (2) Gerek görülen hâllerde toplântı düzenlenerek gündeme alınan konular görüşülür. (...) Toplântı gündemi valinin görüş ve direktifleri ile diğer kurum ve kuruluşların görüşleri alınarak (...) Aile ve Sosyal Politikalar Bakanlığı il müdürlüğünce hazırlanır. Toplântı gündemi ve günü sekretarya görevini yürüten koordinatör birim tarafından bu kişilere on beş gün önceden bildirilir. (4) İllerde koordinasyonun sekretarya hizmetleri (...) Aile ve Sosyal Politikalar Bakanlığı il müdürlüğü tarafından yürütülür. (m.21/1) İlçelerde koruyucu ve destekleyici tedbirlerin yerine getirilmesinde kurumların koordinasyonu, 20 nci madde hükümlerine göre kaymakamlıkça yerine getirilir.",
  "Çocuk Tedbir Yön m.22": "(2) Koruyucu ve destekleyici tedbir kararlarını yerine getirmekle görevli kişi, kurum veya kuruluşlar, (...) kararın kendilerine bildirildiği veya tebliğ edildiği tarihten itibaren çocuğu teslim alarak derhâl gerekli işlemleri başlatır. (3) Çocuğun bulunamaması hâlinde durum ilgili kolluk birimlerine bildirilir. Mahkeme veya çocuk hâkimi tedbir kararının yerine getirilmesi için çocuğun bulunması ve ilgili kuruma tesliminin kolluğun çocuk birimi tarafından sağlanmasına karar verebilir. (...) Yakalanan çocuklar ilgili kurumlara teslim edilir. (...) (4) Haklarında bakım veya barınmaya ilişkin tedbir kararı alınan ve (...) çocukların, izinsiz olarak kurum veya kuruluştan ayrılmaları durumunda tutanak tutulur. Durum, en seri iletişim araçları ile kolluk birimine bildirilir. (...) Ayrıca mahkeme veya çocuk hâkimine de bilgi verilir.",
  "Çocuk Tedbir Yön m.26": "Çocuklara ilişkin koruyucu ve destekleyici tedbir kararlarının alınması ile uygulanmasına ilişkin tüm süreçlerde çocuğun avukatı hariç olmak üzere çocuğun kimliği, adresi, fotoğrafları, yaşadığı travmalar gibi çocuğa ve yakınlarına ait her türlü bilgi ve bu bilgilerin yer aldığı rapor ve belgeler ile kayıtlar gizli tutulur. Yazışmalar gizlilik ilkesine uygun bir şekilde gerçekleştirilir.",
  "Çocuk Tedbir Yön m.4": "a) Çocuk: Daha erken yaşta ergin olsa bile, onsekiz yaşını doldurmamış kişiyi; bu kapsamda, 1) Korunma ihtiyacı olan çocuk: Bedensel, zihinsel, ahlâkî, sosyal ve duygusal gelişimi ile kişisel güvenliği tehlikede olan, ihmal veya istismar edilen ya da suç mağduru çocuğu, 2) Suça sürüklenen çocuk: Kanunlarda suç olarak tanımlanan bir fiili işlediği iddiası ile hakkında soruşturma veya kovuşturma yapılan ya da işlediği fiilden dolayı hakkında güvenlik tedbirine karar verilen çocuğu, b) Çocuk hâkimi: Hakkında kovuşturma başlatılmış olanlar hariç, suça sürüklenen çocuklarla korunma ihtiyacı olan çocuklar hakkında uygulanacak tedbir kararlarını veren çocuk mahkemesi hâkimini, (...) d) Mahkeme: Çocuk mahkemeleri ile çocuk ağır ceza mahkemelerini, çocuk mahkemesi bulunmayan yerlerde aile ya da asliye hukuk mahkemeleri ile ceza mahkemelerini, (...) ifade eder.",
  "Çocuk Tedbir Yön m.5": "Koruyucu ve destekleyici tedbirler, çocuğun yararı göz önünde bulundurularak, öncelikle kendi aile ortamında korunmasının sağlanması ile yaşına ve gelişimine uygun eğitim ve öğreniminin desteklenmesini, kişiliğinin ve toplumsal sorumluluğunun geliştirilmesini sağlamaya yönelik; a) Danışmanlık, b) Eğitim, c) Bakım, d) Sağlık, e) Barınma, tedbirleridir.",
  "Çocuk Tedbir Yön m.6": "Adlî ve idarî merciler, kolluk görevlileri, köy ve mahalle muhtarları, belediye zabıta memurları, sağlık ve eğitim kuruluşları, diğer kamu kurum ve kuruluşlarının görevlileri, sivil toplum kuruluşları ile bir çocuğun korunma ihtiyacı olduğundan haberdar olanlar, durumu il ve ilçelerdeki (...) Aile ve Sosyal Politikalar müdürlüklerine bildirmekle yükümlüdür. (3) İl ve ilçe (...) Aile ve Sosyal Politikalar müdürlükleri, korunma ihtiyacı olan çocuklar hakkında basın ve yayın organları ile benzeri iletişim araçlarında çıkan haberleri ve her türlü duyumu ihbar kabul ederek ayrıca bir resmî duyuru gelmesini beklemeden harekete geçerek bunları araştırmakla yükümlüdür. (...) (7) Koruyucu ve destekleyici tedbir kararı alınması gereken hâllerde, il veya ilçe (...) Aile ve Sosyal Politikalar müdürlüğünce çocuk hakkında (...) hazırlanacak sosyal inceleme raporu, talep yazısı ekinde mahkemeye veya çocuk hâkimine sunulur.",
  "Çocuk Tedbir Yön m.7": "Acil korunma kararının alınması için Kurum tarafından çocuğun Kuruma geldiği tarihten itibaren en geç beş gün içinde çocuk hâkimine müracaat edilir. Hâkim tarafından, üç gün içinde talep hakkında karar verilir. Hâkim, çocuğun bulunduğu yerin gizli tutulmasına ve gerektiğinde kişisel ilişkinin tesisine karar verebilir. (...) Acil korunma kararı en fazla otuz günlük süre ile sınırlı olmak üzere verilebilir. Bu süre içinde Kurumca çocuk hakkında sosyal inceleme yapılır.",
  "Çocuk Tedbir Yön m.8": "Çocuklar hakkında koruyucu ve destekleyici tedbir kararı; çocuğun anası, babası, vasisi, bakım ve gözetiminden sorumlu kimse (...) Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü ve Cumhuriyet savcısının istemi üzerine veya re'sen çocuğun menfaatleri bakımından kendisinin, ana, baba, vasisi veya birlikte yaşadığı kimselerin bulunduğu yerdeki çocuk hâkimince alınır. (...) Hakkında kovuşturma başlatılmış olan çocuklar için koruyucu ve destekleyici tedbir kararı kovuşturmanın yapıldığı mahkemece alınır. (...) (12) Mahkeme veya çocuk hâkimi bir veya birden fazla tedbire karar verebilir. (...) kurumda bakım ve kurumda tutmanın son çare olarak görülmesi (...) temel ilkesinden hareketle çocuğu öncelikle aile içinde destekleyen danışmanlık, eğitim ve sağlık tedbirlerinin alınması esası gözetilir. Ancak; (...) çocuğun yaşama, gelişme, korunma ve katılım hakları ile yarar ve esenliğinin tehlikeye düşebileceğinin tespiti hâlinde; diğer tedbirler yanında kurumda bakım veya barınma tedbiri kararı alınması öncelikle değerlendirilir.\n\nFiili işlediği sırada oniki yaşından küçük çocuklar ile onbeş yaşını doldurmamış sağır ve dilsizler hakkında mahkemece, 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun 31 inci maddesinin birinci fıkrası ile 33 üncü maddesi uyarınca çocuklara özgü güvenlik tedbirleri uygulanabilir. (...) Fiili işlediği sırada oniki yaşını bitirmiş onbeş yaşını doldurmamış bulunan çocuklar ile onbeş yaşını doldurmuş ancak onsekiz yaşını doldurmamış sağır ve dilsizlerin işledikleri fiilin hukukî anlam ve sonuçlarını algılayamamaları veya davranışlarını yönlendirme yeteneklerinin yeterince gelişmemiş olması hâlinde mahkemece, 5237 sayılı Türk Ceza Kanununun 31 inci maddesinin ikinci fıkrası ile 33 üncü maddesi uyarınca çocuklara özgü güvenlik tedbirlerine hükmolunur.\n\n(8) Çocuk hâkimi veya mahkemece, koruyucu ve destekleyici tedbir kararı verilmeden önce yeterli idrak gücü bulunan çocuğun yazılı veya sözlü olarak görüşü alınır. Gerektiğinde koruyucu ve destekleyici tedbir kararını istemeye yetkili olan çocuğun anası, babası, vasisi, bakım ve gözetiminden sorumlu kimse ile Aile ve Sosyal Politikalar Bakanlığı Çocuk Hizmetleri Genel Müdürlüğü temsilcileri de dinlenebilir. (10) Aile mahkemeleri, bakmakta oldukları davalar ile ilgili koruyucu ve destekleyici tedbir kararı verebilir. (12) Mahkeme veya çocuk hâkimi bir veya birden fazla tedbire karar verebilir. (...) (15) Çocuk hâkimi veya mahkeme, hakkında koruyucu ve destekleyici tedbir kararı verdiği çocuğun denetim altına alınmasına da karar verebilir.",
  "Çocuk Tedbir Yön m.9": "Mahkeme veya çocuk hâkimince bu Yönetmelik uyarınca verilen; a) Danışmanlık ve barınma tedbir kararları, ilgisine göre il millî eğitim müdürlükleri, (...) Aile ve Sosyal Politikalar Bakanlığı il veya ilçe müdürlükleri ya da yerel yönetimlere, b) Eğitim tedbiri kararı, ilgisine göre il millî eğitim müdürlüklerine veya Çalışma ve Sosyal Güvenlik Bakanlığı bölge müdürlüklerine, c) Bakım tedbiri kararı (...) Aile ve Sosyal Politikalar Bakanlığı il veya ilçe müdürlüklerine, ç) Sağlık tedbiri kararı, il sağlık müdürlüklerine, gönderilir. (...) Koruyucu ve destekleyici tedbir kararı, kesinleştirilmesi beklenmeksizin derhâl uygulanır.",
  "Çocuk Usul Yön m.16": "Çocuklarla ilgili kolluk görevi, öncelikle kolluğun çocuk birimleri tarafından yerine getirilir. Kolluk bünyesinde çocuklarla ilgili işlemlerin yürütülmesi sırasında, bunların soruşturma nedeniyle kolluk biriminde bulunan yetişkinlerle karşılaşmalarının engellenmesi için gerekli tedbirler alınır.\" (m.16/1-2)\n\nKolluğun çocuk birimi, korunma ihtiyacı olan veya suça sürüklenen çocuklar hakkında işleme başlandığında durumu, derhal çocuğun veli veya vasisine ya da çocuğun bakımını üstlenen kimseye, baroya ve Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna, çocuk resmî veya özel bir kurumda kalıyorsa ayrıca kurum temsilcisine bildirir. Ancak, çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınlarına bilgi verilmez. Keyfiyet, soruşturma dosyası içine konulmak üzere tutanak altına alınarak derhâl Cumhuriyet savcısına bildirilir.\" (m.16/3)\n\nÇocuğun yararı aksini gerektirmediği takdirde kollukta bulunduğu süre içerisinde yanında yakınlarından birinin devamlı olarak bulunmasına imkân sağlanır. Çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelenilen yakınları yanında bulundurulmaz. Keyfiyet hazırlanan tutanağa yazılarak adlî veya idarî makamlara sevk edilen evraka eklenir.\" (m.16/4)\n\nKolluğun çocuk birimi, suça sürüklenen çocuğun aileye teslimini gerektiren hâllerde; çocuğun teslim edileceği veli, vasi, kanunî temsilci veya bakımını üstlenen kimseleri bulamaz ya da bunların çocuğu suça azmettirdiğinden veya istismar ettiğinden şüphelendiğinde bu kişilere teslim edemez. Cumhuriyet savcısının talimatını alarak Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna teslim eder.\" (m.16/5)\n\nKolluk görevlisi, teslim ettiği çocuğun veli, vasi, kanunî temsilcisi veya bakımını üstlenen kimselerin çocuğa yeterli rehberliği sunamadığı veya çocuğu yeterince gözetemediği hususlarında bilgi edinmesi hâlinde durumu Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna derhâl bildirir.\" (m.16/6) — \"Korunma ihtiyacı içinde olan çocuğun (...) hakkında acil korunma kararı almak için beklemenin çocuğun yararına aykırı olacağını gösteren nedenlerin (...) tespiti hâlinde; kolluğun çocuk birimi, durumun gerektirdiği önlemleri almak suretiyle çocuğun güvenliğini sağlar ve mümkün olan en kısa sürede Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna teslim eder. (...) Kolluğun çocuk birimi, suç mağduru olan korunma ihtiyacı içinde olan çocuklar hakkında (...) teslim işlemini, Cumhuriyet savcısının talimatı doğrultusunda yapar.\" (m.16/7)",
  "Çocuk Usul Yön m.3": "Bu Yönetmelik, 3/7/2005 tarihli ve 5395 sayılı Çocuk Koruma Kanununun 32 ve 47 nci maddelerine dayanılarak hazırlanmıştır.\" (m.3/1)",
  "Çocuk Usul Yön m.5": "Suça sürüklenen çocuk hakkındaki soruşturma, çocuk bürosunda görevli Cumhuriyet savcısı tarafından bizzat yapılır. Gecikmesinde sakınca bulunan hâllerde, soruşturma çocuk bürosunda görevli olmayan Cumhuriyet savcıları tarafından da yerine getirilebilir.\" (m.5/1)\n\nİşlenen suçun etkisiyle psikolojisi bozulmuş mağdur çocuk, bu suça ilişkin soruşturmada tanık olarak bir defa dinlenebilir. Maddî gerçeğin ortaya çıkarılması açısından zorunluluk arz eden haller saklıdır.\" (m.5/6)\n\nMağdur çocuğun tanık olarak dinlenmesi sırasında psikoloji, psikiyatri, tıp veya eğitim alanında uzman bir kişi bulundurulur. Bunlar hakkında bilirkişilere ilişkin hükümler uygulanır.\" (m.5/7)\n\nSuça sürüklenen çocuğun ifadesinin alınması veya çocuk hakkındaki diğer işlemler sırasında, çocuğun yanında sosyal çalışma görevlisi bulundurulabilir.\" (m.5/4) — \"Mağdur çocuğun tanık olarak dinlenmesi hâlinde, yemin hariç, 4/12/2004 tarihli ve 5271 sayılı Ceza Muhakemesi Kanununun tanıklığa ilişkin hükümleri uygulanır.\" (m.5/5)\n\nCumhuriyet savcısı soruşturmayı yürütürken aynı zamanda tedbir kararı alınabilmesi için korunma ihtiyacı olan çocuğu, Sosyal Hizmetler ve Çocuk Esirgeme Kurumuna bildirmekle yükümlüdür. Sosyal Hizmetler ve Çocuk Esirgeme Kurumu gerekli incelemeyi derhâl yapar. (...) Cumhuriyet savcısı da soruşturma sırasında gerekli gördüğünde çocuk hâkiminden koruyucu ve destekleyici tedbir kararı verilmesini isteyebilir.\" (m.5/8)\n\nGörünüş itibarıyla oniki yaşından büyük olup, nüfus kaydına göre oniki yaşından küçük çocuklar ile çocuğun nüfusa kayıtlı yaşının gerçek yaşı olmadığının başka bir şekilde anlaşılması hâlinde; çocuğun yaşı hukuk mahkemesi nezdinde dava açılıp düzeltilmeden kamu davası açılamaz.\" (m.5/11)\n\nFiili işlediği sırada oniki yaşından küçük çocuklar ile onbeş yaşını doldurmamış sağır ve dilsizlerin işledikleri iddia olunan suçlara dair delillerin toplanması veya başka fail ya da faillerin bulunup bulunmadığının belirlenmesine ilişkin olarak yukarıdaki esaslar dahilinde soruşturma yapılabilir.\" (m.5/10)",
  "Disiplin m.1": "MADDE 1- (1) Bu Kanunun amacı; Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeline ilişkin disiplinsizlik ve cezaları, disiplin amirlerini ve kurullarını, disiplin soruşturma usulü ile diğer ilgili hususları düzenlemektir. MADDE 2- (1) Bu Kanun; a) Emniyet Genel Müdürlüğü teşkilatında çalışan her sınıftan memurları, b) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarında görev yapan subay, astsubay, sözleşmeli subay, sözleşmeli astsubay, uzman jandarma, uzman erbaş, sözleşmeli erbaş ve sözleşmeli erler ile diğer sınıflardaki memurları, kapsar.\n\nMADDE 1- (1) Bu Kanunun amacı; Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeline ilişkin disiplinsizlik ve cezaları, disiplin amirlerini ve kurullarını, disiplin soruşturma usulü ile diğer ilgili hususları düzenlemektir. MADDE 2- (1) Bu Kanun; a) Emniyet Genel Müdürlüğü teşkilatında çalışan her sınıftan memurları, b) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarında görev yapan subay, astsubay, sözleşmeli subay, sözleşmeli astsubay, uzman jandarma, uzman erbaş, sözleşmeli erbaş ve sözleşmeli erler ile diğer sınıflardaki memurları, kapsar. (2) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı emrine verilen yükümlü erbaş ve erler hakkında 31/1/2013 tarihli ve 6413 sayılı Türk Silahlı Kuvvetleri Disiplin Kanunu hükümleri uygulanır. MADDE 3- (1) Bu Kanunun uygulanmasında; a) Amir: Kadro ve kuruluş yönünden bağlı olunan kimse ile amir olarak yetkilendirilmiş olan diğer kişileri, b) Bakan: İçişleri Bakanını, c) Bakanlık: İçişleri Bakanlığını, ç) Disiplinsizlik: Bu Kanuna göre disiplin cezası ile cezalandırılan fiilleri, d) Disiplin amiri: Bu Kanun ile disiplin cezası vermeye yetkili kılınmış ilk amiri, (...) i) Personel: (...) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarında görev yapan subay, astsubay, (...) memurları, j) Üst: Makam, rütbe veya kıdem büyüklüğünü, k) Üst disiplin amirleri: Disiplin amirinin kadro ve kuruluş yönünden bağlı bulunduğu ve disiplin cezası verilecek personelden makam, rütbe veya kıdemce büyük olan yetkili sıralı tüm amirleri, ifade eder.",
  "Disiplin m.10": "MADDE 10- (1) Amirin emrinin yapılmaması fiilinin neticesinde, Devlet ya da kişiler zarara uğratılmış ya da hizmetin gecikmesine ya da durmasına neden olunmuşsa doğan zararın derecesine ya da durumun ağırlığına göre meslekten çıkarma cezası uygulanabilir. (10) Görevin takdir ve yerine getirilmesinde müsamaha veya savsaklama fiili Devleti veya kişileri zarara uğratmış veya hizmetin gecikmesine, durmasına ya da aksamasına neden olmuşsa durumun ağırlığına ve zararın derecesine göre daha ağır cezalardan birisi verilebilir. (13) Bu Kanunda belirlenmiş ve bir disiplin cezasıyla yaptırıma bağlanmış fiillerin sahil güvenlik personelince yurtdışı liman ziyaretlerinde veya Türk karasuları dışında işlenmesi halinde, uyarma ve kınama cezası gerektiren fiillerde (...) aylıktan kesme, kısa veya uzun süreli durdurma cezası; aylıktan kesme, kısa veya uzun süreli durdurma cezası gerektiren fiillerde ise (...) meslekten çıkarma cezası verilebilir.",
  "Disiplin m.11": "MADDE 11- (1) Jandarma Genel Komutanlığının terörle mücadele harekatı kapsamındaki operasyonlarında ve Sahil Güvenlik Komutanlığının seyir halindeki gemi ve botlarında, bunların komutanları, diğer kanunlar ile verilmiş yakalama yetkisi haricinde aşağıdaki durumlardan birisi bulunduğunda veya benzer bir amaçla emri altındakileri geçici olarak kontrol altına almaya veya aldırmaya yetkilidir. a) Kendisine, başkalarına veya çevresine ya da hizmete ait bir eşyaya zarar vereceği açık bir şekilde belli olanların bu durumunun engellenmesi. b) Ciddi şekilde bozulan disiplinin yeniden tesis edilmesi. c) Sarhoşluk süresince kişinin kontrol altında tutulması. (2) Kontrol altında bulundurma, bu amaç için hazırlanacak mahallerde, Jandarma Genel Komutanlığı için operasyon komutanının uygun gördüğü mahallerde ve yirmidört saati geçmeyecek şekilde uygulanır. Tedbir süresinin oniki saati geçmesi halinde, personelin yakınlarına ve tedbiri uygulayan komutanın üstüne en kısa sürede bilgi verilir. (3) Kontrol altına alınanlarla ilgili olarak durumun gerektirdiği tedbirler, disiplin amirlerince alınır veya alınması sağlanır. Bunlar hakkında disiplin cezası uygulamasında, eyleminin karşılığı olan cezanın üst sınırı, ceza üst sınırdaysa veya cezanın üst sınırı yok ise bir üst ceza uygulanır.",
  "Disiplin m.12": "MADDE 12- (1) Aşağıda belirtilen durumlar disiplinsizliği alışkanlık haline getirme olarak kabul edilir ve personel hakkında meslekten çıkarma cezası yetkili disiplin kurullarınca verilir: a) En son alınan disiplin cezasının kesinleştiği tarihten geriye doğru son bir yıl içinde yirmi disiplin cezası puanı veya en az iki farklı disiplin amirinden toplam oniki defa veya daha fazla disiplin cezası almak. b) En son alınan disiplin cezasının kesinleştiği tarihten geriye doğru son beş yıl içinde kırk disiplin cezası puanı veya en az iki farklı disiplin amirinden toplam yirmibeş defa veya daha fazla disiplin cezası almak. (2) Aynı disiplin dosyası kapsamında birden fazla disiplin cezası verilmesi halinde en yüksek olanın puanı değerlendirmeye esas alınır.",
  "Disiplin m.13": "MADDE 13- (1) Disiplin amirinin, disiplin cezası verilecek personelden makam, rütbe veya kıdemce büyük olması ve amir konumunda bulunması gerekir. (3) Kaymakamlar ilçe, valiler il teşkilatındaki diğer disiplin amirlerine göre en üst disiplin amiridir. Valiler kaymakamlara, Bakan ise Emniyet Genel Müdürü, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanı ile valilere göre bir üst disiplin amiridir. (5) Disiplin soruşturması yapma ve disiplin cezası verme görev ve yetkisi üst disiplin amirleri tarafından da kullanılabilir.",
  "Disiplin m.14": "MADDE 14- (1) Maiyetinden birinin disiplinsizlik teşkil eden bir fiilini veya mesleğe aykırı tutum ve davranışını herhangi bir şekilde öğrenen disiplin amirleri, olayın araştırılmasının gerektiğine kanaat getirirse bizzat ya da yazılı olarak görevlendireceği soruşturmacılar vasıtasıyla disiplin soruşturması yapar. (2) Disiplin soruşturmacısı olarak hakkında disiplin soruşturması yapılacak kişinin üstü konumundaki bir veya birden fazla kişi ya da Bakanlık ve/veya ilgisine göre Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ya da Sahil Güvenlik Komutanlığı müfettişi görevlendirilebilir. Ancak gerek görülmesi halinde, heyet başkanı hariç olmak üzere hakkında disiplin soruşturması yapılacak kişinin astı konumunda heyet üyeleri görevlendirilebilir. (...) (3) Disiplin soruşturmacıları ve heyeti, kendilerini görevlendiren disiplin amiri adına disiplin soruşturmasıyla ilgili bilgi ve belgeleri toplama, ifade alma, tanık dinleme, bilirkişi görevlendirme, keşif yapma, hâkim veya savcı kararı gerektirmeyen durumlarda kriminal inceleme yaptırma da dahil olmak üzere her türlü inceleme yapma ve ilgili makamlarla yazışma yetkisini haizdir. (...) (4) Disiplin soruşturmacısı olarak görevlendirilebileceği belirtilenler, boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında yürütülen soruşturmalarda görevlendirilemez.",
  "Disiplin m.15": "MADDE 15- (2) Disiplin amiri olarak tayin edilen unvanlara ait görevleri vekâleten, ikinci görevle, geçici görevle veya kanunlarda yazılı diğer hallerde yetkili olarak yürütenler de bu görevi yürüttükleri sürece disiplin amirlerine tanınan yetkileri kullanabilirler. (3) Disiplin amirleri boşanmış olsalar dahi eşleri veya ikinci dereceye kadar kan ve kayın hısımları olan personel hakkında, bu sıfatlarından doğan yetkilerini kullanamazlar. Bu hallerde, disiplin amirliği yetkisi, üst konumdaki disiplin amiri tarafından kullanılır. (4) Disiplin amirliği yetkisi devredilemez.",
  "Disiplin m.19": "MADDE 19- (1) Jandarma Genel Komutanlığı merkez ve taşra teşkilatlarında aşağıdaki disiplin kurulları bulunur. a) İl jandarma disiplin kurulu, vali yardımcısının başkanlığında, 1) İl hukuk işleri müdürü (...), 2) İl jandarma komutanı veya görevlendireceği yardımcılarından biri (...), 3) Personel şube müdürü (...), 4) Asayiş şube müdürü (...) oluşur. (...) ç) (...) Jandarma Genel Komutanlığı Merkez Disiplin Kurulu; Jandarma Genel Komutanının görevlendireceği en az tuğgeneral rütbesini taşıyan bir subayın başkanlığında (...) oluşur. d) (...) Jandarma Genel Komutanlığı Yüksek Disiplin Kurulu; Jandarma Genel Komutanının veya görevlendireceği jandarma genel komutan yardımcısının başkanlığında (...) oluşur. (2) Astsubayların disiplin işlerinin görüşülmesinde ve karara bağlanmasında; Bakanlık Yüksek Disiplin Kurulu ve Jandarma Genel Komutanlığı Yüksek Disiplin Kurulu hariç olmak üzere diğer disiplin kurullarında, hakkında disiplin soruşturması yapılandan daha kıdemli bir astsubay üyeye de yer verilir.",
  "Disiplin m.2": "MADDE 2- (2) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı emrine verilen yükümlü erbaş ve erler hakkında 31/1/2013 tarihli ve 6413 sayılı Türk Silahlı Kuvvetleri Disiplin Kanunu hükümleri uygulanır.",
  "Disiplin m.20": "MADDE 20- (1) a) İl jandarma disiplin kurulu (...) 1) Yüzbaşı ve altı rütbelerdeki subay, astsubay, uzman jandarma ve diğer sınıflardaki memurlara meslekten çıkarma ve Devlet memurluğundan çıkarma cezası dışında kalan diğer disiplin cezalarını, verebilir. (2) (...) a) Albay rütbesindeki personele meslekten çıkarma cezasını, b) Generaller hakkında tüm disiplin cezalarını, vermeye Bakanlık Yüksek Disiplin Kurulu yetkilidir. MADDE 21- (1) a) İl jandarma disiplin kurulunun meslekten çıkarma cezası dışındaki kararları valinin onayıyla; meslekten çıkarma cezası kararları valinin önerisi, Jandarma Genel Komutanlığı Yüksek Disiplin Kurulunun uygun görüşü ve Bakanın onayıyla, b) Asayiş kolordu komutanlıkları, komando tugay/alay komutanlıkları, (...) eğitim tugay ve birlik komutanlıkları disiplin kurulu, Genel Komutanlık Merkez Disiplin Kurulu ile eğitim ve öğretim kurumlarındaki disiplin kurullarının meslekten çıkarma cezası dışındaki kararları Jandarma Genel Komutanının onayıyla, meslekten çıkarma cezası kararları JGnK Yüksek Disiplin Kurulunun uygun görüşü ve Bakanın onayıyla, c) Genel Komutanlık Yüksek Disiplin Kurulunun kararları Bakanın onayıyla, kesinleşir.",
  "Disiplin m.25": "MADDE 25- (1) Emniyet Genel Müdürü, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının disiplin cezasını gerektiren fiilleri öğrenildiğinde haklarında Bakan onayıyla Bakanlık müfettişleri görevlendirilir. (2) Soruşturma sonucunda Bakanın resen verebileceği cezalardan daha ağır bir cezayı gerektiren disiplinsizlik tespit edilmesi halinde, dosya Bakanlık Yüksek Disiplin Kurulunca karara bağlanır. (3) Bakanlık Yüksek Disiplin Kurulunun bu maddedeki görevlerine ilişkin sekretarya hizmetleri Bakanlık Personel Genel Müdürlüğü tarafından yerine getirilir. (4) (...) Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığından gelen üyeler katılamazlar. MADDE 26- (1) (Değişik:18/10/2018-7148/42 md.) Disiplin soruşturmasının açılmasında ve disiplin amiri veya disiplin kurulunun saptanmasında disiplinsizlik yaptığı iddia edilen personelin fiili işlediği tarihte çalıştığı yer esas alınır. (...) Ast memur ile üst memurun aynı fiile iştiraki halinde yetkili disiplin kurulu, üst memur hakkında disiplin cezası vermeye yetkili disiplin kuruludur. (...) (8) Disiplin kurulları salt çoğunlukla toplanır. Kararlar oy çokluğu ile alınır. Çekimser oy kullanılamaz. Oyların eşitliği halinde başkanın oyu yönünde karar alınmış sayılır. (9) Disiplin kurulları; (...) hâkim veya savcı kararı gerektirmeyen durumlarda kriminal inceleme yaptırma da dahil olmak üzere her türlü inceleme yapma ve ilgili makamlarla yazışma yetkisini haizdir.",
  "Disiplin m.29": "MADDE 29- (1) Bu Kanunda sayılan fiilleri işleyenler hakkında bu fiillerin işlendiğinin disiplin amiri tarafından öğrenildiği tarihten itibaren; a) Uyarma, kınama, aylıktan kesme ve kısa ve uzun süreli durdurma cezalarında bir ay içinde, b) Meslekten çıkarma cezası ve Devlet memurluğundan çıkarma cezasında altı ay içinde, disiplin soruşturmasına başlanmadığı takdirde disiplin cezası verme yetkisi zamanaşımına uğrar. (2) Disiplin cezasını gerektiren fiillerin işlendiği tarihten itibaren iki yıl içinde disiplin cezası verilmediği takdirde ceza verme yetkisi zamanaşımına uğrar. (3) Zamanaşımı, tamamlanmış suçlarda suçun işlendiği, kesintisiz suçlarda kesintinin gerçekleştiği, zincirleme suçlarda ise son suçun işlendiği tarihten itibaren işlemeye başlar.",
  "Disiplin m.3": "MADDE 3- (1) Bu Kanunun uygulanmasında; d) Disiplin amiri: Bu Kanun ile disiplin cezası vermeye yetkili kılınmış ilk amiri, e) Disiplin amirleri: Disiplin amiri ile üst disiplin amirlerini, j) Üst: Makam, rütbe veya kıdem büyüklüğünü, k) Üst disiplin amirleri: Disiplin amirinin kadro ve kuruluş yönünden bağlı bulunduğu ve disiplin cezası verilecek personelden makam, rütbe veya kıdemce büyük olan yetkili sıralı tüm amirleri, ifade eder.",
  "Disiplin m.30": "MADDE 30- (1) Disiplin amirleri tarafından verilen disiplin cezalarına karşı, cezanın tebliğ edilmesinden itibaren on gün içinde itiraz edilebilir. İtiraz, bir üst disiplin amirine yazılı olarak yapılır. Ancak vali, Emniyet Genel Müdürü, Jandarma Genel Komutanı veya Sahil Güvenlik Komutanının doğrudan verdikleri disiplin cezalarına karşı Bakanlık Yüksek Disiplin Kuruluna itiraz edilir. İtiraz üzerine Kurulun verdiği karar kesindir. Kaymakamın doğrudan verdiği disiplin cezalarına karşı ise valiye itiraz edilir. Süresi içinde itiraz edilmeyen cezalar kesinleşir. (2) İtiraz, yetkili merci tarafından otuz gün içinde karara bağlanır. (3) İtiraz haklı görülürse itirazı inceleyen merci verilen cezayı hafifletebilir veya tamamen kaldırabilir. (...) (4) İtiraz üzerine önceki cezadan daha ağır ceza verilemez. (5) Bakan ile disiplin kurullarının verdiği disiplin cezalarına karşı ancak idari yargı yoluna başvurulabilir.",
  "Disiplin m.31": "MADDE 31- (1) Disiplin amirleri veya disiplin kurulları tarafından savunma alınmadan disiplin cezası verilemez. (2) Disiplin amirince veya yetkili disiplin kurulu başkanı ya da görevlendireceği kurul üyelerinden biri tarafından ilgiliden savunma istenir. Savunma için verilen süre yedi günden az olamaz. Süresi içinde savunmasını yapmayan personel, savunma hakkından vazgeçmiş sayılır. (3) Hakkında disiplin soruşturması yapılan personel, ikinci fıkra gereğince kendisinden savunma istenmesinden itibaren soruşturma evrakını inceleme hakkına sahiptir. (4) Hakkında meslekten çıkarma cezası veya Devlet memurluğundan çıkarma cezası istenen personel, soruşturma evrakını incelemeye, tanık dinletmeye, disiplin kurulunda sözlü veya yazılı olarak kendisi veya vekili vasıtasıyla savunma yapma hakkına sahiptir.",
  "Disiplin m.32": "MADDE 32- (1) Kesinleşen disiplin cezalarına karşı iptal davası açılabilir. (2) Dava açma süresi, kesinleşen cezanın personele tebliğinden itibaren başlar. Ancak Sahil Güvenlik Komutanlığının seyir halindeki gemi ve botlarında verilen cezalarda dava açma süresi, geminin bağlı bulunduğu üsse veya limana dönmesiyle başlar.",
  "Disiplin m.33": "MADDE 33- (1) Disiplin cezaları, kesinleşmesini müteakip yerine getirilir. (2) Aylıktan kesme cezası, kesinleşme tarihini takip eden aybaşında uygulanır. (3) Verilen disiplin cezaları üst disiplin amirine, meslekten çıkarma cezası ve Devlet memurluğundan çıkarma cezası ayrıca Devlet Personel Başkanlığına bildirilir.",
  "Disiplin m.4": "MADDE 4- (1) Disiplinsizlik kasten veya taksirle oluşabilir.\n\nMADDE 4- (2) Aynı fiil nedeniyle bu Kanunda yazılı disiplin cezalarından birden fazlası verilemez. (3) Bir fiilin birden fazla disiplinsizlik teşkil etmesi halinde ağır olan disiplin cezası verilir. (4) Bir fiilin diğer kanunlar kapsamında idari yaptırıma bağlanmış olması, aynı fiile bu Kanun kapsamında disiplin cezası verilmesine engel teşkil etmez.",
  "Disiplin m.5": "MADDE 5- (1) Herhangi bir fiilden dolayı ilgili hakkında yapılan adli soruşturma veya kovuşturma, aynı fiilden dolayı ayrıca disiplin soruşturması ve tahkikat yapılmasını, disiplin cezası verilmesini ve bu cezanın yerine getirilmesini engellemez.",
  "Disiplin m.6": "MADDE 6- (1) Bu Kanun ile disiplin cezası vermeye yetkilendirilen disiplin amirleri veya kurulları, disiplin cezası uygulanması ile ilgili takdir haklarını ölçülü, adaletli ve hakkaniyetli bir şekilde kullanırlar. (2) Takdir hakkı mutlaka gerekçeli olarak kullanılır. (3) Takdir hakkı kullanılırken; a) Disiplinsizliğin işleniş biçimi, b) Disiplinsizliğin işlendiği zaman ve yer, c) Disiplinsizliğin hizmete olumsuz etkisinin ağırlığı, ç) Meydana gelen zarar veya tehlikenin ağırlığı, d) Disiplinsizlik yapan personelin kast veya taksire dayalı kusurunun ağırlığı, e) Disiplinsizlik yapan personelin daha önceki disiplin durumu, f) Disiplinsizlik yapan personelin samimi ikrarı ve gösterdiği pişmanlık, gözönüne alınır. (4) İtiraz üzerine yetkili makamlar tarafından verilen kararlar hariç olmak üzere, hiçbir idari makam tarafından, disiplin cezası ile ilgili takdir hakkının kaldırılması sonucunu doğuran bir karar verilemez veya uygulama yapılamaz.",
  "Disiplin m.7": "MADDE 7- (1) Personele verilecek disiplin cezaları şunlardır: a) Uyarma cezası: (...) yazı ile bildirilmesidir. b) Kınama cezası: (...) kusurlu olduğunun yazı ile bildirilmesidir. c) Aylıktan kesme cezası: (...) zam ve tazminatlar hariç brüt aylığından onbeş günlüğe kadar kesinti yapılmasıdır. ç) Kısa süreli durdurma: Personelin bulunduğu kademede ilerlemesinin dört, altı veya on ay süre ile durdurulmasıdır. d) Uzun süreli durdurma: (...) oniki, onaltı, yirmi veya yirmidört ay süre ile durdurulmasıdır. e) Meslekten çıkarma: Personelin emniyet, jandarma ve sahil güvenlik teşkilatlarında bir daha çalıştırılmamak üzere meslekten çıkarılmasıdır. f) Devlet memurluğundan çıkarma: Personelin bir daha Devlet memurluğuna atanmamak üzere memurluktan çıkarılmasıdır.\n\nMADDE 7- (1) c) Aylıktan kesme cezası: (...) brüt aylığından onbeş günlüğe kadar kesinti yapılmasıdır. ç) Kısa süreli durdurma: Personelin bulunduğu kademede ilerlemesinin dört, altı veya on ay süre ile durdurulmasıdır. d) Uzun süreli durdurma: Personelin bulunduğu kademede ilerlemesinin oniki, onaltı, yirmi veya yirmidört ay süre ile durdurulmasıdır.\n\nMADDE 7- (5) Devlet memurluğundan çıkarma ya da meslekten çıkarma cezalarından başka bir disiplin cezasına çarptırılmış olanlar, uyarma ve kınama cezalarının uygulanmasından başlayarak beş yıl, diğer cezaların uygulanmasından başlayarak on yıl geçtikten sonra, atamaya yetkili amire başvurarak verilmiş olan disiplin cezalarının özlük dosyasından silinmesini isteyebilir. İlgilinin bu süreler içerisindeki davranışları, bu isteğini haklı kılacak nitelikte görülürse söz konusu ceza özlük dosyasından silinir.\n\nMADDE 7- (1) e) Meslekten çıkarma: Personelin emniyet, jandarma ve sahil güvenlik teşkilatlarında bir daha çalıştırılmamak üzere meslekten çıkarılmasıdır. f) Devlet memurluğundan çıkarma: Personelin bir daha Devlet memurluğuna atanmamak üzere memurluktan çıkarılmasıdır.\n\nMADDE 7- (2) Kurumda geçmiş hizmetleri sırasında çalışmaları olumlu bulunan ve iyi veya çok iyi derecede değerlendirme puanı alan personel için verilecek cezalarda bir derece hafif olanı uygulanabilir. (3) Birinci fıkranın (c), (ç) ve (d) bentlerinin uygulanmasında, cezanın üst ve alt kademeleri ağır ya da hafif ceza sayılmaz.",
  "Disiplin m.8": "MADDE 8- (7) (...) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığında, terfileri (...) 926 sayılı (...), 3466 sayılı (...), 3269 sayılı (...) ve (...) 6191 sayılı (...) Kanunu hükümlerine tabi olan personelin; a) Kısa süreli durdurma cezası verilmesini gerektiren hallerde brüt aylıklarının 1/5'i ila 1/4'ü, b) Uzun süreli durdurma cezası verilmesini gerektiren hallerde brüt aylıklarının 1/3'ü ila 1/2'si, kesilir. (8) Yedinci fıkrada yer alan cezalar yetkili disiplin kurullarınca verilir.\n\nMADDE 8- (1) Uyarma cezasını gerektiren fiiller şunlardır: a) Silahını, araç ve gerecini, giyim ve kuşamını temiz tutmamak, çalıştığı yerin temizliğine özen göstermemek. b) Yetkili makamlarca belirlenmiş tasarruf tedbirlerine riayet etmemek veya kullanımına sunulan kamu kaynaklarının kullanılmasında gösterilmesi gereken makul seviyedeki özeni göstermemek. c) İzinsiz veya kurumunca kabul edilebilir özrü olmaksızın belirli zamanda yapılması gereken faaliyetlere geç kalmak. ç) (Mülga). d) Özürsüz veya izinsiz olarak mesaiye geç gelmek veya erken ayrılmak ya da günlük mesai saatlerine riayet etmemek. e) Nezaket kurallarına aykırı tavır ve davranışlarda bulunmak. f) Emrin icrası veya sonuçları ile katılım sağlanan toplantılarla ilgili olarak görevlendirme yapan amire bilgi vermemek. g) Usulüne uygun olarak kendisine verilmiş olan bir emir üzerine; emrin uygun olmadığı, yanlış verildiği, yapılamayacağı ve benzeri şekillerde amirini alenen eleştirmek veya amire karşı itirazda bulunmak (Amir tarafından karar verilene kadar astın fikrini savunması veya emrin kanunsuz olduğu hususundaki kanaatini belirtmek için amire yaptığı itiraz bu kapsamda disiplinsizlik teşkil etmez.).\n\nMADDE 8- (2) Kınama cezasını gerektiren fiiller şunlardır: a) Görev sırasında, mevzuat veya talimatlarla yasaklanan davranışlarda bulunmak. b) Mevzuatta belirlenmiş usul ve kurallara riayet etmeden sözlü, yazılı veya elektronik olarak müracaat veya şikâyette bulunmak. c) Nöbeti teslimden sonra görev yerine özürsüz olarak geç dönmek. ç) Bildirimleri süresi içerisinde yerine ulaştırmamak. d) Mevzuat veya talimatlarla taşınmasına veya bulundurulmasına izin verilmiş olanlar dışında, mesleğin ciddiyeti ile bağdaşmayacak biçimde yüzük, bilezik, kolye, madalyon, rozet ve benzeri şeyleri takmak. e) Görev sırasında veya dışında kendisi ile aynı rütbede çalışanlara veya mesai arkadaşlarına karşı saygısız davranmak. f) Mevzuat ve talimatlarla kendisine tevdi edilmiş görevlerin gerektirdiği sorumluluğu üstlenmekten imtina ettiğini gösterecek tavır ve davranışlarda bulunmak. g) Amirleri, üstleri, aynı rütbedeki veya çalışma arkadaşları hakkında ve onların bulunmadığı ortamlarda, onların kişilikleri hakkında kötüleyici veya konuştuğu kişilerde kötü intiba bırakacak tarzda olumsuz sözler söylemek. ğ) Zati demirbaş tabanca veya geçici olarak verilen demirbaş tabancanın üzerinde orijinalliğini bozacak boya, kaplama, gravür veya ciddiyetle bağdaşmayacak şekil, desen, resim ve karakter gibi değişiklikler yapmak. h) Mevzuata veya mesleki teamüllere aykırı hitaplarda bulunmak. ı) Bu fıkrada disiplinsizlik olarak saptanan eylem, işlem, tutum ve davranışlar dışında herhangi bir biçimde görevin takdir ve yerine getirilmesinde müsamaha ve savsaklama göstermek. i) (Mülga).\n\nMADDE 8- (3) a) Üç günlüğe kadar aylıktan kesme cezasını gerektiren fiiller; 1) Mevzuat veya talimata aykırı olarak eksik kuşam ve teçhizatla göreve çıkmak. 2) Amir ve üstlerinin, görev ve mesleki konulara veya tutum ve davranışlarına ilişkin uyarılarına uymamak ya da bu uyarılara kayıtsız kalmak, amir ve üstleri tarafından sorulan soruları gereken süre içinde yanıtlamamak. 3) Özlük hakları ile ilgili veya başka bir kişisel menfaat temini için başkalarını aracı koyup öncelik ve ayrıcalık talep etmek. 4) İzinsiz veya kurumunca kabul edilebilir bir özrü olmaksızın yirmidört saate kadar göreve gelmemek. 5) Görev dışında amir veya üstlerine saygısız davranmak. 6) Nöbet görevine gelmemek veya nöbet ya da nokta görevinde mevzuatla ve/veya talimatlarla belirlenen kurallara aykırı hareket etmek. 7) Görevli bulunduğu sırada görev gereği olmaksızın veya amirin izni olmadan resmi kıyafet ile kahvehane, kıraathane, lokal, kulüp ve benzeri yerlerde oturmak. 8) Amirinden izin almaksızın görevli bulunduğu il sınırları dışına çıkmak. 9) Emrinde çalışanları veya Devletin araç ve gereçlerini idarece kabul edilebilir bir mazereti olmaksızın özel işlerinde kullanmak. 10) Kendisine verilmiş olan personel kimlik kartını kabul edilebilir bir neden olmaksızın kaybetmek. 11) Bazı isteklerini yerine getirmek, kişisel bir menfaat sağlamak, görev veya sorumluluktan kaçmak gibi amaçlarla hastalığını abartmak veya olmadığı halde bir rahatsızlığı varmış gibi göstererek günlük mesainin bir kısmına katılmamayı alışkanlık haline getirmek. 12) Herhangi bir yolu, yeri veya kişiyi arayıp soranlara cevap vermemek, baştan savmak. 13) Görevde kayıtsızlık göstermek, görevi savsaklamak veya geçerli bir özrü olmaksızın belirtilen sürede bitirmemek. 14) Haklı bir neden olmadan kişileri bekletmek. 15) Selamlama ile ilgili olarak belirlenmiş kurallara riayet etmemek. 16) Resmi protokol kurallarına aykırı tavır ve davranışlarda bulunmak. 17) Görevdeyken, yetkili makamlar tarafından izin verilen durumlar haricinde görev veya hizmetle ilgisi olmayan işlerle uğraşmak. 18) Kılık ve kıyafet ile ilgili olarak mevzuatta belirlenmiş kurallara uymamak.\n\nMADDE 8- (3) b) Dört ila on günlüğe kadar aylıktan kesme cezasını gerektiren fiiller; 1) Kendisi ile aynı rütbede çalışanlara, astlarına veya mesai arkadaşlarına karşı onur kırıcı söz söylemek, davranışta bulunmak veya söz, yazı ya da eylemle hakaret etmek. 2) Resmi belge veya göreve ilişkin evrakı kaybetmek. 3) Önlem almamak veya tedbirli davranmamak yüzünden Devlet malı eşyanın hasar görmesine veya kaybolmasına neden olmak. 4) İzinli olduğu zamanlarda resmi kıyafetle, izinli olmadığı zamanlarda görevli olmaksızın resmi veya sivil kıyafetle, personelin girmesine veya oturup eğlenmesine izin verilen yerler dışındaki kahvehane, lokal, kulüp veya benzeri yerlerde oyun oynamak. 5) İzinsiz veya kurumunca kabul edilebilir bir özrü olmaksızın yirmidört saatten fazla ve iki güne kadar (ikinci gün dahil) göreve gelmemek. 6) Mühür veya beratını kabul edilebilir bir neden olmaksızın kaybetmek. 7) Yükümlü bulunduğu devir ve teslim işlemlerini tamamlamadan ya da devir ve teslim işleri tamamlanamadığı takdirde ilgili mevzuatında belirtilen süre dolmadan görev yerinden ayrılmak. 8) Görevle ilgili resmi belge, araç ve gereçleri görevin sona ermesine ya da kurumca istenmesine rağmen geri vermemek. 9) İzin verilen haller dışında üniforma giymemek.\n\nMADDE 8- (3) c) Onbir ila onbeş günlüğe kadar aylıktan kesme cezasını gerektiren fiiller; 1) İzinsiz veya kurumunca kabul edilebilir bir özrü olmaksızın iki günden fazla ve üç güne kadar (üçüncü gün dahil) görevine gelmemek. 2) İzinli bulunduğu sürede, hizmet ve görevin gerektirdiği durumlarda, görevine derhal dönmesi kendisine sözlü, yazılı ya da herhangi bir iletişim vasıtasıyla duyurulduğu halde, kabul edilebilir özrü bulunmaksızın görevine makul sürede dönmemek. 3) Amir ve üstlerine iletilmesi gereken olay, bilgi ve emirleri zamanında iletmemek. 4) Görev sırasında kişilere karşı onur kırıcı söz söylemek veya davranışta bulunmak. 5) Denetleme ve soruşturmaları uzatmak, denetleme raporları ve soruşturma raporlarını süresinde ilgili yerlere vermemek veya göndermemek ya da kabul edilebilir bir neden olmadan soruşturmayı eksik bırakmak.\n\nMADDE 8- (4) a) Dört ay kısa süreli durdurma cezasını gerektiren fiiller; 1) Amir ve memurlara görevle ilgili olarak yalan söylemek. 2) Denetim görevini yerine getirmemek. 3) İzinsiz ya da kurumca kabul edilebilir özrü olmaksızın kesintisiz olarak üç günden fazla ve beş güne kadar (beşinci gün dahil) göreve gelmemek. 4) Amirlerini, üstlerini, aynı rütbedeki arkadaşlarını, astlarını veya diğer mesai arkadaşlarını haksız yere şikâyet etmek. 5) Astlarını, aynı rütbedeki arkadaşlarını ve diğer mesai arkadaşlarını dövme girişiminde bulunmak. 6) Toplu olarak sözlü veya yazılı şikâyette bulunmak. 7) Görev sırasında amir veya üstlerine saygısız davranmak. 8) Bu Kanunda ayrıca disiplinsizlik olarak tanımlanmamış olmak kaydıyla astları veya mesai arkadaşlarına yönelik olarak sürekli ve sistemli her türlü baskı ve taciz uygulamak.\n\nMADDE 8- (4) b) Altı ay kısa süreli durdurma cezasını gerektiren fiiller; 1) Doğrudan veya aracı eliyle astlarından ya da iş sahiplerinden hediye veya borç almak. 2) Kabul edilebilir mücbir sebepler haricinde borçlanıp ödememeyi alışkanlık haline getirmek. 3) Görevde kullanılan telsiz haberleşme araçlarıyla görevle ilgili olmayan veya saygısızca konuşmalar yapmak ya da anlaşılmaz sesler çıkarmak. 4) Teslim aldığı her çeşit motorlu araç, makine, cihaz ve teçhizatta ağır kusur veya hizmetten ayrılabilen kişisel kusurla hasara sebep olmak. 5) Görev sırasında veya dışında kurumun hiyerarşik düzenini bozacak veya amirin ya da üstlerinin otoritesini zedeleyecek şekilde amir ya da üstlerinin eylem veya işlemlerini olumsuz yönde eleştirici nitelikte söz söylemek ya da yazı yazmak. 6) Hizmet dışında resmi sıfatının gerektirdiği saygınlığı ve güven duygusunu sarsacak eylem ve davranışlarda bulunmak. 7) Bir görevin kendisine tevdi edildiğini öğrendikten sonra mazeretler ileri sürmek suretiyle göreve başlamayı geciktirmek.\n\nMADDE 8- (4) c) On ay kısa süreli durdurma cezasını gerektiren fiiller; 1) Amir ve üstlerine iletilmesi gereken olayları ve bunlarla ilgili bilgileri amirlerinden ve resmen istenmesi halinde görevli ve yetkili kuruluş ve kişilerden gizlemek. 2) Yetkili olmadığı halde basın, haber ajansları, radyo ve televizyon kurumları veya diğer iletişim kanalları vasıtasıyla kamuoyuna bilgi ya da demeç vermek. 3) Silahla dikkatsizlik, tedbirsizlik veya ihmal sonucu yaralamaya sebebiyet vermek, kendisini yaralamak ya da bu fiillerin başkaları tarafından işlenmesine neden olmak. 4) Hizmet aracıyla ağır kusuru veya hizmetten ayrılabilen kişisel kusuruyla trafik kazası sonucu yaralamaya sebebiyet vermek. 5) Aynı rütbedeki meslektaşları ile diğer mesai arkadaşlarını tehdit etmek.\n\nMADDE 8- (5) a) Oniki ay uzun süreli durdurma cezasını gerektiren fiiller; 1) Belirlenen durum ve sürelerde mal bildiriminde bulunmamak veya gerçeğe aykırı bildirimde bulunmak. 2) Görev sırasında kişilere veya herhangi bir nedenle kurum binalarına gelen ya da getirilenlere hakaret etmek.\n\nMADDE 8- (5) b) Onaltı ay uzun süreli durdurma cezasını gerektiren fiiller; 1) Devlet malı motorlu araçları, muhabere araçlarını, silah veya mühimmatı ihmal nedeniyle kaybetmek. 2) Hizmet içinde resmi sıfatının gerektirdiği saygınlığı ve güven duygusunu sarsacak eylem ve davranışlarda bulunmak. 3) Görev sırasında herhangi bir şekilde uyumak veya uyuklamak.\n\nMADDE 8- (5) c) Yirmi ay uzun süreli durdurma cezasını gerektiren fiiller; 1) İzinsiz veya kurumca kabul edilebilir özrü olmaksızın kesintisiz olarak beş günden fazla ve dokuz güne kadar (dokuzuncu gün dahil) görevine gelmemek. 2) Muhafazası veya sevkiyle yükümlü bulunduğu şüpheli, sanık, tutuklu veya hükümlünün uyanık davranmamak ya da önlem almamak yüzünden kaçmasına neden olmak ya da yakalama görevini savsaklamak. 3) Kanunun verdiği yetkiye dayalı olmaksızın spor müsabakalarına dayalı sabit ihtimalli veya müşterek bahis veya şans oyunlarını oynamak.\n\nMADDE 8- (5) ç) Yirmidört ay uzun süreli durdurma cezasını gerektiren fiiller; 1) Silahla dikkatsizlik, tedbirsizlik veya ihmal sonucu ölüme sebebiyet vermek ya da bu fiilin başkaları tarafından işlenmesine neden olmak. 2) Silahla yaralama suçunu kasten işlemek. 3) Meskûn yerlerde, binalarda, herkesin dolaşıp gezebileceği veya oturabileceği yerlerde silah atmak. 4) Amirin usulüne göre verdiği emri yerine getirmemek. 5) Amirin izni olmaksızın görev yerini terk etmek. 6) Kişinin iffetine yönelik söz söylemek, fiil veya harekette bulunmak. 7) Amir veya üste hakaret etmek. 8) Amir veya üstlerini söz, yazı, tutum veya davranışlarıyla küçümsemek. 9) Amir veya üstlerini dövmeye teşebbüs etmek. 10) Amir veya üstlerini sözlü veya fiili olarak tehdit etmek. 11) Göreve ilişkin her türlü yazılı kağıt, belge, mikrofilm aslı veya kopyalarını kasıtlı olarak yok etmek, ortadan kaldırmak ya da belge niteliği taşıyan bilgisayar programlarını, dosyalarını, verilerini hukuka aykırı olarak ele geçirmek, başkasına zarar vermek üzere kullanmak, tahrip etmek, değiştirmek, silmek, sistemin işlemesine engel olmak ya da yanlış biçimde işlemesini sağlamak. 12) Kriptolu telsiz cihazının ve her türlü kriptolu cihazın kaybını veya çalındığını, idarece kabul edilebilir bir mazereti olmaksızın ilgili birime derhal bildirmemek. 13) Hizmet aracıyla ağır kusuru veya hizmetten ayrılabilen kişisel kusuruyla trafik kazası sonucu ölüme sebebiyet vermek.\n\nMADDE 8- (6) Meslekten çıkarma cezasını gerektiren fiiller şunlardır: a) Görevin yerine getirilmesinde dil, ırk, cinsiyet, siyasi düşünce, felsefi inanç, din ve mezhep ayrımı yapmak veya personel arasında bu yolda ayrım yapıcı tutum ve davranışlarda bulunmak. b) Göreve çıkılmaması için propaganda yapmak, kışkırtmak, zorlamak, karar alınmasını sağlamak, alınan bu karara katılmak veya karar uyarınca göreve çıkmamak. c) Amir ya da üstlerinin icraatına karşı çıkmak ve bu hareketi toplu hale dönüştürerek görev yapılmasını ya da göreve çıkılmasını engellemek, buna katılmak, katılmaya tahrik ya da teşvik etmek. ç) Yetkisini veya nüfuzunu kendisine veya başkalarına çıkar sağlamak amacıyla ya da kin ve dostluk gibi nedenlerle kötüye kullanmak. d) Hizmetle ilgili her türlü dosya, kayıt, resmi evrak veya belgeyi ya da örneklerini yetkisiz kişilere vermek, verilmesini emretmek, verilmesine göz yummak. e) Gizli tutulması zorunlu olan ve görev ile ilgili bulunan bilgi ve belgeleri görevli veya yetkili olmayan kişilere açıklamak. f) Muhafazası veya sevkiyle görevli olduğu şüpheli, sanık, tutuklu veya hükümlünün kaçmasına bilerek ve isteyerek imkân vermek. g) Bilerek ve isteyerek suç kanıtlarını yok etmek veya bunların yok olmasına neden olmak, kanıtları silmek, gizlemek, değiştirmek, bozmak veya bu fiillere yardımcı olmak. ğ) Devlet malı araç, gereç, hayvan, silah, mermi ve mühimmatı satmak veya mal edinmek, personel kimlik kartını, araç, gereç, hayvan, silah ve mühimmatı başkalarının kullanımına vermek. h) Kasıtlı olarak gerçek dışı rapor vermek veya tutanak düzenleyip imza etmek veya ettirmek. ı) Görev sırasında yardım isteyen güvenlik görevlilerine haklı bir neden yokken yardımdan kaçınmak veya bildiği ya da gördüğü bir suçun izlenmesi ve suçlunun yakalanması için gerekli girişimde bulunmamak. i) Mesleğin saygınlığını zedeleyecek şekilde uygunsuz yerlere gitmek. j) Görev mahallinde veya görevli bulunduğu sırada alkollü içki içmek veya içilmesine göz yummak. k) Göreve sarhoş veya alkollü içki içtiği belli olacak biçimde gelmek. l) Resmi kıyafetle umuma açık yerlerde alkollü içki içmek veya resmi kıyafetli olarak gizlenemeyecek derecede sarhoş görünmek. m) Uyuşturucu maddeleri yapmak veya kullanmak, bunların yapılmasına, kullanılmasına, saklanmasına, nakledilmesine, yakalanacağı sırada ortadan kaldırılmasına, satılmasına veya satın alınmasına aracı olmak, kullanılmasını kolaylaştırmak ya da özendirmek. n) Kumar oynamak veya oynatmak, kumar oynatanlarla ilişki kurmak. o) Kaçakçılık yapmak veya kaçakçılarla ilişki kurmak. ö) Geliri ile uygun sayılmayacak biçimde yaşadığı ve aşırı harcamada bulunduğu kanıtlanmış olmak ve bunun haklı kaynağını gösterememek. p) 657 sayılı Devlet Memurları Kanunu ile öngörülen grev yasağı kapsamına giren eylemlerde bulunmak. r) Devlet memurları tarafından yapılamayacağı 657 sayılı Kanunda belirtilen kazanç getirici faaliyetlerde bulunmak. s) Siyasi partilerin yararına veya zararına çalışmak ya da siyasal eylemlerde bulunmak, görevli olmaksızın siyasal amaçla yapılacak açık veya kapalı yer toplantılarına ya da gösteri yürüyüşlerine katılmak. ş) İffetsizliği bilinen veya anlaşılmış olan bir kimse ile bilerek evlenmek ya da evlilik bağını devam ettirmek veya böyle bir kimseyi yanında bulundurmak ya da nikahsız olarak devamlı surette yaşamakta ısrar etmek. t) Kanuna aykırı olarak sendikalara üye olmak, sendikaların veya üyesi bulunmadıkları derneklerin yapacakları bilimsel, kültürel ve teknik nitelik taşımayan açık veya kapalı yer toplantılarına ya da gösteri yürüyüşlerine görevli olmaksızın katılmak, açık yer toplantı ve gösteri yürüyüşlerine resmi kıyafetli veya silahlı olarak katılmak ya da üyesi bulundukları derneklerin tüzüklerinde belirtilen amaçları dışındaki çalışmalarını veya bu nitelikteki toplantı ya da gösteri yürüyüşlerini düzenlemek veya bunlara katılmak. u) Görevde kullanılan telsiz, telefon haberleşmesini veya kurum içi iletişim sistemlerini kasıtlı olarak engellemek. ü) Mesleğin onur ve saygınlığını zedeleyici veya amir ya da üstlerinin eylem ve işlemlerini olumsuz yönde eleştirici nitelikte tek başına veya topluca bildiri dağıtmak ya da basın, haber ajansları, radyo ve televizyon kurumları ve diğer iletişim kanalları vasıtasıyla kamuoyuna yönelik bilgi, yazı ve demeç vermek. v) Amir ya da üste karşı itaatsizliğe, mukavemete ya da fiilen taarruza tahrik ya da teşvik etmek. y) Menşei belli olmayan, bulundurulması ve taşınması yasak olan her çeşit silah, mühimmat ve benzerlerini bulundurmak. z) Hukuka aykırı olarak kişiler arasındaki haberleşmenin gizliliğini ihlal etmek, ... kişilerin özel hayatının gizliliğini ihlal etmek, ... kişisel verileri kaydetmek, kişisel verileri bir başkasına vermek, yaymak veya ele geçirmek, ... gerçeğin meydana çıkmasını engellemek amacıyla suç delillerini yok etmek, silmek, gizlemek, değiştirmek veya bozmak, sayılan fiilleri emir vererek yaptırmak. aa) Yetkili olmadığı halde hukuka aykırı olarak elektronik ortamda veya bilgisayar loglarında kişisel verilerle ilgili sorgulama yapmak, bu şekilde elde edilen bilgileri paylaşmak veya yayın yoluyla duyurmak, log kayıtlarını değiştirmek veya silmek. bb) Görevi gereği öğrendiği veya edindiği kişisel bilgi veya belgeleri yetkisiz kişilerle paylaşmak ya da basın ve yayın kuruluşlarına veya diğer iletişim kanallarına vermek. cc) Bir kimseyle gayri tabii mukarenette bulunmak yahut bu fiili kendisine rızasıyla yaptırmak. çç) Görevine, sosyal ve aile yaşantısına zarar verecek derecede menfaatine, içkiye, kumara ve benzeri kötü alışkanlıklara düşkün olmak. dd) Üstlerine, aynı rütbedeki meslektaşları ile diğer mesai arkadaşlarına fiili tecavüzde bulunmak. ee) Görevde kullanılan telsiz haberleşme araçlarıyla amir ya da üstleri hakkında olumsuz yönde eleştirici nitelikte konuşmalar yapmak. ff) Dernek kurmak ya da spor dernekleri dışındaki derneklere üye olmak. gg) Vakıf kurmak veya Bakanlıkça belirlenmiş vakıflardan başka vakıfların organlarında görev almak. hh) Fuhşa teşvik eden, bunun yolunu kolaylaştıran ya da fuhuş için aracılık eden veya yer temin eden kişilerle bilerek ilişki kurmak.",
  "Disiplin m.9": "MADDE 9- (1) Devlet memurluğundan çıkarma cezası uygulanacak fiiller ve bu cezayı verme yetkisi ile ilgili olarak 657 sayılı Kanun hükümleri uygulanır. Ayrıca, aşağıdaki filleri işleyen personel de Devlet memurluğundan çıkarma cezası ile cezalandırılır; a) Ülkenin bağımsızlığını zedelemeye, bütünlüğünü bozmaya ve milli güvenliği tehlikeye düşürmeye yönelik herhangi bir faaliyette bulunmak veya aynı nitelikte faaliyet gösteren herhangi bir harekete, gruplaşmaya, vakıf, dernek ve benzeri teşekküle katılmak, bunlara yardım etmek veya bu yapılarla ilişki içerisinde bulunmak. b) İşkence yapmak.",
  "E-İmza m.3": "Bu Kanunda geçen; a) Elektronik veri: Elektronik, optik veya benzeri yollarla üretilen, taşınan veya saklanan kayıtları, b) Elektronik imza: Başka bir elektronik veriye eklenen veya elektronik veriyle mantıksal bağlantısı bulunan ve kimlik doğrulama amacıyla kullanılan elektronik veriyi, c) İmza sahibi: Elektronik imza oluşturmak amacıyla bir imza oluşturma aracını kullanan gerçek kişiyi, (...) ifade eder.\n\n(...) d) İmza oluşturma verisi: İmza sahibine ait olan, imza sahibi tarafından elektronik imza oluşturmak amacıyla kullanılan ve bir eşi daha olmayan şifreler, kriptografik gizli anahtarlar gibi verileri, (...) f) İmza doğrulama verisi: Elektronik imzayı doğrulamak için kullanılan şifreler, kriptografik açık anahtarlar gibi verileri, (...) h) Zaman damgası: Bir elektronik verinin, üretildiği, değiştirildiği, gönderildiği, alındığı ve / veya kaydedildiği zamanın tespit edilmesi amacıyla, elektronik sertifika hizmet sağlayıcısı tarafından elektronik imzayla doğrulanan kaydı, ı) Elektronik sertifika: İmza sahibinin imza doğrulama verisini ve kimlik bilgilerini birbirine bağlayan elektronik kaydı, j) Kurum: Telekomünikasyon Kurumunu, ifade eder.\" **[GÜNCEL NOT — mevzuat.gov.tr dipnot 1:** 5809 s. Kanun m.65/3 gereği \"Telekomünikasyon Kurumu\" ibaresi bugün **Bilgi Teknolojileri ve İletişim Kurumu (BTK)** olarak anlaşılır; yürürlükteki makam BTK'dır.]",
  "E-İmza m.4": "Güvenli elektronik imza; a) Münhasıran imza sahibine bağlı olan, b) Sadece imza sahibinin tasarrufunda bulunan güvenli elektronik imza oluşturma aracı ile oluşturulan, c) Nitelikli elektronik sertifikaya dayanarak imza sahibinin kimliğinin tespitini sağlayan, d) İmzalanmış elektronik veride sonradan herhangi bir değişiklik yapılıp yapılmadığının tespitini sağlayan, elektronik imzadır.",
  "E-İmza m.5": "Güvenli elektronik imza, elle atılan imza ile aynı hukukî sonucu doğurur. Kanunların resmî şekle veya özel bir merasime tabi tuttuğu hukukî işlemler ile banka teminat mektupları ve Türkiye'de yerleşik sigorta şirketleri tarafından düzenlenen kefalet senetleri dışındaki teminat sözleşmeleri, güvenli elektronik imza ile gerçekleştirilemez.",
  "Hayvanları Koruma m.10": "Satılırken; hayvanların sağlıklarının iyi, barındırıldıkları yerin temiz ve sağlık şartlarına uygun olması zorunludur. (Ek cümle: 9/7/2021-7332/4 md.) Ev hayvanı satış yerlerinde kedi ve köpek bulundurulamaz, ancak buralarda Bakanlıkça izin verilen ev hayvanı üretim yerlerindeki kedi ve köpeklerin satışı yapılabilir. (...) Hayvanların ticarî amaçla film çekimi ve reklam için kullanılması ile ilgili hususlar izne tâbidir. (...) Bir hayvan; acı, ıstırap ya da zarar görecek şekilde, film çekimi, gösteri, reklam ve benzeri işler için kullanılamaz. (...) Hasta, sakat ve yaşlı durumda bulunan veya iyileşemeyecek derecede ağrısı veya acısı olan bir hayvanı usulüne uygun kesmek ya da ağrısız öldürme amacından başka bir amaçla birine devretmek, satmak veya almak yasaktır.",
  "Hayvanları Koruma m.11": "Hayvanları başka bir canlı hayvanla dövüştürmek yasaktır. Folklorik amaca yönelik, şiddet içermeyen geleneksel gösteriler, Bakanlığın uygun görüşü alınarak il hayvanları koruma kurullarından izin alınmak suretiyle düzenlenebilir.",
  "Hayvanları Koruma m.12": "Hayvanların kesilmesi; dini kuralların gerektirdiği özel koşullar dikkate alınarak hayvanı korkutmadan, ürkütmeden, en az acı verecek şekilde, hijyenik kurallara uyularak ve usulüne uygun olarak bir anda yapılır. Hayvanların kesiminin ehliyetli kişilerce yapılması sağlanır. Dini amaçla kurban kesmek isteyenlerin kurbanlarını dini hükümlere, sağlık şartlarına, çevre temizliğine uygun olarak, hayvana en az acı verecek şekilde bir anda kesimi, kesim yerleri, ehliyetli kesim yapacak kişiler ve ilgili diğer hususlar Bakanlık, kurum ve kuruluşların görüşü alınarak, Diyanet İşleri Başkanlığının bağlı olduğu Bakanlıkça çıkarılacak yönetmelikle belirlenir.",
  "Hayvanları Koruma m.13": "Kanunî istisnalar ile tıbbî ve bilimsel gerekçeler ve gıda amaçlı olmayan, insan ve çevre sağlığına yönelen önlenemez tehditler bulunan acil durumlar dışında yavrulama, gebelik ve süt anneliği dönemlerinde hayvanlar öldürülemez.\n\nEk bağlam (m.13 — 7527/2024, başlık \"Hayvanların ötanazisi\"): \"Madde 13- (Ek: 30/7/2024-7527/5 md.) Bakımevine alınan köpeklerden; insan ve hayvanların hayatı ve sağlığı için tehlike teşkil eden ve olumsuz davranışları kontrol edilemeyen, bulaşıcı veya tedavi edilemeyen hastalığı bulunan ya da sahiplenilmesi yasak olanlara (...) 5996 sayılı Kanunun 9 uncu maddesinin üçüncü fıkrasında belirtilen tedbir uygulanır.\" — Not: madde başlığı 7527 ile \"Ötanazi\" oldu; yavrulama/gebelik/süt anneliği koruması bu maddenin sonraki fıkrasıdır. Kart bu koruma fıkrasını esas alır; ötanazi fıkrası olgusal bağlam, ayrı kart açılmaz.",
  "Hayvanları Koruma m.14": "d) Ev (...) hayvanlarını onaltı yaşından küçüklere satmak. (...) ı) Hayvanları hasta, gebelik süresinin 2/3'ünü tamamlamış gebe ve yeni ana iken çalıştırmak, uygun olmayan koşullarda barındırmak.\n\ng) Kesim için yetiştirilmiş hayvanlar dışındaki hayvanları ödül, ikramiye ya da prim olarak dağıtmak. (...) k) Sağlık nedenleri ile gerekli olmadıkça bir hayvana zor kullanarak yem yedirmek, acı, ıstırap ya da zarar veren yiyecekler ile alkollü içki, sigara, uyuşturucu ve bunun gibi bağımlılık yapan yiyecek veya içecekler vermek. l) (Değişik:9/7/2021-7332/5 md.) Bakanlıkça belirlenen tehlike arz eden hayvanları üretmek, sahiplenmek, sahiplendirmek, barındırmak, beslemek, takas etmek, sergilemek, hediye etmek ve bunların ülkemize girişini, satışını ve reklamını yapmak.\n\nj) (Değişik:9/7/2021-7332/5 md.) Hayvanlara cinsel saldırıda bulunmak veya tecavüz etmek. (...) m) (Ek:9/7/2021-7332/5 md.) Hayvanlara işkence yapmak veya acımasız ve zalimce muamelede bulunmak. n) (Ek:9/7/2021-7332/5 md.) Ev hayvanını terk etmek. o) (Ek: 30/7/2024-7527/6 md.) Yerel yönetimler adına toplanan sahipsiz hayvanları bakımevi dışında bir yere terk etmek veya bakımevinde barındırılan köpekleri bakımevi dışında bir yere bırakmak.",
  "Hayvanları Koruma m.20": "Hayvanların korunması ve refahı amacıyla; yaygın ve örgün eğitime yönelik programların yapılması, radyo ve televizyon programlarında bu konuya yer verilmesi esastır. Türkiye Radyo ve Televizyon Kurumu ile özel televizyon kanallarına ait televizyon programlarında ayda en az iki saat, özel radyo kanallarının programlarında ise ayda en az yarım saat eğitici yayınların yapılması zorunludur. Bu yayınların % 20'sinin izlenme ve dinlenme oranı en yüksek saatlerde yapılması esastır. Radyo ve Televizyon Üst Kurulu görev alanına giren hususlarda bu maddenin takibi ile yükümlüdür.",
  "Hayvanları Koruma m.21": "Bir hayvana çarpan ve ona zarar veren sürücü, onu en yakın veteriner hekim ya da tedavi ünitesine götürmek veya götürülmesini sağlamak zorundadır.",
  "Hayvanları Koruma m.22": "İşletme sahipleri ve belediyeler hayvanat bahçelerini, doğal yaşama ortamına en uygun şekilde tanzim etmekle ve ettirmekle yükümlüdürler. (Mülga ikinci cümle: 9/7/2021-7332/10 md.) (Ek ikinci fıkra:9/7/2021-7332/10 md.) Gerçek veya tüzel kişiler, hayvanların etolojisine ve habitatına uygun, serbest dolaşımlarına imkan sağlayan doğal yaşam parkları kurabilir. (Ek üçüncü fıkra:9/7/2021-7332/10 md.) Hayvanat bahçeleri ile doğal yaşam parklarının kuruluşu ile çalışma usul ve esasları Bakanlıkça çıkarılacak yönetmelikle belirlenir.",
  "Hayvanları Koruma m.3": "f) (Değişik: 30/7/2024-7527/2 md.) Sahipsiz hayvan: Sahipli hayvanlar dışında kalan evcil hayvanları, (...) h) Yabani hayvan: Doğada serbest yaşayan evcilleştirilmemiş ve kültüre alınmamış omurgalı ve omurgasız hayvanları, (...) o) Bakanlık: Tarım ve Orman Bakanlığını, (...) ifade eder.\n\nb) Etoloji: Bir hayvan türünün doğuştan gelen, kendine özgü davranışlarını inceleyen bilim dalını, c) Ekosistem: Canlıların kendi aralarında ve cansız çevreleriyle ilişkilerini bir düzen içinde yürüttükleri biyolojik, fiziksel ve kimyasal sistemi, (...) g) Güçten düşmüş hayvan: Bulaşıcı ve salgın hayvan hastalıkları haricinde yaşlanma, sakatlanma, yaralanma ve hastalanma gibi çeşitli nedenlerle fizikî olarak iş yapabilme yeteneğini kaybetmiş binek ve yük hayvanlarını, (...) l) Deney: Herhangi bir hayvanın acı, eziyet, üzüntü veya uzun süreli hasara neden olacak deneysel ya da diğer bilimsel amaçlarla kullanılmasını, m) Deney hayvanı: Deneyde kullanılan ya da kullanılacak olan hayvanı, n) Kesim hayvanı: Gıda amaçlı kesimi yapılan hayvanları, (...) ifade eder.",
  "Hayvanları Koruma m.4": "k) Kontrolsüz üremeyi önlemek amacıyla, toplu yaşanan yerlerde beslenen ve barındırılan kedi ve köpeklerin sahiplerince kısırlaştırılması esastır. (Değişik ikinci cümle: 9/7/2021-7332/2 md.) Kedi ve köpek sahipleri, hayvanlarını dijital kimliklendirme yöntemleriyle kayıt altına aldırmakla yükümlüdürler. (Ek cümle: 9/7/2021-7332/2 md.) Dijital kimliklendirme yöntemlerine ilişkin usul ve esaslar Bakanlıkça yürürlüğe konulacak yönetmelikle belirlenir.\n\na) Bütün hayvanlar eşit doğar ve bu Kanun hükümleri çerçevesinde yaşama hakkına sahiptir. c) Hayvanların korunması, gözetilmesi, bakımı ve kötü muamelelerden uzak tutulması için gerekli önlemler alınmalıdır. d) Hiçbir maddî kazanç ve menfaat amacı gütmeksizin, sadece insanî ve vicdanî sorumluluklarla, sahipsiz ve güçten düşmüş hayvanları sahiplenmek isteyen ve bu Kanunda öngörülen koşulları taşıyan gerçek ve tüzel kişilerin teşviki ve bu kapsamda eşgüdüm sağlanması esastır. e) Nesli yok olma tehlikesi altında bulunan tür ve bunların yaşama ortamlarının korunması esastır. f) Yabani hayvanların yaşama ortamlarından koparılmaması, doğada serbestçe yaşayan bir hayvanın yakalanıp özgürlükten yoksun bırakılmaması esastır. g) Hayvanların korunması ve rahat yaşamalarının sağlanmasında; insanlarla diğer hayvanların hijyen, sağlık ve güvenlikleri de dikkate alınmalıdır. h) Hayvanların türüne özgü şartlarda bakılması, beslenmesi, barındırılma ve taşınması esastır. ı) Hayvanları taşıyan ve taşıtanlar onları türüne ve özelliğine uygun ortam ve şartlarda taşımalı, taşıma sırasında beslemeli ve bakımını yapmalıdırlar. j) (Değişik:9/7/2021-7332/2 md.) Yerel yönetimler, gönüllü kuruluşlarla iş birliği içerisinde, sahipsiz hayvanların sahiplendirilinceye kadar bakılmaları için hayvan bakımevleri kurarak onların bakımlarını ve tedavilerini sağlar ve eğitim çalışmaları yapar. Ayrıca yerel yönetimler, ilgili karar organının uygun görmesi halinde hayvan hastanesi kurar.\" — Not: (b) bendi 30/7/2024-7527/3 md. ile mülga.",
  "Hayvanları Koruma m.5": "Bir hayvanı, (…) sahiplenen (…) kişi, hayvanı barındırmak, hayvanın türüne ve üreme yöntemine uygun olan etolojik ihtiyaçlarını temin etmek, sağlığına dikkat etmek, insan, hayvan ve çevre sağlığı açısından gerekli tüm önlemleri almakla yükümlüdür. Hayvan sahipleri, sahip oldukları hayvanlardan kaynaklanan çevre kirliliğini ve insanlara verilebilecek zarar ve rahatsızlıkları önleyici tedbirleri almakla yükümlü olup; zamanında ve yeterli seviyede tedbir alınmamasından kaynaklanan zararları tazmin etmek zorundadırlar. Ev (…) hayvanı satan kişiler, bu hayvanların bakımı ve korunması ile ilgili olarak yerel yönetimler tarafından düzenlenen eğitim programlarına katılarak sertifika almakla yükümlüdürler. (…) Ticarî amaç güdülmeden (…) bakılan ev (…) hayvanları sahiplerinin borcundan dolayı haczedilemezler.",
  "Hayvanları Koruma m.6": "Sahipsiz ya da güçten düşmüş hayvanların kanuni istisnalar hariç öldürülmeleri yasaktır. Güçten düşmüş hayvanlar ticarî ve gösteri amaçlı veya herhangi bir şekilde binicilik ve taşımacılık amacıyla çalıştırılamaz.\n\nSahipsiz veya güçten düşmüş hayvanların en hızlı şekilde yerel yönetimlerce kurulan veya izin verilen hayvan bakımevlerine götürülmesi zorunludur. Bu hayvanların öncelikle söz konusu merkezlerde oluşturulacak müşahede yerlerinde tutulması sağlanır. (Değişik son cümle: 30/7/2024-7527/4 md.) Bakımevlerine alınan hayvanlar Bakanlık veri sistemine kaydedilir ve rehabilite edilen köpekler, sahiplendirilinceye kadar hayvan bakımevlerinde barındırılır.",
  "Hayvanları Koruma m.7": "Hayvanlara tıbbî ve cerrahi müdahaleler sadece veteriner hekimler tarafından yapılır. Kontrolsüz üremenin önlenmesi için, hayvanlara acı vermeden kısırlaştırma müdahaleleri yapılır.",
  "Hayvanları Koruma m.8": "Bir hayvan neslini yok edecek her türlü müdahale yasaktır. Hayvanların, yaşadıkları sürece, tıbbî amaçlar dışında organ veya dokularının tümü ya da bir bölümü çıkarılıp alınamaz veya tahrip edilemez. Ev (...) hayvanının dış görünüşünü değiştirmeye yönelik veya diğer tedavi edici olmayan kuyruk ve kulak kesilmesi, ses tellerinin alınması ve tırnak ve dişlerinin sökülmesine yönelik cerrahi müdahale yapılması yasaktır. Ancak bu yasaklamalara; bir veteriner hekimin, veteriner hekimliği uygulamaları ile ilgili tıbbî sebepler veya özel bir hayvanın yararı için gerektiğinde tedavi edici olmayan müdahaleyi gerekli görmesi veya üremenin önlenmesi durumlarında izin verilebilir. Bir hayvana tıbbî amaçlar dışında, onun türüne ve etolojik özelliklerine aykırı hale getirecek şekilde ve dozda hormon ve ilaç vermek, çeşitli maddelerle doping yapmak, hayvanların türlerine has davranış ve fizikî özelliklerini yapay yöntemlerle değiştirmek yasaktır.",
  "Hayvanları Koruma m.9": "Hayvanlar, bilimsel olmayan teşhis, tedavi ve deneylerde kullanılamazlar. (...) Başkaca bir seçenek olmaması halinde, hayvanlar bilimsel çalışmalarda deney hayvanı olarak kullanılabilir. Hayvan deneyi yapan kurum ve kuruluşlarda bu deneylerin yapılmasına kendi bünyelerinde kurulmuş ve kurulacak etik kurullar yoluyla izin verilir. Etik kurulların kuruluşu, çalışma usul ve esasları, (…) Sağlık Bakanlığının ve ilgili kuruluşların görüşleri alınarak Bakanlıkça çıkarılacak yönetmelikle belirlenir.",
  "Hizmet Esasları Yön m.1": "MADDE 1 - (1) Bu Yönetmeliğin amacı; yürütülen görevlerin icrası esnasında ve görev dışı zamanlarda Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisi personelinin uyması gereken kuralları, sahip olması gereken vasıfları ve muhtelif görevlerin icra tarzını belirlemektir. MADDE 2 - (1) Bu Yönetmelik, Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisindeki karargâh, birlik ve kurumlar ile buralarda görev yapan personeli kapsar. (...) MADDE 3 - (1) Bu Yönetmelik, 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 24'üncü maddesine ve 9/7/1982 tarihli ve 2692 sayılı Sahil Güvenlik Komutanlığı Kanununun 23'üncü maddesine dayanılarak hazırlanmıştır.",
  "Hizmet Esasları Yön m.10": "(1) Emir tüm görevlerin düzenleyicisidir. (2) Emirlerin, göreve ilişkin ve mevzuata uygun olması şarttır. (3) Ast emri; Anayasa ve mevzuat hükümlerine aykırı görürse, yerine getirmez ve bu aykırılığı o emri verene bildirilir. Ancak, âmir emrinde ısrar ederse ve bu emrini yazı ile yinelerse, emir yerine getirilir. Emrin yerine getirilmesinden doğacak sorumluluk emri verene aittir. Ancak, durum emri veren âmirin bir üst âmirine bildirilir. (4) Konusu suç teşkil eden emir hiçbir surette yerine getirilmez; yerine getiren kimse sorumluluktan kurtulamaz.\n\n(5) Emrin yazılı, sözlü veya sair usullerle verilme takdiri, âmire aittir. (...) (7) Emirler, kural olarak birbirine bağlı âmirler tarafından, silsile ile verilir. Ancak, acele ve zorunlu hallerde bu sıraya riayet edilmeden de emir verilebilir. Bu takdirde emri veren âmir, atlanan kademelere en kısa zamanda bilgi verir. Böyle bir emri alan maiyet de âmirini haberdar eder. (...) (9) Emir, net ve anlaşılır olmalıdır. (...) (11) Emirde kararlılık esastır. Verilen emir, mecburi sebepler oluşmadıkça veya gerekliliği ortadan kalkmadıkça değiştirilemez veya yok sayılamaz.",
  "Hizmet Esasları Yön m.11": "(1) Personel, kurumlarıyla ilgili resmi ve şahsi işlerinden dolayı müracaat; amirleri veya kurumları tarafından kendilerine uygulanan idari eylem ve işlemlerden dolayı şikâyet ve dava açma hakkına sahiptir. (2) Personelin, aynı konu ve şahısla ilgili, toplu olarak söz veya yazı ile müracaatı yasaktır. Aynı olay birden fazla personelin şikâyetine sebep veya konu olursa bunların her biri ayrı ayrı veya yalnız başına şikâyet hakkını kullanabilir. (3) Şikâyetleri incelemeye yetkili olan âmirler, bizzat şikâyeti neticelendirirler. (...) (4) Âmirin yüzüne karşı kendisini şikâyet etmek, âmirinden şikâyetçi olacağını söyleyerek dedikodu yapmak cezayı muciptir.",
  "Hizmet Esasları Yön m.14": "(1) İznin maksadı, personelin dinlenmesi, gücünü toplaması, yenilenmiş güçle göreve tekrar dönmesinin sağlanması ve bazı şahsi ihtiyaçlarını görmesidir. (2) İzinler; göreve ve mümkün olduğunca personelin talep edeceği aylara göre önceden planlanmalı (...). (3) Âmir, açıkça olmasa da, personelin izin hakkından gönüllü olarak feragat etmesine yönelik tavır, davranış ve imada bulunmamalıdır. (...) (5) İzne giden her personel, ayrılmadan evvel kendi birlik veya kurum âmirine gideceği yerdeki adresini ve iletişim araçlarını bildirmeli, izinden çağrılmayı gerektirecek hallerin varlığı halinde ise kendisini ulaşılabilir kılmalıdır. (6) İzin yılı, her senenin ilk ayından itibaren başlar (...).",
  "Hizmet Esasları Yön m.15": "(1) Personelin kılık ve kıyafetlerinin uygun olması kendilerine, ait olduğu kuruma, mesleklerine ve topluma saygılarının bir ifadesidir. (2) Rütbeli personel ve erlerin görev sırasında resmî kıyafetli olması esastır. (...) (7) Rütbeli personel ve erlerin hangi görevlerde sivil kıyafet giyebileceği, görevin mahiyetine göre yetkili makamlarca tespit edilir. (8) Rütbeli personel ve erler; tanıklık veya bilirkişilik dışında, adlî yargı makam ve mercilerine çağrıldığında, tutuklu veya hükümlü iken veya görevden uzaklaştırıldıkları süre içerisinde resmî kıyafet giyemez. (...) (10) Kimlik kartı, kişinin jandarma veya sahil güvenlik personeli olduğunu gösteren resmî bir belgedir. Personel, (...) çeşitli istisnai durumlar dışında, kimlik kartını resmî ve sivil olarak her zaman üzerinde bulundurmak zorundadır.\n\n(9) Kılık ve resmî kıyafet konusunda dikkat edilecek hususlar şunlardır: a) Resmi kıyafet ile görev amacı saklı kalmak üzere toplumun genel ahlak anlayışı ile örtüşmeyen yer ve alkollü mekânlara gidilmez. b) Resmî kıyafet ile sakız çiğnenmez, poşet taşınmaz, şapka çıkarılmaz, kol kola girilmez, el ele tutuşulmaz, ağızda sigara veya eller cepte dolaşılmaz. (...) c) (...) Hak sahibi olunmayan veya mevzuatta belirtilen özelliklere uymayan şerit rozet ve bröveler takılmaz. ç) Resmî kıyafet ile nişan, evlilik ve devre yüzüğü dışında yüzük, bileklik ve kolye kullanılmaz. d) Pantolon kemerine veya palaskaya cep telefonu, gözlük, çakı takımı, sigaralık vb. aksesuar/malzeme takılmaz. (...) e) Bina ve müştemilatı ile araç dışında, görevin özelliğine göre şapka, kep, bere veya örgü başlık giyilmesi zorunludur. (...) f) Araç içinde resmî kıyafetli olarak yolculuk yaparken şapka çıkarılabilir. g) Resmî kıyafet ütülü, gömlek üst düğmesi ilikli ve kravat (...) ortalamış şekilde kullanılır. (...) ı) (...) resmî kıyafetler sivil kıyafete dönüştürülerek kullanılamaz. (...) m) Kadın rütbeli personel, hamileliğini belgelediği takdirde sivil kıyafet ile görev yapabilir. (...) o) (...) ilişiği kesildiği tarihten itibaren resmî kıyafetini çıkarmaya mecburdur. ö) El, yüz ve saç tuvaletlerinde sadelik esastır. (...)",
  "Hizmet Esasları Yön m.17": "(1) Esas duruş, rütbeli personel ve erlerin ruhen ve bedenen olgunluk ve göreve hazırlık derecesini gösterir ve günlük görevlerin her safhasında aranır. (2) Âmir veya üst, astın veya astların bulunduğu yere gelir ise derhal ayağa kalkılır ve esas duruşa geçilir. Âmir otur veya rahat komutunu vermeden esas duruş bozulmaz. (...) (5) Esas duruşta sessiz kalınır ve aksi emredilmedikçe kımıldanılmaz. (...) (7) Devlet memurları esas duruşa geçmez. Ancak amirleri karşısında saygılı bir duruş sergilemek zorundadır.",
  "Hizmet Esasları Yön m.18": "(1) Selam ve selamlama; saygının, sevginin, birlik ve beraberliğin, aidiyet duygusunun, içtenlik ve bağlılığın bir sembolü ve göstergesidir. Küçüğün büyüğü selamlaması saygının, büyüğün küçüğü selamlaması sevginin, aynı seviyede olanların birbirini selamlaması ise nezaket ve muhabbetin belirtisidir. (...) (3) Astlar, üstlerden önce selam vermek zorundadır. (...) Üst veya âmir selamlamayı bitirmeden ast selamlamayı bitiremez. (...) (5) Selamlama gecikmiş bile olsa yapılır, görmemek mazeret teşkil etmez. (...) (8) Elle selamlama, başta şapka, kayık kep, bere, kar başlığı, çelik/fiber başlık bulunduğunda ve sağ el ile yapılır. (...) (16) Devlet memurları selamlama ile ilgili hususlardan muaftır. Ancak, amirlerine karşı saygılı duruşunu muhafaza etmekle mükelleftir.",
  "Hizmet Esasları Yön m.19": "(4) Her personelde bulunması lazım gelen ahlaki ve manevi vasıflar şunlardır: a) Cumhuriyete, yurda ve millete karşı sevgi ve bağlılık (...) b) İtaat: Mevzuat ile emirlerin gösterdiğinden dışarı çıkmamak ve yasak edilen şeyleri yapmamaktır. c) Sebat ve mukavemet (...) ç) Cesaret ve şecaat (...) Korkaklık; personel için en büyük ve affedilmeyecek kusurdur. d) Canını esirgememek (...) e) Göreve hazırlık (...) f) İyi geçinmek (...) g) İyi ahlâk sahibi olmak (...) ğ) Sır saklamak (...) h) Emel ve fikir birliği (...) ı) Birbirine yardım (...) i) Tavır ve hareket (...) j) İntizam severlik: Personel, görevini muntazam işleyen bir saat gibi dakikası dakikasına yapmayı adet haline getirmelidir. k) Temsil ve tanıtım (...)",
  "Hizmet Esasları Yön m.22": "(1) Personel, tek başına veya topluca bildiri dağıtamaz, kamu görevleri hakkında basına, haber ajanslarına, radyo ve televizyon kurumlarına veya diğer iletişim kanallarına bilgi, yazı ve demeç veremez. Bu konuda gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir. (2) Personel, görevi gereği öğrendiği veya edindiği kişisel bilgi veya belgeleri yetkisiz kişilerle paylaşamaz (...). (4) Personel, gazete ve dergilere, internet ve sosyal medya vasıtalarına iç ve dış siyaset hakkında yazı yazamaz, Hükümet ve meslek aleyhinde tenkitte bulunamaz (...). (5) Personel, siyaset hariç olmak üzere, özellikle bilimsel, tarihi, iktisadi, içtimai, edebi bir zemin üzerinde gazete ve dergilere makaleler göndermekte (...) serbesttir.",
  "Hizmet Esasları Yön m.23": "(1) Birden fazla birliğin aynı kışla içinde bulunduğu yerlerde en kıdemli birlik komutanı, karargâh veya kurum âmiri kışla komutanıdır. (2) Kışla Komutanının görevleri şunlardır: a) Birliklerin sınırlarını ve sorumluluk alanlarını ayırır ve birliklere bildirir. (...) b) Emniyet, intizam ve disiplin bakımından gereken tedbirleri alır. (...) c) Yasak edilen malzemelerin kışlaya sokulmasını engeller. ç) Müşterek görevlerin icrasını planlar ve uygular. (...) ğ) Kışlaya giriş ve çıkışların kontrollü yapılmasını sağlar. (...)",
  "Hizmet Esasları Yön m.24": "(1) Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisinde görevli subay, sözleşmeli subay, astsubay, sözleşmeli astsubay ve uzman jandarmaların haftalık çalışma süresi genel olarak 40 saattir. Bu durum, görevin gerektirdiği durumlarda, rütbeli personelin görev yerine çağrılmasına veya görev yerinden ayrılmamasına engel teşkil etmez. (2) Günün yirmi dört saatinde devamlılık gösteren görevlerde çalışan rütbeli personelin çalışma saat ve şekilleri birlik komutanları veya birim âmirlerince belirlenir. (3) Nöbetçi ve görevli olmayan (...) günlük mesai veya eğitimin bitiminde görev yerinden ayrılabilir. Ancak nöbete ilişkin hükümler saklıdır.",
  "Hizmet Esasları Yön m.26": "MADDE 26 - (1) Birliklerdeki müşterek görevlerin yapılmasını ve devamını, bu görevlerin belli bir sıra ve süreyle; personel tarafından yerine getirilmesini sağlamak maksadıyla nöbet görevi ihdas edilir. (...) MADDE 27 - (1) Hâl ve vaziyetin gerektirdiği zamanlarda, birlik emniyetini sağlamak amacıyla, her birlik ve karargâhta derhal kullanılmak üzere rütbeli personel ve erlerden oluşan bir hazır kıt'a bulundurulur. (2) Hazır kıt'a kendisine gösterilen yerde gece dahi tam teçhizatlı, silahlı ve giyimli olarak harekete hazır bulunur. (...) (3) Hazır kıt'anın teşkil edileceği zaman ve kuvveti ihtiyaca göre birlik komutanı belirler. Bu kıt'anın kuvveti en az üç kişiden birliğin tamamına kadar olabilir. (...)",
  "Hizmet Esasları Yön m.34": "MADDE 34 - (1) Bu Yönetmelik onaylandığı tarihte yürürlüğe girer. MADDE 35 - (1) Bu Yönetmelik hükümleri Bakan tarafından yürütülür.",
  "Hizmet Esasları Yön m.5": "(1) Personel, her durumda Devletin menfaatlerini korumak mecburiyetindedir. Türkiye Cumhuriyeti Anayasasına ve kanunlarına aykırı olan, memleketin bağımsızlığını ve bütünlüğünü bozan, Türkiye Cumhuriyetinin güvenliğini tehlikeye düşüren herhangi bir faaliyette bulunamaz. (2) Personel, ettiği yemine uygun hareket etmek zorundadır. Personel, yetkili âmirlerin huzurunda mevzuatta belirtildiği şekilde ant içerek göreve başlar. (...)",
  "Hizmet Esasları Yön m.6": "(1) Subaylar, diğer rütbeli personelin üstüdür. (2) Astsubaylar, subayların astı diğer rütbeli personelin üstüdür. (3) Uzman jandarmalar, subay ve astsubayların astı, diğer rütbeli personelin üstüdür. (4) Uzman erbaşlar, subay, astsubay ve uzman jandarmaların astı, emsal rütbedeki sözleşmeli erbaşların ve 7179 sayılı Kanuna göre askerlik yükümlüsü olan emsal rütbedeki erbaşların üstüdür. (5) Sözleşmeli erbaşlar, (...) emsal rütbedeki uzman erbaşların astı, 7179 sayılı Kanuna göre askerlik yükümlüsü olan emsal rütbedeki erbaşların üstüdür. (6) Devlet memurları ile rütbeli personel arasında bir astlık-üstlük ilişkisi bulunmamakla birlikte (...) amir-maiyet ilişkisi vardır.",
  "Hizmet Esasları Yön m.7": "(1) Disiplin, Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı, Jandarma ve Sahil Güvenlik Akademisinin temelidir ve hiçbir suretle disiplinden taviz verilemez. (2) Personel görevini yerine getirirken ast-üst ve amir-maiyet ilişkisi içerisinde hareket etmekten, görev, nöbet, selamlama, kılık ve kıyafet gibi disiplinin ayrılmaz unsurlarına ilişkin mevzuat hükümlerine, disiplin kurallarına ve emirlere uymak zorundadır. (...) (7) Disiplin, en zor zamanlarda bile uygulanacak şekilde tesis edilmelidir. (...) (10) Sevk ve idarede otoritenin, öncelikle bilgi, yetenek ve yüksek bir karakter ile sağlanması esastır.",
  "Hizmet Esasları Yön m.8": "(1) Ast, âmir ve üstlerine genel görgü ve disiplin kurallarına uygun tam bir saygı göstermekle, resmî kıyafetli olsun veya olmasın âmirlerinin, usulüne uygun emirlerini tam, zamanında, değiştirmeden ve eksiksiz olarak yerine getirmekle, görevini kusursuz icra etmekle (...) yükümlüdür. (2) Görevini; korku ile değil, sevgi ve üstün görev anlayışı ile icra eder. Âmirin mevzuata uygun şekilde verdiği her emri mutlak itaat anlayışıyla, bütün tahammül kuvvetini sarf ederek yapar. (...) (5) Aldığı bir emirden dolayı âmirine mütalâada bulunmaz. Bir emri alırken veya aldıktan sonra mırıldanmaz, doğru bulmadığını sezdirecek hal ve harekette bulunmaz. (...) (14) Devlet memurları bu maddede maiyete yüklenen görevleri yapar.",
  "Hizmet Esasları Yön m.9": "(1) Tüm görevleri mevzuata uygun, zamanında ve eksiksiz yapar veya yaptırır, disiplini tesis ve idame eder, maiyetini yetiştirir, hal ve hareketlerini takip ve kontrol eder. (2) Maiyetinin sağlık, özlük ve sosyal haklarını sürekli gözetir. (...) (5) Astlarına karşı adil ve hakkaniyetli hareket eder. Hiçbir mazeret, hukuk ve adaletten ayrılmaya gerekçe gösterilemez. (...) (7) Görevine sadakati, gayreti, dürüstlüğü, güzel ahlâkı, tecrübesi ve hukuk kurallarına riayeti ile astlarına örnek olur. (...) (10) Maiyetinin katlandığı her türlü zahmet ve mahrumiyete, fiziki imkân nispetinde beraber katlanır, bir kolaylık çıkınca bunlardan istifade için nefsini sona bırakır ve bir zorluk çıkınca bilâkis öne atılmayı şerefli bir görev kabul eder.",
  "İkramiye Yön m.3": "Madde 3 — Türkiye Cumhuriyeti sınırları içinde yerüstünde, yeraltında ve sualtında taşınır kültür ve tabiat varlığı bulunduğunu bilenler veya varlığından yeni haberdar olan malik veya zilyetlerden; bunu en geç üç gün içinde en yakın müzeye, köyde muhtara veya diğer yerlerde mülki idare amirlerine haber verenlere; (...)\n\na) Varlık, bulanın mülkü içinde ise; (...) tespit edilecek değeri usulüne göre ödenerek müzelerce satın alınır. Ayrıca ikramiye verilmez. b) Varlık başkasının mülkü içinde ise ilgili Yönetmeliğine göre takdir edilecek bedelin %80'i ikramiye olarak bulan ile mülk sahibi arasında eşit olarak paylaştırılır. c) Varlık Devlete ait arazide bulunmuş ise, ilgili Yönetmeliğine göre takdir olunacak bedelin %40'ı bulana ikramiye olarak ödenir.\n\nd) Nerede bulunursa bulunsun haber verilen varlık, korunması gerekli nitelikte kültür ve tabiat varlığı olmadığı takdirde sahiplerine, müzelerce verilecek bir belge ile iade olunur. Bu belge iade olunan varlık ile sahibini açıkça tanımlayabilecek nitelikte düzenlenir. Belge ile iade olunan varlıklar üzerinde sahipleri her türlü tasarrufta bulunabilirler. Bir yıl içinde sahiplerince alınmayan varlıklar müzelerde saklanabilir veya usulüne uygun olarak Devletçe satılabilirler.",
  "İkramiye Yön m.4": "Madde 4 — (...) süresi içinde haber verilmediğinden gizlenmiş sayılan varlıkları haber verenler ile, bunları yakalayan kamu görevlilerine usulüne göre tespit edilen değerin, 1905 sayılı (...) Kanunda belirlenen şekilde: a) 5.000 liraya kadar %30, b) 25.000 liraya kadar (5.000 liradan yukarı olan kısmı için) %25, c) 50.000 liraya kadar (25.000 liradan yukarı olan kısmı için) %15, d) 100.000 liraya kadar (50.000 liradan yukarı kısmı için) %10, e) 100.000 liradan yukarı olan kısmı için %7,5 (...)\n\n(...) Oranlarındaki miktarı, haber veren ve yakalayan şahıslara ayrı ayrı ikramiye olarak ödenir. Gerek haber verenler ve gerekse yakalayan kamu görevlilerinin birden fazla olmaları halinde hesap edilen ikramiye aralarında eşit olarak paylaştırılır.",
  "İkramiye Yön m.5": "Madde 5 — Taşınmaz kültür ve tabiat varlıkları ile, nerede bulunursa bulunsun varlığı Bakanlıkça daha önceden bilinen taşınır kültür ve tabiat varlıkları için ihbar ikramiyesi ödenmez.",
  "İl İdaresi m.11": "A) Vali, il sınırları içinde bulunan genel ve özel bütün kolluk kuvvet ve teşkilatının amiridir. Suç işlenmesini önlemek, kamu düzen ve güvenini korumak için gereken tedbirleri alır. Bu maksatla Devletin genel ve özel kolluk kuvvetlerini istihdam eder, bu teşkilat amir ve memurları vali tarafından verilen emirleri derhal yerine getirmekle yükümlüdür.\n\nVali, kamu düzeni veya güvenliğinin olağan hayatı durduracak veya kesintiye uğratacak şekilde bozulduğu ya da bozulacağına ilişkin ciddi belirtilerin bulunduğu hâllerde on beş günü geçmemek üzere ildeki belirli yerlere girişi ve çıkışı kamu düzeni ya da kamu güvenliğini bozabileceği şüphesi bulunan kişiler için sınırlayabilir; belli yerlerde veya saatlerde kişilerin dolaşmalarını, toplanmalarını, araçların seyirlerini düzenleyebilir veya kısıtlayabilir ve ruhsatlı da olsa her çeşit silah ve merminin taşınması ve naklini yasaklayabilir.\n\nD) Valiler, ilde çıkabilecek veya çıkan olayların, emrindeki kuvvetlerle önlenmesini mümkün görmedikleri veya önleyemedikleri; aldıkları tedbirlerin bu kuvvetlerle uygulanmasını mümkün görmedikleri veya uygulayamadıkları takdirde, diğer illerin kolluk kuvvetleriyle bu iş için tahsis edilen diğer kuvvetlerden yararlanmak amacıyla, İçişleri Bakanlığından ve gerekirse (…) Kara Kuvvetleri Komutanlığının sınır birlikleri dahil olmak üzere en yakın kara, deniz ve hava birlik komutanlığından mümkün olan en hızlı vasıtalar ile müracaat ederek yardım isterler. (...) Valinin yaptığı yardım istemi geciktirilmeksizin yerine getirilir. Acil durumlarda bu istek sonradan yazılı şekle dönüştürülmek kaydıyla sözlü olarak yapılabilir.\n\nF) Valiler, halkın askerlik muameleleri hakkındaki müracaat ve şikayetlerini kabul ederler. Askerlik şubelerine ve dairelerine yazarlar. Cevabı kafi görmedikleri takdirde askerlik şubelerinin bağlı bulunduğu bölge, tümen veya korkomutanlıklarına ve Milli Savunma Bakanlığına müracaat ederler. Bu makamlar tarafından lazımgelen soruşturma yapılarak kanuni gereği ifa edilir ve sonucundan valilere bilgi verilir.\n\nG) Vali, lüzumu hâlinde, kolluk amir ve memurlarına suç faillerinin bulunması için gereken emirleri verebilir. Kolluk bu emirleri, mevzuatta belirlenen usule uygun olarak yerine getirir. H) Vali, kamu düzenini ve güvenliğini veya kişilerin can ve mal emniyetini sağlamak amacıyla aldığı tedbir ve kararların uygulanması için adli kuruluşlar ile (D) fıkrası hükmü saklı kalmak kaydıyla askeri kuruluşlar dışında, mahalli idareler dâhil bütün kamu kurum ve kuruluşlarının itfaiye, ambulans, çekici, iş makinesi ve tedbirlerin zorunlu kıldığı diğer araç ve gereçlerinden yararlanabilir, personeline görev verebilir. Kamu kurum ve kuruluşları, valinin bu konudaki emir ve talimatlarını yerine getirmek zorundadır. Aksi takdirde vali, emir ve talimatlarını kolluk aracılığıyla uygular. (...) I) (H) fıkrası ile valiye verilmiş olan yetkiler, ilçede kaymakam tarafından da kullanılabilir.\n\nJ) Genel kolluk kuvvetlerinin imkân ve kabiliyetlerini aşan durumlarda terörle mücadele için gerekli olması veya terör eylemlerinin kamu düzenini ciddi şekilde bozması hâlinde, İçişleri Bakanlığının teklifi üzerine Cumhurbaşkanı kararıyla Türk Silahlı Kuvvetleri görevlendirilebilir. Cumhurbaşkanı kararında; görevin kapsam ve süresi, görev alanı, istihbarat yetkisinin kapsamı, destek silahlarının kullanımına yönelik tahditler, görevlendirilen birliklerin mülki amirler ve genel kolluk kuvvetleri ile ilişkileri (...) gösterilir. (...) Askeri birliklerin belirli görevleri genel kolluk kuvvetleriyle birlikte yapması hâlinde komuta, sevk ve idare askeri birliklerin en kıdemli komutanı tarafından üstlenilir. (...) gecikmesinde sakınca bulunan hallerde güvenlik kuvvetlerinin elinden kaçmakta olan kişilerin izlenirken girdikleri konuta, işyerine veya kamuya açık olmayan kapalı alanlar ile bunların eklentilerine (...) yetkili birlik komutanının yazılı emriyle girilebilir. Birlik komutanının kararı yirmi dört saat içinde hâkim onayına sunulur.",
  "İl İdaresi m.18": "Valiler, vali muavini ile kaymakamların, il idare şube başkanlarının ve il ve bölge muhakemat müdürlerinin, genel ve özel kolluk amirlerinin birinci derecede, diğer memurların ikinci derecede sicil amiridirler.",
  "İl İdaresi m.2": "İl, ilçe ve bucak kurulması, kaldırılması, adlarının, bağlılıklarının, merkez ve sınırlarının belirtilmesi ve değiştirilmesi aşağıda gösterilen şekilde yapılır: A) İl ve ilçe kurulması, kaldırılması, merkezlerinin belirtilmesi, adlarının değiştirilmesi, bir ilçenin başka bir il'e bağlanması kanun ile; B) Bucak kurulması, kaldırılması, merkezinin belirtilmesi, il ilçe ve bucak sınırlarının ve bucak adlarının değiştirilmesi bir köyün veya kasabanın veya bucağın başka bir il ve ilçeye bağlanması, mühim mevki ve tabii arazi adlarının değiştirilmesi Cumhurbaşkanı onayı ile; C) Yeniden köy kurulması veya yerinin değiştirilmesi Bayındırlık ve Sağlık ve Sosyal Yardım Bakanlıklarının mütalaası alınmak suretiyle; Ç) Köy ve kasabaların aynı ilçe içinde bir bucaktan başka bir bucağa bağlanması, köy adlarının değiştirilmesi, köylerin birleştirilmesi ve ayrılması, bir köy, mahalle veya semtin o köyden ayrılıp başka bir köy ile birleştirilmesi İçişleri Bakanlığının tasvibiyle yapılır.",
  "İl İdaresi m.27": "İlçe genel idaresinin başı ve mercii kaymakamdır. Kaymakam, ilçede Cumhurbaşkanının idari yürütme vasıtasıdır. İlçenin genel idaresinden kaymakam sorumludur. Bakanlıkların kuruluş mevzuatına göre ilçede lüzumu kadar teşkilatı bulunur. Bu teşkilat (Dördüncü maddenin son fıkrasında belirtilen adli ve askeri teşkilat hariç) kaymakamın emri altındadır.",
  "İl İdaresi m.31": "A) Kaymakam kanun, Cumhurbaşkanlığı kararnamesi ve diğer mevzuatın neşir ve ilanını, uygulanmasını sağlar ve bunların verdiği yetkileri kullanır ve ödevleri yerine getirir. Kaymakam, valinin talimat ve emirlerini yürütmekle ödevlidir; (...) I) (...) Kaymakam, ilçenin idare şube başkanlariyle ikinci derecedeki memurlarına, genel ve özel kolluk amir ve memurlarına Memurin Kanundaki usulüne göre savunmasını aldıktan sonra uyarma, kınama cezaları verir ve uygular. Daha ağır disiplin cezaları verilmesi için özel kanunu hükümlerine göre teklif ve talepte bulunabilir. Kaymakamlarca re'sen verilen cezalar kesindir. Bu cezalar tebliğ tarihinden itibaren sicile geçer. (...) J) Kaymakam, ilçe idare şube başkanlarına acele hallerde (8 güne kadar) ve tayini kendisine ait memurlara, Memurlar Kanunundaki yıllık izin, süresine mahsup edilmek üzere bir aya kadar izin verebilir.",
  "İl İdaresi m.32": "A) Kaymakam, ilçe sınırları içinde bulunan genel ve özel kolluk kuvvet ve teşkilatının amiridir; B) Suç işlenmesini önlemek, kamu düzen ve güvenini korumak için gereken tedbirleri alır. Bu maksatla Devletin genel ve özel kolluk kuvvetlerini istihdam eder. (...) Bu teşkilat amir ve memurları kaymakam tarafından verilen emirleri derhal yerine getirmekle ödevlidir; (...) D) Kaymakam, valinin tasvibiyle ilçe genel ve özel kolluk kuvvetleri mensuplarının geçici veya sürekli olarak yerlerini değiştirebilir; E) Kaymakam, ilçe çevresinde çıkabilecek olayların emrindeki kolluk kuvvetleriyle önlenmesine olanak bulunmayacağı kanısına varır veya ilçe içindeki kolluk kuvetleriyle önlenemeyecek olağanüstü ve ani olaylar karşısında kalırsa hemen valiye bilgi vererek yardım ister ve en yakın askeri (Kara, Deniz ve Hava) komutanlara da haber verir;",
  "İl İdaresi m.4": "İl genel idaresinin başı ve mercii validir. Bakanlıkların kuruluş mevzuatına göre illerde lüzumu kadar teşkilat bulunur. Bu teşkilatın her birinin başında bulunanlar il idare şube başkanlarıdır. Bunların emri altında çalışanlar ilin ikinci derecede memurlarıdır. Bu teşkilat valinin emri altındadır. Hakimler Kanunu ile İcra ve İflas Kanununda yazılı yargıç, Cumhuriyet savcısı ve yargıç sınıfında bulunanlarla bu kanunlarda yazılı adalet memurları, askeri birlikler, askeri fabrika ve müesseseler, askerlik daire ve şubeleri bu madde hükmünden müstesnadır.",
  "İl İdaresi m.42": "Bucak müdürü, bucakta en büyük Hükümet memuru ve temsilcisidir. Bu sıfatla; A) Bucağın genel idaresinden sorumludur; (...) E) Müdür, 4 üncü maddenin son fıkrasında belirtilen adli ve askeri teşkilat dışında kalan, gözetim ve teftişi altında bulunan bucak teşkilatına dahil daire ve müesseselerin amir ve memurları ile genel ve özel kolluk amir ve memurlarına Memurin Kanunundaki usulüne göre savunmalarını aldıktan sonra uyarma cezası verir ve uygular. Bu ceza kesindir ve tebliğ tarihinden itibaren sicile geçer. Daha ağır disiplin cezaIarı ile takdirname verilmesini gerektiren hallerde vali ve kaymakama tekliflerde bulunur. (...) [m.43] Bucağın güven ve düzeninin korunmasından bucak müdürü sorumludur. Suç işlenmesini önlemek için gereken tedbirleri alır ve uygular. Genel ve özel kolluk kuvvetleri bucak müdürünün emri altındadır. Bunlar müdürden aldıkları emri yerine getirmeye mecburdurlar.",
  "İl İdaresi m.57": "İl idare kurulu, valinin başkanlığı altında hukuk işleri müdürü, defterdar, milli egitim, bayındırlık, sağlık ve sosyal yardım, tarım ve veteriner müdürlerinden teşekkül eder. Vali, idare kuruluna başkanlık etmek üzere vali muavinini görevlendirebilir.",
  "İl İdaresi m.58": "İlçe idare kurulu, kaymakamın başkanlığı altında tahrirat katibi, malmüdürü, Hükümet hekimi, milli eğitim memuriyle tarım memuru ve veterinerden teşekkül eder.",
  "İl İdaresi m.66": "İl genel kurulu veya idare kurulları yahut en büyük mülkiye amirleri tarafından kanunların verdiği yetkiye istinaden ittihaz ve usulen tebliğ veya ilan olunan karar ve tedbirlerin tatbik ve icrasına muhalefet eden veya müşkülat gösterenler veya riayet etmeyenler, mahallî mülkî amir tarafından Kabahatler Kanununun 32 nci maddesi hükmü uyarınca cezalandırılır. (Ek cümle: 27/3/2015 - 6638/16 md.) Ancak, kamu düzenini ve güvenliğini veya kişilerin can ve mal emniyetini tehlikeye düşürecek toplumsal olayların baş göstermesi hâlinde vali tarafından kamu düzenini sağlamak amacıyla alınan ve usulüne göre ilan olunan karar ve tedbirlere aykırı davrananlar, üç aydan bir yıla kadar hapis cezasıyla cezalandırılır.",
  "İl İdaresi m.8": "Yetiştirme ve ikmal kaynakları Bakanlıklar veya tüzel kişiliği haiz genel müdürlüklere bağlı olup il genel teşkilatı içinde birden fazla istihdam yerleri bulunan meslek, fen ve uzmanlık kadrolarına dahil görevlerden: A) İlçe idare şube başkanı sıfatını haiz olanlarla il merkezinde Devlet gelir, giderlerinin ve mallarının tahakkuk, tahsil, ödeme ve idaresiyle ilgili ikinci derecedeki müdürler, şube şefleri ve kontrol memurları, nakit muhasipleriyle, lise, orta ve o derecelerdeki okul müdür ve öğretmenleri, hastaneler mütehassıs hekimleri, Bakanlıklar veya tüzelkişiliği haiz genel müdürlükler tarafından tayin edilirler. B) Bunun dışında kalan bütün memurlar Bakanlıklar veya tüzelkişiliği haiz genel müdürlükler tarafından valilik emrine tayin edilerek il idare şube başkanının inhası üzerine valiler tarafından istihdam yerleri tesbit olunur; C) Yukardaki fıkralarda yazılı bütün memurların lüzumu halinde il içinde nakil ve tahvilleri mensup olduğu il idare şube başkanlarının inhası üzerine valiler tarafından icra edilmekle beraber mensup oldukları Bakanlıklar veya genel müdürlüklere sebepleriyle bildirilir. Yukarda (A, B) fıkraları dışında kalan il merkez teşkilatına bağlı memurlar ilgili idare şube başkanının inhası ile valiler tarafından tayin, nakil ve tahvil olunurlar.",
  "İl İdaresi m.9": "Vali, ilde Cumhurbaşkanının temsilcisi ve idari yürütme vasıtasıdır. Bu sıfatla: A) Valiler, ilin genel idaresinden Cumhurbaşkanına karşı sorumludur. Cumhurbaşkanı yardımcıları ve bakanlar, görevlerine ait işleri için valilere re'sen emir ve talimat verirler. (...) Ç) Kanun, Cumhurbaşkanlığı kararnamesi ve diğer mevzuatın verdiği yetkiyi kullanmak ve bunların yüklediği ödevleri yerine getirmek için valiler genel emirler çıkarabilir ve bunları ilan ederler.",
  "İl İdaresi m.Ek 1": "Vali; sivil hava meydanları, limanlar ve sınır kapılarında, güvenliğin sağlanması, giriş-çıkışlarla ilgili görev ve hizmetlerin düzenli ve etkili bir biçimde yürütülmesi, görevli kuruluşlar arasında işbirliği ve koordinasyonun gerçekleştirilmesi için gerekli önlemleri almaya ve uygulamaya, kuruluşların çalışmalarını denetlemeye yetkilidir. İçişleri Bakanlığının uygun göreceği bu yerlerde vali tarafından mülki idare amiri görevlendirilir. Vali, yetkilerinin tamamını veya bir kısmını görevlendirdiği mülki idare amirine devredebilir. Bu yerlerde hizmet veren kuruluşlar, görevli mülki idare amirine karşı sorumludur.",
  "İşyeri Açma Yön m.29": "Madde 29- İçkili yer bölgesi, mülkî idare amirinin genel güvenlik ve asayiş durumu hakkındaki görüşü doğrultusunda belediye sınırları ve mücavir alanlar içinde belediye meclisi, bu sınırlar dışında il genel meclisi tarafından tespit edilir. İçkili yer bölgesi haricinde içkili yer açılamaz.",
  "İşyeri Açma Yön m.3": "Dayanak — Madde 3- Bu Yönetmelik, 24/4/1930 tarihli ve 1593 sayılı Umumi Hıfzıssıhha Kanunu, 15/5/1930 tarihli ve 1608 sayılı Umuru Belediyeye Müteallik Ahkâmı Cezaiye Hakkında 16 Nisan 1340 Tarih ve 486 Numaralı Kanunun Bazı Maddelerini Muaddil Kanun, 4/7/1934 tarihli 2559 sayılı Polis Vazife ve Selahiyet Kanunu, 14/6/1989 tarihli ve 3572 sayılı İşyeri Açma ve Çalışma Ruhsatlarına Dair Kanun Hükmünde Kararnamenin Değiştirilerek Kabulüne Dair Kanun, 12/4/2000 tarihli ve 4562 sayılı Organize Sanayi Bölgeleri Kanunu, 9/1/2002 tarihli ve 4737 sayılı Endüstri Bölgeleri Kanunu, 10/7/2004 tarihli ve 5216 sayılı Büyükşehir Belediyesi Kanunu, 22/2/2005 tarihli ve 5302 sayılı İl Özel İdaresi Kanunu, 3/7/2005 tarihli ve 5393 sayılı Belediye Kanunu hükümleri ile 3/5/1985 tarihli ve 3194 sayılı İmar Kanununun ek 11 inci maddesinin birinci fıkrasının (ç) ve (f) bentlerine dayanılarak hazırlanmıştır.",
  "İşyeri Açma Yön m.30": "Madde 30- İçkili yer bölgesi; a) Hükümet binaları, hapishane ve ıslah evleri; her türlü mabet, dini kurum ve kuruluşlar; sanat müesseseleri, maden ocakları, inşaat yerleri; patlayıcı, parlayıcı, yanıcı ve benzeri tehlikeli maddeler üretilen, satılan ve depolanan yerler ile gaz dolum tesisleri yakınında, b) Konaklama yerleri hariç olmak üzere, otoyolları ve karayollarının her iki tarafında sınır çizgisine ikiyüz metreden yakın mesafe içinde, c) Otogar ve otobüs terminallerinde, d) Resmî ve özel okul binaları, ilk ve orta öğretim öğrencilerinin barındığı öğrenci yurtları ile anaokullarına yüz metreden yakın mesafe içinde, tespit edilemez.",
  "İşyeri Açma Yön m.32": "Madde 32- (...) Umuma açık istirahat ve eğlence yerinin açılması ve faaliyette bulunmasına belediye sınırları ve mücavir alan sınırları içinde belediye, bu alanlar dışında il özel idaresi tarafından izin verilir. İl özel idaresi ve belediyeler, umuma açık istirahat ve eğlence yeri ruhsatını vermeden önce kolluk kuvvetinin görüşünü alır. Yetkili kolluk kuvveti, açılacak yerin genel güvenlik ve asayişin korunması açısından kolaylıkla kontrol edilebilecek bir yerde ve konumda olup olmadığını dikkate alarak, işyeri hakkındaki görüşünü mülki idare amiri vasıtasıyla yedi gün içinde bildirir. Umuma açık istirahat ve eğlence yeri açılması hususundaki başvurular yetkili idareler tarafından bir ay içinde sonuçlandırılır.\n\nİzin almadan açılan umuma açık istirahat ve eğlence yerleri, yetkili idarelerin ilgili birimleri tarafından sebebi bir tutanakla belirlenmek ve mühürlenmek suretiyle re'sen kapatılır. Kollukça, izin almadan açıldığı tespit edilen umuma açık istirahat ve eğlence yerleri düzenlenecek bir tutanakla kapatılmak üzere yetkili idareye bildirilir. Yetkili idare yapılan bildirim üzerine izin almadan açılan yeri kapatarak en geç üç gün içinde kolluğa bilgi verir.\n\n(Değişik cümle:RG-25/1/2020-31019-CK-2048/2 md.) Meyhane, kahvehane, kıraathane, bar, elektronik oyun merkezleri, internet salonu gibi umuma açık yerler ile alkollü içkilerin açık olarak satışının yapıldığı yerlerin; örgün eğitim kurumları, özel öğretim kursları, yükseköğretim hariç öğrenci yurtları ile anaokullarından, kapıdan kapıya en az yüz metre uzaklıkta bulunması zorunludur. Özel eğitime muhtaç bireylerin devam ettikleri öğretim kurumları ile okullar dışındaki diğer özel öğretim kurumları için bu zorunluluk aranmaz. Ancak söz konusu özel öğretim kurumlarıyla yukarıda belirtilen türdeki işyerleri aynı binada bulunamaz. Turizmin yoğun olduğu yörelerdeki okulların tatil olduğu dönemlerde yukarıda belirtilen işyerleri ile okullar arasında yüz metre şartı aranmaz. Sabit veya seyyar olarak kullanılan kara, deniz, hava ve her çeşit taşıma araçlarının umuma açık istirahat ve eğlence yeri olarak kullanılmasının istenmesi halinde, deniz araçları için bağlı olduğu veya bulunduğu liman başkanlığının, diğerleri için ilgili kurum ve kuruluşların uygun görüşü alınır.",
  "İşyeri Açma Yön m.33": "Madde 33- Umuma açık istirahat ve eğlence yerlerinin açılış ve kapanış saatleri belediye sınırları içinde belediye encümeni, bu yerler dışında il encümeni tarafından tespit edilir.",
  "İşyeri Açma Yön m.34": "Madde 34- Meyhane, kahvehane, kıraathane, bar, elektronik oyun merkezleri, internet salonu gibi umuma açık yerler ile açık alkollü içki satılan yerlerin açılmasına izin verilirken mesafe ölçümünde, bina ve tesislerin varsa bahçe kapıları, yoksa bina kapıları; kapıların birden fazla olması durumunda en yakını esas alınır. Yüz metre uzaklığın ölçümünde, mevcut cadde ve sokaklar üzerinden yaya yolu kullanılarak, yaya kurallarına göre gidilebilecek en kısa mesafe dikkate alınır.",
  "İşyeri Açma Yön m.36": "Madde 36- Kanunî istisnalar saklı kalmak üzere; eğlence, oyun, içki ve benzeri amaçlı umuma açık yerlerde onsekiz yaşından küçükler çalıştırılamaz. Umuma açık istirahat ve eğlence yerlerinde çalıştırılacak kişilerin adı, soyadı, Türkiye Cumhuriyeti kimlik numarası, adlî sicil ve bulaşıcı hastalığı bulunmadığına dair beyanlarının yetkili idareye verilmesi şarttır. Umuma açık istirahat ve eğlence yerlerinde çalıştırılacak kişilerin, bulaşıcı hastalığı bulunmadığına dair resmî sağlık kurumundan alınacak sağlık raporu, bu kişiler işe başlamadan önce temin edilir ve bu kişiler çalıştığı sürece altı ayda bir yenilenerek işyerinde hazır bulundurulur. Bu raporlar ruhsat verme aşamasında yetkili idare tarafından istenmez; ancak, yapılacak denetimlerde bu raporların görevlilere gösterilmesi gerekir. Umuma açık istirahat ve eğlence yerlerinde, genel kadın olarak tescil edilenler çalıştırılamaz.",
  "İşyeri Açma Yön m.38": "Madde 38- (Başlığı ile Birlikte Değişik: 22/2/2023-32112-C.K-6825/1 md.) İş yerlerindeki müzik yayınları, 30/11/2022 tarihli ve 32029 sayılı Resmî Gazete'de yayımlanan Çevresel Gürültü Kontrol Yönetmeliği hükümleri kapsamında verilmiş müzik yayın izni ile yapılır. Müzik yayın izni ruhsata işlenmez. Ancak görevlilerce sorulduğu zaman gösterilebilecek şekilde iş yerinde bulundurulur. Müzik yayın izni iptal edilen iş yerlerinde, müzik yayını harici faaliyetlere devam edilir. Müzik yayın izni iptal edildiği halde müzik yayını yaptığı tespit edilen iş yerlerinde, ek 3 üncü maddeye göre işlem tesis edilir.",
  "İşyeri Açma Yön m.43": "Madde 43- Her türlü konaklama yeri işleticisi, bu yerlerde yatacak olan Türkiye Cumhuriyeti vatandaşı veya yabancı uyruklu kişilerin kimlik ve geliş-gidiş kayıtlarını ücretli veya ücretsiz, gündüz veya gece kalmalarına bakılmaksızın örneğine ve usulüne uygun şekilde, günü gününe tutmak ve kolluk denetimine hazır bulundurmak zorundadır. Bu Yönetmelik kapsamına giren işletmelerin işletmecisi veya mesul müdürü, iş yerinde sürekli veya geçici olarak çalıştırılan kişinin ayrılışını, 1774 sayılı Kimlik Bildirme Kanununun uygulanmasına ilişkin yönetmelikteki örneğine uygun kimlik bildirme belgesi doldurmak suretiyle yirmi dört saat içerisinde bağlı bulunduğu kolluğa bildirir.",
  "İşyeri Açma Yön m.5": "Madde 5- İşyeri açma ve çalışma ruhsatı verilen işyerleri aşağıda belirtilen şartları taşımak zorundadır: a) İş sağlığı ve güvenliği ile ilgili olarak mevzuatta öngörülen tedbirlerin alınmış olması, b) 634 sayılı Kat Mülkiyeti Kanunu kapsamına giren gayrimenkullerin, tapu kütüğünde mesken olarak gösterilen bağımsız bölümlerinde sinema, tiyatro, kahvehane, gazino, pavyon, bar, kulüp, dans salonu ve benzeri eğlence ve toplantı yerleri; fırın, lokanta, pastane, süthane gibi gıda ve beslenme yerleri; imalathane, boyahane, basımevi, dükkan, galeri ve çarşı gibi işyerlerinin açılması hususunda kat maliklerinin oy birliği ile karar alması, Tapuda iş yeri olarak görünen yerlerde, umuma açık istirahat ve eğlence yeri açılması durumunda yönetim planında aksine bir hüküm yoksa, kat maliklerinin oy çokluğu ile aldığı kararın bulunması, (...) f) (Ek: 23/5/2011 – 2011/1900 K.) Madencilik faaliyetleri sırasında patlayıcı madde kullanılan yerlerde 27/11/1973 tarihli ve 7/7551 sayılı Bakanlar Kurulu Kararı ile yürürlüğe konulan Parlayıcı, Patlayıcı, Tehlikeli ve Zararlı Maddelerle Çalışılan İşyerlerinde ve İşlerde Alınacak Tedbirler Hakkında Tüzük (...) hükümlerine uygun tedbirlerin alınması, g) Karayolu kenarındaki işyerleri için karayolu trafik güvenliğinin sağlanmış ve geçiş yolu izin belgesinin alınmış olması, (...) j) Sınaî, tıbbî ve radyoaktif atık üreten işyerlerinde bu atıkların toplanması, taşınması, depolanması, işlenmesi ve bertarafı konusunda gerekli tedbirlerin ve izinlerin alınmış olması, (...)\n\nı) Umuma açık istirahat ve eğlence yerlerinden meyhane, bar, kahvehane, kıraathane, elektronik oyun merkezi, internet salonu ile açıkta alkollü içki satılan işyerlerinin okul, yurt, mabet bina ve tesislerine mevzuatın öngördüğü uzaklıkta bulunması, (...) o) Sıvılaştırılmış petrol gazı tüp dağıtım merkezleri ve perakende satış yerleri ile bunların varsa tüp depolamak için kullandığı yerlerde işyerlerine giren ve çıkanların tespiti amacıyla gerekli kamera kayıt sisteminin kurulması (Bu sistem aracılığıyla elde edilen kayıtlar otuz gün süre ile saklanır ve kayıtlar yetkili makamlar haricindeki kişi ve kuruluşlara verilemez.).\n\nc) Özel yapı şeklini gerektiren sinema, tiyatro, düğün salonu, otel, hamam, sauna; ekmek fırını ile akaryakıt, sıvılaştırılmış petrol gazı, sıvılaştırılmış doğal gaz ve sıkıştırılmış doğal gaz istasyonu için yapı kullanma izin belgesinin alınmış olması, (...) n) (Ek: 29/6/2010 – 2010/671 K.) Yanıcı ve parlayıcı madde kategorisindeki sıvıların depolanması amacıyla kullanılan tesis ve düzeneklerde, işyeri açma ve çalışma ruhsatında kayıtlı hacimden fazla ve başka kategoriden sıvı depolanmaması, bu tesis ve düzeneklerde gerçekleştirilecek tadilatların ruhsata işlenmeden faaliyete geçirilmemesi. o) (Ek: 12/12/2016-2016/9607 K.) Sıvılaştırılmış petrol gazı tüp dağıtım merkezleri ve perakende satış yerleri ile bunların varsa tüp depolamak için kullandığı yerlerde işyerlerine giren ve çıkanların tespiti amacıyla gerekli kamera kayıt sisteminin kurulması (Bu sistem aracılığıyla elde edilen kayıtlar otuz gün süre ile saklanır ve kayıtlar yetkili makamlar haricindeki kişi ve kuruluşlara verilemez.).\n\nd) Umuma açık istirahat ve eğlence yerlerinde genel asayiş ve güvenlik yönünden yetkili kolluk kuvvetinin görüşünün alınmış olması, e) Umuma açık istirahat ve eğlence yerlerinin, patlayıcı, parlayıcı, yanıcı ve benzeri tehlikeli maddeler üretilen, satılan, kullanılan, depolanan yerler ile gaz dolum tesislerine mevzuatın öngördüğü uzaklıkta bulunması, (...) h) Umuma açık istirahat ve eğlence yerleri; patlayıcı, parlayıcı ve yanıcı maddelerin üretildiği, satıldığı ve depolandığı işyerleri; otuz kişiden fazla çalışanın bulunduğu her türlü işyerleri, ana giriş kapıları dışında cadde ve sokağa doğrudan bağlantısı olmayan ve birden fazla işyerinin bir arada bulunduğu iş hanı, çarşı ve benzeri işyerlerinde yangına karşı gerekli önlemlerinin alındığını gösteren itfaiye raporunun alınması, diğer işyerlerinde ise yangına karşı gerekli tedbirlerin alınmış olması, ı) Umuma açık istirahat ve eğlence yerlerinden meyhane, bar, kahvehane, kıraathane, elektronik oyun merkezi, internet salonu ile açıkta alkollü içki satılan işyerlerinin okul, yurt, mabet bina ve tesislerine mevzuatın öngördüğü uzaklıkta bulunması, (...) m) (Ek: 29/6/2010 – 2010/671 K.; Değişik: 10/11/2014-2014/7002 K.) Ekmek fırınlarının bu amaca tahsisli ayrık nizamda müstakil binalarda açılmış olması (Ancak, alışveriş merkezleri içinde bulunan 1000 m2 ve üstü alana sahip hipermarket, süpermarket, grossmarket ve megamarket gibi adlarla açılan işyerleri bünyesinde yer alan fırınlarda ayrık nizamda müstakil bina şartı aranmaz.), (...) Umuma açık istirahat ve eğlence yerleri için bu hususlar işyeri açma ve çalışma ruhsatı verilmeden önce yerinde kontrol edilir.",
  "İşyeri Açma Yön m.6": "Madde 6- (...) Yetkili idarelerden usulüne uygun olarak işyeri açma ve çalışma ruhsatı alınmadan işyeri açılamaz ve çalıştırılamaz. İşyerlerine bu Yönetmelikte belirtilen yetkili idareler dışında diğer kamu kurum ve kuruluşları ile ilgili meslek kuruluşları tarafından özel mevzuatına göre verilen izinler ile tescil ve benzeri işlemler bu Yönetmelik hükümlerine göre ruhsat alma mükellefiyetini ortadan kaldırmaz. İşyeri açma ve çalışma ruhsatı alınmadan açılan işyerleri yetkili idareler tarafından kapatılır. İşyeri ruhsatları yetkili idarelerin en üst amiri veya görevlendireceği yetkili tarafından bu Yönetmelikte öngörülen sürede imzalanır; ruhsat için ayrıca, meclis veya encümen tarafından bir karar alınmaz. Ruhsat, Örnek 5'te yer alan bilgileri içerecek şekilde düzenlenir.",
  "İşyeri Açma Yön m.7": "Madde 7- Yetkili idareler tarafından verilen işyeri açma ve çalışma ruhsatlarının örnekleri aylık olarak sigorta il müdürlüğüne ve ilgili ise ticaret siciline veya esnaf siciline gönderilir. Umuma açık istirahat ve eğlence yerleri için düzenlenen işyeri açma ve çalışma ruhsatlarının bir örneği en geç yedi gün içinde yetkili idare tarafından kolluğa gönderilir.",
  "İşyeri Açma Yön m.8": "Madde 8- (...) İşyeri sahibinin ölümü halinde, yeni ruhsat düzenlenmeksizin kanunî mirasçıları adına eski ruhsatın intibakı yapılır. Ruhsatın yenilenmesi veya intibakı gereken hallerde yetkili idareye en geç üç ay içinde müracaat edilmesi zorunludur. Bu süre mirasçılar için altı ay olarak uygulanır. Süresi içinde müracaat yapılmadığının yetkili idarelerce tespiti durumunda tespit tarihinden itibaren onbeş günlük süre verilir. Bu süre sonunda ruhsat yenilenmediği veya intibak yaptırılmadığı hallerde ruhsat iptal edilir.",
  "İzin Yön m.10": "MADDE 10- (1) (...) a) Hizmet yapamayacak şekilde hastalanan personelin hastalığı geçici ise (...) hastanelerde geçen teşhis ve tedavi süreleri hariç, (...) toplam olarak ve fiilen iki yılı geçmemek üzere, nekahet tedavisi, istirahat ve hava değişimi işlemine tabi tutulur. (...) b) Kanser, her türlü kötü huylu tümör, verem, kronik böbrek yetmezliği ile akıl ve ruh hastalıkları gibi uzun süreli bir tedaviye ihtiyaç gösteren hastalığa yakalananlar, (...) toplam olarak ve fiilen üç yılı geçmemek şartı ile tedavi, istirahat veya hava değişimine tabi tutulabilirler. c) Sağlık durumundan dolayı \"Yurdun alçak veya alçak mutedil bölgelerinde faal görev yapar\" veya \"Muayyen bölgelere gidemez\" şeklinde iklim değiştirme raporları alanlar (...) bu durumlardaki sıhhi izin süreleri dört yıl olarak hesaplanır.\n\nMADDE 10- (1) d) Kadın personele doğum yapmasından önce sekiz hafta ve doğum yaptığı tarihten itibaren sekiz hafta olmak üzere toplam on altı hafta süre ile aylıklı izin verilir. (...) 1) Çoğul gebelik halinde, doğum öncesi sekiz haftalık izin süresine iki hafta süre eklenir. 2) Beklenen doğum tarihinden sekiz hafta öncesinden, sağlık durumunun uygun olduğu doktor raporu ile belgelenen personel, isterse doğumdan önceki üç haftaya kadar iş yerinde çalışabilir. (...) e) Doğum yapan personele çocuklarını emzirmeleri için aylıklı izin süresinin bitim tarihinden itibaren ilk altı ayda günde üç saat, ikinci altı ayda günde bir buçuk saat süt izni verilir. f) Doğum yapan personele, aylıklı izinlerinin bitiminden itibaren başlamak üzere istekleri üzerine on iki aya kadar aylıksız izin verilir.",
  "İzin Yön m.11": "MADDE 11- (1) (...) a) İçişleri Bakanlığınca; 1) Öğrenim için öğrenim süresi kadar, 2) Meslekî bilgi ve görgüsünü artırmak maksadıyla bir yıla kadar, 3) Seminer, müşahede gezisi ve ziyaretler için lüzumlu görülen süre kadar, 4) Mazeret dolayısıyla yıllık izinle birlikte üç aya kadar, 5) Seyahat maksadıyla yurt dışına gidecek personele, yıllık izin süresi kadar, yurt dışı izni verilebilir. (...) c) Yurt dışı izin verme yetkisi İçişleri Bakanlığınca devredilebilir. Yetki devri hâllerinde, verilen yurt dışı izinleri yetki devri yapan makama bildirilir.",
  "İzin Yön m.12": "MADDE 12- (1) (...) öğrenim amacıyla, öğrenim süresi kadar yurt dışı izni verilebilir. Bu iznin verilebilmesi için, öğrenim görülecek kurumun en az üniversite, akademi veya bunların eşiti düzeyde öğrenim/eğitim veren bir kurum olması, alınacak öğrenim/eğitimin lisansüstü düzeyde, personelin mesleği ile ilgili bir konu olması (...) şarttır. (2) (...) a) Müracaat tarihi itibarıyla bulunduğu statüde beşinci hizmet yılını tamamlamış, on ikinci hizmet yılını tamamlamamış olmak. (...) (3) Bu madde gereğince izin verilecek personel miktarı, her statüdeki personel mevcudunun binde birini geçemez.",
  "İzin Yön m.16": "MADDE 16- (1) (...) seyahat maksadı ile izin sıra cetveline tabi olarak yurt dışına izinli gidebilirler. (2) Bu madde gereğince verilecek izin, personelin yıllık izinlerinden sayılır ve otuz günü geçemez. (3) İzne gidecek personele, kullanılan ulaşım vasıtası da dikkate alınarak ayrıca yol izni verilebilir. Yol izni süresi toplam dört günü geçemez. (...) (4) c) Yurt dışı izin müracaatı, asgari alay ve eşiti birimlerin amirlerince izin tarihinden en az otuz gün önce, Jandarma Genel Komutanlığı Personel Başkanlığında hazır bulundurulur. (...) f) Seyahat maksadıyla aynı anda yurt dışında izinli bulunan personel sayısı statülerine göre mevcutlarının yüzde birini geçemez.",
  "İzin Yön m.18": "MADDE 18- (1) Mesleki bilgi ve görgünün artırılması, öğrenim, seminer, müşahede gezisi ve ziyaretler için verilecek yurt dışı izinleri ile yabancı memleketlerde görevlendirilen personelde (...) aşağıdaki şartlar aranır: a) Sicil notu ortalaması, sicil tam notunun yüzde 93'ü ve üzerinde olmak. b) İzinli gidilecek yabancı ülkenin dilinden (...) son iki yıl içerisinde ÖSYM tarafından yapılan yabancı dil sınavı (YDS/E-YDS) (...) yüz tam puan üzerinden en az seksen beş not almış olmak. (...) f) (...) başvuru tarihinden itibaren geriye doğru son beş yıl içinde, toplamda on iki ay veya daha fazla durdurma cezası almamış olmak.",
  "İzin Yön m.20": "MADDE 20- (1) İzinli olarak yurt dışında bulunan subay, sözleşmeli subay, astsubay, sözleşmeli astsubay, uzman jandarma ve uzman erbaşlar; a) Milletimizin ve Jandarma Genel Komutanlığının birer temsilcisi olarak gerek resmî gerekse özel hayatlarını Türk Jandarmasına yaraşır bir şekilde düzenlemek zorundadır. b) Yurt dışındaki Türk Silahlı Kuvvetleri, Sahil Güvenlik Komutanlığı ile yabancı askeri ve kolluk personeline karşı tavır ve hareketlerinde meslekî vakar ve ananeyi muhafaza eder. c) Yabancılarla temasta daha titiz ve dikkatli davranır, resmî ve özel hayatlarında herhangi bir olumsuz olaya sebebiyet vermemek için özen gösterir. ç) Mevzuat ve malî imkânlarına göre uygun bir meskende ve meslekî şerefe uygun bir şekilde yaşamak zorundadır. d) Zorunlu olmadıkça üniforma giyemez. e) Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez. (2) Yurt dışına izinli gidecek personele bağlı bulunduğu birlik, karargâh ve kurum amirlikleri ve komutanlıkları tarafından, yurt dışındaki hareket tarzları hakkında, istihbarata karşı koyma ve koruyucu güvenlik önlemleri konularında uyarıcı bilgiler verilir. (3) İzinli olarak yurt dışında bulunan personel, Jandarma Genel Komutanlığınca belirlenen istihbarata karşı koyma ve koruyucu güvenlik esaslarına uyar.",
  "İzin Yön m.22": "MADDE 20- (1) (...) d) Zorunlu olmadıkça üniforma giyemez. e) Seyahat maksadıyla yurt dışına giden personel şahsi, zati ve miri silahını götüremez. MADDE 22- (1) İzinli olarak yurt dışına gönderilen personelden, aşağıda sayılanlar derhal yurda çağrılırlar. Geri çağırma yetkisi onay veren makama aittir. (...) a) Vatandaşlık ve memurluk şeref ve haysiyetini zedeleyecek hareketlerde bulunanlar. (...) ç) İznin maksadına aykırı hareket edenler. d) Gerçeğe aykırı beyanda bulunarak amirlerini ve izin işlemini yapan makamları aldatanlar.",
  "İzin Yön m.5": "MADDE 5- (1) Personelin izin işlemleri aşağıdaki genel esaslar dâhilinde yürütülür. a) Personele verilecek izinler şunlardır: 1) Yıllık izin. 2) Mazeret izinleri. 3) Sıhhi izinler. 4) Yurt dışı izinleri. (...) g) Savaş ve olağanüstü hallerde 2803 sayılı Kanunun ek 3 üncü maddesi uyarınca izin süreleri kısaltılabilir veya kaldırılabilir. Bu hâllerde, personel izinden geriye çağrılabilir. (...) i) Yurt dışında izinde bulunup, yurda dönme kararı kendisine tebliğ edilen personel, 48 saat içerisinde, en kısa yoldan ve en seri vasıta ile dönüşe geçer. (...) j) Personel görev yaptığı ilin dışına izinsiz çıkamaz.",
  "İzin Yön m.6": "MADDE 6- (1) (...) a) Personelin her yıl otuz gün yıllık izin hakkı vardır. Bu müddete yol dâhil değildir. Ayrıca kısa süreli mazeretlerde kullanılmak üzere on beş güne kadar yıllık mazeret izni verilebilir. (...) ç) Personelin yıllık mazeret izin talebinin izin vermeye yetkili amiri tarafından uygun görülmesi durumunda, yıllık iznini kullanmamış olsa dahi, öncelikli olarak yıllık mazeret izni verilir. (...) i) (...) Aynı yıl içinde kullanılabilecek yıllık izin süresi hiçbir suretle toplam altmış günü geçemez.\n\nMADDE 6- (1) c) Yıllık izinlerin; personelin talebi, birlik görevleri ve personel mevcudu dikkate alınarak, yirmi ve on günlük olarak iki defada kullandırılması esastır. Haziran, Temmuz, Ağustos ve Eylül aylarında kullanılacak yıllık izin süresi en fazla yirmi gün olarak planlanır. Ancak yıllık izinler, uygun olduğu takdirde, izin sıra çizelgesini onaylayan makamın yetkisinde iznin tamamı bir seferde veya birkaç defada verilebilecek şekilde planlanabilir. (...) f) Yıllık izinlerini kullanan personelin gidiş ve dönüşlerinde bir defaya mahsus olmak üzere, (...) iki günden az olmamak kaydıyla dört güne kadar yol izni verilir. (...) ğ) Aynı anda izin kullanacak personel sayısının, birimin genel mevcudunun yüzde 25'ini geçmemesi (...) esastır.",
  "İzin Yön m.8": "MADDE 7- (2) Jandarma Bölge Komutanlığı ve il jandarma komutanlığı personelinin izin sıra çizelgeleri vali tarafından, ilçe jandarma komutanlığı personelinin izin sıra çizelgeleri kaymakam tarafından onaylanır. (4) İzin sıra çizelgesi, her yıl Kasım ayı sonuna kadar onay makamında bulundurulur. (...) 15 Aralık tarihine kadar personele tebliğ edilir. MADDE 8- (1) Yıllık izinler ve yıllık mazeret izinleri; a) Jandarma Genel Komutanı için İçişleri Bakanı, b) Jandarma Genel Komutanı Yardımcıları için Jandarma Genel Komutanı, (...) d) Jandarma bölge komutanları ve il jandarma komutanları için konuşlu bulunduğu ilin valisi, e) İlçe jandarma komutanları için kaymakam, tarafından verilir.",
  "İzin Yön m.9": "MADDE 9- (1) Personele 6 ncı maddede yazılı on beş günlük yıllık mazeret izinleri dışında; a) Eşinin doğum yapması, eşinin ölümü, çocuğunun ölümü, kendisinin veya eşinin ana, baba veya kardeşinin ölümü hallerinin her birinde isteği üzerine on güne kadar; kendisinin veya çocuğunun evlenmesi halinde isteği üzerine yedi güne kadar mazeret izni verilebilir. Bu bentte yazılı izinler ertelenemez veya devredilemez. b) Yangın, deprem, su baskını gibi olağanüstü bir mazeret dolayısıyla bir yıl içinde otuz güne kadar mazeret izni verilebilir. c) Hizmetleri sırasında radyoaktif ışınlarla çalışan personele her yıl, yıllık izinlerinden ayrı olarak, otuz gün izin verilir. Bu izin bölünemez, yıl geçişlerinde üst üste kullanılamaz ve diğer yıla aktarılamaz. (...) (3) Bu madde kapsamında verilen mazeret izinleri yıllık izne mahsup edilmez.\n\nMADDE 9- (1) d) Bakmakla yükümlü olduğu veya refakat etmediği takdirde hayatı tehlikeye girecek anne, baba, eş ve çocukları ile kardeşlerinden birinin ağır bir kaza geçirmesi veya tedavisi uzun süren önemli bir hastalığa tutulmuş olması hâllerinde, bu hâllerin sağlık kurulu raporuyla belgelendirilmesi şartıyla, istekleri üzerine, aylık ve özlük hakları korunarak üç aya kadar izin verilebilir. Gerektiğinde bu süre bir katına kadar uzatılır. Bu sürenin bitimini müteakip istekleri üzerine ayrıca altı aya kadar aylıksız izin verilebilir. (...) 3) Aynı kişi ve aynı vakaya dayalı olarak verilecek refakat izninin aylıklı ve aylıksız toplam süresi on iki ayı geçemez.",
  "Jandarma Kanunu m.12": "Madde 12 – (Değişik: 25/7/2016-KHK-668/12 md.; Aynen kabul: 8/11/2016-6755/12 md.)\nLüzum görüldüğü hallerde İçişleri Bakanı tarafından, Emniyet Genel Müdürlüğü, Sahil Güvenlik Komutanlığı ve Jandarma Genel Komutanlığı arasında her kademedeki personel, geçici olarak görevlendirilebilir. İçişleri Bakanı bu yetkisini il valilerine devredebilir.\nAyrıca, İçişleri Bakanının onayıyla; Emniyet Genel Müdürlüğü, Sahil Güvenlik Komutanlığı ve Jandarma Genel Komutanlığı silah, mühimmat, teçhizat, taşıt ve diğer taşınırları ile taşınmazlarını birbirlerine geçici olarak tahsis edebilirler veya bedelsiz olarak devredebilirler.\nBu maddenin uygulanmasına ilişkin usul ve esaslar İçişleri Bakanlığınca yürürlüğe konulan yönetmelikle belirlenir.",
  "Jandarma Kanunu m.14": "Madde 14 – (Değişik birinci fıkra: 2/7/2018 – KHK/703/128 md.) Jandarma Genel Komutanı, Genel Komutan Yardımcıları, generaller, bölge ve il jandarma komutanları dışında kalanlar İçişleri Bakanınca yapılır.",
  "Jandarma Kanunu m.15": "Madde 15 – Disiplin ve soruşturma usulleri:\n\nMadde 15 – (Değişik: 25/7/2016-KHK-668/15 md.; Aynen kabul: 8/11/2016-6755/15 md.)\nJandarma personeli hakkında disiplin ve soruşturma işlemleri aşağıdaki usullere göre yapılır.\na) Disiplin işleri özel kanun hükümlerine göre yürütülür.\nb) Jandarma personelinin mülki görevlerinden doğan suçlarında; özel kanunların hükümleri saklı kalmak şartıyla 2/12/1999 tarihli ve 4483 sayılı Memurlar ve Diğer Kamu Görevlilerinin Yargılanması Hakkında Kanun hükümlerine göre işlem yapılır.\nc) Adli görevlerinden doğan suçlarda; 4/12/2004 tarihli ve 5271 sayılı Ceza Muhakemesi Kanununun 161 inci maddesinin beşinci fıkrası hükmü uygulanır.\nd) (Değişik: 2/7/2018 – KHK/703/128 md.) Jandarma personeline askeri görev verildiği takdirde bu görevlerden doğan suçların muhakemesi, Jandarma personelinin emrine verildiği askeri birlik personelini muhakeme etmekle görevli ve yetkili olan mahkemede görülür.\ne) Jandarma personelinin kişisel suçlarında genel hükümlere göre işlem yapılır.\n(Ek fıkra: 15/8/2017/KHK-694/55 md.; Aynen kabul: 1/2/2018-7078/52 md.) Ertelenmiş, seçenek yaptırımlara çevrilmiş, hükmün açıklanmasının geri bırakılmasına karar verilmiş, affa uğramış veya 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun 53 üncü maddesinde belirtilen süreler geçmiş olsa bile; Devletin güvenliğine karşı suçlar, Anayasal düzene ve bu düzenin işleyişine karşı suçlar, milli savunmaya karşı suçlar, Devlet sırlarına karşı suçlar ve casusluk, zimmet, irtikâp, rüşvet, iftira, hırsızlık, dolandırıcılık, sahtecilik, güveni kötüye kullanma, hileli iflas, ihaleye fesat karıştırma, edimin ifasına fesat karıştırma, suçtan kaynaklanan malvarlığı değerlerini aklama veya kaçakçılık suçlarından ya da kasten işlenen bir suçtan dolayı bir yıl veya daha fazla süreyle hapis cezasına mahkûm olan Jandarma Genel Komutanlığında görevli subay, astsubay ve uzman jandarmaların Komutanlıkla ilişikleri İçişleri Bakanının onayı ile kesilir.\n\nMadde 15/A- (Ek: 25/7/2018-7145/6 md.) Erbaş ve erlerin üst ve eşyalarının aranması\nTehlikenin veya suç işlenmesinin önlenmesi amacıyla usulüne göre verilmiş sulh ceza hâkimi kararı veya bu sebeplere bağlı olarak gecikmesinde sakınca bulunan hâllerde yirmi dört saat içinde görevli hâkimin onayına sunulması şartıyla birlik komutanının veya kurum amirinin yazılı emri üzerine, jandarma hizmet binaları ve eklentilerinde, askerlik yükümlülüğünü yerine getiren erbaş ve erlerin üstü, özel kâğıtları ve eşyası aranır, gerekli tedbirler alınır, suç delilleri koruma altına alınarak 5271 sayılı Kanun hükümlerine göre gerekli işlemler yapılır.\nArama talep yazısında, arama için makul sebeplerin oluştuğunun, gerekçeleriyle birlikte gösterilmesi gerekir. Arama kararında veya emrinde; aramanın sebebi, konusu ve kapsamı ile yapılacağı yer, zaman ve geçerli olacağı süre belirtilir.\nAramanın sonucu, arama kararı veya emri veren merci veya makama bir tutanakla bildirilir.\nKonutta ve yerleşim yerinde ve eklentilerinde önleme araması yapılamaz.\nBu maddenin uygulanmasına ilişkin usul ve esaslar İçişleri Bakanlığı tarafından çıkarılan yönetmelikle düzenlenir.",
  "Jandarma Kanunu m.18": "Madde 18 – Jandarma Genel Komutanlığının bütçesi, İçişleri Bakanlığının bünyesinde ve bu Bakanlığın bütçesinden ayrı olarak düzenlenir.",
  "Jandarma Kanunu m.19": "Madde 19 – (Değişik: 25/7/2016-KHK-668/16 md.; Değiştirilerek kabul: 8/11/2016-6755/16 md.) Jandarma Genel Komutanlığı ikmal hizmetleriyle faaliyetlerine ait her türlü ihtiyacını ve silah ve mühimmatını İçişleri Bakanlığınca belirlenecek standartlara uygun olarak kendi bütçesinden karşılar. Ancak Jandarma Genel Komutanlığı, Savunma Sanayi Destekleme Fonundan Türk Silahlı Kuvvetlerinin tabi olduğu usul ve esaslar dahilinde yararlanır. Jandarma Genel Komutanlığının ihtiyaçları, İçişleri Bakanlığı tarafından Savunma Sanayii Müsteşarlığına doğrudan teklif edilir. Bu ihtiyaçlar İçişleri Bakanlığının güvenlik önceliklerine göre değerlendirilir. Seferberlik ve savaş hallerinde Kuvvet Komutanlıkları emrine girecek veya İçişleri Bakanı ya da valilerce askeri görev verilen jandarma birliklerinin her türlü ihtiyacı (sefer stokları dahil) emrine gireceği Kuvvet Komutanlıklarının standartlarına uygun olarak Milli Savunma Bakanlığınca sağlanır. (Ek fıkra: 2/1/2017-KHK-680/45 md.; Aynen kabul: 1/2/2018-7072/44 md.) Jandarma Genel Komutanlığının ihtiyaç fazlası ve standart dışı malzemelerinin bedelli veya bedelsiz devir işlemleri 12/4/2001 tarihli ve 4645 sayılı Emniyet Genel Müdürlüğüne Ait Araç, Gereç, Mal ve Malzemenin Satış, Hibe, Hek ve Hurda Durum ve İşlemleri ile Hizmet Satışına Dair Kanun hükümlerine göre yürütülür. Ayrıca, Jandarma Genel Komutanlığı, 30/5/1985 tarihli ve 3212 sayılı Silahlı Kuvvetler İhtiyaç Fazlası Mal ve Hizmetlerinin Satış, Hibe, Devir ve Elden Çıkarılması; Diğer Devletler Adına Yurt Dışı ve Yurt İçi Alımların Yapılması ve Eğitim Görecek Yabancı Personel Hakkında Kanun kapsamında Türk Silahlı Kuvvetlerinin yararlandığı hak ve imkânlardan aynen yararlanır. (Ek fıkra: 17/4/2017-KHK-690/21 md.; Aynen kabul: 1/2/2018-7077/18 md.) Bütçe kanunları ve diğer kanunlarla Milli Savunma Bakanlığı ile Türk Silahlı Kuvvetlerine tanınan gümrük, her türlü vergi, resim, harç ve ardiye ücretlerine ilişkin muafiyet ve istisna hükümleri Jandarma Genel Komutanlığı hakkında da uygulanır.",
  "Jandarma Kanunu m.20": "Madde 20 – Jandarma Genel Komutanlığı personeli; bu Kanunla getirilen hakların yanısıra, özlük hakları bakımından, 926 sayılı \\\"Türk Silahlı Kuvvetleri Personel Kanunu\\\", 657 sayılı \\\"Devlet Memurları Kanunu\\\" ile genel ve özel düzenleme getiren diğer kanunlarla verilen haklardan da yararlanır.",
  "Jandarma Kanunu m.21": "Madde 21 – (Değişik: 13/7/1993 – KHK – 486/18 md.)\nJandarma Genel Komutanlığı fiili kadrolarına atanmış subay, astsubay ve uzman jandarma ve uzman erbaşlara; 657 sayılı Devlet Memurları Kanununda belirtilen en yüksek Devlet memuru aylığının (ek gösterge dahil);\na) Komando ve sınır birliklerinde % 52,\nb) Diğer karargah, birlik ve kurumlarda % 40,\ntutarını geçmemek üzere İçişleri Bakanlığınca belirlenecek usul ve esaslara göre fazla çalışma karşılığı asayiş tazminatı ödenir. Bu tazminattan damga vergisi hariç herhangi bir vergi ve kesinti yapılmaz.",
  "Jandarma Kanunu m.22": "Madde 22 – Uzman jandarmaların hizmet süreleri, giyim, kuşam, beslenme usulleri ve diğer özlük hakları ile erbaş ve erlerin kaynakları, hizmet süreleri, kıyafetleri özel kanunlarında gösterildiği gibidir.",
  "Jandarma Kanunu m.24": "Madde 24 – (Değişik: 27/5/2016-KHK-668/17 md.; Aynen kabul: 8/11/2016-6755/17 md.) Bu Kanunla münhasıran yönetmelik çıkarılması öngörülen hususların yanısıra jandarmanın teşkilat, görev, yetki ve sorumlulukları, diğer makamlarla ilişkileri, birlikte çalışma ve işbirliği esasları dahil komuta ve kontrol ilişkileri ile Jandarma (…) personelinin terfi işleri, değerlendirme, ödüllendirme, kılık ve kıyafet ve Kanunun uygulanmasına ilişkin diğer hususlar; Cumhurbaşkanınca yürürlüğe konulan yönetmelikle düzenlenir.",
  "Jandarma Kanunu m.26": "Yürürlük:\nMadde 26 – Bu Kanun yayımı tarihinde yürürlüğe girer.",
  "Jandarma Kanunu m.4": "Madde 4 – (Değişik: 25/7/2016-KHK-668/6 md.; Aynen kabul: 8/11/2016-6755/6 md.)\nJandarma Genel Komutanlığı İçişleri Bakanlığına bağlıdır.",
  "Jandarma Kanunu m.5": "Madde 5 – (Değişik: 25/7/2016-KHK-668/7 md. ; Değiştirilerek kabul: 8/11/2016-6755/7 md.)\nJandarma Genel Komutanlığının kuruluş ve kadrolarıyla konuş yerleri, İçişleri Bakanlığınca düzenlenir. Ancak seferberlik ve savaşta Kuvvet Komutanlıkları emrine girecek birliklerin kuruluş ve kadrolarıyla konuş yerlerinin düzenlenmesinde Genelkurmay Başkanlığının görüşü alınır.\nJandarma birliklerinin kuruluş ve konuşlarının düzenlenmesinde mülki taksimat esas alınır. Ancak geçici olarak birden çok ili içine alan bölge teşkilatı da kurulabilir. Bölge komutanı, bölge teşkilatının konuşlu bulunduğu ilin valisine karşı sorumlu olarak görev yapar.",
  "Jandarma Kanunu m.6": "Madde 6 – (Değişik: 25/7/2016-KHK-668/8 md. ; Aynen kabul: 8/11/2016-6755/8 md.)\nJandarma Genel Komutanı tüm Jandarma Teşkilatının komutanıdır. (Mülga ikinci cümle: 2/7/2018 - KHK/703/128 md.)\nJandarma Genel Komutanı, Teşkilatın sevk ve idaresinden, kanun ve nizam hükümlerinin icrasını sağlamaktan, bunlara dayalı olarak verilen emir ve kararların uygulanmasından sorumludur.",
  "Jandarma Kanunu m.7": "Jandarmanın genel olarak görevleri:\nMadde 7 – (Değişik: 25/7/2016-KHK-668/9 md.; Aynen kabul: 8/11/2016-6755/9 md.)\nJandarmanın sorumluluk alanlarında genel olarak görevleri şunlardır.\na) Mülki görevleri;\nEmniyet ve asayiş ile kamu düzenini sağlamak, korumak ve kollamak, kaçakçılığı men, takip ve tahkik etmek, suç işlenmesini önlemek için gerekli tedbirleri almak ve uygulamak, ceza infaz kurumları ve tutukevlerinin dış korunmalarını yapmak, (b) ve (c) bentlerinde belirtilen görevler dışında kalan ve diğer kanun ve nizam hükümlerinin icrası ile bunlara dayalı emir ve kararlarla Jandarmaya verilen görevleri yapmak.\nb) Adli görevleri;\nİşlenmiş suçlarla ilgili olarak kanunlarda belirtilen işlemleri yapmak ve bunlara ilişkin adli hizmetleri yerine getirmek.\nc) Askeri görevleri;\nKanunlarla ve Cumhurbaşkanlığı kararnameleriyle verilen askeri hizmetleri yerine getirmek.",
  "Jandarma Kanunu m.8": "Jandarmanın (…) seferberlik ve savaş halindeki görevleri:\nMadde 8 – (Değişik: 25/7/2016-KHK-668/10 md.; Değiştirilerek kabul: 8/11/2016-6755/10 md.)\nJandarma birlikleri; seferberlik ve savaş hallerinde, Cumhurbaşkanı kararıyla belirlenecek bölümleriyle Kuvvet Komutanlıkları emrine girer, kalan bölümüyle normal görevlerine devam eder.\nAyrıca, Jandarma birlikleri; Genelkurmay Başkanlığının talebi üzerine İçişleri Bakanının, illerde ise garnizon komutanının talep etmesi halinde valinin onayıyla kendilerine verilen askeri görevleri de yaparlar.",
  "Jandarma Kanunu m.9": "Madde 9 – Kanun ve nizamlar ile bunlara dayalı olarak verilen emir ve kararların öngörmediği hiçbir görev jandarmadan istenemez. (Mülga ikinci cümle: 26/3/2002-4748/7 md.)",
  "Jandarma Kanunu m.Ek 7": "Ek Madde 7 - (Ek: 25/7/2016 –KHK- 668/19 md.; Değiştirilerek kabul: 8/11/2016-6755/19 md.)\nDiğer kanunlarda bu Kanuna aykırı hükümler bulunması halinde bu Kanun hükümleri uygulanır.\nBu Kanunun uygulanmasıyla ilgili tereddütleri gidermeye ve bu yönde düzenleyici ve yönlendirici işlemler yapmaya İçişleri Bakanlığı yetkilidir.\nBu Kanunda bu maddeyi ihdas eden Kanun ile yapılan düzenlemeler sebebiyle teşkilat, personel, eğitim ve diğer hususlarla ilgili olarak yeni ihtiyaçların ortaya çıkması halinde, buna ilişkin düzenleme yapmaya Cumhurbaşkanı yetkilidir.\n\nGeçici Madde 1: \"Bu Kanunun 24 üncü maddesiyle çıkarılması öngörülen yönetmelikler yürürlüğe girinceye kadar, 1 Aralık 1937 gün ve 2/7756 sayılı Kararname ile yürürlüğe konulmuş olan \\\"Jandarma Teşkilat ve Vazife Tüzüğü\\\" ile ek ve değişikliklerinin bu Kanuna aykırı olmayan hükümlerinin uygulanmasına devam edilir.\"\n\nGeçici Madde 3: \"Bu Kanunun yürürlüğe girdiği tarihte, yeterli polis bulunmaması nedeniyle jandarmanın polis sahalarındaki görev ve sorumluluğu devam eder. Polis miktarına bağlı olarak jandarma bu sahaları Emniyet Genel Müdürlüğüne devreder.\"\n\nGeçici Madde 5: \"Jandarma Genel Komutanlığının er ve erbaş ile askerlik yükümlüsü ihtiyacı, 21/6/1927 tarihli ve 1111 sayılı Askerlik Kanunu hükümleri çerçevesinde Milli Savunma Bakanlığı tarafından üç yıl süreyle karşılanır. Ancak Cumhurbaşkanı kararıyla; bu süre uzatılabilir. Bu suretle Jandarma Genel Komutanlığı emrine verilen er ve erbaşlar ile askerlik yükümlüleri hakkında, diğer er ve erbaşlar ile askerlik yükümlülerinin tabi olduğu hükümler uygulanır. Bunların giderleri Jandarma Genel Komutanlığı bütçesinden karşılanır.\"\n\nGeçici Madde 7: \"Jandarma Genel Komutanlığının halihazırda devam eden yabancı ülkeler ile eğitim ve işbirliği faaliyetleri askeri eğitim işbirliği anlaşmaları ve protokollerinde belirtilen esaslara göre İçişleri Bakanlığı tarafından yürütülür.\"\n\nJandarma Genel Komutanlığı bünyesindeki deniz birlik ve tesisleri ile buralarda hizmet yapan sivil memur ve işçiler; 9/7/1982 gün ve 2692 sayılı Kanunla kurulup 1985 yılına kadar Jandarma Genel Komutanlığına bağlı olarak görev icra edecek Sahil Güvenlik Komutanlığına geçerler.\" (Geçici Md.2)\n\nYürürlük:\nMadde 26 – Bu Kanun yayımı tarihinde yürürlüğe girer.",
  "Jandarma Teşkilat Yön m.1": "MADDE 1- (1) Bu Yönetmeliğin amacı; jandarmanın teşkilat, görev, yetki ve sorumluluklarını, diğer makamlarla ilişkilerini, birlikte çalışma ve işbirliği esasları dahil komuta ve kontrol ilişkilerini düzenlemektir. MADDE 2- (1) Bu Yönetmelik, 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun 24 üncü maddesine dayanılarak hazırlanmıştır.",
  "Jandarma Teşkilat Yön m.10": "MADDE 10- (2) (...) il ve ilçelerdeki jandarma ve polis sorumluluk alanlarının sınırları, ilçelerde kaymakam, illerde vali veya görevlendireceği vali yardımcısı başkanlığında jandarma ve emniyet temsilcilerinin katılacağı bir komisyon tarafından belirlenir. (...) Büyükşehir, il veya ilçe belediyesi kurulması, kaldırılması ya da kentleşme veya diğer sebeplerle sınırlarda değişiklik olması halinde, değişikliğin yürürlüğe girdiği tarihten itibaren en geç üç ay içerisinde sorumluluk alanları yeniden düzenlenir. (3) Komisyon tarafından alınan kararlar İçişleri Bakanının onayıyla yürürlüğe girer. (...) (4) Sorumluluk alanlarının sınırlarının belirlenmesinde kolluk birimleri arasındaki anlaşmazlıklar, mülki amir tarafından kesin olarak çözümlenir. (5) Sorumluluk alanını belirleyen karar doğrultusunda devir ve teslim ile ilgili işlemler en geç üç ay içerisinde tamamlanır.",
  "Jandarma Teşkilat Yön m.11": "MADDE 11- (1) Jandarma; a) Halkın can, ırz ve malını korur. b) Suç işlenmesini önlemek ve kamu düzenini sağlamak için gerekli önlemleri alır. c) Asayişi, kamunun ve kişilerin güvenliğini ve konut dokunulmazlığını korur. ç) Anayasada ve kanunlarda düzenlenen hak ve hürriyetlerin güvenli şekilde kullanılması için gerekli önlemleri alır. (...) e) Yardım isteyenlere, korunmaya muhtaç çocuklarla yardım gereken küçüklere, engelli, hasta, yaşlı kimselerle, düşkün ya da kimsesizlere ve yabancılara yardım eder. f) Her türlü kaçakçılığa engel olur. g) Ceza infaz kurumlarının dış korumalarını sağlayıcı önlemleri alır (...). ı) Trafik hizmetlerini yürütür (...).",
  "Jandarma Teşkilat Yön m.24": "MADDE 24- (1) Ceza infaz kurumlarının dış korunması jandarmaya aittir. (...) (2) Jandarma, ceza infaz kurumlarının dışarıdan emniyet ve koruma tedbirlerini almak, tutuklu ve hükümlülerin kaçmalarına engel olmakla görevlidir. Jandarmaların hükümlü ve tutuklularla görüşmeleri ve ilişki kurmaları, ceza infaz kurumlarının içindeki iş ve işlemlere karışmaları yasaktır. (...) (3) Jandarma hiçbir şekilde ceza infaz kurumlarının iç işlerinde ve infaz koruma memurluğu görevlerinde kullanılamaz.",
  "Jandarma Teşkilat Yön m.25": "MADDE 26- (1) Bir ceza infaz kurumundan diğer bir ceza infaz kurumuna gönderilmesi gereken tutuklu ve hükümlüler, kanunen yetkili makamın yazılı istemi üzerine, jandarma kuvvetlerince istenilen yere götürülürler. MADDE 27- (1) Hükümlü ve tutukluların sevk ve nakillerinin bu iş için ayrılmış olan ceza infaz kurumu araçlarıyla yapılması esastır. (...) (3) Jandarmaya ait hizmet araçları sevklerde kullanılmaz. MADDE 29- (1) İştirak halinde suç işlemiş olanlar ile kanunen önemli ilişki sayılacak derecede yakınlığı olanlar dışında; erkek ve kadın tutuklu ya da hükümlüler, birlikte sevk edilemez. (2) Sevk edilen tutuklu ve hükümlünün kadın olması durumunda, kadın ceza infaz koruma görevlisi verilir. MADDE 32- (1) (...) firara teşebbüs etmeleri durumunda firarın başka şekilde önlenmesine imkân bulunmazsa silah kullanılır. MADDE 33- (1) Sevk ve nakillerde, gidilecek yere gündüz varılacak biçimde hareket edilir.",
  "Jandarma Teşkilat Yön m.3": "a) Asayiş: Hukuka uygun ve gerekli önlemlerin alınması sonucu, Devlete, topluma, kişilere, mal ve eşyalara yönelik tehlike, kaza ve sabotajların söz konusu olmadığı bir ortamı, düzensizlik ve karışıklıkların önlendiği, hayatın normal akışının sağlandığı hali, dirlik ve düzenin varlığı konusunda kamuda oluşan yerleşik ve yaygın inancı, (...) d) Emniyet: Devlete, topluma, kişilere, mal ve eşyalara yönelik tehlike, kaza ve sabotajları önlemek için alınan hukuka uygun önlemlerin tümünü ve bu önlemlerin alınmış bulunduğu hali, (...) i) Kamu düzeni: Emniyet ve asayiş, huzur ve sükun, genel sağlık ve genel ahlak unsurlarından oluşan, hak ve hürriyetlerin tam olarak kullanımına elverişli ortamı, (...) ifade eder.\n\ne) Genel kolluk: Kamu düzeninin korunmasını sağlayan, mevzuatla verilen görevleri yerine getiren ve silah kullanma yetkisini haiz Bakanlığa bağlı jandarma, sahil güvenlik ve polisi, (...) j) Kapalı yerler: Konut, işyerleri ve eklentileri ile bunların dışında olsa bile zilyedinin rızası bulunmadıkça girilmemesi gerektiğini belirtir şekilde etrafı çit, parmaklık, duvar ve benzeri engellerle çevrili yerleri (...), l) Mülki amir: İllerde vali, ilçelerde kaymakamı, m) Özel kolluk: Devlet ve yetkili diğer kamu tüzel kişilerince, özel kanunlar çerçevesinde kurulup teşkilatlandırılan, kendi görev alanında güvenliği sağlamak amacı taşıyan ve jandarma, sahil güvenlik ve polis dışındaki kolluk birimlerini, ifade eder.",
  "Jandarma Teşkilat Yön m.39": "MADDE 39- (1) Ceza muhakemesine ilişkin olarak suçların soruşturulması ve kovuşturulmasına ilişkin hususlar, 5271 sayılı Kanunda öngörülen usul ve esaslara göre yürütülür. Adli görevler bakımından ilgili mevzuat ve adli amirlerin talimatlarına göre hareket edilir. MADDE 40- (1) Gözaltına alınan şahısların sadece adli makamlar önüne çıkarılıncaya kadarki yeme, içme ve nakil masrafları ile sevkin Jandarma Genel Komutanlığına ait taşıtlarla gerçekleştirilmesi durumunda, söz konusu taşıta ait yakıt ve benzeri masraflar Jandarma Genel Komutanlığı bütçesinden ödenir.",
  "Jandarma Teşkilat Yön m.4": "MADDE 4- (1) Jandarma Genel Komutanlığı Bakanlığa bağlıdır. Jandarma Genel Komutanı, Bakana karşı sorumludur.",
  "Jandarma Teşkilat Yön m.41": "MADDE 41- (1) Jandarma birlikleri; seferberlik ve savaş hallerinde, Bakanlar Kurulu kararıyla belirlenecek bölümleriyle kuvvet komutanlıkları emrine girer, kalan bölümüyle normal görevlerine devam eder. Jandarma, seferberlik ve savaş halinde, 4/11/1983 tarihli ve 2941 sayılı Seferberlik ve Savaş Hali Kanunu ile verilen görevleri yapar. (2) Jandarma birlikleri; Genelkurmay Başkanlığının talebi üzerine Bakanın, illerde ise garnizon komutanının talep etmesi halinde valinin onayıyla kendilerine verilen askeri görevleri de yapar (...).",
  "Jandarma Teşkilat Yön m.42": "MADDE 42- (1) Jandarma sorumluluk alanında, mülki ve adli görevlerinin ifası sırasında 2803 sayılı Kanun, 4/7/1934 tarihli ve 2559 sayılı Polis Vazife ve Salâhiyet Kanunu ve 5271 sayılı Kanun ile diğer mevzuat hükümlerine göre hareket eder. Jandarma bu görevlerini yerine getirirken polisin sahip olduğu yetki ve sorumluluklara sahiptir. (2) Jandarma amirinden aldığı emri Anayasa, kanun, tüzük ve yönetmelik hükümlerine aykırı görürse yerine getirmez ve bu aykırılığı emri verene bildirir. Ancak, amir emrinde ısrar eder ve bu emrini yazılı olarak tekrar ederse emir yerine getirilir. Bu halde, emri yerine getiren sorumlu olmaz. Konusu suç teşkil eden emir hiçbir suretle yerine getirilmez. Yerine getirenler sorumluluktan kurtulamaz. (...)\n\n(2) (...) Aşağıda yazılı hallerde; a) Can, ırz veya mal emniyetini korumak için, b) Devletin güvenliğine karşı işlenen suçların faillerini yakalamak veya delillerini tespit etmek için, (...) e) Kolluk kuvvetlerinin elinden kaçmakta olan şahısların yakalanması için, f) İşlenmekte olan bir suçun işlenmesine veya devamına mani olmak için, g) 5271 sayılı Kanun ile diğer kanunlar uyarınca kolluk kuvvetleri tarafından suç delillerinin tespiti veya suç faillerinin yakalanması maksadıyla yapılacak aramalar için, ğ) Kanunsuz toplantı veya kanunsuz yürüyüşleri dağıtmak veya failleri yakalamak için, (...) yetkili amir tarafından verilecek sözlü emirler derhal yerine getirilir. Bu emirlerin yazılı olarak verilmesi istenilemez. Bu hallerde emrin yerine getirilmesinden doğabilecek sorumluluk emri verene aittir. (...)",
  "Jandarma Teşkilat Yön m.46": "MADDE 46- (1) Jandarma, kişileri ve araçları; a) Bir suç veya kabahatin işlenmesini önlemek, b) Suç işlendikten sonra kaçan faillerin yakalanmasını sağlamak, işlenen suç veya kabahatlerin faillerinin kimliklerini tespit etmek, c) Hakkında yakalama emri ya da zorla getirme kararı verilmiş olan kişileri tespit etmek, ç) Kişilerin hayatı, vücut bütünlüğü veya malvarlığı bakımından ya da topluma yönelik mevcut veya muhtemel bir tehlikeyi önlemek, amacıyla durdurabilir. (2) Durdurma yetkisinin kullanılabilmesi için jandarmanın tecrübesine ve içinde bulunulan durumdan edindiği izlenime dayanan makul bir sebebin bulunması gerekir. Süreklilik arz edecek, fiili durum ve keyfilik oluşturacak şekilde durdurma işlemi yapılamaz. (...) (6) (...) Bu amaçla kişinin üzerindeki elbisenin çıkarılması veya aracın dışarıdan bakıldığında içerisi görünmeyen bölümlerinin açılması istenemez. Ancak el ile dıştan kontrol hariç, kişinin üstü ve eşyası ile aracının dışarıdan bakıldığında içerisi görünmeyen bölümlerinin aranması, Bakanlık tarafından belirlenen esaslar dahilinde mülki amirin görevlendireceği kolluk amirinin yazılı, acele hallerde sonradan yazıyla teyit edilmek üzere sözlü emriyle yapılabilir. Kolluk amirinin kararı yirmidört saat içinde görevli hakimin onayına sunulur. Bu fıkra kapsamında yapılan araç aramalarına ilişkin olarak kişiye, arama gerekçesini de içeren bir belge verilir. (...)",
  "Jandarma Teşkilat Yön m.47": "MADDE 47- (1) Jandarma, tehlikenin veya suç işlenmesinin önlenmesi amacıyla usulüne göre verilmiş sulh ceza hakiminin kararı veya bu sebeplere bağlı olarak gecikmesinde sakınca bulunan hallerde mülki amirin vereceği yazılı emirle kişilerin üstlerini, araçlarını, özel kağıtlarını ve eşyasını arar (...). (2) Arama talep yazısında, arama için makul sebeplerin oluştuğunun gerekçeleriyle birlikte gösterilmesi gerekir. (3) Arama kararında veya emrinde aşağıdaki hususlar belirtilir. a) Sebebi. b) Konusu ve kapsamı. c) Yapılacağı yer. ç) Yapılacağı zaman ve geçerli olacağı süre. (4) Önleme araması aşağıdaki yerlerde yapılabilir. a) (...) toplantı ve gösteri yürüyüşlerinin yapıldığı yerde veya yakın çevresinde. (...) c) Halkın topluca bulunduğu veya toplanabileceği yerlerde. (...) d) Umumi veya umuma açık yerlerde. e) Her türlü toplu taşıma araçları ile seyir halindeki taşıtlarda. (5) Konutta, yerleşim yerinde ve kamuya açık olmayan işyerlerinde ve eklentilerinde önleme araması yapılamaz. (6) Spor karşılaşması, miting, konser, festival, toplantı ve gösteri yürüyüşünün düzenlendiği veya aniden toplulukların oluştuğu hallerde gecikmesinde sakınca bulunan hal var sayılır.",
  "Jandarma Teşkilat Yön m.48": "MADDE 48- (1) Jandarma; a) İmdat istenmesi veya yangın, su baskını ve boğulma gibi büyük tehlikelerin haber verilmesi veya görülmesi hallerinde bu tehlikelerden kişileri kurtarmak amacıyla, b) Bir suçun işlenmesine veya işlenmekte olan bir suçun devamına engel olmak için, konutlara, işyerlerine ve eklentilerine girebilir.",
  "Jandarma Teşkilat Yön m.5": "MADDE 5- (1) Jandarma teşkilatı aşağıda belirtilen merkez ve taşra teşkilatı ile doğrudan merkeze bağlı birimlerden oluşur. a) Merkez teşkilatı (...) b) Taşra teşkilatı şunlardır: 1) Jandarma bölge komutanlıkları. 2) İl jandarma komutanlıkları. 3) İlçe jandarma komutanlıkları. (...) c) Doğrudan merkeze bağlı birimler (...) MADDE 6- (1) Jandarma birimlerinin konuşlarının düzenlenmesinde, mülki taksimat esas alınır. (...) Her düzeydeki jandarma birlikleri Bakan onayı ile kurulabilir. (...) (4) (...) İlçe jandarma komutanlıklarının sorumluluk alanı bir ya da birden çok karakol sorumluluk bölgesine ayrılabilir. (...) (7) Karakolların sorumluluk bölgeleri il jandarma komutanının önerisi üzerine valinin onayı, karakolların konuş yerleri ise Bakan onayı ile belirlenir. Geçici asayiş karakolları ile jandarma hizmet merkezleri, il jandarma komutanının önerisi üzerine valinin onayıyla teşkil edilir.",
  "Jandarma Teşkilat Yön m.52": "MADDE 52- (1) Jandarma Genel Komutanı, jandarma teşkilatının komutanıdır. (...) (3) Jandarma Genel Komutanı; teşkilatın sevk ve idaresinden (...) Bakana karşı sorumludur. MADDE 54- (1) Jandarma bölge komutanları (...) bölge komutanlığının konuşlu olduğu ilin valisinin onayıyla; terörle mücadele kapsamında operasyonları planlamak (...) görevlidir. (...) (2) (...) bölge komutanı (...) bölge komutanlığının konuşlu olduğu ilin valisine karşı sorumludur. MADDE 55- (1) İl jandarma komutanları, il jandarma teşkilatının komutanıdır. (...) MADDE 56- (1) İlçe jandarma komutanları, ilçe jandarma teşkilatının komutanıdır. (...) MADDE 57- (1) Jandarma karakol komutanları, karakolun komutanıdır.",
  "Jandarma Teşkilat Yön m.58": "MADDE 58- (1) Jandarma Genel Komutanlığı, Bakanlığa bağlıdır. Bakan, jandarma teşkilatının en üst amiridir ve teşkilatı idare eder. (...) (2) Jandarma bölge komutanları konuşlu olduğu ilin valisine, il ve ilçe jandarma komutanları ise mülki amirlere bağlı ve sorumlu olarak görev yapar. (3) Mülki amirler ile adli makamlar mevzuat hükümlerine uygun olarak jandarma komutanlarına ve diğer jandarma personeline doğrudan emir verme yetkisine sahiptir. Diğer makamlar jandarmaya görev olarak verilmesini istedikleri konunun kanuni dayanaklarını belirterek o yerin mülki amirine başvurur (...). (4) Jandarma birimleri, aldıkları görevin yürütülmesi bakımından, kendi amirlerinin emir komutası altında ve silsile esasına göre sevk ve idare edilir. (5) Emniyet ve asayiş görevlerinden doğrudan doğruya sorumlu olan mülki amir, bu görevlerin yürütülmesini jandarmanın sorumluluk alanında, jandarma aracılığıyla sağlar. (6) Jandarma birimlerindeki her kademedeki amir ve personel, görevlerini kanunlara uygun yürütmekten ve yetkilerini amaca uygun bir tarzda kullanmaktan, mülki amirlere karşı sorumludur. (7) Jandarma birimlerinin üstlendikleri görevin yapılmasında kullanacakları araç ve gereçlerin seçimi kendi komutanlarına aittir. Mülki amirler özellik taşıyan ve yetersiz kalınan durumlarda gereken araç ve gereçleri diğer kamu kurum ve kuruluşlarından sağlayarak jandarmanın hizmetine verebilir.",
  "Jandarma Teşkilat Yön m.59": "MADDE 59- (1) Jandarma; bölgelerindeki her türlü suçları ve sonuçlarını, ülkenin emniyet ve asayişini bozan ya da bozacak olan olayları, yangın, su baskını gibi afetleri, haber aldıkları salgın ve bulaşıcı hastalıkları, Devletin ülkesi ve milletiyle bölünmez bütünlüğünü, nitelikleri Anayasada gösterilen Cumhuriyeti yıkmaya, sarsmaya ve bölmeye yönelik propagandalar konusunda edindikleri bilgileri, il veya ilçenin asayiş veya güvenliğini etkileyecek mahiyetteki kovuşturma ve soruşturmaları, vakit geçirmeksizin mülki amire sözlü ya da yazılı olarak bildirir. Suçla ilgili görülen olaylar aynı zamanda Cumhuriyet savcılığına da bildirilir.",
  "Jandarma Teşkilat Yön m.60": "MADDE 60- (1) Jandarma Genel Komutanlığı merkez ve taşra teşkilatları birbirleriyle; mahalli vakalar hakkında malumat istemek ve teknik, muhasebe, lojistik ve özlük konularına dair işlemler haricinde resen muhabere edemez ve yazışma yapamaz. Taşra teşkilatının merkez teşkilatıyla, merkez teşkilatının taşra teşkilatıyla yapacağı yazışmalar Bakanlık ve mülki amirler aracılığı ile yapılır. Hak ve yükümlülük doğuran ve Bakanlık ya da Jandarma Genel Komutanlığı adına irade beyanı niteliği taşıyan yazışmalar, her halükarda valilikler aracılığıyla yapılır. (...) (4) Bakanlığa gönderilecek asayiş raporlarından jandarmanın sorumluluk alanında meydana gelen olaylara ait bulunanlar, il jandarma komutanlığınca hazırlanır ve vali imzasıyla gönderilir.",
  "Jandarma Teşkilat Yön m.61": "MADDE 61- (1) Jandarma, 5271 sayılı Kanun ve diğer mevzuatta yazılı soruşturma işlemlerine ilişkin görevleri yerine getirir, il ve ilçenin emniyet ve asayişini, genel hayatın akışını ilgilendiren olaylarda mülki amire bilgi verir. MADDE 62- (1) Adli kolluk makamları ile işbirliği Adlî Kolluk Yönetmeliğine göre yürütülür. MADDE 63- (1) İcra müdürlüklerinin talebi üzerine kolluk kuvvetleri tarafından yakalanan araçlar, en yakın yediemin otoparkına teslim edilerek en geç üç işgünü içinde en yakın icra müdürlüğüne teslim alınması için bildirimde bulunulur. MADDE 64- (1) Jandarmanın askeri makamlarla ilişkisi 8 inci ve 41 inci maddelerde belirtilen hallerle sınırlıdır.",
  "Jandarma Teşkilat Yön m.65": "MADDE 65- (1) Jandarma sorumluluk alanında herhangi bir suçla karşılaşan sahil güvenlik veya polis, olaya müdahale etmek ve jandarmaya da haber vermek, jandarmanın istemi üzerine gerekli yardımı yapmakla yükümlüdür. Bu gibi durumlarda, sahil güvenlik ve polis, jandarma gelinceye kadar olay yerinde soruşturma yapamaz, durumu olduğu gibi koruyarak delillerin kaybolmaması için gereken önlemleri alır. (...) (2) Zorunlu durumlarda, jandarma da sahil güvenlik veya polis sorumluluk alanında birinci fıkradaki hükümlere uygun olarak hareket eder. (...) (6) Jandarma, sahil güvenlik ve polisin birlikte çalışmalarına gerek duyulan durumlarda, operasyona katılan birimlerin komuta, sevk ve idaresinin hangi kolluk kuvvetine ait olduğu mülki amir tarafından belirlenir.",
  "Jandarma Teşkilat Yön m.7": "MADDE 7- (1) Jandarmanın genel olarak görev ve sorumluluk alanı, polis ve sahil güvenlik teşkilatının görev alanının dışı olup, bu alanlar il ve ilçe belediye sınırları dışında kalan ya da polis ve sahil güvenlik teşkilatı bulunmayan yerlerdir. Ancak, belediye sınırları içinde olmakla birlikte, hizmet gerekleri bakımından uygun görülen yerler, jandarmanın görev ve sorumluluk alanı olarak belirlenebilir. Bakanın kararıyla bir il veya ilçenin tamamı polis ya da jandarma görev ve sorumluluk alanı olarak belirlenebilir.",
  "Jandarma Teşkilat Yön m.70": "MADDE 70- (1) Jandarma birimlerinde, emniyet ve asayişle ilgili görev alan personelin resmi kıyafet ile görev yapmaları esastır. Ancak suç ve suçluların gizli olarak takibi (...) için gerek görüldüğünde mülki amirin veya il jandarma komutanının izni ile görevin icap ettirdiği değişik kılık ve kıyafetle de hizmet yürütülebilir. MADDE 71- (1) (...) jandarma, sahil güvenlik ve emniyet teşkilatı, kendi sorumluluk alanında yetersiz kaldıkları takdirde (...) geçici bir süre için birbirlerinin sorumluluk alanlarında görevlendirilebilirler. Bu görev hiç bir zaman süreklilik taşımaz (...). (2) Bu madde kapsamındaki görevlendirmeler mülki amirin onayı ile yapılır. MADDE 72- (2) Görevlendirilen ekiplerin kolluk yetkilerini kullanması, jandarma sorumluluk alanı ile sınırlı değildir. (...) MADDE 73- (1) Bakanın onayı ile; Jandarma Genel Komutanlığı, Sahil Güvenlik Komutanlığı ve Emniyet Genel Müdürlüğü silah, mühimmat, teçhizat, taşıt ve diğer taşınırları ile taşınmazlarını birbirlerine geçici olarak tahsis edebilirler veya bedelsiz olarak devredebilirler.",
  "Jandarma Teşkilat Yön m.74": "MADDE 74- (1) Yoklama kaçakları ve bakayalar, askerlik ödevlerini yerine getirmek maksadıyla yakalanmaları için Millî Savunma Bakanlığınca Bakanlığa, askerlik şubelerince de mülki amire bildirilirler. Yakalanarak muhafaza altına alınan yükümlüler, vakit geçirmeksizin ve en geç yirmidört saat içerisinde en yakın askerlik şubesine getirilirler. Askerlik şubesince teslim alınamayan yükümlüler, jandarma tarafından hazırlanan tutanağa istinaden derhal serbest bırakılırlar. (2) Firar, izin veya hava değişimi tecavüzünde olan yükümlülerden haklarında adli makamlarca çıkarılmış yakalama kararları olanlar, ele geçirilinceye kadar jandarma tarafından aranır.",
  "Jandarma Teşkilat Yön m.75": "MADDE 75- (1) Jandarma birimleri, emniyet ve asayiş ile kamu düzeninin korunmasını sağlamak ve olaylara etkili biçimde müdahale edebilmek amacıyla suçları önleme ve suçlara müdahale planı, doğal afet ve yardım planı ile koruma ve müdahale harekat planı hazırlar. (3) Planlar, mülki amirin onayı ile yürürlüğe konulur. (4) Planların birer örneği; mülki amirlikler, jandarma, sahil güvenlik ve polisin ilgili birimlerinde saklanır ve Jandarma Genel Komutanlığına gönderilir.",
  "Jandarma Teşkilat Yön m.76": "MADDE 76- (1) Jandarma teşkilatının (...) hedeflerinin belirlenmesi için hazırlanan ve beş yıllık bir dönemi kapsayan Jandarma Genel Komutanlığı stratejik hedef planı Bakan onayı ile yürürlüğe konulur. Bu plan en az iki yılda bir gözden geçirilir.",
  "Jandarma Teşkilat Yön m.80": "MADDE 80- (1) 3/11/1983 tarihli ve 83/7362 sayılı Bakanlar Kurulu Kararı ile yürürlüğe konulan Jandarma Teşkilatı Görev ve Yetkileri Yönetmeliği yürürlükten kaldırılmıştır. (2) (...) İşyeri Açma ve Çalışma Ruhsatlarına İlişkin Yönetmeliğin 39 uncu maddesinin birinci fıkrası (...) değiştirilmiştir.",
  "Jandarma Teşkilat Yön m.9": "MADDE 9- (1) Jandarma sorumluluk alanı dışında olmakla birlikte; a) Polis teşkilatı kurulmamış olması nedeniyle, b) Özel kolluk kuruluşlarının sorumluluk alanına giren yerlerde, jandarmayı ilgilendiren ihlal ya da suç işlenmesi nedeniyle, c) Özel kolluk kuruluşlarının sorumluluk alanına giren konularda, bu kuruluş ve kuvvetlerin yokluğundan ötürü meydana gelen ihlal ya da suçlar nedeniyle, jandarmanın görevlendirilmesi ya da kendiliğinden olaya elkoyması mümkündür. Bu gibi durumlarda jandarmanın görev yaptığı o yer, jandarmanın görev alanı sayılır. (2) Kamu ve özel hukuk tüzel kişilerine ait kurum ve kuruluşların, kendi tesis ve yapılarının iç güvenliğinin sağlanması, bu kurum ve kuruluşlarca kendi mevzuatına göre yürütülür. Özel hallerde, geçici olarak koruma ve kollama görevi verilmesi hususunda mülki amirin yetkisi saklıdır.",
  "Kabahatler m.1": "(1) Bu Kanunda; toplum düzenini, genel ahlâkı, genel sağlığı, çevreyi ve ekonomik düzeni korumak amacıyla; a) Kabahatlere ilişkin genel ilkeler, b) Kabahatler karşılığında uygulanabilecek olan idarî yaptırımların türleri ve sonuçları, c) Kabahatler dolayısıyla karar alma süreci, d) İdarî yaptırıma ilişkin kararlara karşı kanun yolu, e) İdarî yaptırım kararlarının yerine getirilmesine ilişkin esaslar, belirlenmiş ve çeşitli kabahatler tanımlanmıştır.",
  "Kabahatler m.11": "(1) Fiili işlediği sırada onbeş yaşını doldurmamış çocuk hakkında idarî para cezası uygulanamaz.\n\n(2) Akıl hastalığı nedeniyle, işlediği fiilin hukukî anlam ve sonuçlarını algılayamayan veya bu fiille ilgili olarak davranışlarını yönlendirme yeteneği önemli derecede azalmış olan kişi hakkında idarî para cezası uygulanmaz.",
  "Kabahatler m.13": "(1) Kabahate teşebbüs cezalandırılmaz. Ancak, teşebbüsün de cezalandırılabileceğine dair ilgili kanunda hüküm bulunan haller saklıdır. Bu durumda, Türk Ceza Kanununun suça teşebbüse ve gönüllü vazgeçmeye ilişkin hükümleri, kabahatler bakımından da uygulanır.",
  "Kabahatler m.14": "(1) Kabahatin işlenişine birden fazla kişinin iştirak etmesi halinde bu kişilerin her biri hakkında, fail olarak idarî para cezası verilir.\n(2) Özel faillik niteliğinin arandığı durumlarda, kabahate iştirak eden ve bu niteliği taşımayan kişi hakkında da fail olarak idarî para cezası verilir.\n(3) Kabahate iştirak için kasten ve hukuka aykırı işlenmiş bir fiilin varlığı yeterlidir...\n(4) Kanunda özel faillik niteliğini taşıyan kişi açısından suç, diğer kişiler açısından kabahat olarak tanımlanan fiilin... ortaklaşa işlenmesi halinde suça iştirake ilişkin hükümler uygulanır.",
  "Kabahatler m.15": "(1) Bir fiil ile birden fazla kabahatin işlenmesi halinde bu kabahatlere ilişkin tanımlarda sadece idarî para cezası öngörülmüşse, en ağır idarî para cezası verilir. Bu kabahatlerle ilgili olarak kanunda idarî para cezasından başka idarî yaptırımlar da öngörülmüş ise, bu yaptırımların her birinin uygulanmasına karar verilir.\n\n(2) Aynı kabahatin birden fazla işlenmesi halinde her bir kabahatle ilgili olarak ayrı ayrı idarî para cezası verilir. Kesintisiz fiille işlenebilen kabahatlerde, bu nedenle idarî yaptırım kararı verilinceye kadar fiil tek sayılır.\n\n(3) Bir fiil hem kabahat hem de suç olarak tanımlanmış ise, sadece suçtan dolayı yaptırım uygulanabilir. Ancak, suçtan dolayı yaptırım uygulanamayan hallerde kabahat dolayısıyla yaptırım uygulanır.",
  "Kabahatler m.16": "(1) Kabahatler karşılığında uygulanacak olan idarî yaptırımlar, idarî para cezası ve idarî tedbirlerden ibarettir.\n(2) İdarî tedbirler, mülkiyetin kamuya geçirilmesi ve ilgili kanunlarda yer alan diğer tedbirlerdir.",
  "Kabahatler m.17": "(1) İdarî para cezası, maktu veya nispi olabilir.\n\n(2) İdarî para cezası, kanunda alt ve üst sınırı gösterilmek suretiyle de belirlenebilir. Bu durumda, idarî para cezasının miktarı belirlenirken işlenen kabahatin haksızlık içeriği ile failin kusuru ve ekonomik durumu birlikte göz önünde bulundurulur.\n\n(3) ... Cumhuriyet başsavcılıkları ve mahkemeler tarafından verilen idarî para cezaları Genel Bütçeye gelir kaydedilir. Sosyal güvenlik kurumları ile mahalli idareler tarafından verilen idarî para cezaları kendi bütçelerine gelir kaydedilir. ... Kişinin ekonomik durumunun müsait olmaması halinde, idarî para cezasının, ilk taksitinin peşin ödenmesi koşuluyla, bir yıl içinde ve dört eşit taksit halinde ödenmesine karar verilebilir. Taksitlerin zamanında ve tam olarak ödenmemesi halinde, idarî para cezasının kalan kısmının tamamı tahsil edilir.\n\n(6) Kabahat dolayısıyla idarî para cezası veren kamu görevlisi, ilgilinin rıza göstermesi halinde bunun tahsilatını derhal kendisi gerçekleştirir. Kanunlarında ödeme süresi düzenlenmemiş olan idari para cezaları, tebliğinden itibaren bir ay içinde ödenir.\n\n(6) ... İdari para cezasının ödeme süresi içinde ödenmesi halinde, cezadan %25 oranında indirim yapılır. Ödeme yapılması, kişinin bu karara karşı kanun yoluna başvurma hakkını etkilemez.\n\n(7) İdarî para cezaları her takvim yılı başından geçerli olmak üzere o yıl için ... yeniden değerleme oranında artırılarak uygulanır. ... Bu fıkra hükmü, nispi nitelikteki idarî para cezaları açısından uygulanmaz.",
  "Kabahatler m.18": "(1) Kabahatin konusunu oluşturan veya işlenmesi suretiyle elde edilen eşyanın mülkiyetinin kamuya geçirilmesine, ancak kanunda açık hüküm bulunan hallerde karar verilebilir.\n(4) Eşyanın mülkiyeti, kanunda açık hüküm bulunan hallerde ilgili kamu kurum ve kuruluşuna, aksi takdirde Devlete geçer.\n(7) Mülkiyeti kamuya geçirilen eşya, başka suretle değerlendirilmesi mümkün olmazsa imha edilir.\n\n(2) Mülkiyetin kamuya geçirilmesine ilişkin karar, eşyanın; a) Kullanılmaz hale getirilmesi, b) Niteliğinin değiştirilmesi, c) Ancak belli bir surette kullanılması koşullarından birinin yerine getirilmesine bağlı olarak belli bir süre geciktirilebilir...\n\n(5) Eşyanın mülkiyetinin kamuya geçirilmesine karar verilebilmesi için fail hakkında idarî para cezası veya başka bir idarî yaptırım kararı verilmiş olması şart değildir.\n\n(6) Kaim değerin mülkiyetinin kamuya geçirilmesine de karar verilebilir.",
  "Kabahatler m.2": "(1) Kabahat deyiminden; kanunun, karşılığında idarî yaptırım uygulanmasını öngördüğü haksızlık anlaşılır.",
  "Kabahatler m.20": "(1) Soruşturma zamanaşımının dolması halinde kabahatten dolayı kişi hakkında idarî para cezasına karar verilemez.\n(2) Soruşturma zamanaşımı süresi; a) Yüzbin Türk Lirası veya daha fazla idarî para cezasını gerektiren kabahatlerde beş, b) Ellibin Türk Lirası veya daha fazla cezayı gerektiren kabahatlerde dört, c) Ellibin Türk Lirasından az cezayı gerektiren kabahatlerde üç yıldır. Ancak, 1111 Askerlik, 2839 Milletvekili Seçimi, 2918 Karayolları Trafik, 2972, 3376, 4925, 5490 ve 6001 sayılı kanunlarda belirtilen ve idari para cezasını gerektiren fiilin işlendiği tarihi takip eden takvim yılının son günü bitimine kadar idari para cezası verilerek tebliğ edilmediği takdirde idari yaptırım kararı verilemez, verilmiş olanlar düşer.\n(3) Nispî idarî para cezasını gerektiren kabahatlerde zamanaşımı süresi sekiz yıldır.\n(4) Zamanaşımı süresi, kabahate ilişkin tanımdaki fiilin işlenmesiyle veya neticenin gerçekleşmesiyle işlemeye başlar.\n(5) Kabahati oluşturan fiilin aynı zamanda suç oluşturması halinde suça ilişkin dava zamanaşımı hükümleri uygulanır.",
  "Kabahatler m.21": "(1) Yerine getirme zamanaşımının dolması halinde idarî para cezasına veya mülkiyetin kamuya geçirilmesine ilişkin karar artık yerine getirilemez.\n(2) Yerine getirme zamanaşımı süresi; a) Ellibin Türk Lirası veya daha fazla cezaya karar verilmesi halinde yedi, b) Yirmibin Türk Lirası veya daha fazla cezada beş, c) Onbin Türk Lirası veya daha fazla cezada dört, d) Onbin Türk Lirasından az cezada üç yıldır.\n(3) Mülkiyetin kamuya geçirilmesine ilişkin zamanaşımı süresi on yıldır.\n(4) Zamanaşımı süresi, kararın kesinleşmesinin rastladığı takvim yılını takip eden takvim yılı başından itibaren işlemeye başlar.\n(5) Kanun hükmü gereği olarak idarî yaptırımın yerine getirilmesine başlanamaması veya yerine getirilememesi halinde zamanaşımı işlemez (durur).",
  "Kabahatler m.22": "(1) Kabahat dolayısıyla idarî yaptırım kararı vermeye ilgili kanunda açıkça gösterilen idarî kurul, makam veya kamu görevlileri yetkilidir.\n(2) Kanunda açık hüküm bulunmayan hallerde ilgili kamu kurum ve kuruluşunun en üst amiri bu konuda yetkilidir.",
  "Kabahatler m.23": "(1) Cumhuriyet savcısı, kanunda açıkça hüküm bulunan hallerde bir kabahat dolayısıyla idarî yaptırım kararı vermeye yetkilidir.\n(2) Bir suç dolayısıyla başlatılan soruşturma kapsamında bir kabahatin işlendiğini öğrenmesi halinde Cumhuriyet savcısı durumu ilgili kamu kurum ve kuruluşuna bildirebileceği gibi, kendisi de idarî yaptırım kararı verebilir.",
  "Kabahatler m.24": "(1) Kovuşturma konusu fiilin kabahat oluşturduğunun anlaşılması halinde mahkeme tarafından idarî yaptırım kararı verilir.",
  "Kabahatler m.25": "(1) İdarî yaptırım kararına ilişkin tutanakta; a) Hakkında idarî yaptırım kararı verilen kişinin kimlik ve adresi, b) İdarî yaptırım kararı verilmesini gerektiren kabahat fiili, c) Bu fiilin işlendiğini ispata yarayacak bütün deliller, d) Karar tarihi ve kararı veren kamu görevlilerinin kimliği, açık bir şekilde yazılır. Tutanakta, ayrıca kabahati oluşturan fiil, işlendiği yer ve zaman gösterilerek açıklanır.\n\n(1) ... (Tuzak kartı — yukarıdaki m.25/1 unsurları üzerinden, listede olmayan bir unsur sorulur.)",
  "Kabahatler m.26": "(1) İdarî yaptırım kararı, 7201 sayılı Tebligat Kanunu hükümlerine göre ilgili kişiye tebliğ edilir...\n(4) İdari yaptırım kararları ... elektronik ortamda tebliğ edilebilir. Elektronik ortamda yapılan tebligat, muhatabın elektronik adresine ulaştığı tarihi izleyen beşinci günün sonunda yapılmış sayılır.",
  "Kabahatler m.27": "(1) İdarî para cezası ve mülkiyetin kamuya geçirilmesine ilişkin idarî yaptırım kararına karşı, kararın tebliği veya tefhimi tarihinden itibaren en geç onbeş gün içinde, sulh ceza mahkemesine başvurulabilir. Bu süre içinde başvurunun yapılmamış olması halinde idarî yaptırım kararı kesinleşir.\n\n(2) Mücbir sebebin varlığı dolayısıyla bu sürenin geçirilmiş olması halinde bu sebebin ortadan kalktığı tarihten itibaren en geç yedi gün içinde karara karşı başvuruda bulunulabilir...\n\n(3) Başvuru, bizzat kanunî temsilci veya avukat tarafından sulh ceza mahkemesine verilecek bir dilekçe ile yapılır. Başvuru dilekçesi, iki nüsha olarak verilir.",
  "Kabahatler m.28": "(1) Başvuru üzerine mahkemece yapılan ön inceleme sonucunda; yetkisizlik halinde dosyanın yetkili mahkemeye gönderilmesine, süresinde yapılmama/incelenebilir karar olmama/hak bulunmama halinde başvurunun reddine, aksi halde başvurunun usulden kabulüne karar verilir.\n\n(3) İlgili kamu kurum ve kuruluşu, başvuru dilekçesinin tebliği tarihinden itibaren en geç onbeş gün içinde mahkemeye cevap verir...\n\n(10) Onbeşbin Türk Lirası dahil idarî para cezalarına karşı başvuru üzerine verilen kararlar kesindir.",
  "Kabahatler m.29": "(1) Mahkemenin verdiği son karara karşı, Ceza Muhakemesi Kanununa göre itiraz edilebilir. Bu itiraz, kararın tebliği tarihten itibaren en geç iki hafta içinde yapılır.\n(2) İtirazla ilgili karar, dosya üzerinden inceleme yapılarak verilir.",
  "Kabahatler m.3": "(1) Bu Kanunun; a) İdarî yaptırım kararlarına karşı kanun yoluna ilişkin hükümleri, diğer kanunlarda aksine hüküm bulunmaması halinde, b) Diğer genel hükümleri, idarî para cezası veya mülkiyetin kamuya geçirilmesi yaptırımını gerektiren bütün fiiller hakkında, uygulanır.",
  "Kabahatler m.30": "(1) Kanun yoluna başvuran kişi, bu konuda karar verilinceye kadar başvurusundan vazgeçebilir. Vazgeçme halinde bir daha aynı konuda başvuruda bulunulamaz.\n(2) İlgili kamu kurum ve kuruluşu da mahkeme tarafından karar verilinceye kadar kanun yolu başvurusunu kabul ederek idarî yaptırım kararını geri alabilir.",
  "Kabahatler m.32": "(1) Yetkili makamlar tarafından adlî işlemler nedeniyle ya da kamu güvenliği, kamu düzeni veya genel sağlığın korunması amacıyla, hukuka uygun olarak verilen emre aykırı hareket eden kişiye yüz Türk Lirası idarî para cezası verilir. Bu cezaya emri veren makam tarafından karar verilir.",
  "Kabahatler m.33": "(1) Dilencilik yapan kişiye, elli Türk Lirası idarî para cezası verilir. Ayrıca, dilencilikten elde edilen gelire elkonularak mülkiyetin kamuya geçirilmesine karar verilir.\n(2) Bu kabahat dolayısıyla idarî para cezasına ve elkoymaya kolluk veya belediye zabıta görevlileri, mülkiyetin kamuya geçirilmesine mülkî amir veya belediye encümeni karar verir.",
  "Kabahatler m.34": "(1) Kumar oynayan kişiye, bin Türk Lirası idarî para cezası verilir. Ayrıca, kumardan elde edilen gelire elkonularak mülkiyetin kamuya geçirilmesine karar verilir.\n(2) Bu kabahat dolayısıyla idarî para cezasına ve elkoymaya kolluk görevlileri, mülkiyetin kamuya geçirilmesine mülkî amir karar verir.",
  "Kabahatler m.35": "(1) Sarhoş olarak başkalarının huzur ve sükununu bozacak şekilde davranışlarda bulunan kişiye, kolluk görevlileri tarafından elli Türk Lirası idarî para cezası verilir. Kişi, ayrıca sarhoşluğun etkisi geçinceye kadar kontrol altında tutulur.",
  "Kabahatler m.36": "(1) Başkalarının huzur ve sükununu bozacak şekilde gürültüye neden olan kişiye, elli Türk Lirası idarî para cezası verilir.\n(2) Bu fiilin bir ticarî işletmenin faaliyeti çerçevesinde işlenmesi halinde işletme sahibi gerçek veya tüzel kişiye bin Türk Lirasından beşbin Türk Lirasına kadar idarî para cezası verilir.\n(3) Bu kabahat dolayısıyla idarî para cezasına kolluk veya belediye zabıta görevlileri karar verir.",
  "Kabahatler m.37": "(1) Mal veya hizmet satmak için başkalarını rahatsız eden kişi, elli Türk Lirası idarî para cezası ile cezalandırılır.\n(2) Bu kabahat dolayısıyla idarî para cezası vermeye kolluk veya belediye zabıta görevlileri yetkilidir.",
  "Kabahatler m.38": "(1) Yetkili makamların açık ve yazılı izni olmaksızın meydan, cadde, sokak veya yayaların gelip geçtiği kaldırımları işgal eden veya buralarda mal satışa arz eden kişiye, belediye zabıta görevlileri tarafından elli Türk Lirası idarî para cezası verilir.\n(2) ... meydan, cadde, sokak veya kaldırımlar üzerine inşaat malzemesi yığan kişiye ... yüz Türk Lirasından beşyüz Türk Lirasına kadar idarî para cezası verilir.",
  "Kabahatler m.39": "(1) Kamu hizmet binalarının kapalı alanlarında tütün mamulü tüketen kişiye, ilgili idarî birim amirinin yetkili kıldığı kamu görevlileri tarafından elli Türk Lirası idarî para cezası verilir...\n(2) Toplu taşıma araçlarında tütün mamulü tüketen kişiye, elli Türk Lirası idarî para cezası verilir...",
  "Kabahatler m.4": "(1) Hangi fiillerin kabahat oluşturduğu, kanunda açıkça tanımlanabileceği gibi; kanunun kapsam ve koşulları bakımından belirlediği çerçeve hükmün içeriği, idarenin genel ve düzenleyici işlemleriyle de doldurulabilir.\n(2) Kabahat karşılığı olan yaptırımların türü, süresi ve miktarı, ancak kanunla belirlenebilir.",
  "Kabahatler m.40": "(1) Görevle bağlantılı olarak sorulması halinde kamu görevlisine kimliği veya adresiyle ilgili bilgi vermekten kaçınan veya gerçeğe aykırı beyanda bulunan kişiye, bu görevli tarafından elli Türk Lirası idarî para cezası verilir.\n(2) ... kimliği belirlenemeyen kişi tutularak durumdan derhal Cumhuriyet savcısı haberdar edilir. Bu kişi, kimliği açık bir şekilde anlaşılıncaya kadar gözaltına alınır ve gerekirse tutuklanır.",
  "Kabahatler m.41": "(1) Evsel atık ve artıkları, bunların toplanmasına veya depolanmasına özgü yerler dışına atan kişiye, yirmi Türk Lirası idarî para cezası verilir...\n(7) Bu kabahatler dolayısıyla idarî para cezasına belediye sınırları içerisinde belediye zabıta görevlileri, belediye sınırları dışında kolluk görevlileri karar verir.\n(8) Bu kabahatler dolayısıyla meydana gelen kirliliğin kişi tarafından derhal giderilmesi halinde idarî para cezasına karar verilmeyebilir.",
  "Kabahatler m.42": "(1) Meydanlara/parklara, cadde-sokak kenarlarındaki kamuya ait duvar/alanlara, rızası olmaksızın özel kişilere ait alanlara afiş ve ilân asan kişiye, yüz Türk Lirasından üçbin Türk Lirasına kadar idarî para cezası verilir. Aynı içerikteki afiş ve ilânlar, tek fiil sayılır.\n(4) ... kolluk veya belediye zabıta görevlileri karar verir.",
  "Kabahatler m.42/A": "(1) 112 Acil Çağrı Merkezini meşgul etmek amacıyla arayarak görevlilerle konuşan veya ısrarla çağrı bırakan kişiye, il valileri tarafından binbeşyüz Türk Lirası idari para cezası verilir.\n(2) 112 Acil Çağrı Merkezine yapılan ihbarın asılsız olduğunun olay yerine giden ekiplerce tutanakla tespit edilmesi halinde kişiye, il valileri tarafından onbeşbin Türk Lirası idari para cezası verilir.\n(3) Bu maddede yazılı fiillerin bir yıl içinde tekrarı halinde idari para cezası iki katı olarak uygulanır.",
  "Kabahatler m.43": "(1) Yetkili makamlardan ruhsat almaksızın kanuna göre yasak olmayan silahları park, meydan, cadde veya sokaklarda görünür bir şekilde taşıyan kişiye, kolluk tarafından elli Türk Lirası idarî para cezası verilir.",
  "Kabahatler m.43/A": "(1) ... bir tüzel kişinin organ veya temsilcisi ... tarafından dolandırıcılık, uyuşturucu imal-ticareti, ihaleye/edime fesat, rüşvet, suçtan kaynaklanan malvarlığını aklama, zimmet, kaçakçılık, petrol piyasası suçu, terörizmin finansmanı suçunun tüzel kişinin yararına işlenmesi halinde, ayrıca bu tüzel kişiye onbin Türk Lirasından elli milyon Türk Lirasına kadar idarî para cezası verilir. Ancak idari para cezası, işleme veya eyleme konu menfaatin iki katından az olamaz.\n(2) ... yargılama yapmakla görevli mahkeme yetkilidir.",
  "Kabahatler m.43/B": "(1) ... bankalara, finansal kuruluşlara ... ibraz edilen paranın sahte olduğunun anlaşılması halinde, ... bildirim yükümlülüğü yerine getirilmediği takdirde, bu tüzel kişilere Cumhuriyet savcısı tarafından bin Türk Lirasından beşbin Türk Lirasına kadar idarî para cezası verilir.",
  "Kabahatler m.5": "(1) 5237 sayılı Türk Ceza Kanununun zaman bakımından uygulamaya ilişkin hükümleri kabahatler bakımından da uygulanır. Ancak, kabahatler karşılığında öngörülen idarî yaptırımlara ilişkin kararların yerine getirilmesi bakımından derhal uygulama kuralı geçerlidir.\n(2) Kabahat, failin icraî veya ihmali davranışı gerçekleştirdiği zaman işlenmiş sayılır. Neticenin oluştuğu zaman, bu bakımdan dikkate alınmaz.",
  "Kabahatler m.7": "(1) Kabahat, icraî veya ihmali davranışla işlenebilir. İhmali davranışla işlenmiş kabahatin varlığı için kişi açısından belli bir icraî davranışta bulunma hususunda hukukî yükümlülüğün varlığı gereklidir.",
  "Kabahatler m.8": "(1) Organ veya temsilcilik görevi yapan ya da organ veya temsilci olmamakla birlikte, tüzel kişinin faaliyeti çerçevesinde görev üstlenen kişinin bu görevi kapsamında işlemiş bulunduğu kabahatten dolayı tüzel kişi hakkında da idarî yaptırım uygulanabilir.\n(2) Temsilci sıfatıyla hareket eden kişinin bu sıfatla bağlantılı olarak işlemiş bulunduğu kabahatten dolayı temsil edilen gerçek kişi hakkında da idarî yaptırım uygulanabilir. Gerçek kişiye ait bir işte çalışan kişinin bu faaliyeti çerçevesinde işlemiş bulunduğu kabahatten dolayı, iş sahibi kişi hakkında da idarî yaptırım uygulanabilir.\n(3) Kanunun, organ veya temsilcide ya da temsil edilen kişide özel nitelikler aradığı hallerde de yukarıdaki fıkralar hükümleri uygulanır.\n(4) Birinci ve ikinci fıkra hükümleri, organ veya temsilcilik ya da hizmet ilişkisinin dayanağını oluşturan işlemin hukuken geçerli olmaması halinde de uygulanır.",
  "Kabahatler m.9": "(1) Kabahatler, kanunda açıkça hüküm bulunmayan hallerde, hem kasten hem de taksirle işlenebilir.",
  "Kaçakçılık m.10": "(2) 13 üncü maddenin birinci fıkrasının (a) bendi kapsamına girmesi, Türkiye'de sicile kayıtlı olmaması ya da soruşturma ve kovuşturma devam ederken, kaçakçılık suçunun işlenmesinde tekrar kullanılması halinde, elkonulan taşıt, elkoyma kararı veren mercilerce alıkonulur. Sahibinin taşıtın değeri kadar teminatı alıkoyma tarihinden itibaren otuz gün içinde gümrük idaresine teslim etmesi halinde, taşıt sahibine iade edilir. Aksi takdirde, tasfiye idaresi tarafından soruşturma ve kovuşturma sonucu beklenmeksizin derhal tasfiye olunur. (3) (...) hakkında elkoyma kararı bulunmakla birlikte ikinci fıkra uyarınca alıkonulmayan taşıtlar, gümrük idaresince yapılacak tebligattan itibaren doksan gün içinde (...) sahibi tarafından teslim alınmaması halinde, (...) derhal tasfiye olunur.\" (m.10/2-3)",
  "Kaçakçılık m.11": "(8) Kaçak akaryakıt, yakalandığı ildeki il özel idaresine, il özel idaresi bulunmayan yerlerde ise yatırım izleme ve koordinasyon başkanlığına, miktarı, cinsi ve özelliklerini gösterir bir tutanakla yakalandığı yerde teslim edilir. Kaçak akaryakıtın muhafazası, depolanması, yüklenmesi, boşaltılması ve nakliyesi gibi nedenlerle yapılan masraflar duruma göre il özel idaresi veya yatırım izleme ve koordinasyon başkanlığı tarafından karşılanır.\" (m.11/8)\n\n(1) Kaçak şüphesiyle elkonulan eşya ile 10 uncu maddenin ikinci fıkrası gereğince alıkonulan her türlü taşıt ve araç; miktarı, cinsi, markası, tipi, modeli, seri numarası gibi eşyanın ayırıcı özelliklerini gösterir bir tutanakla gümrük idaresine teslim edilir. (2) Gümrük idaresi, kaçak eşya ve taşıtların muhafazası için gerekli görülen yerlerde depo temin eder. (3) (...) alıkonularak gümrük idaresine teslim edilen deniz taşıtları, teminatla teslim alınmaması halinde, muhafaza ve zorunlu bakım giderleri sahiplerince ya da donatanlarınca karşılanmak üzere gümrük idaresince belirlenen liman işletme müdürlüğüne teslim edilir. Masraflar, sahiplerince ya da donatanlarınca karşılandığı sürece, taşıtın tasfiyesi yoluna gidilmez. (4) Muhafazası özel tesis ve tertibatı gerektiren veya gümrük idaresinin depolama kapasitesini aşan eşya, özelliklerine göre doğrudan ilgili idarelere, bunun mümkün olmaması halinde büyükşehirler dahil ilçelerde kaymakam, illerde valinin uygun göreceği yerlere konulur. (5) (...) ambalajlarında (...) bandrol, etiket, hologram, pul, damga veya benzeri işaret bulunmayan tütün mamulleri, etil alkol, metanol, alkollü içkiler, makaron ve yaprak sigara kâğıdı ile ilaç, ilaç hammaddeleri, (...) tıbbi cihaz ve malzemeler, (...) elektronik sigara ve elektronik nargile dahil her türlü mamul (...) el koyan idarelerce numune alınmak veya numune alınması mümkün olmaması halinde ayırt edici bilgilerin tespiti yapılmak suretiyle tutanağa bağlanarak imha edilir. (6) Kaçak akaryakıt hariç el konulan ve alıkonulan her türlü eşya, yük hayvanı ve taşıtların muhafazası, depolanması, (...) nakliyesi ve imhası gibi nedenlerle (...) yapılan masraflar, Gümrük ve Ticaret Bakanlığı döner sermaye işletmesi gelirlerinden karşılanır. Bu kapsamda yapılacak (...) alımlarında (...) Kamu İhale Kanunu hükümleri uygulanmaz. (7) Dördüncü, beşinci ve altıncı fıkralara ilişkin usul ve esaslar (...) yönetmelikle düzenlenir.\" (m.11/1-7)",
  "Kaçakçılık m.13": "(1) Bu Kanunda tanımlanan suçlarla ilgili olarak 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun eşya ve kazanç müsaderesine ilişkin hükümleri uygulanır. Ancak kaçak eşya taşımasında bilerek kullanılan veya kullanılmaya teşebbüs edilen her türlü taşıma aracının müsadere edilebilmesi için aşağıdaki koşullardan birinin gerçekleşmesi gerekir: a) Kaçak eşyanın, suçun işlenmesini kolaylaştıracak veya fiilin ortaya çıkmasını engelleyecek şekilde özel olarak hazırlanmış gizli tertibat içerisinde saklanmış veya taşınmış olması. b) Kaçak eşyanın, taşıma aracı yüküne göre miktar veya hacim bakımından tamamını veya ağırlıklı bölümünü oluşturması veya naklinin, bu aracın kullanılmasını gerekli kılması. c) Taşıma aracındaki kaçak eşyanın, Türkiye'ye girmesi veya Türkiye'den çıkması yasak veya toplum veya çevre sağlığı açısından zararlı maddelerden olması.\" (m.13/1)",
  "Kaçakçılık m.16": "(1) (...) Kaçak şüphesiyle el konulan kaçak akaryakıt hariç her türlü eşya hakkında, el koyma tarihinden itibaren altı ay, ancak eşyanın zarara uğraması veya değerinde esaslı ölçüde kayıp meydana gelme tehlikesinin varlığı veya muhafazasının ciddi külfet oluşturması halinde bir ay içinde, gerekli tespitler yaptırılarak soruşturma aşamasında hâkim, kovuşturma aşamasında mahkeme tarafından tasfiye kararı verilir. Bu süreler içinde karar verilmemesi halinde eşya derhal tasfiye edilir.\" (m.16/1)\n\n(1) Bu Kanun uyarınca el konulan kaçak akaryakıttan teknik düzenlemelere uygun olanlar, il özel idareleri, il özel idaresi bulunmayan yerde yatırım izleme ve koordinasyon başkanlıkları tarafından, numune alınmak suretiyle kamu kurum ve kuruluşları ile mahalli idarelerin kullanımına bedelsiz tahsis edilerek veya satışı yapılarak tasfiye edilir (...). (3) (...) Numune analiz sonuçları teknik düzenlemelere uygun olmayan kaçak akaryakıt, il özel idaresi veya yatırım izleme ve koordinasyon başkanlığı tarafından en yakın rafinericiye satılır. (...) Yapılan analiz sonucunda rafineri işlem süreçlerine zarar vereceği anlaşılan kaçak akaryakıt, bertaraf ve/veya enerji geri kazanımı amacıyla (...) bertaraf ettirilir.\" (m.16/A 1-3)",
  "Kaçakçılık m.17": "(2) Bu Kanun kapsamına giren suçlar dolayısıyla açılan davalar, Adalet Bakanlığının teklifi üzerine Hakimler ve Savcılar Yüksek Kurulunca belirlenen asliye ceza mahkemelerinde görülür. Ancak bu suçlarla bağlantılı olarak resmî belgede sahtecilik suçunun işlenmesi halinde, görevli mahkeme ağır ceza mahkemesidir.\" (m.17/2)",
  "Kaçakçılık m.18": "(1) Bu Kanunda tanımlanan suçlar dolayısıyla açılan davalarda mahkeme, iddianamenin bir örneğini ilgili gümrük idaresine de gönderir. Başvurusu üzerine, ilgili gümrük idaresi açılan davaya katılan olarak kabul edilir.\" (m.18/1)",
  "Kaçakçılık m.19": "(1) Mülkî amirler, Gümrük Müsteşarlığı personeli ile Emniyet Genel Müdürlüğü, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığına bağlı personel, bu Kanunla yaptırım altına alınan fiilleri önleme, izleme ve araştırmakla yükümlüdür.\" (m.19/1)",
  "Kaçakçılık m.2": "(1) Bu Kanunda yer alan; a) Gümrük vergileri: Gümrük idaresi veya başka idarelerce, eşyanın ithali veya ihracına bağlı olarak uygulanan vergiler ile diğer malî yükümlülükleri, b) Gümrüklenmiş değer: Uluslararası kıymet sözleşmesine göre belirlenecek; ithal eşyası için eşyanın CIF kıymeti ile gümrük vergileri toplamını, ihraç eşyası için FOB kıymeti ile gümrük vergileri toplamını, c) (...) Akaryakıt: Benzin, gaz yağı, jet yakıtı, motorin, fuel-oil, sıvılaştırılmış petrol gazları, doğal gaz gibi akaryakıt ürünleri ile akaryakıt yerine kullanılan petrol türevleri ve bunların karışımları ile akaryakıt yerine kullanılan diğer ürünleri, ifade eder.\" (m.2/1)",
  "Kaçakçılık m.20": "(1) Kaçakçılık fiillerinin izlenmesine ilişkin tutanakların; a) Tarih, yer, düzenleyenlerin unvan ve isimleri, hâkim kararının tarih ve sayısı ile Cumhuriyet savcısının yazılı emri ile yapılması durumunda emrin tarih ve sayısını, b) Olay ve kanıtlarını, suç (...) konusu eşya ve taşıma araçlarının ayrıntılı olarak türü, kapsamı, miktar ve nitelikleri ile nerede ve ne suretle el konulduklarını, c) İlgilinin kimlik, iş ve yerleşim yeri ile varsa ifadesini, kapsaması ve imza altına alınması gereklidir.\" (m.20/1)",
  "Kaçakçılık m.22": "(1) Gümrük Kanunu gereğince belirlenen kapı ve yollardan başka yerlerden gümrük bölgesine girmek, çıkmak veya geçmek isteyen kişiye \"dur\" uyarısında bulunulmasına rağmen bu uyarıya uymaması halinde, havaya ateş edilmek suretiyle uyarı yinelenir. Ancak silâhla karşılığa yeltenilmesi ve sair surette meşru müdafaa durumuna düşülmesi halinde, yetkili memurlar saldırıyı etkisiz kılacak oranda doğrudan hedefe ateş edebilir.\" (m.22/1)",
  "Kaçakçılık m.23": "(2) Dağıtılacak ikramiyenin yüzde ellisi muhbirlere, yüzde ellisi elkoyma ikramiyesine hak kazananlara verilir. İhbarsız yakalama olaylarında ikramiyenin tamamı elkoyma ikramiyesine hak kazananlara ödenir. Kaçakçılığı önleme, izleme ve soruşturmakla yükümlü olanlara muhbir ikramiyesi ödenmez. Kaçakçılığı önleme, izleme ve soruşturmakla görevli olanlardan yakalama işlemine bizzat ve fiilen katılanlar (...) elkoyma ikramiyesine hak kazanır.\" (m.23/2)",
  "Kaçakçılık m.3": "(1) Eşyayı, gümrük işlemlerine tabi tutmaksızın ülkeye sokan kişi, bir yıldan beş yıla kadar hapis ve on bin güne kadar adlî para cezası ile cezalandırılır. Eşyanın, gümrük kapıları dışından ülkeye sokulması halinde, verilecek ceza üçte birinden yarısına kadar artırılır.\" (m.3/1)\n\n(10) Kaçakçılık suçunun konusunu oluşturan eşyanın akaryakıt ile tütün, tütün mamulleri, makaron, yaprak sigara kâğıdı, etil alkol, metanol ve alkollü içkiler olması halinde, yukarıdaki fıkralara göre verilecek cezalar yarısından iki katına kadar artırılır, ancak bu fıkranın uygulanması suretiyle verilecek ceza üç yıldan az olamaz.\" (m.3/10)\n\n(2) Eşyayı, aldatıcı işlem ve davranışlarla gümrük vergileri kısmen veya tamamen ödenmeksizin ülkeye sokan kişi, iki yıldan beş yıla kadar hapis ve on bin güne kadar adlî para cezası ile cezalandırılır. (...) (5) Birinci ila dördüncü fıkralarda tanımlanan fiillerin işlenmesine iştirak etmeksizin, bunların konusunu oluşturan eşyayı, bu özelliğini bilerek ve ticarî amaçla satın alan, satışa arz eden, satan, taşıyan veya saklayan kişi, bir yıldan üç yıla kadar hapis ve beş bin güne kadar adlî para cezası ile cezalandırılır. (...) (7) İthali kanun gereği yasak olan eşyayı ülkeye sokan kişi, fiil daha ağır bir cezayı gerektiren suç oluşturmadığı takdirde, iki yıldan altı yıla kadar hapis ve yirmi bin güne kadar adlî para cezası ile cezalandırılır. (...) (8) İhracı kanun gereği yasak olan eşyayı ülkeden çıkaran kişi, (...) bir yıldan üç yıla kadar hapis ve beş bin güne kadar adlî para cezası ile cezalandırılır.\" (m.3/2, 5, 7, 8)\n\n(22) Yukarıdaki fıkralarda tanımlanan fiiller, teşebbüs aşamasında kalmış olsa bile, tamamlanmış gibi cezalandırılır. (23) Yukarıdaki fıkralarda tanımlanan suçların konusunu oluşturan eşyanın değerinin fahiş olması hâlinde, verilecek cezalar yarısından bir katına kadar artırılır. Eşyanın değerinin hafif olması hâlinde verilecek cezalar yarısına kadar, pek hafif olması hâlinde ise üçte birine kadar indirilir.\" (m.3/22-23)",
  "Kaçakçılık m.4": "(1) Bu Kanunda tanımlanan suçların (...), bir örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek ceza iki kat artırılır. (2) Bu Kanunda tanımlanan suçların (...), üç veya daha fazla kişi tarafından birlikte işlenmesi halinde, verilecek ceza yarı oranında artırılır.\" (m.4/1-2)\n\n(6) Kaçakçılık fiillerini önlemek, izlemek ve araştırmakla görevli olup da bu Kanunda tanımlanan suçların işlenmesine kasten göz yuman kişi, işlenen suçun müşterek faili olarak sorumlu tutulur. (7) Kaçakçılık suçunun konusunu oluşturan eşyanın, Devletin siyasî, iktisadî veya askerî güvenliğini bozacak ya da çevre veya toplum sağlığını tehdit edecek nitelikte olması halinde, fiil daha ağır cezayı gerektiren bir suç oluşturmadığı takdirde, verilecek hapis cezası on yıldan az olamaz.\" (m.4/7)\n\n(4) Bu Kanunda tanımlanan suçların, kaçakçılık fiillerini önlemek, izlemek, araştırmak ve soruşturmakla görevli kişiler tarafından veya meslek ve sanatın sağladığı kolaylıklardan yararlanmak suretiyle işlenmesi halinde, verilecek ceza yarı oranında artırılır.\" (m.4/4)",
  "Kaçakçılık m.5": "(2) Yedinci fıkrası hariç, 3 üncü maddede tanımlanan suçlardan birini işlemiş olan kişi, etkin pişmanlık göstererek suç konusu eşyanın gümrüklenmiş değerinin iki katı kadar parayı Devlet Hazinesine; a) Soruşturma evresi sona erinceye kadar ödediği takdirde, hakkında bu Kanunda tanımlanan kaçakçılık suçlarından dolayı verilecek ceza yarı oranında, b) Kovuşturma evresinde hüküm verilinceye kadar ödediği takdirde, hakkında bu Kanunda tanımlanan kaçakçılık suçlarından dolayı verilecek ceza üçte bir oranında, indirilir. Bu husus, soruşturma evresinde Cumhuriyet savcısı tarafından şüpheliye ihtar edilir. Soruşturma evresinde ihtar yapılmaması hâlinde kovuşturma evresinde hâkim tarafından sanığa ihtar yapılır.\" (m.5/2)\n\n(1) 3 üncü maddede tanımlanan suçlardan (...) birine iştirak etmiş olan kişi; resmî makamlar tarafından haber alınmadan önce, fiili, diğer failleri ve kaçak eşyanın saklandığı yerleri merciine haber verirse, verilen bilginin, faillerin yakalanmasını veya kaçak eşyanın ele geçirilmesini sağlaması halinde cezalandırılmaz. Haber alındıktan sonra fiilin bütünüyle ortaya çıkmasına hizmet ve yardım eden kişiye verilecek ceza üçte iki oranında indirilir.\" (m.5/1)\n\n(3) İkinci fıkra hükmü, mükerrirler hakkında veya suçun bir örgütün faaliyeti çerçevesinde işlenmesi hâlinde uygulanmaz.\" (m.5/3)",
  "Kaçakçılık m.9": "(3) Gümrük bölgesine, Gümrük Kanunu gereğince belirlenen kapı ve yollardan başka yerlerden girmek, çıkmak veya geçmek yasaktır. Bu yerlerde rastlanacak kişi ve her nevi taşıma araçları yetkili memurlar tarafından durdurulur ve kişilerin eşya, yük ve üzerleri ile varsa taşıma araçları aranır. Yapılan arama sonucunda tespit edilen kaçak eşyaya derhal elkonulur.\" (m.9/3)",
  "Kara Avcılığı m.12": "Özel avlaklarda avlanmak avlak sahibinin, Devlet avlakları, genel avlaklar ve örnek avlaklarda avlanmak Genel Müdürlüğün iznine bağlıdır. Sahipli arazilerde avlanmayla ilgili esaslar Genel Müdürlükçe tespit edilir. Özel kanunlarla veya Merkez Av Komisyonunca avlanmanın yasak edildiği yerlerde ve 2 nci maddenin 11, 12 ve 13 üncü bentlerinde tanımlanan saha ve istasyonlarda avlanılamaz. Buralarda, ancak av ve yaban hayvanlarının çoğaldığı ve zararlı olduğu hâllerde avlanmaya Bakanlıkça izin verilebilir.",
  "Kara Avcılığı m.13": "Avcılık belgesi, Türk vatandaşlarına bir defaya mahsus olmak üzere verilir ve her yıl vize edilir. (...) Avcılık belgesi alacak olanlar, eğitime ve yeterlik sınavına tâbi tutulur. Avcılık belgelerine ait iş ve işlemler Genel Müdürlükçe yürütülür ve bu belgeler olmadan avlanılamaz. (...) [m.14] Avcılık belgesi sahibi avcılar, avlanmak istedikleri av yılına ait avlanma izin ücretini Döner Sermaye İşletmesine yatırmak suretiyle avlanma izni almak zorundadırlar. (...) Avlanma izni bir av yılı içindir. Avlaklarda, avcılık belgesi ve avlanma izni olmadan avlanılamaz. (...) Özel avlaklarda üretilip salınan türlerin avlanması için gerekli izin, avlak sahibi veya işletenlerce ücreti karşılığı verilir. Bu ücretin %10'u Döner Sermaye İşletmesine yatırılır, aksi takdirde özel avlak kuruluş izni iptal edilir.",
  "Kara Avcılığı m.15": "[m.15] Türkiye'de av turları, fotoğraf ve film çekimleri ile av ve yaban hayvanları gözlem turları yaptıracak seyahat acenteleri, Genel Müdürlükten av turizmi izin belgesini almaya; seyahat acenteleri vasıtasıyla veya münferiden sadece özel avlaklar ile gerçek ve tüzel kişiler tarafından işletilen avlaklarda avlanmak üzere yurdumuza gelen avcı turistler ise 13 üncü maddede belirtilen geçici avcılık belgesini almaya ve avlayacakları av hayvanlarını bu belgeye kaydettirmeye mecburdurlar. (...) [m.16] Avcı turistler, beraberlerinde ok-yay ile yivli ve yivsiz av tüfeklerini ve bunlara ait mermileri getirebilirler. 6136 sayılı Kanun ile (...) 2521 sayılı (...) Kanun hükümleri saklıdır. [m.17] Avcı turistler, avladıkları ve onaylanmış geçici avcılık belgelerine kayıtlı av hayvanlarının etlerini ve hatıra değeri taşıyan parçalarını, Türkiye'nin taraf olduğu uluslararası sözleşmelerdeki taahhütlerini dikkate almak kaydıyla başka bir izne bağlı olmadan yurt dışına beraberlerinde çıkarabilirler, adreslerine gönderebilirler veya göndertebilirler.",
  "Kara Avcılığı m.18": "Taraf olunan uluslararası sözleşmelerle ticareti yasaklanan yerli ve yabancı yaban hayvanları ve bu Kanunun 6 ncı maddesi çerçevesinde belirlenen avlanma esas ve usullerine aykırı olarak avlanan yaban hayvanları canlı veya cansız olarak veya bunların et, yumurta, deri, post, boynuz ve benzeri parçaları ile bunların türevleri satılamaz, satın alınamaz, nakledilemez ve bunların ithalatı ve ihracatı yapılamaz. (...) Yurt içinde sergilenmek üzere veya gösteri amaçlı olarak uluslararası sözleşmeler çerçevesinde ithalatına Bakanlıkça izin verilen yaban hayvanları satılamaz. Bu hususlar Genel Müdürlükçe denetlenir.",
  "Kara Avcılığı m.20": "Avcılığın kontrolü, av hayvanlarının korunması, av yasaklarının takibi (...) Genel Müdürlük ve Orman Genel Müdürlüğünce yapılır. 4/7/1934 tarihli ve 2559 sayılı Polis Vazife ve Salâhiyet Kanunu ile 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilât, Görev ve Yetkileri Kanunu hükümleri saklıdır. Genel kolluk ile, av yasaklarının takibi ile görevli olan orman muhafaza memurları, av ve doğa koruma memurları ve saha bekçileri, bu Kanunda belirtilen yasaklara aykırı hareket edenleri avlanmadan men etmeye, haklarında tutanak düzenlemeye; (...) yasak olan eşya ve vasıtalara elkoymaya ve bu amaçla yakalamaya görevli ve yetkilidir. (...) Elkonulan ve bulundurulması suç oluşturan silâhlar soruşturma evrakı ile birlikte Cumhuriyet başsavcılığına intikal ettirilir.\n\nAv koruma ve kontrollerinde Genel Müdürlük görevlilerine veya güvenlik güçlerine gönüllü destek sağlamak üzere Genel Müdürlükçe belirlenecek kişilere fahri av müfettişliği görev ve unvanı verilebilir. Fahri av müfettişleri; bu Kanuna göre yasak avlanma sayılan fiilleri işleyenler hakkında işlem yapılması amacıyla Genel Müdürlükçe kendilerine verilen tutanağı düzenleyerek en geç bir hafta içinde en yakın Genel Müdürlük taşra birimine teslim etmek mecburiyetindedir.\" · **[m.21/5 — fahri müfettişin kendisi suç işlerse]** \"Bu Kanunda belirtilen yasak fiillerin fahri av müfettişleri tarafından işlenmesi halinde verilecek cezalar iki misli uygulanır. Yasak avlanma fiilini işleyen veya gerçeğe aykırı tutanak düzenleyen fahri av müfettişlerinin belgeleri iptal edilir ve kendilerine bir daha fahri av müfettişliği görevi verilmez.",
  "Kara Avcılığı m.21": "4 üncü maddenin dördüncü fıkrası gereğince av ve yaban hayvanlarının beslendikleri ve barındıkları ortamı zehirleyenler, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. Ayrıca, faillerin avcılık belgesi iptal edilir ve kendilerine bir daha belge verilmez. (...) Avlanmak suretiyle, bir canlı türünün yok olması tehlikesine ya da ekolojik dengenin bozulması tehlikesine neden olunması halinde, failler hakkında iki yıldan beş yıla kadar hapis cezasına hükmolunur.",
  "Kara Avcılığı m.22": "11 inci madde gereğince yapılan denetimlerde özel avlakların kuruluş amaçları dışında işletildiğinin tespiti halinde, avlak sahibine veya bu avlakları kiralamak sureti ile işletenlere, binikiyüz Türk Lirası idarî para cezası verilir.\" (5728/2008 ile \"birmilyar lira\"→\"binikiyüz Türk Lirası\".) **(2026: %25,49 yeniden değerleme uygulanır; kesin TL editör teyidi)**",
  "Kara Avcılığı m.23": "Merkez Av Komisyonunca avlanmanın yasaklandığı avlaklarda avlananlara onbin Türk Lirası, özel kanunlarla avlanmanın yasaklandığı sahalar ile 2 nci maddenin 11, 12 ve 13 üncü bentlerinde tanımlanan saha ve istasyonlarda avlananlara, onbeşbin Türk Lirası idarî para cezası verilir.\" (7576/2026 ile tutarlar ikiyüz→onbin, üçyüzelli→onbeşbin'e yükseltilmiştir.) **(2026: %25,49 yeniden değerleme uygulanır; kesin TL editör teyidi)**",
  "Kara Avcılığı m.24": "Zehirle avlananlar, bir yıldan üç yıla kadar hapis ve elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Ayrıca, faillerin avcılık belgesi iptal edilir ve bir daha belge verilmez. (...) Bu Kanuna göre alınması gereken avcılık belgesini almadan avlananlara onbin Türk Lirası; avlanma izni olmadan ve avlaklarda izin almadan avlananlara ise beşbin Türk Lirası idarî para cezası verilir. (...) Avcılık belgesini ve avlanma izin belgesini yanında taşımadan avlananlara yirmi Türk Lirası idarî para cezası verilir. (...) Bu maddede yazılı cezaya konu fiillerin beş yıl içinde tekrarı halinde ceza üç katı olarak uygulanır.\" **(2026: %25,49 yeniden değerleme uygulanır; kesin TL editör teyidi)** · **Tekrar ayrımı:** m.24'teki \"beş yıl içinde tekrar → **para (İPC) cezası x3**\"tür; **belge iptali / 2 yıl belge yasağı** sonucu ise **m.29** kapsamındadır (m.21/1, m.23, m.24/1, m.26/1 tekrarı).",
  "Kara Avcılığı m.25": "Av turizmi izin belgesi almadan av turu, fotoğraf ve film çekimleri ile av ve yaban hayvanları gözlem turları yaptıran veya yabancıların geçici avcılık belgesi olmadan avlanmasına aracılık eden kişi, kuruluş ve acentelere onbin Türk Lirası, geçici avcılık belgesinde kayıtlı türler ve yerler dışında avlanan yabancı uyruklu kişiye, beşbin Türk Lirası idarî para cezası verilir.\" (5728/2008 ile \"onmilyar lira\"→\"onbin TL\", \"beşmilyar lira\"→\"beşbin TL\".) **(2026: %25,49 yeniden değerleme uygulanır; kesin TL editör teyidi)**",
  "Kara Avcılığı m.26": "18 inci maddenin birinci ve ikinci fıkraları ve 19 uncu madde gereğince Genel Müdürlüğün koyacağı esaslara uymayanlara, beşyüz Türk Lirasından ikibinbeşyüz Türk Lirasına kadar idarî para cezası verilir. 18 inci maddenin üçüncü fıkrasında belirtilen yasağa uymayanlara üçbin Türk Lirası idarî para cezası verilir.\" **(2026: %25,49 yeniden değerleme uygulanır; kesin TL editör teyidi)**",
  "Kara Avcılığı m.28": "Bu Kanunla yasak edilen fiilleri işleyenler derhal avdan men edilir. Bu Kanunun 20 nci maddesi kapsamında elkonulan av hayvanları ve türevleri ile sair eşyanın mülkiyetinin kamuya geçirilmesine mahallî mülkî amir tarafından karar verilir. (...) Canlı olarak el konulan ve özel bakım ve tedaviye muhtaç olmayan av hayvanları, Genel Müdürlük yetkilileri tarafından başka bir şekilde değerlendirilmesine karar verilmediği takdirde, doğal yaşama ortamlarında serbest bırakılır.",
  "Kara Avcılığı m.29": "21 inci maddenin birinci fıkrasında yazılı cezaya konu fiillerin tekrarı hâlinde ayrıca faillerin avcılık belgeleri iptal edilir ve kendilerine iki yıl süre ile avcılık belgesi verilmez. 22 nci maddede yazılı cezaya konu fiillerin tekrarı hâlinde ayrıca avlak kuruluş izni iptal edilir. 23 üncü maddede yazılı cezalara konu fiillerin tekrarı hâlinde, ayrıca faillerin avcılık belgeleri iptal edilir ve kendilerine iki yıl süre ile avcılık belgesi verilmez. 24 üncü maddenin birinci fıkrasında yazılı cezaya konu; 6 ncı maddenin ikinci/üçüncü fıkrasındaki fiillerin tekrarı hâlinde faillerin avcılık belgeleri iptal edilir ve kendilerine iki yıl süre ile avcılık belgesi verilmez. 26 ncı maddenin birinci fıkrasında yazılı cezaya konu fiillerin tekrarı hâlinde ilgililerin ayrıca, 18 inci maddenin birinci ve ikinci fıkrasındaki faaliyetlerden iki yıl süreyle men'ine ve 19 uncu maddedeki iznin iptaline karar verilir.",
  "Kara Avcılığı m.3": "Merkezde, Bakanın veya Bakan Yardımcısının başkanlığında; **Genel Müdürlükten üç**, **Bakanlığın diğer birimlerinden bir bitki uzmanı ve bir veteriner olmak üzere iki**, **Jandarma Genel Komutanlığı, Orman Genel Müdürlüğü ve Emniyet Genel Müdürlüğünden birer**, **yükseköğretim kurumlarının orman fakültelerinden bir ve biyoloji bölümlerinden bir olmak üzere iki bilim insanı**, **doğa koruma alanında faaliyet gösteren sivil toplum kuruluşlarını temsilen dört**, **dokuz coğrafi bölge esas alınarak belirlenecek avcı kuruluşlarından dokuz**, **özel avlak veya örnek avlak temsilcisi bir** olmak üzere **toplam yirmibeş üyeden** teşekkül eden Merkez Av Komisyonu kurulur. İllerde ise valinin veya görevlendireceği vali yardımcısının başkanlığında; **Genel Müdürlük ve Orman Genel Müdürlüğü taşra teşkilatı ile tarım ve orman il müdürlüğü, il milli eğitim müdürlüğü, il emniyet müdürlüğü, jandarma teşkilâtı ve gönüllü kuruluşları temsilen birer** (yedi), **mahalli avcı kuruluşlarından üç üye** olmak üzere **toplam onbir üyeden** teşekkül eden il av komisyonu kurulur. İlçe av komisyonu kararları il av komisyonunda, il av komisyonu kararları da Merkez Av Komisyonunda değerlendirilir. Merkez Av Komisyonu bu Kanunda Genel Müdürlüğe verilen yetkiler dışında av ve yaban hayatının korunması ve geliştirilmesi için gerekli kararları alır. Merkez Av Komisyonu kararı kesindir.",
  "Kara Avcılığı m.30": "Bu Kanuna göre verilecek idarî para cezaları Genel Müdürlük bölge müdürü veya yetki verdiği personeli ile 31.10.1985 tarihli ve 3234 sayılı Orman Genel Müdürlüğünün Kuruluş ve Görevleri Hakkında Kanunda yer alan orman işletme şefi tarafından verilir.",
  "Kara Avcılığı m.4": "Koruma altına alınan yaban hayvanları avlanamaz. Yaban hayvanları üreme, tüy değiştirme ve göç dönemlerinde rahatsız edilemez, yavru ve yumurtaları toplanamaz, yuvaları dağıtılamaz ve memeliler kış uykusunda rahatsız edilemez. (...) Av ve yaban hayvanlarının beslenmesine, barınmasına, üremesine ve korunmasına imkân veren doğal yaşama ortamları zehirlenemez, sulak alanlar kirletilemez, kurutulamaz ve bunların doğal yapıları değiştirilemez.\" · **[m.4/2 — istisna]** \"Koruma altında olmayan yaban hayvanlarının avlanmanın yasaklandığı gün ve sürelerde; tarım alanları ile besi ve yaban hayvanlarına zarar verecek sayıda çoğalmaları veya bulaşıcı hastalık taşıdıklarının tespiti durumunda, (...) hazırlanacak ortak rapor doğrultusunda belli sayıda yaban hayvanının (...) avlattırılmasına Genel Müdürlükçe izin verilebilir.",
  "Kara Avcılığı m.5": "Sürüngen, kuş ve memeli av hayvanlarının (...) avlanma sürelerinin başlama ve bitiş tarihleri ile populasyon durumuna göre avlanma günleri ve av miktarlarını tespit etmeye, Devlet avlakları ve genel avlaklarda bazı türlerin avını ve bazı avlaklarda avlanmayı belli bir süre yasaklamaya; il av komisyonlarının görüş ve önerileri doğrultusunda Merkez Av Komisyonu, özel avlaklar ile örnek avlaklarda ise Genel Müdürlük yetkilidir. (...) Merkez Av Komisyonunca tespit edilen av miktarları ve avlanma süreleri dışında avlanılamaz. **[m.5 son fıkra]** Av ve yaban hayatının korunması, geliştirilmesi ve sürdürülebilir yönetiminde; kamuoyu desteğinin sağlanması için toplumun bilgilendirilmesi, bilinçlendirilmesi ile avcıların ve toplumun eğitilmesi amacıyla; Türkiye sınırları içinde yayın yapan ulusal, bölgesel, yerel radyo ve televizyonlar; av sezonunun başlamasından **onbeş gün önce** ve sona ermesinden itibaren de **onbeş gün süreyle** eğitici, uyarıcı ve tanıtıcı yayın yapmak zorundadırlar. Bu yayın ve tanıtım faaliyetleri her kuruluşun ana haber bültenlerinden sonraki kuşakta ve ücretsiz olarak yayınlanır. Bu programların süresi **yılda toplam üç saatten az olamaz.** Bu hizmetlerin yürütülmesinde kurum ve kuruluşlar Bakanlık ile işbirliği yaparlar.",
  "Kara Avcılığı m.6": "Avlanma, avcılık belgesi ve avlanma izni almak şartıyla, yasalarla izin verilen silâh, araç ve eğitilmiş hayvanlarla, avlanma plânlarına veya Merkez Av Komisyonu kararlarına göre yapılır. Zehirle avlanmak yasaktır. Haznesi iki fişek alacak şekilde sınırlandırılmamış otomatik, yarı otomatik, pompalı ve benzeri yivsiz av tüfekleri ile havalı tüfek ve tabancalar avda kullanılamaz.",
  "Kimlik Bild. Yön m.15": "Şehir, kasaba ve köy sınırları içindeki konutlara misafir olarak gelen ve 30 günden fazla bir süre için kalacak kişilerin kimlikleri, bu konutlarda oturmakta olan ailelerin reisleri veya aralarında aile bağı olmaksızın kalan veya yalnız yaşayan kişiler tarafından form 6'daki Misafirlere Ait Kimlik Bildirme Belgesine yazılır ve iki nüsha olarak düzenlenen bu belgeler üç gün içinde en yakın yetkili genel kolluk örgütüne verilir.\" (m.15)",
  "Kimlik Bild. Yön m.19": "İskele, istasyon, hava meydanı, terminal, garaj, benzin istasyon ve benzeri kara, deniz hava ulaşım merkezleri ile fuar, panayır, sergi ve pazar kurulması gibi zorunluluk olan zaman ve yerlerdeki sabahçı kahvesi ve diğer benzeri tesislerin, o yerin bağlı bulunduğu kolluk örgütü ile belediye veya köy idaresinin olumlu görüşü alındıktan sonra mahallin en büyük mülkiye amiri tarafından geçici veya sürekli olarak açık tutulması ve buralarda kişilerin kalması için verilen izin belgesinin, tesislerin görünür bir yerine asılması zorunludur. Buralarda kalanlar için bildirim yapılmaz.\" (m.19)",
  "Kimlik Bild. Yön m.20": "İşletici kimlik bildirme belgesi: a) İlk sorumlu işletici için doldurulduğunda önceki sorumlu işleticiye ait haneler boş bırakılarak, b) Ayrılanı izleyen sorumlu işleticiler için doldurulduğunda önceki sorumlu, işleticiye ait bilgiler her halde yazılarak, kolluk örgütüne verilir. Örgütteki görevli, (...) yeni belgenin alınış hanelerini bizzat doldurarak imzalar, birinci örneği saklar, öteki örneği yükümlüye geri verir ve önceki sorumlu işleticiye ait belgeyi imha eder. (...)\" (m.20) \"İşletici kimlik bildirme belgesi dışındaki bütün belgelerin tabloları her iki örnekte doldurup imzalandıktan sonra ve zımbalı kısmın örneklerdeki ayrılış tarihi ve imza haneleri boş bırakılarak kolluk örgütüne verilir. Örgütteki görevli, (...) birinci örneği saklar, öteki örneği yükümlüye geri verir.\" (m.21) \"Adına belge düzenlenmiş olan çalışan veya barınan kişinin o yerden ilişiğinin kesilerek ayrılması veya konutun değiştirilmesi halinde yükümlü, belgelerin verilmesindeki sürelere uymak kaydı ile; kendisindeki örnekten ayırdığı zımbalı kısma ayrılış tarihini yazıp imzalayarak kolluk örgütüne verir. (...) Yükümlü, kendisinde kalan belge örneğini kolluk örgütünden aldığı zımbalı kısımla birlikte üç yıl süre ile saklar. (...) Hakkında belge verilmiş bulunan misafirlerin ayrılışı kolluk örgütüne bildirilmez.\" (m.22)",
  "Kimlik Bild. Yön m.23": "Yönetmeliğin 6.maddesinde sayılan yerlerin sorumlu işleticileri tarafından; buralarda ücretli veya ücretsiz, gündüz veya gece yatacak yer gösterilen yerli veya yabancı herkesin kimliği ile geliş ve ayrılış tarihleri, KONAKLAMA YERİ KAYIT DEFTERİ (Form:7) ne günü gününe geçirilir. Bu yerlerde kalacak kişilerin, kendilerine verilecek kopyalı bir örnek KONAKLAMA BELGESİ (form:8) ni doldurarak imzalamaları ve sorumlu işleticiye vermeleri şarttır. Konaklama belgesindeki bilgiler, kişinin kimliğini belirten geçerli resmi belge ile karşılaştırıldıktan sonra, konaklama yeri kayıt defterine aktarılır.\" (m.23)",
  "Kimlik Bild. Yön m.24": "Defter yüz sahifeden aşağı olamaz. (...) Bir yıla ait konaklama belgeleri, düzenlendiği yılı izleyen takvim yılından başlayarak bir yıl; konaklama yeri kayıt defterleri, dolduğu yılı izleyen takvim yılından başlayarak beş yıl süre ile, sorumlu işleticinin sorumluluğu altında tesiste saklanır. Saklama süreleri içinde sorumlu işleticisi değişen tesisin belge ve defterleri yeni sorumlu işleticiye; kesin olarak kapanan tesisinkiler en yakın yetkili genel kolluk örgütüne hemen verilir; saklama görevi geri kalan süreler için yeni işletici veya örgütçe sürdürülür.\" (m.24) \"Yetkili resmi örgütler dışında, mahkeme kararı olmadıkça, hiç kimsenin konaklama belgelerinden ve konaklama yeri kayıt defterlerinden yararlanmasına müsaade edilemez.\" (m.25) \"Yükümlü, kendisinde kalan belge örneğini kolluk örgütünden aldığı zımbalı kısımla birlikte üç yıl süre ile saklar.\" (m.22)",
  "Kimlik Bild. Yön m.28": "Her karakol üç ayda bir kez ve gerektiğinde sürekli olarak, bölgesini tarar ve bölge krokisinde veya binalar cetvelinde yer almayan yeni veya yıkılan yapıları ve her türlü ilave ve değişiklikleri saptar, bunları kroki veya cetveline işler veya düşümünü sağlar. Belediyeler, mahallin en büyük mülki amirince istenilmesi halinde düzenledikleri nümerotaj cetvelinin birer örneğini vermekle yükümlüdürler.\" (m.28)",
  "Kimlik Bild. Yön m.3": "Bu Yönetmelikte geçen; a) Aile reisi: Eşlerden biri, eşlerin yerleşim yerinin ayrı olması halinde ayrı ayrı eşleri ya da aynı konutu paylaşan aile fertlerinden yaşça en büyük olanı, b) En yakın yetkili genel kolluk örgütü: Tesis, iş yeri veya konutun bulunduğu yerin sürekli olarak genel güvenliğini sağlayan polis veya jandarma karakollarını, (...) ifade eder.\" (m.3)",
  "Kimlik Bild. Yön m.4": "Bu Yönetmelikte sözü edilen: a) 24 saat deyimi; işe başlamanın veya ayrılmanın vuku bulduğu saatten itibaren geçen 24 saatlik, b) Üç gün deyimi; işe başlama veya geliş veya ayrılmanın vuku bulduğu saatten itibaren işlemeye başlayan 72 saatlik, süreyi kapsar.\" (m.4)",
  "Kimlik Bild. Yön m.5": "Bu Yönetmelik hükümlerine göre kimlik bildirme belgelerini en yakın yetkili genel kolluk örgütüne vermekle yükümlü tutulanlar, kimliğini nüfus hüviyet cüzdanı veya diğer resmi geçerli belgelerle ispat edemeyen kimseleri, tesislerinde barındıramaz, konut ve iş yerinde çalıştıramaz.\" (m.5)",
  "Kimlik Bild. Yön m.6": "Otel, motel, han, pansiyon, bekar odaları, günübirlik kiralanan evler, kamp, kamping, tatil köyü, her türlü özel veya resmi konaklama yerleri (yatılı okulların pansiyonları, yetiştirme yurtları ve köy odaları dahil) ile özel sağlık müesseseleri, dinlenme ve huzur evleri ve dini ve hayır kurumlarının sosyal tesislerinde (...) her an ulaşılabilecek bir sorumlu işletici bulunur. Sorumlu işleticinin kimliği, o tesis açılmadan önce, sahip veya kanuni temsilci veya kiracısı tarafından iki örnek İŞLETİCİ KİMLİK BİLDİRME BELGESİ (form: 1) ne yazılır ve bu belgeler en yakın yetkili genel kolluk örgütüne verilir.\" (m.6)",
  "Kimlik Bild. Yön m.7": "Sorumlu işleticinin değişmesi halinde, tesisin sahip, kanuni temsilci veya kiracısı tarafından, 24 saat içinde, yeni işleticiye ait kimlik bildirme belgesi, ayrılan işleticinin adı ve ayrılış tarihi de yazılarak yukarıdaki maddede belirtilen yönteme göre en yakın yetkili genel kolluk örgütüne verilir.\" (m.7)",
  "Kimlik Bild. Yön m.8": "Yönetmeliğin: a) 6. maddesi kapsamına giren tesislerle, b) 6. madde kapsamı dışındaki her çeşit ticaret ve sanat amacı güden iş yerlerinin sorumlu işleticileri tarafından; buralarda sürekli veya geçici olarak çalıştırılanların kimlikleri, iki örnek ÇALIŞANLARA AİT KİMLİK BİLDİRME BELGESİ (Form: 2) ne yazılır ve (a) bendi kapsamında olanların belgesi 24 saat, (b) bendi kapsamında olanların belgesi üç gün içinde en yakın yetkili genel kolluk örgütüne verilir. Maddenin (b) bendindeki yerler köylerde ise belgeler anılan örgütle verilmeden önce muhtara onaylatılır. (...) Bildirimlerin elektronik ortamda yapılması durumunda muhtar onayı aranmaz. (...) Elektronik ortamda bildirimde bulunmak isteyen iş yerleri sorumlu işleticilerinin kimliğini en yakın kolluk birimine bildirir; sorumlu işleticinin değişmesi halinde değişiklik 24 saat içinde aynı şekilde bildirilir. İşleticiler, kendilerine verilen görev ve yükümlülükleri kendi sorumlulukları altında yöneticilerine devredebilirler; bu durumda işletici ve yönetici müştereken sorumlu olurlar.\" (m.8)",
  "Kimlik Bild. Yön m.Ek 1": "1774 sayılı Kanunun 2 nci maddesinde sayılan özel veya resmi her türlü konaklama tesisleri ve işletmeler tüm kayıtlarını bilgisayarda günü gününe tutmak, genel kolluk kuvvetlerinin bilgisayar terminallerine bağlanarak mevcut bilgi, belge ve kayıtları genel kolluk kuvvetlerine anlık olarak bildirmek zorundadırlar. Bildirilen kayıtlar genel kolluk kuvvetlerine ait sistemde beş yıl süre ile muhafaza edilir. Bu süreyi dolduran kayıtlar kaydedilen sistemden otomatik olarak silinir. Bu veriler üzerinden yapılan tüm işlemler kayıt altına alınır.\" (Ek m.1)",
  "Kimlik Bild. Yön m.Ek 2": "Araç kiralama şirketlerinin sorumlu işleticileri ve yöneticileri, kiralanan araç bilgileri ile aracı kiralayanların kimlik bilgileri ve kira sözleşmesi kayıtlarını usulüne uygun şekilde günü gününe tutmak ve bu kapsamda mevcut bilgi, belge ve kayıtları genel kolluk kuvvetlerinin her an incelemelerine hazır bulundurmak zorundadırlar. Ancak araç kiralayanın kamu kurum veya kuruluşu olması halinde sadece kamu kurum veya kuruluşuyla yapılan sözleşme ile araç bilgileri sisteme kaydedilir. Birinci fıkrada belirtilen veriler 5 yıl süreyle muhafaza edilir. Sistemdeki kayıtlar 5 yıl sonunda sistemden otomatik olarak silinir. Bu veriler üzerinden yapılan tüm işlemler kayıt altına alınır.\" (Ek m.2)",
  "Kimlik Bildirme m.1": "Bu Kanunda sayılan, özel veya resmi, her türlü konaklama, dinlenme bakım ve tedavi tesisleri, marinalar, liman tesisleri, kıyı tesisleri ve işyerleri ile konutlarda geçici veya sürekli olarak kalanlar, oturanlar, çalışanlar ve ayrılanlar ile araç, gemi/deniz turizmi aracı kiralayan gerçek ve tüzel kişilerin kimliklerinin tespiti ve bildirilmesi bu Kanunun hükümlerine göre yapılır. Askeri konaklama, dinlenme ve kamp tesisleri ile ordu evleri bu Kanunun kapsamı dışındadır.",
  "Kimlik Bildirme m.10": "Kahvehane, oyun salonu, kulüp, lokal ve benzeri yerlerde ve bu Kanunun kapsamına giren diğer yatısız iş yerlerinde, özel kanunları müsaade ettiği takdirde, ancak sahipleri ve çalıştırdıkları kimseler yatabilir, başkaları kalamazlar. İskele, istasyon, hava meydanı terminal, garaj, benzin istasyonu ve benzeri kara, deniz ve hava ulaşım merkezleri ile fuar, panayır, sergi ve pazar kurulması gibi zorunluluk olan zaman ve yerlerde, sabahçı kahvesi ve benzeri diğer tesislere, bağlı olduğu kolluk kuvvetinin görüşü alınmak şartıyla belediye veya il özel idaresi tarafından geçici veya, sürekli olarak izin verilebilir. Buralarda kalanlar için bildirim yapılmaz.",
  "Kimlik Bildirme m.11": "Kat mülkiyetine tabi taşınmaz mal yöneticileri ve kapıcıları, binalarında bildirim dışı kimselerin oturup oturmadığını, çalışıp çalışmadığını, garaj, kömürlük, boş daire gibi bölümlere saklanmalar, sığınmalar, bazı eşya veya maddeleri gizlemeler olup olmadığını kontrol etmekle yükümlüdürler. Bütün kat sahipleri ve kiracıları ile binada çalışanlar bu konularda yöneticiye yardımcı olmak ve gereken bilgileri vermek zorundadırlar. Yönetici ve kapıcıların, bu Kanuna aykırılıkları ve diğer şüpheli gördükleri hususları, bağlı oldukları genel kolluk örgütüne bildirmeleri gereklidir.",
  "Kimlik Bildirme m.15": "Madde 15 – (...) 3 ve 4 üncü maddelerdeki yükümlülüklerden her birine aykırı hareket edenlere ikiyüzelli Türk Lirası idarî para cezası verilir. Madde 17 – 6, 7, 9, 10 ve 11 inci maddelerdeki hükümlere aykırı hareket edenlere yirmi Türk Lirası; kimlik bildirme belgesinde gerçeğe uymayan bilgi verenlere yüz Türk Lirası idarî para cezası verilir. Madde 18 – Bu Kanunda belirtilen idarî para cezaları, mahallî mülkî amir tarafından verilir.\" *(Tutarlar 5728/2008 nominal; yeniden değerlemeyle artar — görsele sabit yazılmaz, kademe/merci işlenir.)*",
  "Kimlik Bildirme m.2": "Otel, motel, han, pansiyon, bekar odaları, günübirlik kiralanan evler, kamp, kamping, tatil köyü, marinalar, liman tesisi, kıyı tesisi ve benzeri her türlü, özel veya resmi konaklama yerleri ile özel sağlık müesseseleri, dinlenme ve huzur evleri, dini ve hayır kurumlarının sosyal tesislerinin sorumlu işleticileri, bu yerlerde ücretli veya ücretsiz, gündüz veya gece, yatacak yer gösterdikleri gemi/deniz turizmi araçlarında kalan kişiler de dahil olmak üzere yerli veya yabancı herkesin kimlik ve geliş- ayrılış kayıtlarını, örneğine ve usulüne uygun şekilde günü gününe tutmak, genel kolluk örgütlerinin her an incelemelerine hazır bulundurmak, Devlet İstatistik Enstitüsüne, talebi halinde vermek zorundadırlar.",
  "Kimlik Bildirme m.3": "İkinci maddede sayılan tesislerin sorumlu işleticilerinin kimlikleri, tesis açılmadan evvel müessesenin sahibi veya kanuni temsilcisi tarafından örneğine uygun şekilde, en yakın kolluk örgütüne bildirilir. Sorumlu işleticinin değişmesi halinde keyfiyetin 24 saat içinde ve yukarıdaki fıkrada gösterilen şekilde bildirilmesi zorunludur. İşleticiler, kendilerine bu konuda verilen görev ve yükümlülükleri, kendi sorumlulukları altında yöneticilerine devredebilirler. Bu durumda işletici ve yönetici müştereken sorumlu olurlar. Kamu kuruluşlarına ait tesislerin amir ve müdürleri işletici gibi sorumludurlar.",
  "Kimlik Bildirme m.4": "İkinci maddedeki tesislerin sorumlu işleticileri, müesseselerinde sürekli veya geçici olarak çalıştırdıkları kimseleri ve bunların ayrılışlarını, örneğine uygun kimlik bildirme belgesi doldurarak, 24 saat içinde bağlı oldukları en yakın kolluk örgütüne bildirirler. Kolluk örgütüne bildirilerek çalıştırılanlara, sorumlu işletici tarafından doldurulup onaylanan, örneğine uygun bir kimlik kartı verilir. Kolluk görevlilerince her istenildiğinde bu kimlik kartının gösterilmesi zorunludur.",
  "Kimlik Bildirme m.6": "Şehir, kasaba ve köy sınırları içindeki; (...) b) Bu Kanunun ikinci maddesinde sayılanlar dışında kalan her çeşit ticaret ve sanat amacı güden iş yerlerinde çalışanlar ve buralarda her türlü barındırmalar için iş yerlerinin sorumlu işleticisi; c) Öğrenci yurtları ve benzeri yerlerde çalışanlar ile bu yerlerde kalmakta olan öğrenciler için o yerin sorumlu işleticisi; tarafından örneğine uygun kimlik belgesi doldurularak üç gün içinde genel kolluk örgütüne verilmesi zorunludur. (...) Konutun değiştirilmesi veya (b) ve (c) bentlerinde sayılan konut, iş yeri ve yurtlarda çalışmakta veya barınmakta olanların ayrılmaları halinde de, yukarıdaki şekil ve süre içinde bildirim belgesi gereklidir. (...) Kimlik bildirimleri, mahalli kolluk örgütüne verilmeden evvel mahalle veya köy muhtarına onaylatılır. Bu bildirimler sorumlu işleticiler tarafından, yukarıda belirtilen süre içerisinde genel kolluk kuvvetlerine elektronik ortamda da yapılabilir. Bildirimlerin elektronik ortamda yapılması durumunda üçüncü fıkra hükmü uygulanmaz. Bu fıkra kapsamında elektronik ortamda yapılan bildirimler, genel kolluk tarafından köy ve mahalle muhtarları ile paylaşılır.",
  "Kimlik Bildirme m.7": "Geçici yer değiştirmelerde; a) Konutlarda 30 günden fazla kalacak misafir için aile reisi; b) Yaylak ve kışlak gibi yerlere mevsimlik olarak göçenler için de aile reisi tarafından, örneğine uygun bildirim, Üç gün içinde kolluk örgütüne verilir.\n\n(Ek fıkra: 28/11/2017-7061/36 md.) Mevsimlik tarım işçisi olarak sürekli ikametinin dışında bir başka ilde çalışmak amacıyla geçici olarak yer değiştirenlerin kimlik bildirimleri, bu kişilerin yaşadıkları geçici yerleşim alanlarında doğrudan kolluk kuvvetlerince alınır ve bu bildirimler Çalışma ve Sosyal Güvenlik Bakanlığı ile elektronik ortamda paylaşılır.",
  "Kimlik Bildirme m.9": "Bu Kanun hükümlerine göre kimlik bildirme belgesini yetkili idareye vermekle yükümlü tutulanlar, kimliğini nüfus hüviyet cüzdanı ve diğer resmi geçerli belgelerle ispat edemeyen kimseleri tesislerinde barındıramaz, konut ve işyerlerinde çalıştıramaz.",
  "Kimlik Bildirme m.Ek 1": "Bu Kanunun uygulanması sırasında genel kolluk kuvvetlerine ait karakollara, il merkezlerinden de sorgulanabilen bilgisayar terminalleri konulur. (...) Bu Kanunun 2 nci maddesinde sayılan özel veya resmi her türlü konaklama tesisleri tüm kayıtlarını bilgisayarda günü gününe tutmak, genel kolluk kuvvetlerinin bilgisayar terminallerine bağlanarak mevcut bilgi, belge ve kayıtları genel kolluk kuvvetlerine anlık olarak bildirmek zorundadırlar.\n\nİkinci fıkrada belirtilen genel kolluk kuvvetlerinin terminallerine bağlanmayanlara onbin Türk Lirası, anlık veri göndermeyen veya gerçeğe aykırı kayıt tutanlara beşbin Türk Lirası idari para cezası, mülki idare amirlerince verilir. Bu maddede sayılan fiillerin işlendiği takvim yılı içinde tekrarı halinde en son kesilen para cezasının iki katı uygulanır, ayrıca sayılan fiillerin işlendiği takvim yılı içinde dördüncü defa işlenmesi halinde işletme ruhsatları iptal edilir. Bu maddeye göre verilen idari para cezaları tebliğinden itibaren bir ay içinde ödenir.\" *(Tutarlar görsele sabit yazılmaz; kademe — bağlanmama daha ağır, anlık göndermeme — + tekrar 2 kat + 4. kez ruhsat iptal işlenir.)*",
  "Kimlik Bildirme m.Ek 3": "(Değişik fıkra:21/11/2024-7533/16 md.) Araç, gemi/deniz aracı kiralama faaliyeti yürüten gerçek ve tüzel kişilere ait işletmenin sorumlu işletmecileri ve yöneticileri, kiralanan araç bilgileri ile aracı, gemi/deniz aracını kiralayanların kimlik bilgileri ve kira sözleşmesi ile buna ilişkin tüm bilgi, belge ve kayıtları usulüne uygun şekilde bilgisayarda tutmak, genel kolluk kuvvetlerinin her an incelemelerine hazır bulundurmak, bilgisayar terminallerini genel kolluk kuvvetlerinin bilgisayar terminallerine bağlamak ve kiralayan şahıs ile kiralanan araç bilgilerini araç teslimi esnasında genel kolluk kuvvetlerine sistem üzerinden anlık olarak bildirmek ve kiralanan araçlarda GPS cihazı (küresel uydu navigasyon sistemi) bulundurarak, araçlara ait konum bilgisine ilişkin kayıtları üç yıl saklamak zorundadırlar. (...) Araç, gemi/deniz aracı kiralama esnasında gerçeğe aykırı kimlik kullananlar ile birinci fıkra kapsamında elde edilen bilgi ve kayıtları, hukuka aykırı olarak kullanan, bir başkasına veren, yayan veya ele geçiren kişi, 5237 sayılı Türk Ceza Kanunu hükümlerine göre cezalandırılır. (...) [ağır idari para cezası, mülki idare amirlerince; tekrar 2 kat, 4. kez ruhsat iptal — tutarlar görsele sabit yazılmaz].",
  "Kum/Çakıl Yön m.10": "MADDE 10 – (1) (...) Çevresel Etki Değerlendirmesi Yönetmeliği uyarınca çevresel etki değerlendirmesi raporu hazırlaması zorunlu ya da gerekli faaliyet sahipleri, çevresel etki değerlendirmesi raporunun eki olarak Doğaya Yeniden Kazandırma Planını, çevre yönetim uygulama takvimini ve bu plan ve takvimi aynen uygulayacağını gösterir noter tasdikli taahhüdü ilgili makamlara sunmakla ve projelerini, verilen kararlara göre gerçekleştirmekle yükümlüdürler. (2) Çevresel etki değerlendirmesi gerekli değildir kararı verilen faaliyet sahipleri ve Çevresel Etki Değerlendirmesi Yönetmeliği dışındaki faaliyet sahipleri bu Yönetmeliğin Ek-1'inde formatı verilen Çevre Yönetim Planını ve bu planı aynen uygulayacaklarını gösterir noter tasdikli taahhüdü ilgili İl Çevre ve Orman Müdürlüğüne üç nüsha halinde vermekle ve faaliyetlerini, verdikleri plan ve taahhüde göre gerçekleştirmekle yükümlüdürler.",
  "Kum/Çakıl Yön m.14": "MADDE 14 – (1) Bu Yönetmelik çerçevesindeki denetimlerde, Çevre Kanununun 12 nci maddesi uyarınca Bakanlık, İl Çevre ve Orman Müdürlüğü ve Bakanlıkça yetki devri yapılmış kurum veya kuruluşlar yetkilidir.",
  "Kum/Çakıl Yön m.15": "MADDE 15 – (1) Bu Yönetmelik hükümlerine aykırı faaliyette bulunanlara Çevre Kanunu'nun 20 nci maddesi birinci fıkrası (l) bendinin ikinci paragrafına göre idari para cezası ve 15 inci maddesi uyarınca faaliyeti durdurma yaptırımı uygulanır.",
  "Kum/Çakıl Yön m.3": "MADDE 3 – (1) Bu Yönetmelik 9/8/1983 tarihli ve 2872 sayılı Çevre Kanunu'nun Ek–1 inci maddesinin birinci fıkrasının (d) bendine dayanılarak hazırlanmıştır.",
  "Kum/Çakıl Yön m.5": "MADDE 5 – (1) Bu Yönetmelik kapsamındaki faaliyetlerle ilgili sınırlamalar ve yasaklar şunlardır; a) İçme ve kullanma suyu temin edilen kıta içi yüzeysel su kaynaklarında ve bunları besleyen, akar ve kuru derelerde, b) Termal su kaynaklarının birinci ve ikinci derece koruma alanları içerisinde, (...) ç) Denizlerde kıyı çizgisi ile kıyı kenar çizgisi arasındaki bölge ve deniz sahil şeritlerinde, d) Kıyı çizgisinden deniz istikametine doğru 20 metreden daha az derin denizlerde, (...) i) Akarsu ve dere yatakları üzerinde inşa edilmiş köprü, menfez ve benzeri sanat yapıları bulunan akarsu ve dere yataklarında, anılan sanat yapılarından herhangi birine menba yönünde 750 metre ve mansap yönünde 1000 metreden daha yakın mesafe bırakarak yaklaşılacak hallerde, (...) kum, çakıl ve benzeri maddelerin alımına yönelik kum ve çakıl ocağı açılması ve işletilmesine izin verilmez.\n\ni) Akarsu ve dere yatakları üzerinde inşa edilmiş köprü, menfez ve benzeri sanat yapıları bulunan akarsu ve dere yataklarında, anılan sanat yapılarından herhangi birine menba yönünde 750 metre ve mansap yönünde 1000 metreden daha yakın mesafe bırakarak yaklaşılacak hallerde, (...) kum ve çakıl ocağı açılması ve işletilmesine izin verilmez.",
  "Kum/Çakıl Yön m.6": "MADDE 6 – (1) (...) a) Ocak sahasının çevresi beton kazık veya benzerleri ile işaretlenir. Ocak sahasının akarsu yatağı içindeki başlangıç ve bitim noktaları kıyıda çakılacak en az 1,5 metre yüksekliğindeki beton kazıklar ile belirlenir; kazıklar herhangi bir şüpheye mahal vermeyecek şekilde sabit röper noktalarına teknik esaslara uygun olarak yerleştirilir. (...) e) Belirlenecek talveg kotundan daha fazla derine inilmez. (...) ı) Kum, çakıl ve benzeri malzeme alınan yerlere hiçbir şekilde atık bırakılmaz.\n\nk) Akarsu ve kuru dere yataklarından kum, çakıl ve benzeri maddelerin alınması ve işletilmesi faaliyetlerine ilişkin olarak Tarım ve Köyişleri Bakanlığı'ndan söz konusu faaliyet sahası ile ilgili su ürünleri açısından alınacak görüş doğrultusunda faaliyetler yürütülür.",
  "Kum/Çakıl Yön m.7": "MADDE 7 – (1) (...) a) Ekosistem bütünlüğünün korunması ve doğal hayata zarar verilmemesi esastır. b) Kıyının jeomorfolojik yapısının doğal durumu korunur. (...) ç) Deniz ve göl rezervuarlarına su akışı engellenmez. d) Denizlerden, göl yataklarından kum, çakıl ve benzeri maddelerin alınması ve işletilmesi faaliyetlerine ilişkin olarak Tarım ve Köyişleri Bakanlığı'ndan söz konusu faaliyet sahası ile ilgili su ürünleri açısından alınacak görüş doğrultusunda faaliyetler yürütülür. (...) f) Faaliyet sahibince ocak sahası içerisinde derinlik ölçümü yapılabilmesine olanak sağlayacak gerekli ekipman bulundurulur.",
  "Kum/Çakıl Yön m.8": "MADDE 8 – (1) Sulak alanlardan kum, çakıl ve benzeri maddelerin alınması ve işletilmesi faaliyetleri ile ilgili olarak bu Yönetmelikle getirilen hükümlere ilaveten, 17/5/2005 tarihli ve 25818 sayılı Resmî Gazete'de yayımlanan Sulak Alanların Korunması Yönetmeliği hükümleri uygulanır. (2) Faaliyet sahibince ocak sahası içerisinde derinlik ölçümü yapılabilmesine olanak sağlayacak gerekli ekipman bulundurulur.",
  "Kültür/Tabiat m.16": "Korunması gerekli taşınmaz kültür ve tabiat varlıkları ile bunların korunma alanlarında ruhsatsız olarak inşaat yapmak yasaktır. Buralarda ruhsatsız olarak yapılacak inşaatlar ile, koruma amaçlı imar planlarında, plana; sitlerde, sit şartlarına aykırı olarak inşa edilen yapılar hakkında imar mevzuatına göre işlem yapılır.",
  "Kültür/Tabiat m.23": "Korunması gerekli taşınır kültür ve tabiat varlıkları şunlardır: a) (...) Her çeşit hayvan ve bitki fosilleri, insan iskeletleri, çakmak taşları (sleks), volkan camları (obsidyen), kemik veya madeni her türlü aletler, çini, seramik, benzeri kab ve kacaklar, heykeller, figürinler, tabletler, (...) sikkeler, (...) etnografik nitelikteki kültür varlıkları. Osmanlı Padişahlarından Abdülmecit, Abdülaziz, V. Murat, II. Abdülhamit, V. Mehmet Reşat ve Vahidettin ve aynı çağdaki sikkeler, bu Kanuna göre tescile tabi olmaksızın yurt içinde alınıp satılabilirler. Bu madde kararına girmeyen sikkeler bu Kanunun genel hükümlerine tabidir.",
  "Kültür/Tabiat m.26": "Devlet müzeleri içerisinde özel bir ihtisas ve araştırma müzeleri olan askeri müzelerin kurulması, yaşatılması, malzemenin ve uğraş konularının tayin ve tespiti Genelkurmay Başkanlığına aittir. Bu müzelerin görev, yetki ve sorumlulukları ile çalışma düzenleri, Milli Savunma Bakanlığının, Kültür ve Turizm Bakanlığıyla birlikte hazırlayacağı bir yönetmelikte belirtilir.\n\nKoleksiyoncular, ilgili müzeye tescil ettirerek, koleksiyonlarındaki her türlü eseri onbeş gün önce Kültür ve Turizm Bakanlığına haber vermek şartı ile kendi aralarında değiştirebilir veya satabilirler. Satın almada öncelik Kültür ve Turizm Bakanlığına aittir.",
  "Kültür/Tabiat m.3": "(1) \"Kültür varlıkları\"; tarih öncesi ve tarihi devirlere ait bilim, kültür, din ve güzel sanatlarla ilgili bulunan veya tarih öncesi ya da tarihi devirlerde sosyal yaşama konu olmuş bilimsel ve kültürel açıdan özgün değer taşıyan yer üstünde, yer altında veya su altındaki bütün taşınır ve taşınmaz varlıklardır. (2) \"Tabiat varlıkları\"; jeolojik devirlerle, tarih öncesi ve tarihi devirlere ait olup ender bulunmaları veya özellikleri ve güzellikleri bakımından korunması gerekli, yer üstünde, yer altında veya su altında bulunan değerlerdir.\n\n(3) \"Sit\"; tarih öncesinden günümüze kadar gelen çeşitli medeniyetlerin ürünü olup, yaşadıkları devirlerin sosyal, ekonomik, mimari ve benzeri özelliklerini yansıtan kent ve kent kalıntıları, kültür varlıklarının yoğun olarak bulunduğu sosyal yaşama konu olmuş veya önemli tarihi hadiselerin cereyan ettiği yerler ve tespiti yapılmış tabiat özellikleri ile korunması gerekli alanlardır. (...) (7) \"Ören yeri\"; (...) topoğrafik olarak tanımlanabilecek derecede yeterince belirgin ve mütecanis özelliklere sahip, aynı zamanda tarihsel, arkeolojik, sanatsal, bilimsel, sosyal veya teknik bakımlardan dikkate değer, kısmen inşa edilmiş, insan emeği kültür varlıkları ile tabiat varlıklarının birleştiği alanlardır.\n\nb) Kısaltmalar: (1) \"Bakanlık\"; Kültür ve Turizm Bakanlığını, (2) \"Koruma Yüksek Kurulu\"; Kültür Varlıklarını Koruma Yüksek Kurulunu, (3) \"Koruma Bölge Kurulu\"; Kültür Varlıklarını Koruma Bölge Kurulunu, İfade eder.\n\n(4) \"Koruma\"; ve \"Korunma\"; taşınmaz kültür ve tabiat varlıklarında muhafaza, bakım, onarım, restorasyon, fonksiyon değiştirme işlemleri; taşınır kültür varlıklarında ise muhafaza, bakım, onarım ve restorasyon işleridir. (5) \"Korunma alanı\"; taşınmaz kültür ve tabiat varlıklarının muhafazaları veya tarihi çevre içinde korunmalarında etkinlik taşıyan korunması zorunlu olan alandır.\n\n(6) \"Değerlendirme\"; kültür ve tabiat varlıklarının teşhiri, tanzimi, kullanılması ve bilimsel yöntemlerle tanıtılmasıdır. (9) \"Çevre düzenleme projesi\"; ören yerlerinin arkeolojik potansiyelini koruyacak şekilde, denetimli olarak ziyarete açmak, tanıtımını sağlamak, mevcut kullanım ve dolaşımdan kaynaklanan sorunlarını çözmek (...) amacıyla her ören yerinin kendi özellikleri göz önüne alınarak hazırlanacak 1/500, 1/200 ve 1/100 ölçekli düzenleme projeleridir.\n\n(8) \"Koruma amaçlı imar plânı\"; bu Kanun uyarınca belirlenen sit alanlarında (...) kültür ve tabiat varlıklarının sürdürülebilirlik ilkesi doğrultusunda korunması amacıyla (...) nazım ve uygulama imar plânlarının gerektirdiği ölçekteki plânlardır. (15) \"Sokak sağlıklaştırma proje ve uygulamaları\"; kentsel sit alanları ve koruma alanlarında, korunması gerekli taşınmaz kültür varlıkları ile sokaktaki diğer yapıların özgün sokak dokusunu tanımlayan tüm öğelerle birlikte korunması ve belgelenmesine yönelik rölöve, restitüsyon, restorasyon, kentsel tasarım projeleri (...) ve bunların uygulamalarıdır. (16) \"Etkileşim-geçiş sahası\"; korunması gerekli kültür varlıklarını ve sit alanlarını doğrudan etkileyen (...) sit sınırları dışına çıkarılmış veya sit sınırları dışında tutulmuş (...) koruma amaçlı imar planlarının hazırlanma aşamasında gözönünde bulundurulması gereken alanlardır.\n\n(10) \"Yönetim alanı\"; sit alanları, ören yerleri ve etkileşim sahalarının doğal bütünlüğü içerisinde etkin bir şekilde korunması, yaşatılması, değerlendirilmesi (...) amacıyla (...) sınırları ilgili idarelerin görüşleri alınarak Bakanlıkça belirlenen yerlerdir. (11) \"Yönetim plânı\"; yönetim alanının korunmasını, yaşatılmasını, değerlendirilmesini sağlamak amacıyla (...) koruma ve gelişim projesinin, yıllık ve beş yıllık uygulama etaplarını ve bütçesini de gösteren, her beş yılda bir gözden geçirilen plânlardır. (12) \"Bağlantı noktası\"; yönetim alanı sınırlarında yer almamakla birlikte, arkeolojik, coğrafi, kültürel ve tarihi nedenlerle (...) bu yer ile irtibatlandırılan kültürel varlıklardır.\n\n(13) \"Doğal (tabii) sit\"; jeolojik devirlere ait olup, ender bulunmaları nedeniyle olağanüstü özelliklere sahip yer üstünde, yer altında veya su altında bulunan korunması gerekli alanlardır. (14) \"Taşınır tabiat varlıkları\"; jeolojik devirlere ait olup, ender bulunmaları nedeniyle olağanüstü özelliklere sahip yer üstünde, yer altında veya su altında bulunan korunması gerekli taşınır tabii değerlerdir.",
  "Kültür/Tabiat m.4": "Taşınır ve taşınmaz kültür ve tabiat varlıklarını bulanlar, malik oldukları veya kullandıkları arazinin içinde kültür ve tabiat varlığı bulunduğunu bilenler veya yeni haberdar olan malik ve zilyetler, bunu en geç üç gün içinde, en yakın müze müdürlüğüne veya köyde muhtara veya diğer yerlerde mülki idare amirlerine bildirmeye mecburdurlar. (...) Muhtar, aynı gün alınan tedbirlerle birlikte durumu en yakın mülki amire; mülki amir ve diğer makamlar ise on gün içinde, yazı ile Kültür ve Turizm Bakanlığına ve en yakın müze müdürlüğüne bildirir.\n\nBu gibi varlıklar, askeri garnizonlar ve yasak bölgeler içinde bulunursa, usulüne uygun olarak üst komutanlıklara bildirilir.",
  "Kültür/Tabiat m.6": "Korunması gerekli taşınmaz kültür ve tabiat varlıkları şunlardır: a) Korunması gerekli tabiat varlıkları ile 19 uncu yüzyıl sonuna kadar yapılmış taşınmazlar, b) Belirlenen tarihten sonra yapılmış olup önem ve özellikleri bakımından Kültür ve Turizm Bakanlığınca korunmalarında gerek görülen taşınmazlar, c) Sit alanı içinde bulunan taşınmaz kültür varlıkları, d) Milli tarihimizdeki önemleri sebebiyle zaman kavramı ve tescil söz konusu olmaksızın Milli Mücadele ve Türkiye Cumhuriyetinin kuruluşunda büyük tarihi olaylara sahne olmuş binalar ve tesbit edilecek alanlar ile Mustafa Kemal ATATÜRK tarafından kullanılmış evler. Ancak, Koruma Kurullarınca mimari, tarihi, estetik, arkeolojik ve diğer önem ve özellikleri bakımından korunması gerekli bulunmadığı karar altına alınan taşınmazlar, korunması gerekli taşınmaz kültür varlığı sayılmazlar.\n\nKaya mezarlıkları, yazılı, resimli ve kabartmalı kayalar, resimli mağaralar, höyükler, tümülüsler, ören yerleri, akropol ve nekropoller; kale, hisar, burç, sur, tarihi kışla, tabya ve isihkamlar ile bunlarda bulunan sabit silahlar; harabeler, kervansaraylar, han, hamam ve medreseler; kümbet, türbe ve kitabeler, köprüler, su kemerleri, su yolları, sarnıç ve kuyular; (...) camiler, mescitler (...); külliyeler, eski anıt ve duvar kalıntıları; freskler, kabartmalar, mozaikler, peri bacaları ve benzeri taşınmazlar; taşınmaz kültür varlığı örneklerindendir. Tarihi mağaralar, kaya sığınakları; özellik gösteren ağaç ve ağaç toplulukları ile benzerleri; taşınmaz tabiat varlığı örneklerindendir.",
  "Kültür/Tabiat m.64": "a) Bulunan varlık, bunların mülkü içinde ise bu Kanunun 24 üncü ve 25 inci maddeleri uygulanır. Ayrıca ikramiye verilmez. b) Bulunan varlık başkasının mülkü içinde ise Kültür ve Turizm Bakanlığınca varlığın değeri dikkate alınarak, takdir olunacak bedelin % 80'i ikramiye olarak bulan ile mülk sahibi arasında yarı yarıya paylaştırılır. c) Kültür varlığı Devlete ait arazide bulunmuş ise, takdir olunacak bedelin % 40'ı bulana ikramiye olarak verilir. d) (...) korunması gerekli nitelikte olmadığı takdirde (...) 25 inci maddesindeki işlem uygulanır. Ayrıca ikramiye verilmez. e) (...) 4 üncü maddede yazılı süreler içinde haber verilmediğinden dolayı gizlenmiş sayılan kültür varlıklarını haber verenler ile, bunları yakalayan kamu görevlilerine, 1905 sayılı (...) Kanun'da taşınır mallar için gösterilen oranlar dahilinde tespit edilen bedel ikramiye olarak verilir. f) (...) bulan, haber veren veya yakalayan kişiler birden fazla ise verilecek ikramiyeler bunlar arasında eşit olarak paylaştırılır.",
  "Kültür/Tabiat m.65": "Tescil edilen sit alanları ve korunması gerekli taşınmaz kültür ve tabiat varlıkları ile korunma alanlarının bu Kanuna göre tebliğ veya ilan edilmiş olmasına rağmen yıkılmasına, bozulmasına, tahribine, yok olmasına veya her ne suretle olursa olsun zarar görmesine kasten sebebiyet verenler ile (...) izin alınmaksızın inşaî ve fiziki müdahale yapanlar veya yaptıranlar, iki yıldan beş yıla kadar hapis ve beş bin güne kadar adli para cezasıyla cezalandırılır. Bu Kanuna aykırı olarak yıkma veya imar izni verenler, iki yıldan beş yıla kadar hapis (...) cezalandırılır. Birinci ve ikinci fıkralarda belirtilen fiiller, korunması gerekli kültür ve tabiat varlığını yurt dışına kaçırmak amacıyla işlenmiş ise verilecek cezalar bir kat artırılır. (Dördüncü fıkra) Taşınmaz kültür ve tabiat varlıkları ile bunların koruma alanları ve sit alanlarında, 3194 sayılı İmar Kanununun 21 inci maddesi kapsamına giren ruhsata tabi olmayan tadilat ve tamiratları (...) izin almaksızın ya da izne aykırı olarak yapanlar veya yaptıranlar, altı aydan üç yıla kadar hapis veya adli para cezası ile cezalandırılır.",
  "Kültür/Tabiat m.67": "Kültür ve tabiat varlıklarıyla ilgili olarak bildirim yükümlülüğüne mazereti olmaksızın ve bilerek aykırı hareket eden kişi, altı aydan üç yıla kadar hapis cezası ile cezalandırılır. Bildirimi yapılmamış olan kültür ve tabiat varlığını satışa arzeden, satan, veren, satın alan, kabul eden kişi iki yıldan beş yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır. Ancak, bu durumda birinci fıkrada tanımlanan suçtan dolayı ayrıca cezaya hükmolunmaz. Ticareti yasak olmayan taşınır kültür varlıklarının izinsiz olarak ticaretini yapan kişi, altı aydan üç yıla kadar hapis cezası ile cezalandırılır.",
  "Kültür/Tabiat m.68": "Kültür ve tabiat varlıklarını bu Kanuna aykırı olarak yurt dışına çıkaran kişi, beş yıldan oniki yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır.",
  "Kültür/Tabiat m.74": "Kültür varlıkları bulmak amacıyla, izinsiz olarak kazı veya sondaj yapan kişi, iki yıldan beş yıla kadar hapis cezasıyla cezalandırılır. Ancak, kazı veya sondajın yapıldığı yerin, sit alanı veya bu Kanuna göre korunması gerekli başka bir yer olmaması halinde, verilecek cezanın üçte biri indirilir. İzinsiz olarak define araştıranlar, üç aydan iki yıla kadar hapis cezası ile cezalandırılır. Ancak, bu fiillerin yurt dışına kültür varlıklarını kaçırma amacıyla veya kültür varlıklarının korunmasında görevli kişiler tarafından işlenmesi hâlinde, verilecek ceza iki katına kadar artırılır.\n\nKişinin bu maddede tanımlanan suçları işlemek suretiyle bulduğu kültür varlığını soruşturma başlamadan önce mahallî mülkî amire teslim etmesi hâlinde, mahkeme verilecek cezada üçte ikisine kadar indirim yapabilir. İzinsiz olarak define araştıran kişinin, hakkında kovuşturma başlayıncaya kadar, kendisini bu fiili işlemeye gerekli cihazları temin etmek suretiyle sevk eden kişilerin kimliklerini açıklaması ve yakalanmasını sağlaması hâlinde, mahkeme verilecek cezada indirim yapabileceği gibi, ceza verilmesine yer olmadığına da karar verebilir.",
  "Kültür/Tabiat m.75": "Bu Kanun kapsamında kalan suçlar nedeniyle elkonulan taşınır kültür ve tabiat varlıkları müzeye teslim edilir.",
  "KV Silme Yön m.11": "(1) Kişisel veri saklama ve imha politikası hazırlamış olan veri sorumlusu, (...) yükümlülüğünün ortaya çıktığı tarihi takip eden ilk periyodik imha işleminde, kişisel verileri siler, yok eder veya anonim hale getirir. (2) Periyodik imhanın gerçekleştirileceği zaman aralığı, veri sorumlusu tarafından kişisel veri saklama ve imha politikasında belirlenir. Bu süre her halde altı ayı geçemez. (3) Kişisel veri saklama ve imha politikası hazırlama yükümlülüğü olmayan veri sorumlusu, (...) yükümlülüğünün ortaya çıktığı tarihi takip eden üç ay içinde, kişisel verileri siler, yok eder veya anonim hale getirir.",
  "KV Silme Yön m.12": "(1) İlgili kişi, Kanunun 11 inci ve 13 üncü maddelerine istinaden veri sorumlusuna başvurarak kendisine ait kişisel verilerin silinmesini veya yok edilmesini talep ettiğinde; a) Kişisel verileri işleme şartlarının tamamı ortadan kalkmışsa; veri sorumlusu talebe konu kişisel verileri siler, yok eder veya anonim hale getirir. Veri sorumlusu, ilgili kişinin talebini en geç otuz gün içinde sonuçlandırır ve ilgili kişiye bilgi verir.",
  "KV Silme Yön m.4": "c) İmha: Kişisel verilerin silinmesi, yok edilmesi veya anonim hale getirilmesini, (...) ğ) Periyodik imha: Kanunda yer alan kişisel verilerin işlenme şartlarının tamamının ortadan kalkması durumunda kişisel verileri saklama ve imha politikasında belirtilen ve tekrar eden aralıklarla resen gerçekleştirilecek silme, yok etme veya anonim hale getirme işlemini, (...) i) Veri sorumlusu: Kişisel verilerin işleme amaçlarını ve vasıtalarını belirleyen, veri kayıt sisteminin kurulmasından ve yönetilmesinden sorumlu olan gerçek veya tüzel kişiyi, ifade eder.",
  "KV Silme Yön m.7": "(1) Kanunun 5 inci ve 6 ncı maddelerinde yer alan kişisel verilerin işlenme şartlarının tamamının ortadan kalkması halinde, kişisel verilerin veri sorumlusu tarafından resen veya ilgili kişinin talebi üzerine silinmesi, yok edilmesi veya anonim hâle getirilmesi gerekir. (...) (3) Kişisel verilerin silinmesi, yok edilmesi ve anonim hale getirilmesiyle ilgili yapılan bütün işlemler kayıt altına alınır ve söz konusu kayıtlar, diğer hukuki yükümlülükler hariç olmak üzere en az üç yıl süreyle saklanır.",
  "KVKK m.11": "(1) Herkes, veri sorumlusuna başvurarak kendisiyle ilgili; a) Kişisel veri işlenip işlenmediğini öğrenme, b) Kişisel verileri işlenmişse buna ilişkin bilgi talep etme, c) Kişisel verilerin işlenme amacını ve bunların amacına uygun kullanılıp kullanılmadığını öğrenme, ç) Yurt içinde veya yurt dışında kişisel verilerin aktarıldığı üçüncü kişileri bilme, d) Kişisel verilerin eksik veya yanlış işlenmiş olması hâlinde bunların düzeltilmesini isteme, e) 7 nci maddede öngörülen şartlar çerçevesinde kişisel verilerin silinmesini veya yok edilmesini isteme, f) (d) ve (e) bentleri uyarınca yapılan işlemlerin, kişisel verilerin aktarıldığı üçüncü kişilere bildirilmesini isteme, g) İşlenen verilerin münhasıran otomatik sistemler vasıtasıyla analiz edilmesi suretiyle kişinin kendisi aleyhine bir sonucun ortaya çıkmasına itiraz etme, ğ) Kişisel verilerin kanuna aykırı olarak işlenmesi sebebiyle zarara uğraması hâlinde zararın giderilmesini talep etme, haklarına sahiptir.",
  "KVKK m.12": "(1) Veri sorumlusu; a) Kişisel verilerin hukuka aykırı olarak işlenmesini önlemek, b) Kişisel verilere hukuka aykırı olarak erişilmesini önlemek, c) Kişisel verilerin muhafazasını sağlamak, amacıyla uygun güvenlik düzeyini temin etmeye yönelik gerekli her türlü teknik ve idari tedbirleri almak zorundadır. (...) (4) Veri sorumluları ile veri işleyen kişiler, öğrendikleri kişisel verileri bu Kanun hükümlerine aykırı olarak başkasına açıklayamaz ve işleme amacı dışında kullanamazlar. Bu yükümlülük görevden ayrılmalarından sonra da devam eder. (5) İşlenen kişisel verilerin kanuni olmayan yollarla başkaları tarafından elde edilmesi hâlinde, veri sorumlusu bu durumu en kısa sürede ilgilisine ve Kurula bildirir. (...)",
  "KVKK m.13": "(1) İlgili kişi, bu Kanunun uygulanmasıyla ilgili taleplerini yazılı olarak veya Kurulun belirleyeceği diğer yöntemlerle veri sorumlusuna iletir. (2) Veri sorumlusu başvuruda yer alan talepleri, talebin niteliğine göre en kısa sürede ve en geç otuz gün içinde ücretsiz olarak sonuçlandırır. Ancak, işlemin ayrıca bir maliyeti gerektirmesi hâlinde, Kurulca belirlenen tarifedeki ücret alınabilir. (3) Veri sorumlusu talebi kabul eder veya gerekçesini açıklayarak reddeder ve cevabını ilgili kişiye yazılı olarak veya elektronik ortamda bildirir. (...)",
  "KVKK m.18": "(1) Bu Kanunun; a) 10 uncu maddesinde öngörülen aydınlatma yükümlülüğünü yerine getirmeyenler hakkında 5.000 Türk lirasından 100.000 Türk lirasına kadar, b) 12 nci maddesinde öngörülen veri güvenliğine ilişkin yükümlülükleri yerine getirmeyenler hakkında 15.000 Türk lirasından 1.000.000 Türk lirasına kadar, c) 15 inci maddesi uyarınca Kurul tarafından verilen kararları yerine getirmeyenler hakkında 25.000 Türk lirasından 1.000.000 Türk lirasına kadar, ç) 16 ncı maddesinde öngörülen Veri Sorumluları Siciline kayıt ve bildirim yükümlülüğüne aykırı hareket edenler hakkında 20.000 Türk lirasından 1.000.000 Türk lirasına kadar, d) (Ek:2/3/2024-7499/35 md.) 9 uncu maddenin beşinci fıkrasında öngörülen bildirim yükümlülüğünü yerine getirmeyenler hakkında 50.000 Türk lirasından 1.000.000 Türk lirasına kadar, idari para cezası verilir. (2) (Değişik:2/3/2024-7499/35 md.) Birinci fıkranın (a), (b), (c) ve (ç) bentlerinde öngörülen idari para cezaları veri sorumlusu, (d) bendinde öngörülen idari para cezası veri sorumlusu veya veri işleyen gerçek kişiler ile özel hukuk tüzel kişileri hakkında uygulanır. (3) (Ek:2/3/2024-7499/35 md.) Kurulca verilen idari para cezalarına karşı, idare mahkemelerinde dava açılabilir. (...)",
  "KVKK m.28": "(1) Bu Kanun hükümleri aşağıdaki hâllerde uygulanmaz: a) Kişisel verilerin, üçüncü kişilere verilmemek ve veri güvenliğine ilişkin yükümlülüklere uyulmak kaydıyla gerçek kişiler tarafından tamamen kendisiyle veya aynı konutta yaşayan aile fertleriyle ilgili faaliyetler kapsamında işlenmesi. b) Kişisel verilerin resmi istatistik ile anonim hâle getirilmek suretiyle araştırma, planlama ve istatistik gibi amaçlarla işlenmesi. c) Kişisel verilerin millî savunmayı, millî güvenliği, kamu güvenliğini, kamu düzenini, ekonomik güvenliği, özel hayatın gizliliğini veya kişilik haklarını ihlal etmemek ya da suç teşkil etmemek kaydıyla, sanat, tarih, edebiyat veya bilimsel amaçlarla ya da ifade özgürlüğü kapsamında işlenmesi. ç) Kişisel verilerin millî savunmayı, millî güvenliği, kamu güvenliğini, kamu düzenini veya ekonomik güvenliği sağlamaya yönelik olarak kanunla görev ve yetki verilmiş kamu kurum ve kuruluşları tarafından yürütülen önleyici, koruyucu ve istihbari faaliyetler kapsamında işlenmesi. d) Kişisel verilerin soruşturma, kovuşturma, yargılama veya infaz işlemlerine ilişkin olarak yargı makamları veya infaz mercileri tarafından işlenmesi. (2) Bu Kanunun amacına ve temel ilkelerine uygun ve orantılı olmak kaydıyla veri sorumlusunun aydınlatma yükümlülüğünü düzenleyen 10 uncu, zararın giderilmesini talep etme hakkı hariç, ilgili kişinin haklarını düzenleyen 11 inci ve Veri Sorumluları Siciline kayıt yükümlülüğünü düzenleyen 16 ncı maddeleri aşağıdaki hâllerde uygulanmaz: a) Kişisel veri işlemenin suç işlenmesinin önlenmesi veya suç soruşturması için gerekli olması. b) İlgili kişinin kendisi tarafından alenileştirilmiş kişisel verilerin işlenmesi. c) Kişisel veri işlemenin kanunun verdiği yetkiye dayanılarak görevli ve yetkili kamu kurum ve kuruluşları ile kamu kurumu niteliğindeki meslek kuruluşlarınca, denetleme veya düzenleme görevlerinin yürütülmesi ile disiplin soruşturma veya kovuşturması için gerekli olması. ç) Kişisel veri işlemenin bütçe, vergi ve mali konulara ilişkin olarak Devletin ekonomik ve mali çıkarlarının korunması için gerekli olması.",
  "KVKK m.3": "(1) Bu Kanunun uygulanmasında; a) Açık rıza: Belirli bir konuya ilişkin, bilgilendirilmeye dayanan ve özgür iradeyle açıklanan rızayı, b) Anonim hâle getirme: Kişisel verilerin, başka verilerle eşleştirilerek dahi hiçbir surette kimliği belirli veya belirlenebilir bir gerçek kişiyle ilişkilendirilemeyecek hâle getirilmesini, (...) ç) İlgili kişi: Kişisel verisi işlenen gerçek kişiyi, d) Kişisel veri: Kimliği belirli veya belirlenebilir gerçek kişiye ilişkin her türlü bilgiyi, e) Kişisel verilerin işlenmesi: Kişisel verilerin tamamen veya kısmen otomatik olan ya da herhangi bir veri kayıt sisteminin parçası olmak kaydıyla otomatik olmayan yollarla elde edilmesi, kaydedilmesi, depolanması, (...) gibi veriler üzerinde gerçekleştirilen her türlü işlemi, f) Kurul: Kişisel Verileri Koruma Kurulunu, g) Kurum: Kişisel Verileri Koruma Kurumunu, ğ) Veri işleyen: Veri sorumlusunun verdiği yetkiye dayanarak onun adına kişisel verileri işleyen gerçek veya tüzel kişiyi, (...) ı) Veri sorumlusu: Kişisel verilerin işleme amaçlarını ve vasıtalarını belirleyen, veri kayıt sisteminin kurulmasından ve yönetilmesinden sorumlu olan gerçek veya tüzel kişiyi, ifade eder.",
  "KVKK m.4": "(1) Kişisel veriler, ancak bu Kanunda ve diğer kanunlarda öngörülen usul ve esaslara uygun olarak işlenebilir. (2) Kişisel verilerin işlenmesinde aşağıdaki ilkelere uyulması zorunludur: a) Hukuka ve dürüstlük kurallarına uygun olma. b) Doğru ve gerektiğinde güncel olma. c) Belirli, açık ve meşru amaçlar için işlenme. ç) İşlendikleri amaçla bağlantılı, sınırlı ve ölçülü olma. d) İlgili mevzuatta öngörülen veya işlendikleri amaç için gerekli olan süre kadar muhafaza edilme.",
  "KVKK m.5": "(1) Kişisel veriler ilgili kişinin açık rızası olmaksızın işlenemez. (2) Aşağıdaki şartlardan birinin varlığı hâlinde, ilgili kişinin açık rızası aranmaksızın kişisel verilerinin işlenmesi mümkündür: a) Kanunlarda açıkça öngörülmesi. b) Fiili imkânsızlık nedeniyle rızasını açıklayamayacak durumda bulunan veya rızasına hukuki geçerlilik tanınmayan kişinin kendisinin ya da bir başkasının hayatı veya beden bütünlüğünün korunması için zorunlu olması. c) Bir sözleşmenin kurulması veya ifasıyla doğrudan doğruya ilgili olması kaydıyla, sözleşmenin taraflarına ait kişisel verilerin işlenmesinin gerekli olması. ç) Veri sorumlusunun hukuki yükümlülüğünü yerine getirebilmesi için zorunlu olması. d) İlgili kişinin kendisi tarafından alenileştirilmiş olması. e) Bir hakkın tesisi, kullanılması veya korunması için veri işlemenin zorunlu olması. f) İlgili kişinin temel hak ve özgürlüklerine zarar vermemek kaydıyla, veri sorumlusunun meşru menfaatleri için veri işlenmesinin zorunlu olması.",
  "KVKK m.6": "(1) Kişilerin ırkı, etnik kökeni, siyasi düşüncesi, felsefi inancı, dini, mezhebi veya diğer inançları, kılık ve kıyafeti, dernek, vakıf ya da sendika üyeliği, sağlığı, cinsel hayatı, ceza mahkûmiyeti ve güvenlik tedbirleriyle ilgili verileri ile biyometrik ve genetik verileri özel nitelikli kişisel veridir. (2) (Mülga:2/3/2024-7499/33 md.) (3) (Değişik:2/3/2024-7499/33 md.) Özel nitelikli kişisel verilerin işlenmesi yasaktır. Ancak bu verilerin işlenmesi; a) İlgili kişinin açık rızasının olması, b) Kanunlarda açıkça öngörülmesi, c) Fiili imkânsızlık nedeniyle rızasını açıklayamayacak durumda bulunan (...) kişinin, kendisinin ya da bir başkasının hayatı veya beden bütünlüğünün korunması için zorunlu olması, ç) İlgili kişinin alenileştirdiği kişisel verilere ilişkin ve alenileştirme iradesine uygun olması, d) Bir hakkın tesisi, kullanılması veya korunması için zorunlu olması, e) Sır saklama yükümlülüğü altında bulunan kişiler veya yetkili kurum ve kuruluşlarca, kamu sağlığının korunması, koruyucu hekimlik, tıbbi teşhis, tedavi ve bakım hizmetlerinin yürütülmesi (...) amacıyla gerekli olması, f) İstihdam, iş sağlığı ve güvenliği, sosyal güvenlik, sosyal hizmetler ve sosyal yardım alanlarındaki hukuki yükümlülüklerin yerine getirilmesi için zorunlu olması, g) Siyasi, felsefi, dini veya sendikal amaçlarla kurulan vakıf, dernek ve diğer kâr amacı gütmeyen kuruluş (...) mevcut veya eski üyelerine (...) yönelik olması, halinde mümkündür. (4) Özel nitelikli kişisel verilerin işlenmesinde, ayrıca Kurul tarafından belirlenen yeterli önlemlerin alınması şarttır.",
  "KVKK m.7": "(1) Bu Kanun ve ilgili diğer kanun hükümlerine uygun olarak işlenmiş olmasına rağmen, işlenmesini gerektiren sebeplerin ortadan kalkması hâlinde kişisel veriler resen veya ilgili kişinin talebi üzerine veri sorumlusu tarafından silinir, yok edilir veya anonim hâle getirilir. (2) Kişisel verilerin silinmesi, yok edilmesi veya anonim hâle getirilmesine ilişkin diğer kanunlarda yer alan hükümler saklıdır. (3) Kişisel verilerin silinmesine, yok edilmesine veya anonim hâle getirilmesine ilişkin usul ve esaslar yönetmelikle düzenlenir.",
  "Mera m.19": "Muhtarlar ve belediye başkanları; mera, yaylak ve kışlakların ve sınır işaretlerinin korunmasından (...) sorumludur. (...) Muhtarlar ve belediye başkanları, mera, yaylak ve kışlaklara tecavüz olduğu takdirde durumu derhal Bakanlık il veya ilçe müdürlüğüne, il ve ilçe müdürlükleri de valilik veya kaymakamlığa bildirmekle yükümlüdürler. Bu makamlarca 3091 sayılı Taşınmaz Mal Zilyedliğine Yapılan Tecavüzlerin Önlenmesi Hakkında Kanun veya 2886 sayılı Devlet İhale Kanununun 75 inci maddesi uyarınca gerekli işlemler yapılır.",
  "Mera m.20": "Yaylak ve kışlaklarda, 442 sayılı Köy Kanununda öngörülen inşaatlar ile valiliklerden izin alınmak suretiyle imar mevzuatına göre yapılacak kullanma amacına uygun mandıra, suluk, sundurma ve süreklilik göstermeyen barınak ve ağıllar ile Turizm Bakanlığının talebi üzerine turizme açılması uygun görülen bölgelerde ahşap yapılar dışında, ev, ahır ve benzeri inşaatlar yapılamaz.",
  "Mera m.22": "Çiftçi ailelerinin bir mera, yaylak ve kışlaktan yararlanabilmeleri için, bu yerin bulunduğu köy veya belediye sınırları içinde, tahsisin yapıldığı tarihte en az altı aydan beri ikamet ediyor olmaları gerekir. Ancak, Devletçe naklen yerleştirilenler için bu şart aranmaz.",
  "Mera m.23": "Mera, yaylak ve kışlağa, komisyonun tahsis kararında belirtilen miktardan fazla hayvan sokulamaz. Ancak, daha sonra bakım, koruma ve ıslah sonucu mera, yaylak ve kışlağın otlatma ve barındırma kapasitesinde bir artışın olması halinde, köy veya belediyelerin teklifi üzerine veya doğrudan doğruya komisyonca yeniden tespit yapılarak otlatılacak hayvan miktarı artırılabilir.",
  "Mera m.26": "Bu alanlarda otlatma hakkının üstünde hayvan otlatılamaz, otlatma haklarından fazla hayvan otlatanlardan bu ücret, fazla her hayvan sayısı için üç katı olarak tahsil edilir. Muhtarlık veya belediyeler tarafından bu amaçla yapılacak tahsilat, o yerin mera alanlarının ıslah ve geliştirilmesi amacı ile köy sandığına veya belediye bütçesinde ayrı bir hesaba gelir kaydedilir ve amacı dışında kullanılamaz. Komisyonca tespit edilen ücret ve para cezalarının takip ve tahsilinde 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun hükümleri uygulanır.",
  "Mera m.27": "26 ncı maddede öngörülen hususlara riayet etmeyen ve yükümlülüklerini yerine getirmeyenlerin mera, yaylak ve kışlaklardan yararlanma hakları, Bakanlık taşra teşkilatının teklifi ve valilik onayı ile en az 7 gün, en çok 30 gün süre ile geçici olarak, aynı fiilin tekrarı halinde ise yararlanma hakkı bir otlatma dönemi için iptal edilir.",
  "Mera m.3": "c) Çayır: Taban suyunun yüksek bulunduğu veya sulanabilen yerlerde biçilmeye elverişli, yem üretilen ve genellikle kuru ot üretimi için kullanılan yeri, d) Mera: Hayvanların otlatılması ve otundan yararlanılması için tahsis edilen veya kadimden beri bu amaçla kullanılan yeri, e) Yaylak: Çiftçilerin hayvanları ile birlikte yaz mevsimini geçirmeleri, hayvanlarını otlatmaları ve otundan yararlanmaları için tahsis edilen veya kadimden beri bu amaçla kullanılan yeri, f) Kışlak: Hayvanların kış mevsiminde barındırılması ve otundan yararlanılması için tahsis edilen veya kadimden beri bu amaçla kullanılan yeri, ifade eder.\n\nn) Büyükbaş Hayvan Birimi: Hayvan sayısının, bir büyükbaş hayvan birimi olan 500 kg canlı ağırlığa çevrilerek ifade edilen şeklini, ifade eder.",
  "Mera m.4": "Mera, yaylak ve kışlakların kullanma hakkı bir veya birden çok köy veya belediyeye aittir. Bu yerler Devletin hüküm ve tasarrufu altındadır. (...) Mera, yaylak ve kışlaklar; özel mülkiyete geçirilemez, amacı dışında kullanılamaz, zaman aşımı uygulanamaz, sınırları daraltılamaz. Ancak, kullanım hakkı kiralanabilir. Kiralama ilkeleri yönetmelikle belirlenir.",
  "Mera m.6": "Mera, yaylak ve kışlakların tespit, tahdit ve tahsisi Gıda, Tarım ve Hayvancılık Bakanlığınca yapılır. Bu amaçla valinin görevlendireceği bir vali yardımcısı başkanlığında; Bakanlık il müdürü, Bakanlık il müdürlüğünden konu uzmanı bir ziraat mühendisi, Devlet Su İşleri Genel Müdürlüğü yetkili temsilcisi, Orman Genel Müdürlüğü yetkili temsilcisi, ilgili köy veya mahalle muhtarı, defterdarlıktan veya bulunamaması halinde vali tarafından görevlendirilecek bir hukukçu, Milli Emlak Müdürlüğünden bir temsilci, Kadastro Müdürlüğünden bir teknik eleman, Ziraat Odası Başkanlığından bir temsilci ve ilgisine göre genel kolluk biriminde görevli bir temsilci olmak üzere on bir kişiden oluşan bir komisyon kurulur. Komisyonlar valilik onayı ile oluşturulur. Vali yardımcısının bulunmadığı durumlarda komisyona Bakanlık il müdürü veya görevlendireceği konu uzmanı bir ziraat mühendisi başkanlık eder.",
  "OHAL m.1": "Madde 1 – Bu Kanunun amacı, a) Tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım, b) Anayasa ile kurulan hür demokrasi düzenini veya temel hak ve hürriyetleri ortadan kaldırmaya yönelik yaygın şiddet hareketlerine ait ciddi belirtilerin ortaya çıkması veya şiddet olayları sebebiyle kamu düzeninin ciddi şekilde bozulması, Durumlarında olağanüstü hal ilan edilmesi ve usulleriyle olağanüstü hallerde uygulanacak hükümleri belirlemektir.",
  "OHAL m.10": "Madde 10 – Ağır ekonomik bunalım sebebiyle olağanüstü hal ilanı durumunda, ekonominin düzenlenmesi ve iyileştirilmesi amacı ile mal, sermaye ve hizmet piyasalarını yönlendirici; vergi, para, kredi, kira, ücret ve fiyat politikalarını belirleyici ve çalışmaya ilişkin her türlü tedbir ve yükümlülüklerin tespiti, tanzimi ve takibi konularında Cumhurbaşkanlığı kararnamesi çıkarılabilir. (...)",
  "OHAL m.11": "Madde 11 – Bu Kanunun 3 üncü maddesinin birinci fıkrasının (b) bendi gereğince olağanüstü hal ilanında; genel güvenlik, asayiş ve kamu düzenini korumak, şiddet olaylarının yaygınlaşmasını önlemek amacıyla 9 uncu maddede öngörülen tedbirlere ek olarak aşağıdaki tedbirler de alınabilir: a) Sokağa çıkmayı sınırlamak veya yasaklamak, b) Belli yerlerde veya belli saatlerde kişilerin dolaşmalarını ve toplanmalarını, araçların seyirlerini yasaklamak, c) Kişilerin; üstünü, araçlarını, eşyalarını aratmak ve bulunacak suç eşyası ve delil niteliğinde olanlarına el koymak, d) Olağanüstü hal ilan edilen bölge sakinleri ile bu bölgeye hariçten girecek kişiler için kimlik belirleyici belge taşıma mecburiyeti koymak, e) Gazete, dergi, broşür, kitap, el ve duvar ilanı ve benzerlerinin basılmasını, çoğaltılmasını, yayımlanmasını ve dağıtılmasını, bunlardan olağanüstü hal bölgesi dışında basılmış veya çoğaltılmış olanların bölgeye sokulmasını ve dağıtılmasını yasaklamak veya izne bağlamak; basılması ve neşri yasaklanan kitap, dergi, gazete, broşür, afiş ve benzeri matbuayı toplatmak, f) Söz, yazı, resmi, film, plak, ses ve görüntü bantlarını ve sesle yapılan her türlü yayımı denetlemek, gerektiğinde kayıtlamak veya yasaklamak, g) Hassasiyet taşıyan kamuya veya kişilere ait kuruluşlara ve bankalara, kendi iç güvenliklerini sağlamak için özel koruma tedbirleri aldırmak veya bunların artırılmasını istemek, h) Her nevi sahne oyunlarını ve gösterilen filmleri denetlemek, gerektiğinde durdurmak veya yasaklamak, i) Ruhsatlı da olsa her nevi silah ve mermilerin taşınmasını veya naklini yasaklamak, j) Her türlü cephaneler, bombalar, tahrip maddeleri, patlayıcı maddeler, radyoaktif maddeler veya yakıcı, aşındırıcı, yaralayıcı eczalar veya diğer her türlü zehirler ve boğucu gazlar veya benzeri maddelerin bulundurulmasını, hazırlanmasını, yapılmasını veya naklini izne bağlamak veya yasaklamak ve bunlar ile bunların hazırlanmasına veya yapılmasına yarayan eşya, alet veya araçların teslimini istemek veya toplatmak, k) Kamu düzeni veya kamu güvenini bozabileceği kanısını uyandıran kişi ve toplulukların bölgeye girişini yasaklamak, bölge dışına çıkarmak veya bölge içerisinde belirli yerlere girmesini veya yerleşmesini yasaklamak, l) Bölge dahilinde güvenliklerinin sağlanması gerekli görülen tesis veya teşekküllerin bulunduğu alanlara giriş ve çıkışı düzenlemek, kayıtlamak veya yasaklamak, m) Kapalı ve açık yerlerde yapılacak toplantı ve gösteri yürüyüşlerini yasaklamak, ertelemek, izne bağlamak veya toplantı ve gösteri yürüyüşlerinin yapılacağı yer ve zamanı tayin, tespit ve tahsis etmek, izne bağladığı her türlü toplantıyı izletmek, gözetim altında tutmak veya gerekiyorsa dağıtmak, n) (Ek: 14/11/1984 - 3076/1 md.) İşçinin isteği, ahlak ve iyi niyet kurallarına uymayan haller, sağlık sebepleri, normal emeklilik ve belirli süresinin bitişi nedeniyle hizmet aktinin sona ermesi veya feshi dışında kalan hallerde işçi çıkartmalarını işverenin de durumunu dikkate alarak üç aylık bir süreyi aşmamak kaydıyla izne bağlamak veya ertelemek, o) (Ek: 14/11/1984 - 3076/1 md.) Dernek faaliyetlerini; her dernek hakkında ayrı karar almak ve üç ayı geçmemek kaydıyla durdurmak, (ö bendi mülga/Anayasa Mahkemesince iptal); p) (...) valinin talebi üzerine ilgili komutan, eylemcileri ele geçirmek veya tesirsiz hale getirmek maksadı ile, her defasında Genelkurmay Başkanlığı kanalı ile Hükümetin müsaadesi tahtında, ihtiyaca göre, Kara, Hava veya Deniz Kuvvetleri unsurları ile mahdut hedefli sınır ötesi harekat planlayıp icra etmek.",
  "OHAL m.12": "Madde 12 – Olağanüstü hal ilanında koordinasyon, Cumhurbaşkanlığınca veya Cumhurbaşkanının görevlendireceği Cumhurbaşkanı yardımcısı ya da bakanlıkça sağlanır. Bunun için, olağanüstü hal ilanına sebep olan konu ile ilgili bulunan bakanlıklar temsilcilerinden meydana gelen Olağanüstü Hal Koordinasyon Kurulu kurulur. (...) Olağanüstü Hal Koordinasyon Kurulunun kuruluş ve çalışma esasları, çıkarılacak yönetmelikte gösterilir. Ağır ekonomik bunalım sebebiyle olağanüstü hal ilanında 10 uncu madde hükümleri saklıdır. Madde 13 – Bölge valiliği teşkilat ve birimlerinin görevleri saklı kalmak üzere, olağanüstü hal ilan edilen bölgelerde; olağanüstü hal ilanını gerektiren olayları ve tedbirlerin uygulanmasını izlemek, değerlendirmek, bunlarla ilgili önerilerde bulunmak üzere bölge valisinin başkanlığında, görevlendireceği il valileri ile diğer kamu kuruluşları yöneticilerinin, garnizon komutanı veya görevlendireceği bir temsilcinin üye olarak katılacağı bölge olağanüstü hal kurulu kurulur. Bölge valisinin gerek görmesi veya olağanüstü halin bir ilde ilanı halinde, il merkezlerinde ve ilçelerde birer olağanüstü hal bürosu oluşturulur. İl bürolarına il valisi veya görevlendireceği vali muavini, ilçe bürolarına kaymakamlar başkanlık eder. (...) Olağanüstü hal kurul ve bürolarının kuruluş, toplanma, karar alma, çalışma usul ve esasları yönetmelikte belirlenir.",
  "OHAL m.2": "Madde 2 – Bu Kanun; olağanüstü hal ilanına tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım hallerinde ilan edilen olağanüstü hallerde vatandaşlar için getirilecek para, mal ve çalışma yükümlülükleri ile olağanüstü hallerin her türü için ayrı ayrı geçerli olmak üzere, temel hak ve hürriyetlerin nasıl sınırlanacağı veya nasıl durdurulacağına, halin gerektirdiği tedbirlerin nasıl ve ne suretle alınacağına, kamu hizmeti görevlilerine ne gibi yetkiler verileceğine, görevlilerin durumlarında ne gibi değişiklikler yapılacağına ve olağanüstü yönetim usullerine ilişkin hükümleri kapsar.",
  "OHAL m.3": "Madde 3 – Cumhurbaşkanı: a) Tabii afet, tehlikeli salgın hastalıklar veya ağır ekonomik bunalım hallerinden birinin veya birden fazlasının görülmesi durumunda, b) Anayasa ile kurulan hür demokrasi düzenini veya temel hak ve hürriyetleri ortadan kaldırmaya yönelik yaygın şiddet hareketlerine ait ciddi belirtilerin ortaya çıkması veya şiddet olayları sebebiyle kamu düzeninin ciddi şekilde bozulması hallerinde, Milli Güvenlik Kurulunun görüşünü de aldıktan sonra; Yurdun bir veya birden fazla bölgesinde veya bütününde altı ayı geçmemek üzere olağanüstü hal ilan edebilir. Olağanüstü hal kararı Resmi Gazete'de yayımlanır ve hemen Türkiye Büyük Millet Meclisinin onayına sunulur. Türkiye Büyük Millet Meclisi tatilde ise derhal toplantıya çağrılır. Meclis, olağanüstü hal süresini değiştirebilir. Cumhurbaşkanının istemi üzerine, her defasında dört ayı geçmemek üzere, süreyi uzatabilir veya olağanüstü hali kaldırabilir. Cumhurbaşkanı, olağanüstü halin bu maddenin birinci fıkrasının (b) bendi gereğince ilanından sonra; süreyi uzatmaya, kapsamını değiştirmeye veya olağanüstü hali kaldırmaya ilişkin hususlarda da karar almadan önce Milli Güvenlik Kurulunun görüşünü alır.",
  "OHAL m.4": "Madde 4 – Olağanüstü hal süresince, Cumhurbaşkanı olağanüstü halin gerekli kıldığı konularda Anayasanın 91 inci maddesindeki kısıtlamalara ve usule bağlı olmaksızın, kanun hükmünde kararnameler çıkarabilir. Bu kararnameler Resmi Gazete'de yayımlanır ve aynı gün Türkiye Büyük Millet Meclisinin onayına sunulur.",
  "OHAL m.5": "Madde 5 – Tabii afet ve tehlikeli salgın hastalıklar sebepleriyle olağanüstü hal ilan edilmesi durumunda; felakete uğrayanların kurtarılması, meydana gelen hasar ve zararın telafisi için ihtiyaç duyulan ve hemen sağlanamayan para ve her türlü taşınır ve taşınmaz mallar ve yapılması gereken işler; para, mal ve çalışma yükümlülüğü yoluyla sağlanır. Madde 6 – Tabii afet ve tehlikeli salgın hastalıklar sebebiyle olağanüstü hal ilan edilmesi durumunda gerekli harcamalar öncelikle kamu kaynakları ile yardımlardan sağlanır. (...) Madde 7 – (...) bölge içindeki kamu kurum ve kuruluşlarıyla tüzel ve gerçek kişiler, kendilerinden istenecek veya yükümlülük konulacak arazi, arsa, bina, tesis, araç, gereç, yiyecek, ilaç ve tıbbi malzeme ile giyecek ve diğer maddeleri vermek zorundadırlar. Bu amaçla; öncelikle o bölgedeki genel ve katma bütçeli dairelere, kamu iktisadi devlet teşekkülleri ve kuruluşları ile bunlara bağlı müesseselere ve mahalli idarelere başvurulur. İhtiyaçların bu kaynaklardan zamanında ve yeterince karşılanmaması halinde, imkan ve kaynakları da dikkate alınarak, bölgedeki özel kuruluşlara ve gerçek kişilere ait olanlara yükümlülük konulur.",
  "OHAL m.8": "Madde 8 – Tabii afet ve tehlikeli salgın hastalıklar sebepleriyle olağanüstü hal ilan edilen bölgelerde bulunan 18 - 60 yaşları arasındaki bütün vatandaşlar, olağanüstü hal sebebiyle kendilerine verilecek işleri yapmakla yükümlüdürler. Görevlendirmelerde; iş mevzuatının çalıştırma yasağı ile ilgili hükümleri çalıştırılacak kişilerin yaş, cinsiyet, sağlık, meslekleri, meşguliyetleri ve sosyal durumları ile aile ve bakıma muhtaç yakınları gözönünde bulundurulur. (...)",
  "OHAL m.9": "Madde 9 – Tabii afet ve tehlikeli salgın hastalıklar sebebiyle olağanüstü hal ilanında, olağanüstü hal ilanını gerektiren hususlar gözönünde bulundurularak aşağıda yazılı tedbirler alınabilir: a) Bölgenin belirli yerlerinde yerleşimi yasaklamak, belirli yerleşim yerlerine girişi ve buralardan çıkışı sınırlamak, belli yerleşim yerlerini boşaltmak veya başka yerlere nakletmek, b) Resmi ve özel her derecedeki öğretim ve eğitim kurumlarında öğrenime ara vermek ve öğrenci yurtlarını süreli veya süresiz olarak kapatmak, c) Gazino, lokanta, birahane, meyhane, lokal, taverna, diskotek, bar, dansing, sinema, tiyatro ve benzeri eğlence yerleri ile kulüp vesair oyun salonlarını, otel, motel, kamping, tatil köyü ve benzeri konaklama tesislerini denetlemek ve bunların açılma ve kapanma zamanını tayin etmek, sınırlamak, gerektiğinde kapatmak ve bu yerleri olağanüstü halin icaplarına göre kullanmak, d) Bölgede olağanüstü hal hizmetlerinin yürütülmesi ile görevli personelin yıllık izinlerini sınırlamak veya kaldırmak, e) Bölge sınırları içerisindeki tüm haberleşme araç ve gereçlerinden yararlanmak ve gerektiğinde bu amaçla geçici olarak bunlara elkoymak, f) Tehlike arz eden binaları yıkmak; sağlığı tehdit ettiği tespit olunan taşınır ve taşınmaz mallar ile sağlığa zararlı gıda maddelerini ve mahsullerini imha etmek, g) Belli gıda maddeleri ile hayvan ve hayvan yemi ve hayvan ürünlerinin bölge dışına çıkarılmasını veya bölgeye sokulmalarını kontrol etmek, sınırlamak veya gerektiğinde yasaklamak, h) Gerekli görülen zaruri ihtiyaç maddelerinin dağıtımını düzenlemek, i) Halkın beslenmesi, ısınması, temizliği ve aydınlanması için gerekli gıda madde ve eşyalarla her türlü yakıtın, sağlığın korunmasında, tedavide ve tıpta kullanılan ilaç, kimyevi madde, alet ve diğer şeylerin, inşaat, sanayi, ulaşım ve tarımda kullanılan eşya ve maddelerin, kamu için gerekli diğer mal, eşya, araç, gereç ve her türlü maddelerin imali, satımı, dağıtımı, depolanması ve ticareti konularında gerekli tedbirleri almak, bu yerlere gerektiğinde elkoymak, kontrol etmek ve bu malları satıştan kaçınan, saklayan, kaçıran, fazla fiyatla satan, imalatını durduran veya yavaşlatanlar hakkında fiilin işleniş şekli veya niteliği de nazara alınarak işyeri bulunduğu mahal için hayati önem taşımadığı takdirde işyerini kapatmak, j) Kara, deniz ve hava trafik düzenine ilişkin tedbirleri almak, ulaştırma araçlarının bölgeye giriş ve çıkışlarını kayıtlamak veya yasaklamak.",
  "Orman m.14": "Devlet ormanlarında: A) Yetişmiş veya yetiştirilmiş fidanları kesmek, sökmek, ekim sahalarını bozmak, yaş ağaçları boğmak, yaralamak, tepelerini veya dallarını kesmek veya koparmak veya ağaçlardan yalamuk, pedavra hartama çıkarmak; B) Dikili yaş veya kuru ağaçları kesmek veya bunları kökünden sökmek veya bunlardan kabuk veya çıra veya katran veya sakız çıkarmak, yatık veya devrik ağaçları kesmek veya götürmek, kök sökmek, kömür yapmak; C) Palamut, ıhlamur çiçeği, her çeşit orman örtüsü, mazı kozalağı tıbbi ve sınai nebatları veya orman tohumlarını toplayıp götürmek; D) Ormanlardaki göl, gölet, baraj ve derelerde dinamit atmak veya zehir bırakmak suretiyle avlanmak; E) Ticaret amacıyla olmaksızın kendi ihtiyacı için toprak, kum ve çakıl çıkarmak; F) Nakil vasıtaları ile ormanlara yıkıntı veya inşaat atığı atmak ya da hafriyat veya çöp dökmek; Yasaktır.",
  "Orman m.15": "Ormanın gelişmesi için idarenin fenni maksatlarla yapacağı ameliyat dışında; 14 üncü maddenin (A) bendinde yazılı fiillerden fidan sökmek veya dal kesmek ile orman hasılatı elde etmek üzere aynı maddenin (B) bendinde ve muhtelif faydalar sağlamak için (C) bendinde yazılı fiil ve hareketleri yapmak, orman idaresinin izin ve müsaadesine bağlıdır.",
  "Orman m.16": "(Değişik birinci fıkra:23/3/2023-7442/10 md.) Devlet ormanları içinde maden aranması ve işletilmesi ile madencilik faaliyeti için zorunlu; tesis, yol, enerji, su, haberleşme ve altyapı tesislerine, fon bedelleri hariç, bedeli alınarak Tarım ve Orman Bakanlığınca izin verilir. (...) Ruhsatname veya imtiyaz almış olanlarla, ruhsatname veya imtiyaz alacaklar, işe başlamadan evvel çalışma sahalarını orman idaresine haber vermeye ve ormana zarar gelebilecek hallerde, orman idaresinin göstereceği tedbirleri almaya ve yapmaya mecburdurlar.",
  "Orman m.17": "(Değişik ikinci fıkra:23/3/2023-7442/11 md.) Devlet ormanlarının herhangi bir suretle yanmasından veya açıklıklarından faydalanılarak işgal, açma veya hangi şekilde olursa olsun kesme, sökme, budama veya boğma yollarıyla elde edilecek yerlerle buralarda yapılacak her türlü yapı ve tesisler, şahıslar adına tapuya tescil olunamaz. Buralara doğrudan doğruya orman idaresince el konulur. Devlet ormanlarında el konulan bütün yapı ve tesisler, inşa aşamasında olanlar da dâhil olmak üzere, hiçbir karar alınmasına lüzum kalmaksızın, Orman Genel Müdürlüğü tarafından derhal yıkılır veya ihtiyaç görüldüğü takdirde ormancılık hizmetlerinde kullanılabilir. (...) Savunma, ulaşım, enerji, haberleşme, su, atık su, petrol, doğalgaz, (...) altyapı, katı atık bertaraf ve düzenli depolama tesislerinin; baraj, gölet, sokak hayvanları bakımevi ve mezarlıkların; Devlete ait sağlık, eğitim, ve spor tesisleri ve bunlarla ilgili her türlü yer ve binanın Devlet ormanları üzerinde bulunması veya yapılmasında kamu yararı ve zaruret olması halinde, gerçek ve tüzel kişilere bedeli mukabilinde Çevre ve Orman Bakanlığınca izin verilebilir. Devletçe yapılan ve/veya işletilenlerden bedel alınmaz. Bu izin süresi kırkdokuz yılı geçemez. (...)\n\n(Değişik birinci fıkra: 19/4/2012-6292/13 md.) Devlet ormanları içinde bu ormanların korunması, istihsal ve imarı ile alakalı olarak yapılacak her nevi bina ve tesisler müstesna olmak üzere; otlatma planı yapılan alanlarda yıllık otlatma süresi dâhilinde hayvanların planlı otlatılmasını sağlayan, gecelemesini emniyet altına alan ve dağılmalarını engelleyen geçici çevirmeler şeklinde düzenlemeler dışında, her çeşit bina, ağıl ve hayvanların barınmasına mahsus yerler yapılması, tarla açılması, işlenmesi, ekilmesi ve orman içinde yerleşilmesi yasaktır.\n\nAncak, Devlet ormanlarında 31/12/2011 tarihinden önce toplu yerleşimin bulunduğu; yaylak ve otlak olarak kullanılan alanlar içindeki yerler ile yılın belirli dönemlerinde geleneksel yaylacılık maksadıyla yerleşim yeri olarak kullanılan alanlar kullanım bütünlüğü de dikkate alınarak Orman Genel Müdürlüğünce tespit edilir. Tespit edilen bu alanlardan uygun görülenler Cumhurbaşkanı kararı ile yayla alanı olarak ilan edilir. (...) Kullanıcısı tespit edilen bina ve tesisler vaziyet planına göre kullanıcısına, tespit tarihinden itibaren bir yıl içinde talebi hâlinde rayiç bedel üzerinden 8/9/1983 tarihli ve 2886 sayılı Devlet İhale Kanunu hükümlerine göre kiraya verilebilir. Kullanıcıları tarafından kiralanmayan bina ve tesisler ise yıkılır. (...)\n\nSavunma, ulaşım, enerji, haberleşme, su, atık su, petrol, doğalgaz, (…) altyapı, katı atık bertaraf ve düzenli depolama tesislerinin; baraj, gölet, sokak hayvanları bakımevi ve mezarlıkların; Devlete ait sağlık, eğitim, ve spor tesisleri ve bunlarla ilgili her türlü yer ve binanın Devlet ormanları üzerinde bulunması veya yapılmasında kamu yararı ve zaruret olması halinde, gerçek ve tüzel kişilere bedeli mukabilinde Çevre ve Orman Bakanlığınca izin verilebilir. Devletçe yapılan ve/veya işletilenlerden bedel alınmaz. Bu izin süresi kırkdokuz yılı geçemez. (...) İzin amaç ve şartlarına uygun olarak faaliyet gösteren hak sahiplerinin izin süreleri; yer, bina ve tesislerin rayiç değeri üzerinden belirlenecek yıllık bedelle doksandokuz yıla kadar uzatılabilir. Bu durumda devir işlemleri uzatma süresi sonunda yapılır. (Ek fıkra) Yukarıdaki fıkrada belirtilen bina ve tesislerin hükmi şahsiyeti haiz amme müesseselerine ait ormanlarda veya hususi ormanlarda yapılmak istenmesi halinde de Çevre ve Orman Bakanlığınca izin verilebilir.",
  "Orman m.18": "(Değişik : 19/4/2018-7139/11 md.) Devlet ormanlarında; arkeolojik kazı ve restorasyon yapılmasına ve bu alanların kullanımına, tarihi eserlerin restorasyonu ve korunması için gerekli tesislere, odun kömürü, terebentin, katran, sakız gibi işletilmesinde ağaç kullanılan ocakların açılmasına, orman içi su kaynakları kullanılarak balık üretim yerleri kurulmasına (...) ve göl, baraj ve deniz yüzeyinde yapılan balık, midye ve istiridye üretimi için karada yapılması mecburi tesislere ve yeraltında depolama alanı kurulmasına; (...) Orman Genel Müdürlüğünce bedeli alınarak yirmidokuz yıla kadar izin verilebilir. Bu süre sonunda her türlü bina ve tesis eksiksiz ve bedelsiz olarak Orman Genel Müdürlüğü tasarrufuna geçer (...). (Ek cümle:28/10/2020-7255/4 md.) Ancak saha tesliminden itibaren iki yıl içinde tesislerin işletmeye alınmaması hâlinde izin iptal edilir.",
  "Orman m.19": "(Değişik : 23/9/1983 - 2896/12 md.) Ormanlara hertürlü hayvan sokulması yasaktır. Ancak, kamu yararı gereklerine uygun olarak, orman idaresince belirlenen orman alanlarında; orman idaresince tespit edilen usul ve esaslar çerçevesinde hayvan otlatılmasına izin verilebilir. (...) Yangın görmüş ormanlarla, gençleştirmeye ayrılmış veya ağaçlandırılmış sahalarda hiç bir surette hayvan otlatılamaz.",
  "Orman m.41": "(Değişik:23/3/2023-7442/16 md.) Herhangi bir suretle satışı yapılmış orman emvali, bedeli ödenmeden veya karşılığı banka teminat mektubu veya Devlet tahvili temin edilmeden, damgaya tabi olanlar damgalanmadan veya işaretlemeye tabi iken işaretsiz olanlar taşıma belgesi olmaksızın nakledilemez. (...) Orman emvali; adedi, cinsi, nevi, vasfı, ebadı, bedeli, hareket tarihi ve saati ile geçerlilik süresi itibarıyla ibraz olunan taşıma belgesine uyduğu ve damgaya veya damga yerine geçecek işaretlemeye tabi olanlar damgalı veya işaretli bulunduğu takdirde, hepsi üzerinden hacmen yüzde on ve ağırlığının yüzde onbeşine kadar çıkacak fazlalık için taşıma belgesinde yazılı satış bedeli üzerinden tutarı ve bu tutarın yüzde on fazlası alınarak serbest bırakılır. Yukarıdaki hadleri aşan miktar, bütün fazlalığa şamil olmak üzere kaçak sayılarak idarece müsadere olunur.",
  "Orman m.42": "(Değişik birinci fıkra:23/3/2023-7442/17 md.) Orman içinde yapılacak nakliyat, orman idaresinin göstereceği yollardan yapılır. Taşıma belgesi emval taşıyanların daima üzerinde bulunur ve ilgili memurlar tarafından istenildiğinde gösterilmesi zorunludur. (Değişik ikinci fıkra: 5/11/2003-4999/10 md.) Şehir ve kasabalardaki ticarethane ve fabrikalardan alınan orman emvali şehir içinde fatura veya sevk irsaliyesi ile taşınabilir. Bu belgelerin taşıma araçlarında bulundurulması zorunludur.",
  "Orman m.68": "Ormanların içinde veya yakınında ateş ve yangın belirtisi görenler bunu derhal orman idaresine veya en yakın muhtarlığa, jandarma dairelerine veya mülkiye amirlerine haber vermeye mecburdurlar. Yangın ihbarında Devlete ait her türlü askeri ve mülki haberleşme vasıtalarından derhal ve parasız olarak faydalanılır. (...) Telefon devreleri PTT İdaresi santrallerine ve PTT İdaresinin santrali olmıyan yerlerde jandarma santrallerine bağlanabilir.",
  "Orman m.76": "(Değişik : 4/7/1995 - 4114/1 md.) a) Devlet ormanlarında; Orman İdaresince belirlenen konak yerlerinden başka yerlerde gecelemek, b) Ormanlarda izin verilen ve ocak yeri olarak belirlenen yerler dışında ateş yakmak veya izin verilen yerlerde yakılan ateşi söndürmeden mahalli terketmek, c) Ormanlara sönmemiş sigara veya yangına dolaylı olarak yol açabilecek madde atmak, d) Ormanlara dört kilometre mesafede veya bu Kanunun 31 inci ve 32 nci maddeleri kapsamına giren köyler hudutları içinde anız veya benzeri bitki örtüsü yakmak, Yasaktır.",
  "Orman m.77": "(Değişik: 23/1/2008-5728/191 md.) Orman memurları, bu Kanunda tanımlanan suçların işlenmesinin önlenmesi veya işlenen suçlarla ilgili olarak başlatılan soruşturmadaki görevleri kapsamında kolluk görevlisi sıfatını taşırlar. Orman teşkilatında her sınıf, derece ve vazifede çalışan memurlardan, Çevre ve Orman Bakanlığınca ve Orman Genel Müdürlüğünce lüzum görülecek olanlar, Cumhurbaşkanınca seçilecek silahla teçhiz olunurlar. Bu silahlar memurlara orman idaresince demirbaş olarak verilir. Ayrıca, kolluk görevi yapan orman memurları idarece verilecek özel kıyafetle donatılır. Devlet ormanlarından gayrı ormanlarda çalışan orman bekçilerine de umumi hükümler dairesinde silah taşıma izni verilebilir.",
  "Orman m.78": "77 nci madde mucibince silah taşımaya salahiyetli olanlar vaziflerini ifa sırasında aşağıda yazılı hallerde silahlarını kullanabilirler: A) (Değişik: 23/1/2008-5728/192 md.) Türk Ceza Kanununda düzenlenen hakkın kullanılması, meşru savunma veya zorunluluk hallerinde; B) Tecavüz veya taarruza yarıyan alet ve silahları taşıyanlala alet veya silahların derhal teslimi emredildiği halde bu emre riayet edilmiyerek fiilen tecavüz ve taarruzda bulunulması ve bu tecavüz ve taarruzun da başka şekilde def'ine imkan olmaması; C) (B) bendi gereğince teslim edilen alet ve silahları veya elkonan müsadereye tabi nakil vasıtaları ile orman emvalini veya memurun silahını almak veya orman bölge ve muhafaza binalarına zorla girmek maksadiyle vakı tecavüz ve taarruzun başka şekilde def'ine imkan bulunamaması.",
  "Orman m.79": "(Değişik: 23/1/2008-5728/193 md.) Orman memurları, bu Kanuna aykırılık oluşturan fiillere ilişkin delilleri bir tutanakla tespit eder. Bu Kanuna aykırılık oluşturan fiillerin işlenmesi suretiyle elde edilen orman malları ile bu Kanunda yer alan suçların işlenmesinde kullanılan nakil vasıtası ve sair eşyaya Ceza Muhakemesi Kanunu hükümlerine göre elkonulur. Ancak, Cumhuriyet savcısına ulaşılamadığı hallerde elkoyma, orman işletme şefinin yazılı emri ile yapılır. Ayrıca, orman muhafaza memurları Ceza Muhakemesi Kanunu hükümlerine göre şüphelileri yakalama yetkisine sahiptir. (...) Talep vukuunda polis, jandarma, köy muhtar ve bekçileri orman memurlarına yardıma mecburdurlar.",
  "Orman m.83": "(Değişik birinci fıkra : 23/1/2008-5728/194 md.) Bu Kanunda yazılı orman suçlarına ilişkin davalardan; 110 uncu maddenin üçüncü fıkrasında gösterilen suçlara ilişkin davalar asliye ceza mahkemesinde; dördüncü fıkrasında gösterilen suçlara ilişkin davalar ağır ceza mahkemesinde; beşinci fıkrasında gösterilen suçlara ilişkin davalar Ceza Muhakemesi Kanununun 250 nci maddesi uyarınca görevlendirilen ağır ceza mahkemesinde; bu suçlar dışında kalan davalar sulh ceza mahkemesinde görülür. Orman suçlarına ait davalar mahkemelerce acele mevaddan sayılır.",
  "Orman m.84": "(Değişik: 23/1/2008-5728/195 md.) Orman Kanununa aykırılık oluşturan fiillerden dolayı elkonulan ağaç, tomruk, kereste, yakacak ve sair mahsuller, vazifeli orman memurları tarafından muhafaza edilmek üzere orman depolarına, orman deposu yoksa ve fiilin işlendiği yer belediye hudutlarında ise o yer belediyesine, köy hudutları içinde ise o köy muhtarına, yokluğunda vekiline, onun da yokluğunda ihtiyar heyeti üyelerinden birine yediemin senedi mukabilinde teslim olunur. Belediye veya köy yetkililerine teslim edilen bu mallar en kısa zamanda orman depolarına idarece nakledilir. Bunlardan çürüyecek veya bozulacak olanlarla muhafazası zor ve masraflı bulunanlar, Ceza Muhakemesi Kanununun 132 nci maddesinin birinci ve ikinci fıkraları hükümlerine uygun olarak orman işletme müdürlüklerinin müsadereli mallar satış komisyonlarınca, mahallinde veya pazar yerlerinde ilan edilmek suretiyle derhal satılır.",
  "Orman m.88": "(Değişik : 23/1/2008-5728/197 md.) Bu Kanunda tanımlanan suçlardan dolayı arama, Ceza Muhakemesi Kanunu hükümlerine göre yapılır. Ancak, Ceza Muhakemesi Kanununun 119 uncu maddesinin birinci fıkrasına göre, Cumhuriyet savcısına ulaşılamadığı hâllerde arama, orman şefinin yazılı emri ile yapılır.",
  "Özel Güvenlik m.10": "Özel güvenlik görevlilerinde aşağıdaki şartlar aranır: a) Türkiye Cumhuriyeti vatandaşı olmak. b) Silahsız olarak görev yapacaklar için en az sekiz yıllık ilköğretim veya ortaokul; silahlı olarak görev yapacaklar için en az lise veya dengi okul mezunu olmak. c) 18 yaşını doldurmuş olmak. (...) f) Görevin yapılmasına engel olabilecek vücut ve akıl hastalığı ile engelli bulunmamak. g) 14 üncü maddede belirtilen özel güvenlik temel eğitimini başarıyla tamamlamış olmak. h) Güvenlik soruşturması olumlu olmak.",
  "Özel Güvenlik m.14": "Özel güvenlik temel eğitimi teorik ve pratik eğitim ile silah eğitiminden oluşmak üzere yüz yirmi ders saatinden; yenileme eğitimi altmış ders saatinden az olmamak üzere düzenlenir. Yükseköğretim kurumlarının güvenlikle ilgili fakülte ve meslek yüksek okullarından mezun olanlar ile fakülte veya meslek yüksek okullarının güvenlikle ilgili bölümlerinden mezun olanlarda silah eğitimi dışında özel güvenlik temel eğitimi şartı aranmaz. Genel kolluk kuvvetlerinden ve Milli İstihbarat Teşkilatından emekli olanlar ile en az beş yıl bu görevlerde çalıştıktan sonra kendi istekleriyle görevlerinden ayrılmış olanlarda, özel güvenlik temel eğitimi şartı ve Kanunun 10 uncu maddesinin birinci fıkrasının (b) bendinde belirtilen eğitim şartı aranmaz.",
  "Özel Güvenlik m.17": "Özel güvenlik personeli greve katılamaz.",
  "Özel Güvenlik m.19": "Bu Kanunda öngörülen adlî suçlar ve cezalar şunlardır: a) Bu Kanunun 3 üncü maddesinde belirtilen özel güvenlik iznini almadan özel güvenlik görevlisi istihdam eden kişiler veya kuruluşların yöneticileri üç aydan bir yıla kadar hapis veya adlî para cezası ile cezalandırılır. (...) c) Bu Kanunun 11 inci maddesine göre çalışma izni verilmeyen kişileri özel güvenlik görevlisi olarak istihdam eden kişi, kurum, kuruluş veya şirketlerin yetkilileri, üç aydan bir yıla kadar hapis cezası ile cezalandırılır. Bu kişilerin silâhlı olarak çalıştırılmış olması hâlinde, verilecek ceza bir kat artırılır. Bu suçun bir tüzel kişinin faaliyeti çerçevesinde işlenmesi hâlinde ayrıca bunlara özgü güvenlik tedbirlerine hükmolunur.",
  "Özel Güvenlik m.20": "Bu Kanunda öngörülen idari para cezasını veya yaptırımı gerektiren fiiller şunlardır: a) Özel güvenlik kimlik kartını başkasına kullandıran özel güvenlik yöneticisi ve görevlisine üçbin Türk Lirası idari para cezası verilir ve bu kişilerin özel güvenlik kimlik kartı valilikçe iptal edilir. Bu kişiler bir daha özel güvenlik alanında çalışamazlar. (...) c) 6 ncı madde uyarınca mülki idare amirlerince istenen ilave tedbirleri almayan kişi, kurum, kuruluş veya şirketlerin yöneticilerine altıbin Türk Lirası idari para cezası verilir. (...) e) Geçerli mazereti olmadan denetim esnasında güvenlik sorumlusunu veya yöneticiyi bulundurmayan, denetim kapsamındaki bilgi, belge ve kayıtları vermeyen kişi, kurum, kuruluş ve şirketlere beşbin Türk lirası, denetimlerde tespit edilip giderilmesi istenen eksiklikleri gidermeyen kişi, kurum, kuruluş veya şirketlerin yöneticilerine altıbin Türk Lirası idari para cezası verilir. (...) ı) Grev yasağına uymayan özel güvenlik görevlileri altı ay süreyle özel güvenlik alanında görev alamazlar. Bu maddede öngörülen cezalar mahalli mülki amir tarafından verilir.",
  "Özel Güvenlik m.4": "Özel güvenlik komisyonu, bu Kanunda belirtilen özel güvenlikle ilgili kararları almak üzere valinin görevlendireceği bir vali yardımcısının başkanlığında, il emniyet müdürlüğü, il jandarma komutanlığı, ticaret odası başkanlığı, sanayi odası başkanlığı temsilcisinden oluşur. Sanayi odasının bulunmadığı illerde komisyona ticaret ve sanayi odası başkanlığının temsilcisi katılır. Özel güvenlik izni verilmesi ya da bu uygulamanın kaldırılması için başvuran kişi ya da kuruluşun temsilcisi ilgili komisyon toplantısına üye olarak katılır. Komisyon, kararlarını oy çokluğu ile alır; oyların eşitliği halinde başkanın bulunduğu taraf çoğunluk sayılır; çekimser oy kullanılamaz.",
  "Özel Güvenlik m.5": "Şirketlerin özel güvenlik alanında faaliyette bulunması İçişleri Bakanlığının iznine tâbidir. Faaliyet izni verilebilmesi için şirket hisselerinin nama yazılı olması ve faaliyet alanının münhasıran koruma ve güvenlik hizmeti olması zorunludur. Özel güvenlik şirketleri, şubelerini bir ay içinde Bakanlığa ve ilgili valiliğe yazılı olarak; hisse devirlerini bir ay içinde Bakanlığa bildirirler. (...) Kurucu, temsilci ve yöneticilerde aranan şartların kaybedilmesi halinde iki ay içinde eksiklik giderilmediği veya bu kurucu, temsilci ve yöneticiler değiştirilmediği takdirde faaliyet izni iptal edilir.",
  "Özel Güvenlik m.7": "Özel güvenlik görevlilerinin yetkileri şunlardır: a) Koruma ve güvenliğini sağladıkları alanlara girmek isteyenleri duyarlı kapıdan geçirme, bu kişilerin üstlerini dedektörle arama, eşyaları X-ray cihazından veya benzeri güvenlik sistemlerinden geçirme. (...) d) Görev alanında, haklarında yakalama emri veya mahkûmiyet kararı bulunan kişileri yakalama ve arama. (...) g) Genel kolluk kuvvetlerine derhal bildirmek şartıyla, aramalar sırasında suç teşkil eden veya delil olabilecek ya da suç teşkil etmemekle birlikte tehlike doğurabilecek eşyayı emanete alma. h) Terk edilmiş ve bulunmuş eşyayı emanete alma. (...) k) Türk Medeni Kanununun 981 inci maddesine, Borçlar Kanununun 52 nci maddesine, Türk Ceza Kanununun 24 ve 25 inci maddelerine göre zor kullanma.",
  "Özel Güvenlik Yön m.12": "Özel güvenlik birimleri ve özel güvenlik şirketleri, bu Yönetmelik kapsamında güvenlik hizmeti verecekleri tesis ve alanlara ilişkin koruma ve güvenlik planlarını hizmetin başladığı tarihten itibaren en geç otuz gün içinde hazırlayarak, güncel bir örneğini valiliğin talep etmesi veya Bakanlık/valilik denetimlerinde ibraz edilmek üzere hazır halde bulundurur.",
  "Özel Güvenlik Yön m.17": "Genel kolluk kuvvetlerinden ve Milli İstihbarat Teşkilatından emekli olanlar ile en az beş yıl fiilen bu görevlerde çalıştıktan sonra kendi istekleri ile görevlerinden ayrılmış olanlarda, özel güvenlik temel eğitim şartı ve Kanunun 10 uncu maddesinin birinci fıkrasının (b) bendinde belirtilen eğitim şartı aranmaz. (...) Yükseköğretim kurumlarının güvenlikle ilgili fakülte ve meslek yüksekokullarından mezun olanlar ile fakülte veya meslek yüksek okullarının güvenlikle ilgili bölümlerinden mezun olanlarda silah eğitimi dışında özel güvenlik temel eğitimi şartı aranmaz.",
  "Özel Güvenlik Yön m.21": "Özel güvenlik görevlileri kimlik kartını görev alanı ve süresi içerisinde herkes tarafından görülebilecek şekilde yakasında taşır. Kimliğin kaybedilmesi halinde işveren durumu derhal Bakanlığa/valiliklere bildirir. Kimlik kartları, Kanunun 11 inci maddesi gereğince her beş yılda bir yenilenecek güvenlik soruşturması ve arşiv araştırması sonucunun olumlu olması ve özel güvenlik yenileme eğitim sertifikasının ibrazı halinde ruhsat harcı alınmaksızın (...) her beş yılda bir yeniden düzenlenir.",
  "Özel Güvenlik Yön m.22": "Özel güvenlik görevlilerinin giyeceği üniforma ve üniformayı tamamlayan diğer unsurlar, Türk Silahlı Kuvvetleri ve genel kolluk kuvvetleri ile kanunlarla kurulan özel kolluk kuvvetlerinde kullanılan renkte, biçim ve motifte olamaz. Üniforma ve üniformayı tamamlayan unsurlar ve teçhizat özel güvenlik birimlerince belirlendikten sonra, Komisyonun onayına sunulur. Üniformada şirketi tanıtıcı isim, işaret veya logo bulunur. (...) Özel güvenlik görevlileri gece görevinde, spor müsabakalarında, konser ve sahne gösterilerinde üniformanın üzerine, arkasında ışığı yansıtan (...) \"ÖZEL GÜVENLİK\" ibaresi yazılı yeleği giyerler.",
  "Özel Güvenlik Yön m.24": "Koruma ve güvenliğin sağlanabilmesi için fiziki önlemlere ve güvenlik cihazlarına öncelik verilir. Komisyon, orantılılık ilkesine uygun olarak canlılar üzerinde kalıcı etkisi olmayan kimyasalların kullanılmasına izin verebilir. Görevin niteliği gereği bu tedbirlerin yeterli olmayacağının anlaşılması halinde, (...) 6136 sayılı (...) Kanuna göre ruhsatlandırılması mümkün olan yarı otomatik tabancaların ve (...) 2521 sayılı Kanun kapsamına giren av silahlarının bulundurulmasına ve taşınmasına Komisyonca karar verilir. Bu silahların sayısı ve niteliği Komisyon kararında belirtilir.",
  "Özel Güvenlik Yön m.29": "Bulundurulmasına ve taşınmasına izin verilen her silah için yirmi beş adet fişek alınmasına izin verilir. Fişek miktarı Komisyonun kararı ve valinin onayı ile görev yeri ve niteliğine göre arttırılabilir. Görev nedeniyle sarf edilen ve miktarı bir tutanakla tespit edilen eksik fişeklerin tamamlanmasına izin verilir. Ateşli silah eğitiminde kullanılacak fişekler bu sınırlamaya tabi değildir. Programlı eğitimleri dışında personeline atış eğitimi yaptıracak kişi ve kuruluşlara talepte bulunmaları halinde fişek almalarına genel kollukça izin verilir.",
  "Özel Güvenlik Yön m.30": "Özel güvenlik izni veya silah bulundurma ve taşıma izni iptal edilen veya ihtiyaç fazlası bildiriminde bulunan kişi ve kuruluşlara ait silah ve fişekler genel hükümlere göre devredilir. Altı ay içinde devir gerçekleştirilmez ise, takip eden iki ay içerisinde silahın ait olduğu kişi veya kurum 6136 sayılı Kanuna göre ruhsat başvurusunda bulunmak zorundadır. Süresi içerisinde ruhsatlandırılmayan silahlar müsadere edilmek üzere adli makamlara intikal ettirilir.",
  "Özel Güvenlik Yön m.33": "Özel güvenlik eğitimine alınan adaylar asgari yüz yirmi saatlik eğitime tabi tutulur. Programın yirmi saati silah ve atış eğitimine ayrılır. Ateşli silah taşımayacak özel güvenlik görevlilerinin silah ve atış eğitimini alması zorunlu değildir. Bu görevlilerin temel eğitimi yüz saatten aşağı olmayacak şekilde düzenlenir.\n\nTemel ve yenileme eğitiminde kursiyerlere silah bilgisi ve atış dersi kapsamında (...) Bakanlıkça belirlenen mesafeden ve 25 fişek üzerinden atış yaptırılır. Kursiyerlerin atış eğitiminde başarılı kabul edilmesi için 25 adet fişeğin en az 15 adedinin hedefe isabet etmesi gerekir. Yeterli başarıyı gösteremeyen kursiyerlere ek fişek istihkakı alınmak suretiyle başarılı oluncaya kadar atış yaptırılır. (...) Silahlı görev yapan özel güvenlik görevlilerine, istihdam edildikleri kurum/kuruluş veya şirket tarafından her yıl en az 25 fişek üzerinden hizmet içi eğitim atışı yaptırılır.\n\nÖzel güvenlik temel eğitimi günlük sekiz saat ve haftada kırksekiz saatten fazla olamaz. Bir ders saati kırk dakikadır ve iki ders arası en az on dakika ara verilir. İhtiyaç halinde aynı ders konusunda ve ikişer dersten fazla olmayacak şekilde blok ders yapılabilir. Haftanın bir günü kursiyerlerin istirahatına ayrılır ve ders yapılmaz.\" *(Aynı tempo m.34 yenileme eğitiminde de geçerlidir.)*",
  "Özel Güvenlik Yön m.34": "Özel güvenlik görevlileri ile yöneticiler kimlik kartlarının yenilenebilmesi için beş yılda bir yenileme eğitimi alır. (...) Yenileme eğitimi (...) en az altmış ders saatinden oluşur. Yenileme eğitiminin (...) sekiz ders saati silah bilgisi ve atış dersine ayrılır. Yenileme eğitiminde okutulacak ders konuları ve saatleri Ek-13'de gösterilmiştir.",
  "Özel Güvenlik Yön m.36": "Özel güvenlik temel ve yenileme eğitimini tamamlayanlar yazılı ve uygulamalı sınava tabi tutulur. Yazılı sınav, merkezi sınav komisyonunca hazırlanan sorularla illerde yapılır. Bakanlıkça belirlenen sayıda yazılı sınav gözlemcisi ve illerde yapılacak uygulamalı sınav komisyonlarında görevlendirilecek personel valilik tarafından belirlenir.",
  "Özel Güvenlik Yön m.37": "Yazılı sınavın yeri, tarihi, başvuru süresi, başvuru sırasında istenecek belgeler ve diğer hususlar en az on beş gün önceden Komisyon tarafından belirlenerek ilan edilir. (...) temel eğitim yazılı sınavı, 80 sorudan oluşan birinci kısım ile adayların silah bilgisinin ölçüldüğü 20 sorudan oluşan ikinci kısımdan, yenileme eğitimi yazılı sınavı ise 40 sorudan oluşan birinci kısım ile adayların silah bilgisinin ölçüldüğü 20 sorudan oluşan ikinci kısım olmak üzere çoktan seçmeli sorulardan oluşan iki kısım halinde yapılır.",
  "Özel Güvenlik Yön m.38": "Uygulamalı sınavda, (...) Bakanlıkça belirlenen mesafeden ve 5 adet fişek üzerinden yaptırılacak atış ile adayların atış becerisi ölçülür. Adayların atış becerilerinin ölçüldüğü uygulamalı sınav, yazılı sınavdan hemen sonra yapılır. Sınava girecek aday sayısının fazla olması halinde, illerde birden fazla uygulamalı sınav komisyonu oluşturulabileceği gibi, sınav aynı gün bitirilemediği takdirde devam eden günlerde de tamamlanabilir.",
  "Özel Güvenlik Yön m.43": "Bakanlık ve valilikler, (...) özel güvenlik şirketlerini, alarm izleme merkezlerini, özel güvenlik birimlerini ve özel eğitim kurumlarını her zaman denetleyebilir. Bakanlık adına denetimler, sorumluluk bölgesi esasına göre Jandarma Genel Komutanlığı ve Emniyet Genel Müdürlüğü merkez teşkilatına bağlı ilgili birimler tarafından yerine getirilir. (...) Denetim sonucunda tespit edilen eksiklikler ilgili kişi, kurum, kuruluş, eğitim kurumu, alarm izleme merkezi ve şirkete yazılı şekilde bildirilerek bu eksiklikleri gidermesi için eksikliğin niteliğine göre asgari yedi gün süre verilir. (...) ilgili kişi ve kuruluşa en az yedi gün süre verilerek savunması istenir. Savunması yeterli görülmeyenlere ilçelerde kaymakamın, illerde valinin onayı ile idari para cezası verilir.",
  "Özel Güvenlik Yön m.44": "Denetim sırasında, faaliyet izninin ve personelin çalışma izinlerinin geçerli olup olmadığı; özel güvenlik görevlileri için mali sorumluluk sigortasının yaptırılıp yaptırılmadığı; üçüncü kişilere verilen koruma ve güvenlik hizmetlerine ilişkin sözleşmelerin usulüne uygun düzenlenip düzenlenmediği ve bu sözleşmelerin zamanında valiliğe bildirilip bildirilmediği; görev alanına uyulup uyulmadığı; silah ve teçhizatın ruhsatlı olup olmadığı ve bunların usulüne uygun korunup korunmadığı; kayıt ve defterlerin usulüne uygun tutulup tutulmadığı; eğitim hizmetlerinin bu Yönetmelik hükümlerine uygun yürütülüp yürütülmediği, (...) incelenir.",
  "Özel Güvenlik Yön m.45": "Denetim sonucu düzenlenen raporun bir sureti denetlenen birimin dosyasında muhafaza edilir, diğer sureti valiliğe, ilgisine göre bir sureti de Bakanlığa sunulur.",
  "Özel Güvenlik Yön m.5": "Özel güvenlik komisyonu, her ilde valinin görevlendireceği bir vali yardımcısının başkanlığında, il emniyet müdürlüğü, il jandarma komutanlığı, ticaret odası başkanlığı ve sanayi odası başkanlığının temsilcilerinden oluşur. Sanayi odasının bulunmadığı illerde Komisyona, ticaret ve sanayi odası başkanlığının temsilcisi katılır. Özel güvenlik izni verilmesi ya da bu uygulamanın kaldırılması için başvuran kişi yada kuruluşun temsilcisi Komisyonun ilgili toplantısına üye olarak katılır. Komisyon, gerekli hallerde başkanın çağrısı üzerine toplanır.\n\nKomisyon, üye tam sayısının yarısının bir fazlasıyla toplanır ve oy çokluğuyla karar alır. Oyların eşitliği halinde başkanın bulunduğu taraf çoğunluk sayılır ve çekimser oy kullanılamaz. Özel güvenlik izni için başvuran kişi ya da kuruluşun temsilcisi toplantıya katılır. Komisyon kararları, başkan ve üyeler tarafından imzalanır ve (...) muhafaza edilir. (...) Kanunun 3 üncü maddesinde belirtilen istisnai haller dışında, özel güvenlik hizmetlerinin yerine getirilmesi özel güvenlik komisyonunun kararı üzerine valinin iznine bağlıdır.",
  "Özel Güvenlik Yön m.6": "Özel güvenlik hizmetini yerine getirecek azami personel sayısını, bulundurulabilecek veya taşınabilecek silah ve teçhizatın miktar ve niteliğini, gerektiğinde kişiler, özel güvenlik birimleri veya özel güvenlik şirketleri tarafından alınacak fiziki ve aletli güvenlik tedbirleri belirlemek, (...) Koruma ve güvenlik hizmetinin yerine getirileceği alanı belirlemek ve zorunlu hallerde görev alanını genişletmek, (...) Özel güvenlik uygulamasının sona erdirilmesine ilişkin talepleri karara bağlamak, (...) Özel güvenlik faaliyetleriyle ilgili denetim sonucunda, valinin talebi üzerine alınacak tedbirleri kararlaştırmak.",
  "Özel Güvenlik Yön m.8": "Özel güvenlik izni için yapılan müracaatlar en geç on iş günü içinde neticelendirilir. Komisyonun özel güvenlik izni verilmesi ya da verilmemesi yönündeki kararları valinin onayına sunulur. (...) Özel güvenlik izni verilen kişilerde veya yerlerde istihdam edilen özel güvenlik personelinin listesi ve özel güvenlik mali sorumluluk sigortası poliçelerinin birer sureti, personelin göreve başladığı tarihten itibaren on beş gün içinde, geçici veya acil özel güvenlik izinlerinde ise müracaat sırasında valiliğe verilir. (...) göreve başlama ve görevden ayrılma bildirimleri onbeş gün içinde Valiliğe bildirilir.\n\nÖzel güvenlik izni verilen kurum veya kuruluşun talebi olması halinde; özel güvenlik görevlilerinin izin veya istirahat gibi durumlarda yerine geçici personel görevlendirilebilmesi, hizmette aksama veya zafiyete düşülmesinin önüne geçilebilmesini temin etmek ve geçici özel güvenlik hizmetleri de dahil olmak üzere ihtiyaç duyulan yerlerde görevlendirmek amacıyla, Komisyonca il genelinde verilen özel güvenlik görevlisi kadrosunun %10'unu aşmayacak şekilde personel istihdam etme izni verilebilir.",
  "Personel Yön m.1": "MADDE 1- (1) Bu Yönetmeliğin amacı; 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanunu, 9/7/1982 tarihli ve 2692 sayılı Sahil Güvenlik Komutanlığı Kanunu ile 14/7/1965 tarihli ve 657 sayılı Devlet Memurları Kanununun; Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeliyle ilgili hükümlerinin uygulanmasına dair usul ve esasları belirlemektir. MADDE 2- (1) Bu Yönetmelik; (...) subay, astsubay, sözleşmeli subay ve astsubay, uzman jandarma, uzman erbaş, sözleşmeli erbaş ve erlerin kaynakları, işe alınmaları, mesleki gelişimleri (...) ödev, hak, yükümlülük ile sorumlulukları ve diğer özlük işlerine ilişkin hükümleri kapsar. MADDE 3- (1) Bu Yönetmelik; 2803 sayılı Kanunun 24 üncü maddesi ve 2692 sayılı Kanunun 23 üncü maddesi hükümlerine dayanılarak hazırlanmıştır.",
  "Personel Yön m.10": "(1) Atamalarda hizmet bölgesinin özellikleri esas alınır. (2) Personel, hizmet ihtiyacı esas alınarak (...) meslek hayatları boyunca farklı hizmet bölgeleri arasında zorunlu atama işlemine tabi tutulur. (...) (6) Subay ve astsubayların atandığı hizmet bölgesinde hizmet süresini tamamlamaları esastır. (...) (7) İhtiyaç duyulması halinde subay kadrolarına, liyakat esas alınarak emsalleri arasında temayüz etmiş astsubaylar atanabilir. (...)",
  "Personel Yön m.14": "(2) Genel atamalar, her yılın Mayıs ve Ekim (dâhil) ayları arasında yapılır. Bu atamalar, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı tarafından önceden duyurulabilir. (3) Genel atamalar, hizmet gerekleri dikkate alınarak Bakanlık tarafından belirlenen diğer zamanlarda da yapılabilir.",
  "Personel Yön m.15": "(1) İlk defa veya yeniden veyahut yer değiştirme suretiyle atamalarda; a) Aynı yerdeki görevlere atananlar atama emirlerinin kendilerine tebliğ gününü, b) Başka yerdeki görevlere atananlar, atama emirlerinin kendilerine tebliğ tarihinden itibaren onbeş gün içerisinde o yere hareket ederek belli yol süresini, izleyen işgünü içinde işe başlamak zorundadırlar. Savaş ve olağanüstü hallerde bu süre Bakanlar Kurulu kararı ile kısaltılabilir. (...) (4) Atama emrinde aksi belirlenmedikçe atama emrinin amire ulaşmasından itibaren en geç on gün içerisinde ilgilisine tebliğ edilir.",
  "Personel Yön m.18": "MADDE 18- (1) Personel, Türkiye Cumhuriyeti Anayasasına ve kanunlarına sadakatle bağlı kalmak (...) zorundadır. MADDE 19- (1) Personel siyasi partiye üye olamaz, herhangi bir siyasi parti, kişi veya zümrenin yararını veya zararını hedef tutan bir davranışta bulunamaz; (...) dil, ırk, cinsiyet, siyasi düşünce, felsefi inanç, din ve mezhep gibi ayırım yapamaz; hiçbir şekilde siyasi ve ideolojik amaçlı beyanda ve eylemde bulunamaz (...). (2) Personel her durumda Devletin menfaatlerini korumak mecburiyetindedir. MADDE 20- (1) Personel, resmi sıfatının gerektirdiği itibar ve güvene layık olduğunu, hizmet içindeki ve dışındaki davranışlarıyla göstermek zorundadır.",
  "Personel Yön m.24": "MADDE 23- (1) Personel, görevlerini dikkat ve itina ile yerine getirmek ve kendilerine teslim edilen Devlet malını korumak (...) zorundadır. (2) Personelin kasıt, kusur, ihmal veya tedbirsizliği sonucu idare zarara uğratılmışsa, bu zararın ilgili personel tarafından rayiç bedeli üzerinden ödenmesi esastır. MADDE 24- (1) Kişiler kamu hukukuna tabi görevlerle ilgili olarak uğradıkları zararlardan dolayı bu görevleri yerine getiren personel aleyhine değil, ilgili kurum aleyhine dava açarlar. (...) Kurumun, genel hükümlere göre sorumlu personele rücu hakkı saklıdır.",
  "Personel Yön m.25": "MADDE 25- (1) Personel, kamu görevleri hakkında basına, haber ajanslarına veya radyo ve televizyon kurumlarına bilgi veya demeç veremez. Bu konuda gerekli bilgi ancak illerde valiler ve Bakanın yetkili kılacağı görevli tarafından verilebilir. MADDE 26- (1) Personel, görevleri ile ilgili resmi belge, araç ve gereçleri, yetki verilen mahaller dışına çıkaramaz, hususi işlerinde kullanamaz ve kullandıramaz. (...) (2) Personel görevleri icabı kendilerine teslim edilen resmi belge, araç ve gereçleri görevleri sona erdiği zaman iade etmek zorundadır. Bu zorunluluk personelin mirasçılarına da şamildir.",
  "Personel Yön m.33": "(1) Personel hakkındaki ihbar ve şikâyetler, garaz veya mücerret hakaret için, uydurma bir suç isnadı suretiyle yapıldığı ve soruşturma veya yargılamanın tabi olduğu kanuni işlem sonucunda bu isnat sabit olmadığı takdirde, merkezde bu personelin en büyük amiri, illerde valiler, isnatta bulunanlar hakkında kamu davası açılmasını Cumhuriyet savcılığından ister.",
  "Personel Yön m.35": "Madde 35- (1) Personelin kamu hizmetlerini aksatacak şekilde görevden kasıtlı olarak birlikte çekilmeleri veya görevlerine gelmemeleri (...) eylem ve hareketlerde bulunmaları yasaktır. MADDE 36- (1) Personelin greve karar vermeleri, grev tertiplemeleri, ilan etmeleri, bu yolda propaganda yapmaları yasaktır. (2) Personel, herhangi bir greve veya grev teşebbüsüne katılamaz (...). MADDE 37- (1) Personel, (...) tacir veya esnaf sayılmalarını gerektirecek bir faaliyette bulunamaz, ticaret ve sanayi müesseselerinde görev alamaz (...). (3) Eşleri, reşit olmayan veya mahcur olan çocukları, yasaklanan faaliyetlerde bulunan personel, bu durumu onbeş gün içinde bağlı oldukları kuruma bildirmekle yükümlüdürler.",
  "Personel Yön m.38": "MADDE 38- (1) Personelin doğrudan doğruya veya aracı eliyle hediye istemeleri ve görevleri sırasında olmasa dahi menfaat sağlama amacı ile hediye kabul etmeleri veya iş sahiplerinden borç para istemeleri ve almaları yasaktır. MADDE 39- (1) Personelin, denetimi altında bulunan veya kendi görevi (...) ile ilgisi olan bir teşebbüsten, (...) bir menfaat sağlaması yasaktır. MADDE 40- (1) Personele; (...) ikinci görev verilemez; bu kurumlardan her ne ad ile olursa olsun ödeme yapılamaz ve yarar sağlanamaz. MADDE 41- (1) Gizli bilgi; doğrudan kanunlarla veya kanun ve düzenleyici işlemlere dayanarak yetkili makamlar tarafından gizli olarak nitelendirilen bilgidir. (2) Personel, kamu hizmetleri ile ilgili gizli bilgileri görevinden ayrılmış olsa bile Bakanın yazılı izni olmadıkça açıklayamaz.",
  "Personel Yön m.4": "a) Amir: Kadro ve kuruluş yönünden bağlı olunan kimse ile amir olarak yetkilendirilmiş olan diğer kişileri, (...) d) Branş: Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı teşkilatlarındaki alt hizmet alanlarını, (...) i) Makam: Her amirin kuruluş ve kadrolarında temsil ettiği mevkii, (...) k) Üst: Makam, rütbe veya kıdem büyüklüğünü, ifade eder.",
  "Personel Yön m.42": "(1) Günün yirmidört saatinde devamlılık gösteren hizmetlerde çalışan personelin çalışma saat ve şekilleri ile nöbet sistemleri kurumlarınca düzenlenir. (2) Nöbet, kurumlarda amirin münasip göreceği zamanda başlar ve yirmidört saati geçemez. Ancak kadın memurlara; tabip raporlarında belirtilmesi halinde hamilelik boyunca ve doğumdan sonraki iki yıl süreyle gece nöbeti ve gece vardiyası görevi verilemez. Engelli memurlara da isteği dışında gece nöbeti ve gece vardiyası görevi verilemez. (...)",
  "Personel Yön m.45": "(1) Yürütülen hizmetlerin özelliklerini gözönünde bulundurarak personelin başarı, verimlilik ve gayretlerini ölçmek üzere değerlendirme sistemi oluşturulur. Bu sistem elektronik ortamda da düzenlenebilir. (...) (3) Değerlendirme sonuçları personelin görevlere seçiminde, atama ve yer değiştirmesinde, mesleki gelişiminde, statüler arası geçişte, terfiinde, (...) ve ödüllendirilmesinde dikkate alınır. (4) Değerlendirme yılda en az bir kez yapılır.",
  "Personel Yön m.46": "MADDE 46- (4) Bu Yönetmelik kapsamında verilen ödüller; başarı belgesi, üstün başarı belgesi, takdir belgesi, şerit rozet, bröve ve madalyadır. MADDE 47- (2) (...) somut olaylara ve verilere dayalı olarak katkı sağladıkları tespit edilen personele, merkezde Bakan, illerde valiler, ilçelerde kaymakamlar tarafından başarı belgesi verilebilir. Üç defa başarı belgesi alanlara üstün başarı belgesi verilir. MADDE 50- (1) Kendisine tevdi edilen görevleri fiilen hayatını tehlikeye atarak üstün bir cesaret ve feragatle yerine getirdiği tespit edilen personele üstün cesaret ve feragat madalyası (...) verilir.",
  "Personel Yön m.5": "(1) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığının personel ihtiyacı; a) Jandarma ve Sahil Güvenlik Akademisi tarafından, b) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı bünyesindeki eğitim komutanlıklarındaki eğitimlerini başarıyla tamamlayanlardan, karşılanır. (...) (4) Personel ihtiyacı, (...) Bakanlık tarafından onaylanan insan gücü planına göre karşılanır.",
  "Personel Yön m.51": "MADDE 51- (1) Görevden uzaklaştırma Devlet kamu hizmetlerinin gerektirdiği hallerde, görevi başında kalmasında sakınca görülecek personel hakkında alınan ihtiyati bir tedbirdir. Görevden uzaklaştırma hususunda 657 sayılı Kanunda belirtilen usul ve esaslara uyulur. MADDE 52- (1) Görevden uzaklaştırmaya yetkililer şunlardır: a) Atamaya yetkili amirler. b) Bakanlık müfettişleri. c) İllerde valiler. ç) İlçelerde kaymakamlar. (2) Valiler ve kaymakamlar tarafından alınan görevden uzaklaştırma tedbiri, personelin kurumuna derhal bildirilir.",
  "Personel Yön m.54": "MADDE 54- (1) Personelin görev sırasında, bu Yönetmelikte veya diğer mevzuatta belirtilen istisnalar saklı kalmak kaydıyla resmi üniforma giymesi zorunludur. MADDE 55- (1) (...) c) Resmi üniformalar eskimiş dahi olsa personel dışındaki kişiler tarafından giyilemez ve bu kişilere verilemez. ç) Branş ve rütbe işaretleri sökülmek suretiyle resmi üniformalar sivil kıyafete dönüştürülerek kullanılamaz (...) e) Resmi üniformalı olarak görev yapan kadın personel, hamileliğini belgelediği takdirde resmi kıyafet yerine sivil kıyafet ile görev yapabilir. (3) Personel; emeklilik, çekilme veya herhangi bir nedenle (...) ilişiği kesildiği tarihten itibaren resmi üniformasını çıkarmaya mecburdur.",
  "Personel Yön m.56": "MADDE 56- (1) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı personeline, genel ve özel düzenleme getiren kanunlarla verilen özlük hakları saklıdır. (2) Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı kadrolarına atanmış personel ayrıca Asayiş Tazminatından yararlanır.",
  "Personel Yön m.60": "(1) Selamlama, rütbe ve makam farkı olmadan her personel tarafından bütün bir ciddiyet ve hürmetle el ve baş, yalnız baş ile kılıç veya çeşitli teçhizat ve bayraklarla yapılır. (2) Selamlama her yerde ve her zaman yapılır. Astlar, üstlerden evvel selam vermeye mecburdurlar. Aynı rütbede olanlar veya birbirinin rütbesini ayırt edemeyenler birbirini beklemeden selamlarlar. Üstler aynı usul ve esaslarla astlarının selamını alırlar. (3) Personel, siviller ile selamlaşmayı mesleki kurallar, örf, adet ve nezaket kuralları çerçevesinde yapar.",
  "Personel Yön m.7": "(1) Jandarma Genel Komutanlığında bulunan branşlar şunlardır: a) Subaylar 1) Jandarma 2) İstihkâm 3) Muhabere 4) Pilot 5) İkmal 6) Bakım 7) Personel 8) Kimyager 9) Veteriner hekim 10) Mühendis 11) Maliye 12) Öğretmen 13) Bando 14) Tabip 15) Eczacı 16) Diş tabibi 17) Sağlık 18) (Ek:RG-28/5/2020) Hukuk 19) (Ek:RG-16/1/2024) İnsansız Hava Aracı b) Astsubaylar 1) Jandarma 2) İstihkâm 3) Muhabere 4) Uçak ve helikopter teknisyeni 5) İkmal 6) Bakım 7) Personel 8) Maliye 9) Bando 10) Sağlık 11) (Ek:RG-16/1/2024) İnsansız Hava Aracı (2) Sahil Güvenlik Komutanlığında bulunan branşlar şunlardır: a) Subaylar 1) Sahil güvenlik 2) İkmal 3) Mühendis 4) (Ek:RG-28/5/2020) Hukuk b) Astsubaylar 1) Güverte 2) Makine 3) İkmal 4) Uçak bakım 5) İdari 6) Bilgi teknolojileri",
  "PVSK m.13/A": "Kaybolan çocukların bulunması amacıyla, polis, sulh ceza hâkiminin veya gecikmesinde sakınca bulunan hallerde mülki idare amirinin yazılı veya sonradan yazılı hale getirilmek üzere sözlü emri ile kayıp çocuğa ait veya başkasına ait olmakla birlikte kayıp çocuk tarafından kullanılan her türlü banka hesap hareketlerini talep edebilir, telekomünikasyon yoluyla iletişimini denetleyebilir ve sinyal bilgilerini değerlendirebilir. Tedbir kararı, en çok bir ay için verilebilir; ancak bu süre, bir defaya mahsus olmak üzere bir ay daha uzatılabilir. Mülki idare amirinin kararı, derhal mahkemenin onayına sunulur. Mahkeme kararını en geç yirmidört saat içinde verir.",
  "PVSK m.16": "Zor kullanma yetkisi kapsamında, direnmenin mahiyetine ve derecesine göre ve direnenleri etkisiz hale getirecek şekilde kademeli olarak artan nispette bedenî kuvvet, maddî güç ve kanunî şartları gerçekleştiğinde silah kullanılabilir. İkinci fıkrada yer alan; a) Bedenî kuvvet; polisin direnen kişilere karşı veya eşya üzerinde doğrudan doğruya kullandığı bedenî gücü, b) Maddî güç; polisin direnen kişilere karşı veya eşya üzerinde bedenî kuvvetin dışında kullandığı kelepçe, cop, basınçlı ve/veya boyalı su, göz yaşartıcı gazlar veya tozlar, fizikî engeller, polis köpekleri ve atları ile sair hizmet araçlarını, ifade eder.\n\nPolis; a) Meşru savunma hakkının kullanılması kapsamında, b) Bedenî kuvvet ve maddî güç kullanarak etkisiz hale getiremediği direniş karşısında, bu direnişi kırmak amacıyla ve kıracak ölçüde, c) Hakkında tutuklama, gözaltına alma, zorla getirme kararı veya yakalama emri verilmiş olan kişilerin ya da suçüstü halinde şüphelinin yakalanmasını sağlamak amacıyla ve sağlayacak ölçüde, d) Kendisine veya başkalarına, işyerlerine, konutlara, kamu binalarına, okullara, yurtlara, ibadethanelere, araçlara ve kişilerin tek tek veya toplu halde bulunduğu açık veya kapalı alanlara molotof, patlayıcı, yanıcı, yakıcı, boğucu, yaralayıcı ve benzeri silahlarla saldıran veya saldırıya teşebbüs edenlere karşı, saldırıyı etkisiz kılmak amacıyla ve etkisiz kılacak ölçüde, silah kullanmaya yetkilidir.\n\nPolis, yedinci fıkranın (c) bendi kapsamında silah kullanmadan önce kişiye duyabileceği şekilde 'dur' çağrısında bulunur. Kişinin bu çağrıya uymayarak kaçmaya devam etmesi halinde, önce uyarı amacıyla silahla ateş edilebilir. Buna rağmen kaçmakta ısrar etmesi dolayısıyla ele geçirilmesinin mümkün olmaması halinde ise kişinin yakalanmasını sağlamak amacıyla ve sağlayacak ölçüde silahla ateş edilebilir.",
  "PVSK m.5": "Birinci fıkraya göre alınan parmak izi, ait olduğu kişinin kimlik bilgileri ile birlikte, ne zaman ve kim tarafından alındığı belirtilmek suretiyle, bu amaca özgü sisteme kaydedilerek saklanır. Ancak, parmak izinin hangi sebeple alındığı sisteme kaydedilmez. Olay yerinden elde edilen ve kime ait olduğu henüz tespit edilemeyen parmak izleri, kime ait olduğu tespit edilinceye kadar, ilgili soruşturma dosya numarası ile birlikte sisteme kaydedilir.\n\nPolis; a) Gönüllü, b) Her çeşit silah ruhsatı, sürücü belgesi, pasaport veya pasaport yerine geçen belge almak için başvuruda bulunan, c) Başta polis olmak üzere, genel veya özel kolluk görevlisi ya da özel güvenlik görevlisi olarak istihdam edilen, ç) Türk vatandaşlığına başvuruda bulunan, d) Sığınma talebinde bulunan veya gerekli görülmesi halinde, ülkeye giriş yapan sair yabancı, e) Gözaltına alınan, kişilerin parmak izini alır.\n\nSisteme kayıtlı olan parmak izi ve fotoğraflar, kişinin ölümünden itibaren on yıl ve her halde kayıt tarihinden itibaren seksen yıl geçtikten sonra sistemden silinir.",
  "PVSK m.Ek 7": "Polis, Devletin ülkesi ve milletiyle bölünmez bütünlüğüne, Anayasa düzenine ve genel güvenliğine dair önleyici ve koruyucu tedbirleri almak, emniyet ve asayişi sağlamak üzere, ülke seviyesinde ve sanal ortamda istihbarat faaliyetlerinde bulunur, bu amaçla bilgi toplar, değerlendirir, yetkili mercilere veya kullanma alanına ulaştırır. Devletin diğer istihbarat kuruluşlarıyla işbirliği yapar. Birinci fıkrada belirtilen görevlerin yerine getirilmesine yönelik olarak, 4.12.2004 tarihli ve 5271 sayılı Ceza Muhakemesi Kanununun, casusluk suçları hariç, 250 nci maddesinin birinci fıkrasının (a), (b) ve (c) bentlerinde yazılı suçlar ile bilişim suçlarının işlenmesinin önlenmesi amacıyla hâkim kararı veya gecikmesinde sakınca bulunan hallerde Emniyet Genel Müdürünün, Emniyet Genel Müdürlüğü İstihbarat Dairesi Başkanının veya bilişim suçlarıyla sınırlı olmak üzere bilişim suçları ile ilgili daire başkanının yazılı emriyle, telekomünikasyon yoluyla yapılan iletişim veya internet bağlantı adresleriyle internet kaynakları arasındaki veri trafiği ile iletilen veriler tespit edilebilir, dinlenebilir, sinyal bilgileri değerlendirilebilir, kayda alınabilir.\n\nGecikmesinde sakınca bulunan hallerde verilen yazılı emir, yirmidört saat içinde yetkili ve görevli hâkimin onayına sunulur. Hâkim, kararını en geç kırk sekiz saat içinde verir. Sürenin dolması veya hâkim tarafından aksine karar verilmesi halinde tedbir derhal kaldırılır. Bu halde dinlemenin içeriğine ilişkin kayıtlar en geç on gün içinde yok edilir; durum bir tutanakla tespit olunur ve bu tutanak denetimde ibraz edilmek üzere muhafaza edilir. (...) Kararlar, en fazla üç ay için verilebilir; bu süre aynı usûlle üçer ayı geçmeyecek şekilde en fazla üç defa uzatılabilir. Ancak, terör örgütünün faaliyeti çerçevesinde devam eden tehlikelere ilişkin olarak gerekli görülmesi halinde, hâkim üç aydan fazla olmamak üzere sürenin müteaddit defalar uzatılmasına karar verebilir. (...) Uygulanan tedbirin sona ermesi halinde, dinlemenin içeriğine ilişkin kayıtlar en geç on gün içinde yok edilir. Durum bir tutanakla tesbit olunur ve bu tutanak denetimde ibraz edilmek üzere muhafaza edilir.\n\nPolis, Devletin ülkesi ve milletiyle bölünmez bütünlüğüne, Anayasa düzenine ve genel güvenliğine dair önleyici ve koruyucu tedbirleri almak, emniyet ve asayişi sağlamak üzere, ülke seviyesinde istihbarat faaliyetlerinde bulunur, bu amaçla bilgi toplar, değerlendirir, yetkili mercilere veya kullanma alanına ulaştırır. Devletin diğer istihbarat kuruluşlarıyla işbirliği yapar.\n\nBirinci fıkrada belirtilen görevlerin yerine getirilmesine yönelik olarak, 4/12/2004 tarihli ve 5271 sayılı Ceza Muhakemesi Kanununun, casusluk suçları hariç, 250 nci maddesinin birinci fıkrasının (a), (b) ve (c) bentlerinde yazılı suçlar ile bilişim suçlarının işlenmesinin önlenmesi amacıyla, hâkim kararı veya gecikmesinde sakınca bulunan hallerde Emniyet Genel Müdürünün, Emniyet Genel Müdürlüğü İstihbarat Dairesi Başkanının veya bilişim suçlarıyla sınırlı olmak üzere bilişim suçları ile ilgili daire başkanının yazılı emriyle, telekomünikasyon yoluyla yapılan iletişim veya internet bağlantı adresleriyle internet kaynakları arasındaki veri trafiği ile iletilen veriler tespit edilebilir, dinlenebilir, sinyal bilgileri değerlendirilebilir, kayda alınabilir.\n\nYetkili ve görevli hâkim, Ankara ağır ceza mahkemesi üyesidir. Gecikmesinde sakınca bulunan hallerde verilen yazılı emir, yirmidört saat içinde yetkili ve görevli hâkimin onayına sunulur. Hâkim, kararını en geç kırk sekiz saat içinde verir. Sürenin dolması veya hâkim tarafından aksine karar verilmesi halinde tedbir derhal kaldırılır. Bu halde dinlemenin içeriğine ilişkin kayıtlar en geç on gün içinde yok edilir; durum bir tutanakla tespit olunur ve bu tutanak denetimde ibraz edilmek üzere muhafaza edilir.\n\nKararlar, en fazla üç ay için verilebilir; bu süre aynı usûlle üçer ayı geçmeyecek şekilde en fazla üç defa uzatılabilir. Ancak, terör örgütünün faaliyeti çerçevesinde devam eden tehlikelere ilişkin olarak gerekli görülmesi halinde, hâkim üç aydan fazla olmamak üzere sürenin müteaddit defalar uzatılmasına karar verebilir. Uygulanan tedbirin sona ermesi halinde, dinlemenin içeriğine ilişkin kayıtlar en geç on gün içinde yok edilir. Durum bir tutanakla tespit olunur ve bu tutanak denetimde ibraz edilmek üzere muhafaza edilir.",
  "Resmî Yazışma m.1": "Bu Yönetmeliğin amacı; güvenli elektronik imza kullanılarak elektronik ortamda veya el yazısıyla atılan imza ile fiziksel ortamda yapılan resmî yazışmalara ilişkin kuralları belirlemek, bilgi veya belge alışverişini, hızlı ve güvenli bir biçimde yürütmek ve uygulama birliğini sağlamaktır. (2) Bu Yönetmelik, bütün kamu kurum ve kuruluşlarını kapsar.",
  "Resmî Yazışma m.10": "Başlık (antet), belgeyi gönderen idarenin adının belirtildiği bölümdür. (2) Başlık, belgenin yazı alanının üst kısmına ortalanarak yazılır. İlk satıra \"T.C.\" kısaltması, ikinci satıra idarenin adı büyük harflerle, üçüncü satıra birimin adı ilk harfleri büyük diğerleri küçük harflerle ortalanarak yazılır. (...) (3) İdarelerin il ve ilçe teşkilatlarında kullanılan başlıklar, (...) 5442 sayılı İl İdaresi Kanunu hükümlerine uygun olarak (...) yazılır. (...) (6) Başlığın yazımında DETSİS'te yer alan başlık kayıtları esas alınır.",
  "Resmî Yazışma m.11": "Belgelerde sayı bulunması zorunludur. \"Sayı:\" sırasıyla; belgenin hazırlanma süreçlerini ifade eden elektronik ortam için \"E\", zorunlu hâller için \"Z\" veya olağanüstü durumlar için \"O\" ibarelerinden uygun olanı, DETSİS'te belirtilen Türkiye Cumhuriyeti Devlet Teşkilatı Numarası, standart dosya planı kodu ile kayıt numarasından oluşur ve bunların arasına kısa çizgi işareti (-) konulur (...). (Örnek: E-67915368-903.07.02-4752) (...) Zorunlu hâllerde (...) (Örnek: Z-67915368-804.02-4757) (...) Olağanüstü durumlarda (...) (Örnek: O-67915368-952.02.05-10).",
  "Resmî Yazışma m.12": "Tarih; sayı ile aynı satırda olmak üzere yazı alanının en sağında gün, ay, yıl olarak rakamla ve aralarına nokta işareti \".\" konularak yazılır (...). Gün ve ay iki haneli, yıl ise dört haneli olarak düzenlenir (Örnek: 01.09.2019). Ay adları, harfle de yazılabilir. Bu durumda gün, ay ve yıl arasına herhangi bir işaret konulmaz (Örnek: 10 Ekim 2019). (2) Belgenin en son yetkili tarafından güvenli elektronik imza ile imzalandığı zamanı gösteren zaman damgasındaki tarih bilgisi, belge tarihi olarak esas alınır (...).",
  "Resmî Yazışma m.13": "\"Konu:\" yan başlığı, \"Sayı:\" yan başlığının bir alt satırına yazılır. Belgenin konusu, yazı alanının dikey orta hizasını geçmeyecek biçimde kelimelerin baş harfleri büyük olarak ve sonuna herhangi bir noktalama işareti konulmaksızın yazılır (...). (2) Konu, belgenin içeriği hakkında kısa ve öz bilgi barındırır (...).",
  "Resmî Yazışma m.14": "Muhatap, belgenin gönderildiği idareyi veya kişiyi belirtir. (...) (2) Muhatabın idare veya özel hukuk tüzel kişisi olması durumunda, adı büyük harflerle ve sonuna yönelme hâl eklerinden uygun olanı getirilerek yazılır. Muhatap idarenin adının yazımında DETSİS'te yer alan kayıtlar esas alınır. (...) (3) (...) Muhatap gerçek kişi ise muhatap bölümüne \"Sayın\" ibaresinden sonra muhatabın adı ilk harfi büyük diğerleri küçük harflerle, soyadı ise büyük harflerle yazılır (...). (6) Birden fazla muhataba iletilecek dağıtımlı belgelerin muhatap bölümüne \"DAĞITIM YERLERİNE\" ibaresi yazılır (...).",
  "Resmî Yazışma m.15": "İlgi, belgenin bağlantılı olduğu diğer belge veya belgelerin belirtildiği bölümdür. (...) (5) İlginin birden fazla olması durumunda, belgeler önceki tarihli olandan başlanarak tarih sırasına göre sıralanır. (...) (7) İlgide, \"… tarihli ve … sayılı …\" ibaresi kullanılır ve ilginin sonuna nokta (.) işareti konulur (...). (9) İlgide belirtilen belge, gerçek kişiden geliyorsa ilgi bölümü \"…'ın … tarihli başvurusu/dilekçesi.\" biçiminde yazılır (...).",
  "Resmî Yazışma m.16": "(4) Paragrafa 1,25 cm içeriden başlanır ve metin iki yana hizalanır. (...) (12) Metnin son bölümü: a) Yazışma yapan makamlar arasındaki hiyerarşi yönünden alt makamlara \"… rica ederim.\", üst ve aynı düzeydeki makamlara \"… arz ederim.\" ibaresiyle bitirilir. b) Üst, aynı düzey ve alt makamlara birlikte dağıtımlı olarak yapılan yazışmalar \"… arz ve rica ederim.\" veya \"… arz/rica ederim.\" ibaresiyle bitirilir. c) Muhatap kısmında ikinci satırda parantez içerisinde birim veya idare ismi belirtilen yazışmalar, birinci satırda yer alan muhatap idare dikkate alınarak arz veya rica ibarelerinden uygun olanı ile bitirilir. ç) 1 sayılı Cumhurbaşkanlığı Kararnamesinin 6 ncı maddesi gereğince bakanlıklarla yapılan yazışmalar, Cumhurbaşkanlığı İdari İşler Başkanı tarafından veya adına imzalandığında \"Rica ederim.\" ibaresiyle bitirilir. d) Belge, imza yetkisini devreden makam adına imzalandığında, yetkiyi devreden makamın hiyerarşik durumu dikkate alınarak arz veya rica ibarelerinden uygun olanı ile bitirilir. e) Muhatabı gerçek kişi olan yazışmalar \"Saygılarımla.\", \"İyi dileklerimle.\" veya \"Bilgilerinize sunulur.\" ibareleriyle bitirilebilir.\n\n(1) Metin alanı, \"Muhatap\" veya varsa \"İlgi\" ile \"İmza\" arasındaki kısımdır. (2) \"İlgi\" ile metin başlangıcı arasında bir satır, \"İlgi\" yoksa belgenin muhatabı ile metin başlangıcı arasında iki satır boşluk bulunur. (3) Metindeki kelime aralarında ve noktalama işaretlerinden sonra bir karakter boşluk bırakılır. Noktalama işaretleri kendinden önce gelen harfe bitişik yazılır. (4) Paragrafa 1,25 cm içeriden başlanır ve metin iki yana hizalanır. Paragraflar arasında satır boşluğu bırakılmaz. İhtiyaç duyulması hâlinde paragraflar harf veya rakam ile sıralanabilir. (5) Birden fazla sayfa tutan üst yazılarda sayı, tarih, konu, muhatap ve ilgi bilgilerine sadece ilk sayfada; imza, ek ve dağıtım bilgilerine ise sadece son sayfada yer verilir. İletişim bilgisine ve belge doğrulama bilgilerine her sayfanın en alt kısmında yer verilir. (6) Metin içinde geçen sayılar, rakamla veya harfle yazılabilir. (7) Dört ve dörtten çok haneli sayılar sondan sayılmak üzere üçlü gruplara ayrılarak yazılır ve araya nokta (.) işareti konulur (Örnek: 1.452; 25.126; 326.197). Sayılarda kesirler virgül (,) ile ayrılır (Örnek: 10.545,72). (8) Belge, Türk Dil Kurumu tarafından hazırlanan Yazım Kılavuzu ve Türkçe Sözlük'ün güncel yayımı esas alınarak dil bilgisi kurallarına göre anlamlı ve özlü olarak yazılır. (...) Ancak muhatabı yabancı ülke veya uluslararası kuruluş olan resmî yazışmalarda yabancı dil kullanılabilir. (...) yabancı dille yazılan belgenin Türkçe tercümesi oluşturulur (...). (9) Metin içinde yer alan alıntılar tırnak içinde ve/veya eğik (italik) olarak yazılabilir. (10) Metin içinde harfler kullanılarak maddelendirmeye/numaralandırmaya ihtiyaç duyulduğunda, Türk alfabesinde yer alan bütün küçük harfler kendilerinden sonra kapama parantez işareti \")\" konularak kullanılır. (11) Metin içinde kısaltma kullanılacak ise ifadenin ilk kullanıldığı yerde açık biçimi, sonra parantez içinde kısaltılmış biçimi yazılır (Örnek: Türkiye Büyük Millet Meclisi (TBMM), Kayıtlı Elektronik Posta (KEP)).",
  "Resmî Yazışma m.17": "Metnin bitiminden itibaren iki ilâ dört satır boşluk bırakılarak, belgeyi imzalayacak olan makam sahibinin adına, soyadına ve bunların altında unvanına, yazı alanının en sağında ortalanarak yer verilir (...). (3) Elektronik ortamda (...) yetkili makam belgeyi güvenli elektronik imzası ile imzalar. (...) (6) Zorunlu hâllerde veya olağanüstü durumlarda imza, ad ve soyadın üzerinde bırakılan boşluğa el yazısıyla atılır. El yazısıyla atılan imza, kaybolmayacak ve kâğıda işlemesini sağlayacak mavi renkli kalemle atılır. (...) (9) Belgeyi imza yetkisi devredilen makam imzaladığında, (...) \"Bakan a.\", \"İdari İşler Başkanı a.\", \"Vali a.\", (...) \"Genel Müdür a.\" veya \"Rektör a.\" biçimindeki ibare (...). (10) Belge vekâleten imzalandığında, (...) \"Genel Müdür V.\", \"Başkan V.\", (...) \"Rektör V.\" veya \"Dekan V.\" biçiminde (...) yazılır.",
  "Resmî Yazışma m.18": "Belgede ek olması hâlinde \"Ek:\" başlığı imza bölümünden sonra uygun satır boşluğu bırakılarak ve yazı alanının solundan başlanarak yazılır. (...) (2) (...) Eklerin sayfa, adet, kişi sayısı gibi açıklayıcı ifadeleri parantez içinde belirtilir (...). (5) Belge eklerinin muhataba gönderilmediği durumlarda \"Ek konulmadı\" veya \"Ek-... konulmadı\" ifadesi yazılır (...).",
  "Resmî Yazışma m.19": "Belgenin birden fazla muhataba gönderilmesi durumunda dağıtım bölümüne yer verilir. (...) (2) Belgenin gereğini yerine getirme durumunda olanlar \"Gereği:\" kısmına, belgenin içeriği hakkında bilgi sahibi olması istenenler ise \"Bilgi:\" kısmına yazılır. \"Gereği:\" kısmı \"Dağıtım:\" başlığının altına, \"Bilgi:\" kısmı ise \"Gereği:\" kısmı ile aynı satıra ve yazı alanının ortasına doğru yazılır (...).",
  "Resmî Yazışma m.20": "Makam oluru alınan belgeler, ilgili birimin yöneticisi tarafından güvenli elektronik imza ile teklif edilir ve oluru alınan makam tarafından güvenli elektronik imza ile imzalanır. (...) (2) Belge, olur için makama sunulurken imza bölümünden sonra uygun boş satır bırakılarak yazı alanının ortasına büyük harflerle \"OLUR\" yazılır. (...) (4) Oluru teklif eden birim ile olur alınan makam arasında başka makamlar varsa bunlar olura katılabilir. (...) \"Uygun görüşle arz ederim.\" ibaresi yazılır (...).",
  "Resmî Yazışma m.21": "Paraf bölümünde tarih, unvan, ad ve soyad bilgileri kısaltma kullanılmadan ast-üst ilişkisine uygun olarak belirtilir. Güvenli elektronik imza ile imzalanan belgeye ait paraf bilgileri, belgenin üstverisinde tutulur (...). Belge muhataba iletildiğinde, belgeye ait paraf bilgileri paylaşılmaz. (2) Elektronik ortamda hazırlanan belgelerde paraf, güvenli elektronik imza veya elektronik onay ile atılır. (...) (3) Zorunlu hâllerde veya olağanüstü durumlarda el yazısıyla atılan paraf, kaybolmayacak ve kâğıda işlemesini sağlayacak mavi kalemle atılır. Fiziksel ortamda hazırlanan belgelerde paraflar, belgenin sadece idarede kalacak nüshasında, yazı alanının sonunda ve sol kenarında yer alır (...).",
  "Resmî Yazışma m.23": "Elektronik ortamda güvenli elektronik imza ile imzalanan belgelerde, \"İletişim bilgileri\" alanının üst sınırını belirleyen çizginin üzerinde iki satırlık alanın ilk satırında \"Bu belge, güvenli elektronik imza ile imzalanmıştır.\" ibaresi bulunur. Belge doğrulama bilgilerini içeren \"belge doğrulama kodu\" ikinci satırda, \"karekod\" ise \"İletişim bilgileri\" alanının en sağ kısmında yer alır (...). (2) Belge doğrulama işlemi, doğrulama kodu ve karekod ile Dijital Türkiye (e-Devlet) üzerinden sağlanır.",
  "Resmî Yazışma m.25": "\"Hizmete Özel\" gizlilik derecesi bulunan belgelerin hazırlanması, kaydedilmesi, saklanması, gönderilmesi, alınması ve diğer işlemleri elektronik ortamda gerçekleştirilir. (2) \"Özel\" ve üstü gizlilik dereceli belgelerin hazırlanması, kaydedilmesi, saklanması, gönderilmesi, alınması ve diğer işlemler ilgili mevzuatta belirtilen hükümlere uygun olarak fiziksel ortamda gerçekleştirilir. (3) Belgenin imzacısı olan yetkili makam, belgeye ait gizlilik derecesinin belirlenmesinden sorumludur.",
  "Resmî Yazışma m.26": "Güvenli elektronik imza ile imzalanan süreli belgelerde \"ACELE\" veya \"GÜNLÜDÜR\" ibaresine üstveride ve üst yazı üzerinde yer verilir. (...) (2) \"ACELE\" ibaresi taşıyan belgeye derhâl ve süratle; \"GÜNLÜDÜR\" ibaresi taşıyan belgeye belirtilen süre içinde cevap verilir. (3) (...) süreli belgelerde \"ACELE\" veya \"GÜNLÜDÜR\" ibaresi yazı alanının sağ üst köşesinde kırmızı renkli olarak belirtilir (...). (4) \"KİŞİYE ÖZEL\" ibaresi, belgenin ilgilisine teslim edilmesini ve sonrasında yürütülecek süreci ifade eder. (5) \"KİŞİYE ÖZEL\" ibaresi taşıyan belgenin zarfı açılmadan zarf üzerinde yer alan bilgiler, yetkili birimce (...) kaydedilir ve ilgilisine teslim edilir (...).",
  "Resmî Yazışma m.28": "Güvenli elektronik imza ile imzalanan belgelerde asgari olarak e-Yazışma Teknik Rehberi'nde belirtilen üstveri elemanları kullanılır. (...) (3) Elektronik ortamda güvenli elektronik imza ile imzalanan belgenin üstveri elemanları, belgenin ayrılmaz bir bütünüdür. Tarih ve sayı gibi belge görüntüsü üzerinde yer alan bilgiler ile üstveride yer alan bilgiler arasında fark olamaz.",
  "Resmî Yazışma m.29": "Güvenli elektronik imza ile imzalanan belgenin çoğaltılması, yetkilendirilmiş görevliler tarafından çıktı alınarak gerçekleştirilir. Çoğaltılan güvenli elektronik imzalı belgenin doğrulama işlemi, 23 üncü maddenin ikinci fıkrasında belirtildiği şekilde yapılır. (2) Zorunlu hâllerde veya olağanüstü durumlarda ya da bu Yönetmeliğin yürürlüğe girdiği tarihten önce fiziksel ortamda hazırlanan bir belgeden örnek çıkartılması hâlinde, çoğaltılan belgenin uygun bir yerine \"ASLI GİBİDİR\" ibaresi konulur ve yetkilendirilmiş görevli tarafından ad, soyad, unvan ve tarih belirtilmek suretiyle imzalanır. Bu şekilde çoğaltılan belge, asıl belge gibi kabul edilir.",
  "Resmî Yazışma m.3": "c) Belge: (...) güvenli elektronik imza ya da el yazısıyla imzalanmış ve kayıt altına alınmış her türlü bilgiyi, p) Üstveri: Bir belgeyi tanımlayan gönderici, konu, tarih, sayı ve benzeri tüm bilgileri, r) Üst yazı: Belgenin, varsa ek veya ekleri hariç kısmını, ifade eder.\n\na) Aidiyet zinciri: Belgenin hazırlanmasından tasfiyesine kadar olan sürecini, b) Arşiv imza: Kriptografik metodların zaman içerisinde koruyucu özelliğini yitirmesine karşı, periyodik olarak alınan zaman damgası ile korunan elektronik imzayı, e) Elektronik onay: Güvenli elektronik imza kullanılmayan durumlarda paraf yerine geçecek kaydın elektronik ortamda alınmasını, ifade eder.",
  "Resmî Yazışma m.30": "Güvenli elektronik imza ile imzalanan belgelerin gönderilmesi ve alınması işlemlerinin, elektronik ortamda ilgili mevzuatla yetki verilmiş üçüncü bir taraf aracılığıyla kayıt altına alınarak yapılması esastır. (...) (4) İdare, başka bir idareden kendisine resmî yazışma kapsamında iletilen ve e-Yazışma Teknik Rehberi'nde tanımlanan kurallara uygun şekilde hazırlanmamış bir belgeyi reddetme hakkına sahiptir. Bu durumda, kendisine iletilen belgeyi reddeden idare, gönderen idareye bu durumu sebepleriyle birlikte belgenin kendisine ulaştığı tarihi takip eden ikinci iş gününün sonuna kadar bildirir.",
  "Resmî Yazışma m.31": "(1) Muhatabına elektronik olarak iletiminin mümkün olmadığı durumlarda, yetkilendirilmiş görevliler tarafından çıktısı alınan güvenli elektronik imzalı belge, elektronik ortamdaki aslına erişim amacı ile fiziksel ortamda gönderilir. (...) (5) İdareler, fiziksel ortamda alınan belgeler için gelen belge kaydında kullanacakları etikette/kaşede en az Örnek 23'te belirtilen unsurlara yer verir. Etiket/kaşe, üst yazının ilk sayfasının ön veya arka yüzüne basılır. (6) Birime fiziksel ortamda gelen belgelerle ilgili havale, talimat ve benzeri işlemler, üst yazının ilk sayfasının ön veya arka yüzüne kaşe basılarak belge üzerinde gösterilebilir. Bu kaşenin şekli ilgili birimler tarafından belirlenir. (7) Kişiler tarafından idareye yazılan dilekçelerin; '… arz ederim.' şeklinde bitirilmemesi veya '… rica ederim.' ibaresiyle ya da başka ibarelerle bitirilmesi dilekçenin işleme alınmasına engel değildir.",
  "Resmî Yazışma m.33": "İdare içi ve idare dışı görüş, bilgi ve belge talep yazıları günlü yazılır. İdareler, ilgili mevzuattaki özel hükümler saklı kalmak kaydıyla süre belirtilmeyen belge taleplerini, talebin kendilerine ulaşmasından itibaren en geç beş iş günü; süre belirtilmeyen bilgi ve görüş taleplerini ise talebin kendilerine ulaşmasından itibaren en geç on beş iş günü içinde yerine getirir. (...)",
  "Resmî Yazışma m.38": "MADDE 36- (...) (3) Bu Yönetmelik ile ilgili (...) ortaya çıkabilecek tereddütleri gidermeye ve gerektiğinde uygulamaya yönelik esasları düzenlemeye Cumhurbaşkanlığı İdari İşler Başkanlığı yetkilidir. MADDE 38- (1) Bu Yönetmelik yayımını takip eden ayın birinci günü yürürlüğe girer. MADDE 39- (1) Bu Yönetmelik hükümlerini Cumhurbaşkanı yürütür.",
  "Resmî Yazışma m.4": "Kamu kurum ve kuruluşlarınca resmî yazışmalar, elektronik ortamda e-Yazışma Teknik Rehberi'ne uygun olarak hazırlanan ve güvenli elektronik imza ile imzalanan belgelerle yapılır. Bu belgeler, elektronik ortamda muhatapları ile paylaşılır ve elektronik ortamda saklanır. Ayrıca güvenli elektronik imza ile imzalanan belgeler, çıktısı alınarak el yazısıyla atılan imza ile imzalanmaz ve fiziksel ortamda saklanmaz. (2) Zorunlu hâllerde veya olağanüstü durumlarda resmî yazışmalar, el yazısıyla imzalanan belgelerle yapılır. Bu belgelerin gönderilmesi ve saklanması fiziksel ortam şartlarına göre gerçekleştirilir.",
  "Resmî Yazışma m.5": "Elektronik ortamda güvenli elektronik imza ile imzalanan belgeler tek nüsha olarak hazırlanır. (2) Zorunlu hâllerde veya olağanüstü durumlarda hazırlanacak belgeler, paraflı nüshası hazırlayan idarede kalacak şekilde en az iki nüsha olarak düzenlenir.",
  "Resmî Yazışma m.6": "MADDE 6- (1) Belgeler, A4 (210x297 mm) boyutu dikkate alınarak hazırlanır. (2) Belge ekleri farklı form, format veya ebatlarda hazırlanabilir. (3) Zorunlu hâllerde veya olağanüstü durumlarda hazırlanacak belgelerin üst yazıları için kâğıdın bir yüzü kullanılır. Ancak üst yazının ekleri için kâğıdın her iki yüzü de kullanılabilir. MADDE 7- (1) Hazırlanan belgelerde \"Times New Roman\" veya \"Arial\" yazı tipi normal yazı stilinde kullanılır. Harf büyüklüğünün Times New Roman için 12 punto, Arial için 11 punto olması esastır. Ancak gerekli hâllerde yazı alanında harf büyüklüğü 9 puntoya, iletişim bilgileri kısmında ise 8 puntoya kadar düşürülebilir. Belge eklerinde farklı yazı tipi ve harf büyüklüğü kullanılabilir.",
  "Resmî Yazışma m.8": "Belgenin yazı alanı sayfanın üst, sol ve sağ kenarından 1,5 cm boşluk bırakılarak düzenlenir. İdare, logo kullanmak istediğinde sayfanın üst boşluğu 0,5 cm olarak düzenlenir.",
  "Resmî Yazışma m.9": "İdareler, tercihen kurumsal logo kullanabilir. Logo, tek kullanıldığında belgenin en üst orta kısmında \"T.C.\" ibaresini ortalayacak şekilde veya \"Başlık\" alanını ortalayacak şekilde belgenin üst sol kısmında yer alır (...). Belge üzerinde iki ayrı logo kullanıldığında ise \"Başlık\" alanını ortalayacak şekilde hiyerarşi yönünden üst olan idareye ait logo solda, alt olan idareye ait logo sağda kullanılır. (...) Belge üzerinde en fazla iki logo kullanılabilir (...).",
  "Ses/Gaz Fişeği Yön m.13": "(1) Ses ve gaz fişeği atabilen silahların satışı, mermi veya av malzemesi ya da yivsiz tüfek satışı yapmak için ruhsatlandırılmış yerlerce yapılır. (2) Ses ve gaz fişeği atabilen silahları satan yerler, yurt içine ve yurt dışına sattıkları mamullerin cins, çap ve seri numaralarını, satın alan kişi veya kuruluşun ad ve açık adreslerini belirleyecek tarzda bilgisayar ortamında düzenleyecekleri listeleri bir ay içerisinde kolluk birimlerine bildirmek zorundadır. Merkezi kayıt sisteminin devreye alınmasını müteakip bildirimler depo girişinde ve çıkışında anlık olarak yapılır. (3) Genel amaçlı üretimlerden yurt içine satılan ses ve gaz fişeği atabilen silahların ambalaj ve kutularına Ek-1'de yer alan yasal uyarı ile ses ve gaz fişeği atabilen silahın kullanım kılavuzunun konulması zorunludur.",
  "Ses/Gaz Fişeği Yön m.14": "(2) Yetki belgesinin geçerlilik süresi 6 aydır. (3) Alınan her yetki belgesi ile bir adet ses ve gaz fişeği atabilen silah alınabilir.\n\n(3) (...) Ancak ülkemizde ikamet eden yabancılara, turistlere, mültecilere, şartlı mülteci ve ikincil koruma statüsü sahipleri ile insani ikamet izni sahipleri ve geçici koruma sağlananlara ses ve gaz fişeği atabilen silah satılamaz. (4) Dağıtıcının, Kanunun 3 üncü maddesinde belirtilen şartları sağlamayan ve merkezi kayıt sisteminin devreye alınmasını müteakip yetki belgesi olmayan kişilere satış yapması durumunda İçişleri Bakanlığınca verilen bayilik belgesi 5 yıl süre ile iptal edilir.",
  "Ses/Gaz Fişeği Yön m.15": "(1) Ses ve gaz fişeği atabilen silah sadece dağıtıcılardan alınır. Merkezi kayıt sisteminin devreye alınmasını müteakip yetki belgesi sahibi, bu yetki belgesi ile birlikte dağıtıcılardan ses ve gaz fişeği atabilen silahı satın alma işlemini gerçekleştirir. (2) Satın alma işlemini gerçekleştiren kişi fatura tarihinden itibaren bir aylık bildirim süresi içerisinde, fatura ve ses ve gaz fişeği atabilen silah ile birlikte kolluk birimine müracaat eder. Müracaat edilen kolluk birimince her ses ve gaz fişeği atabilen silah için Ek-3'te yer alan Ses ve Gaz Fişeği Atabilen Silah Bildirim Kartı düzenlenir.\n\n(3) Film, tiyatro, sinema, şenlik, kutlama ve tören gibi etkinlikler için kullanılacak ses ve gaz fişeği atabilen silahların satışında satın alma yetkilendirme ve izin işlemleri Emniyet Genel Müdürlüğü tarafından yapılır. Bu etkinlikler için kullanılacak silahlarda genel satış amaçlı silah satın alma şartları aranmaz. Satın alma işlemi sonrasında Emniyet Genel Müdürlüğü tarafından süreli olarak izin verilir ve kullanılacak silahlar için bildirim kartı düzenleme işlemi yapılmaz. Verilen süre sonunda izin verilen silahlar Makine ve Kimya Endüstrisi Anonim Şirketinde imha edilmek üzere Emniyet Genel Müdürlüğüne teslim edilir veya ihraç edilir.",
  "Ses/Gaz Fişeği Yön m.17": "(1) Ses ve gaz fişeği atabilen silahlar; fişekleri boşaltılarak, her an kullanıma ve erişim kolaylığına imkân vermeyecek şekilde ve bir kutu içerisinde Ek-3'te yer alan Ses ve Gaz Fişeği Atabilen Silah Bildirim Kartı ile nakledilebilirler. Bu silahların belirtilen şekil ve şartların dışında nakledilmesi taşıma olarak kabul edilir. (2) Bu silahlar bayiden veya üçüncü şahıslardan devir veya satın alınmasından itibaren bildirimde bulunulmasına kadar tanınan bir aylık süre içerisinde birinci fıkrada belirtilen usule göre ve ancak fatura ya da Ek-5'te yer alan belge ile nakledilebilir. Merkezi kayıt sisteminin devreye alınmasını müteakip üretici ve dağıtıcılar tarafından yurt içi veya yurt dışına satılan ses ve gaz fişeği atabilen silahlar, merkezi kayıt sistemi tarafından oluşturulan nakil belgesi ile nakledilir. (3) Birinci ve ikinci fıkralarda belirtilen işlemlere aykırı davranılması durumunda Kanunun 4 üncü maddesine göre işlem yapılır. (4) Ses ve gaz fişeği atabilen silahlar birinci ve ikinci fıkralarda belirtilen usullere uygun olarak posta veya kargo yoluyla nakledilebilir.",
  "Ses/Gaz Fişeği Yön m.4": "Ses ve gaz fişeği atabilen silah: Bu Yönetmelik kapsamında özellikleri belirlenen ses ve gaz fişeği atabilen, 10/7/1953 tarihli ve 6136 sayılı Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Kanun hükümlerine tabi silah vasfında olmayan; mermi çekirdeği, saçma veya katı cisim ihtiva eden özel şekil ve nitelikteki fişekleri ise atamayacak şekilde imal edilmiş, kurusıkı silah olarak da tabir edilen silahları, (...) ifade eder.",
  "Sözleşmeli Sb/Asb m.10": "(Madde 10) Sözleşmeli astsubay adayları, ön sözleşme yapılarak askerî eğitime alınırlar. Bu eğitimi başarı ile tamamlayanlardan yönetmelikte belirtilen şartları taşıyanlarla sözleşme yapılır ve bu kişiler astsubay çavuş rütbesine nasbedilirler. Sözleşme süreleri; üç yıldan az ve dokuz yıldan fazla olmamak şartıyla, hizmet gerekleri ve yetiştirme maliyetlerine bağlı olarak kuvvet, sınıf ve branşlara göre yönetmelikte belirlenir. Yönetmelikte belirlenen şartları taşıyanların talepleri halinde sözleşmeleri yenilenebilir. Sözleşme süreleri; (...) seferberlik, savaş veya silahlı çatışmayı gerektirecek hal ile savaş hallerinde Kuvvet Komutanları, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının göstereceği lüzum üzerine, durumun devamı müddetince ilgisine göre Milli Savunma Bakanlığı veya İçişleri Bakanlığının onayı ile talebe bakılmaksızın uzatılabilir. (...) (Madde 11) Sözleşmeli astsubaylardan yönetmelikte belirtilen şartları taşıyanlar, talepleri halinde muvazzaf astsubaylığa geçirilebilirler. Muvazzaf astsubaylığa geçiş için, Türk Silâhlı Kuvvetlerindeki dördüncü fiilî hizmet yılı başından itibaren onikinci fiilî hizmet yılının bitimine kadar başvuru yapılabilir. Bu şekilde muvazzaf astsubaylığa geçirilenler; astsubay nasbedildikleri tarihten başlamak üzere onbeş yıl hizmet etmedikçe istifa edemezler.",
  "Sözleşmeli Sb/Asb m.12": "Sözleşmeli subay ve astsubayların rütbe bekleme süreleri hakkında, 27.7.1967 tarihli ve 926 sayılı Kanunda muvazzaf subay ve astsubaylar için belirlenen süreler uygulanır. (...) Her sözleşme süresinin sona erme tarihinden en az üç ay önce taraflar sözleşmeyi yenileyeceklerine dair yazılı bildirimde bulunmadıkları takdirde, sözleşme kendiliğinden sona erer. Sözleşmeli subay veya astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak fesh edemezler.",
  "Sözleşmeli Sb/Asb m.3": "a) Ön sözleşme: Türk Silâhlı Kuvvetleri birlik, karargâh, kurum ve kuruluşları ile sözleşmeli subay veya sözleşmeli astsubay adayları arasında; askerî eğitime alınmaları konusunda yapılan ve askerî eğitim dönemi başlangıcı ile subaylık veya astsubaylık nasıp onayı tarihine kadar geçecek süreyi kapsayan sözleşmeyi, b) Sözleşme : Türk Silâhlı Kuvvetleri birlik, karargâh, kurum ve kuruluşları ile sözleşmeli subay ve astsubay adaylarından askerî eğitimi başarıyla tamamlayanlar arasında yapılan ve üç yıldan az, dokuz yıldan fazla olmamak üzere hizmet yükümlülüğü getiren, örneğine göre hazırlanmış olan yazılı bir belgeyi, c) Sözleşmeli subay adayı : Sözleşmeli subay yetiştirilmek amacıyla ön sözleşme yapılarak askerî eğitime alınanları, d) Sözleşmeli astsubay adayı : Sözleşmeli astsubay yetiştirilmek amacıyla ön sözleşme yapılarak askerî eğitime alınanları, e) Sözleşmeli subay : Bu Kanunda öngörülen esaslara göre, kendileri ile sözleşme yapılarak subay nasbedilen teğmen, üsteğmen ve yüzbaşı rütbelerini haiz subayları, f) Sözleşmeli astsubay : Bu Kanunda öngörülen esaslara göre, kendileri ile sözleşme yapılarak astsubay nasbedilen; astsubay çavuş, astsubay kıdemli çavuş, astsubay üstçavuş ve astsubay kıdemli üstçavuş rütbelerini haiz astsubayları, g) Askeri eğitim: Sözleşmeli subay ve sözleşmeli astsubay adaylarına okul, kurum, sınıf okulu, kıtalar veya eğitim merkezlerinde yaptırılacak olan temel askerlik ile subaylık veya astsubaylık anlayışı kazandırma eğitimini, h) Emsal: Sözleşmeli subaylar için subaylığa nasbedildikleri yıl harp okullarından mezun olan muvazzaf subayları; sözleşmeli astsubaylar için ise astsubaylığa nasbedildikleri yıl astsubay meslek yüksekokullarından mezun olan muvazzaf astsubayları, ı) Sözleşme yılı: Sözleşmenin yürürlüğe girdiği ay ve günü başlangıç olarak kabul eden ve bu tarihten itibaren geçen her bir yıllık süreyi, ifade eder.",
  "Sözleşmeli Sb/Asb m.4": "Sözleşmeli subay kaynaklarını; en az dört yıllık fakülte veya yüksekokulları bitirenlerden düzeltilmemiş nüfus kaydına göre müracaat yapılan yılın ocak ayının ilk günü itibarıyla yirmiyedi yaşını, lisansüstü eğitimini tamamlamış olanlardan otuziki yaşını bitirmemiş olanlar teşkil eder. Askeri okullardan ve Türk Silahlı Kuvvetlerinden her ne sebeple olursa olsun ilişikleri kesilen personel, Türk Silahlı Kuvvetlerine sözleşmeli subay olarak alınmaz. Ancak, askerlik yükümlülüğünü yerine getirmekte olanlar veya terhis edilenler sözleşmeli subay olabilirler. Sözleşmeli subaylık için genel olarak aşağıdaki nitelikler aranır: a) Türk vatandaşı olmak. b) Bu Kanunda belirtilen öğrenim ile ilgili koşulları taşımak. c) Sağlık ile ilgili Yönetmelikte belirtilen şartları taşımak. d) Kamusal hakları kullanmaktan yoksun bırakılmamış olmak. e) (...) yüz kızartıcı veya şeref ve haysiyet kırıcı suçlar ile (...) suçlardan birisinden (...) mahkum olmamak. f) Güvenlik soruşturması olumlu sonuçlanmış olmak. g) Yapılacak olan sınavlarda başarılı olmak. (...) Askeri hakim sınıfına, sözleşmeli subay statüsünde personel alınmaz.",
  "Sözleşmeli Sb/Asb m.6": "Sözleşmeli subay adayları ön sözleşme yapılarak askerî eğitime alınırlar. Bu eğitimi başarı ile tamamlayanlardan yönetmelikte belirtilen şartları taşıyanlarla sözleşme yapılır ve bu kişiler teğmen rütbesine nasbedilirler. Sözleşme süreleri üç yıldan az ve dokuz yıldan fazla olmamak şartıyla, hizmet gerekleri ve yetiştirme maliyetlerine bağlı olarak kuvvet, sınıf ve branşlara göre yönetmelikte belirlenir. Yönetmelikte belirlenen şartları taşıyanların talepleri halinde sözleşmeleri yenilenebilir. Ancak sözleşmeli subaylardan rütbe yaş haddini dolduranlar hakkında 8.6.1949 tarihli ve 5434 sayılı Kanun hükümleri uygulanır. Sözleşme süreleri; terörle mücadele sırasında veya bu görevlerden dolayı alıkonulma ya da kaybolma hâli ve (...) seferberlik, savaş veya silahlı çatışmayı gerektirecek hal ile savaş hallerinde Kuvvet Komutanları, Jandarma Genel Komutanı ve Sahil Güvenlik Komutanının göstereceği lüzum üzerine, durumun devamı müddetince ilgisine göre Milli Savunma Bakanlığı veya İçişleri Bakanlığının onayı ile talebe bakılmaksızın uzatılabilir.",
  "Sözleşmeli Sb/Asb m.7": "Sözleşmeli subaylardan yönetmelikte belirtilen şartları taşıyanlar, talepleri halinde muvazzaf subaylığa geçirilebilirler. Muvazzaf subaylığa geçiş için, Türk Silâhlı Kuvvetlerindeki yedinci fiilî hizmet yılı başından itibaren onikinci fiilî hizmet yılının bitimine kadar başvuru yapılabilir. Bu şekilde muvazzaf subaylığa geçirilenler; subay nasbedildikleri tarihten başlamak üzere onbeş yıl hizmet etmedikçe istifa edemezler. Muvazzaf subaylığa geçirileceklerde, 27.7.1967 tarihli ve 926 sayılı Kanunun 14 üncü maddesindeki yaş ile ilgili hükümler uygulanmaz. Sözleşmeli subaylardan muvazzaf subaylığa geçirilenler hakkında muvazzaf subayların tâbi olduğu ilgili mevzuat hükümleri uygulanır. Türk Silahlı Kuvvetleri bünyesinde bulunan ve ön lisans, lisans ve lisansüstü düzeyde eğitim ve öğretim yapan kurum ve kuruluşların öğretim üyesi kadrolarında atamalı olarak görev yapanlarda yukarıda belirtilen fiili hizmet yılı şartı aranmaz.",
  "Sözleşmeli Sb/Asb Yön m.12": "Madde 12 - Sözleşme süreleri en az üç yıl olarak düzenlenir. Sözleşme sürelerinin azami sınırı dokuz yıldır. Kuvvet Komutanlıkları, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı sözleşme sürelerini azami ve asgari sözleşme sınırlarını aşmamak kaydıyla her sınıf ve branşa göre çıkaracakları yönergelerde ayrıca belirleyebilirler.",
  "Sözleşmeli Sb/Asb Yön m.13": "Madde 13 - Sözleşmeli subayların ve astsubayların rütbe bekleme süreleri hakkında, 27/07/1967 tarihli ve 926 sayılı Türk Silahlı Kuvvetleri Personel Kanununda muvazzaf subaylar ve astsubaylar için belirlenen süreler uygulanır. Sözleşmeli subaylardan üst rütbede kadro açığı bulunmadığı için terfi edemeyenler, terfi şartlarını haiz olmak kaydıyla sözleşme süresinin sonuna kadar derece ilerlemesi yaparlar. (...)",
  "Sözleşmeli Sb/Asb Yön m.14": "Madde 14 - (...) a) Sözleşmeli subay ve astsubaylardan, sözleşmesini yenilemek isteyenler sözleşme süresinin sona erme tarihinden 6 ay önceden başlamak suretiyle dilekçe ile ilk amirine müracaat eder. (...) d) Her sözleşme süresinin sona erme tarihinden en az 3 ay önce taraflar sözleşmeyi yenileyeceklerine dair yazılı bildirimde bulunmadıkları taktirde sözleşme kendiliğinden sona erer. (...) c) Sözleşmeli subay ve astsubay nasbedildikten sonra; yabancı memleketlere 6 ay veya daha uzun süreli öğrenim, staj, kurs (...) gidenlerin sözleşme süreleri, gidiş ve dönüş tarihleri arasında geçen sürenin iki katı kadar (...) uzatılır.",
  "Sözleşmeli Sb/Asb Yön m.15": "MADDE 15 – (...) Sözleşmeli subay ve sözleşmeli astsubaylar, sözleşme süreleri sona ermeden sözleşmelerini tek taraflı olarak feshedemezler. Sözleşmeli subay veya sözleşmeli astsubay adaylarının ön sözleşmeleri, aşağıdaki nedenlerle süresinin bitiminden önce feshedilebilir: a) Askerî eğitim esnasında yetkili kurullarca başarısız veya disiplinsiz olduğuna karar verilmek. (...) ç) Askerî eğitimin üçte birine çeşitli nedenlerle katılmamak. Sözleşmeli subay veya sözleşmeli astsubayların sözleşmeleri, aşağıdaki nedenlerle (...) feshedilebilir: (...) b) Disiplinsizlik ve ahlaki durum nedeniyle (...) görev yapamayacağı (...) anlaşılmak. c) Yetersizlik nedeniyle kendisinden istifade edilemeyeceği (...) anlaşılmak. (...)\n\nSözleşmeli subay veya sözleşmeli astsubay adaylarının ön sözleşmeleri, aşağıdaki nedenlerle (...) feshedilebilir: a) Askerî eğitim esnasında yetkili kurullarca başarısız veya disiplinsiz olduğuna karar verilmek. b) Yetkili sağlık kurullarınca askerî eğitime ve/veya göreve devam edemez kararı verilmiş olmak. c) (...) şartlarından herhangi birini taşımadığı sonradan anlaşılmak veya (...) kaybetmek. ç) Askerî eğitimin üçte birine çeşitli nedenlerle katılmamak. (...) Sözleşmeli subay veya sözleşmeli astsubayların sözleşmeleri, aşağıdaki nedenlerle (...) feshedilebilir: a) (...) eğitim ve öğretimde (...) başarısız olmak. b) Disiplinsizlik ve ahlaki durum nedeniyle (...) görev yapamayacağı (...) anlaşılmak. c) Yetersizlik nedeniyle kendisinden istifade edilemeyeceği (...) anlaşılmak. ç) (...) yüz kızartıcı/askerî suçlardan (...) mahkûm olmak. d) Taksirli suçlar hariç (...) bir ay ve daha fazla süreli hürriyeti bağlayıcı bir cezaya mahkûm olmak. e) (...) son bir yıl içinde toplamda otuz gün ve daha fazla oda hapsi veya hizmet yerini terk etmeme cezası (...) veya (...) toplam sekiz defa veya daha fazla disiplin cezası almak. f) Yasadışı siyasi, yıkıcı, bölücü, irticai faaliyetlerde bulunmak (...). g) (...) nitelik ve şartlardan herhangi birini (...) kaybetmek. ğ) Yabancı uyruklu kişilerle (...) evlilikleri (...) uygun görülmemek (...) veya Türk vatandaşlığını kaybetmek (...). h) Yetkili sağlık kurullarınca (...) göreve devamı mümkün olmamak. ı) (...) sınıflarında görev yapamayacaklarına (...) karar verilenlerden (...) istihdamına gerek duyulmamak. i) (...) bir sözleşme yılı içinde alınan hava değişimi, istirahat ve benzeri sıhhi izin süresi toplamı doksan günü geçmek. j) Haklarında yüksek disiplin kurulları tarafından Silahlı Kuvvetlerden ayırma cezası verilmiş olmak.",
  "Sözleşmeli Sb/Asb Yön m.16": "Madde 16 - (...) a) Sözleşmeli subay olarak yetiştirilecekler, 926 sayılı (...) EK-VI sayılı cetvelde asteğmenler için öngörülen dokuzuncu derecenin birinci kademe aylığı (...) yararlandırılırlar. b) Sözleşmeli astsubay olarak yetiştirilecekler, (...) 3269 sayılı Uzman Erbaş Kanununa bağlı (...) uzman onbaşılar gibi, on birinci derecenin birinci kademe aylığı (...) yararlandırılırlar. (...) askerî eğitim süresince iaşe ve ibateleri Devlet tarafından karşılanır. MADDE 17 – Sözleşmeli subay ve sözleşmeli astsubaylar, emsali rütbe ve derecedeki muvazzaf subay ve astsubaylar hakkında uygulanan aylık, tazminat, yan ödeme ve diğer mali ve sosyal haklardan aynen istifade ederler. Sözleşmeli subaylardan on beşinci, sözleşmeli astsubaylardan on sekizinci fiili hizmet yılını tamamlayanlardan (...) rütbe verilmeksizin bir üst dereceye yükseltilirler (...). Madde 18 - (...) ön sözleşme yapılması ile birlikte 5434 sayılı Kanun ile ilgilendirilirler (...). Sözleşmeli subaylar ve astsubaylar aynı zamanda Ordu Yardımlaşma Kurumunun daimi üyesidirler. Madde 19 – (...) a) (...) son olarak aldıkları net maaşın 2 katının hizmet yılıyla çarpımı tutarında tazminat verilir. (...) hizmet yılı olarak en fazla dokuz yıl esas alınır. (...) yabancı memleketlere (...) gitmiş olanlardan (...) Devletçe yapılan masrafların dört katı ayrıca tazminat olarak alınır.",
  "Sözleşmeli Sb/Asb Yön m.22": "MADDE 22 – (...) Sözleşmeli subay ve sözleşmeli astsubaylar ile bunların bakmakla yükümlü oldukları kimselerin, sözleşme süresince, sosyal hakları ve sağlık işlemlerinde (...) 211 sayılı Türk Silahlı Kuvvetleri İç Hizmet Kanununun muvazzaf subay ve astsubaylara ilişkin hükümleri uygulanır. (...) a) Kendi kusurları olmaksızın idare tarafından sözleşmeleri yenilenmeyenler (...) hizmet edilen süre kadar ve en çok on yılı, b) Sözleşme süresi sonunda kendi istekleriyle sözleşmeleri yenilenmeyenler (...) hizmet edilen sürenin yarısı kadar ve en çok beş yılı geçmemek üzere muayene ve tedavi hizmetleri askerî hastanelerde (...) ücretsiz olarak verilmeye devam edilir.",
  "Sözleşmeli Sb/Asb Yön m.23": "MADDE 23 – Giyim, kuşam ve istihkakların verilme usulleri; a) Sözleşmeli subay adayları için yedek subay adaylarında, b) Sözleşmeli astsubay adayları için astsubay naspedilmek üzere temel askerlik eğitimine tabi tutulan adaylarda, c) Sözleşmeli subay ve sözleşmeli astsubaylar için ise muvazzaf subay ve astsubaylarda olduğu gibidir. Madde 24 - Sözleşmeli subaylara askeri eğitimi müteakip (...) 4608 sayılı Kanuna göre, sözleşmeli astsubaylara da (...) 1468 sayılı Kanuna göre bir defaya mahsus olmak üzere zati tabanca verilir. (...) 15 inci maddenin dördüncü fıkrasının (a)-(ğ) bentlerinde sayılan nedenlerden herhangi biriyle (...) ilişiği kesilenler ile dokuzuncu fiili hizmet yılından önce ayrılanların, zati tabancaları geri alınır. (...) Madde 25 - Sözleşmeli subay ve astsubaylar, (...) Milli Savunma Bakanlığı veya İçişleri Bakanlığına (...) ait konutlardan, kiralama sisteminden ve lojman tazminatından emsali muvazzaf subay ve astsubaylar gibi istifade ederler.",
  "Sözleşmeli Sb/Asb Yön m.26": "Madde 26 – (...) Sözleşmeli subay ve sözleşmeli astsubaylar hakkında muvazzaf subay ve astsubaylara uygulanan disiplin ve ceza hükümleri, sözleşmeli subay adayları hakkında yedek subay adaylarına uygulanan disiplin ve ceza hükümleri; sözleşmeli astsubay adayları hakkında ise astsubay naspedilmek üzere temel askerlik eğitimine tabi tutulan adaylara uygulanan disiplin ve ceza hükümleri tatbik edilir. Jandarma Genel Komutanlığına mensup sözleşmeli subay ve sözleşmeli astsubayların mülki hizmete ilişkin suçlarında 10/3/1983 tarihli ve 2803 sayılı Jandarma Teşkilat, Görev ve Yetkileri Kanununun ilgili hükümleri uygulanır.",
  "Sözleşmeli Sb/Asb Yön m.3": "a) (...) Ön sözleşme: Türk Silahlı Kuvvetleri birlik, karargâh, kurum ve kuruluşları ile sözleşmeli subay veya sözleşmeli astsubay adayları arasında; askerî eğitime alınmaları konusunda yapılan ve askerî eğitim dönemi başlangıcı ile subaylık veya astsubaylık nasıp kararnamesinin onay tarihine kadar geçecek süreyi kapsayan sözleşmeyi (...), b) Sözleşme: Türk Silahlı Kuvvetleri birlik, karargah, kurum ve kuruluşları ile sözleşmeli subay veya astsubay adaylarından askeri eğitimi başarı ile tamamlayanlar arasında yapılan ve üç yıldan az, dokuz yıldan fazla olmamak üzere hizmet yükümlülüğü getiren (...) yazılı bir belgeyi, (...) c) Sözleşmeli Subay/Astsubay Aday Adayı: Sözleşmeli subay veya astsubay adayı olmak için müracaat etmiş ancak henüz kendileriyle ön sözleşme yapılmamış olanları, ç) Sözleşmeli Subay Adayı: Sözleşmeli subay yetiştirilmek amacıyla ön sözleşme yapılarak askeri eğitime alınanları, (...)\n\ne) Sözleşmeli Subay: Bu Yönetmelikte öngörülen esaslara göre, kendileri ile sözleşme yapılarak subay nasbedilen teğmen, üsteğmen ve yüzbaşı rütbelerini haiz subayları, f) Sözleşmeli Astsubay: (...) astsubay nasbedilen astsubay çavuş, astsubay kıdemli çavuş, astsubay üstçavuş ve astsubay kıdemli üstçavuş rütbelerini haiz astsubayları, (...) ğ) (...) Emsal: Sözleşmeli subaylar için subaylığa nasbedildikleri yıl harp okullarından mezun olan muvazzaf subayları; sözleşmeli astsubaylar için ise astsubaylığa nasbedildikleri yıl astsubay meslek yüksekokullarından mezun olan muvazzaf astsubayları, (...)",
  "Sözleşmeli Sb/Asb Yön m.30": "Madde 30 - Sözleşmeli subay ve astsubay aday adayları (...) belirleyeceği makamlara, çıkarılacak yönergede belirtilen usullere uygun olarak müracaat ederler. Müracaatları kabul edilenler fiziki yetenek, değerlendirme testi, genel kültür ve meslek bilgisi ile mülakata tabi tutulurlar. (...) Yapılacak değerlendirmeler sonucunda başarılı olanlardan tam teşekküllü askeri hastanelerden sınıfında 'Sözleşmeli Subay veya Astsubay Olur' kararlı sağlık raporu alanlardan ihtiyaç kadarı ile ön sözleşme yapılır, bunlar sözleşmeli subay veya astsubay adayı olurlar.",
  "Sözleşmeli Sb/Asb Yön m.31": "MADDE 31 – (...) Sözleşmeli subay ve astsubay adayları ile sözleşmeli subay ve astsubaylarla (...) ön sözleşme ve ön sözleşmeden sonraki ilk sözleşmeyi yapmaya yetkili makamlar, kuvvet komutanlıkları, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı Personel Temin Merkezi Komutanı veya eşidi birim amiridir. (...) Müteakip sözleşmeleri yapmaya yetkili makamlar, kuvvet komutanlıkları, Jandarma Genel Komutanlığı ve Sahil Güvenlik Komutanlığı Tayin/Atama Daire Başkanı veya eşidi birim amiridir.",
  "Sözleşmeli Sb/Asb Yön m.32": "Madde 32 – (...) Askeri eğitimi başarıyla tamamlayan sözleşmeli subay ve astsubay adayları kendilerinin istemesi ve idarenin uygun görmesi üzerine EK-A ve EK-B'de örneği gösterilen belgeyi imzalayarak subaylığa veya astsubaylığa nasıp (...) onayları çıktıktan sonra subay veya astsubay nasbedilirler. Bu personelin subaylık/astsubaylık nasıpları hangi tarihte olursa olsun, kademe ilerlemesi veya üst rütbeye yükselmelerine esas olacak nasıplarında kararname takvim yılının 30 Ağustos'u itibar olunur. (...) Ancak sözleşme yenileme tarihleri için ilk sözleşme imzaladıkları tarih esas alınır. (...)",
  "Sözleşmeli Sb/Asb Yön m.5": "Sözleşmeli subay kaynaklarını; en az dört yıllık fakülte veya yüksekokulları bitirenlerden (...) müracaat yapılan yılın Ocak ayının ilk günü itibariyle yirmi yedi yaşını, lisansüstü eğitimini tamamlamış olanlardan otuz iki yaşını bitirmemiş olanlar (...) teşkil eder. Sözleşmeli astsubay kaynaklarını; (...) a) Dört yıl veya daha fazla süreli yüksek öğrenimi bitirenler için yirmi yedi yaşını, b) Dört yıldan daha az süreli yüksek öğrenimi bitirenler için yirmi dört yaşını, bitirmemiş olanlardan (...) teşkil eder. Askerî okullardan ve Türk Silahlı Kuvvetlerinden her ne sebeple olursa olsun ilişikleri kesilen personel, Türk Silahlı Kuvvetlerine sözleşmeli subay veya sözleşmeli astsubay olarak alınmaz. (...) Askerî hâkim sınıfına, sözleşmeli subay statüsünde personel alınmaz.",
  "Sözleşmeli Sb/Asb Yön m.8": "b) (...) 1) Muvazzaf subaylığa geçiş sınavları yazılı sınav, fiziki yeterlilik ve değerlendirme testi ile mülakat sınavı olmak üzere üç aşamalı yapılır. (...) 5) (...) Mülakat sınavına katılan adayın asgari yetmiş puan almış olma şartı aranır. 6) Başarı sıralamasına esas değerlendirme notu, yazılı sınav notunun %55'i, fiziki yeterlilik ve değerlendirme testinde alınan notun %15'i ve mülakat sınav notunun %30'unun toplamına, sicil notu ortalaması ile (...) mükâfat puanının eklenmesi (...) ile belirlenir.",
  "Sporda Şiddet m.12": "MADDE 12 – (1) (...) Müsabaka, seyir, özel seyir ve antrenman alanları ile takım veya taraftarların toplu olarak seyahat ettikleri araçlara; a) Ruhsatlı dahi olsa ateşli silahlar ile esasen bulundurulması yasak olan diğer silahların, b) Esasen bulundurulması yasak olmamakla beraber kesici, ezici, bereleyici veya delici aletler ile patlayıcı, parlayıcı, yanıcı veya yakıcı maddelerin, c) Uyuşturucu veya uyarıcı maddelerin, sokulması yasaktır. Müsabaka, seyir ve antrenman alanlarında alkollü içecek sokulması, kullanılması ve satılmasına ilişkin usul ve esaslar ilgili federasyonlar tarafından belirlenir.\n\n(2) Müsabaka güvenliğinin sağlanması amacıyla, genel kolluk görevlileri ile bunların gözetiminde olmak üzere özel güvenlik görevlileri, mülki amirin yazılı emrine istinaden, spor alanına girişte izleyicilerin üstünü ve eşyasını teknik cihazlarla ve gerektiğinde el ile kontrol edebilir ve arayabilir. (3) Spor müsabakası öncesinde, esnasında ve sonrasında spor alanında taraftarların üzeri ve eşyası 4/7/1934 tarihli ve 2559 sayılı Polis Vazife ve Salahiyet Kanununun önleme aramasına ilişkin hükümlerine göre aranabilir. (4) 4/12/2004 tarihli ve 5271 sayılı Ceza Muhakemesi Kanununun adli aramaya ilişkin hükümleri saklıdır. (5) Genel kolluk görevlileri ve belediye zabıtası birinci fıkranın (b) ve (c) bentleri kapsamına giren alet veya maddeleri spor alanında seyyar olarak satan, satışa arz eden, dağıtan veya dağıtmak için bulunduran kişileri bu alandan uzaklaştırmakla yükümlüdür.",
  "Sporda Şiddet m.4": "MADDE 4 – (1) İl spor güvenlik kurulu, vali veya görevlendireceği vali yardımcısının başkanlığında, belediye başkanlığı, il jandarma komutanlığı, il emniyet müdürlüğü, gençlik ve spor il müdürlüğü, il sağlık müdürlüğü, il milli eğitim müdürlüğü, ilgili federasyon ve amatör spor kulüpleri konfederasyon temsilcileri, vali tarafından belirlenecek bir hukukçu ile farklı spor kulüplerine mensup stat güvenliğinden sorumlu yönetim kurulu üyesi ve gerekli görüldüğünde davet edilecek basın kuruluşlarının ve ilgili kamu kuruluşlarının temsilcilerinden oluşur. (2) İlçe spor güvenlik kurulu, kaymakam başkanlığında il spor güvenlik kurulunda yer alan kurum ve kuruluşların ilçedeki temsilcileri ve kaymakam tarafından belirlenecek bir hukukçu ile varsa farklı spor kulüplerine mensup stat güvenliğinden sorumlu yönetim kurulu üyesi (...) temsilcilerinden oluşur.",
  "Sporda Şiddet m.6": "MADDE 6 – (1) Profesyonel spor dallarında yapılan müsabakalara katılanlar ile basketbol en üst ligindeki spor kulüpleri, genel kolluk ile birlikte görev yapmak üzere güvenliği sağlamaya yetecek sayıdaki özel güvenlik görevlilerini müsabaka öncesinden müsabakanın tamamlanıp seyirci ve sporcuların tahliyesine kadar geçecek dönem içerisinde, müsabakanın yapılacağı yerde bulundurmakla ve müsabaka, antrenman ve seyir alanlarının güvenliğini sağlamakla yükümlüdür. (...) (4) Müsabaka, antrenman ve seyir alanlarında görev yapacak özel güvenlik görevlileri, (...) 5188 sayılı Özel Güvenlik Hizmetlerine Dair Kanunda belirtilen görev ve yetkileri haizdir. Bu Kanundan doğan görevlerinin ifası sırasında, özel güvenlik görevlilerinin ateşli silah taşımaları yasaktır.\n\n(3) (...) Müsabakada görevlendirilecek özel güvenlik görevlilerinin kimlik bilgileri müsabakanın başlangıç saatinden en geç kırk sekiz saat önce ilgili kolluk birimine bildirilir. (...) Bu kolluk görevlilerine, görevlendirildikleri müsabaka ile sınırlı olarak günlük harcırah miktarının üç katı kadar ödeme yapılır. (...) İl veya ilçe spor güvenlik kurulları tarafından belirlenen özel güvenlik görevlisi sayısının yarısını, yüksek riskli müsabakalarda ise üçte ikisini geçmeyecek sayıda ve bunların yerine genel kolluk görevlisi bu şekilde görevlendirilir.",
  "Sporda Şiddet m.7": "MADDE 7 – (1) Müsabaka güvenlik amiri veya yardımcısı, spor müsabakalarında alınacak güvenlik önlemlerinin yürütülmesi ve denetlenmesi konularında, müsabakanın güvenliği ile ilgili tüm kişi ve kuruluşlarla gerekli koordinasyonu sağlamakla yetkili ve görevlidir. (2) Her spor güvenlik birimi amiri, futbolda en üst lig ve bir altındaki lig için, her bir kulüple ilgili bir kolluk görevlisini gözlemci olarak görevlendirmekle yükümlüdür. Belirlenen kolluk görevlisi, deplasman maçları dahil ilgili kulübün bütün maçlarında görevlendirilir. (5) (Ek:4/7/2019-7182/5 md.) Spor müsabakalarından önce müsabaka güvenlik amirinin başkanlığında müsabakanın güvenliğine ilişkin eş güdüm toplantısı yapılır. Bu toplantının yapılacağı müsabakalar ile toplantıya katılacaklar ve gerekli diğer hususlar yönetmelikle belirlenir.\n\n(3) Müsabaka ve seyir alanlarında genel kolluk görevlileri ile özel güvenlik görevlileri, müsabaka güvenlik amiri ve yardımcısının emir ve denetiminde birlikte görev yapar. Müsabaka güvenlik amiri her zaman tribünlerdeki genel kolluk görevlilerinin sayısının artırılmasına karar verebilir. (4) İl veya ilçe spor güvenlik kurulları, müsabaka ve seyir alanında spor kulüplerinin bulundurmakla yükümlü oldukları özel güvenlik görevlilerinin sayısını ve görev alacakları yerleri belirlemekle yetkilidir.",
  "Su Ürünleri m.19": "Bomba, torpil, dinamit, kapsül ve benzeri patlayıcı maddeler öldürücü veya uyuşturucu maddeler, sönmemiş kireç ve Tarım Orman ve Köyişleri Bakanlığının müsaadesi alınmaksızın elektrik cereyanı, elektroşok ve hava tazyiki ile su ürünleri avlanması yasaktır. Tespit olunacak belli bir aydınlatma gücünü geçmemek üzere elektrik cereyanı ile aydınlatma ve münhasıran denizlerde olta ile avlanan su ürünlerinin denizden çıkarılmasında elektroşok usulünün uygulanması müsaadeye bağlı değildir.",
  "Su Ürünleri m.2": "Su ürünleri: Denizlerde ve içsularda bulunan bitkiler ile hayvanlar ve bunların yumurtalarıdır. (Kara Avcılığı Kanunu şümulüne giren hayvanlar hariç) (...) İçsular: Göller, suni göller, lagünler, baraj gölleri, bentler, regülatörler, kanallar, arklar, akarsular, mansaplar, üretme ve yetiştirme yerleridir. Lagünler: Denizle irtibatı ve denizin etkisi altında bulunan göllerdir. Mansaplar: Akarsuların göl veya denizlere açıldığı bölgelerde akarsuyun etkisi altında kalan su ürünleri istihsaline elverişli sahalardır. Üretme ve yetiştirme yerleri: Su ürünlerini üretmek ve yetiştirmek için yapılan tesislerdir.\n\nSabit dalyan: Denizlerde ve içsularda su ürünleri istihsal etmek için kazık, çit, çubuk, tel, taş veya beton ve benzeri manialarla çevrilmek suretiyle, sınırları değişmeyecek şekilde kurulan veya tabii olarak çevrilmiş su sahalarından meydana getirilen diple irtibatlı tesislerdir. Muvakkat dalyan (Yüzer): Şamandıra, duba, tekne ve saireye bağlı ağlarla çevrilmek suretiyle kurulan su mahsulleri istihsaline mahsus tesislerdir. (...) Dip trolu: Bir veya daha çok gemiler ile çekilmek suretiyle zemin üzerinde sürütülerek dip su ürünlerini istihsale mahsus trol ağları ve bu ağlarla yapılan su ürünleri istihsalidir. Orta su trolu: Munhasıran göçmen balıkların istihsaline mahsus, dibe temas etmeksizin suyun ortasından veya yüzüne yakın kısımdan çekilen trol ağları ve bunlarla yapılan su ürünleri istihsalidir. Kombine trol: Dip ve orta su trolunu yapmaya elverişli trol ağları ve bunlarla yapılan su ürünleri istihsalidir.\n\nMansaplar: Akarsuların göl veya denizlere açıldığı bölgelerde akarsuyun etkisi altında kalan su ürünleri istihsaline elverişli sahalardır. Dalyan yeri: Bir veya mütaaddit sabit yahut muvakkat dalyan kurmaya elverişli istihsal sahalarıdır. Voli yeri: Deniz ve içsularda su ürünleri istihsaline elverişli, sahile bitişik ve sınırları belli su sahalarıdır. Muvakkat dalyan (Yüzer): Şamandıra, duba, tekne ve saireye bağlı ağlarla çevrilmek suretiyle kurulan su mahsulleri istihsaline mahsus tesislerdir.",
  "Su Ürünleri m.20": "Su ürünleri veya bunları istihlak edenlerin veya kullananların sağlığına veyahut istihsal vasıtalarına malzeme, teçhizat, alet ve edevata zarar veren maddelerin içsulara ve denizlerdeki istihsal yerlerine veya civarlarına dökülmesi veya döküleceği şekilde tesisat yapılması yasaktır. Hangi maddelerin dökülmesinin yasak olduğu yönetmelikte gösterilir.",
  "Su Ürünleri m.21": "Türk vatandaşı olmayan kişilerin su ürünleri avcılığı yapmak üzere 2674 sayılı Karasuları Kanununun 1 inci maddesinde yazılı karasularına veya 4 üncü maddesinde yazılı içsulara girmeleri ve bu sularda su ürünleri avcılığında bulunmaları yasaktır. Ancak, 3 üncü maddenin 7 nci bendinde yazılı yabancı turistler ile Tarım Orman ve Köyişleri Bakanlığının müsaadesi gereğince 14 üncü maddede gösterilen etüt ve araştırma işlerinde çalışacak yabancılar bu hükümden müstesnadır.",
  "Su Ürünleri m.22": "Tarım ve Orman Bakanlığının müsaadesi alınmadan akarsularda su ürünlerinin geçmesine veya yetişmesine engel olacak şekilde ağlar kurulması, bent, çit ve benzeri engeller yapılması yasaktır. Akarsular üzerinde kurulmuş veya kurulacak olan baraj ve regülatör gibi su yapılarında su ürünlerinin geçmesine mahsus balık geçidi yapılması ve işler durumda bulundurulması zorunludur. Ancak yüksekliği yirmi metreden fazla olan su yapılarında, masrafları müteşebbisçe karşılanmak üzere Tarım ve Orman Bakanlığınca yapılacak veya yaptırılacak bilimsel araştırma ve inceleme sonucu balık geçitlerinin işlevsiz olacağının anlaşılması halinde balık geçidi dışında farklı göç yapıları, asansörle taşıma, yapay ortamda üretilip kaynağa bırakma gibi tedbirler alınabilir. Bu madde kapsamındaki balık geçidi, balık asansörü ve diğer yapılara ilişkin projenin (...) kontrollüğü (...) inşaat tekniği açısından Devlet Su İşleri Genel Müdürlüğü tarafından yapılır veya yaptırılır.",
  "Su Ürünleri m.23": "a) Su ürünleri istihsalinde kullanılan istihsal vasıtalarının haiz olmaları gereken asgari vasıf ve şartlar ile bunların kullanma usul ve esasları; b) Sağlık, memleket ekonomisi, seyrüsefer, teknik ve bilimsel yönlerden bölgeler, mevsimler, zamanlar, su ürünleri cinsleri, çeşitleri, ağırlık, irilik, büyüklük gibi vasıflar bakımından konulacak yasak, sınırlama ve yükümlülükler yönetmelikle düzenlenir. **(Mülga son fıkra: 11/6/2010-5996/47 md.)**",
  "Su Ürünleri m.24": "a) İçsular, Marmara Denizi, İstanbul ve Çanakkale boğazlarında her çeşit trol ile su ürünleri istihsali yasaktır. İlmi maksatlarla yapılacak incelemelerde trol kullanılabilir. b) Kara sularımız dahilinde dip trolu ile su ürünleri istihsali şekli ayrı bir yönetmelikle düzenlenir. Bu yönetmelik hükümlerine aykırı olarak dip trolu ile su ürünleri istihsali yasaktır. c) Orta su trolu hakkında 23 üncü madde hükümleri uygulanır. Ancak orta su trolunun dip trolu olarak kullanılması yasaktır. d) Munhasıran sünger avında kullanılan kankava troldan sayılmaz.",
  "Su Ürünleri m.25": "Zamanlar, mevsimler, cins, nev'i, çeşit, irilik, ağırlık, büyüklük itibariyle istihsali yasak olan su ürünlerinin, yasağın devam ettiği müddet zarfında her ne suretle olursa olsun satışı, nakli, imalatla kullanılması yasaktır. 19, 24 üncü maddeler hükümlerine aykırı olarak istihsal edilen su ürünlerine el konulup mülkiyeti kamuya geçirilerek bunlar hakkında 29 ve 34 üncü madde hükümleri uygulanır. Kaynakların korunması amacıyla, su ürünlerinin yurt dışına çıkarılması ve canlı olarak yurt içine sokulması izne tabidir. Bu maddenin uygulanmasına ilişkin usul, esas ve istisnalar Tarım ve Orman Bakanlığı tarafından çıkarılan yönetmelikle belirlenir.",
  "Su Ürünleri m.3": "Ticari amaçlı su ürünleri avcılık faaliyetinde bulunacak gerçek ve tüzel kişiler ile ticari amaçlı su ürünleri avcılık ya da yetiştiricilik faaliyetinde kullanılacak gemiler ve diğer su vasıtaları için Tarım ve Orman Bakanlığından ruhsat tezkeresi veya izin alınması zorunludur. (...) Ruhsat tezkerelerinin veya izinlerin yetkililerce talep edilmesi halinde gösterilmesi zorunludur. 10/6/1946 tarihli ve 4922 sayılı Denizde Can ve Mal Koruma Hakkında Kanun hükümleri saklıdır.",
  "Su Ürünleri m.33": "Tarım ve Orman Bakanlığı teşkilatında ve Bakanlığa bağlı su ürünleri ile ilgili teşekküllerde su ürünlerinin, deniz ve içsuların koruma ve kontrolü ile görevlendirilen personel ile emniyet, jandarma, sahil güvenlik, gümrük ve orman muhafaza teşkilatları mensupları, belediye zabıtası amir ve mensupları, kamu tüzel kişilerine bağlı muhafız, bekçi ve korucular ile emniyet ve jandarma teşkilatının bulunmadığı yerlerde köy muhtarı ve ihtiyar heyeti üyeleri bu Kanunla ve bu Kanuna istinaden konulan yasaklardan dolayı, bu Kanun kapsamına giren kabahatler ve suçlar hakkında zabıt varakası tutmak, kabahatin ve suçun işlenmesinde kullanılan istihsal vasıtalarına ve elde edilen su ürünlerine el koymak ve bu Kanunun ek 3 üncü maddesinde yer alan hükümler çerçevesinde idarî para cezalarını kesmekle vazifeli ve yetkilidirler.",
  "Su Ürünleri m.34": "El konulan su ürünleri ve istihsal vasıtaları hakkında aşağıdaki işlemler yapılır: a) El konulan canlı olmayan su ürünlerinden insan tüketiminde veya sanayide kullanılması mümkün, ancak muhafaza edilmesi mümkün olmayanlar (...) veteriner hekim, Hükümet, belediye veya sağlık merkezi tabiplerinden birine muayene ettirilir. Tüketiminde veya kullanılmasında sakınca görülmeyenler, Tarım ve Orman Bakanlığı tarafından açık artırma suretiyle satılır. Ancak satışa sunulan su ürünlerinden asgari avlanılabilir ağırlıktan ve boy uzunluğundan küçük olanlar ile av yasağı döneminde avlanmış olanlar perakende satılamaz, yem sanayi hammaddesi olarak satılabilir. Avlanması tamamen yasak olan türler ise kamu kurum ve kuruluşlarına, bilimsel kuruluşlara ya da sosyal yardım kuruluşlarına bağışlanabilir. (...) satış bedeli mülkiyetin kamuya geçirilmesi kararı kesinleşinceye kadar Hazine veznesine emaneten yatırılır. Mülkiyetin kamuya geçirilmesi kararı kesinleşenlerin satış bedeli genel bütçeye gelir kaydedilir. b) El konulan istihsal vasıtalarından sahipleri belli olanlar, mülkiyetin kamuya geçirilmesi kararı kesinleşinceye kadar Tarım ve Orman Bakanlığınca belirlenen alanlarda yedieminde tutulur. Sahiplenilmeyen veya mülkiyetin kamuya geçirilmesi kararı kesinleşen istihsal vasıtaları satılamaz, kamu kurum ve kuruluşlarına veya bilimsel kuruluşlara bağışlanabilir. c) Bağışlanamayan su ürünleri veya mülkiyetin kamuya geçirilmesi kararı kesinleşen bağışlanamayan istihsal vasıtaları imha edilir. (...) el konulan su ürünlerinden canlı olanların yaşam alanlarına iadeleri veya bunlar için yapılacak diğer işlemler Tarım ve Orman Bakanlığınca belirlenir. d) Fiilî imkânsızlıklar nedeniyle el konularak mülkiyeti kamuya geçirilmesi mümkün olmayan istihsal vasıtaları ve ürünlerin kaim değerinin mülkiyetinin kamuya geçirilmesine de karar verilebilir. Bu Kanuna aykırı fiiller neticesinde, istihsal vasıtaları, su ürünleri ve diğer su vasıtalarına uygulanan el koyma, yediemin, bekletme, muhafaza, imha, sökme, nakliye ve diğer işlemlere ait masraflar aykırılığı işleyenden, gemi sahibi veya donatandan tahsil edilir. Bu Kanunda düzenlenen mülkiyetin kamuya geçirilmesi kararları vali tarafından verilir.",
  "Su Ürünleri m.35": "Bu Kanun hükümlerine göre mülkiyeti kamuya geçirilmesine karar verilen muhafazası mümkün su ürünleri ile istihsal vasıtaları hakkında mülkiyetin kamuya geçirilmesi kararı kesinleştikten sonra aşağıdaki işlemler uygulanır: a) Su ürünleri satılarak bedeli genel bütçeye gelir kaydedilmek üzere Hazine veznesine yatırılır. b) İstihsal vasıtaları kamu kurum ve kuruluşlarına veya bilimsel kuruluşlara bağışlanabilir, bağışlanamayanlar imha edilir. Yasak olan eşyadan satışı mahzurlu görülenlerin imhasına ve imha şekline ilişkin hususlar yönetmelikle düzenlenir.",
  "Su Ürünleri m.36": "Bu Kanundaki ve bu Kanuna göre çıkarılan yönetmeliklerdeki yasak, sınırlama ve yükümlülüklere aykırı hareket edenlere verilecek cezalar aşağıda gösterilmiştir: (...) Kabahat konusu fiillerin tekrarı, kabahatin tespit edildiği tarihten itibaren iki yıl içinde ilk cezaya konu kabahatin tekrar işlenmesini ifade eder. Bu maddede sayılan kabahat konusu fiillerin tekrarı halinde birinci fıkranın (b), (e) ve (f) bentleri ile (j) bendinin ikinci paragrafı hariç olmak üzere, idarî para cezaları iki katı olarak uygulanır.\n\nBu maddede yazılı idarî para cezaları, tam boyu oniki metre dahil yirmiiki metreye kadar olan gemiler için iki katı, yirmiiki metre ve daha uzun gemiler için üç katı olarak uygulanır.\n\na) 3 üncü maddenin birinci fıkrasına göre ruhsat tezkeresi almadan ticari amaçlı su ürünleri avcılığı yapan kişilere bin Türk lirasından beş bin Türk lirasına kadar, gemiler ve diğer su vasıtaları için sahip veya donatanlarına beş bin Türk lirasından elli bin Türk lirasına kadar idarî para cezası verilir. (...) g) 19 uncu maddeye aykırı hareket edenlere on bin Türk lirası idarî para cezası verilir (...) el konularak mülkiyetin kamuya geçirilmesine karar verilir. (...) i) 21 inci maddenin birinci fıkrasına aykırı hareket edenlere yirmi bin Türk lirası idarî para cezası verilir ve (...) el konularak mülkiyetin kamuya geçirilmesine karar verilir. (...) l) 24 üncü maddenin birinci fıkrasının (a) bendinde belirtilen alanlarda trol ile su ürünleri istihsalinde bulunanlara on bin Türk lirası, kullanılan gemiler için sahip veya donatanlarına yirmi bin Türk lirası idarî para cezası verilir (...). Fiilin iki yıl içinde tekrarı halinde (...) hapis (...) hükmolunur. m) (...) 25 inci madde ile satışı, nakli ve imalatta kullanılması yasak edilen su ürünlerini nakledenlere, satanlara beş bin Türk lirası, bunları imalatta kullananlara, işleyenlere, muhafaza edenlere ve ihraç edenlere on bin Türk lirası idarî para cezası verilir. 25 inci maddenin üçüncü fıkrasına aykırı hareket edenlere beş bin Türk lirasından yüz bin Türk lirasına kadar idarî para cezası verilir.\n\nBu maddede sayılan kabahat konusu fiillerin tekrarı halinde birinci fıkranın (b), (e) ve (f) bentleri ile (j) bendinin ikinci paragrafı hariç olmak üzere, idarî para cezaları iki katı olarak uygulanır. b) 4 üncü maddeye göre (...) kooperatiflerin (...) başkan ve yönetim kurulu üyelerine ayrı ayrı iki bin beş yüz Türk lirasından yirmi beş bin Türk lirasına kadar, gerçek veya tüzel kişilere iki bin beş yüz Türk lirasından yirmi beş bin Türk lirasına kadar (...). Aynı kabahatin tekrarında idarî para cezaları iki katı olarak uygulanır ve kira sözleşmeleri iptal edilir. e) 13 üncü maddenin birinci fıkrasına aykırı (...) tesis sahiplerine on bin Türk lirasından yüz bin Türk lirasına kadar (...); doksan gün süre (...) devam etmesi durumunda ilk (...) ceza iki katı (...); otuz gün daha (...) devam (...) üç katı (...) ve tesisin mülki amir tarafından kapatılması. f) 17 nci maddeye dayanılarak (...) başkan ve yönetim kurulu üyelerine ayrı ayrı iki bin beş yüz Türk lirasından yirmi beş bin Türk lirasına kadar, gerçek veya tüzel kişilere iki bin beş yüz Türk lirasından yirmi beş bin Türk lirasına kadar (...). Aynı kabahatin tekrarı halinde idarî para cezaları iki katı olarak uygulanır ve kira sözleşmeleri iptal edilir. j) (ikinci paragraf) 22 nci maddenin ikinci fıkrasındaki balık geçidini yapmayanlara (...) su yapısının niteliği dikkate alınarak on sekiz ayı geçmemek üzere yeterli süre verilir. (...) giderilmemesi halinde, yüz bin Türk lirasından iki yüz elli bin Türk lirasına kadar idarî para cezası verilir. Müteakip kontrollerde de aynı yöntem uygulanır ve (...) bir önce uygulanan idarî para cezası iki katı olarak uygulanır.",
  "Su Ürünleri m.Ek 3": "36 ncı maddede yer alan idarî para cezaları mahallin en büyük mülki amiri ile Sahil Güvenlik Komutanlığının yetki ve sorumluluk alanlarında Sahil Güvenlik Komutanlığı tarafından görevlendirilen personel tarafından uygulanır. Mülki amirler idarî para cezası verme yetkilerini 33 üncü maddede belirtilen görevlilere devredebilir. Vali mülkiyetin kamuya geçirilmesi yetkisini ildeki mülki idare amirlerinden birine veya Tarım ve Orman Bakanlığı il müdürüne devredebilir. (...) İdarî yaptırımlara karşı tebliğ tarihinden itibaren onbeş gün içerisinde yetkili idare mahkemesinde dava açılabilir. Bu Kanuna göre verilen idarî para cezaları tebliğ tarihinden itibaren bir ay içinde ödenir.",
  "Suç Eşyası Yön m.10": "MADDE 10 – (1) Cumhuriyet başsavcılığı, emanet bürosuna tevdi edilen eşyadan, kıymetli maden veya taşlardan mamul, antika ve sair vasıfları dolayısıyla fazla değerde oldukları bilirkişi tarafından tespit olunanlar, (...) emre veya hâmile yazılı kambiyo senetleri, (...) hisse senetleri, tahviller (...) ait tutanakların, emanet bürosunda mevcut kasada iyi bir şekilde muhafazası için gereken tedbirleri alır. Bu maksatla bankada kasa kiralamak zorunluluğu doğarsa durum derhâl Adalet Bakanlığına bildirilir (...). Her iki hâlde de emanet bürosunca kasaya giren ve kasadan çıkan eşya için (...) bir defter tutulur. Bu defter kasa içerisinde durur, kasa en az iki kişi tarafından açılır, kapanır. Bu göreve emanet memurundan başka kimin katılacağı Cumhuriyet başsavcılığınca tayin edilir. (2) Fikri ve sınai mülkiyet hukuku kapsamında işlenen suçlar sebebiyle elkonulan CD, DVD, giyim ve kitap gibi suç eşyasının sayı ve ebatları nedeniyle emanet bürosunda muhafaza edilemeyecek olması hâlinde, (...) yeteri kadar numune alınmasına müteakip geri kalan suç eşyası mahallin en büyük mal memurluğuna gönderilir. (3) (...) bozulacak veya değerlerini açık bir şekilde kaybedecek olan yahut nitelik, ebat ve sayı itibarıyla muhafazaları zor olması nedeniyle saklanması mümkün olmayan eşya hakkında; (...) soruşturma evresinde hâkimden ve kovuşturma evresinde yargılamayı yapan mahkemeden; soruşturma veya kovuşturma sonu beklenmeksizin satılmalarına veya 18 nci maddede yazılı mercilerden birine (...) teslim edilmelerine karar verilmesi istenir.",
  "Suç Eşyası Yön m.11": "(2) 10/7/1953 tarihli ve 6136 sayılı Ateşli Silâhlar ve Bıçaklar ile Diğer Aletler Hakkında Kanun kapsamına giren ve elkonulan ateşli silâhlar ve miktar itibarıyla emanet bürolarında muhafazası Cumhuriyet başsavcılığınca sakıncalı görülen bu silâhlara ait mermilerle her türlü patlayıcı maddeler, (...) soruşturma sırasında Cumhuriyet savcısı tarafından bilirkişi marifetiyle belirlendikten (...) sonra, mahkemece haklarında bir karar verilinceye kadar Cumhuriyet başsavcılığının yazılı emri ile mahallî jandarma birlik komutanlıklarına ait mahfuz bina ve depolarda muhafaza altına alınırlar. (...) jandarma birlik komutanlığına ait bina ve depolarında görevli adli emanet depo sorumlusu (...) tutanakla derhâl teslim edilir. Bu tutanak üç nüsha olarak düzenlenir. (...)",
  "Suç Eşyası Yön m.12": "(2) Elkonulan kara, deniz ve hava araçlarının, emanet bürosuna girişi ve bu konu ile ilgili kayıt işlemleri, 6 ncı madde gereğince yapıldıktan sonra, mahallin en büyük mal memurluğuna, ilgili mahkemelerce ve Cumhuriyet başsavcılıklarınca yazılı olarak istendiğinde iade edilmek üzere, tüm bilgileri içeren bir tutanakla derhâl teslim edilir. Bu tutanak üç nüsha olarak düzenlenir. Bir nüshası teslim alana verilir, diğer nüshalarından biri emanet bürosunda, biri de Cumhuriyet başsavcılığında saklanır. (...)",
  "Suç Eşyası Yön m.16": "MADDE 16 – (1) Cumhuriyet savcısı, hâkim veya mahkeme tarafından emanet eşyasının iadesine veya elden çıkarılmasına ilişkin verilen kararlar, dosyadaki emanet makbuzu ile birlikte en geç iki gün içerisinde Cumhuriyet başsavcılığına tevdi edilir. (...) (4) Emanet memuru, bu kararların tarih ve numaraları ile niteliklerini suç eşyası esas kaydındaki özel sütunlarına işler ve kararları kartonlarında saklar.\" · \"MADDE 17 – (1) Mahkemelerce, emanet eşyasının müsaderesine veya sahibine iadesine ilişkin kesinleşen karar örneklerinden biri, dosyadaki emanet makbuzu ve kesinleşme şerhi ile birlikte bir hafta içerisinde UYAP'tan Cumhuriyet başsavcılığına gönderilir. (2) Mahkemelerce verilecek müsadere ve iade kararlarında emanet eşyanın vasfı ve emanet numarasının belirtilmesi zorunludur.",
  "Suç Eşyası Yön m.18": "a) Sahibine iadesine karar verilen eşya, kimliğini ispatlamaya yeterli bir belgeye dayanılarak suç eşyası esas kaydındaki hanesine işaret olunarak imza, mühür veya parmak izi alınmak suretiyle sahibine, yasal temsilcisine veya vekiline teslim ve tesellüm tutanağı ile teslim olunur. b) Bu işlemler, Cumhuriyet savcısının huzurunda yerine getirilir ve düzenlenen teslim ve tesellüm tutanağına Cumhuriyet savcısı ve emanet memurunun imzaları ile şerh verilir. (...) e) Müsadere konusu eşya veya maddî menfaatlere elkonulamadığı veya merciine teslim edilemediği hâllerde, bunların karşılığını oluşturan değerlerin müsaderesine ilişkin verilen kesinleşmiş karar örneği mahkemesince doğrudan bulunduğu yerin en büyük mal memurluğuna gönderilir. Bu kararların infazı, 21/7/1953 tarihli ve 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun hükümlerine göre yapılır.",
  "Suç Eşyası Yön m.20": "a) Emanet memuru, emanet bürosuna teslimi tarihinden itibaren bir yıl içerisinde, hakkında herhangi bir karar verilmemiş olan eşya veya paraları, ilgili mahkemeden sorulmak üzere, Cumhuriyet başsavcılığı soruşturma veya esas kaydı sayısını ihtiva eden bir yazı ile Cumhuriyet başsavcılığına bildirir. Mahkeme veya daire yazı işleri müdürü ile Cumhuriyet başsavcılığı yazı işleri müdürü en geç on beş gün içinde bu eşya ve paraların ilgili bulundukları iş veya davaların karara bağlanıp bağlanmadıklarını, hakkında bir karar verilmiş ise, kararın bir suretini de eklemek suretiyle aynı yoldan durumu emanet bürosuna bildirirler.",
  "Suç Eşyası Yön m.21": "(1) İadesine karar verilmiş olup usulüne uygun meşruhatlı tebligata rağmen sahipleri tarafından bir ay içinde alınmayan veya kendilerine tebligat yapılamayan kimselere ait eşya en geç iki ay içerisinde satılarak bedeli millî bankalardan birinde ilgilisi adına açılacak vadeli hesaba yatırılır. Satışa karar verecek merci suç eşyasının bulunduğu yer sulh ceza hâkimidir. (3) Satılacak suç eşyasının değerinin, satış masraflarını karşılamayacağının belli olması hâlinde, satışa karar veren hâkimin kararı üzerine 24 üncü madde uyarınca işlem yapılır. (4) Teslim alınmayan kıymetli evrakın ilgili kanunlardaki zamanaşımı süresince emanet bürosunda muhafazasına devam olunur.",
  "Suç Eşyası Yön m.24": "(1) İadesine karar verilmiş olup da mahkeme kararı kendilerine tebliğ edildiği hâlde sahipleri tarafından 21 inci maddede yazılı süre içerisinde alınmayan ve ekonomik değeri bulunmayan eşyanın, Cumhuriyet savcısı başkanlığında, emanet memuru ve bir zabıt kâtibinden oluşan komisyonca imhasına karar verilir. İmha, komisyon huzurunda yapılır ve buna dair bir tutanak tanzim olunur. (2) Birinci fıkrada belirtilen imha komisyonuna hangi zabıt kâtibinin katılacağı, adalet komisyonlarınca, bulunmayan yerlerde kıdemli hâkim tarafından belirlenir.",
  "Suç Eşyası Yön m.25": "(1) Emanet bürosunda aşağıda belirtilen kayıtların UYAP'ta tutulması zorunludur: a) Suç eşyası esas kaydı, b) Kasa kaydı, c) Muhabere kaydı, ç) Zimmet kaydı, d) Kıymetli eşya kaydı. (...) (4) Bu kayıtlar UYAP'a emanet memuru tarafından güvenli elektronik imza ile onaylanarak işlenir.",
  "Suç Eşyası Yön m.3": "ı) Suç eşyası: İspat aracı olarak yararlı görülen, suçta kullanılan veya suçun işlenmesine tahsis edilen ya da suçun işlenmesinde kullanılmak üzere hazırlanan, suçtan meydana gelen ya da üretimi, bulundurulması, kullanılması, taşınması, alım ve satımı suç oluşturan eşyayı, (...) ğ) Kazanç: Suçun işlenmesi ile elde edilen veya suçun konusunu oluşturan ya da suçun işlenmesi için sağlanan maddî menfaatler ile bunların değerlendirilmesi veya dönüştürülmesi sonucu ortaya çıkan yahut bunların karşılığını oluşturan ekonomik malvarlığı değerlerini, (...) ifade eder.",
  "Suç Eşyası Yön m.4": "(1) Suç eşyası ile ilgili işlemler, Cumhuriyet başsavcılığının sürekli gözetim ve denetimi altında emanet bürosunca yürütülür. (2) Cumhuriyet başsavcılığı nezdinde bir emanet bürosu bulunur. Emanet bürosunda emanet memuru görev yapar. Emanet memurunun atanmasına lüzum görülmeyen hâllerde bu görev, ilgili yer Cumhuriyet başsavcısının teklifi üzerine adalet komisyonunca, adalet komisyonu bulunmayan yerlerde bu yer Cumhuriyet başsavcısınca belirlenecek yazı işleri müdürü veya zabıt kâtiplerinden birine geçici olarak verilir. (...)\n\n(4) Adalet dairelerinin bulunduğu binalarda suç eşyasının muhafazası maksadıyla, mümkün ise penceresiz, değil ise dışarıdan sökülemeyecek biçimde demir parmaklıklı pencereli, çift kilitli çelik ya da demir kapılı, rutubet almayan, havalandırması süreklilik arz eden ve yangına karşı her türlü tedbirin alındığı muhkem bir yer tahsis edilir. Bu yerler kamera sistemi ile kontrol edilir. (5) Devlet sırrı niteliğindeki bilgileri içeren belge, CD, DVD, harici bellek ve benzeri aygıtlar yüksek güvenlikli kasada saklanır.",
  "Suç Eşyası Yön m.5": "(1) İspat aracı olarak yararlı görülen ya da eşya veya kazanç müsaderesinin konusunu oluşturan malvarlığı değerleri, muhafaza altına alınır. Yanında bulunduran kişinin rızasıyla teslim etmediği bu tür eşyaya elkonulabilir. (2) Hâkim kararı üzerine veya gecikmesinde sakınca bulunan hâllerde Cumhuriyet savcısının, Cumhuriyet savcısına ulaşılamadığı hâllerde ise kolluk amirinin yazılı emri ile elkoyma işlemini yapan kolluk görevlilerince, suç eşyasına elkonulduğuna dair bir tutanak düzenlenir.\n\n(5) Hâkim kararı olmaksızın yapılan elkoyma işlemi yirmi dört saat içinde görevli hâkimin onayına sunulur. Hâkim, kararını elkoymadan itibaren kırk sekiz saat içinde açıklar; aksi hâlde elkoyma kendiliğinden kalkar. Elkonulan eşyanın bu süre içerisinde muhafazası için gerekli tedbirler, Cumhuriyet başsavcılığınca alınır.\n\n(6) Elkoyma işlemi, suçtan zarar gören mağdura Cumhuriyet başsavcılığınca gecikmeksizin bildirilir. (...) (9) Zilyetliğinde bulunan eşya veya diğer malvarlığı değerlerine elkonulan kimse, hâkimden her zaman elkoymanın kaldırılması konusunda bir karar verilmesini isteyebilir.",
  "Suç Eşyası Yön m.7": "(1) Emanet memuru, 5 inci maddedeki usule göre ambalajlanmamış veya mühürlenmemiş olan suç eşyasını teslim alamaz.",
  "Suç Eşyası Yön m.8": "(1) Emanet bürosunda muhafaza altına alınan suç eşyasının; vasfının, maddî değerinin ve delil oluşturan özelliklerinin tamamen veya kısmen kaybının engellenmesi, böylece hak kayıplarının önüne geçilmesi ve delil değeri taşıyan olguların kaybının önlenmesi amacıyla, nitelik ve yıllarına göre tasnifinin yapılması ve buna uygun şekilde muhafaza edilmesi sağlanır. (2) Emanet memuru, büronun imkânları ölçüsünde suç eşyasının depoda muhafaza edildiği yeri, sırayı, rafı, depoya giriş ve çıkış tarihleri de dâhil olmak üzere yapılan tüm işlemleri gösterir şekilde barkod sistemiyle kaydeder ve buna göre yerleştirir. (3) Bilgisayar, bilgisayar kütükleri ve bu sisteme ilişkin verilerin asıl ya da kopyaları, ses ve görüntü kayıtlarının bulunduğu depolama aygıtları gibi elektronik eşya, bozulmalarını engelleyecek, nem, ısı, manyetik alan ve darbelerden korunmalarını sağlayacak müstakil uygun alanlarda muhafaza edilir. (4) 11 inci maddenin ikinci fıkrası kapsamı dışında kalan ve emanete kabul edilebilecek olan kimyasal ve biyolojik eşya için müstakil alanların oluşturulması sağlanır.",
  "Suç Eşyası Yön m.9": "(1) Emanet memuru, mahkeme ve diğer resmî daireler tarafından incelenmek üzere UYAP üzerinden veya yazılı olarak istenilen suç eşyasını, üzerindeki etiketlerde yazılı bilgiyi kapsayan bir yazı ile isteyen makama, Cumhuriyet savcısının onayıyla zimmet kaydına görevlinin imzasını almak suretiyle teslim eder ve teslim işlemini suç eşyası kaydına derhâl kaydeder. Mahkemelerin ve Cumhuriyet başsavcılıklarının isteklerini UYAP üzerinden güvenli elektronik imzalı olarak yapmaları zorunludur.\n\n(4) İade edilmeyen suç eşyasının iade edilmeme sebebi, ilgili merciden üçer aylık fasılalarla sorulur.",
  "TCK m.1": "(1) Ceza Kanununun amacı; kişi hak ve özgürlüklerini, kamu düzen ve güvenliğini, hukuk devletini, kamu sağlığını ve çevreyi, toplum barışını korumak, suç işlenmesini önlemektir. Kanunda, bu amacın gerçekleştirilmesi için ceza sorumluluğunun temel esasları ile suçlar, ceza ve güvenlik tedbirlerinin türleri düzenlenmiştir.",
  "TCK m.102": "Cinsel davranışla vücut dokunulmazlığını ihlal → şikâyete bağlı 5–10 yıl; sarkıntılık düzeyinde 2–5 yıl. (2) Organ veya sair cisim sokulması → en az 12 yıl (eşe karşı şikâyete bağlı). (3) Nitelikli haller (savunamayacak kişi, kamu görevi/hizmet nüfuzu, 3. dereceye kadar hısım/üvey-evlatlık, silahla/birden fazla kişi, toplu yaşam ortamı kolaylığı) → ceza yarı oranında artar. (4) Cebir/şiddet ağır yaralama neticesi → ayrıca yaralama hükümleri. (5) Ölüm/bitkisel hayat → ağırlaştırılmış müebbet. *(Kaynak satır 893-920)*",
  "TCK m.103": "Çocuğu cinsel istismar → 8–15 yıl; sarkıntılık → 3–8 yıl. 12 yaşını tamamlamamış mağdurda ceza istismarda ≥10 yıl, sarkıntılıkta ≥5 yıl. (2) Organ/sair cisim sokma → ≥16 yıl; 12 yaş altı → ≥18 yıl. İstismar tanımı: 15 yaşını bitirmemiş veya algısı gelişmemiş çocuğa karşı her türlü cinsel davranış (rıza aranmaz); diğer çocuklarda cebir/tehdit/hile/iradeyi etkileyen neden gerekir. (3) Nitelikli haller (birden fazla kişi, toplu yaşam, hısım/üvey, vasi-eğitici-bakıcı-koruyucu/sağlık görevlisi, kamu/hizmet nüfuzu) → ½ artar. (4) cebir/tehdit/silah → ½ artar. (6) Ölüm/bitkisel hayat → ağırlaştırılmış müebbet. *(Kaynak satır 923-969)*",
  "TCK m.104": "Cebir-tehdit-hile OLMAKSIZIN 15 yaşını bitirmiş çocukla cinsel ilişki → şikâyet üzerine 2–5 yıl. (2) Mağdurla evlenme yasağı bulunan kişi işlerse → şikâyet aranmaz, 10–15 yıl. (3) Evlat edinme öncesi bakımı üstlenen/koruyucu aile işlerse → şikâyet aranmaz, ikinci fıkra cezası. *(Cebir/tehdit/hile varsa veya 15 yaş altıysa m.103 uygulanır.)* *(Kaynak satır 972-984)*",
  "TCK m.105": "Bir kimseyi cinsel amaçlı (temassız) taciz → şikâyet üzerine 3 ay–2 yıl hapis veya adli para; çocuğa karşı 6 ay–3 yıl. (2) Nitelikli haller (kamu/hizmet/aile içi ilişki, vasi-eğitici-bakıcı-koruyucu/sağlık görevlisi, aynı işyeri, posta/elektronik haberleşme, teşhir) → ceza ½ artar; mağdur işi/okulu/ailesini bırakmak zorunda kalmışsa ceza 1 yıldan az olamaz. *(Vücuda dokunma olursa m.102.)* *(Kaynak satır 987-1005)*",
  "TCK m.106": "Kişinin/yakınının hayatına, vücut veya cinsel dokunulmazlığına saldırı tehdidi → 6 ay–2 yıl (kadına karşı alt sınır 9 aydan az olamaz). Malvarlığına büyük zarar veya sair kötülük tehdidi → şikâyete bağlı, 2–6 ay hapis veya adli para. (2) Silahla, kendini tanınmaz hale koyarak/imzasız mektup/özel işaret, birden fazla kişi, suç örgütünün korkutucu gücüyle → 2–7 yıl. (3) Tehdit amacıyla öldürme/yaralama/mala zarar işlenirse ayrıca ceza. *(Kaynak satır 1009-1029)*",
  "TCK m.107": "Hakkı olan veya yükümlü olduğu bir şeyi yapacağından/yapmayacağından bahisle, bir kimseyi kanuna aykırı/yükümlü olmadığı bir şeyi yapmaya-yapmamaya ya da haksız çıkar sağlamaya zorlama → 1–3 yıl hapis + 5.000 güne kadar adli para. (2) Kişinin şeref/saygınlığına zarar verecek hususların açıklanacağı/isnat edileceği tehdidi de şantajdır (aynı ceza). *(Kaynak satır 1032-1041)*",
  "TCK m.108": "Bir şeyi yapması/yapmaması ya da yapılmasına müsaade etmesi için bir kişiye karşı cebir (fiziksel zor) kullanılması → kasten yaralama suçundan verilecek ceza üçte birinden yarısına kadar artırılarak hükmolunur (cebrin ayrı sabit cezası yoktur). *(Tehditten farkı: tehdit söz/gelecek, cebir fiziksel zor/şimdi.)* *(Kaynak satır 1044-1048)*",
  "TCK m.109": "Bir kimseyi hukuka aykırı olarak gitme/kalma hürriyetinden yoksun bırakma → 1–5 yıl. (2) Fiili işlemek için/sırasında cebir, tehdit veya hile → 2–7 yıl. (3) Silahla, birden fazla kişi, kamu görevi nedeniyle, kamu nüfuzunu kötüye kullanma, üstsoy-altsoy-eş/boşandığı eş, çocuğa ya da savunamayacak kişiye karşı → ceza bir kat artar. (4) Mağdurun önemli ekonomik kaybı → ayrıca 1.000 güne kadar adli para. (5) Cinsel amaçla işlenirse ceza ½ artar. (m.110 Etkin pişmanlık): Soruşturmaya başlanmadan önce, mağdurun şahsına zarar dokunmaksızın onu kendiliğinden güvenli yerde serbest bırakırsa ceza ⅔'e kadar indirilir. *(Kaynak satır 1051-1080)*",
  "TCK m.112": "m.111 Tehdit/şantaj/cebir/hürriyetten yoksun kılmadan yarar sağlayan tüzel kişilere güvenlik tedbiri. m.112 Cebir/tehdit ya da hukuka aykırı davranışla eğitim-öğretim hakkının engellenmesi → 2-5 yıl. m.113 Kamu hizmetlerinden yararlanma hakkının engellenmesi → 2-5 yıl (konu sağlık hizmeti ise 1/6'ya kadar artar). m.114 Cebir/tehditle siyasi hakları engelleme → 1-3 yıl; parti faaliyetini engelleme → 2-5 yıl. m.115 İnanç/düşünce/kanaat hürriyetini engelleme → 1-3 yıl (dini ibadet/ayin engellemede de aynı). *(Kaynak satır 1084-1144)*",
  "TCK m.116": "Bir kimsenin konutuna/eklentilerine rızaya aykırı girme veya rıza ile girip çıkmama → şikâyete bağlı 6 ay–2 yıl. (2) Açık rıza gerektiren işyeri ve eklentilerinde → şikâyete bağlı 6 ay–1 yıl hapis veya adli para. (3) Aile bireyleri veya ortak kullananlardan birinin (meşru amaçlı) rızası varsa suç oluşmaz. (4) Cebir/tehditle veya gece vakti → 1–3 yıl. *(Kaynak satır 1147-1163)*",
  "TCK m.117": "Cebir/tehdit ya da hukuka aykırı davranışla iş ve çalışma hürriyetini ihlal → şikâyete bağlı 6 ay–2 yıl hapis veya adli para. (2) Çaresizlik/kimsesizlik/bağlılığı sömürerek ücretsiz veya orantısız düşük ücretle çalıştırma ya da insan onuruyla bağdaşmaz koşullara tabi kılma → 6 ay–3 yıl + en az 100 gün adli para. (3) Bu duruma düşürmek üzere tedarik/sevk/nakil → aynı ceza. (4) Cebir/tehditle ücret-koşul anlaşmasına zorlama veya işi durdurma → 6 ay–3 yıl. (m.119 Ortak nitelikli): m.112-117 (eğitim, kamu hizmeti, siyasi/inanç hürriyeti, konut dokunulmazlığı, iş ve çalışma hürriyeti) suçları silahla, kimliği gizleyerek/imzasız mektup-özel işaret, birden fazla kişi, suç örgütü gücüyle, kamu nüfuzu kötüye kullanılarak işlenirse ceza bir kat artar; bu suçlar sırasında kasten yaralamanın ağır neticesi → ayrıca yaralama hükümleri. *(Tehdit/şantaj m.119 kapsamında DEĞİL.)* *(Kaynak satır 1166-1214)*",
  "TCK m.118": "Bir sendikaya üye olmaya/olmamaya, faaliyetlerine katılmaya/katılmamaya ya da sendikadan/görevinden ayrılmaya cebir/tehditle zorlama → 6 ay-2 yıl. (2) Cebir/tehdit ya da hukuka aykırı davranışla sendika faaliyetini engelleme → 1-3 yıl. *(Kaynak satır 1187-1195)*",
  "TCK m.120": "Hukuka aykırı olarak bir kimsenin üstünü veya eşyasını arayan kamu görevlisine → 3 ay–1 yıl hapis. (Özgü suç: fail yalnız kamu görevlisidir; arama yetkisi/kararı olmaksızın yapılan arama suç oluşturur.) *(Kaynak satır 1217-1219)*",
  "TCK m.121": "m.121 Kişinin bir hakkı kullanmak için yetkili makama verdiği dilekçenin hukuki neden olmaksızın kabul edilmemesi → 6 aya kadar hapis. m.124 (1) Kişiler arasındaki haberleşmenin hukuka aykırı engellenmesi → 6 ay-2 yıl hapis veya adlî para. (2) Kamu kurumları arasındaki haberleşmeyi engelleme → 1-5 yıl. (3) Basın-yayın organının yayınını engelleme → 1-5 yıl. *(Kaynak satır 1222-1274)*",
  "TCK m.122": "(Değişik: 2/3/2014-6529/15 md.) Dil, ırk, milliyet, renk, cinsiyet, engellilik, siyasi düşünce, felsefi inanç, din veya mezhep farklılığından kaynaklanan nefret nedeniyle; (a) kamuya arz edilmiş taşınır/taşınmaz malın bir kişiye satılmasını, devrini veya kiraya verilmesini, (b) bir kişinin kamuya arz edilmiş belli bir hizmetten yararlanmasını, (c) bir kişinin işe alınmasını, (d) bir kişinin olağan bir ekonomik etkinlikte bulunmasını engelleyen kimseye → 1 yıldan 3 yıla kadar hapis. *(Kaynak satır 1228-1240)*",
  "TCK m.123": "m.123 Sırf huzur ve sükûnunu bozmak maksadıyla bir kimseye ısrarla telefon, gürültü ya da aynı maksatla hukuka aykırı davranış → mağdurun şikâyeti üzerine 3 ay-1 yıl. m.123/A (Ek:12/5/2022-7406) Israrla fiziken takip ya da haberleşme/iletişim araçları, bilişim sistemleri veya üçüncü kişilerle temas kurmaya çalışarak ciddi huzursuzluk/güvenlik endişesi oluşturma → 6 ay-2 yıl. (2) Çocuğa/ayrılık-boşandığı eşe; okul-iş-konut değiştirtme/bıraktırma; uzaklaştırma tedbirli fail → 1-3 yıl. (3) Şikâyete bağlı. *(Kaynak satır 1241-1264)*",
  "TCK m.125": "(1) Bir kimseye onur, şeref ve saygınlığını rencide edebilecek nitelikte somut bir fiil veya olgu isnat eden (...) veya sövmek suretiyle bir kimsenin onur, şeref ve saygınlığına saldıran kişi, üç aydan iki yıla kadar hapis veya adlî para cezası ile cezalandırılır. Mağdurun gıyabında hakaretin cezalandırılabilmesi için fiilin en az üç kişiyle ihtilat ederek işlenmesi gerekir. (2) Fiilin, mağduru muhatap alan sesli, yazılı veya görüntülü bir iletiyle işlenmesi halinde, yukarıdaki fıkrada belirtilen cezaya hükmolunur. (3) Hakaret suçunun; a) Kamu görevlisine karşı görevinden dolayı, b) Dini, siyasi, sosyal, felsefi inanç (...) dolayı, c) Kişinin mensup bulunduğu dine göre kutsal sayılan değerlerden bahisle, İşlenmesi halinde, cezanın alt sınırı bir yıldan az olamaz. (4) Hakaretin alenen işlenmesi halinde ceza altıda biri oranında artırılır. (5) Kurul hâlinde çalışan kamu görevlilerine görevlerinden dolayı hakaret edilmesi hâlinde suç, kurulu oluşturan üyelere karşı işlenmiş sayılır (...).",
  "TCK m.126": "(1) Hakaret suçunun işlenmesinde mağdurun ismi açıkça belirtilmemiş veya isnat üstü kapalı geçiştirilmiş olsa bile, eğer niteliğinde ve mağdurun şahsına yönelik bulunduğunda duraksanmayacak bir durum varsa, hem ismi belirtilmiş ve hem de hakaret açıklanmış sayılır.",
  "TCK m.127": "(1) İsnat edilen ve suç oluşturan fiilin ispat edilmiş olması halinde kişiye ceza verilmez. Bu suç nedeniyle hakaret edilen hakkında kesinleşmiş bir mahkûmiyet kararı verilmesi halinde, isnat ispatlanmış sayılır. Bunun dışındaki hallerde isnadın ispat isteminin kabulü, ancak isnat olunan fiilin doğru olup olmadığının anlaşılmasında kamu yararı bulunmasına veya şikayetçinin ispata razı olmasına bağlıdır. (2) İspat edilmiş fiilinden söz edilerek kişiye hakaret edilmesi halinde, cezaya hükmedilir.",
  "TCK m.128": "(1) Yargı mercileri veya idari makamlar nezdinde yapılan yazılı veya sözlü başvuru, iddia ve savunmalar kapsamında, kişilerle ilgili olarak somut isnadlarda ya da olumsuz değerlendirmelerde bulunulması halinde, ceza verilmez. Ancak, bunun için isnat ve değerlendirmelerin, gerçek ve somut vakıalara dayanması ve uyuşmazlıkla bağlantılı olması gerekir.",
  "TCK m.129": "(1) Hakaret suçunun haksız bir fiile tepki olarak işlenmesi halinde, verilecek ceza üçte birine kadar indirilebileceği gibi, ceza vermekten de vazgeçilebilir. (2) Bu suçun, kasten yaralama suçuna tepki olarak işlenmesi halinde, kişiye ceza verilmez. (3) Hakaret suçunun karşılıklı olarak işlenmesi halinde, olayın mahiyetine göre, taraflardan her ikisi veya biri hakkında verilecek ceza üçte birine kadar indirilebileceği gibi, ceza vermekten de vazgeçilebilir.",
  "TCK m.130": "(1) Bir kimsenin öldükten sonra hatırasına en az üç kişiyle ihtilat ederek hakaret eden kişi, üç aydan iki yıla kadar hapis veya adlî para cezası ile cezalandırılır. Ceza, hakaretin alenen işlenmesi halinde, altıda biri oranında artırılır. (2) Bir ölünün kısmen veya tamamen ceset veya kemiklerini alan veya ceset veya kemikler hakkında tahkir edici fiillerde bulunan kişi, üç aydan iki yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.132": "(1) Kişiler arasındaki haberleşmenin gizliliğini ihlal eden kimse, bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Bu gizlilik ihlali haberleşme içeriklerinin kaydı suretiyle gerçekleşirse, verilecek ceza bir kat artırılır. (2) Kişiler arasındaki haberleşme içeriklerini hukuka aykırı olarak ifşa eden kimse, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. (3) Kendisiyle yapılan haberleşmelerin içeriğini diğer tarafın rızası olmaksızın hukuka aykırı olarak alenen ifşa eden kişi, bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. İfşa edilen bu verilerin basın ve yayın yoluyla yayımlanması halinde de aynı cezaya hükmolunur.",
  "TCK m.133": "(1) Kişiler arasındaki aleni olmayan konuşmaları, taraflardan herhangi birinin rızası olmaksızın bir aletle dinleyen veya bunları bir ses alma cihazı ile kaydeden kişi, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. (2) Katıldığı aleni olmayan bir söyleşiyi, diğer konuşanların rızası olmadan ses alma cihazı ile kayda alan kişi, altı aydan iki yıla kadar hapis veya adlî para cezası ile cezalandırılır. (3) Kişiler arasındaki aleni olmayan konuşmaların kaydedilmesi suretiyle elde edilen verileri hukuka aykırı olarak ifşa eden kişi, iki yıldan beş yıla kadar hapis ve dörtbin güne kadar adlî para cezası ile cezalandırılır. İfşa edilen bu verilerin basın ve yayın yoluyla yayımlanması halinde de aynı cezaya hükmolunur.",
  "TCK m.134": "(1) Kişilerin özel hayatının gizliliğini ihlal eden kimse, bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Gizliliğin görüntü veya seslerin kayda alınması suretiyle ihlal edilmesi halinde, verilecek ceza bir kat artırılır. (2) Kişilerin özel hayatına ilişkin görüntü veya sesleri hukuka aykırı olarak ifşa eden kimse iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. İfşa edilen bu verilerin basın ve yayın yoluyla yayımlanması halinde de aynı cezaya hükmolunur.",
  "TCK m.135": "**m.135** (1) Hukuka aykırı olarak kişisel verileri kaydeden kimseye bir yıldan üç yıla kadar hapis cezası verilir. (2) Kişisel verinin, kişilerin siyasi, felsefi veya dini görüşlerine, ırki kökenlerine; (...) cinsel yaşamlarına, sağlık durumlarına veya sendikal bağlantılarına ilişkin olması durumunda (...) ceza yarı oranında artırılır. — **m.136** (1) Kişisel verileri, hukuka aykırı olarak bir başkasına veren, yayan veya ele geçiren kişi, iki yıldan dört yıla kadar hapis cezası ile cezalandırılır. (2) Suçun konusunun, Ceza Muhakemesi Kanununun 236 ncı maddesinin beşinci ve altıncı fıkraları uyarınca kayda alınan beyan ve görüntüler olması durumunda verilecek ceza bir kat artırılır. — **m.138** (1) Kanunların belirlediği sürelerin geçmiş olmasına karşın verileri sistem içinde yok etmekle yükümlü olanlara görevlerini yerine getirmediklerinde bir yıldan iki yıla kadar hapis cezası verilir. (2) Suçun konusunun Ceza Muhakemesi Kanunu hükümlerine göre ortadan kaldırılması veya yok edilmesi gereken veri olması hâlinde verilecek ceza bir kat artırılır.",
  "TCK m.141": "**m.141** (1) Zilyedinin rızası olmadan başkasına ait taşınır bir malı, kendisine veya başkasına bir yarar sağlamak maksadıyla bulunduğu yerden alan kimseye bir yıldan üç yıla kadar hapis cezası verilir. — **m.142** (1) Hırsızlık suçunun; kamu kurumlarında/ibadete ayrılmış yerlerde bulunan eşya, ulaşım aracı içindeki eşya, afet için hazırlanan eşya, açıkta bırakılmış eşya hakkında işlenmesi hâlinde **üç yıldan yedi yıla** kadar hapis. (2) Suçun; malını koruyamayacak durumdakine/ölmüşten yararlanarak, kapkaç/özel beceriyle, doğal afet-kargaşadan yararlanarak, taklit anahtar/aletle kilit açarak, bilişim sistemiyle, resmî sıfat takınarak, hayvan hakkında, kilitli/bina içinde muhafaza altındaki eşya hakkında işlenmesi hâlinde **beş yıldan on yıla** kadar hapis (...). (3) Sıvı/gaz enerji ve tesisleri hakkında işlenmesi hâlinde **beş yıldan oniki yıla** kadar hapis (...). — **m.143** (1) Hırsızlık suçunun gece vakti işlenmesi halinde, verilecek ceza yarı oranında artırılır.",
  "TCK m.144": "**m.144** (1) Hırsızlık suçunun; paydaş/elbirliği ile malik olunan mal üzerinde veya bir hukuki ilişkiye dayanan alacağı tahsil amacıyla işlenmesi halinde, şikayet üzerine, fail hakkında iki aydan bir yıla kadar hapis veya adlî para cezasına hükmolunur. — **m.145** (1) Hırsızlık suçunun konusunu oluşturan malın değerinin azlığı nedeniyle, verilecek cezada indirim yapılabileceği gibi, suçun işleniş şekli ve özellikleri de göz önünde bulundurularak, ceza vermekten de vazgeçilebilir. — **m.146** (1) Hırsızlık suçunun, malın geçici bir süre kullanılıp zilyedine iade edilmek üzere işlenmesi halinde, şikayet üzerine, verilecek ceza yarı oranına kadar indirilir. Ancak malın suç işlemek için kullanılmış olması halinde bu hüküm uygulanmaz. — **m.147** (1) Hırsızlık suçunun ağır ve acil bir ihtiyacı karşılamak için işlenmesi halinde, olayın özelliğine göre, verilecek cezada indirim yapılabileceği gibi, ceza vermekten de vazgeçilebilir.",
  "TCK m.148": "(1) Bir başkasını, kendisinin veya yakınının hayatına, vücut veya cinsel dokunulmazlığına yönelik bir saldırı gerçekleştireceğinden ya da malvarlığı itibarıyla büyük bir zarara uğratacağından bahisle tehdit ederek veya cebir kullanarak, bir malı teslime veya malın alınmasına karşı koymamaya mecbur kılan kişi, altı yıldan on yıla kadar hapis cezası ile cezalandırılır. (2) Cebir veya tehdit kullanılarak mağdurun (…) bir senedi (…) vermeye (…) mecbur edilmesi halinde de aynı ceza verilir. (3) Mağdurun, herhangi bir vasıta ile kendisini bilmeyecek ve savunamayacak hale getirilmesi de, yağma suçunda cebir sayılır.",
  "TCK m.149": "(1) Yağma suçunun; a) Silahla, b) Kişinin kendisini tanınmayacak bir hale koyması suretiyle, c) Birden fazla kişi tarafından birlikte, d) Yol kesmek suretiyle ya da konutta, işyerinde veya bunların eklentilerinde, e) Beden veya ruh bakımından kendisini savunamayacak durumda bulunan kişiye karşı, f) Var olan veya var sayılan suç örgütlerinin (…) korkutucu güçten yararlanılarak, g) Suç örgütüne yarar sağlamak maksadıyla, h) Gece vaktinde, İşlenmesi halinde, fail hakkında on yıldan onbeş yıla kadar hapis cezasına hükmolunur. (2) Yağma sırasında kasten yaralamanın neticesi sebebiyle ağırlaşmış halleri gerçekleşirse, ayrıca kasten yaralama hükümleri uygulanır.",
  "TCK m.150": "(1) Kişinin bir hukuki ilişkiye dayanan alacağını tahsil amacıyla tehdit veya cebir kullanması halinde, ancak tehdit veya kasten yaralama suçuna ilişkin hükümler uygulanır. (2) Yağma suçunun konusunu oluşturan malın değerinin azlığı nedeniyle, verilecek ceza üçte birden yarıya kadar indirilebilir.",
  "TCK m.151": "(1) Başkasının taşınır veya taşınmaz malını kısmen veya tamamen yıkan, tahrip eden, yok eden, bozan, kullanılamaz hale getiren veya kirleten kişi, mağdurun şikayeti üzerine, dört aydan üç yıla kadar hapis veya adlî para cezası ile cezalandırılır.",
  "TCK m.152": "(1) Mala zarar verme suçunun; a) Kamuya ait/kamu hizmetine tahsis edilmiş yer-bina-tesis-eşya hakkında, b) Felaketlere karşı korunmaya tahsis edilmiş eşya/tesis hakkında, c) (…) dikili ağaç-fidan-bağ çubuğu hakkında, d) Sulama-içme suyu-afet tesisleri hakkında, e-f) Sendika/siyasi parti/meslek kuruluşu malları hakkında, g) Görevinden ötürü öç almak amacıyla kamu görevlisinin zararına, İşlenmesi halinde, bir yıldan dört yıla kadar hapis cezasına hükmolunur. (2) Yakarak, yakıcı/patlayıcı madde ile; sel-çığ-taşkına neden olarak; radyasyon/nükleer-biyolojik-kimyasal silahla işlenirse ceza bir katına kadar artırılır. (3) Haberleşme-enerji-demiryolu-havayolu kamu hizmetinin aksaması halinde ceza yarısından iki katına kadar artırılır.",
  "TCK m.153": "(1) İbadethanelere, eklentilerine, buralardaki eşyaya, mezarlara, üzerindeki yapılara, mezarlıklardaki tesislere (…) yıkmak, bozmak veya kırmak suretiyle zarar veren kişi, bir yıldan dört yıla kadar hapis cezası ile cezalandırılır. (2) Bu yerleri ve yapıları kirleten kişi, üç aydan bir yıla kadar hapis veya adlî para cezası ile cezalandırılır. (3) Fiillerin ilgili dini inanışı benimseyen toplum kesimini tahkir maksadıyla işlenmesi halinde, ceza üçte biri oranında artırılır.",
  "TCK m.155": "(1) Başkasına ait olup da, muhafaza etmek veya belirli bir şekilde kullanmak üzere zilyedliği kendisine devredilmiş olan mal üzerinde, kendisinin veya başkasının yararına olarak, zilyedliğin devri amacı dışında tasarrufta bulunan veya bu devir olgusunu inkar eden kişi, şikayet üzerine, altı aydan iki yıla kadar hapis ve adlî para cezası ile cezalandırılır. (2) Suçun, meslek ve sanat, ticaret veya hizmet ilişkisinin ya da (…) başkasının mallarını idare etmek yetkisinin gereği olarak tevdi ve teslim edilmiş eşya hakkında işlenmesi halinde, bir yıldan yedi yıla kadar hapis ve üçbin güne kadar adlî para cezasına hükmolunur. (3) Suçun konusunun motorlu kara, deniz veya hava taşıtı olması halinde (…) ceza bir kat artırılır.",
  "TCK m.156": "(1) Bedelsiz kalmış bir senedi kullanan kimseye, şikayet üzerine, altı aydan iki yıla kadar hapis ve adlî para cezası verilir.",
  "TCK m.157": "(1) Hileli davranışlarla bir kimseyi aldatıp, onun veya başkasının zararına olarak, kendisine veya başkasına bir yarar sağlayan kişiye bir yıldan beş yıla kadar hapis ve beşbin güne kadar adlî para cezası verilir.",
  "TCK m.158": "(1) Dolandırıcılık suçunun; a) Dinî inanç ve duyguların istismarı, b) Tehlikeli durum/zor şartlardan yararlanma, c) Algılama zayıflığından yararlanma, d) Kamu kurumu/parti/vakıf/derneğin araç kılınması, e) Kamu kurumlarının zararına, f) Bilişim sistemi/banka-kredi kurumunun araç kılınması, g) Basın-yayın kolaylığından yararlanma, h) Tacir/şirket yöneticisi (…) ticari faaliyet sırasında, i) Serbest meslek sahibinin mesleğine duyulan güveni kötüye kullanması, j) Hak etmediği krediyi açtırma, k) Sigorta bedelini alma maksadıyla, l) Kendini kamu görevlisi/banka çalışanı olarak tanıtma suretiyle işlenmesi halinde, üç yıldan on yıla kadar hapis ve beşbin güne kadar adlî para cezası. Ancak (e),(f),(j),(k),(l) hâllerinde hapsin alt sınırı dört yıldan, adli para suçtan elde edilen menfaatin iki katından az olamaz.",
  "TCK m.159": "(1) Dolandırıcılığın, bir hukuki ilişkiye dayanan alacağı tahsil amacıyla işlenmesi halinde, şikayet üzerine, altı aydan bir yıla kadar hapis veya adlî para cezasına hükmolunur.",
  "TCK m.160": "(1) Kaybedilmiş olması nedeniyle malikinin zilyedliğinden çıkmış olan ya da hata sonucu ele geçirilen eşya üzerinde, iade etmeksizin veya yetkili mercileri durumdan haberdar etmeksizin, malik gibi tasarrufta bulunan kişi, şikayet üzerine, bir yıla kadar hapis veya adlî para cezası ile cezalandırılır.",
  "TCK m.163": "(1) Otomatlar aracılığı ile sunulan ve bedeli ödendiği takdirde yararlanılabilen bir hizmetten ödeme yapmadan yararlanan kişi, iki aydan altı aya kadar hapis veya adlî para cezası. (2) Telefon hatları/frekanslarından veya elektromanyetik dalgalarla yapılan şifreli/şifresiz yayınlardan sahibinin/zilyedinin rızası olmadan yararlanan kişi, altı aydan iki yıla kadar hapis veya adlî para cezası. (3) Abonelik esasına göre yararlanılan elektrik, su veya doğal gazın sahibinin rızası olmaksızın ve tüketim miktarının belirlenmesini engelleyecek şekilde tüketilmesi halinde, bir yıldan üç yıla kadar hapis cezası.",
  "TCK m.168": "(1) Hırsızlık, mala zarar verme, güveni kötüye kullanma, dolandırıcılık, hileli iflâs, taksirli iflâs (…) suçları tamamlandıktan sonra ve fakat bu nedenle hakkında kovuşturma başlamadan önce, failin, azmettirenin veya yardım edenin bizzat pişmanlık göstererek mağdurun uğradığı zararı aynen geri verme veya tazmin suretiyle tamamen gidermesi halinde, verilecek cezanın üçte ikisine kadarı indirilir. (2) Etkin pişmanlığın kovuşturma başladıktan sonra ve fakat hüküm verilmezden önce gösterilmesi halinde, verilecek cezanın yarısına kadarı indirilir. (3) Yağma suçundan dolayı etkin pişmanlık gösteren kişiye verilecek cezanın, birinci fıkraya giren hallerde yarısına, ikinci fıkraya giren hallerde üçte birine kadarı indirilir. (4) Kısmen geri verme/tazmin halinde, ayrıca mağdurun rızası aranır.",
  "TCK m.170": "(1) Kişilerin hayatı, sağlığı veya malvarlığı bakımından tehlikeli olacak biçimde ya da kişilerde korku, kaygı veya panik yaratabilecek tarzda; a) Yangın çıkaran, b) Bina çökmesine, toprak kaymasına, çığ düşmesine, sel veya taşkına neden olan, c) Silahla ateş eden veya patlayıcı madde kullanan, kişi, bir yıldan beş yıla kadar hapis cezası ile cezalandırılır. (…) Suçun ses ve gaz fişeği atabilen silahla ateş etmek suretiyle işlenmesi halinde kişi, altı aydan üç yıla kadar hapis cezası ile cezalandırılır. (2) (…) suçun kişilerin toplu olarak bulundukları yerlerde işlenmesi halinde, verilecek ceza yarı oranında artırılır. (3) Yangın, bina çökmesi, toprak kayması, çığ düşmesi, sel veya taşkın tehlikesine neden olan kişi, üç aydan bir yıla kadar hapis veya adlî para cezası ile cezalandırılır.",
  "TCK m.174": "(1) Yetkili makamlardan gerekli izni almaksızın, patlayıcı, yakıcı, aşındırıcı, yaralayıcı, boğucu, zehirleyici, sürekli hastalığa yol açıcı nükleer, radyoaktif, kimyasal, biyolojik maddeyi imal, ithal veya ihraç eden, ülke içinde bir yerden diğer bir yere nakleden, muhafaza eden, satan, satın alan veya işleyen kişi, dört yıldan sekiz yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır. (…) (2) Bu fiillerin suç işlemek için teşkil edilmiş bir örgütün faaliyeti çerçevesinde işlenmesi halinde, verilecek ceza bir kat artırılır. (3) Önemsiz tür ve miktarda patlayıcı maddeyi satın alan, kabul eden veya bulunduran kişi hakkında, kullanılış amacı gözetilerek, bir yıla kadar hapis cezasına hükmolunur.",
  "TCK m.179": "(1) Kara, deniz, hava veya demiryolu ulaşımının güven içinde akışını sağlamak için konulmuş her türlü işareti değiştirerek, kullanılamaz hale getirerek, konuldukları yerden kaldırarak, yanlış işaretler vererek, geçiş, varış, kalkış veya iniş yolları üzerine bir şey koyarak ya da teknik işletim sistemine müdahale ederek, başkalarının hayatı, sağlığı veya malvarlığı bakımından bir tehlikeye neden olan kişiye bir yıldan altı yıla kadar hapis cezası verilir. (2) Kara, deniz, hava veya demiryolu ulaşım araçlarını kişilerin hayat, sağlık veya malvarlığı açısından tehlikeli olabilecek şekilde sevk ve idare eden kişi, dört aydan iki yıla kadar hapis cezası ile cezalandırılır. (3) Alkol veya uyuşturucu madde etkisiyle ya da başka bir nedenle emniyetli bir şekilde araç sevk ve idare edemeyecek halde olmasına rağmen araç kullanan kişi altı aydan iki yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.188": "(1) Uyuşturucu veya uyarıcı maddeleri ruhsatsız veya ruhsata aykırı olarak imal, ithal veya ihraç eden kişi, yirmi yıldan otuz yıla kadar hapis ve ikibin günden yirmibin güne kadar adlî para cezası ile cezalandırılır. (…) (3) Uyuşturucu veya uyarıcı maddeleri ruhsatsız veya ruhsata aykırı olarak ülke içinde satan, satışa arz eden, başkalarına veren, sevk eden, nakleden, depolayan, satın alan, kabul eden, bulunduran kişi, on yıldan az olmamak üzere hapis ve bin günden yirmibin güne kadar adlî para cezası ile cezalandırılır. Ancak, uyuşturucu veya uyarıcı madde verilen veya satılan kişinin çocuk olması hâlinde, veren veya satan kişiye verilecek hapis cezası on beş yıldan az olamaz. (4) (…) a) Maddelerin eroin, kokain, morfin, bazmorfin, sentetik kannabinoid, sentetik katinon, sentetik opioid ve türevleri veya amfetamin ve türevleri olması, b) Üçüncü fıkradaki fiillerin; okul, yurt, hastane, kışla veya ibadethane gibi (…) toplu bulunulan bina ve tesisler (…) sınırlarına iki yüz metreden yakın mesafe içindeki (…) yerlerde işlenmesi, hâlinde verilecek ceza yarı oranında artırılır. (5) (…) suçların, üç veya daha fazla kişi tarafından birlikte işlenmesi hâlinde verilecek ceza yarı oranında, suç işlemek için teşkil edilmiş bir örgütün faaliyeti çerçevesinde işlenmesi hâlinde, verilecek ceza bir kat artırılır.",
  "TCK m.190": "(1) Uyuşturucu veya uyarıcı madde kullanılmasını kolaylaştırmak için; a) Özel yer, donanım veya malzeme sağlayan, b) Kullananların yakalanmalarını zorlaştıracak önlemler alan, c) Kullanma yöntemleri konusunda başkalarına bilgi veren, kişi, beş yıldan on yıla kadar hapis ve bin günden onbin güne kadar adlî para cezası ile cezalandırılır. (2) Uyuşturucu veya uyarıcı madde kullanılmasını alenen özendiren veya bu nitelikte yayın yapan kişi, beş yıldan on yıla kadar hapis ve bin günden onbin güne kadar adlî para cezası ile cezalandırılır.",
  "TCK m.191": "(1) Kullanmak için uyuşturucu veya uyarıcı madde satın alan, kabul eden veya bulunduran ya da uyuşturucu veya uyarıcı madde kullanan kişi, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. (2) Bu suçtan dolayı başlatılan soruşturmada şüpheli hakkında (…) beş yıl süreyle kamu davasının açılmasının ertelenmesine karar verilir. (…) (3) Erteleme süresi zarfında şüpheli hakkında asgari bir yıl süreyle denetimli serbestlik tedbiri uygulanır. (…) (10) Birinci fıkradaki fiillerin; okul, yurt, hastane, kışla veya ibadethane gibi (…) sınırlarına iki yüz metreden yakın mesafe içindeki (…) yerlerde işlenmesi hâlinde verilecek ceza yarı oranında artırılır.",
  "TCK m.197": "(1) Memlekette veya yabancı ülkelerde kanunen tedavülde bulunan parayı, sahte olarak üreten, ülkeye sokan, nakleden, muhafaza eden veya tedavüle koyan kişi, iki yıldan oniki yıla kadar hapis ve onbin güne kadar adlî para cezası ile cezalandırılır. (2) Sahte parayı bilerek kabul eden kişi, bir yıldan üç yıla kadar hapis ve adlî para cezası ile cezalandırılır. (3) Sahteliğini bilmeden kabul ettiği parayı bu niteliğini bilerek tedavüle koyan kişi, üç aydan bir yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.2": "(1) Kanunun açıkça suç saymadığı bir fiil için kimseye ceza verilemez ve güvenlik tedbiri uygulanamaz. Kanunda yazılı cezalardan ve güvenlik tedbirlerinden başka bir ceza ve güvenlik tedbirine hükmolunamaz. (2) İdarenin düzenleyici işlemleriyle suç ve ceza konulamaz. (3) Kanunların suç ve ceza içeren hükümlerinin uygulanmasında kıyas yapılamaz. Suç ve ceza içeren hükümler, kıyasa yol açacak biçimde geniş yorumlanamaz.",
  "TCK m.20": "(1) Ceza sorumluluğu şahsidir. Kimse başkasının fiilinden dolayı sorumlu tutulamaz. (2) Tüzel kişiler hakkında ceza yaptırımı uygulanamaz. Ancak, suç dolayısıyla kanunda öngörülen güvenlik tedbiri niteliğindeki yaptırımlar saklıdır.",
  "TCK m.204": "(1) Bir resmi belgeyi sahte olarak düzenleyen, gerçek bir resmi belgeyi başkalarını aldatacak şekilde değiştiren veya sahte resmi belgeyi kullanan kişi, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. (2) Görevi gereği düzenlemeye yetkili olduğu resmi bir belgeyi sahte olarak düzenleyen, gerçek bir belgeyi başkalarını aldatacak şekilde değiştiren, gerçeğe aykırı olarak belge düzenleyen veya sahte resmi belgeyi kullanan kamu görevlisi üç yıldan sekiz yıla kadar hapis cezası ile cezalandırılır. (3) Resmi belgenin, kanun hükmü gereği sahteliği sabit oluncaya kadar geçerli olan belge niteliğinde olması halinde, verilecek ceza yarısı oranında artırılır.",
  "TCK m.206": "(1) Bir resmi belgeyi düzenlemek yetkisine sahip olan kamu görevlisine yalan beyanda bulunan kişi, üç aydan iki yıla kadar hapis veya adlî para cezası ile cezalandırılır.",
  "TCK m.207": "(1) Bir özel belgeyi sahte olarak düzenleyen veya gerçek bir özel belgeyi başkalarını aldatacak şekilde değiştiren ve kullanan kişi, bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. (2) Bir sahte özel belgeyi bu özelliğini bilerek kullanan kişi de yukarıdaki fıkra hükmüne göre cezalandırılır.",
  "TCK m.21": "(1) Suçun oluşması kastın varlığına bağlıdır. Kast, suçun kanuni tanımındaki unsurların bilerek ve istenerek gerçekleştirilmesidir. (2) Kişinin, suçun kanuni tanımındaki unsurların gerçekleşebileceğini öngörmesine rağmen, fiili işlemesi halinde olası kast vardır. Bu halde, (...) temel ceza üçte birden yarısına kadar indirilir.",
  "TCK m.22": "(1) Taksirle işlenen fiiller, kanunun açıkça belirttiği hallerde cezalandırılır. (2) Taksir, dikkat ve özen yükümlülüğüne aykırılık dolayısıyla, bir davranışın suçun kanuni tanımında belirtilen neticesi öngörülmeyerek gerçekleştirilmesidir. (3) Kişinin öngördüğü neticeyi istememesine karşın, neticenin meydana gelmesi halinde bilinçli taksir vardır; bu halde taksirli suça ilişkin ceza üçte birden yarısına kadar artırılır.",
  "TCK m.220": "(1) Kanunun suç saydığı fiilleri işlemek amacıyla örgüt kuranlar veya yönetenler, örgütün yapısı, sahip bulunduğu üye sayısı ile araç ve gereç bakımından amaç suçları işlemeye elverişli olması halinde, beş yıldan on yıla kadar hapis cezası ile cezalandırılır. Ancak, örgütün varlığı için üye sayısının en az üç kişi olması gerekir. (2) Suç işlemek amacıyla kurulmuş olan örgüte üye olanlar, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır. (3) Örgütün silahlı olması halinde, yukarıdaki fıkralara göre verilecek ceza yarısı oranında artırılır. (4) Örgütün faaliyeti çerçevesinde suç işlenmesi halinde, ayrıca bu suçlardan dolayı da cezaya hükmolunur. (5) (…) Örgütün faaliyeti çerçevesinde işlenen suçlarda çocukların araç olarak kullanılması halinde, örgüt yöneticilerine verilecek ceza yarısından bir katına kadar artırılır. (…) (7) Örgüt içindeki hiyerarşik yapıya dahil olmamakla birlikte, örgüte bilerek ve isteyerek yardım eden kişi, örgüt üyesi olarak cezalandırılır. (…) (8) Örgütün cebir, şiddet veya tehdit içeren yöntemlerini meşru gösterecek veya övecek ya da bu yöntemlere başvurmayı teşvik edecek şekilde propagandasını yapan kişi, bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Bu suçun basın ve yayın yolu ile işlenmesi halinde, verilecek ceza yarı oranında artırılır.",
  "TCK m.226": "(1) a) Bir çocuğa müstehcen görüntü, yazı veya sözleri içeren ürünleri veren ya da bunların içeriğini gösteren, okuyan, okutan veya dinleten, b) Bunların içeriklerini çocukların girebileceği veya görebileceği yerlerde ya da alenen gösteren (…), c-d-e-f) (…) Kişi, altı aydan iki yıla kadar hapis ve adlî para cezası ile cezalandırılır. (2) Müstehcen görüntü, yazı veya sözleri basın ve yayın yolu ile yayınlayan veya yayınlanmasına aracılık eden kişi altı aydan üç yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır. (3) Müstehcen (…) ürünlerin üretiminde çocukları, temsili çocuk görüntülerini veya çocuk gibi görünen kişileri kullanan kişi, beş yıldan on yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır. (…) (7) Bu madde hükümleri, bilimsel eserlerle; üçüncü fıkra hariç olmak ve çocuklara ulaşması engellenmek koşuluyla, sanatsal ve edebi değeri olan eserler hakkında uygulanmaz.",
  "TCK m.227": "(1) Çocuğu fuhşa teşvik eden, bunun yolunu kolaylaştıran, bu maksatla tedarik eden veya barındıran ya da çocuğun fuhşuna aracılık eden kişi, dört yıldan on yıla kadar hapis ve beşbin güne kadar adlî para cezası ile cezalandırılır. Bu suçun işlenişine yönelik hazırlık hareketleri de tamamlanmış suç gibi cezalandırılır. (2) Bir kimseyi fuhşa teşvik eden, bunun yolunu kolaylaştıran ya da fuhuş için aracılık eden veya yer temin eden kişi, iki yıldan dört yıla kadar hapis ve üçbin güne kadar adlî para cezası ile cezalandırılır. (…) (4) Cebir veya tehdit kullanarak, hile ile ya da çaresizliğinden yararlanarak bir kimseyi fuhşa sevk eden veya fuhuş yapmasını sağlayan kişi hakkında yukarıdaki fıkralara göre verilecek ceza yarısından iki katına kadar artırılır. (5) Yukarıdaki fıkralarda tanımlanan suçların eş, üstsoy, kayın üstsoy, kardeş, evlat edinen, vasi, eğitici, öğretici, bakıcı, koruma ve gözetim yükümlülüğü bulunan diğer kişiler tarafından ya da kamu görevi veya hizmet ilişkisinin sağladığı nüfuz kötüye kullanılmak suretiyle işlenmesi halinde, verilecek ceza yarı oranında artırılır. (…) (8) Fuhşa sürüklenen kişi, tedaviye veya psikolojik terapiye tâbi tutulabilir.",
  "TCK m.23": "(1) Bir fiilin, kastedilenden daha ağır veya başka bir neticenin oluşumuna sebebiyet vermesi halinde, kişinin bundan dolayı sorumlu tutulabilmesi için bu netice bakımından en azından taksirle hareket etmesi gerekir.",
  "TCK m.24": "(1) Kanunun hükmünü yerine getiren kimseye ceza verilmez. (2) Yetkili bir merciden verilip, yerine getirilmesi görev gereği zorunlu olan bir emri uygulayan sorumlu olmaz. (3) Konusu suç teşkil eden emir hiçbir surette yerine getirilemez. Aksi takdirde yerine getiren ile emri veren sorumlu olur. (4) Emrin, hukuka uygunluğunun denetlenmesinin kanun tarafından engellendiği hallerde, yerine getirilmesinden emri veren sorumlu olur.",
  "TCK m.247": "(1) Görevi nedeniyle zilyedliği kendisine devredilmiş olan veya koruma ve gözetimiyle yükümlü olduğu malı kendisinin veya başkasının zimmetine geçiren kamu görevlisi, beş yıldan oniki yıla kadar hapis cezası ile cezalandırılır. (2) Suçun, zimmetin açığa çıkmamasını sağlamaya yönelik hileli davranışlarla işlenmesi halinde, verilecek ceza yarı oranında artırılır. (3) Zimmet suçunun, malın geçici bir süre kullanıldıktan sonra iade edilmek üzere işlenmesi halinde, verilecek ceza yarı oranına kadar indirilebilir.",
  "TCK m.248": "(1) Soruşturma başlamadan önce, zimmete geçirilen malın aynen iade edilmesi veya uğranılan zararın tamamen tazmin edilmesi halinde, verilecek cezanın üçte ikisi indirilir. (2) Kovuşturma başlamadan önce, gönüllü olarak, (...) verilecek cezanın yarısı indirilir. Etkin pişmanlığın hükümden önce gerçekleşmesi halinde, verilecek cezanın üçte biri indirilir.",
  "TCK m.249": "(1) Zimmet suçunun konusunu oluşturan malın değerinin azlığı nedeniyle, verilecek ceza üçte birden yarıya kadar indirilir.",
  "TCK m.25": "(1) Gerek kendisine ve gerek başkasına ait bir hakka yönelmiş, gerçekleşen, gerçekleşmesi veya tekrarı muhakkak olan haksız bir saldırıyı o anda hal ve koşullara göre saldırı ile orantılı biçimde defetmek zorunluluğu ile işlenen fiillerden dolayı faile ceza verilmez. (2) ...bilerek neden olmadığı ve başka suretle korunmak olanağı bulunmayan ağır ve muhakkak bir tehlikeden kurtulmak veya başkasını kurtarmak zorunluluğu ile ve tehlikenin ağırlığı ile konu ve kullanılan vasıta arasında orantı bulunmak koşulu ile işlenen fiillerden dolayı faile ceza verilmez.",
  "TCK m.250": "(1) Görevinin sağladığı nüfuzu kötüye kullanmak suretiyle kendisine veya başkasına yarar sağlanmasına (...) bir kimseyi icbar eden kamu görevlisi, beş yıldan on yıla kadar hapis cezası ile cezalandırılır. (...) (2) Görevinin sağladığı güveni kötüye kullanmak suretiyle gerçekleştirdiği hileli davranışlarla, (...) bir kimseyi ikna eden kamu görevlisi, üç yıldan beş yıla kadar hapis cezası ile cezalandırılır. (3) İkinci fıkrada tanımlanan suçun kişinin hatasından yararlanarak işlenmiş olması halinde, bir yıldan üç yıla kadar hapis cezasına hükmolunur. (...)",
  "TCK m.251": "(1) Zimmet veya irtikap suçunun işlenmesine kasten göz yuman denetimle yükümlü kamu görevlisi, işlenen suçun müşterek faili olarak sorumlu tutulur. (2) Denetim görevini ihmal ederek, zimmet veya irtikap suçunun işlenmesine imkan sağlayan kamu görevlisi, üç aydan üç yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.252": "(1) Görevinin ifasıyla ilgili bir işi yapması veya yapmaması için, doğrudan veya aracılar vasıtasıyla, bir kamu görevlisine veya göstereceği bir başka kişiye menfaat sağlayan kişi, dört yıldan oniki yıla kadar hapis cezası ile cezalandırılır. (2) (...) menfaat sağlayan kamu görevlisi de birinci fıkrada belirtilen ceza ile cezalandırılır. (3) Rüşvet konusunda anlaşmaya varılması halinde, suç tamamlanmış gibi cezaya hükmolunur. (...)",
  "TCK m.253": "(1) Rüşvet suçunun işlenmesi suretiyle yararına haksız menfaat sağlanan tüzel kişiler hakkında bunlara özgü güvenlik tedbirlerine hükmolunur.",
  "TCK m.254": "(1) Rüşvet alan kişinin, durum resmi makamlarca öğrenilmeden önce, rüşvet konusu şeyi soruşturmaya yetkili makamlara aynen teslim etmesi halinde, hakkında rüşvet suçundan dolayı cezaya hükmolunmaz. (...) (2) Rüşvet veren veya bu konuda kamu görevlisiyle anlaşmaya varan kişinin, durum resmi makamlarca öğrenilmeden önce, pişmanlık duyarak durumdan yetkili makamları haberdar etmesi halinde, hakkında rüşvet suçundan dolayı cezaya hükmolunmaz. (...)",
  "TCK m.255": "(1) Kamu görevlisi üzerinde nüfuz sahibi olduğundan bahisle, haksız bir işin gördürülmesi amacıyla girişimde bulunması için, doğrudan veya aracılar vasıtasıyla, kendisine veya bir başkasına menfaat temin eden kişi, iki yıldan beş yıla kadar hapis ve beşbin güne kadar adli para cezası ile cezalandırılır. (...)",
  "TCK m.256": "(1) Zor kullanma yetkisine sahip kamu görevlisinin, görevini yaptığı sırada, kişilere karşı görevinin gerektirdiği ölçünün dışında kuvvet kullanması halinde, kasten yaralama suçuna ilişkin hükümler uygulanır.",
  "TCK m.257": "(1) Kanunda ayrıca suç olarak tanımlanan haller dışında, görevinin gereklerine aykırı hareket etmek suretiyle, kişilerin mağduriyetine veya kamunun zararına neden olan ya da kişilere haksız bir menfaat sağlayan kamu görevlisi, altı aydan iki yıla kadar hapis cezası ile cezalandırılır. (2) Kanunda ayrıca suç olarak tanımlanan haller dışında, görevinin gereklerini yapmakta ihmal veya gecikme göstererek, (...) üç aydan bir yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.258": "(1) Görevi nedeniyle kendisine verilen veya aynı nedenle bilgi edindiği ve gizli kalması gereken belgeleri, kararları ve emirleri ve diğer tebligatı açıklayan veya yayınlayan veya ne suretle olursa olsun başkalarının bilgi edinmesini kolaylaştıran kamu görevlisine, bir yıldan dört yıla kadar hapis cezası verilir. (2) Kamu görevlisi sıfatı sona erdikten sonra, birinci fıkrada yazılı fiilleri işleyen kimseye de aynı ceza verilir.",
  "TCK m.259": "(1) Yürüttüğü görevin sağladığı nüfuzdan yararlanarak, bir başkasına mal veya hizmet satmaya çalışan kamu görevlisi, altı aya kadar hapis veya adlî para cezası ile cezalandırılır.",
  "TCK m.26": "(1) Hakkını kullanan kimseye ceza verilmez. (2) Kişinin üzerinde mutlak surette tasarruf edebileceği bir hakkına ilişkin olmak üzere, açıkladığı rızası çerçevesinde işlenen fiilden dolayı kimseye ceza verilmez.",
  "TCK m.260": "(1) Hukuka aykırı olarak ve toplu biçimde, görevlerini terk eden, görevlerine gelmeyen, görevlerini geçici de olsa kısmen veya tamamen yapmayan veya yavaşlatan kamu görevlilerinin her biri hakkında üç aydan bir yıla kadar hapis cezası verilir. Kamu görevlisi sayısının üçten fazla olmaması halinde cezaya hükmolunmaz. (2) (...) hizmeti aksatmayacak biçimde, geçici ve kısa süreli iş bırakmaları (...) halinde, verilecek cezada indirim yapılabileceği gibi, ceza da verilmeyebilir.",
  "TCK m.261": "(1) İlgili kanunlarda belirlenen koşullara aykırı olduğunu bilerek, kişilerin taşınır veya taşınmaz malları üzerinde, karşılık ödenmek suretiyle de olsa, zorla tasarrufta bulunan kamu görevlisi, fiil daha ağır cezayı gerektiren bir suç oluşturmadığı takdirde, altı aydan iki yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.262": "(1) Bir kamu görevini, kanun ve nizamlara aykırı olarak yerine getirmeye teşebbüs eden veya terk emri kendisine bildirilmiş olduğu halde görevi sürdüren kimseye üç aydan iki yıla kadar hapis cezası verilir.",
  "TCK m.264": "(1) Bir rütbe veya kamu görevinin veya mesleğin, resmi elbisesini yetkisi olmaksızın alenen ve başkalarını yanıltacak şekilde giyen veya hakkı olmayan nişan veya madalyaları takan kimseye üç aydan bir yıla kadar hapis cezası verilir. (2) Elbisenin sağlayacağı kolaylık ve olanaklardan yararlanarak bir suç işlenirse, yalnız bu fiilden ötürü yukarıdaki fıkrada belirtilen cezalar üçte biri oranında artırılarak hükmolunur.",
  "TCK m.265": "(1) Kamu görevlisine karşı görevini yapmasını engellemek amacıyla, cebir veya tehdit kullanan kişi, altı aydan üç yıla kadar hapis cezası ile cezalandırılır. (2) Suçun yargı görevi yapan kişilere karşı işlenmesi halinde, iki yıldan dört yıla kadar hapis cezasına hükmolunur. (...) (4) Suçun, silahla ya da var olan veya var sayılan suç örgütlerinin (...) işlenmesi halinde, (...) ceza yarı oranında artırılır. (...)",
  "TCK m.266": "(1) Görevi gereği olarak elinde bulundurduğu araç ve gereçleri bir suçun işlenmesi sırasında kullanan kamu görevlisi hakkında, ilgili suçun tanımında kamu görevlisi sıfatı esasen göz önünde bulundurulmamış ise, verilecek ceza üçte biri oranında artırılır.",
  "TCK m.267": "(1) Yetkili makamlara ihbar veya şikayette bulunarak ya da basın ve yayın yoluyla, işlemediğini bildiği halde, hakkında soruşturma ve kovuşturma başlatılmasını ya da idari bir yaptırım uygulanmasını sağlamak için bir kimseye hukuka aykırı bir fiil isnat eden kişi, bir yıldan dört yıla kadar hapis cezası ile cezalandırılır. (2) Fiilin maddî eser ve delillerini uydurarak iftirada bulunulması halinde, ceza yarı oranında artırılır. ... [m.268: işlediği suç nedeniyle kendisi hakkında soruşturmayı engellemek için BAŞKASINA AİT KİMLİĞİ kullanan kimse, iftira hükümlerine göre cezalandırılır.]",
  "TCK m.271": "(1) İşlenmediğini bildiği bir suçu, yetkili makamlara işlenmiş gibi ihbar eden ya da işlenmeyen bir suçun delil veya emarelerini soruşturma yapılmasını sağlayacak biçimde uyduran kimseye üç yıla kadar hapis cezası verilir.",
  "TCK m.272": "(1) Hukuka aykırı bir fiil nedeniyle başlatılan bir soruşturma kapsamında tanık dinlemeye yetkili kişi veya kurul önünde gerçeğe aykırı olarak tanıklık yapan kimseye, dört aydan bir yıla kadar hapis cezası verilir. (2) Mahkeme huzurunda ya da yemin ettirerek tanık dinlemeye kanunen yetkili kişi veya kurul önünde gerçeğe aykırı olarak tanıklık yapan kimseye bir yıldan üç yıla kadar hapis cezası verilir. (3) Üç yıldan fazla hapis cezasını gerektiren bir suçun soruşturma veya kovuşturması kapsamında yalan tanıklık yapan kişi hakkında iki yıldan dört yıla kadar...",
  "TCK m.277": "(1) Görülmekte olan bir davada (...) gerçeğin ortaya çıkmasını engellemek veya bir haksızlık oluşturmak amacıyla...bir karar vermesi veya bir işlem tesis etmesi ya da beyanda bulunması için, yargı görevi yapanı, bilirkişiyi veya tanığı hukuka aykırı olarak etkilemeye teşebbüs eden kişi, iki yıldan dört yıla kadar hapis cezası ile cezalandırılır. Teşebbüs iltimas derecesini geçmediği takdirde verilecek ceza altı aydan iki yıla kadardır.",
  "TCK m.278": "(1) İşlenmekte olan bir suçu yetkili makamlara bildirmeyen kişi, bir yıla kadar hapis cezası ile cezalandırılır. (2) İşlenmiş olmakla birlikte, sebebiyet verdiği neticelerin sınırlandırılması halen mümkün bulunan bir suçu yetkili makamlara bildirmeyen kişi, yukarıdaki fıkra hükmüne göre cezalandırılır. (3) Mağdurun onbeş yaşını bitirmemiş bir çocuk, bedensel veya ruhsal bakımdan engelli olan ya da hamileliği nedeniyle kendisini savunamayacak durumda bulunan kimse olması halinde...ceza, yarı oranında artırılır. (4) Tanıklıktan çekinebilecek olan kişiler bakımından cezaya hükmolunmaz...",
  "TCK m.279": "(1) Kamu adına soruşturma ve kovuşturmayı gerektiren bir suçun işlendiğini göreviyle bağlantılı olarak öğrenip de yetkili makamlara bildirimde bulunmayı ihmal eden veya bu hususta gecikme gösteren kamu görevlisi, altı aydan iki yıla kadar hapis cezası ile cezalandırılır. (2) Suçun, adlî kolluk görevini yapan kişi tarafından işlenmesi halinde, yukarıdaki fıkraya göre verilecek ceza yarı oranında artırılır.",
  "TCK m.28": "(1) Karşı koyamayacağı veya kurtulamayacağı cebir ve şiddet veya muhakkak ve ağır bir korkutma veya tehdit sonucu suç işleyen kimseye ceza verilmez. Bu gibi hallerde cebir ve şiddet, korkutma ve tehdidi kullanan kişi suçun faili sayılır.",
  "TCK m.280": "(1) Görevini yaptığı sırada bir suçun işlendiği yönünde bir belirti ile karşılaşmasına rağmen, durumu yetkili makamlara bildirmeyen veya bu hususta gecikme gösteren sağlık mesleği mensubu, bir yıla kadar hapis cezası ile cezalandırılır. (2) Sağlık mesleği mensubu deyiminden tabip, diş tabibi, eczacı, ebe, hemşire ve sağlık hizmeti veren diğer kişiler anlaşılır.",
  "TCK m.281": "(1) Gerçeğin meydana çıkmasını engellemek amacıyla, bir suçun delillerini yok eden, silen, gizleyen, değiştiren veya bozan kişi, altı aydan beş yıla kadar hapis cezası ile cezalandırılır. Kendi işlediği veya işlenişine iştirak ettiği suçla ilgili olarak kişiye bu fıkra hükmüne göre ceza verilmez. (2) Bu suçun kamu görevlisi tarafından göreviyle bağlantılı olarak işlenmesi halinde, verilecek ceza yarı oranında artırılır. (3) İlişkin olduğu suç nedeniyle hüküm verilmeden önce gizlenen delilleri mahkemeye teslim eden kişi hakkında...verilecek cezanın beşte dördü indirilir.",
  "TCK m.282": "(1) Alt sınırı altı ay veya daha fazla hapis cezasını gerektiren bir suçtan kaynaklanan malvarlığı değerlerini, yurt dışına çıkaran veya bunların gayrimeşru kaynağını gizlemek veya meşru bir yolla elde edildiği konusunda kanaat uyandırmak maksadıyla, çeşitli işlemlere tâbi tutan kişi, üç yıldan yedi yıla kadar hapis ve yirmibin güne kadar adlî para cezası ile cezalandırılır. (2) ...bu suçun konusunu oluşturan malvarlığı değerini, bu özelliğini bilerek satın alan, kabul eden, bulunduran veya kullanan kişi iki yıldan beş yıla kadar...",
  "TCK m.283": "(1) Suç işleyen bir kişiye araştırma, yakalanma, tutuklanma veya hükmün infazından kurtulması için imkan sağlayan kimse, altı aydan beş yıla kadar hapis cezası ile cezalandırılır. (2) Bu suçun kamu görevlisi tarafından göreviyle bağlantılı olarak işlenmesi halinde, verilecek ceza yarı oranında artırılır. (3) Bu suçun üstsoy, altsoy, eş, kardeş veya diğer suç ortağı tarafından işlenmesi halinde, cezaya hükmolunmaz.",
  "TCK m.289": "(1) Muhafaza edilmek üzere kendisine resmen teslim olunan rehinli veya hacizli veya herhangi bir nedenle elkonulmuş olan mal üzerinde teslim amacı dışında tasarrufta bulunan kişi, üç aydan iki yıla kadar hapis ve üç bin güne kadar adlî para cezası ile cezalandırılır. Kişinin bu malın sahibi olması halinde, verilecek ceza yarı oranında indirilir. ... (4) Bir suça ilişkin soruşturma veya kovuşturma kapsamında elkonulan eşyayı amacı dışında kullanan kimse, bir yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.29": "(1) Haksız bir fiilin meydana getirdiği hiddet veya şiddetli elemin etkisi altında suç işleyen kimseye, ağırlaştırılmış müebbet hapis cezası yerine onsekiz yıldan yirmidört yıla ve müebbet hapis cezası yerine oniki yıldan onsekiz yıla kadar hapis cezası verilir. Diğer hallerde verilecek cezanın dörtte birinden dörtte üçüne kadarı indirilir.",
  "TCK m.299": "(1) Cumhurbaşkanına hakaret eden kişi, bir yıldan dört yıla kadar hapis cezası ile cezalandırılır. (2) Suçun alenen işlenmesi hâlinde, verilecek ceza altıda biri oranında artırılır. (3) Bu suçtan dolayı kovuşturma yapılması, Adalet Bakanının iznine bağlıdır.",
  "TCK m.3": "(1) Suç işleyen kişi hakkında işlenen fiilin ağırlığıyla orantılı ceza ve güvenlik tedbirine hükmolunur. (2) Ceza Kanununun uygulamasında kişiler arasında ırk, dil, din, mezhep, milliyet, renk, cinsiyet, siyasal veya diğer fikir yahut düşünceleri, felsefi inanç, milli veya sosyal köken, doğum, ekonomik ve diğer toplumsal konumları yönünden ayrım yapılamaz ve hiçbir kimseye ayrıcalık tanınamaz.",
  "TCK m.301": "(1) Türk Milletini, Türkiye Cumhuriyeti Devletini, Türkiye Büyük Millet Meclisini, Türkiye Cumhuriyeti Hükümetini ve Devletin yargı organlarını alenen aşağılayan kişi, altı aydan iki yıla kadar hapis cezası ile cezalandırılır. (2) Devletin askerî veya emniyet teşkilatını alenen aşağılayan kişi, birinci fıkra hükmüne göre cezalandırılır. (3) Eleştiri amacıyla yapılan düşünce açıklamaları suç oluşturmaz. (4) Bu suçtan dolayı soruşturma yapılması, Adalet Bakanının iznine bağlıdır.",
  "TCK m.31": "(1) Fiili işlediği sırada oniki yaşını doldurmamış olan çocukların ceza sorumluluğu yoktur. ...ceza kovuşturması yapılamaz; ancak, çocuklara özgü güvenlik tedbirleri uygulanabilir. (2) ...oniki yaşını doldurmuş olup da onbeş yaşını doldurmamış olanların...algılayamaması veya...yeteneğinin yeterince gelişmemiş olması hâlinde ceza sorumluluğu yoktur...varlığı hâlinde...diğer cezaların yarısı indirilir... (3) ...onbeş yaşını doldurmuş olup da onsekiz yaşını doldurmamış olan kişiler hakkında...diğer cezaların üçte biri indirilir...",
  "TCK m.314": "(1) Bu kısmın dördüncü ve beşinci bölümlerinde yer alan suçları işlemek amacıyla, silahlı örgüt kuran veya yöneten kişi, on yıldan onbeş yıla kadar hapis cezası ile cezalandırılır. (2) Birinci fıkrada tanımlanan örgüte üye olanlara, beş yıldan on yıla kadar hapis cezası verilir. ... [m.315 silah sağlama: örgütün amaçlarını bilerek silah üreten, satın alan, ülkeye sokan, nakleden veya depolayan kişi 10-15 yıl.] [KARŞILAŞTIR — m.220 adi suç örgütü: kuran/yöneten 5-10 yıl, üye 2-5 yıl; örgüt silahlıysa ceza yarı artar; üye sayısı en az 3 kişi. m.314 ise Devletin güvenliğine/anayasal düzene karşı suçlar için kurulan silahlı (terör) örgütü olup cezası ağırdır.]",
  "TCK m.317": "(1) Kanunen yetkili olmadıkları veya Devlet tarafından memur edilmedikleri halde, bir asker kıtasının veya donanmasının veya savaş gemisinin veya savaş hava filosunun veya bir kale veya müstahkem mevkiin veya bir askerî üssün veya tesisin, bir liman veya şehrin komutasını alanlara müebbet hapis cezası verilir. (2) (...) yetkili makamlarca komutanlığı terk etmeleri için verilen emirlere uymayanlara da aynı ceza verilir.",
  "TCK m.318": "(1) Askerlik hizmetini yapanları firara sevk edecek veya askerlik hizmetine katılacak olanları bu hizmeti yapmaktan vazgeçirecek şekilde teşvik veya telkinde bulunanlara altı aydan iki yıla kadar hapis cezası verilir. (2) Fiil, basın ve yayın yolu ile işlenirse ceza yarısı oranında artırılır.",
  "TCK m.319": "(1) Askerleri veya askerî idareye bağlı olarak görev yapan diğer kişileri kanunlara karşı itaatsizliğe veya yeminlerini bozmaya veya askerî disiplini veya askerlik hizmetine ilişkin görevlerini ihlale yönelten ve tahrik edenler (...) bir yıldan üç yıla kadar hapis cezası verilir. (2) Fiil, aleni olarak işlenmişse iki yıldan beş yıla kadar hapis cezası verilir. (3) Fiil, savaş zamanında işlenmiş ise ceza bir katı oranında artırılır.",
  "TCK m.32": "(1) Akıl hastalığı nedeniyle, işlediği fiilin hukuki anlam ve sonuçlarını algılayamayan veya bu fiille ilgili olarak davranışlarını yönlendirme yeteneği önemli derecede azalmış olan kişiye ceza verilmez. Ancak, bu kişiler hakkında güvenlik tedbirine hükmolunur. (2) Birinci fıkrada yazılı derecede olmamakla birlikte...yeteneği azalmış olan kişiye, ağırlaştırılmış müebbet hapis cezası yerine yirmibeş yıl, müebbet hapis cezası yerine yirmi yıl hapis cezası verilir. Diğer hallerde verilecek ceza, altıda birden fazla olmamak üzere indirilebilir...",
  "TCK m.320": "(1) Hükûmetin izni olmaksızın bir yabancı veya yabancı Devlet hizmetinde veya bunların lehinde çalışmak üzere Ülke içinde vatandaşlardan asker yazan veya vatandaşları silahlandıran kimseye üç yıldan altı yıla kadar hapis cezası verilir. (2) Asker yazılanlar veya silahlandırılanlar arasından asker veya askerlik çağında olanlar varsa ceza üçte biri oranında artırılır. (3) Birinci fıkradaki hizmeti kabul eden kimseye bir yıldan üç yıla kadar hapis cezası verilir.",
  "TCK m.321": "(1) Savaş zamanında Devletin yetkili makam ve mercilerinin emir veya kararlarına bilerek aykırı harekette bulunan kimseye bir yıldan altı yıla kadar hapis cezası verilir.",
  "TCK m.322": "(1) Savaş zamanında, Devletin silahlı kuvvetlerinin veya halkın ihtiyaçları için Devlet veya bir kamu kuruluşu (...) ile iş yapmak veya eşya vermek üzere yaptıkları sözleşmedeki yükümlülükleri kısmen veya tamamen yerine getirmeyen kimseye üç yıldan on yıla kadar hapis ve onbin güne kadar adlî para cezası verilir. (2) Yükümlülüklerin kısmen veya tamamen yerine getirilmemesi taksirden ileri gelmişse, cezanın dörtte üçüne kadarı indirilebilir. (...) (4) Savaş zamanında yükümlülüklerin yerine getirilmesinde hile yapan (...) on yıldan onbeş yıla kadar hapis ve (...)",
  "TCK m.323": "(1) Savaş sırasında kamunun endişe ve heyecan duymasına neden olacak veya halkın maneviyatını sarsacak veya düşman karşısında ülkenin direncini azaltacak şekilde asılsız veya abartılmış veya özel maksada dayalı havadis veya haber yayan veya nakleden veya temel milli yararlara zarar verebilecek herhangi bir faaliyette bulunan kimseye beş yıldan on yıla kadar hapis cezası verilir. (...) (3) Fiil, düşmanla anlaşma neticesi işlenmişse müebbet hapis cezası verilir.",
  "TCK m.324": "(1) Sulh zamanında seferberlikle ilgili görevlerini ihmal eden veya geciktiren kamu görevlisine altı aydan üç yıla kadar hapis cezası verilir.",
  "TCK m.325": "(1) Türkiye ile savaş halinde bulunan bir devletten akademik derece veya şeref, unvan, nişan ve diğer fahri rütbe veya bunlara ait maaş veya başka yararlar kabul eden vatandaşa bir yıldan üç yıla kadar hapis cezası verilir.",
  "TCK m.33": "(1) Bu Kanunun, fiili işlediği sırada oniki yaşını doldurmamış olan çocuklara ilişkin hükümleri, onbeş yaşını doldurmamış olan sağır ve dilsizler hakkında; oniki yaşını doldurmuş olup da onbeş yaşını doldurmamış olanlara ilişkin hükümleri, onbeş yaşını doldurmuş olup da onsekiz yaşını doldurmamış olan sağır ve dilsizler hakkında; onbeş yaşını doldurmuş olup da onsekiz yaşını doldurmamış olanlara ilişkin hükümleri, onsekiz yaşını doldurmuş olup da yirmibir yaşını doldurmamış olan sağır ve dilsizler hakkında da uygulanır.",
  "TCK m.34": "(1) Geçici bir nedenle ya da irade dışı alınan alkol veya uyuşturucu madde etkisiyle, işlediği fiilin hukuki anlam ve sonuçlarını algılayamayan veya...yeteneği önemli derecede azalmış olan kişiye ceza verilmez. (2) İradi olarak alınan alkol veya uyuşturucu madde etkisinde suç işleyen kişi hakkında birinci fıkra hükmü uygulanmaz.",
  "TCK m.35": "(1) Kişi, işlemeyi kastettiği bir suçu elverişli hareketlerle doğrudan doğruya icraya başlayıp da elinde olmayan nedenlerle tamamlayamaz ise teşebbüsten dolayı sorumlu tutulur. (2) Suça teşebbüs halinde fail, meydana gelen zarar veya tehlikenin ağırlığına göre, (...) Diğer hallerde verilecek cezanın dörtte birinden dörtte üçüne kadarı indirilir.",
  "TCK m.36": "(1) Fail, suçun icra hareketlerinden gönüllü vazgeçer veya kendi çabalarıyla suçun tamamlanmasını veya neticenin gerçekleşmesini önlerse, teşebbüsten dolayı cezalandırılmaz; fakat tamam olan kısım esasen bir suç oluşturduğu takdirde, sadece o suça ait ceza ile cezalandırılır.",
  "TCK m.37": "(1) Suçun kanuni tanımında yer alan fiili birlikte gerçekleştiren kişilerden her biri, fail olarak sorumlu olur. (2) Suçun işlenmesinde bir başkasını araç olarak kullanan kişi de fail olarak sorumlu tutulur. Kusur yeteneği olmayanları suçun işlenmesinde araç olarak kullanan kişinin cezası, üçte birden yarısına kadar artırılır.",
  "TCK m.38": "(1) Başkasını suç işlemeye azmettiren kişi, işlenen suçun cezası ile cezalandırılır. (2) Üstsoy ve altsoy ilişkisinden doğan nüfuz kullanılmak suretiyle suça azmettirme halinde, azmettirenin cezası üçte birden yarısına kadar artırılır. (...)",
  "TCK m.39": "(1) Suçun işlenmesine yardım eden kişiye, (...) Diğer hallerde cezanın yarısı indirilir. Ancak, bu durumda verilecek ceza sekiz yılı geçemez. (2) Aşağıdaki hallerde kişi işlenen suçtan dolayı yardım eden sıfatıyla sorumlu olur: a) Suç işlemeye teşvik etmek veya suç işleme kararını kuvvetlendirmek veya fiilin işlenmesinden sonra yardımda bulunacağını vaat etmek. b) Suçun nasıl işleneceği hususunda yol göstermek veya fiilin işlenmesinde kullanılan araçları sağlamak. c) Suçun işlenmesinden önce veya işlenmesi sırasında yardımda bulunarak icrasını kolaylaştırmak.",
  "TCK m.4": "(1) Ceza kanunlarını bilmemek mazeret sayılmaz.",
  "TCK m.40": "(1) Suça iştirak için kasten ve hukuka aykırı işlenmiş bir fiilin varlığı yeterlidir. Suçun işlenişine iştirak eden her kişi, (...) kendi kusurlu fiiline göre cezalandırılır. (2) Özgü suçlarda, ancak özel faillik niteliğini taşıyan kişi fail olabilir. Bu suçların işlenişine iştirak eden diğer kişiler ise azmettiren veya yardım eden olarak sorumlu tutulur. (3) Suça iştirakten dolayı sorumlu tutulabilmek için ilgili suçun en azından teşebbüs aşamasına varmış olması gerekir.",
  "TCK m.41": "(1) İştirak halinde işlenen suçlarda, sadece gönüllü vazgeçen suç ortağı, gönüllü vazgeçme hükümlerinden yararlanır. (2) Suçun; a) Gönüllü vazgeçenin gösterdiği gayreti dışında başka bir sebeple işlenmemiş olması, b) Gönüllü vazgeçenin bütün gayretine rağmen işlenmiş olması, hallerinde de gönüllü vazgeçme hükümleri uygulanır.",
  "TCK m.42": "(1) Biri diğerinin unsurunu veya ağırlaştırıcı nedenini oluşturması dolayısıyla tek fiil sayılan suça bileşik suç denir. Bu tür suçlarda içtima hükümleri uygulanmaz.",
  "TCK m.43": "(1) Bir suç işleme kararının icrası kapsamında, değişik zamanlarda bir kişiye karşı aynı suçun birden fazla işlenmesi durumunda, bir cezaya hükmedilir. Ancak bu ceza, dörtte birinden dörtte üçüne kadar artırılır. (...) (2) Aynı suçun birden fazla kişiye karşı tek bir fiille işlenmesi durumunda da, birinci fıkra hükmü uygulanır. (3) Kasten öldürme, kasten yaralama, işkence ve yağma suçlarında bu madde hükümleri uygulanmaz.",
  "TCK m.44": "(1) İşlediği bir fiil ile birden fazla farklı suçun oluşmasına sebebiyet veren kişi, bunlardan en ağır cezayı gerektiren suçtan dolayı cezalandırılır.",
  "TCK m.45": "(1) Suç karşılığında uygulanan yaptırım olarak cezalar, hapis ve adlî para cezalarıdır.",
  "TCK m.5": "(1) Bu Kanunun genel hükümleri, özel ceza kanunları ve ceza içeren kanunlardaki suçlar hakkında da uygulanır.",
  "TCK m.6": "(1) Ceza kanunlarının uygulanmasında; ... c) Kamu görevlisi deyiminden; kamusal faaliyetin yürütülmesine atama veya seçilme yoluyla ya da herhangi bir surette sürekli, süreli veya geçici olarak katılan kişi, ... e) Gece vakti deyiminden; güneşin batmasından bir saat sonra başlayan ve doğmasından bir saat evvele kadar devam eden zaman süresi, f) Silah deyiminden; 1. Ateşli silahlar, 2. Patlayıcı maddeler, 3. ...her türlü kesici, delici veya bereleyici alet, 4. fiilen saldırı ve savunmada kullanılmaya elverişli diğer şeyler, 5. ...nükleer, radyoaktif, kimyasal, biyolojik maddeler, ... anlaşılır.",
  "TCK m.73": "(1) Soruşturulması ve kovuşturulması şikayete bağlı olan suç hakkında yetkili kimse altı ay içinde şikayette bulunmadığı takdirde soruşturma ve kovuşturma yapılamaz. (2) ...bu süre, şikayet hakkı olan kişinin fiili ve failin kim olduğunu bildiği veya öğrendiği günden başlar. (Ek 2024) ...hakaret suçu bakımından şikâyet süresi, fiilin gerçekleştiği tarihten itibaren İKİ YILI geçemez. (3) Şikayet hakkı olan birkaç kişiden birisi altı aylık süreyi geçirirse bundan dolayı diğerlerinin hakları düşmez. (4) ...suçtan zarar gören kişinin vazgeçmesi davayı düşürür... (5) İştirak halinde suç işlemiş sanıklardan biri hakkındaki şikayetten vazgeçme, diğerlerini de kapsar. (6) Kanunda aksi yazılı olmadıkça, vazgeçme onu KABUL ETMEYEN sanığı etkilemez.",
  "TCK m.76": "Madde 76- (1) Bir planın icrası suretiyle, milli, etnik, ırki veya dini bir grubun tamamen veya kısmen yokedilmesi maksadıyla, bu grupların üyelerine karşı; kasten öldürme, bedensel/ruhsal bütünlüğe ağır zarar, yok edici koşullara zorlama, doğuma engel tedbirler, çocukları zorla başka gruba nakletme fiillerinden birinin işlenmesi soykırımdır. (2) Faile ağırlaştırılmış müebbet verilir. (3) Tüzel kişiler hakkında güvenlik tedbiri. (4) Zamanaşımı işlemez.",
  "TCK m.77": "Madde 77- (1) Kasten öldürme, yaralama, işkence/eziyet/köleleştirme, hürriyetten yoksun kılma, bilimsel deneye tabi kılma, cinsel saldırı/çocukların cinsel istismarı, zorla hamile bırakma, zorla fuhşa sevketme fiillerinin siyasal, felsefi, ırki veya dini saiklerle toplumun bir kesimine karşı bir plan doğrultusunda sistemli olarak işlenmesi insanlığa karşı suçtur. (2) Öldürme → ağ. müebbet; diğer bentler → 8 yıldan az olmamak üzere hapis. (4) Zamanaşımı işlemez.",
  "TCK m.78": "Madde 78- (1) Yukarıdaki maddelerde (soykırım/insanlığa karşı suçlar) yazılı suçları işlemek maksadıyla örgüt kuran veya yöneten kişi on yıldan onbeş yıla; üye olanlar beş yıldan on yıla kadar hapisle cezalandırılır. (3) Zamanaşımı işlemez.",
  "TCK m.79": "Madde 79- (1) Doğrudan/dolaylı maddi menfaat için yasal olmayan yollardan bir yabancıyı ülkeye sokan/kalmasına imkan sağlayan ya da Türk vatandaşı/yabancının yurt dışına çıkmasına imkan sağlayan kişi beş yıldan sekiz yıla kadar hapis ve bin günden onbin güne kadar adlî para. Teşebbüs tamamlanmış gibi cezalandırılır. (2) Hayatı tehlikeye sokma/onur kırıcı → yarısından 2/3'e; (3) birden fazla kişi → yarıya, örgütle → yarısından bir katına artar.",
  "TCK m.80": "Madde 80- (1) Zorla çalıştırma, hizmet ettirme, fuhuş yaptırma, esarete tâbi kılma ya da organlarının verilmesini sağlama maksadıyla; tehdit, baskı, cebir, şiddet, nüfuzu kötüye kullanma, kandırma veya çaresizlikten yararlanarak rıza elde etme suretiyle kişileri ülkeye sokan/çıkaran/tedarik eden/kaçıran/nakleden/barındıran kişiye sekiz yıldan oniki yıla kadar hapis ve onbin güne kadar adlî para. (2) Mağdurun rızası geçersizdir. (3) 18 yaşını doldurmamışlarda bu maksatlarla tedarik/nakil/barındırma yeterlidir (cebir vb. aranmaz).",
  "TCK m.81": "Madde 81- (1) Bir insanı kasten öldüren kişi, müebbet hapis cezası ile cezalandırılır.",
  "TCK m.82": "Madde 82- (1) Kasten öldürme suçunun;\na) Tasarlayarak,\nb) Canavarca hisle veya eziyet çektirerek,\nc) Yangın, su baskını, tahrip, batırma veya bombalama ya da nükleer, biyolojik veya kimyasal silah kullanmak suretiyle,\nd) Üstsoy veya altsoydan birine ya da eş, boşandığı eş veya kardeşe karşı,\ne) Çocuğa ya da beden veya ruh bakımından kendisini savunamayacak durumda bulunan kişiye karşı,\nf) (Değişik:12/5/2022-7406/2 md.) Kadına karşı,\ng) Kişinin yerine getirdiği kamu görevi nedeniyle,\nh) Bir suçu gizlemek, delillerini ortadan kaldırmak veya işlenmesini kolaylaştırmak ya da yakalanmamak amacıyla,\ni) (Ek:29/6/2005 - 5377/9 md.) Bir suçu işleyememekten dolayı duyduğu infialle,\nj) Kan gütme saikiyle,\nk) Töre saikiyle,\nİşlenmesi halinde, kişi ağırlaştırılmış müebbet hapis cezası ile cezalandırılır.",
  "TCK m.83": "Madde 83- (1) Kişinin yükümlü olduğu belli bir icrai davranışı gerçekleştirmemesi dolayısıyla meydana gelen ölüm neticesinden sorumlu tutulabilmesi için, bu neticenin oluşumuna sebebiyet veren yükümlülük ihmalinin icrai davranışa eşdeğer olması gerekir.\n(2) İhmali ve icrai davranışın eşdeğer kabul edilebilmesi için, kişinin;\na) Belli bir icrai davranışta bulunmak hususunda kanuni düzenlemelerden veya sözleşmeden kaynaklanan bir yükümlülüğünün bulunması,\nb) Önceden gerçekleştirdiği davranışın başkalarının hayatı ile ilgili olarak tehlikeli bir durum oluşturması,\ngerekir.\n(3) Belli bir yükümlülüğün ihmali ile ölüme neden olan kişi hakkında, temel ceza olarak, ağırlaştırılmış müebbet hapis cezası yerine yirmi yıldan yirmibeş yıla kadar, müebbet hapis cezası yerine onbeş yıldan yirmi yıla kadar, diğer hallerde ise on yıldan onbeş yıla kadar hapis cezasına hükmolunabileceği gibi, cezada indirim de yapılmayabilir.",
  "TCK m.84": "Madde 84- (1) Başkasını intihara azmettiren, teşvik eden, başkasının intihar kararını kuvvetlendiren ya da başkasının intiharına herhangi bir şekilde yardım eden kişi, iki yıldan beş yıla kadar hapis cezası ile cezalandırılır.\n(2) İntiharın gerçekleşmesi durumunda, kişi dört yıldan on yıla kadar hapis cezası ile cezalandırılır.\n(3) Başkalarını intihara alenen teşvik eden kişi, üç yıldan sekiz yıla kadar hapis cezası ile cezalandırılır. (Mülga ikinci cümle: 29/6/2005 – 5377/10 md.)\n(4) İşlediği fiilin anlam ve sonuçlarını algılama yeteneği gelişmemiş olan veya ortadan kaldırılan kişileri intihara sevk edenlerle cebir veya tehdit kullanmak suretiyle kişileri intihara mecbur edenler, kasten öldürme suçundan sorumlu tutulurlar.",
  "TCK m.85": "Madde 85- (1) Taksirle bir insanın ölümüne neden olan kişi, iki yıldan altı yıla kadar hapis cezası ile cezalandırılır.\n(2) Fiil, birden fazla insanın ölümüne ya da bir veya birden fazla kişinin ölümü ile birlikte bir veya birden fazla kişinin yaralanmasına neden olmuş ise, kişi iki yıldan onbeş yıla kadar hapis cezası ile cezalandırılır.",
  "TCK m.86": "Madde 86- (1) Kasten başkasının vücuduna acı veren veya sağlığının ya da algılama yeteneğinin bozulmasına neden olan kişi, bir yıl altı aydan üç yıla kadar hapis cezası ile cezalandırılır.\n(2) (Ek fıkra: 31/3/2005 – 5328/4 md.) Kasten yaralama fiilinin kişi üzerindeki etkisinin basit bir tıbbî müdahaleyle giderilebilecek ölçüde hafif olması hâlinde, mağdurun şikâyeti üzerine, altı aydan bir yıl altı aya kadar hapis veya adlî para cezasına hükmolunur. (Ek cümle:12/5/2022-7406/3 md.) Suçun kadına karşı işlenmesi hâlinde cezanın alt sınırı dokuz aydan az olamaz.\n(3) Kasten yaralama suçunun;\na) Üstsoya, altsoya, eşe, boşandığı eşe veya kardeşe karşı,\nb) Beden veya ruh bakımından kendisini savunamayacak durumda bulunan kişiye karşı,\nc) Kişinin yerine getirdiği kamu görevi nedeniyle,\nd) Kamu görevlisinin sahip bulunduğu nüfuz kötüye kullanılmak suretiyle,\ne) Silahla,\nf) (Ek:14/4/2020-7242/11 md.) Canavarca hisle,\nİşlenmesi halinde, şikâyet aranmaksızın, verilecek ceza yarı oranında, (f) bendi bakımından ise bir kat artırılır.",
  "TCK m.87": "Madde 87- (1) Kasten yaralama fiili, mağdurun;\na) Duyularından veya organlarından birinin işlevinin sürekli zayıflamasına,\nb) Konuşmasında sürekli zorluğa,\nc) Yüzünde sabit ize,\nd) Yaşamını tehlikeye sokan bir duruma,\ne) Gebe bir kadına karşı işlenip de çocuğunun vaktinden önce doğmasına,\nNeden olmuşsa, yukarıdaki maddeye göre belirlenen ceza, bir kat artırılır. Ancak, verilecek ceza, birinci fıkraya giren hallerde dört yıldan, üçüncü fıkraya giren hallerde altı yıldan az olamaz.\n(2) Kasten yaralama fiili, mağdurun;\na) İyileşmesi olanağı bulunmayan bir hastalığa veya bitkisel hayata girmesine,\nb) Duyularından veya organlarından birinin işlevinin yitirilmesine,\nc) Konuşma ya da çocuk yapma yeteneklerinin kaybolmasına,\nd) Yüzünün sürekli değişikliğine,\ne) Gebe bir kadına karşı işlenip de çocuğunun düşmesine,\nNeden olmuşsa, yukarıdaki maddeye göre belirlenen ceza, iki kat artırılır. Ancak, verilecek ceza, birinci fıkraya giren hallerde altı yıldan, üçüncü fıkraya giren hallerde dokuz yıldan az olamaz.\n(3) (Değişik: 6/12/2006 – 5560/4 md.) Kasten yaralamanın vücutta kemik kırılmasına veya çıkığına neden olması halinde, yukarıdaki maddeye göre belirlenen ceza, kırık veya çıkığın hayat fonksiyonlarındaki etkisine göre, yarısına kadar artırılır.\n(4) Kasten yaralama sonucunda ölüm meydana gelmişse, yukarıdaki maddenin birinci fıkrasına giren hallerde on yıldan ondört yıla kadar, üçüncü fıkrasına giren hallerde ise ondört yıldan onsekiz yıla kadar hapis cezasına hükmolunur.",
  "TCK m.88": "Madde 88- (1) Kasten yaralamanın ihmali davranışla işlenmesi halinde, verilecek ceza üçte ikisine kadar indirilebilir. Bu hükmün uygulanmasında kasten öldürmenin ihmali davranışla işlenmesine ilişkin koşullar göz önünde bulundurulur.",
  "TCK m.89": "Madde 89- (1) Taksirle başkasının vücuduna acı veren veya sağlığının ya da algılama yeteneğinin bozulmasına neden olan kişi, dört aydan iki yıla kadar hapis veya adlî para cezası ile cezalandırılır.\n(2) Taksirle yaralama fiili, mağdurun;\na) Duyularından veya organlarından birinin işlevinin sürekli zayıflamasına,\nb) Vücudunda kemik kırılmasına,\nc) Konuşmasında sürekli zorluğa,\nd) Yüzünde sabit ize,\ne) Yaşamını tehlikeye sokan bir duruma,\nf) Gebe bir kadının çocuğunun vaktinden önce doğmasına,\nNeden olmuşsa, birinci fıkraya göre belirlenen ceza, yarısı oranında artırılır.\n(3) Taksirle yaralama fiili, mağdurun;\na) İyileşmesi olanağı bulunmayan bir hastalığa veya bitkisel hayata girmesine,\nb) Duyularından veya organlarından birinin işlevinin yitirilmesine,\nc) Konuşma ya da çocuk yapma yeteneklerinin kaybolmasına,\nd) Yüzünün sürekli değişikliğine,\ne) Gebe bir kadının çocuğunun düşmesine,\nNeden olmuşsa, birinci fıkraya göre belirlenen ceza, bir kat artırılır.\n(4) Fiilin birden fazla kişinin yaralanmasına neden olması halinde, dokuz aydan beş yıla kadar hapis cezasına hükmolunur.\n(5) (Değişik: 6/12/2006 – 5560/5 md.) Taksirle yaralama suçunun soruşturulması ve kovuşturulması şikâyete bağlıdır. Ancak, birinci fıkra kapsamına giren yaralama hariç, suçun bilinçli taksirle işlenmesi halinde şikâyet aranmaz.",
  "TCK m.90": "Madde 90- (1) İnsan üzerinde bilimsel deney yapan kişi 1-3 yıl. (Rızaya dayalı, izinli, önce insan dışı/hayvanda denenmiş, kalıcı zarar vermeyen, yazılı rızalı deney ceza sorumluluğu gerektirmez.) (4) Rıza olmaksızın tedavi amaçlı deneme 1 yıla kadar. — Madde 91- (1) Rızaya dayanmadan organ alma 5-9 yıl, doku 2-5 yıl. (2) Ölüden organ/doku 1 yıla kadar. (3) Satan/aracı → birinci fıkra cezası. (4) Örgütle 8-15 yıl + 10.000 gün adlî para. — Madde 92- (Zorunluluk hali) Organ/dokusunu satanın sosyal-ekonomik koşulları → indirim ya da ceza vermekten vazgeçilebilir. — Madde 93- (Etkin pişmanlık) Satan kişi resmî makamlar haber almadan haber verirse cezaya hükmolunmaz.",
  "TCK m.94": "Madde 94- (1) Bir kişiye karşı insan onuruyla bağdaşmayan ve bedensel veya ruhsal yönden acı çekmesine, algılama veya irade yeteneğinin etkilenmesine, aşağılanmasına yol açacak davranışları gerçekleştiren kamu görevlisi hakkında üç yıldan oniki yıla kadar hapis cezasına hükmolunur. (Ek cümle:12/5/2022-7406/4 md.) Suçun kadına karşı işlenmesi hâlinde cezanın alt sınırı beş yıldan az olamaz.\n(2) Suçun;\na) Çocuğa, beden veya ruh bakımından kendisini savunamayacak durumda bulunan kişiye ya da gebe kadına karşı,\nb) Avukata veya diğer kamu görevlisine karşı görevi dolayısıyla,\nİşlenmesi halinde, sekiz yıldan onbeş yıla kadar hapis cezasına hükmolunur.\n(3) Fiilin cinsel yönden taciz şeklinde gerçekleşmesi halinde, on yıldan onbeş yıla kadar hapis cezasına hükmolunur.\n(4) Bu suçun işlenişine iştirak eden diğer kişiler de kamu görevlisi gibi cezalandırılır.\n(5) Bu suçun ihmali davranışla işlenmesi halinde, verilecek cezada bu nedenle indirim yapılmaz.\n(6) (Ek: 11/4/2013-6459/9 md.) Bu suçtan dolayı zamanaşımı işlemez.",
  "TCK m.95": "Madde 95- (1) İşkence fiilleri, mağdurun;\na) Duyularından veya organlarından birinin işlevinin sürekli zayıflamasına,\nb) Konuşmasında sürekli zorluğa,\nc) Yüzünde sabit ize,\nd) Yaşamını tehlikeye sokan bir duruma,\ne) Gebe bir kadına karşı işlenip de çocuğunun vaktinden önce doğmasına,\nNeden olmuşsa, yukarıdaki maddeye göre belirlenen ceza, yarı oranında artırılır.\n(2) İşkence fiilleri, mağdurun;\na) İyileşmesi olanağı bulunmayan bir hastalığa veya bitkisel hayata girmesine,\nb) Duyularından veya organlarından birinin işlevinin yitirilmesine,\nc) Konuşma ya da çocuk yapma yeteneklerinin kaybolmasına,\nd) Yüzünün sürekli değişikliğine,\ne) Gebe bir kadına karşı işlenip de çocuğunun düşmesine,\nNeden olmuşsa, yukarıdaki maddeye göre belirlenen ceza, bir kat artırılır.\n(3) İşkence fiillerinin vücutta kemik kırılmasına neden olması halinde, kırığın hayat fonksiyonlarındaki etkisine göre sekiz yıldan onbeş yıla kadar hapis cezasına hükmolunur.\n(4) İşkence sonucunda ölüm meydana gelmişse, ağırlaştırılmış müebbet hapis cezasına hükmolunur.",
  "TCK m.96": "Madde 96- (1) Bir kimsenin eziyet çekmesine yol açacak davranışları gerçekleştiren kişi hakkında iki yıldan beş yıla kadar hapis cezasına hükmolunur. (Ek cümle:12/5/2022-7406/5 md.) Suçun kadına karşı işlenmesi hâlinde cezanın alt sınırı iki yıl altı aydan az olamaz.\n(2) Yukarıdaki fıkra kapsamına giren fiillerin;\na) Çocuğa, beden veya ruh bakımından kendisini savunamayacak durumda bulunan kişiye ya da gebe kadına karşı,\nb) Üstsoy veya altsoya, babalık veya analığa ya da eşe veya boşandığı eşe karşı,\nİşlenmesi halinde, kişi hakkında üç yıldan sekiz yıla kadar hapis cezasına hükmolunur.",
  "TCK m.97": "Madde 97- (1) Yaşı veya hastalığı dolayısıyla kendini idare edemeyecek durumda olan ve bu nedenle koruma ve gözetim yükümlülüğü altında bulunan bir kimseyi kendi haline terk eden kişi üç aydan iki yıla kadar hapis. (2) Terk dolayısıyla mağdur hastalanmış, yaralanmış veya ölmüşse neticesi sebebiyle ağırlaşmış suç hükümleri.\nMadde 98- (1) Yaşı, hastalığı veya yaralanması dolayısıyla ya da başka nedenle kendini idare edemeyecek durumdaki kimseye hal ve koşulların elverdiği ölçüde yardım etmeyen ya da durumu makamlara bildirmeyen kişi bir yıla kadar hapis veya adlî para. (2) Ölüm durumunda bir yıldan üç yıla kadar hapis.",
  "TCK m.99": "Madde 99- (1) Rızası olmaksızın bir kadının çocuğunu düşürten kişi beş yıldan on yıla kadar. (2) Tıbbi zorunluluk yokken, rızaya dayalı olsa bile gebelik süresi on haftadan fazla olan kadının çocuğunu düşürten iki yıldan dört yıla; rıza gösteren kadın bir yıla kadar. (3-4) Kadının sağlığına zarar/ölüm hallerinde ceza artar. — Madde 100- (1) Gebelik süresi on haftadan fazla olan kadın çocuğunu isteyerek düşürürse bir yıla kadar hapis veya adlî para. — Madde 101- (1) Bir erkek/kadını rızası olmaksızın kısırlaştıran üç yıldan altı yıla kadar; yetkisiz kişi yaparsa ceza 1/3 artar. (2) Rızaya dayalı olsa bile yetkisiz kişi yaparsa bir yıldan üç yıla kadar.",
  "Tebligat m.2": "Diğer kanunlarda özel hüküm bulunması halinde veya tehirinde zarar umulan işlerde veya aynı yerde bulunan 1 inci maddede yazılı daire ve müesseseler arasında veya bu daire ve müesseselerde bulunan şahıslara yapılacak tebligat, kendi memurları veya mahalli mülkiye amirinin emriyle zabıta vasıtasıyla yaptırılır. Zor kullanılmasını gerektiren veya hazırlık tahkikatına taallük eden vazifelerini zabıta tarafından yapılacağına dair olan hükümlerle bu kanunun ikinci babında yazılı hususi hükümler mahfuzdur.",
  "Tebligat m.21": "Kendisine tebligat yapılacak kimse veya yukarıdaki maddeler mucibince tebligat yapılabilecek kimselerden hiçbiri gösterilen adreste bulunmaz veya tebellüğden imtina ederse, tebliğ memuru tebliğ olunacak evrakı, o yerin muhtar veya ihtiyar heyeti azasından birine veyahut zabıta amir veya memurlarına imza mukabilinde teslim eder ve tesellüm edenin adresini ihtiva eden ihbarnameyi gösterilen adresteki binanın kapısına yapıştırmakla beraber, adreste bulunmama halinde tebliğ olunacak şahsa keyfiyetin haber verilmesini de mümkün oldukça en yakın komşularından birine, varsa yönetici veya kapıcıya da bildirilir. İhbarnamenin kapıya yapıştırıldığı tarih, tebliğ tarihi sayılır.",
  "Tebligat m.22": "Muhatap yerine kendisine tebliğ yapılacak kimsenin görünüşüne nazaran onsekiz yaşından aşağı olmaması ve bariz bir surette ehliyetsiz bulunmaması lazımdır.",
  "Tebligat m.24": "Kendisine tebliğ yapılacak kimse imza edecek kadar yazı bilmez veya imza edemiyecek durumda bulunursa, komşularından bir kişi huzurunda sol elinin baş parmağı bastırılmak suretiyle tebliğ yapılır. Sol elinin baş parmağı bulunmıyan kimsenin, aynı elinin diğer bir parmağı ve sol eli yoksa sağ elinin baş parmağı ve bu da mevcut değilse diğer parmaklarından biri bastırılır. Tebliğ yapılacak kimsenin iki eli de yoksa tebliğ evrakı kendisine verilir. Yukardaki fıkralarda yazılı hallerde keyfiyet, tebliğ mazbatasında tasrih edilir ve hazır bulunan şahsa da imza ettirilir. Okur yazar bir komşu bulunmaz veya bulunan komşu imzadan imtina ederse, tebliğ memuru o mahalle veya köyün muhtar veya ihtiyar heyeti azasından birini veyahut bir zabıta memurunu, tebliğ sırasında hazır bulunmak üzere davet eder ve tebligat bunların huzurunda yapılır.",
  "Tebligat m.3": "Posta ve Telgraf Teşkilatı Genel Müdürlüğünün bu Kanuna göre yapacağı işlerden dolayı alacağı ücretler, bu işletme tarafından ayrı bir tarife ile tespit ve tayin edilir.",
  "Terörizm Finansmanı m.10": "(1) Malvarlığının dondurulması kararına aykırı olarak yapılan her türlü tasarruf ve işlem hükümsüzdür. Bu tasarruf ve işlemlerle ilgili olarak 22/11/2001 tarihli ve 4721 sayılı Türk Medeni Kanununun iyiniyetin korunmasına ilişkin hükümleri saklıdır.",
  "Terörizm Finansmanı m.11": "(1) Bu Kanun hükümlerine göre alınan malvarlığının dondurulması ve bu kararın kaldırılmasına ilişkin kararlar Resmî Gazete'de yayımlanır. Bu kararlar yayımı tarihinde, hakkında malvarlığının dondurulması kararı verilen ilgili kişi ve kuruluşa tebliğ edilmiş sayılır. (2) Malvarlığının dondurulması kararında; kararın kimin hakkında verildiği, sebepleri, kapsamı, süresi ve bu karara karşı başvurulabilecek kanun yolları ile başvuru süresi yer alır.",
  "Terörizm Finansmanı m.12": "(3) Hakkında malvarlığının dondurulması kararı verilmiş olanlar, alacak ve borçları ile diğer tüm malvarlığı değerlerini ve bunların dayanağına ilişkin bilgileri; bunlardan alacağı veya borcu olan gerçek ve tüzel kişiler ise alacak veya borcun miktarı ile dayanağına ilişkin bilgileri, malvarlığının dondurulması kararının Resmî Gazete'de yayımlandığı tarihten itibaren en geç otuz gün içinde Başkanlığa bildirirler. (...) (5) Malvarlığının dondurulması kararının yerine getirilmesi talebinde bulunulan gerçek ve tüzel kişiler ile kamu kurum ve kuruluşları; nezdinde malvarlığı kaydı (...) bulunuyor ise dondurulan malvarlığına ilişkin bilgileri talep tarihinden itibaren yedi gün içinde Başkanlığa bildirir.",
  "Terörizm Finansmanı m.13": "(1) Dondurulmasına karar verilen malvarlığının yönetimi, ilgili gerçek veya tüzel kişiye aittir. Ancak (...) malvarlığı dondurulan kişiler bu malvarlığının ortadan kaldırılmasına, tüketilmesine, dönüştürülmesine, transferine, devir ve temlik edilmesine veya sair tasarruflara yönelik işlemlerde bulunamazlar. (2) (...) asgari geçimlerini sağlamak veya ticari işletmeler (...) faaliyetlerine devam edebilmelerini temin etmek üzere; a) Taşınmazlar ile (...) taşınırlar üzerinde sair kişiler lehine ayni veya şahsi hak tesisi (...) işlemleri Başkanlığın izniyle yapılabilir. (4) Taşınmazlar ile (...) taşınırlar üzerinde sair kişiler lehine ayni veya şahsi hak tesisine izin verilmesi hâlinde; a) Sözleşme metninin bir örneği, b) (...) ödeme bilgileri, hakkın tesis edildiği tarihten itibaren en geç on beş gün içinde Başkanlığa verilir.",
  "Terörizm Finansmanı m.14": "(1) Başkanlık; a) Nezdinde malvarlığı bulunduran kişi ve kuruluşların dondurma kararına uygun hareket edip etmediğini, b) Dondurulan malvarlığının yönetiminin bu Kanun hükümlerine uygun olarak yerine getirilip getirilmediğini, denetlemek, gerektiğinde ilgili defter, belge ve kayıtlar üzerinde araştırma ve incelemelerde bulunmak üzere 11/10/2006 tarihli ve 5549 sayılı (...) Kanunun 2 nci maddesinin birinci fıkrasının (e) bendinde belirtilen denetim elemanlarını veya Başkanlıkta istihdam edilen maliye uzmanlarını görevlendirir.",
  "Terörizm Finansmanı m.15": "(1) Bu Kanun hükümlerine göre malvarlığının dondurulmasıyla ilgili alınan kararın gereğini yerine getirmeyen veya yerine getirmekte ihmal veya gecikme gösteren kişilere, fiil daha ağır bir cezayı gerektiren başka bir suç oluşturmadığı takdirde, altı aydan iki yıla kadar hapis veya adli para cezası verilir. (2) Bu Kanunun 5 ila 7 nci maddeleri uyarınca hakkında malvarlığının dondurulması kararı verilen kişi, kuruluş veya organizasyonların yararına veya bunlar tarafından doğrudan veya dolaylı olarak kontrol edilen kuruluşlara ya da bunların adına veya hesabına hareket eden kişi veya kuruluşlara bu niteliklerini bilerek ve isteyerek fon sağlayan veya toplayan ya da finansal hizmet veren kişilere, fiil daha ağır bir cezayı gerektiren başka bir suç oluşturmadığı takdirde, bir yıldan üç yıla kadar hapis veya adli para cezası verilir.\n\n(3) Birinci fıkra kapsamında malvarlığının dondurulmasıyla ilgili alınan kararın gereğini yerine getirmeyen ya da ikinci fıkra kapsamında fon sağlayan veya toplayan ya da finansal hizmet veren kişinin, bir tüzel kişinin organ veya temsilcisi olması veya organ veya temsilcisi olmamakla birlikte, tüzel kişinin faaliyeti çerçevesinde görev üstlenmiş bulunması hâlinde ayrıca bu tüzel kişiye on bin Türk lirasından iki milyon Türk lirasına kadar idari para cezası verilir. Ancak bu fıkra uyarınca verilecek idari para cezası, tespit edilmesi hâlinde işleme konu edilen miktardan az olamaz.",
  "Terörizm Finansmanı m.16": "(1) Bu Kanunda hüküm bulunmayan hâllerde, 5549 sayılı Kanunun bu Kanuna aykırı olmayan hükümleri uygulanır. (2) Mevzuatta, bu Kanunla yürürlükten kaldırılan 3713 sayılı Kanunun 8 inci maddesine yapılan yollamalar bu Kanunun 4 üncü maddesine yapılmış sayılır.",
  "Terörizm Finansmanı m.2": "c) Fon: Para veya değeri para ile temsil edilebilen taşınır veya taşınmaz, maddi veya gayri maddi her türlü mal, hak, alacak ile bunları temsil eden her türlü belgeyi, (...) d) Malvarlığının dondurulması: Malvarlığının ortadan kaldırılmasının, tüketilmesinin, dönüştürülmesinin, transferinin, devir ve temlik edilmesinin ve sair tasarrufi işlemlerin önlenmesi amacıyla, malvarlığı üzerindeki tasarruf yetkisinin kaldırılması veya kısıtlanmasını, ifade eder.",
  "Terörizm Finansmanı m.3": "(1) Aşağıda sayılan fiillerin gerçekleştirilmesi amacıyla fon sağlanması veya toplanması yasaktır: a) Bir halkı korkutmak veya sindirmek ya da bir hükûmeti veya uluslararası kuruluşu herhangi bir eylemi gerçekleştirmeye veya gerçekleştirmekten kaçınmaya zorlamak amacıyla, kasten öldürme veya ağır yaralama fiilleri. b) 12/4/1991 tarihli ve 3713 sayılı Terörle Mücadele Kanunu kapsamında terör suçu olarak kabul edilen fiiller. c) Türkiye'nin taraf olduğu; (...) yasaklanan ve suç olarak düzenlenen fiiller.",
  "Terörizm Finansmanı m.4": "(1) 3 üncü madde kapsamında suç olarak düzenlenen fiillerin gerçekleştirilmesinde tümüyle veya kısmen kullanılması amacıyla veya kullanılacağını bilerek ve isteyerek belli bir fiille ilişkilendirilmeden dahi bir teröriste veya terör örgütlerine fon sağlayan veya toplayan kişi, fiili daha ağır cezayı gerektiren başka bir suç oluşturmadığı takdirde, beş yıldan on yıla kadar hapis cezası ile cezalandırılır. (...) (3) Birinci fıkra hükmüne göre ceza verilebilmesi için fonun bir suçun işlenmesinde kullanılmış olması şartı aranmaz.\n\n(2) Birinci fıkrada sayılan fiillerin, örgütü kuran veya yöneten ya da örgüt üyesi tarafından gerçekleştirilmesi hâlinde bu kişiler hakkında örgüt kurmak, yönetmek veya örgüte üye olmak suçları uyarınca verilecek ceza üçte birine kadar artırılır. (...) (4) Bu madde kapsamına giren suçların kamu görevinin sağladığı nüfuz kötüye kullanılmak suretiyle işlenmesi hâlinde, verilecek ceza yarı oranında artırılır.\n\n(5) Suçun bir tüzel kişinin faaliyeti çerçevesinde işlenmesi hâlinde, bunlara özgü güvenlik tedbirlerine hükmolunur. (6) Suçun, yabancı bir devlet veya uluslararası bir kuruluş aleyhine işlenmesi hâlinde, soruşturma ve kovuşturma yapılması Adalet Bakanının talebine bağlıdır. (7) 3713 sayılı Kanunun soruşturmaya, kovuşturmaya ve infaza ilişkin hükümleri, bu suç bakımından da uygulanır. (8) Bu suç bakımından 5271 sayılı Ceza Muhakemesi Kanununun; a) 133 üncü maddesinde yer alan şirket yönetimi için kayyım tayini, b) 135 inci maddesinde yer alan iletişimin tespiti, dinlenmesi ve kayda alınması, c) 139 uncu maddesinde yer alan gizli soruşturmacı görevlendirilmesi, ç) 140 ıncı maddesinde yer alan teknik araçlarla izleme, tedbirlerine ilişkin hükümler uygulanabilir. Ayrıca, 4208 sayılı Kanunda yer alan hükümlere göre kontrollü teslimat tedbirine karar verilebilir.",
  "Terörizm Finansmanı m.5": "(1) Birleşmiş Milletler Güvenlik Konseyinin 1267 (1999), 1988 (2011), 1989 (2011) ve 2253 (2015) sayılı kararlarıyla listelenen kişi, kuruluş veya organizasyonların tasarrufunda bulunan malvarlığının dondurulması kararları ve bu listelerden çıkarılanlara ilişkin malvarlığının dondurulmasının kaldırılması kararlarının uygulanmasına yönelik Cumhurbaşkanı kararı, Resmî Gazete'de yayımlanır ve gecikmeksizin uygulanır.",
  "Terörizm Finansmanı m.6": "(1) Bir yabancı devlet hükûmeti tarafından bir kişi, kuruluş veya organizasyonun tasarrufunda bulunan malvarlığının dondurulmasına ilişkin olarak Türkiye'den talepte bulunulması hâlinde, Değerlendirme Komisyonunca değerlendirilen talep Cumhurbaşkanı tarafından karara bağlanır. Bu değerlendirmede karşılıklılık ilkesi gözetilir. Karar verilebilmesi için, yabancı devlet tarafından taleple birlikte gerekçelerinin de gönderilmesi gerekir. (...) (5) Bu madde uyarınca verilen malvarlığının dondurulması kararının Resmî Gazete'de yayımlandığı tarihten itibaren bir yıl içinde, talep eden devlet tarafından soruşturma başlatılmadığı takdirde ilgili karar kaldırılabilir.",
  "Terörizm Finansmanı m.7": "(3) 5 inci ve 6 ncı maddelerde düzenlenen hususlar dışında, mahkemelerce terör örgütü olduğuna kesin olarak karar verildikten sonra 3 üncü ve 4 üncü madde kapsamına giren fiilleri gerçekleştirdiği hususunda makul sebeplerin varlığına istinaden kişi, kuruluş veya organizasyonların Türkiye'de bulunan malvarlığının dondurulmasına (...) Değerlendirme Komisyonunun önerisi üzerine Hazine ve Maliye Bakanı ile İçişleri Bakanı tarafından birlikte karar verilebilir. (4) (...) karar derhâl uygulanır ve kırk sekiz saat içinde, Hâkimler ve Savcılar Kurulu tarafından belirlenen Ankara ağır ceza mahkemesinin onayına sunulur. Mahkeme, makul sebeplerin varlığı yönünden yapacağı inceleme neticesinde malvarlığının dondurulması kararının devamına veya kaldırılmasına beş gün içinde karar verir ve sonucu derhâl Başkanlığa bildirir. Mahkemenin kararlarına karşı Ceza Muhakemesi Kanunu hükümlerine göre itiraz edilebilir.\n\n(4) (...) karar derhâl uygulanır ve kırk sekiz saat içinde, Hâkimler ve Savcılar Kurulu tarafından belirlenen Ankara ağır ceza mahkemesinin onayına sunulur. Mahkeme, (...) malvarlığının dondurulması kararının devamına veya kaldırılmasına beş gün içinde karar verir ve sonucu derhâl Başkanlığa bildirir. (5) Değerlendirme Komisyonu, Türkiye'de bulunan malvarlığının dondurulmasına ilişkin kararın Resmî Gazete'de yayımlanmasından itibaren en geç altışar aylık dönemlerle makul sebeplerin varlığının devam edip etmediğini değerlendirerek önerisini ilgili bakanlara sunar.",
  "Terörizm Finansmanı m.8": "(1) Malvarlığının dondurulması kararları hakkında yapılacak mali araştırma Başkanlık tarafından yerine getirilir. Bu görevin yerine getirilmesi amacıyla kamu kurum ve kuruluşları ile gerçek ve tüzel kişilerden talep edilen bilgiler istenilen usul, şekil ve sürede gecikmeksizin Başkanlığa iletilir. (...) (3) Araştırma sonuçları, Başkanlık tarafından Değerlendirme Komisyonuna sunulur. (4) Malvarlığının dondurulmasına ilişkin olarak yapılacak araştırma işlemleri gizlilik esaslarına uygun olarak yerine getirilir.",
  "Terörizm Finansmanı m.9": "(1) 5 inci maddenin dördüncü fıkrası ile 6 ncı ve 7 nci maddeler kapsamında malvarlığının dondurulmasıyla ilgili olarak Malvarlığının Dondurulmasını Değerlendirme Komisyonu oluşturulmuştur. (...) (3) Değerlendirme Komisyonu, birinci fıkrada sayılan üyeler veya bunların yerlerine usulüne uygun olarak atanan vekilleriyle toplanarak katılanların en az beşinin oyu ile karar verir. (4) Değerlendirme Komisyonunun sekretarya hizmetleri Başkanlık tarafından yürütülür.",
  "Terörle Mücadele m.1": "Terör; cebir ve şiddet kullanarak; baskı, korkutma, yıldırma, sindirme veya tehdit yöntemlerinden biriyle, Anayasada belirtilen Cumhuriyetin niteliklerini, siyasî, hukukî, sosyal, laik, ekonomik düzeni değiştirmek, Devletin ülkesi ve milletiyle bölünmez bütünlüğünü bozmak, Türk Devletinin ve Cumhuriyetin varlığını tehlikeye düşürmek, Devlet otoritesini zaafa uğratmak veya yıkmak veya ele geçirmek, temel hak ve hürriyetleri yok etmek, Devletin iç ve dış güvenliğini, kamu düzenini veya genel sağlığı bozmak amacıyla bir örgüte mensup kişi veya kişiler tarafından girişilecek her türlü suç teşkil eden eylemlerdir.",
  "Terörle Mücadele m.2": "Birinci maddede belirlenen amaçlara ulaşmak için meydana getirilmiş örgütlerin mensubu olup da, bu amaçlar doğrultusunda diğerleri ile beraber veya tek başına suç işleyen veya amaçlanan suçu işlemese dahi örgütlerin mensubu olan kişi terör suçlusudur. Terör örgütüne mensup olmasa dahi örgüt adına suç işleyenler de terör suçlusu sayılır (…).",
  "Terörle Mücadele m.3": "26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun 302, 307, 309, 311, 312, 313, 314, 315 ve 320 nci maddeleri ile 310 uncu maddesinin birinci fıkrasında yazılı suçlar, terör suçlarıdır.",
  "Terörle Mücadele m.4": "Aşağıdaki suçlar 1 inci maddede belirtilen amaçlar doğrultusunda suç işlemek üzere kurulmuş bir terör örgütünün faaliyeti çerçevesinde işlendiği takdirde, terör suçu sayılır: a) Türk Ceza Kanununun 79, 80, 81, 82, 84, 86, 87, 96, 106, 107, 108, 109, 112, 113, 114, 115, 116, 117, 118, 142, 148, 149, 151, 152, 170, 172, 173, 174, 185, 188, 199, 200, 202, 204, 210, 213, 214, 215, 223, 224, 243, 244, 265, 294, 300, 316, 317, 318 ve 319 uncu maddeleri ile 310 uncu maddesinin ikinci fıkrasında yer alan suçlar. b) (…) 6136 sayılı Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Kanunda tanımlanan suçlar. c) (…) 6831 sayılı Orman Kanununun 110 uncu maddesinin dördüncü ve beşinci fıkralarında tanımlanan kasten orman yakma suçları. ç) (…) 4926 sayılı Kaçakçılıkla Mücadele Kanununda tanımlanan ve hapis cezasını gerektiren suçlar. d) Anayasanın 120 nci maddesi gereğince olağanüstü hal ilan edilen bölgelerde, olağanüstü halin ilanına neden olan olaylara ilişkin suçlar. e) (…) 2863 sayılı Kültür ve Tabiat Varlıklarını Koruma Kanununun 68 inci maddesinde tanımlanan suç.",
  "Terörle Mücadele m.5": "3 ve 4 üncü maddelerde yazılı suçları işleyenler hakkında ilgili kanunlara göre tayin edilecek hapis cezaları veya adlî para cezaları yarı oranında artırılarak hükmolunur. Bu suretle tayin olunacak cezalarda, gerek o fiil için, gerek her nevi ceza için muayyen olan cezanın yukarı sınırı aşılabilir. Ancak, müebbet hapis cezası yerine, ağırlaştırılmış müebbet hapis cezasına hükmolunur. Suçun, örgütün faaliyeti çerçevesinde işlenmiş olması dolayısıyla ilgili maddesinde cezasının artırılması öngörülmüşse; sadece bu madde hükmüne göre cezada artırım yapılır. Ancak, yapılacak artırım, cezanın üçte ikisinden az olamaz. Bu madde hükümleri çocuklar hakkında uygulanmaz.",
  "Terörle Mücadele m.6": "İsim ve kimlik belirterek veya belirtmeyerek kime yönelik olduğunun anlaşılmasını sağlayacak surette kişilere karşı terör örgütleri tarafından suç işleneceğini veya terörle mücadelede görev almış kamu görevlilerinin hüviyetlerini açıklayanlar veya yayınlayanlar veya bu yolla kişileri hedef gösterenler bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Terör örgütlerinin; cebir, şiddet veya tehdit içeren yöntemlerini meşru gösteren veya öven ya da bu yöntemlere başvurmayı teşvik eden bildiri veya açıklamalarını basanlar veya yayınlayanlar bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Bu Kanunun 14 üncü maddesine aykırı olarak muhbirlerin hüviyetlerini açıklayanlar veya yayınlayanlar bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Yukarıdaki fıkralarda belirtilen fiillerin basın ve yayın yoluyla işlenmesi hâlinde, basın ve yayın organlarının suçun işlenişine iştirak etmemiş olan (…) yayın sorumluları hakkında da bin günden beşbin güne kadar adlî para cezasına hükmolunur.",
  "Terörle Mücadele m.7": "Cebir ve şiddet kullanılarak; baskı, korkutma, yıldırma, sindirme veya tehdit yöntemleriyle, 1 inci maddede belirtilen amaçlara yönelik olarak suç işlemek üzere, terör örgütü kuranlar, yönetenler ile bu örgüte üye olanlar Türk Ceza Kanununun 314 üncü maddesi hükümlerine göre cezalandırılır. Örgütün faaliyetini düzenleyenler de örgütün yöneticisi olarak cezalandırılır. Terör örgütünün; cebir, şiddet veya tehdit içeren yöntemlerini meşru gösterecek veya övecek ya da bu yöntemlere başvurmayı teşvik edecek şekilde propagandasını yapan kişi, bir yıldan beş yıla kadar hapis cezası ile cezalandırılır. Bu suçun basın ve yayın yolu ile işlenmesi hâlinde, verilecek ceza yarı oranında artırılır. (…) Haber verme sınırlarını aşmayan veya eleştiri amacıyla yapılan düşünce açıklamaları suç oluşturmaz. Aşağıdaki fiil ve davranışlar da bu fıkra hükümlerine göre cezalandırılır: a) (Mülga) b) Toplantı ve gösteri yürüyüşü sırasında gerçekleşmese dahi, terör örgütünün üyesi veya destekçisi olduğunu belli edecek şekilde; 1. Örgüte ait amblem, resim veya işaretlerin asılması ya da taşınması, 2. Slogan atılması, 3. Ses cihazları ile yayın yapılması, 4. Terör örgütüne ait amblem, resim veya işaretlerin üzerinde bulunduğu üniformanın giyilmesi. Terör örgütünün propagandasına dönüştürülen toplantı ve gösteri yürüyüşlerinde, kimliklerini gizlemek amacıyla yüzünü tamamen veya kısmen kapatanlar üç yıldan beş yıla kadar hapis cezasıyla cezalandırılır. Bu suçu işleyenlerin cebir ve şiddete başvurmaları ya da her türlü silah, molotof ve benzeri patlayıcı, yakıcı ya da yaralayıcı maddeler bulundurmaları veya kullanmaları hâlinde verilecek cezanın alt sınırı dört yıldan az olamaz.",
  "Toplantı/Gösteri m.10": "(Değişik: 3/8/2002-4771/5 md.) Toplantı yapılabilmesi için, düzenleme kurulu üyelerinin tamamının imzalayacakları bir bildirim, toplantının yapılmasından en az kırksekiz saat önce ve çalışma saatleri içinde, toplantının yapılacağı yerin bağlı bulunduğu valilik veya kaymakamlığa verilir. Bu bildirimde; a) Toplantının amacı, b) Toplantının yapılacağı yer, gün, başlayış ve bitiş saatleri, c) Düzenleme kurulunun başkan ile üyelerinin açık kimlikleri, meslekleri, ikametgahları ve varsa çalışma yerleri, Belirtilir ve bildirime yönetmelikte gösterilecek belgeler eklenir. Bu bildirim karşılığında gün ve saati gösteren alındı belgesi verilmesi zorunludur. Bu bildirim, valilik veya kaymakamlıkça kabul edilmez veya karşılığında alındı belgesi verilmez ise keyfiyet bir tutanakla tespit edilir. Bu halde noter vasıtasıyla ihbar yapılır. İhbar saati bildirimin verilme saati sayılır. Aynı yerde, aynı gün toplantı yapmak üzere ayrı ayrı düzenleme kurullarınca bildirim verilmişse ilk verilen bildirim geçerlidir. Diğerlerine durum hemen yazılı olarak bildirilir.",
  "Toplantı/Gösteri m.11": "Toplantı, 6 ncı madde hükümlerine uymak suretiyle bildirimde belirtilen yerde yapılır. Düzenleme kurulu, kendi üyelerinden başkan dahil en az yedi kişiyi toplantının yapıldığı yerde bulundurmakla yükümlüdür. (Değişik üçüncü cümle:...) Bu yükümlülüğün yerine getirildiğine dair tutulan tutanak, düzenleme kurulu tarafından hazırlanarak yetkili kolluk amirine teslim edilir. (Ek fıkra: 2/3/2014-6529/7 md.) Toplantı ve gösteri yürüyüşlerinde katılımcıların ve konuşmacıların ses ve görüntüleri kolluk tarafından yapıldığı belli olacak şekilde kaydedilebilir. Elde edilen kayıt ve görüntüler şüphelilerin ve suç delillerinin tespiti dışında başka bir amaçla kullanılamaz.",
  "Toplantı/Gösteri m.12": "Düzenleme kurulu, toplantının sükun ve düzenini, bildirimde yazılı amaç dışına çıkılmamasını sağlamakla yükümlü ve sorumludur. Kurul, bunun için gereken önlemleri alır ve gerektiğinde güvenlik kuvvetlerinin yardımını ister. (Değişik üçüncü cümle: 2/3/2014-6529/8 md.) Toplantının amacı dışına çıktığı veya düzen içinde gerçekleşmesini imkânsız gördüğü takdirde kurul veya toplanamadığı takdirde kurul başkanı dağılma kararı alır ve durumu derhâl yetkili kolluk amirine bildirir. Düzenleme kurulunun sorumluluğu, topluluk toplantı yerinden tamamen dağılıncaya kadar sürer.",
  "Toplantı/Gösteri m.14": "m.14: Toplantı, toplantının yapılacağı saatten en az yirmidört saat önce düzenleme kurulunun çoğunluğu tarafından, bildirimin verildiği valilik veya kaymakamlığa yazı ile bildirilmek şartıyla kırksekiz saati geçmemek üzere yalnız bir kez geri bırakılabilir. m.15: Bir il sınırı içinde aynı günde birden çok toplantı yapılmak istenmesi halinde vali (...) toplantılardan bir kısmını on günü aşmamak üzere bir kez erteleyebilir. Bu ertelemede müracaat önceliği göz önünde bulundurulur. m.16: (...) toplantı güvenliğini sağlamak amacıyla (...) takviye istenmesi halinde (...) takviye gönderilemeyen illerdeki toplantılar on günü aşmamak üzere bölge valiliğince (...) veya İçişleri Bakanlığınca bir kez ertelenebilir. m.17: (Değişik: 26/3/2002-4748/6 md.) Bölge valisi, vali veya kaymakam, millî güvenlik, kamu düzeni, suç işlenmesinin önlenmesi, genel sağlığın ve genel ahlâkın veya başkalarının hak ve özgürlüklerinin korunması amacıyla belirli bir toplantıyı bir ayı aşmamak üzere erteleyebilir veya suç işleneceğine dair açık ve yakın tehlike mevcut olması hâlinde yasaklayabilir. m.18: (...) gerekçeli erteleme veya yasaklama kararı toplantının başlama saatinden en az yirmidört saat önce bir yazı ile düzenleme kurulu başkanına veya bulunamadığı takdirde üyelerden birine tebliğ edilir. m.19: Bölge valisi (...) bölgeye dahil illerin birinde veya birkaçında ya da bir ilin bir veya birkaç ilçesinde bütün toplantıları bir ayı geçmemek üzere erteleyebilir. Valiler de aynı sebeplere dayalı olarak ve suç işleneceğine dair açık ve yakın tehlike mevcut olması hâlinde; ile bağlı ilçelerin birinde veya birkaçında bütün toplantıları bir ayı geçmemek üzere yasaklayabilir.",
  "Toplantı/Gösteri m.2": "a) Toplantı; belirli konular üzerinde halkı aydınlatmak ve bir kamuoyu yaratmak suretiyle o konuyu benimsetmek için gerçek ve tüzelkişiler tarafından bu Kanun çerçevesinde düzenlenen açık ve kapalı yer toplantılarını, b) Gösteri yürüyüşü; belirli konular üzerinde halkı aydınlatmak ve bir kamuoyu yaratmak suretiyle o konuyu benimsetmek için gerçek ve tüzelkişler tarafından bu Kanun çerçevesinde düzenlenen yürüyüşleri, İfade eder.\n\nc) Mahallin en büyük mülki amiri; illerde vali, ilçelerde kaymakamı, d) (...) Mahallin güvenlik amirleri; illerde il emniyet müdürü ve il jandarma komutanını, ilçelerde ilçe emniyet amiri veya komiseri ve ilçe jandarma komutanını, Sahil Güvenlik Komutanlığı için Sahil Güvenlik Bölge Komutanını, Sahil Güvenlik Grup Komutanını ve Sahil Güvenlik Karakol Komutanı ile Sahil Güvenlik Gemi/Bot Komutanını, İfade eder. Bir il'e bağlı ilçelerin, o ilin belediye sınırları içindeki kısımlarına ilişkin olarak bu Kanunun uygulaması yönünden mahallin en büyük mülki amiri, ilin valisidir.",
  "Toplantı/Gösteri m.22": "(...) parklarda, mabetlerde, kamu hizmeti görülen bina ve tesislerde ve bunların eklentilerinde ve Türkiye Büyük Millet Meclisine bir kilometre uzaklıktaki alan içinde toplantı yapılamaz (...). Genel meydanlardaki toplantılarda, halkın ve ulaşım araçlarının gelip geçmesini sağlamak üzere valilik ve kaymakamlıklarca yapılacak düzenlemelere uyulması zorunludur.",
  "Toplantı/Gösteri m.23": "a) 9 ve 10 uncu madde hükümlerine uygun biçimde bildirim verilmeden veya toplantı veya yürüyüş için belirtilen gün ve saatten önce veya sonra; b) (Değişik:...) Ateşli silahlar veya havai fişek, molotof ve benzeri el yapımı olanlar dâhil patlayıcı maddeler veya her türlü kesici, delici aletler veya taş, sopa, demir ve lastik çubuklar (...) ile yasadışı örgüt ve topluluklara ait amblem ve işaret taşınarak veya bu işaret ve amblemleri üzerinde bulunduran üniformayı andırır giysiler giyilerek veya kimliklerini gizlemek amacıyla yüzlerini tamamen veya kısmen bez vesair unsurlarla örterek (...) katılma (...) c) 7 nci madde hükümleri gözetilmeksizin, d) 6 ve 10 uncu maddeler gereğince belirtilen yerler dışında, (...) g) Kanunların suç saydığı maksatlar için, h) Bildirimde belirtilen amaç dışına çıkılarak, (...) j) 12 nci madde gereğince toplantının dağılmasına karar verilmesi hâlinde, (...) Yapılan toplantılar veya gösteri yürüyüşleri Kanuna aykırı sayılır.",
  "Toplantı/Gösteri m.24": "(...) Kanuna uygun olarak başlayan bir toplantı veya gösteri yürüyüşü, daha sonra 23 üncü maddede belirtilen kanuna aykırı durumlardan bir veya birkaçının vuku bulması sebebiyle, Kanuna aykırı toplantı veya gösteri yürüyüşü hâline dönüşürse: a) Düzenleme kurulu veya kurul başkanı toplantı veya gösteri yürüyüşünün sona erdiğini topluluğa ilan eder ve durumu derhâl yetkili kolluk amirine bildirir. b) Düzenleme kurulunun veya kurul başkanının bu görevi yerine getirmemesi hâlinde, durum yetkili kolluk amiri tarafından mahallin en büyük mülki amirine bildirilir. Mahallin en büyük mülki amiri tarafından toplantının sona erdirilip erdirilmeyeceğine dair karar alınır. c) Mahallin en büyük mülki amiri, yazılı veya acele hâllerde sonradan yazı ile teyit edilmek kaydıyla sözlü emirle, mahallin güvenlik amirlerini veya bunlardan birini görevlendirerek olay yerine gönderir. Bu amir, topluluğa Kanuna uyularak dağılmalarını, dağılmazlarsa zor kullanılacağını ihtar eder. Topluluk dağılmazsa zor kullanılarak dağıtılır.",
  "Toplantı/Gösteri m.25": "Topluluk içinde suç işleyenleri ve suçluları yakalamak için 24 üncü maddede belirtilen emir ve ihtarların yapılmasına gerek yoktur.",
  "Toplantı/Gösteri m.26": "Toplantı veya yürüyüşlere ilişkin çağrı veya propoganda amacıyla kullanılan basılı veya çoğaltılmış veya el ile yazılmış davetiye, levha ve ilanlarda düzenleme kurulu başkanı ile en az altı üyesinin adları, soyadları ve imzalarının bulunması; bunlardan asılması gerekenlerin, Kanunun 6 ncı maddesinde belirtilen yönteme de uyulmak şartıyla valilik veya kaymakamlıklarca önceden tespit edilmiş yerlere asılması zorunludur. Bu propaganda ve çağrı alet ve araçlarında, halkı suç işlemeye özendiren veya kışkırtan yazı veya resim bulunması yasaktır. Toplantı veya gösteri yürüyüşünün yapılacağı tarihten bir önceki günden toplantı veya gösteri yürüyüşünün başlayacağı saate kadar, güneşin doğuşundan batışına kadarki zaman içinde olmak kaydıyla ses yükselten veya ileten herhangi bir alet veya araç ile çağrı yapılabilir. Bu süre dışında çağrı için sözü geçen alet veya araçlar kullanılamaz. Kapalı yer toplantılarında, ses yükseltici alet veya araçlarla dışarıya yayın yapılamaz.",
  "Toplantı/Gösteri m.27": "Halka karşı, doğrudan doğruya veya ses yükselten veya ileten herhangi bir alet veya araç ile söz söyleyerek veya seslenerek veya basılmış veya çoğaltılmış veya elle yazılmış veya çizilmiş kağıtları duvarlara veya diğer yerlere yapıştırarak veya dağıtarak veya benzeri araç ve yollarla halkı Kanuna aykırı toplantı veya yürüyüşe özendirmek veya kışkırtmak yasaktır. Bu hareketler güvenlik kuvvetlerince derhal menedilir.",
  "Toplantı/Gösteri m.29": "m.29: Toplantı veya yürüyüş yapılmasına engel olan veya devamına imkan vermeyecek tertipler ile toplantı veya yürüyüşü ihlal eden kimse (...) dokuz aydan bir yıl altı aya kadar hapis (...) cezası ile cezalandırılır. m.30: Yapılmakta olan toplantı veya yürüyüşte huzur ve sükûnu bozmak maksadıyla tehdit veya hakaret veya saldırı veya mukavemette bulunanlar (...) bir yıl altı aydan üç yıla kadar hapis (...). m.31: Düzenleme kurulu başkanı ve en az altı üyesinin ad ve soyadları ile imzalarını taşımayan 26 ncı maddede yazılı propaganda vasıtalarını (...) kullananlar veya sair surette 26 ncı maddedeki yasak ve şartlara uymayanlar altı aydan bir yıla kadar hapis (...); halkı suç işlemeye teşvik ve tahrik eder mahiyette yazı veya resim (...) bulunursa (...) bir yıl altı aydan üç yıla kadar (...); teşvik ve tahrik neticesi olarak suç işlenir veya suçun icrasına teşebbüs edilirse (...) üç yıldan beş yıla kadar hapis (...). m.32: (Değişik: 22/7/2010-6008/1 md.) Kanuna aykırı toplantı veya gösteri yürüyüşlerine katılanlar, ihtara ve zor kullanmaya rağmen dağılmamakta ısrar ederlerse, altı aydan üç yıla kadar hapis (...); bu suçu tertip edenlerin işlemesi halinde ceza yarı oranında artırılarak hükmolunur. m.33: (Değişik: 22/7/2010-6008/2 md.) Toplantı ve gösteri yürüyüşlerine; a) Ateşli silahlar (...) veya kimliklerini gizlemek amacıyla yüzlerini (...) örterek katılanlar iki yıl altı aydan dört yıla kadar, b) Yasadışı örgüt ve topluluklara ait amblem ve işaret taşıyarak (...) veya kanunların suç saydığı nitelik taşıyan afiş, pankart (...) taşıyarak (...) katılanlar altı aydan üç yıla kadar, hapis cezası ile cezalandırılırlar. m.34: 27 nci maddedeki yasağa aykırı hareket edenler toplantı veya yürüyüş vukubulmamış veya vukubulmuş olup da ilk emir ve ihtar üzerine dağıtılmış ise (...) bir yıl altı aydan dört yıla, toplantı ve yürüyüş zorla dağıtılmış ise üç yıldan beş yıla kadar hapis cezası ile cezalandırılır.",
  "Toplantı/Gösteri m.3": "Herkes, önceden izin almaksızın, bu Kanun hükümlerine göre silahsız ve saldırısız olarak kanunların suç saymadığı belirli amaçlarla toplantı ve gösteri yürüyüşü düzenleme hakkına sahiptir. (Değişik:...) Yabancıların bu Kanun hükümlerine göre toplantı ve gösteri yürüyüşü düzenlemeleri, İçişleri Bakanlığının iznine bağlıdır. Yabancıların bu Kanuna göre düzenlenen toplantı ve gösteri yürüyüşlerinde topluluğa hitap etmeleri, afiş, pankart, resim, flama, levha, araç ve gereçler taşımaları, toplantının yapılacağı mahallin en büyük mülkî idare amirliğine toplantıdan en az kırksekiz saat önce yapılacak bildirimle mümkündür.",
  "Toplantı/Gösteri m.4": "Aşağıda belirtilen toplantı ve faaliyetler bu Kanun hükümlerine tabi değildir. a) Siyasi partilerin, kamu kurumu niteliğindeki meslek kuruluşlarının, sendikaların, vakıfların, derneklerin, ticari ortaklıkların ve diğer tüzelkişilirin özel kanunlarına ve kendi tüzüklerine göre yapacakları kapalı yer toplantıları, b) Kanunlara uymak, kendi kural ve sınırları içinde kalmak şartıyla kanun veya gelenek ve göreneklere göre yapılacak toplantı, tören, şenlik, karşılama ve uğurlamalar, c) Spor faaliyetleri ile bilimsel, ticari ve ekonomik amaçlarla yapılan toplantılar, d) Cumhurbaşkanı, Cumhurbaşkanı yardımcıları ve bakanların Devlet (...) işleri hakkındaki toplantı ve konuşmaları ile Türkiye Büyük Millet Meclisi üyelerinin halk ile yapacakları sohbet niteliğindeki görüşmeler.",
  "Toplantı/Gösteri m.5": "Seçim zamanlarında yapılacak propaganda toplantıları ile ilgili kanun hükümleri saklıdır.",
  "Toplantı/Gösteri m.6": "(Değişik:...) (...) İl ve ilçelerde toplantı ve gösteri yürüyüşü yer ve güzergâhı, kamu düzenini ve genel asayişi bozmayacak, vatandaşların günlük yaşamını aşırı ve katlanılmaz derecede zorlaştırmayacak (...) şekilde ve 22 nci maddenin birinci fıkrasında sayılan sınırlamalara uyulması kaydıyla Türkiye Büyük Millet Meclisinde grubu bulunan siyasi partilerin il ve ilçe temsilcileri ile güzergâhın geçeceği ilçe ve il belediye başkanlarının, en çok üyeye sahip üç sendikanın ve kamu kurumu niteliğindeki meslek kuruluşlarının il ve ilçe temsilcilerinin görüşleri alınarak mahallin en büyük mülki amiri tarafından belirlenir. (...) Toplantı ve gösteri yürüyüşleri yer ve güzergâhı hakkında sonradan yapılacak değişiklikler de aynı yöntemle yapılır. Bu değişiklikler duyurudan on beş gün sonra geçerli olur.",
  "Toplantı/Gösteri m.7": "Toplantı ve yürüyüşlere ve bu amaçla toplanmalara güneş doğmadan başlanamaz.\" (Not: ikinci fıkra Anayasa Mahkemesi'nin 30/6/2022 tarihli kararı ile iptal edilmiştir; yalnız bu birinci fıkra yürürlüktedir.)",
  "Toplantı/Gösteri m.8": "Toplantının yapıldığı yer, toplantı süresince umuma açık yer sayılır.",
  "Toplantı/Gösteri m.9": "(Değişik:26/3/2002-4748/6 md.) Bu Kanuna göre yapılacak toplantılar, fiil ehliyetine sahip ve onsekiz yaşını doldurmuş, en az yedi kişiden oluşan bir düzenleme kurulu tarafından düzenlenir. Bu kurul, kendi aralarından birini başkan seçer. Diplomatik dokunulmazlıkları bulunan kişiler, düzenleme kurulu başkan veya üyesi olamazlar. Tüzel kişilerin toplantı ve gösteri yürüyüşü düzenlemeleri, yetkili organlarının kararına bağlıdır.",
  "Trafik m.107": "Bir motorlu aracı çalan veya gasbeden kimse işleten gibi sorumlu tutulur. Aracın çalınmış veya gasbedilmiş olduğunu bilen veya gereken özen gösterildiği takdirde öğrenebilecek durumda olan aracın sürücüsü de onunla birlikte müteselsilen sorumludur. İşleten, kendisinin veya eylemlerinden sorumlu olduğu kişilerden birinin, aracın çalınmasında veya gasbedilmesinde kusurlu olmadığını ispat ederse, sorumlu tutulamaz.",
  "Trafik m.109": "Motorlu araç kazalarından doğan maddi zararların tazminine ilişkin talepler, zarar görenin, zararı ve tazminat yükümlüsünü öğrendiği tarihten başlayarak iki yıl ve herhalde, kaza gününden başlayarak on yıl içinde zamanaşımına uğrar. Dava, cezayı gerektiren bir fiilden doğar ve ceza kanunu bu fiil için daha uzun bir zaman aşımı süresi öngörmüş bulunursa, bu süre, maddi tazminat talepleri için de geçerlidir. ...rücu hakları, ...iki yılda zamanaşımına uğrar.",
  "Trafik m.112": "Bu Kanunun 6 ncı maddesinde sayılan görevlilerin ve trafik tescil kuruluşlarının yetkilendirildiği hâller hariç olmak üzere, sürücü belgelerinin geri alınmasına ve iptaline sulh ceza mahkemeleri karar verir. Bu Kanunun 51 inci maddesinin ihlali ve 118 inci maddesinin ikinci ve üçüncü fıkralarında yazılı '100 ceza puanını doldurmak' eylemi nedeniyle sürücü belgelerinin geri alınmasına yine bu Kanunun 6 ncı maddesinde sayılan görevliler yetkilidir.",
  "Trafik m.114": "Bu Kanunda yazılı trafik suçlarını işleyenler hakkında yetki sınırları içinde Emniyet Genel Müdürlüğü ve Jandarma Genel Komutanlığı personeli ile Ulaştırma ve Altyapı Bakanlığının ve Karayolları Genel Müdürlüğünün ilgili birimlerinin il ve ilçe kuruluşlarında görevli ve yetkili kılınmış personelince tutanak düzenlenir. (2026) ...tutanaklara, görevli ve yetkili personelin açık kimliği yerine personel tanıtım numarası yazılır. Birkaç trafik suçunun bir arada işlenmesi halinde her suç için ayrı ceza uygulanır. Yargı yetkisine giren suçlarla ilgili tutanağın bir sureti ilgili mahkemeye 7 iş günü içinde gönderilir.",
  "Trafik m.115": "Ödeme derhal yapılmadığı takdirde para cezalarının, tutanağın tebliğ tarihinden itibaren bir ay içinde ödenmesi gerekir. Bir ay içinde ödenmeyen cezalar için her ay % 5 faiz uygulanır. Aylık faizin hesaplanmasında ay kesirleri tam ay olarak dikkate alınır. Bu suretle bulunacak tutar cezanın iki katını geçemez. Süresinde ödenmeyen para cezaları için 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanun Hükümleri uygulanır.",
  "Trafik m.118": "(...) Trafik suçunun işlendiği tarihten geriye doğru bir yıl içinde toplam 100 ceza puanını dolduran sürücülerin sürücü belgeleri 2 ay süre ile geri alınır ve eğitime tabi tutulurlar. Aynı yıl içinde ikinci defa 100 puanı dolduran sürücülerin sürücü belgeleri 4 ay süre ile geri alınarak psiko-teknik değerlendirmeye ve psikiyatri uzmanının muayenesine tabi tutulurlar. (...) Bir yıl içinde üç defa 100 ceza puanını dolduran sürücülerin sürücü belgeleri süresiz olarak iptal edilir. Ölümle sonuçlanan trafik kazalarına asli kusurlu olarak sebebiyet veren sürücülerin sürücü belgeleri ise 1 yıl süre ile geri alınır.",
  "Trafik m.12": "İl sınırları içinde (...) illerde vali veya yardımcısının başkanlığında, belediye, emniyet, jandarma, milli eğitim, karayolları ve Türkiye Şoförler ve Otomobilciler Federasyonuna bağlı ilgili odanın temsilcileri; (...) İl Trafik Komisyonu, ilçelerde kaymakamın başkanlığında, aynı kuruluşların yöneticileri veya görevlendirecekleri temsilcilerinin katıldığı İlçe Trafik Komisyonu kurulur. Kararlar oy çokluğu ile alınır. Oyların eşitliği halinde başkanın bulunduğu taraf çoğunluk sayılır. İl Trafik Komisyonu kararları valinin onayı ile yürürlüğe girer. İlçe Trafik Komisyonu kararları, İl Trafik Komisyonunca incelenip vali tarafından onaylandıktan sonra yürürlüğe girer.\n\n...illerde vali veya yardımcısının başkanlığında, belediye, emniyet, jandarma, milli eğitim, karayolları ve Türkiye Şoförler ve Otomobilciler Federasyonuna bağlı ilgili odanın temsilcileri; Valilikçe uygun görülen trafikle ilgili üniversite, oda, vakıf ve kamuya yararlı dernek veya kuruluşların birer temsilcisinden oluşan İl Trafik Komisyonu, ilçelerde kaymakamın başkanlığında, aynı kuruluşların yöneticileri veya görevlendirecekleri temsilcilerinin katıldığı İlçe Trafik Komisyonu kurulur. Kuruldaki üniversite, vakıf ve kamuya yararlı dernek veya kuruluşların temsilcilerinin toplam sayısı 3'ü geçemez. Gündem konuları vali veya kaymakamlar tarafından belirlenir. İl Trafik Komisyonu kararları valinin onayı ile yürürlüğe girer; İlçe Trafik Komisyonu kararları İl Trafik Komisyonunca incelenip vali tarafından onaylandıktan sonra yürürlüğe girer. Görev ve yetkiler: 1. ...trafik düzeni ve güvenliğini sağlamak amacıyla gerekli tedbirleri almak, 2. ...alt yapı hizmetleri ile ilgili tedbirleri almak, ... Trafik Güvenliği Yüksek Kurulunun müdahalesini gerektiren hususları İçişleri Bakanlığına iletmek, 3. ...belediye sınırları içinde ticari amaçla çalıştırılacak yolcu ve yük taşıtları ile motorsuz taşıtların çalışma şekil ve şartları, çalıştırılabileceği yerler ile güzergahlarını tespit etmek ve sayılarını belirlemek, 4. ...boş alan, arazi ve arsaları geçici otopark yeri olarak ilan etmek...",
  "Trafik m.126": "Olağanüstü hallerde ve savaşta karayolunun kullanılması, trafiğin düzenlenmesi ve yönetimi esasları Genelkurmay Başkanlığının görüşü alınarak yönetmelikte belirtilir. Barışta, bu düzenleme ve yönetimi denemek için yapılacak manevra ve tatbikatlarda Genelkurmay Başkanlığının istemi üzerine özel uygulamalar yapılabilir.",
  "Trafik m.20": "Tescili zorunlu ve ilk tescili yapılacak olan araçların satın alma veya gümrükten çekme tarihinden itibaren üç ay içinde tescili için; bunların hurda durumuna gelmesi hâlinde ise bir ay içinde tescilin silinmesi için ilgili trafik tescil kuruluşuna (...) başvurmak (...) zorundadırlar. (...) Tescil edilmiş araçların her çeşit satış ve devirleri, (...) noterler tarafından yapılır. Noterler tarafından yapılmayan her çeşit satış ve devirler geçersizdir. (...) Yapılan satış ve devir işlemi üzerine noterler tarafından yeni malik adına bir ay süreyle geçerli tescile ilişkin geçici belge düzenlenir.\n\na-2) Tescilin yapılması veya silinmesi için vergi kimlik numarası ile yönetmelikte belirtilen bilgi ve belgeleri sağlamak zorundadırlar. b) Araçların giriş işlemlerini yapan gümrük idareleri bu durumu 15 gün içinde araç sahiplerinin beyan ettikleri tescil kuruluşuna bildirmekle yükümlüdürler. c) Tescil belgesi, aracın başkasına satış veya devrine, hurdaya çıkarılmasına veya araçta, yönetmelikte belirtilen niteliklerin değişmesine kadar geçerli sayılır.\n\ne) Araç satın alıp, bu maddenin birinci fıkrasının (a) bendinin (1) numaralı alt bendine uymayanlar ile (d) bendinin sekizinci paragrafı hükümlerine göre bir ay içerisinde tescil belgesi almayan alıcılara ... (d) bendi hükümlerine uymayan noterlere ise her bir işlem için ... idari para cezası verilir. Tescil yapılmadan trafiğe çıkarılan araçlar, tescil yapılıncaya kadar trafikten men edilir. f) (Ek:12/2/2026-7574/2) Araç sahiplerinin vefat etmesi halinde mirasçılar, gerekli bilgi ve belgeleri sağlayarak vefat tarihinden itibaren doksan gün içerisinde ilgili tescil kuruluşuna müracaat etmek ve adlarına tescil belgesi almak zorundadırlar... Bu araçların süresi sonunda mirasçılar adına tescil edilmeden karayoluna çıkarıldığının tespiti halinde sürücüye idari para cezası verilir ve ... araç trafikten menedilir.\" *(İPC TL tutarları yıllık değişir; kartta yazılmaz.)*\n\nd) (...) Tescil edilmiş araçların her çeşit satış ve devirleri, satış ve devri yapılacak araçtan dolayı motorlu taşıtlar vergisi, gecikme faizi, gecikme zammı, vergi cezası ve trafik idari para cezası borcu bulunmadığının tespit edilmesi ve taşıt üzerinde satış ve/veya devri kısıtlayıcı herhangi bir tedbir veya kayıt bulunmaması halinde, araç sahibi adına düzenlenmiş tescil belgesi veya trafik tescil kayıtları esas alınarak noterler tarafından yapılır. Noterler tarafından yapılmayan her çeşit satış ve devirler geçersizdir. Satış ve devir işlemi, siciline işlenmek üzere üç işgünü içerisinde ilgili trafik tescil kuruluşu ile vergi dairesine bildirilir. Bu bildirimle birlikte alıcı adına trafik tescil işlemi gerçekleşmiş sayılır. (...) Yapılan satış ve devir işlemi üzerine noterler tarafından yeni malik adına bir ay süreyle geçerli tescile ilişkin geçici belge düzenlenir.",
  "Trafik m.22": "a) Askeri maksatlarla kullanılan Türk Silahlı Kuvvetlerine ait bütün araçlar ... tescilleri Türk Silahlı Kuvvetlerince, b) Raylı sistemle çalışan araçların tescilleri, kullanıldığı yerlere göre ait olduğu kuruluşlarca, c) İş makinesi türünden araçların tescilleri; 1. Kamu kuruluşlarına ait olanlar ilgili kuruluşlarınca, 2. Özel veya tüzelkişilere ait olanlardan tarım kesiminde kullanılanlar ziraat odalarınca, ...sanayi, bayındırlık ve diğer kesimlerde kullanılanların tescilleri üyesi oldukları ticaret, sanayi veya ticaret ve sanayi odalarınca, d) Tarım kesiminde kullanılanlar hariç, İl Trafik Komisyonlarından karar alınmak şartı ile motorsuz taşıtlardan gerekli görülenlerin tescilleri belediyelerce, e) Jandarma Genel Komutanlığı ile Sahil Güvenlik Komutanlığına ait bütün araçların tescilleri Emniyet Genel Müdürlüğünce yapılır... Birinci fıkrada sayılanlar dışında kalan bütün araçların tescilleri ... Emniyet Genel Müdürlüğü veya bağlı trafik tescil kuruluşlarınca yapılır.",
  "Trafik m.23": "Araç tescil belgesi ve tescil plakasının, araç üzerinde uygun durumda bulundurulması zorunludur. Araç tescil belgesini araçta bulundurmayan veya tescil plakasını monte edilmesi gereken yerin dışında farklı bir yere takan sürücülere ... idari para cezası verilir... Yönetmelikte belirtilen nitelik veya ölçülere aykırı plaka takan, öngörülen sayıda plaka takmayan sürücülere ... Tescil plakasının farklı okunmasına veya okunamamasına bilerek neden olacak şekilde plakasında değişiklik yapan sürücülere ... araç otuz gün süre ile trafikten menedilir... Tescilli aracı plakasız kullanan sürücülere ... sürücü belgeleri otuz gün süreyle geri alınır ve araç otuz gün süre ile trafikten menedilir... Başka bir araca ait tescil plakasını ... sahte plakayı takan veya kullananlara ... Ayrıca bu kişiler Türk Ceza Kanununun 204 üncü maddesi hükmüne göre cezalandırılır.\" *(2026-7574/4. İPC TL tutarları yıllık değişir; kartta yazılmaz.)*",
  "Trafik m.3": "Geçiş hakkı: Yayaların ve araç kullananların diğer yaya ve araç kullananlara göre, yolu kullanmak sırasındaki öncelik hakkıdır. Geçiş üstünlüğü: Görev sırasında, belirli araç sürücülerinin can ve mal güvenliğini tehlikeye sokmamak şartı ile trafik kısıtlama veya yasaklarına bağlı olmamalarıdır.\n\nDurma: Her türlü trafik zorunlulukları nedeni ile aracın durdurulmasıdır. Duraklama: Trafik zorunlulukları dışında araçların, insan indirmek ve bindirmek, eşya yüklemek, boşaltmak veya beklemek amacı ile kısa bir süre için durdurulmasıdır. Park etme: Araçların, durma ve duraklaması gereken haller dışında bırakılmasıdır.\n\nBanket: Yaya yolu ayrılmamış karayolunda, taşıt yolu kenarı ile şev başı veya hendek iç üst kenarı arasında kalan ve olağan olarak yayaların ve hayvanların kullanacağı, zorunlu hallerde de araçların faydalanabileceği kısımdır. Ada: Yayaların geçme ve durmalarına, taşıtlardan inip binmelerine yarayan, trafik akımını düzenleme ve trafik güvenliğini sağlama amacı ile yapılmış olan, araçların bulunamayacağı, koruyucu tertibatla belirlenmiş bölüm ve alanlardır. Ayırıcı: Taşıt yollarını veya yol bölümlerini birbirinden ayıran, bir taraftaki taşıtların diğer tarafa geçmesini engelleyen veya zorlaştıran karayolu yapısı, trafik tertibatı veya gereçtir. Römork: Motorlu araçla çekilen insan veya yük taşımak için imal edilmiş motorsuz taşıttır. Yarı römork: Bir kısmı motorlu taşıt veya araç üzerine oturan, taşıdığı yükün ve kendi ağırlığının bir kısmı motorlu araç tarafından taşınan römorkdur. Hafif römork: Azami yüklü ağırlığı 750 Kg'ı geçmeyen römork veya yarı römorkdur. Gabari: Araçların, yüklü veya yüksüz olarak karayolunda güvenli seyirlerini temin amacı ile uzunluk, genişlik ve yüksekliklerini belirleyen ölçülerdir. Dingil ağırlığı: Araçlarda aynı dingile bağlı tekerleklerden karayolu yapısına aktarılan ağırlıktır.",
  "Trafik m.31": "Cinslerine, özelliklerine ve kullanım amaçlarına göre; a) Araçlarda, nitelik ve nicelikleri yönetmelikte belirtilen gereçlerin, b) Yük taşımada kullanılan ve azami yüklü ağırlığı 3.500 kilogramdan fazla olan motorlu taşıtlar ile ... yolcu taşımacılığı faaliyetlerinde kullanılan ve sürücüsü dahil oturma yeri on yediden fazla olan motorlu taşıtlarda takograf, c) Taksi hizmeti veren otomobillerde taksimetre, d) Özellikleri, model yılları ve cinsleri yönetmelikte belirtilen araçlarda hız sınırlayıcı, bulundurulması, kullanılır durumda olması ve kullanılması zorunludur.",
  "Trafik m.32": "Araçlar üzerinde mevzuata uygun şekilde yapılan her türlü değişikliğin işleten tarafından otuz gün içinde araç tescil belgesine/kayıtlarına işletilmesi zorunludur. Bu fıkra hükmüne uymayan işletenlere ... idari para cezası uygulanır. Üzerinde mevzuata uygun olarak teknik değişiklik yapılan araçlar, ... araç tescil belgesine/kayıtlarına işletilinceye kadar trafikten menedilir. Araç üzerinde ilgili mevzuata aykırı şekilde değişiklik yapılması yasaktır.",
  "Trafik m.34": "Muayenesi yapılmamış bir araçla trafiğe çıkılması hâlinde, araç sahibine 235 Türk lirası idari para cezası verilir. Bu araçlara, muayenelerinin yaptırılması için süre ve şartları Karayolları Trafik Yönetmeliğinde belirtilen şekilde izin verilir. İzin verilen süre sonunda, muayenesi yapılmadan veya muayene sonucunda emniyetsiz raporu verilen araçların trafiğe çıkarılması hâlinde, araç sahibine 488 Türk lirası idari para cezası verilir. Bu araçlar trafikten men edilir ve en yakın muayene istasyonuna gönderilirler.\" *(İPC tutarları yıllık yeniden değerlemeyle artar.)*",
  "Trafik m.36": "Motorlu araçların, sürücü belgesi sahibi olmayan kişiler tarafından karayollarında sürülmesi ve sürülmesine izin verilmesi yasaktır. Buna göre; a) Sürücü belgesi sahibi olmadan motorlu araçları kullananlara 40.000 Türk lirası, b) Mahkemelerce veya Cumhuriyet savcılıklarınca ya da bu Kanunda belirtilen yetkililerce sürücü belgesi geçici olarak ya da tedbiren geri alındığı halde motorlu araçları kullananlara 200.000 Türk lirası, c) Sürücü belgesi iptal edildiği halde motorlu araçları kullananlara 200.000 Türk lirası, idari para cezası verilir. Ayrıca, bu fıkra kapsamında motorlu araçların sürülmesine izin veren işletene de tescil plakası üzerinden 40.000 Türk lirası idari para cezası verilir.",
  "Trafik m.37": "Sürücü belgesi almaları zorunlu olmamakla beraber; Bisiklet kullananların 11, elektrikli bisiklet ve elektrikli skuter kullananların 15, motorsuz taşıtları kullananlar ile hayvan sürücülerinin 13 yaşını bitirmiş olmaları, bedensel ve ruhsal bakımdan sağlıklı bulunmaları zorunludur.",
  "Trafik m.46": "Karayollarında trafik sağdan akar. Aksine bir işaret bulunmadıkça sürücüler: a) Araçlarını, gidiş yönüne göre yolun sağından, çok şeritli yollarda ise yol ve trafik durumuna göre hızının gerektirdiği şeritten sürmek, b) Şerit değiştirmeden önce gireceği şeritte sürülen araçların emniyetle geçişini beklemek, c) Trafiği aksatacak veya tehlikeye sokacak şekilde şerit değiştirmemek, d) Gidişe ayrılan en soldaki şeridi sürekli olarak işgal etmemek (...) zorundadırlar.\n\ne) (Değişik:12/2/2026-7574/10) Motosiklet, otomobil, kamyonet, panelvan, minibüs ve otobüs dışındaki araçları kullanırken aynı yönde; 1) İki şeridi bulunan yollarda geçme ve dönme dışında soldaki şeridi kullanmamak, 2) İkiden fazla şeridi bulunan yollarda geçme dışında sağdan ikinci şeridi kullanmamak, 3) İkiden fazla şeridi bulunan yollarda sola dönme dışında en sağdaki iki şerit dışındaki şerit/şeritleri kullanmamak.",
  "Trafik m.47": "Karayollarından faydalananlar aşağıdaki sıralamaya göre; a) Trafiği düzenleme ve denetimle görevli trafik zabıtası veya özel kıyafetli veya işaret taşıyan diğer yetkili kişilerin uyarı ve işaretlerine, b) Trafik ışıklarına, c) Trafik işaret levhaları, cihazları ve yer işaretlemeleri ile belirtilen veya gösterilen hususlara, d) Trafik güvenliği ve düzeni ile ilgili olan ve yönetmelikte gösterilen diğer kural, yasak, zorunluluk veya yükümlülüklere, Uymak zorundadırlar.",
  "Trafik m.48": "Uyuşturucu veya uyarıcı maddeleri almış olan sürücüler ile alkollü olan sürücülerin karayolunda araç sürmeleri yasaktır. (...) Yapılan tespit sonucunda, 0.50 promilin üzerinde alkollü olarak araç kullandığı tespit edilen sürücüler hakkında, fiili bir suç oluştursa bile, 25.000 Türk lirası idari para cezası verilir ve sürücü belgesi altı ay süreyle geri alınır. (...) Uyuşturucu veya uyarıcı madde aldığı tespit edilen sürücülere 150.000 Türk lirası idari para cezası uygulanır ve sürücü belgesi iptal edilir. Bu kişiler hakkında ayrıca Türk Ceza Kanunu hükümleri uygulanır.\n\nYapılan tespit sonucunda, 0.50 promilin üzerinde alkollü olarak araç kullandığı tespit edilen sürücüler hakkında, fiili bir suç oluştursa bile, 25.000 Türk lirası idari para cezası verilir ve sürücü belgesi altı ay süreyle geri alınır. Hususi otomobil dışındaki araçları alkollü olarak kullanan sürücüler bakımından promil alt sınırı 0.21 olarak uygulanır. (...) alkolün kandaki miktarının kolluk tarafından tespit edilmesi için ölçüm yaptırmayan sürücülere 150.000 Türk lirası idari para cezası verilir ve sürücü belgesi beş yıl süreyle geri alınır.",
  "Trafik m.5": "İçişleri Bakanlığının görev ve yetkileri şunlardır: a) Araçları, bu Kanuna göre araçlarda bulundurulması gerekli belge ve gereçleri, sürücüleri ve bunlara ait belgeleri, (...) kurallara uyup uymadığını, trafik düzenlemelerinin ve çeşitli tesislerin bu Kanun hükümlerine uygun olup olmadığını denetlemek. b) Duran ve akan trafiği düzenlemek ve yönetmek. c) El koyduğu trafik kazalarında trafik kaza tespit tutanağı düzenlemek. d) Trafik suçu işleyenler hakkında tutanak düzenlemek (...). f) Araçların tescil işlemlerini yaparak belge ve plakalarını vermek. g) Sürücülerin belgelerini vermek. h) Ülke çapında taşıtların ve sürücülerin sicillerini tutmak (...).",
  "Trafik m.50": "Motorlu araçların cins ve kullanma amaçlarına göre sürülebileceği en çok ve en az hız sınırları, şehirlerarası çift yönlü karayollarında 90 km/s, bölünmüş yollarda 110 km/s, otoyollarda 120 km/s hızı geçmemek üzere yönetmelikte belirlenir. İçişleri Bakanlığı yol standartlarını dikkate alarak yukarıda belirtilen hız sınırlarını otomobiller için 20 km/s artırmaya yetkilidir.",
  "Trafik m.51": "Sürücüler, aksine bir karar alınıp işaretlenmemişse yönetmelikte belirtilen hız sınırlarını aşmamak zorundadırlar. Hız ölçen teknik cihaz veya çeşitli teknik usullerle yapılan tespit sonucu yönetmelikte belirlenen hız sınırlarını; a) Yerleşim yeri içinde ... b) Yerleşim yeri dışında ... aşanlara idari para cezası verilir. Sürücüler tarafından bu maddenin ikinci fıkrasının (a) bendinin; a) (7) numaralı alt bendinin ihlali halinde her seferinde 30 gün, b) (8) numaralı alt bendinin ihlali halinde her seferinde 60 gün, c) (9) numaralı alt bendinin ihlali halinde ise her seferinde 90 gün süre ile sürücü belgeleri geri alınır. (Aynı kademeler (b) bendi/yerleşim dışı için de geçerlidir.) ... Hız sınırlarının aşılıp aşılmadığını tespit etmekte kullanılan cihazların yerini tespit veya sürücüyü ikaz eden her türlü cihazın imali, ithali ve araçlarda bulundurulması yasaktır.\" *(2026-7574/14. İPC TL tutarları yıllık yeniden değerlemeyle değişir; kartta yazılmaz.)*",
  "Trafik m.57": "Kavşağa yaklaşan sürücüler ...geçiş hakkı olan araçların önce geçmesine imkan vermek zorundadırlar. Trafik zabıtası veya trafik işaret levhası veya ışıklı trafik işaret cihazları bulunmayan kavşaklarda; 1. Bütün sürücüler geçiş üstünlüğüne sahip olan araçlara, 2. Bütün sürücüler doğru geçmekte olan tramvaylara, ... 4. Bölünmüş yola çıkan sürücüler bu yoldan geçen araçlara, 5. Tali yoldan anayola çıkan sürücüler anayoldan gelen araçlara, ... 7. Bir iz veya mülkten çıkan sürücüler, karayolundan gelen araçlara ...geçiş hakkını vermek zorundadırlar. c) ...1. Motorsuz araç sürücüleri motorlu araçlara, 2. Motorlu araçlardan soldaki sağdan gelen araca, geçiş hakkını vermek zorundadırlar.",
  "Trafik m.6": "Trafik zabıtası görevi sırasında karşılaştığı acil ve zorunlu hallerde genel zabıta görevi yapmakla da yetkilidir. Mülki idare amirlerince, emniyet ve asayiş bakımından zorunlu görülen haller dışında, trafik zabıtasına genel zabıta görevi verilemez, araç, gereç ve özel teçhizatı trafik hizmetleri dışında kullanılamaz. b) (...) Genel Zabıta: Trafik zabıtasının bulunmadığı veya yeterli olmadığı yerlerde sorumluluk bölgesine göre genel zabıta ilgili mevzuatta belirtilen esas ve usullere uygun olarak trafiği düzenlemeye ve trafik suçlarına el koymaya görevli ve yetkilidir.",
  "Trafik m.66": "a) Ayrı bisiklet yolu veya bisiklet şeridi varsa, bisiklet ve elektrikli skuterlerin taşıt yolunda, ...yayaların kullanmasına ayrılmış yerlerde, bunlardan ikiden fazlasının taşıt yolunun bir şeridinde yan yana sürülmesi yasaktır. b) Bisiklet sürenlerin en az bir elleri, elektrikli skuter ve motorlu bisiklet sürenlerin ...iki elleri ve motosiklet sürenlerin devamlı iki eller ile taşıtlarını sürmeleri ...zorunludur. ... e) Elektrikli skuter otoyol, şehirler arası karayolları ve azami hız sınırı 50 km/s üzerinde olan karayollarında kullanılamaz. f) (2026) ...tek tekerlek üzerinde, ...akrobatik hareketler yapılarak sürülmesi yasaktır.",
  "Trafik m.69": "Madde 69 – Yerleşim birimleri dışındaki karayolunda, taşıt yolu üzerinde zorunlu haller dışında hayvan bulundurmak, ...hayvanla çekilen veya elle sürülen araçları, hayvanları, hayvan sürülerini ve binek hayvanlarını trafik kurallarına uymadan sürmek ve bunları sürme yeteneğinden yoksun kimselerin yönetimine vermek veya başı boş bırakmak yasaktır. ...başıboş hayvan bırakma yasağına riayet etmeyerek trafik kazasına sebebiyet veren faile üç ay hafif hapis cezası uygulanır. Madde 70 – a) Bir il sınırı içindeki karayolları üzerinde yapılacak yarış ve koşular için o ilin valiliğinden, b) Birden fazla il sınırları içindeki şehirlerarası karayolları üzerinde yapılacak milli ve milletlerarası yarış ve koşular için İçişleri Bakanlığından izin alınması zorunludur. ...İzinsiz yapılan yarış ve koşular görevlilerce derhal durdurulur. (2026) Yarış yapan motorlu araç sürücülerine ...idari para cezası uygulanır ve sürücü belgeleri iki yıl süreyle geri alınır.",
  "Trafik m.71": "Geçiş üstünlüğüne sahip araçlar öncelik sırasıyla şunlardır: a) Cankurtaran araçları, yaralı veya acil hasta taşıyan araçlar, b) İtfaiye araçları, orman yangınlarıyla mücadele eden araçlar, c) Hükümlü veya sanığı takip eden veya emniyet ve asayişi korumak için acele olay yerine giden zabıta araçları, (...) Bu hak, halkın can ve mal güvenliğini tehlikeye sokmamak, duyulur ve görünür geçiş üstünlüğü işaretini vermek şartı ile kullanılır.",
  "Trafik m.74": "Sürücüler, görevli bir kişi veya ışıklı trafik işareti bulunmayan ancak trafik işareti veya levhalarıyla belirlenmiş kavşak giriş ve çıkışları ile yaya veya okul geçitlerine yaklaşırken yavaşlamak, varsa buralardan geçen veya geçmek üzere bulunan yayalara durarak ilk geçiş hakkını vermek zorundadırlar.",
  "Trafik m.78": "Araçların sürülmesi sırasında sürücü ve yolcuların güvenliğine ilişkin olarak; a) Emniyet kemerinin, b) Koruma başlığı ve koruma gözlüğünün, c) Çocuk bağlama sisteminin, d) Yönetmelikte belirlenen diğer koruyucu sistemlerin, usulüne uygun olarak kullanılması zorunludur. (...) Sürücüler, 15 yaşını doldurmamış çocukların birinci fıkrada belirtilen koruyucu sistemleri kullanmalarını sağlamak zorundadırlar. 15 yaşını doldurmamış çocukların koruyucu sistemleri kullanmadan veya usulüne uygun olarak kullanılmasını sağlamadan seyahatine izin veren araç sürücüsüne 5.000 Türk lirası idari para cezası uygulanır.",
  "Trafik m.81": "Trafik kazalarına karışanlar: a) Hareket halinde iseler trafik için ek bir tehlike yaratmayacak şekilde hemen durmak, kaza mahallinde trafik güvenliği için gereken tedbirleri almak, b) Kazada ölen, yaralanan veya maddi hasar var ise bu kaza trafiği, can ve mal güvenliğini etkilemiyorsa, sorumluluğun saptanmasında yararlı olacak kanıt ve izler dahil, kaza yerindeki durumu değiştirmemek, c) Kazaya karışan kişiler tarafından istendiği takdirde kimliğini, adresini, sürücü ve tescil belgesi ile sigorta poliçe tarih ve numarasını bildirmek ve göstermek, d) Kazayı; yetkili ve görevli memurlara bildirmek, bunlar gelinceye kadar veya bunların iznini almadan kaza yerinden ayrılmamak, Zorundadırlar.",
  "Trafik m.82": "Karayollarında meydana gelecek trafik kazalarına hemen el konmasını, ölü ve yaralıların taşınmasını ...sağlamak için, a) Kaza yerinden geçmekte olan veya kazaya karışmış bulunan araçların sürücüleri kaza mahallinde ilk yardım önlemlerini almaya ve en yakın zabıtaya veya sağlık kuruluşuna haber vermeye ve yetkililerin talebi üzerine yaralıları en yakın sağlık kuruluşuna götürmeye, b) Şehirlerarası akaryakıt istasyonlarında, sahipleri veya işletenleri, ...ilk yardım malzemesini her an kullanılabilir durumda bulundurmaya, c) Tamirhane, servis istasyonu, garaj sahip ve sorumluları; ...ölüm veya yaralanma ile sonuçlanan bir kaza geçirmiş olduğu belli olan ...bir araç gelince gecikmeksizin zabıtaya haber vermeye ve bunları bir deftere işlemeye, zorunludurlar.",
  "Trafik m.83": "Trafik kazalarına; a) Adli yönden gereği yapılmak üzere mahalli genel zabıtaca, b) Kazanın oluş nedenlerini, iz ve delillerini belirleyerek trafik kaza tespit tutanağı düzenlemek üzere de trafik zabıtasınca el konulur. (...) Karayolunun trafiğe kapanmasına ölümlü ve hayati tehlike yaratan yaralanmalı kazalar neden olmuş ve bu kaza can, mal ve trafik güvenliğini etkiliyor ve başka bir yoldan geçiş verilemiyorsa Cumhuriyet savcısının gecikeceğinin anlaşılması halinde, gerekli işaretlemeler yapılıp araç ve ölüler kenara alınarak durum bir tutanakla tespit edildikten sonra yol trafiğe açılır.",
  "Trafik m.84": "Araç sürücüleri trafik kazalarında; a) Kırmızı ışıklı trafik işaretinde veya yetkili memurun dur işaretinde geçme, (...) d) Arkadan çarpma, e) Geçme yasağı olan yerlerde geçme, (...) h) Kavşaklarda geçiş önceliğine uymama, i) Kaplamanın dar olduğu yerlerde geçiş önceliğine uymama, j) Manevraları düzenleyen genel şartlara uymama, k) Yerleşim birimleri dışındaki karayolunun taşıt yolu üzerinde, zorunlu haller dışında park etme veya duraklama (...), l) Park için ayrılmış yerlerde veya taşıt yolu dışında kurallara uygun olarak park edilmiş araçlara çarpma, Hallerinde asli kusurlu sayılırlar.\n\nb) Taşıt giremez trafik işareti bulunan karayoluna veya bölünmüş karayolunda karşı yönden gelen trafiğin kullandığı şerit, rampa ve bağlantı yollarına girme, c) İkiden fazla şeritli taşıt yollarında, karşı yönden gelen trafiğin kullandığı şerit veya yol bölümüne girme, f) Doğrultu değiştirme manevralarını yanlış yapma, g) Şeride tecavüz etme, i) Kaplamanın dar olduğu yerlerde geçiş önceliğine uymama, j) Manevraları düzenleyen genel şartlara uymama, k) Yerleşim birimleri dışındaki karayolunun taşıt yolu üzerinde, zorunlu haller dışında park etme veya duraklama ..., l) Park için ayrılmış yerlerde veya taşıt yolu dışında kurallara uygun olarak park edilmiş araçlara çarpma, hallerinde asli kusurlu sayılırlar.",
  "Trafik m.Ek 14": "Buluntu olması nedeniyle veya bu Kanun hükümleri gereğince trafikten men edilerek alıkonulan, ancak sahipleri tarafından altı ay içinde teslim alınmayan veya aranmayan araçlar Hazinece satılarak, bedelleri emanet hesabına alınır. Bu araçların maliklerinden adresi bilinenlere, satışından önce tebligat yapılır.",
  "Trafik m.Ek 16": "Belediyelerce veya sermayesinin tamamı belediyelere ait şirketler tarafından ...kurulmuş veya kurulacak elektronik sistemlerin Emniyet Genel Müdürlüğünce trafik ihlallerinin tespiti amacıyla kullanılması durumunda, aylık dönemler halinde yapılan tespitlere dayanılarak düzenlenen trafik idari yaptırım karar tutanaklarında yer alan trafik idari para cezasının % 30'u oranındaki tutar, izleyen ayın sonuna kadar Emniyet Genel Müdürlüğü bütçesinden ilgili belediyelere sistem kullanımı hizmet bedeli olarak ödenir.",
  "Trafik m.Ek 17": "İlk defa sürücü belgesi alanlar en az bir yıl süre ile aday sürücü olarak kabul edilirler. Aday sürücülüğün süresi, aday sürücülerin sürücü belgelerinin iptal edilme ve yeniden sürücü belgesi alma şartları ile diğer usul ve esaslar yönetmelikle düzenlenir. Aday sürücülerle ilgili olarak yönetmelikte belirtilen iptal edilme şartlarının oluşması hâlinde, bu Kanunun 6 ncı maddesinde sayılan görevliler tarafından sürücü belgeleri iptal edilir.",
  "Trafik m.Ek 4": "Karayollarında yolcu taşımacılığı yapan otobüs ve benzeri taşıtların karışmış olduğu ölümlü trafik kazası sonuçlarının; kusurlu araç veya araçları kullanan sürücü ve araca ait plaka numaraları ile birlikte otobüs işleticisi teşebbüsün unvanının, televizyon ve basın organları aracılığı ile kamuoyuna görüntülü ve yazılı olarak, kusur oranlarından söz edilmeksizin ilanı, sırrın ifşaı ve ticari itibarın ihlali sayılmaz.",
  "Trafik m.Ek 6": "Sürücülerin trafik kurallarına uyup uymadığını denetlemekle sorumlu olan yetkililere yardımcı olmak üzere Karayolu Trafik Güvenliği Kurulunca önerilen ve Karayolu Trafik Güvenliği Üst Kurulunca uygun görülen kişilere, valilerce 'fahri trafik müfettişliği' görevi verilir. Fahri trafik müfettişleri; ...tutanağı düzenlemek ve bunları ...en geç bir hafta içerisinde herhangi bir trafik kuruluşuna teslim etmek zorundadırlar. ...Bu hizmet fahri ve ücretsizdir. Görevini kötüye kullandığı tespit edilen fahri trafik müfettişleri iki aydan altı aya kadar hafif hapis cezası ile cezalandırılırlar. Ayrıca belgeleri iptal edilir.",
  "Trafik Yön m.100": "Karayolları Trafik Kanununda ve bu Yönetmelikte yazılı kayıt ve şartlar dışında ve aksine bir işaret bulunmadıkça yol durumlarına göre römorksuz araç cinsleri için saatteki asgari ve azami hız sınırları aşağıda gösterilmiştir.\" [Otomobil (M1): yerleşim yeri içinde 50, şehirlerarası çift yönlü 90, bölünmüş yollarda 110, otoyollarda 120. Minibüs (M2) / Otobüs (M2-M3): 50 / 80 / 90 / 100. Kamyon (N2-N3) / Çekici (N2-N3): 50 / 80 / 85 / 90.] \"Zorunlu haller dışında şehirlerarası karayolunu kullanan motorlu araçlarda araç cinsi gözetilmeksizin asgari hız sınırı 15 km/s, otoyollarda ise 40 km/s'tir.",
  "Trafik Yön m.102": "Madde 102 — Sağa dönüşlerde dar, sola dönüşlerde geniş kavisle dönülür; dönüş işareti verilir, hız azaltılır, yayalara geçiş hakkı verilir. Madde 103 — Geçme, geçilecek aracın SOLUNDAKİ şeritten yapılır ... (c) Araçların sağından veya banketten geçmek yasaktır. Madde 104 — Geçmenin yasak olduğu yerler: tepe üstü ve dönemeçler, yaya/okul geçitleri, kavşaklar ve demiryolu geçitleri, iki yönlü köprü ve tüneller. Madde 105 — Geçilen araç sürücüsü hızını artırmaz, sağa yaklaşır, gerekirse durur. Madde 106 — Dar yolda geçiş hakkı sırası: motorsuz → otomobil, minibüs, kamyonet, otobüs, kamyon, arazi taşıtı, traktör, iş makinesi (yazılış sırasına göre öncekine yol verir). Madde 107 — Takip mesafesi, hızın (km/s) en az YARISI kadar metredir; 2 saniyede alınan yol kadar da olabilir. Tehlikeli madde taşıyan araç yerleşim dışında en az 50 metreden takip eder. Madde 108 — Trafiği aksatacak şekilde yavaş sürmek ve gereksiz ani yavaşlamak yasaktır.",
  "Trafik Yön m.109": "b) Trafik zabıtası veya trafik işaret levhası veya ışıklı işaret cihazları bulunmayan kavşaklarda; 1) Bütün sürücüler geçiş üstünlüğüne sahip olan araçlara, 2) Bütün sürücüler doğru geçmekte olan tramvaylara, 3) Doğru geçen tramvay hattı bulunan karayoluna çıkan sürücüler bu yoldan gelen, geçen araçlara, 4) Bölünmüş yola çıkan sürücüler bu yoldan geçen araçlara, 5) Tali yoldan ana yola çıkan sürücüler, ana yoldan gelen araçlara, 6) Dönel kavşağa gelen sürücüler, dönel kavşak içindeki araçlara, 7) Bir iz veya mülkten çıkan sürücüler, karayolundan gelen araçlara, 8) Dönüş yapan sürücüler, doğru geçmekte olan araçlara, Geçiş hakkını vermek zorundadırlar.\n\nc) Kavşak kollarının trafik yoğunluğu bakımından farklı oldukları işaretlerle belirlenmemiş ise; 1) Motorsuz araç sürücüleri, motorlu araçlara, 2) Lastik tekerlekli traktör ile iş makinesi sürücüleri, diğer motorlu araçlara, 3) Motorlu araçlardan soldaki, sağdan gelen araca, 4) Dönüş yapan sürücüler, kurallara uygun olarak geçiş yapan yayalara, varsa bisiklet yolundaki bisikletlilere, Geçiş hakkını vermek zorundadırlar.\n\nd) Kavşağa gelen sürücüler kavşak giriş ve çıkışlarından kurallara uygun olarak karşıya geçen veya geçmek üzere olan yayalara, Geçiş hakkını vermek zorundadırlar. e) Işıklı trafik işaretleri izin verse bile trafik akımı, kendisini kavşak içinde durmaya zorlayacak veya diğer doğrultudaki trafiğin geçişine engel olacak ise, sürücülerin kavşağa girmeleri yasaktır. f) Görevli kişi veya ışıklı trafik işareti ile yönetilen kavşaklarda, sürücüler kavşağı en kısa zamanda geçmek zorundadırlar. Sürücülerin gereksiz olarak yavaşlamaları, durmaları, araçtan inmeleri, yolcu indirmeleri ve bindirmeleri veya araçlarının motorlarını durdurmaları yasaktır. g) Aksine bir trafik işareti olmadıkça, bütün kavşaklarda araçlar, ray üzerinde hareket eden taşıtlara geçiş hakkını vermek zorundadırlar.",
  "Trafik Yön m.11": "Madde 11 (i) — Trafik zabıtasının görev ve yetkileri saklı kalmak üzere, 2918 sayılı Karayolları Trafik Kanununun 13, 14, 16, 17, 18, 47/a ve 65 inci maddeleri hükümlerine aykırı hareket edenler hakkında Cumhuriyet Başsavcılığına Sevk Tutanağı veya idari para cezasına dair tutanak düzenlemek; 47 nci maddesinin (b), (c) ve (d) bentlerinde belirtilen kural ihlallerinin tespiti halinde, durumu bir tutanakla belirlemek ve gerekli işlemin yapılması için en yakın trafik kuruluşuna teslim etmek.",
  "Trafik Yön m.113": "Madde 112 — ... Duraklama, bekleme amacı ile yapılırsa, bunun süresi en çok 5 dakikadır. Bu sürenin geçirilmesi parketme sayılır. Madde 113 (Duraklamanın yasak olduğu yerler) — ... d) Kavşaklar, tüneller, köprüler ve bağlantı yollarında ve buralara, yerleşim birimleri içinde 5 metre ve yerleşim birimleri dışında 100 metre mesafede, ... f) Otobüs, tramvay ve taksi duraklarında ... h) İşaret levhalarına, yaklaşım yönünde ... yerleşim birimi içinde 15 metre ve yerleşim birimi dışında 100 metre mesafede ... duraklamak yasaktır. Madde 115 (Parketmenin yasak olduğu yer ve haller) — ... 4) Belirlenmiş yangın musluklarına her iki yönden 5 metrelik mesafe içinde, 5) Kamu hizmeti yapan yolcu taşıtlarının duraklarını belirten levhalara her iki yönden 15 metre mesafe içinde, 8) Geçiş üstünlüğü olan araçların gidiş ve çıkışlarının yapıldığı yerleri belirten işaret levhalarına 15 metrelik mesafe içinde, 9) ... giriş çıkış kapılarının her iki yönünden 5 metrelik mesafe içinde, 10) ... alt ve üst geçitler ile köprüler üzerinde veya bunlara 10 metrelik mesafe içinde parketmek yasaktır.",
  "Trafik Yön m.13": "Madde 13 — Ulaştırma Bakanlığının ilgili birimleri; ... ç) Karayolları Trafik Kanununun 35 inci maddesi hükümlerine aykırı hareket edenler hakkında tutanak düzenleyerek idarî para cezası vermek, ... e) Trafik zabıtasının görev ve yetkileri saklı kalmak üzere, araçların ağırlık ve boyut kontrollerini yapmak veya yaptırmak ve denetlemek, aykırı görülen hususlarla ilgili olarak sorumlular hakkında idarî para cezasına dair tutanak düzenlemek.",
  "Trafik Yön m.142": "Geçiş üstünlüğü bulunan bir aracın duyulur veya görülür bir işaretini alan ve araç sürücüleri bu araçların kolayca ilerlemelerini sağlamak için taşıt yolu üzerinde yer açmak, gerekiyorsa durmak ve bu araçlar tarafından tamamen geçilinceye kadar beklemek mecburiyetindedirler. Bir kavşakta iken böyle bir işaret alan araç sürücüleri derhal kavşağı boşaltmak ve gerekiyorsa emniyetli bir mesafe uzaklaştıktan sonra geçişi engellemeyecek şekilde durmak ve geçiş üstünlüğüne haiz araçlar tamamen geçinceye kadar beklemek mecburiyetindedirler.",
  "Trafik Yön m.150": "Belirli sürücülerin ve yolcuların, araçların sürülmesi sırasında koruyucu tertibat kullanmaları mecburidir. (...) a) (...) bisiklet, elektrikli bisiklet, motorlu bisiklet, motosiklet (...) sürücülerin koruma başlığı ve koruma gözlüğü (...), yolcuların ise koruma başlığı takmaları ve bağlamaları, b) (Ek:RG-4/11/2025-33067) (...) motosiklet sürücülerinin ve taşınmaları halinde yolcuların koruyucu eldiven takmaları, c) M1 sınıfı otomobillerin (...), N1, N2, N3 sınıfı kamyonet, kamyon ve çekicilerin, M2 ve M3 sınıfı minibüs ve otobüslerin bütün koltuklarında (...) 'Emniyet Kemeri'nin (...) bulundurulması ve kullanılması zorunludur. (...) Ancak; (...) 2) Geri gitme veya park yerlerinde 25 km/s. geçmeyen hızla seyreden sürücüler, 3) Ambulanslarda sürücü ve yanındaki oturma yeri dışında kalan ve hasta veya yaralıya müdahale nedeniyle özel pozisyonlarda bulunan görevliler, emniyet kemeri kullanmak zorunda değildir.",
  "Trafik Yön m.152": "Madde 152 — Bir trafik kazasına karışanlardan yaralanmamış veya hafif yaralı olanlar; a) hemen durmak, ışıklı işaret/yansıtıcı koyup tedbir almak, b) sorumluluğun belirlenmesine yarayacak iz ve delilleri değiştirmemek, c) istendiğinde kimlik/adres bildirmek, sürücü-trafik belgeleri ile sigorta poliçelerini göstermek, ç) yetkililere bildirmek ve izinsiz kaza yerinden ayrılmamak zorundadırlar. Sadece maddi hasarla sonuçlanan kazalarda taraflar anlaşırsa 'Maddi Hasarlı Trafik Kazası Tespit Tutanağı' düzenleyip ayrılabilir (sonradan yetkiliden tutanak isteyemezler). Madde 153 — Kazaya karışan veya olay yerinden geçenler; ilk yardım tedbirini almak, olayı en yakın zabıta veya sağlık kuruluşuna bildirmek, yetkililerin isteğiyle yaralıları en yakın sağlık kuruluşuna götürmek zorundadır.",
  "Trafik Yön m.154": "a) Trafik kazalarına; 1) Adli yönden gereği yapılmak üzere mahalli genel zabıtaca, 2) Kaza nedenlerini, iz ve delillerini belirleyecek 'Kaza Tespit Tutanağı' düzenlemek üzere de trafik zabıtasınca (polis veya jandarma), El konulur. Trafik zabıtasının görev alanı dışında kalan yerler ile el koyamadığı durumlarda, trafik kaza tespit tutanağı, örneğine uygun olarak mahalli zabıta tarafından düzenlenir ve bir örneği o yerin trafik zabıtasına gönderilir.",
  "Trafik Yön m.155": "Madde 155 — Kazaya el koyan mahalli zabıta veya trafik zabıtası; can, mal ve trafik güvenliği bakımından ek tehlikeyi önlemek, yaralılara ilk yardımı sağlamak, yolu 154. maddeye göre trafiğe açmak, MAL GÜVENLİĞİ açısından araç/eşya/yükün hasara uğratılmaması-alınmaması-kurcalanmaması ve gerekirse tutanakla muhafaza altına alınması, örneğine uygun kaza tespit tutanağı düzenlenmesi konularında görevli ve yetkilidir. Madde 156 — Kaza tespit tutanağı ... en az iki görevli tarafından düzenlenir (hafif yaralanmalı/hasarlıda tek görevli rapor şeklinde de düzenleyebilir). Türk Silahlı Kuvvetlerine ait araçların karıştığı kazalarda bir askeri temsilcinin bulundurulması mecburidir. Tutanak düzenleyenler kusur ORANI belirtmeksizin sadece kimin hangi trafik kuralını ihlal ettiğini belirtir. Yalnız maddi hasarlı ve olay yerinden kaldırılmış araçlarda hasar tespiti sigorta veya mahkeme yoluyla yapılır.",
  "Trafik Yön m.157": "Araç sürücülerinin trafik kazalarında asli kusurlu sayılacakları haller ... aşağıda gösterilmiştir. a) Asli kusur sayılan haller: 1) Kırmızı ışıklı trafik işaretinde veya yetkili memurun dur işaretinde geçme, 2) Taşıt giremez trafik işareti bulunan karayoluna veya bölünmüş karayolunda karşı yönden gelen trafiğin kullanıldığı şerit, rampa ve bağlantı yollarına girme, 3) İkiden fazla şeritli taşıt yollarında karşı yönden gelen trafiğin kullandığı şerit veya yol bölümüne girme, 4) Arkadan çarpma, 5) Geçme yasağı olan yerlerden geçme, 6) Doğrultu değiştirme manevralarını yanlış yapma, 7) Şeride tecavüz etme, 8) Kavşaklarda geçiş önceliğine uymama, 9) Kaplamanın dar olduğu yerlerde geçiş önceliğine uymama, 10) Manevraları düzenlenen genel şartlara uymama, 11) Yerleşim birimleri dışındaki karayolunun taşıt yolu üzerinde, zorunlu haller dışında parketme ve duraklama ..., 12) Park için ayrılmış yerlerde veya taşıt yolu dışında kurallara uygun olarak parkedilmiş araçlara çarpma. Yukarıda sayılan hal ve hareketlerde bulunan sürücüler asli (esas) kusurlu sayılırlar.",
  "Trafik Yön m.16": "Madde 16 — Belediye trafik hizmet birimlerinin görev, yetki ve sorumlulukları ... a) Yolun yapısını, trafik düzeni ve güvenliğini sağlayacak durumda bulundurmak, b) Yol ve kavşak düzenlemeleri yapmak, c) Trafiği düzenleme amacı ile trafik işaret levhaları, ışıklı ve sesli trafik işaretleri, yer işaretlemeleri temin ve tesis etmek ... f) Açık ve kapalı park yerleri (otopark) alt ve üst geçitler yapmak ... k) Karayolları Trafik Kanunu ve bu Kanuna göre çıkarılan yönetmeliklerle verilen diğer görevleri yapmak. ... Belediyeler bu madde ile görev verilen hizmetlerin denetimi dışında, trafiği denetleyemez ve hiçbir halde trafik suç ve ceza tutanağı düzenleyemezler.",
  "Trafik Yön m.160": "Madde 160 — 2918 sayılı Kanunda sayılan görevlilerin ve trafik tescil kuruluşlarının yetkilendirildiği haller hariç olmak üzere, sürücü belgelerinin geri alınmasına ve iptaline SULH CEZA HÂKİMLİKLERİ karar verir. İdarî yaptırımlara itirazlarda 5326 sayılı Kabahatler Kanunu hükümleri uygulanır. Madde 161 — Trafik kural ve yasaklarını ihlal edenler hakkında Emniyet Genel Müdürlüğünün trafik zabıtası ... ve Jandarma Genel Komutanlığının yetkili kıldığı personel tarafından trafik idari para cezası karar tutanağı ve/veya mülki amire sevk tutanağı düzenlenir. (Karayolları Genel Müdürlüğü 13,14,16,17,18,47/a,65; Ulaştırma Bakanlığı 35,65 için.) Madde 162 — Tutanak düzenleyenler; birim adını/kaşeyi basmak, ad-soyad-unvan-sicili yazıp imzalamak, tebliğ yerine geçmek üzere ilgiliye imzalatıp bir nüsha vermek, imzadan kaçınana 'imza etmedi' notu düşmekle yükümlüdür.",
  "Trafik Yön m.166": "2918 sayılı Karayolları Trafik Kanununun yetki verdiği trafik zabıtası, trafik zabıtasının bulunmadığı veya yeterli olmadığı yerlerde polis, polisin ve trafik teşkilatının görev alanı dışında kalan yerlerde de jandarma; trafik eğitimi almış subay, astsubay ve uzman jandarmalar tarafından; a) Trafiği tehlikeye düşürecek, engel olacak şekilde veya yasaklanmış yerlerde parkedilen araçlara, b) Trafik kural ve yasaklarına aykırı davranışları belirlenmiş bulunan, sürücüsü tespit edilemeyen araçlara, Tescil plakasına göre tutanak düzenlenir.",
  "Trafik Yön m.167": "Trafik kuralının ihlal edildiği tarihten geriye doğru bir yıl içinde; a) Toplam 100 ceza puanını aştığı tespit edilen sürücülerin, sürücü belgeleri 2 ay süre ile geri alınır. (...) b) Toplam 100 ceza puanını ikinci defa aştığı tespit edilen sürücülerin sürücü belgeleri 4 ay süre ile geri alınarak, tabi tutulacakları psiko-teknik değerlendirme ve psikiyatri uzmanının muayenesi sonucunda (...) iade edilir. c) Toplam 100 ceza puanını üçüncü defa aştığı tespit edilen sürücüler bu konuda düzenlenecek bir tutanakla sulh ceza hakimliklerine sevk edilir ve mahkeme kararına göre işlem tesis edilir. (...) Ölümle sonuçlanan trafik kazalarına asli kusurlu olarak sebebiyet veren sürücülerin sürücü belgeleri ilgili mahkeme tarafından 1 yıl süre ile geri alınır.",
  "Trafik Yön m.168": "b) Sürücü belgesi sahibinin; 26/9/2004 tarihli ve 5237 sayılı Türk Ceza Kanununun 188, 190 ve 191 inci maddeleri, 21/3/2007 tarihli ve 5607 sayılı Kaçakçılıkla Mücadele Kanununun 4 üncü maddesinin yedinci fıkrasında ve 10/7/1953 tarihli ve 6136 sayılı Ateşli Silahlar ve Bıçaklar ile Diğer Aletler Hakkında Kanunun 12 nci maddesinin ikinci ve takip eden fıkralarında belirtilen suçlardan hüküm giymesi halinde, bu suçlara ilişkin kayıtlar adli sicilinden silininceye kadar sürücü belgesi geri alınır.",
  "Trafik Yön m.17": "Madde 17 — ... illerde vali veya yardımcısının başkanlığında ... il trafik komisyonu, ilçelerde kaymakamın başkanlığında ... ilçe trafik komisyonu kurulur. ... Kararlar oy çokluğu ile alınır. ... İl trafik komisyonu kararları valinin onayı ile yürürlüğe girer. İlçe trafik komisyonu kararları, il trafik komisyonunca incelenip vali tarafından onaylandıktan sonra yürürlüğe girer. Madde 18 — İl ve ilçe trafik komisyonunun görev ve yetkileri: ... c) ticari yolcu ve yük taşıtları ... çalışma şekil ve şartlarını, güzergâhlarını tespit etmek ve sayılarını belirlemek, d) boş alanları geçici otopark ilan etmek, e) karayolunun kapatılmasına ... karar vermek, f) hız limitlerine göre yeniden hız sınırlarını belirlemek ...",
  "Trafik Yön m.173": "Madde 173 — Olağanüstü hal ve savaşta ... askeri trafik için kullanılacak karayolları GENELKURMAY BAŞKANLIĞINCA belirlenir. Olağanüstü hal ve savaşta; a) Askeri trafiğe ayrılan karayollarında trafiğin yönetimi, düzenlenmesi ve denetimi askeri kişilerce yerine getirilir. b) Askeri ve sivil trafiğin kullandığı, kesişen bölümlerde görevli trafik zabıtası ve genel zabıta, askeri görevlilerin isteklerine uyar. c) Askeri yönetimde olan karayolunda sivil kişiler asker görevlilerin, sivil yönetiminde olan karayolunda asker kişiler trafik görevlilerinin talimatlarına uymak zorundadır.",
  "Trafik Yön m.174": "Madde 174 — Karayolunu kullananları uzun süre etkileyecek şekilde park edilmiş, terk edilmiş veya hasara uğramış araçları, durumu bir tutanakla tespit ederek kaldırıp götürmeye ve trafikten men etmeye TRAFİK ZABITASI yetkilidir. ... Trafikten men edilerek alıkonulan araçlar ile buluntu araçlar resmi kurum veya özel otoparklarda muhafaza altına alınır. ... araçlara ait bilgi ve belgeler, araçların trafikten men edildiği tarihten (buluntu araçlar için buluntu tutanağının düzenlendiği tarihten) itibaren 4 AY içinde Defterdarlık veya Mal Müdürlüğüne gönderilir.",
  "Trafik Yön m.178": "Madde 178 — İlk ve orta dereceli okul öğrencilerinin okul önlerinde ve geçitlerinde güvenli giriş-çıkışını sağlamak amacıyla, trafik zabıtasınca verilmiş belgesi bulunan ve özel kıyafet-işaret taşıyan görevliler, bu yerlerde trafiği sevk ve idareye yetkilidir. İstekli öğretmenler, veliler ile 12 YAŞINI DOLDURMUŞ öğrenciler okul geçidi görevlisi olabilir. ... Okul geçidi görevi FAHRÎ bir görev olup ücret talep edilmez. Görevliler taşıt trafiğini gerektiğinde DURDURMA yetkisine sahiptir; sürücüler işaretine uymak zorundadır. Görevliler bir tarafı YEŞİL 'GEÇ', diğer tarafı KIRMIZI 'DUR' yazılı işaret çubuğu taşır.",
  "Trafik Yön m.26": "Madde 26 — Karayollarında her iki taraftan sınır çizgisine 50 metre mesafe içinde bağlantıyı sağlayacak geçiş yolları yönünden; akaryakıt, servis, dolum ve muayene istasyonları, umuma açık park yeri ve garaj, terminal, fabrika ... ve benzeri trafik güvenliğini etkileyecek yapı ve tesisler için, o karayolunun yapımı, bakımı, işletilmesi ile ilgili kuruluştan izin alınması zorunludur. Madde 27 — Belediye sınırları içindeki karayolları kenarında yapılacak veya açılacak ... yapı ve tesisler için, a) Belediyelerden izin alınması ... b) ... Karayolları Genel Müdürlüğünün ... ilgili bölge müdürlüğünden uygun görüş almaları zorunludur.",
  "Trafik Yön m.3": "12) Geçiş Üstünlüğü: Görev sırasında, belirli araç sürücülerinin can ve mal güvenliğini tehlikeye sokmamak şartı ile trafik kısıtlama veya yasaklarına bağlı olmamalarıdır. 13) Geçiş Hakkı: Yayaların ve araç kullananların diğer yaya ve araç kullananlara göre, yolu kullanmak sırasındaki öncelik hakkıdır.\n\n14) Durma: Kırmızı ışık, yetkililerin dur işareti, yol kapanması gibi her türlü trafik zorunlulukları nedeni ile aracın durdurulmasıdır. 15) Duraklama: Trafik zorunlulukları dışında araçların, insan indirmek ve bindirmek, eşya yüklemek, boşaltmak veya beklemek amacı ile kısa bir süre için durdurulmasıdır. 16) Parketme: Araçların, durma ve duraklaması gereken haller dışında bırakılmasıdır.\n\n3) Araç: Karayollarında kullanılabilen motorlu, motorsuz ve özel amaçlı taşıtlar ile iş makineleri ve lastik tekerlekli traktörlerin genel adıdır. 4) Taşıt: Karayolunda insan, hayvan ve yük taşımaya yarayan araçlardır. ... 5) Sürücü: Karayolunda, motorlu veya motorsuz bir aracı veya taşıtı sevk ve idare eden kişidir. 6) Şoför: Karayolunda, ticari olarak tescil edilmiş bir motorlu taşıtı süren kişidir. 9) Yolcu: Aracı kullanan sürücü ile hizmetliler dışında araçta bulunan kişilerdir. 10) Hizmetli: Araçlarda, sürücü hariç, araç veya taşıma hizmetlerinde ... çalışan kişiler ... 21) Trafikten Men: ... araçla ilgili belgelerin alınması ve aracın belirli bir yere çekilerek trafikten alıkonulmasıdır.\n\n13) Banket: Yaya yolu ayrılmamış karayolunda, taşıt yolu kenarı ile şev başı veya hendek iç üst kenarı arasında kalan ve olağan olarak yayaların ve hayvanların kullanacağı, zorunlu hallerde de araçların faydalanabileceği kısımdır. 14) Platform: Karayolunun, taşıt yolu (kaplama) ile yaya yolu kaldırım veya banketinden oluşan kısmıdır. 25) Ada: Yayaların geçme ve durmalarına, taşıtlardan inip binmelerine yarayan, trafik akımını düzenleme ve trafik güvenliğini sağlama amacıyla yapılmış olan, araçların bulunamayacağı, koruyucu tertibatla belirlenmiş bölüm ve alanlardır.\n\n8) Motosiklet: Azami tasarım hızı 45 km/saatten ve/veya silindir kapasitesi 50 santimetreküpten fazla olan sepetli veya sepetsiz iki veya üç tekerlekli motorlu taşıtlar ... 9) Motorlu bisiklet (Moped): Azami hızı saatte 45 kilometreyi, içten yanmalı motorlu ise silindir hacmi 50 santimetreküpü, elektrik motorlu ise azami sürekli nominal güç çıkışı 4 kilovatı geçmeyen iki veya üç tekerlekli taşıtlar ... 10) Bisiklet: Üzerinde bulunan insanın adale gücü ile pedal veya el ile tekerleği döndürülmek suretiyle hareket eden motorsuz taşıtlar ... (Azami sürekli anma gücü 0,25 kilovatı geçmeyen, ... hızı en fazla 25 km/saate ulaşan elektrikli bisikletler de bu sınıfa girer.)\n\n24) Taşıma Sınırı (Kapasite): Bir aracın güvenle taşıyabileceği, en çok yük ağırlığı ve/veya yolcu ve hizmetli sayısıdır. 25) Gabari: Araçların yüklü veya yüksüz olarak karayolunda güvenli seyirlerini temin amacı ile uzunluk, genişlik ve yüksekliklerini belirleyen ölçülerdir. 26) Azami Ağırlık: Aracın güvenle taşıyabileceği azami yükle birlikte ağırlığıdır. 27) Yüksüz Ağırlık: Üzerinde insan veya eşya bulunmayan ve akaryakıt deposu dolu olan bir aracın taşınması zorunlu alet, edevat ve donatımı ile birlikte toplam ağırlığıdır. 28) Yüklü Ağırlık: Bir taşıtın yüksüz ağırlığı ile taşımakta olduğu sürücü, hizmetli, yolcu ve eşyanın toplam ağırlığıdır. 29) Dingil Ağırlığı: ... aynı dingile bağlı tekerleklerden karayolu yapısına aktarılan ağırlıktır. 30) Azami Dingil Ağırlığı / 31) Azami Toplam Ağırlık: Araçların karayolu yapılarında güvenle ve yapıya zarar vermeden geçebilmeleri için saptanan dingil/toplam ağırlıktır.\n\n1) L Sınıfı – İki ve üç veya dört tekerlekli motorlu araçlardır. 2) M Sınıfı – En az dört tekerlekli ve yolcu taşımasında kullanılan motorlu araçlardır (M1: sürücü dahil en fazla 9 oturma; M2: 9'dan fazla, azami 5 tonu aşmayan; M3: 9'dan fazla, 5 tonu aşan). 3) N Sınıfı – En az dört tekerlekli ve yük taşımasında kullanılan motorlu araçlardır (N1: 3,5 tonu aşmayan; N2: 3,5–12 ton; N3: 12 tonu aşan). 4) O Sınıfı – Bir motorlu araç tarafından çekilen römork veya yarı römork motorsuz yük taşıma araçlarıdır. ... 7) G Sınıfı - Arazi Taşıtları.",
  "Trafik Yön m.4": "Karayolu güvenliği konusunda hedefleri tespit etmek, uygulatmak ve koordinasyonu sağlamak amacıyla aşağıdaki kurullar oluşturulmuştur. a) Karayolu Güvenliği Yüksek Kurulu; Karayolu Güvenliği Yüksek Kurulu Başbakanın başkanlığında, Adalet, İçişleri, Maliye, Milli Eğitim, Bayındırlık ve İskan, Sağlık, Ulaştırma, Orman Bakanları ve Köy Hizmetleri Genel Müdürlüğünün Bağlı Olduğu Bakan ile Jandarma Genel Komutanı, Başbakanlık Devlet Planlama Teşkilatı Müsteşarı, Emniyet Genel Müdürü ve Karayolları Genel Müdüründen oluşur. (...) Kurul yılda iki defa olağan, Başbakanın gerek görmesi halinde de olağanüstü olarak, gündemle toplanır. Kurulun sekreterya görevi Emniyet Genel Müdürlüğünce yapılır.",
  "Trafik Yön m.5": "Silahlı Kuvvetlere ait her çeşit bina ve tesisin iç bölümlerindeki trafik düzenlemeleri dışında, mülki idari amirinin isteği ve garnizon komutanının uygun görmesi halinde, merkez komutanlıklarına aşağıdaki esas ve şartlara uyulmak suretiyle gerekli görülen yerlerde ve hallerde geçici olarak trafiği düzenleme yetkisi verilebilir. (...) hallerinde, belirlenen yerlerde, belirtilen süre ve şartlara uygun şekilde uygulamak üzere, özel işaretli ve eğitilmiş askeri personel, geçici olarak trafiği düzenlemekle yetkili kılınabilir. Ancak, bu yetki trafik zabıtasının görevine müdahale şeklinde kullanılamaz. Yetkili kılınan personel, talimatlarına uymayan sürücülere ait araç plakalarını tespit ederek mahalli trafik birimine bildirirler.",
  "Trafik Yön m.75": "Sürücü belgesi sınıfları ile belge sahiplerine sürme yetkisi verilen motorlu araçlar ve özellikleri aşağıda gösterilmiştir: a) M sınıfı ... motorlu bisikletleri (moped) kullanacaklara verilir. b) A1 ... silindir hacmi 125 santimetreküpü ... geçmeyen iki tekerlekli motosikletler ... c) A2 ... gücü 35 kilovatı ... geçmeyen ... motosikletler ... Ç) A ... iki tekerlekli motosikletler ile gücü 15 kilovatı geçen üç tekerlekli motosikletleri kullanacaklara verilir. d) B1 ... dört tekerlekli motosikletleri ... e) B sınıfı sürücü belgesi otomobil ve kamyonet kullanacaklara verilir. f) BE ... azami yüklü ağırlığı 3.500 kilogramı geçmeyen römork veya yarı römork içeren birleşik araçları ... g) C1 ... azami yüklü ağırlığı 3.500 kilogramın üzerinde olan ve 7.500 kilogramı geçmeyen kamyon ve çekicileri ... Ğ) C1E ... h) C sınıfı sürücü belgesi kamyon ve çekici kullanacaklara verilir. I) CE ... römork veya yarı römorktan oluşan birleşik araçları ... i) D1 sınıfı sürücü belgesi minibüs kullanacaklara verilir. j) D1E ... k) D sınıfı sürücü belgesi minibüs ve otobüs kullanacaklara verilir. l) DE ... m) F sınıfı sürücü belgesi lastik tekerlekli traktör kullanacaklara verilir. n) G sınıfı sürücü belgesi iş makinesi türündeki motorlu araçları kullanacaklara verilir. o) K sınıfı sürücü aday belgesi ... araç sürmeyi öğrenen sürücü adaylarına eğitim ve sınavda kullanmak üzere verilir.",
  "Trafik Yön m.76": "Sürücü belgesi alacakların; a) Yaş bakımından; 1) M, A1 ve B1 sınıfı sürücü belgesi alacakların 16, 2) A2, B, BE, C1, C1E, F ve G sınıfı sürücü belgesi alacakların 18, 3) A sınıfı sürücü belgesi alacakların 20 (gücü 15 kilovatı aşan üç tekerlekli motosikletler için 21), 4) C, CE, D1 ve D1E sınıfı sürücü belgesi alacakların 21, 5) D, DE sınıfı sürücü belgesi alacakların 24 yaşını bitirmiş olmaları, b) Deneyim bakımından; 1) A sınıfı ... en az iki yıllık A2 sınıfı, 2) C1, C, D1 ve D sınıfı ... en az B sınıfı, ... sürücü belgesine sahip olmaları ... zorunludur. (...) Jandarma teşkilatının motorlu araç sürücüsü ihtiyacını karşılamak üzere Jandarma Genel Komutanlığının belirleyeceği eğitim programları çerçevesinde yapılacak sınavlarda başarılı olan jandarma teşkilatı mensubu subay, astsubay, uzman jandarma ve uzman erbaşlar ile ... öğrencilere sürücü belgesine dönüştürülmek üzere motorlu taşıt sürücüsü sertifikası verilir.",
  "Trafik Yön m.79": "Madde 79 — ... trafik suçlarını işleyen sürücüler ... psiko-teknik değerlendirme ve psikiyatri uzmanı muayenesine tabi tutulurlar. (Psiko-teknik değerlendirme raporu ile birlikte kırkbeş gün içinde psikiyatri uzmanına başvurulur.) Madde 80 — Uluslararası sürücü belgesi, ... ikili veya çok taraflı anlaşmalar uyarınca, üç yıl süre ile verilen ve verildiği ülke dışındaki ülkeler için geçerli olan sürücü belgesidir. (İçişleri Bakanlığınca yetkilendirilen gerçek veya tüzel kişilerce verilir.) Madde 82 — ... G sınıfı hariç diğer sürücü belgelerinden herhangi birini almak isteyen sürücü adaylarının ... K Sınıfı Sürücü Aday Belgesini almaları zorunludur. K Sınıfı Sürücü Aday Belgesi 6 ay süreyle geçerlidir.\n\nMadde 79 — Kanunun ilgili maddelerinde tanımlanan nitelikteki trafik suçlarını işleyen sürücüler ile diğer mevzuat kapsamında psiko-teknik açıdan sağlıklı olma şartı aranan sürücüler ... psiko-teknik değerlendirme ve psikiyatri uzmanı muayenesine tabi tutulurlar. ... Kişi düzenlenen psiko-teknik değerlendirme raporu ile birlikte kırkbeş gün içerisinde kamu veya özel sağlık kuruluşlarında görev yapan psikiyatri uzmanına başvurur. ... Belirtilen sürede psikiyatri muayenesi için başvurmayan kişiler altı ay boyunca tekrar teste kabul edilmez. Altı ay sonunda yapılacak psiko-teknik değerlendirme ve psikiyatri muayenesinde başarısız olan kişiler iki yıl boyunca tekrar teste alınmaz. Kişi adına düzenlenen rapora otuz gün içerisinde il sağlık müdürlüğüne itiraz edebilir. ... Düzenlenen bu raporlar sistemde on yıl süre ile saklanır.",
  "Trafik Yön m.85": "Madde 85 — Araçları sürme yetkisi; ... e) A sınıfı sürücü belgesi ile M, A1 ve A2, f) B sınıfı sürücü belgesi ile M, B1 ve F, ... sınıfı sürücü belgeleri ile kullanılan araçlar da sürülebilir. Madde 86 — B, C, C1, D ve D1 sınıfı sürücü belgesi sahipleri araçlarını, azami yüklü ağırlığı 750 kilograma kadar olan (750 kilogram dahil) hafif römork takarak da kullanabilirler.",
  "Trafik Yön m.87": "Madde 87 — M, A1, A2, A, B1, B, BE, F ve G sınıfı sürücü belgeleri 10 yıl; C1, C1E, C, CE, D1, D1E, D ve DE sınıfı sürücü belgeleri ise 5 yıl geçerlidir. ... Müracaatı tamamlananlara sürücü belgeleri teslim edilinceye kadar araç kullanabilmeleri için 15 gün süreyle geçerli olmak üzere 'Sürücü Belgesi Yerine Geçen Geçici Belge' (Ek-50) verilebilir. ... Bu şekilde yenilenen sürücü belgeleri için harç alınmaz.",
  "Trafik Yön m.95": "Araç ve hayvan sürücüleri ile yayalar yolu kullanırken; a) Trafiği düzenleme ve denetlemeye yetkili üniformalı veya özel işaret taşıyan görevlilerin uyarı ve işaretlerine, b) Işıklı ve sesli trafik işaretlerine, c) Trafik işaret levhaları, tertipleri ve yer işaretlemelerine, d) Trafik güvenliği ve düzeni ile ilgili olarak Karayolları Trafik Kanununda ve Karayolları Trafik Yönetmeliğinde gösterilen diğer kural, yasak, zorunluluk ve yükümlülüklere, Uymak zorundadırlar. Bunlara uymadaki öncelik yukarıda yapılan sıralamaya göredir.",
  "Trafik Yön m.96": "1) Görevli kişinin bir kolunu dik olarak yukarıya kaldırması; yeterli güvenlikte duramayacak sürücüler ile kavşağa yeni girmiş olan ve kavşak içinde bulunan sürücüler dışında, tüm karayolunu kullananlar için DUR emridir. 2) Görevli kişinin kolunu veya kollarını yatay olarak yana uzatması; kol veya kolların belirttiği doğrultuyu kesen yönlerden (ön ve arka tarafından) gelenler için DUR emridir. Bu hareket aynı zamanda; kol veya kolların uzatıldığı doğrultudan gelenlerin ilerleyebileceğini gösterir. (...) kısa sesli tek veya fasılalı düdük çalması uyarma, uzun sesli tek veya fasılalı düdük çalması DUR emridir.",
  "Trafik Yön m.97": "Uyuşturucu veya uyarıcı maddeleri almış olan sürücüler ile kanlarındaki alkol miktarı 0.50 promilin üzerinde olan hususi otomobil sürücülerinin ve kanlarındaki alkol miktarı 0.20 promilin üstünde olan diğer araç sürücülerinin karayolunda araç sürmeleri yasaktır. Trafik görevlilerince sürücüler her zaman alkol kontrolüne tabi tutulabilirler. Uyuşturucu veya uyarıcı madde kontrolü ise durumundan şüphe edilen sürücüler üzerinde yapılır.\n\nb) Yapılan ölçüm sonucunda yasal sınırların üzerinde alkollü olarak araç kullandığı tespit edilen sürücüye 2918 sayılı Kanunun 48 inci maddesinin beşinci fıkrasında belirtilen miktarlarda idari para cezası verilerek, son ihlalin gerçekleştiği tarihten itibaren geriye doğru beş yıl içinde sürücü belgeleri birinci defasında altı ay, ikinci defasında iki yıl, üç veya üçten fazlasında ise her seferinde beşer yıl süreyle geri alınır. c) Teknik cihaz kullanılmasını kabul etmeyen sürücüye 2918 sayılı Kanunun 48 inci maddesinin dokuzuncu fıkrasında belirtilen miktarda idari para cezası verilir ve sürücü belgesi iki yıl süreyle geri alınır.\n\nd) Yapılan tespit sonucunda 1,00 promilin üzerinde alkollü olduğu tespit edilen ve 2918 sayılı Kanunun 48 inci maddesine göre işlem yapılan sürücüler, haklarında ayrıca 5237 sayılı Türk Ceza Kanununun 179 uncu maddesinin üçüncü fıkrası hükümlerine göre adli işlem yapılmak üzere mahalli zabıtaya teslim edilir. e) 1,00 promilin altında alkollü olmasına rağmen, alkolün etkisiyle emniyetli bir şekilde araç sevk ve idare edemeyecek durumda olduğu tutanakla tespit edilen sürücü, hakkında ayrıca 5237 sayılı Türk Ceza Kanununun 179 uncu maddesinin üçüncü fıkrası hükümlerine göre adli işlem yapılmak üzere mahalli zabıtaya teslim edilir.",
  "Trafik Yön m.98": "Ticari amaçla yük taşımacılığı yapan ve azami ağırlığı 3,5 tonu geçen araçların şoförleri ile ticari amaçla yolcu taşımacılığı yapan ve taşıma kapasitesi şoförü dahil 9 kişiyi geçen araçların şoförlerinin 24 saatlik herhangi bir süre içinde; toplam olarak 9 saatten ve devamlı olarak 4,5 saatten fazla araç sürmeleri yasaktır. Bu şoförler en fazla 6 günlük araç kullanma süresinden sonra 1 günlük hafta tatilini kullanmak zorundadırlar. Hafta tatili en az 24 saattir. (...) Bu şoförler sürekli 4,5 saatlik araç kullanma süresi sonunda, eğer istirahata çekilmiyor ise en az 45 dakika mola almaları mecburidir. Bu molalar sürekli 4,5 saatlik araç kullanma süreleri içerisinde en az 15 dakikalık molalar şeklinde de kullanılabilir. Şoförler her 24 saat içerisinde 11 saat kesintisiz dinlenecektir.",
  "Trafik Yön m.Ek 2": "Ek Madde 2 — Belediyelerce kendi bütçe kaynakları kullanılarak ... kurulmuş veya kurulacak elektronik sistemlerin Emniyet Genel Müdürlüğünce trafik ihlallerinin tespiti amacıyla kullanılması durumunda, bu sistemler üzerinden yapılan aylık tespitlere dayanılarak düzenlenen trafik idari yaptırım karar tutanaklarında yer alan trafik idari para cezasının % 30'u oranındaki tutar, izleyen ayın sonuna kadar Emniyet Genel Müdürlüğü bütçesinden ilgili belediyelere sistem kullanımı hizmet bedeli olarak ödenir.",
  "Trafik Yön m.Ek 3": "Ek Madde 3 — Bu maddenin yürürlüğe girdiği tarihten itibaren ilk defa sürücü belgesi alanlar ile ... belgesi iptal edilip yeniden alanlar, belgenin alındığı tarihten itibaren İKİ YIL süreyle ADAY SÜRÜCÜ kabul edilir. Aday sürücülük süresi içerisinde 2918 sayılı Kanunun 47/1-b, 48/118, 51, 53/2, 74, 78 inci maddelerinden birinin üç kez ihlali ... veya araç cinsine bakılmaksızın 0,20 promilin üzerinde alkollü araç kullanıldığının tespiti veya toplam 75 CEZA PUANININ aşılması durumunda sürücü belgesi trafik görevlilerince iptal edilir. Belgesi iptal edilenlerin tekrar belge alabilmeleri için sürücü kurslarına devam edip sınavda başarılı olarak sertifika almaları gerekir.",
  "Türk Bayrağı m.2": "Madde 1 – Bu Kanunun amacı Türk Bayrağının şekli, yapımı ve korunması ile ilgili esas ve usulleri belirlemektir. Madde 2 – Türk Bayrağı, bu Kanuna ekli cetvelde gösterilen şekil ve oranlarda olmak kaydıyla beyaz ay - yıldızlı albayraktır. Bayrak ile özel bayrakların (sembolik bayrak, özel işaret, flama, flandra ve fors) standartları, hangi kumaş ve maddelerden yapılacağı yönetmelikte gösterilir.",
  "Türk Bayrağı m.3": "Madde 3 – Bayrak, kamu kurum ve kuruluşlarıyla yurt dışı temsilciliklerine ve kamu kuruluşlarıyla gerçek ve tüzelkişilerin deniz vasıtalarına çekilir. Yurt içinde ve yurt dışında yetkililerin araçlarına takılır. Bayrak çekilirken ve indirilirken tören yapılır. Bayrak törenlerinin gereken biçimde yapılmasından o mahaldeki yetkili amirler sorumludur. (Değişik: 14/7/1999 - 4409/1 md.) Kamu kurum ve kuruluşlarında Türk Bayrağı sürekli çekili kalır. (...)",
  "Türk Bayrağı m.4": "Madde 4 – Türk Bayrağı, yas alameti olarak 10 KASIM'da yarıya çekilir. Yas alameti olmak üzere Bayrağın yarıya çekileceği diğer haller ve zamanı Cumhurbaşkanlığınca ilan edilir.",
  "Türk Bayrağı m.5": "Madde 5 – Çekilmesi ve indirilmesi esnasında veya tören geçişlerinde Bayrak, cephe alınarak selamlanır.",
  "Türk Bayrağı m.6": "Madde 6 – Türk Bayrağı, Cumhurbaşkanlığı yapmış kişilerin, şehitlerin ve yönetmelikte belirlenecek asker ve sivil kişilerin cenaze törenlerinde bunların tabutlarına, açılış törenlerinde ATATÜRK heykellerine veya resmi yemin törenlerinde masalara örtülebilir. Ayrıca milli orf ve adetler göz önünde tutularak Bayrağın diğer kullanılma şekil ve yeri yönetmelikte gösterilir.",
  "Türk Bayrağı m.7": "Madde 7 – Türk Bayrağı, yırtık, sökük, yamalı, delik, kirli, soluk, buruşuk veya layık olduğu manevi değeri zedeleyecek herhangi bir şekilde kullanılamaz. Resmi yemin törenleri dışında her ne maksatla olursa olsun, masalara kürsülere, örtü olarak serilemez. Oturulan veya ayakla basılan yerlere konulamaz. Bu yerlere ve benzeri eşyaya Bayrağın şekli yapılamaz. Elbise veya uniforma şeklinde giyilemez. (...) Türk Bayrağına sözle, yazı veya hareketle veya herhangi bir şekilde hakaret edilemez, saygısızlıkta bulunulamaz. Bayrak yırtılamaz, yakılamaz, yere atılamaz, gerekli özen gösterilmeden kullanılamaz. (...)",
  "Türk Bayrağı m.8": "Madde 8 – (Değişik: 23/1/2008-5728/421 md.) Bu Kanuna ve çıkarılacak yönetmeliğe aykırı olarak Bayrak yapmak, satmak ve kullanmak yasaktır. Bu yasağa aykırı olarak yapılan Bayraklar o mahallin yetkili amirlerince toplatılır. Bu Kanun hükümlerine aykırı davranışta bulunanlara, fiilleri suç oluşturmadığı takdirde mahalli mülki amir tarafından Kabahatler Kanununun 32 nci maddesi uyarınca idarî para ceza verilir.",
  "Tütün Satış Yön m.10": "(1) Açık alkollü içki satış belgesi bulunmayan perakende satış yapılan işyerlerinde, açık alkollü içki tüketilemez ve sunumu yapılamaz. (3) (...) Aşağıda sayılan yerlerde faaliyet gösteren işyerlerinde alkollü içki satışı veya sunumu yapılamaz: a) Öğrenci yurtlarında; münhasıran bu hizmet için kullanılan yapılarda, yapıların eklentileri ve bahçelerinde, yurt yerleşke sınırları içinde. b) Sağlık hizmeti verilen yerlerde; (...) c) Spor müsabakası yapılan stadyum ve kapalı spor salonlarında. ç) Her türlü eğitim ve öğretim kurumlarında; (...) d) Kahvehane, kıraathane, pastane, bezik ve briç salonları ile akaryakıt istasyonlarında.\n\n(2) (...) Meskûn mahaller ve konaklama yerleri hariç olmak üzere, otoyollardaki ve devlet karayollarındaki yapı ve tesislerde alkollü içki satışına ve tüketimine izin verilmez.\n\n(5) (...) Alkollü içkilerin perakende veya açık olarak satışının yapıldığı yerler ile örgün eğitim kurumları ve dershaneler, öğrenci yurtları ve ibadethaneler arasında kapıdan kapıya en az yüz metre mesafenin bulunması zorunludur. Mesafe şartı, satış belgesinin verildiği tarih itibariyle aranır. Ancak 11/6/2013 tarihinden önce işyeri açma ve çalışma ruhsatı ve satış belgesi almış işletmeler için bu şart aranmaz. Bu işletme sahipleri işletmelerini birinci ve ikinci derece kan hısımlarına devredebilir. Mesafe şartı turizm belgeli işletmeler için uygulanmaz.",
  "Tütün Satış Yön m.3": "Dayanak — MADDE 3 – (1) Bu Yönetmelik, 8/6/1942 tarihli ve 4250 sayılı İspirto ve İspirtolu İçkiler İnhisarı Kanunu, 7/11/1996 tarihli ve 4207 sayılı Tütün Ürünlerinin Zararlarının Önlenmesi ve Kontrolü Hakkında Kanun, 3/1/2002 tarihli ve 4733 sayılı (...) Tütün, Tütün Mamulleri ve Alkol Piyasasının Düzenlenmesine Dair Kanun ile 8/12/2004 tarihli ve 2004/8235 sayılı Bakanlar Kurulu Kararıyla yürürlüğe konulan Dünya Sağlık Örgütü Tütün Kontrolü Çerçeve Sözleşmesine dayanılarak hazırlanmıştır.",
  "Tütün Satış Yön m.6": "f) (...) İşyerinde; tütün mamulleri ve alkollü içkiler tüketilmek veya beraberinde götürülmek üzere onsekiz yaşını doldurmamış kişilere satılamaz veya sunulamaz. Yaş konusunda tereddüde düşülmesi halinde satıcı, talepte bulunan tüketiciden kimlik belgesi talep eder. g) İşyerinde, tütün mamulleri ve alkollü içkilerin onsekiz yaşını doldurmamış kişilere satış veya sunumunun yapılamayacağına ilişkin uyarı yazılarının bulunması ve bu yazıların görülebilen yerlere okunabilecek şekilde asılması zorunludur. (...) (2) (...) Onsekiz yaşını doldurmamış kişiler, tütün ürünü işletmelerinde, pazarlanmasında ve satışında istihdam edilemez. Ayrıca bu kişiler, alkollü içkilerin üretiminde, pazarlanmasında, satışında ve açık sunumunda istihdam edilemez. Yasal düzenlemeler uyarınca gerçekleştirilen eğitim amaçlı çalışmalar bu hükmün dışındadır.\n\na) Bu Yönetmelik kapsamındaki faaliyetler için sabit ve fiziki bir işyerinin mevcudiyeti aranır. Aynı gerçek veya tüzel kişinin birden fazla işyerinin bulunması halinde her biri için ayrı satış belgesi alınması zorunludur. b) Yetkili satıcılar tarafından satış belgesinde belirtilen işyeri adresi dışında satış ve/veya sunum yapılamaz. d) (...) Bu Yönetmelik kapsamındaki ürünler dışında, farklı ürünlerin de satıldığı işyerlerinde; bu Yönetmelik kapsamındaki ürünler, diğer ürünlerden tefrik edilmiş olarak ve her türlü denetime imkân verecek şekilde depolanır ve/veya satışa arz edilir. (...) ğ) Satıcılar, ambalajlarında mevzuat uyarınca kullanılması zorunlu olan bandrol, etiket, hologram, pul, damga veya benzeri işaretleri taşımayan ürünleri ya da taklit veya niteliğine uygun olmayan işaretleri taşıyan ürünleri, ticari amaçla işyerlerinde bulunduramazlar, nakledemezler, satışa arz edemezler. Birada uygulanacak kod bandrol hükmündedir.",
  "Tütün Satış Yön m.7": "MADDE 7 – (1) (...) c) Toptan satıcılar, (a) bendi hükmü saklı kalmak üzere; toptan satış belgesi almamış kişilerden ürün alamazlar, (...) geçerli satış belgesi olmayanlara ürün satamazlar. Faaliyetine kendi isteğiyle son veren, belgesi iptal edilen veya belgesi geçerliliğini kaybedenlerin, bu durumlarına ilişkin bilgileri Kurumun internet sitesinde yayımlanır. b) (...) Ürünlerin satışa sunulduğu her bir yer ile muhafaza edildiği her bir depo için ayrı satış belgesi alınması zorunludur. (...) MADDE 8 – (1) (...) a) Perakende satıcılar, satış belgesi almamış kişilerden ürün alamazlar.",
  "Tütün Satış Yön m.8": "ç) Perakende satıcılar; tütün mamullerinin ve alkollü içkilerin, nihai tüketicilere yönelik arz ambalajlarını bozmak ya da bölmek suretiyle satış veya sunumunu yapamazlar. d) (...) Alkollü içkiler, 22:00 ila 06:00 saatleri arasında perakende olarak satılamaz.",
  "Tütün Satış Yön m.9": "(1) (...) Sağlık, eğitim ve öğretim, kültür ve spor hizmeti verilen yerlerde ve bunların yerleşkelerinde tütün mamullerinin satışı yapılamaz. Bu hizmetlerin verildiği yerlerin açık alanları ile bu hizmetin verildiği yapılar, yapıların eklentileri ve bahçeleri yerleşke sınırları içinde kabul edilir. (2) Bilgi toplumu hizmetleri vasıtasıyla ya da posta ve benzeri dağıtım hizmetleri yoluyla tütün mamulü satışı ve teslimi yapılamaz. (3) (...) İşyerlerinde bulunan otomatik satış makinelerinde tütün mamulü bulundurulamaz. Tütün mamulleri, her nevi oyun makineleri ile veya farklı yöntemlerle oyun ve bahse konu edilemez.\" (İlgili: m.6/1-h) \"4207 sayılı Kanun kapsamında, tütün mamullerinin tüketilmesinin yasaklandığı alanlarda nargilelik tütün mamulü sunumu yapılamaz.",
  "Tütün Zararları m.2": "(1) Tütün ürünleri; a) Kamu hizmet binalarının kapalı alanlarında, b) Koridorları dahil olmak üzere her türlü eğitim, sağlık, üretim, ticaret, sosyal, kültürel, spor, eğlence ve benzeri amaçlı özel hukuk kişilerine ait olan ve birden çok kişinin girebileceği (ikamete mahsus konutlar hariç) binaların kapalı alanlarında, c) Hususi araçların sürücü koltukları ile taksi hizmeti verenler dâhil olmak üzere karayolu, demiryolu, denizyolu ve havayolu toplu taşıma araçlarında, ç) Okul öncesi eğitim kurumlarının, dershaneler, özel eğitim ve öğretim kurumları dahil olmak üzere ilk ve orta öğrenim kurumlarının, kültür ve sosyal hizmet binalarının kapalı ve açık alanlarında, d) Özel hukuk kişilerine ait olan lokantalar ile kahvehane, kafeterya, birahane gibi eğlence hizmeti verilen işletmelerde, tüketilemez.\n\n(2) Ancak; a) Yaşlı bakım evlerinde, ruh ve sinir hastalıkları hastanelerinde, cezaevlerinde, b) Şehirlerarası veya uluslararası güzergâhlarda yolcu taşıyan denizyolu araçlarının güvertelerinde, tütün ürünleri tüketilmesine mahsus alanlar oluşturulabilir. Bu alanlara onsekiz yaşını doldurmamış kişiler giremez. (3) Otelcilik hizmeti verilen işletmelerde, tütün ürünleri tüketen müşterilerin konaklamasına tahsis edilmiş odalar oluşturulabilir. (4) Açık havada yapılan her türlü spor, kültür, sanat ve eğlence faaliyetlerinin yapıldığı yerler ile bunların seyir yerlerinde tütün ürünleri kullanılamaz. Ancak bu tesislerde, tütün ürünlerinin tüketilmesine mahsus alanlar oluşturulabilir.\n\n(6) Bu Kanunun uygulanmasında \"tütün ürünü\" ibaresi tüttürme, emme, çiğneme ya da buruna çekerek kullanılmak üzere üretilmiş, hammadde olarak tamamen veya kısmen tütün yaprağından imal edilmiş maddeyi ifade eder. Tütün içermeyen ancak tütün mamulünü taklit eder tarzda kullanılan her türlü nargile ve sigara, tütün ürünü kabul edilir.",
  "Tütün Zararları m.3": "(1) Tütün ürünlerinin ve üretici firmaların isim, marka veya alâmetleri kullanılarak her ne suretle olursa olsun reklam ve tanıtımı yapılamaz. Bu ürünlerin kullanılmasını özendiren veya teşvik eden kampanyalar düzenlenemez. Tütün ürünleri üreten ve pazarlamasını yapan firmalar, her ne surette olursa olsun hiçbir etkinliğe isimlerini, amblemlerini veya ürünlerinin marka ya da işaretlerini kullanarak destek olamazlar. (2) ...firmaların isimleri, amblemleri veya ürünlerinin marka ya da işaretleri veya bunları çağrıştıracak alâmetleri kıyafet, takı ve aksesuar olarak taşınamaz. (4) Firmalar ...tütün ürünlerini bayilere veya tüketicilere, teşvik, hediye, eşantiyon, promosyon, bedelsiz veya yardım olarak dağıtamazlar. (6) Televizyonda yayınlanan programlarda, filmlerde, dizilerde, müzik kliplerinde, reklam ve tanıtım filmlerinde, sinema ve tiyatrolarda gösterilen eserlerde tütün ürünlerinin kullanılması ve görüntülerine yer verilmesi ya da internet, topluma açık olan sosyal medya veya benzeri ortamlarda ticari gaye ile veya reklam amacıyla tütün ürünlerinin kullanılması ve görüntülerine yer verilmesi yasaktır. (14) Her türlü sakız, şeker, çerez, oyuncak, kıyafet, takı, aksesuar ve benzeri ürünler tütün ürünlerine benzeyecek veya markasını çağrıştıracak şekilde üretilemez, dağıtılamaz ve satılamaz.\n\n(8) Tütün ürünleri ve tütün ürünü ihtiva eden ve etmeyen nargile ile benzerleri onsekiz yaşını doldurmamış kişilere satılamaz ve tüketimlerine sunulamaz. (9) Onsekiz yaşını doldurmamış kişiler, tütün ürünü işletmelerinde, pazarlanmasında ve satışında istihdam edilemez. (...) (13) Tütün ürünleri, onsekiz yaşını doldurmamış kişilerin doğrudan ulaşacağı ve işletme dışından görülecek şekilde satışa arz edilemez. Tütün ürünleri satış belgesi olmaksızın ve satış belgesinde belirtilen yerin dışında satışa sunulamaz.\n\n(7) Sağlık, eğitim ve öğretim, kültür ve spor hizmeti verilen yerlerde ve bunların yerleşkelerinde tütün ürünlerinin satışı yapılamaz. (10) Tütün ürünleri, paket açılarak adet şeklinde veya daha küçük paketlere bölünerek satılamaz. (11) Tütün ürünleri, (...) otomatik makinelerle, telefon, televizyon ve internet gibi elektronik ortamlarla satılamaz ve satış amacıyla kargo yoluyla taşınamaz.",
  "Tütün Zararları m.4": "(3) Türkiye'de üretilen veya ithal edilen tütün ürünleri paketleri ile tabanı hariç nargile şişelerinin üzerine, en geniş iki yüzünden her birine, bu yüzlerin alanlarının yüzde seksen beşinden az olmamak üzere, özel çerçeve içinde tütün ürünlerinin zararlarını belirten resimli ve Türkçe yazılı uyarılar veya mesajlar konulur. (...) Uyarı mesajlarını taşımayan tütün ürünleri ithal edilemez veya satışa çıkarılamaz. Türkiye'de üretilen veya ithal edilen tütün ürünleri; markanın yazım şekli, yazı karakteri ve boyutu, paket üzerindeki konumu, paketlerin rengi, diğer yazı, ibare ve şekiller dâhil olmak üzere aynı şekilde tasarlanmış düz ve standart paket biçiminde piyasaya arz edilir. Marka, paketin sadece bir yüzeyine ve bu yüzeyin yüzde beşini aşmayacak şekilde yazılır. Paketlerin üzerine markanın logosu, simgesi veya sair işaretleri konulamaz. (...)\n\n(6) Tütün ürünleri sektöründe faaliyet gösteren firmalar, ürün, üretim, pazarlama ve diğer aktiviteleri ile ilgili her türlü bilgiyi istenildiği takdirde onbeş gün içerisinde Sağlık Bakanlığına ve Tütün, Tütün Mamulleri ve Alkollü İçkiler Piyasası Düzenleme Kurumuna vermek zorundadır. (7) Türkiye Radyo ve Televizyon Kurumu ile ulusal, bölgesel ve yerel yayın yapan özel televizyon kuruluşları ve radyolar, ayda en az doksan dakika tütün ürünleri ve sağlığa zararlı diğer alışkanlıkların zararları konusunda uyarıcı, eğitici mahiyette yayınlar yapmak zorundadır. Bu yayınlar, asgari otuz dakikası 17:00-22:00 saatleri arasında olmak üzere 08:00-22:00 saatleri arasında yapılır ve yayınların kopyaları her ay düzenli olarak Radyo ve Televizyon Üst Kuruluna teslim edilir. Bu saatler dışında yapılan yayınlar, aylık doksan dakikalık süreye dahil edilmez.",
  "Tütün/Alkol Piyasası m.8": "Ticari amaç olmaksızın, kendi ürettiği ürünleri kullanarak şahsi tüketimi için elli kilogramı aşmayan sarmalık kıyılmış tütün elde eden veya üçyüzelli litreyi aşmayan fermente alkollü içki imal edenler haricinde, Gıda, Tarım ve Hayvancılık Bakanlığından tesis kurma ve faaliyet izni almadan; tütün işleyenler veya tütün mamulleri, makaron, yaprak sigara kâğıdı, sigara filtresi, etil alkol, metanol ya da alkollü içki üretmek üzere fabrika, tesis veya imalathane kuran ve işletenler bir yıldan üç yıla kadar hapis ve beşbin günden onbin güne kadar adlî para cezası ile cezalandırılır. Bu Kanunun 6 ncı maddesinin ikinci ve üçüncü fıkralarına aykırı hareket edenler ile tesislerinde izin verilen kategori dışında faaliyette bulunanlara da aynı ceza verilir.\n\nTicari amaç olmaksızın, kendi ürettiği ürünleri kullanarak şahsi tüketimi için elli kilogramı aşmayan sarmalık kıyılmış tütün elde eden veya üçyüzelli litreyi aşmayan fermente alkollü içki imal edenler haricinde, (...) [tesis kuran ve işletenler] bir yıldan üç yıla kadar hapis ve beşbin günden onbin güne kadar adlî para cezası ile cezalandırılır.\n\nTütün, tütün mamulleri, etil alkol, metanol ve alkollü içkiler piyasasında Gıda, Tarım ve Hayvancılık Bakanlığından gerekli izinleri alarak veya almadan mal veya hizmet üreten, işleyen, ihraç veya ithal eden, pazarlayan, alan veya satan gerçek ve tüzel kişilere aşağıda yazılı idarî yaptırımlar uygulanır:\n\no) (...) Ticari amaçla sarmalık kıyılmış tütün üretenler ile satan veya satışa arz edenlere ürettikleri, sattıkları veya satışa arz ettikleri tütünün; 50 kilograma kadar (50 kilogram dâhil) olması halinde 250 TL. 50 kilogramdan 100 kilograma kadar (100 kilogram dâhil) olması halinde 500 TL. 100 kilogramdan 250 kilograma kadar (250 kilogram dâhil) olması halinde 1.500 TL. 250 kilogramdan 500 kilograma kadar (500 kilogram dâhil) olması halinde 3.000 TL. 500 kilogramdan fazla olması halinde 5.000 TL. idari para cezası verilir.\n\nİdarî para cezaları, fiillerin tekrarı halinde, bir önceki cezanın iki katı olarak verilir. Beşinci fıkranın (c) bendinde sayılan fiillerin tekrarı halinde ayrıca ihlale konu ürünün piyasaya arzının bir yıla kadar durdurulmasına; (a), (b), (d), (e), (f), (j), (k), (1), (m), (n), (o), (p), (r) ve (s) bentlerinde sayılan fiillerin, ilk fiilin işlenmesinden sonraki beş yıl içinde üçüncü defa işlenmesi halinde ise belgelerin iptaline karar verilir. Satış belgesi iptal edilen satıcılar, (...) işyerinin farklı işletme adı altında fiilen işletilmesi halinde, bu işletme üzerine kayıtlı görünen üçüncü kişiler adına iki yıl süreyle yeni belge başvurusunda bulunulamaz.\n\nBeşinci fıkranın (f), (g), (h), (ı), (j), (n), (o), (p), (r) ve (s) bentlerinde yazılı fiiller hakkında idarî yaptırım uygulamaya ve bu fiillerin konusunu oluşturan her türlü eşyanın mülkiyetinin kamuya geçirilmesi kararını vermeye mahalli mülkî amirler, diğer bentlerde yazılı fiiller hakkında idarî para cezası vermeye Gıda, Tarım ve Hayvancılık Bakanlığı yetkilidir. Mahalli mülkî amirlerce uygulanan idarî yaptırımlar onbeş gün içinde Gıda, Tarım ve Hayvancılık Bakanlığına iletilir.\n\nBu Kanun hükümlerine göre verilen idarî yaptırım kararlarına karşı 6/1/1982 tarihli ve 2577 sayılı İdari Yargılama Usulü Kanunu hükümlerine göre kanun yoluna başvurulabilir. Ancak, idare mahkemesinde dava, işlemin tebliği tarihinden itibaren onbeş gün içinde açılır. İdare mahkemesinde iptal davası açılmış olması, kararın yerine getirilmesini durdurmaz.\n\nBu Kanuna, 4250 sayılı Kanuna, 213 sayılı Kanunun 359 uncu maddesinin (d) fıkrasına veya 21/3/2007 tarihli ve 5607 sayılı Kaçakçılıkla Mücadele Kanununun 3 üncü maddesinin onuncu, onaltıncı, onyedinci, onsekizinci, yirminci ve yirmibirinci fıkralarına aykırı fiillerden dolayı haklarında kesinleşmiş mahkûmiyet kararı olanlara, bu Kanun kapsamında yürütülen faaliyetlere ilişkin hiçbir belge verilmez, verilmiş olanlar Tarım ve Orman Bakanlığınca iptal edilir. (...) soruşturma ve/veya kovuşturma başlatılması durumunda bu Kanun kapsamında yürütülen faaliyetlere ilişkin verilen belgeler, durumun Bakanlığa yargı merciince bir hafta içerisinde bildirilmesiyle (...) askıya alınır. (...) Bakanlıkça askıya alma işleminin kaldırılıp kaldırılmayacağı altı ayda bir değerlendirilir. Ancak kovuşturmaya yer olmadığına dair kararın kesinleşmesi üzerine ya da mahkûmiyet dışında bir hüküm veya hükmün açıklanmasının geri bırakılmasına karar verilmesi halinde kesinleşmesi beklenmeksizin Bakanlık tarafından askıya alma işlemi ortadan kaldırılır.\n\nk) Tütün mamulleri veya alkollü içkilerin, etil alkol, metanol, makaron, sarmalık kıyılmış tütünün ve yaprak sigara kâğıdının tüketicilere satışını (...) internet, televizyon, faks ve telefon gibi elektronik ticaret araçları ya da posta ile sipariş yöntemi kullanarak yapmak üzere satış sistemi kuran veya faaliyette bulunanlara yirmibin Yeni Türk Lirasından yüzbin Yeni Türk Lirasına kadar idarî para cezası verilir. (...) Satışın internet ortamında yapılması halinde, (...) 5651 sayılı (...) Kanunda öngörülen usullere göre erişimin engellenmesine karar verilir ve bu karar hakkında da anılan Kanun hükümleri uygulanır.\n\ng) Gıda, Tarım ve Hayvancılık Bakanlığından satış belgesi almadan tütün mamulleri, makaron, yaprak sigara kâğıdı, etil alkol, metanol ve alkollü içkilerin toptan satışını yapanlara ellibin Yeni Türk Lirası; perakende satışını yapanlara ise beşbin Yeni Türk Lirası idarî para cezası verilir.\n\nf) Gıda, Tarım ve Hayvancılık Bakanlığından belge almamış kişilerden ürün alan veya bu kişilere ürün satan ya da belgesinde belirtilen işyeri dışında satış yapan toptan veya perakende tütün mamulü, makaron, yaprak sigara kâğıdı, etil alkol, metanol veya alkollü içki satıcıları ya da açık içki satıcılarına bin Yeni Türk Lirasından onbin Yeni Türk Lirasına kadar idarî para cezası verilir.\n\na) (...) satış/faaliyet raporu, bilgi/belge/numune vermeyenlere, yanlış/yanıltıcı bilgi verenlere, tesisi incelemeye açmayanlara ellibin Yeni Türk Lirasından ikiyüzellibin Yeni Türk Lirasına kadar (...). b) (...) tütünleri tescil ettirmeyenlere (...) onbin Yeni Türk Lirasından ellibin Yeni Türk Lirasına kadar (...). c) İzin almadan (...) ana girdilerde veya ürün ambalajında değişiklik yaparak ürünleri piyasaya arz edenlere ellibin Yeni Türk Lirasından beşyüzbin Yeni Türk Lirasına kadar (...). d) (...) proje tadilat (...) makinelerini (...) nakleden, başka bir firmaya devreden ya da ülke dışına çıkaranlara (...) ellibin Yeni Türk Lirasından beşyüzbin Yeni Türk Lirasına kadar (...). e) (...) dökme alkollü içkileri (...) piyasaya arz eden, sevkiyatını yapan veya (...) farklı yerlerde depolayanlara ikiyüzbin Yeni Türk Lirası (...). ı) (...) uygunluk belgesi almadan enfiye, çiğneme, nargile tütünü veya yaprak sigara kâğıdı ya da makaron ile sigara filtresi üretenler ile satan veya satışa arz edenlere (...) beşbin Yeni Türk Lirası (...). j) Yetkili olmadıkları halde, açık olarak içki satışı veya sunumu yapanlar ile (...) arz ambalajlarını bozmak veya bunları bölmek suretiyle satanlara bin Yeni Türk Lirasından onbin Yeni Türk Lirasına kadar (...). l) (...) raf veya standlara, (...) teşhir ünitesine, reklam ve tanıtımına ilişkin mevzuata (...) aykırılık (...) veya herhangi bir firmaya üstünlük sağlayacak şekilde yerleştirenlere otuzbin Yeni Türk Lirası (...). m) Tütün mamulleri (...) kullanımını ve satışını özendirici (...) kampanya, promosyon, reklam ve tanıtım (...) düzenlemelere aykırı hareket edenlere otuzbin Yeni Türk Lirası (...). n) Tütün mamulleri (...) otomatik satış makinesi ile satanlara veya bahis oynatmak veya ödül vermek gibi yollarla verenlere, fiilleri suç oluşturmadığı takdirde ellibin Yeni Türk Lirasından ikiyüzellibin Yeni Türk Lirasına kadar (...). Eyleme konu makineler hakkında müsadere kararı verilmemiş ise ayrıca mülkiyetin kamuya geçirilmesine karar verilir. p) Mevzuatta tanımlanmış amacı dışında ya da teknik düzenlemesine uygun olmayan etil alkolü bulunduranlara, satışa sunanlara veya satanlara yirmibin Türk Lirasından yüzbin Türk Lirasına kadar (...).",
  "Uyuşturucu (3298) m.1": "Çizilmiş veya çizilmemiş haşhaş kapsülleri ile, ham afyon, tıbbi afyon ve morfin evsafını haiz afyon alkaloidleri, tuzları, esterleri ve eterleri; koka yaprağı ve bunun alkaloidleri, tuzları, esterleri ve eterleri ile Sağlık ve Sosyal Yardım Bakanlığınca tayin olunacak diğer uyuşturucu maddelerin alımı, satımı, imali, ithali ve ihracı ile ilgili hususlar Cumhurbaşkanının tespit edeceği esaslara göre yürütülür. Bahis konusu maddelerin elde edildiği bitkilerin yurt içinde ekimi ve araştırması izne tabidir. Kullanılması zararlı olduğu ve \"Toxicommanie\" yaptığı Sağlık ve Sosyal Yardım Bakanlığınca tespit edilen diğer tabii ve sentetik maddeler de yine bu Bakanlığın teklifi üzerine Cumhurbaşkanı Kararı ile bu Kanun kapsamına alınabilir.",
  "Uyuşturucu (3298) m.2": "Haşhaş ekilecek, afyon ve kapsül üretilecek yerler memleketin tarımsal ve ekonomik durumu, yurt içi ihtiyacı, ihraç imkanları ve mevcut stok durumuna göre her yıl Cumhurbaşkanınca tespit edilir ve karar en geç 1 Temmuza kadar yayımlanır. Bu konuda yeni bir karar alınmaması halinde, önceki kararname hükümlerinin uygulanmasına devam olunur. Kamu kurum ve kuruluşlarınca bilimsel araştırmalar için yapılacak ekilişler hakkında birinci fıkra hükmü uygulanmaz.\n\nTespit ve ilan edilen yerlerde haşhaş ekimi yapacaklar ilgili kuruluştan izin belgesi almakla yükümlüdür. İzin belgeleri bir üretim yılı için geçerli olup, başkasına devir edilemez. İzin belgeleri herhangi bir sebeple iptal olunanların ekilmiş haşhaş tarlaları masrafı üreticiye ait olmak kaydıyla ilgili kuruluş adına herhangi bir bedel ödenmeksizin toplatılır veya imha ettirilir.\n\n4 üncü madde hükümlerine göre veya kaçakçılık suçlarının herhangi birisinden veya Türk Ceza Kanununun ilgili maddelerine göre kesinleşmiş mahkümiyeti bulunanlara, bu mahkümiyetleri afla ortadan kalkmış olsa bile, izin belgesi verilemez; verilmiş ise iptal edilir. İzin belgesi verilmesinden sonra yukarıdaki fıkrada yazılı suçlardan biri ile mahküm olanların bu mahkümiyetleri kesinleştiğinde izin belgeleri iptal edilir.",
  "Uyuşturucu (3298) m.4": "İzinsiz olarak haşhaş ekimi yapan kişi bir yıldan beş yıla kadar hapis ve adlî para cezası ile cezalandırılır. Bu madde kapsamında ekim yapma ibaresinden, tohumun toprağa ekilmesinden ürünün hasadına kadarki süreç anlaşılır.\n\nİzin almış olmakla birlikte, bilerek belgesinde belirtilen alandan fazla yerde veya izin belgesinde kayıtlı yerden başka yerde haşhaş ekimi yapan kişi altı aydan üç yıla kadar hapis ve adlî para cezası ile cezalandırılır.\n\nİzin belgesinde tespit edilen miktardan az ham afyon veya kapsül teslim eden üreticilere, fiil suç oluşturmadığı takdirde, mahallî mülkî amir tarafından eksik teslim edilen miktarların teslim anındaki baş alım fiyatının iki misli kadar idarî para cezası verilir.\n\nHam afyon, hazırlanmış afyon, tıbbî afyon ve bunların müstahzarları Türk Ceza Kanununun uygulanmasında uyuşturucu maddelerden sayılır. (...) İzinsiz ham afyon üretenler, Türk Ceza Kanunu hükümlerine göre cezalandırılır. (...) Kontrol ve denetim görevini yerine getirmeyen muhtarlar ve kolluk görevlileri, Türk Ceza Kanunu hükümlerine göre cezalandırılır. (...) Bu maddede tanımlanan suçların ekim bölgesi içinde işlenmesi halinde, 21/3/2007 tarihli ve 5607 sayılı Kaçakçılıkla Mücadele Kanununun 23 üncü maddesi hükümleri uygulanmaz.",
  "Uyuşturucu Murakabe m.20": "Gümrüklerden ülkeye izinsiz sokulmaya çalışılan veya ülke içinde izinsiz satıldığı görülen ve her ne surette olursa olsun kanuni yetkisi olmayanlar yanında bulunan uyuşturucu maddeler, zabıtanın, Gümrük ve Ticaret Bakanlığı memurlarının, sağlık ve sosyal yardım bakanlığı müfettiş ve müdürlerinin, hükümet tabiplerinin, sağlık ocağı tabiplerinin, hudut ve sahiller sağlık teşkilatı memurlarının herhangi birisi tarafından bir tutanak düzenlemek suretiyle zaptedilir. Gerek bunlar, gerekse izinsiz imal edilen veya ihraç edilmek istenirken Gümrük ve Ticaret Bakanlığı tarafından zaptolunanlar sahipleri belli olsun veya olmasın suç delili olarak Cumhuriyet Savcılığınca muhafaza altına alınırlar.\n\nUyuşturucu maddelerin kesin olarak raporları alındıktan sonra, yönetmelikte belirlenen usule uygun olarak alınacak örneklerin saklanması kaydıyla müsaderesine sulh ceza hâkimliğince soruşturmanın her safhasında karar verilir.\n\nMüsaderesine karar verilen uyuşturucu maddeler gereği yapılmak üzere mühürlü olarak mahalli mülki amirliğe teslim edilir. (...) Örnek olarak alınan uyuşturucu maddeler hükümle birlikte müsadere edilir ve ancak hükmün kesinleşmesinden sonra mahalli mülki amirliğe teslim edilir.\n\nYönetmelikte belirlenecek esaslar dahilinde, uyuşturucu madde arama köpeği eğitiminde kullanılmak üzere, ihtiyaç duyulacak cins ve miktarda uyuşturucu madde, İçişleri Bakanının talebi üzerine, İçişleri Bakanlığının ilgili bağlı kuruluşlarına; Millî Savunma Bakanının talebi üzerine Türk Silahlı Kuvvetlerine; Gümrük ve Ticaret Bakanının talebi üzerine Gümrükler Muhafaza Genel Müdürlüğüne; uyuşturucu maddelerin tıbbî amaçlı olarak kullanılabilirliğini araştırmak üzere ihtiyaç duyulacak cins ve miktarda uyuşturucu madde ise Tarım ve Köyişleri Bakanının talebi üzerine Tarım ve Köyişleri Bakanlığının ilgili bağlı kuruluşlarına teslim edilir.",
  "Uyuşturucu Murakabe m.21": "Müsaderesine karar verilen uyuşturucu maddeler, valinin görevlendireceği bir yetkilinin başkanlığındaki ve il savcısının veya yardımcısının nezaretçi olarak katıldığı heyet huzurunda imha edilir.",
  "Uyuşturucu Murakabe m.23": "Her ne maksatla olursa olsun izinsiz olarak kenevir yetiştirmek yasaktır. İzinsiz yetiştirilen kenevir bitkisi, Tarım Orman ve Köyişleri Bakanlığı teşkilatında görevli ziraat mühendislerinin, bunların bulunmadığı yerlerde ziraat teknisyenlerinin vereceği rapor üzerine mahallin en büyük mülki amirinin emriyle zabıta tarafından imha edilir veya ettirilir.\n\nİmhada kullanılacak araç ve gereçler, Jandarma Genel Komutanlığı bütçesine konulacak ödenekten sağlanır. İmha dolayısıyla ortaya çıkan masraf, sonradan izinsiz ekim yapanlardan 6183 sayılı Amme Alacaklarının Tahsil Usulü Hakkında Kanuna göre tahsil edilir.\n\nLif, tohum ve sap üretimi ile tıbbi ürünler, sağlık ürünleri, uyuşturucu etkisi olmayacak oranda kişisel bakım ürünleri ve destek ürünleri elde etmeye yönelik çiçek ve yaprak üretimi amaçlı kenevir yetiştiriciliği, Tarım ve Orman Bakanlığının iznine tabidir. Lif, tohum ve sap üretimi amacıyla izinli kenevir yetiştiriciliği Tarım ve Orman Bakanlığınca çıkarılacak yönetmelikle düzenlenir.\n\nİzin belgesi almadan ya da izin belgesi almasına rağmen bilerek belgesinde belirtilen alandan fazla yerde veya izin belgesinde kayıtlı yerden başka yerde kenevir ekimi yapan kişi, elli günden az olmamak üzere adlî para cezası ile cezalandırılır. Esrar elde etmek amacıyla kenevir ekimi yapan kişi dört yıldan on iki yıla kadar hapis ve beşyüz günden onbin güne kadar adlî para cezası ile cezalandırılır. Münhasıran kendi kullanımı için ihtiyaç duyduğu esrarı elde etmek amacıyla kenevir ekimi yapan kişi bir yıldan üç yıla kadar hapis cezası ile cezalandırılır. Bu madde kapsamında ekim yapma ibaresinden, tohumun toprağa ekilmesinden ürünün hasadına kadarki süreç anlaşılır. (Ek fıkra) Esrar elde etmek amacıyla kenevir ekmek suçu bakımından 5271 sayılı Ceza Muhakemesi Kanununun 135 inci maddesinde yer alan iletişimin tespiti, dinlenmesi ve kayda alınması ile 140 ıncı maddesinde yer alan teknik araçlarla izleme tedbirlerine ilişkin hükümler uygulanabilir.",
  "Vatandaşlık Yön m.10": "[Madde başlığı: Onsekiz yaşını tamamladıktan sonra doğuma ilişkin yurt dışından yapılan bildirimlere ait karar] (1) Bakanlıkça yapılacak inceleme ve araştırma sonucunda Türk vatandaşı anadan doğduğu veya babadan olduğu tespit edilen kişinin, doğumundan itibaren Türk vatandaşı olduğu aile kütüğüne tescil edilir. (2) Türk vatandaşı anadan doğduğu veya babadan olduğunu ispata yarayacak yeterli bilgi ve belge bulunmaması halinde, ilgili kişinin bu yöndeki talebi Bakanlıkça reddedilir.",
  "Vatandaşlık Yön m.12": "(1) Bakanlıkça yapılacak inceleme ve araştırma sonucunda; 11 inci maddede belirtilen şartları taşıdığı tespit edilen çocuk, doğumundan itibaren Türk vatandaşlığını kazanır ve yerleşim yerinin bulunduğu idari birimin son hanesinden bir sonraki haneye tescil edilir. (2) Aranan şartları taşımayanların talepleri Bakanlıkça reddedilir. (3) Türkiye'de bulunmuş çocuk, 29/9/2006 tarihli ve 2006/11081 sayılı Bakanlar Kurulu Kararıyla yürürlüğe konulan Nüfus Hizmetleri Kanununun Uygulanmasına İlişkin Yönetmeliğin 32 nci maddesine göre aile kütüğüne tescil edilir.",
  "Vatandaşlık Yön m.22": "(1) Kanunun 13 üncü ve 43 üncü maddelerinde belirtilen kişiler, millî güvenlik bakımından engel teşkil edecek bir hali bulunmamak şartıyla Türkiye'de ikamet şartı aranmaksızın, Türk vatandaşlığını yeniden kazanabilirler. (2) Kanunun 14 üncü maddesinde belirtilen kişiler ise millî güvenlik bakımından engel teşkil edecek bir hali bulunmamak ve Türkiye'de üç yıl ikamet etmek şartıyla Türk vatandaşlığını yeniden kazanabilirler.",
  "Vatandaşlık Yön m.3": "b) Bakanlık: İçişleri Bakanlığını, (...) f) Genel Müdürlük: Nüfus ve Vatandaşlık İşleri Genel Müdürlüğünü, (...) j) Komisyon: Vatandaşlık başvuru inceleme komisyonunu, (...) ifade eder.\n\nc) Çocuk: Onsekiz yaşını tamamlamamış olan kişiyi, (...) e) Ergin: 4721 sayılı Türk Medenî Kanununa göre ergin olan kişiyi, (...) ş) Türk vatandaşı: Türkiye Cumhuriyeti Devletine vatandaşlık bağı ile bağlı olan kişiyi, (...) ifade eder.\n\ng) Göçmen: Türk soyundan ve Türk kültürüne bağlı olup yerleşmek amacıyla tek başına veya toplu halde Türkiye'ye gelip 5543 sayılı İskân Kanunu uyarınca göçmen olarak kabul edilen kişiyi, (...) l) Mavi Kart: Kanunun 28 inci maddesi kapsamına girenlere verilen kartı, (...) u) Yabancı: Türkiye Cumhuriyeti Devleti ile vatandaşlık bağı bulunmayan kişiyi, (...) ifade eder.\n\ns) Türkiye Cumhuriyeti kimlik numarası: 5490 sayılı Nüfus Hizmetleri Kanununa göre her Türk vatandaşı için verilen ve onbir rakamdan oluşan numarayı, (...) ü) Yabancı kimlik numarası: Türkiye'de herhangi bir amaçla en az altı ay süreli ikamet eden yabancıların kayıtlarına ulaşmak amacıyla elektronik ortamda verilen, onbir rakamdan oluşan numarayı, (...) ifade eder.\n\nç) Çok vatandaşlık: Türk vatandaşının aynı anda birden çok vatandaşlığa sahip olmasını, (...) d) Dış temsilcilik: Türkiye Cumhuriyetinin yabancı ülkelerde bulunan büyükelçiliğini, başkonsolosluğunu veya konsolosluğunu, (...) ğ) İdari birim: Kişilerin kayıtlı bulundukları aile kütüklerinin ait olduğu mahalle veya köyü, (...) h) İkamet: Yabancının yasal ikamet izniyle Türkiye'de bulunmasını, (...) ı) İl müdürlüğü: İl nüfus ve vatandaşlık müdürlüğünü, (...) m) Mutad mesken: Kişinin yerleşim yerini, (...) ö) Nüfus müdürlüğü: İlçe nüfus müdürlüğünü, (...) ifade eder.",
  "Vatandaşlık Yön m.5": "Türk vatandaşlığı, doğumla veya sonradan olmak üzere iki yolla kazanılır.",
  "Yabancılar m.102": "MADDE 102 – (1) Diğer kanunlara göre daha ağır bir ceza gerektirmediği takdirde; a) 5 inci maddeye aykırı şekilde, Türkiye'ye yasa dışı giren veya Türkiye'yi yasa dışı terk eden ya da buna teşebbüs eden yabancılar hakkında iki bin Türk Lirası, b) 9 uncu maddenin birinci ve ikinci fıkraları uyarınca Türkiye'ye girişleri yasaklanmış olmasına rağmen Türkiye'ye girebilmiş olanlar hakkında bin Türk Lirası, c) 56 ncı maddenin birinci fıkrasında tanınan sürede Türkiye'den ayrılmayanlar hakkında bin Türk Lirası, ç) 57 nci, 58 inci, 60 ıncı ve 68 inci maddeler kapsamındaki işlemler sırasında kaçanlar hakkında bin Türk Lirası, d) (Ek: 2018-7078/165 md.) 98 inci maddenin birinci ve ikinci fıkralarında yer alan yükümlülüklere uymayan taşıyıcılar hakkında, fiil suç oluşturmadığı takdirde, bin Türk Lirasından onbin Türk Lirasına kadar, e) (Ek:6/12/2019-7196/88 md.) 57/A maddesinin birinci fıkrasının (a), (b), (c), (ç), (d) ve (f) bentlerinde yer alan yükümlülüklere uymayanlara bin Türk Lirası, idari para cezası uygulanır.\n\nMADDE 102 – (...) (2) (...) Geçerli seyahat belgesi, Türkiye Cumhuriyeti yetkili makamlarından verilmiş yabancı kimlik kartı, ikamet izni veya geçerli yol izin belgesi olmayan yabancı şahısların ülkeye girmesine, ülkeden çıkarılmasına, ülke içinde herhangi bir araç veya binek hayvan vasıtasıyla veya yaya olarak seyahat etmesine, barınmasına, konaklamasına imkân sağlayan kişiler ile mülkiyetindeki gayrimenkulü kiralayanlara, kanunlarda ayrıca suç olarak tanımlanmayan eylemler nedeniyle tespit edilen her bir yabancı sayısınca bin Türk Lirası idari para cezası verilir. (3) İdari para cezası öngörülen kabahatlerin bir takvim yılı içinde gerçek kişiler tarafından tekrarı hâlinde, para cezaları yarı oranında artırılarak uygulanır. (4) Bu maddedeki idari para cezalarının uygulanması, Kanunda öngörülen diğer idari tedbirlerin uygulanmasına engel teşkil etmez. (5) Bu maddedeki idari para cezaları, valilik veya Genel Müdürlük ya da kolluk birimlerince uygulanır. Verilen para cezaları tebliğ tarihinden itibaren otuz gün içinde ödenir. (6) (...) Bakanlıkça bu Kanun kapsamında yürürlüğe konulan düzenlemelerde belirtilen yükümlülüklere uymayanlara Genel Müdürlük veya valilikler tarafından beşyüz Türk Lirasından onbin Türk Lirasına kadar idari para cezası verilebilir.",
  "Yabancılar m.3": "MADDE 3 – (1) Bu Kanunun uygulanmasında; (...) b) Avrupa ülkeleri: Avrupa Konseyi üyesi olan ülkeler ile Cumhurbaşkanınca belirlenecek diğer ülkeleri, c) Bakan: İçişleri Bakanını, ç) Bakanlık: İçişleri Bakanlığını, (...) g) Genel Müdür: Göç İdaresi Genel Müdürünü, ğ) Genel Müdürlük: Göç İdaresi Genel Müdürlüğünü, (...) ö) Son karar: Başvuru sahibinin başvurusuyla veya uluslararası koruma statüsü sahibi kişinin statüsüyle ilgili kararlardan; idari itirazda bulunulmaması ve yargıya başvurulmaması hâlinde Genel Müdürlük tarafından verilen kararı veya yargıya başvurulması sonucunda temyiz edilmesi mümkün olmayan kararı, (...) t) Vize: Türkiye'de en fazla doksan güne kadar kalma hakkı tanıyan ya da transit geçişi sağlayan izni, (...) ü) Yabancı: Türkiye Cumhuriyeti Devleti ile vatandaşlık bağı bulunmayan kişiyi, (...) z) (...) Kabul edilemeyen yolcu: Ülkeye giriş yapabilmek veya ülkeden transit geçebilmek için sınır kapılarına gelen ancak mevzuatta aranan koşulları taşımadığından ülkeye girişine veya ülkeden transit geçişine izin verilmeyen kişiyi, (...) ifade eder.\n\nMADDE 3 – (1) Bu Kanunun uygulanmasında; (...) f) Destekleyici: Aile birliği amacıyla Türkiye'ye gelecek yabancıların masraflarını üstlenen ve ikamet izni talebinde bulunanlar tarafından başvuruya dayanak gösterilen Türk vatandaşını veya Türkiye'de yasal olarak bulunan yabancıyı, (...) ı) Göç: Yabancıların, yasal yollarla Türkiye'ye girişini, Türkiye'de kalışını ve Türkiye'den çıkışını ifade eden düzenli göç ile yabancıların yasa dışı yollarla Türkiye'ye girişini, Türkiye'de kalışını, Türkiye'den çıkışını ve Türkiye'de izinsiz çalışmasını ifade eden düzensiz göçü ve uluslararası korumayı, (...) k) Konsolosluk: Türkiye Cumhuriyeti başkonsolosluklarını, konsolosluklarını veya büyükelçilik konsolosluk şubelerini, l) Özel ihtiyaç sahibi: Başvuru sahibi ile uluslararası koruma statüsü sahibi kişilerden; refakatsiz çocuk, engelli, yaşlı, hamile, beraberinde çocuğu olan yalnız anne ya da baba veya işkence, cinsel saldırı ya da diğer ciddi psikolojik, bedensel ya da cinsel şiddete maruz kalmış kişiyi, m) Refakatsiz çocuk: Sorumlu bir kişinin etkin bakımına alınmadığı sürece, kanunen ya da örf ve adet gereği kendisinden sorumlu bir yetişkinin refakati bulunmaksızın Türkiye'ye gelen veya Türkiye'ye giriş yaptıktan sonra refakatsiz kalan çocuğu, (...) ö) Son karar: Başvuru sahibinin başvurusuyla veya uluslararası koruma statüsü sahibi kişinin statüsüyle ilgili kararlardan; idari itirazda bulunulmaması ve yargıya başvurulmaması hâlinde Genel Müdürlük tarafından verilen kararı veya yargıya başvurulması sonucunda temyiz edilmesi mümkün olmayan kararı, (...) z) (...) Kabul edilemeyen yolcu: Ülkeye giriş yapabilmek veya ülkeden transit geçebilmek için sınır kapılarına gelen ancak mevzuatta aranan koşulları taşımadığından ülkeye girişine veya ülkeden transit geçişine izin verilmeyen kişiyi, (...) ifade eder.",
  "Yabancılar m.4": "MADDE 4 – (1) Bu Kanun kapsamındaki hiç kimse, işkenceye, insanlık dışı ya da onur kırıcı ceza veya muameleye tabi tutulacağı veya ırkı, dini, tabiiyeti, belli bir toplumsal gruba mensubiyeti veya siyasi fikirleri dolayısıyla hayatının veya hürriyetinin tehdit altında bulunacağı bir yere gönderilemez.",
  "Yabancılar m.5": "MADDE 5 – (1) Türkiye'ye giriş ve Türkiye'den çıkış, sınır kapılarından, geçerli pasaport veya pasaport yerine geçen belgelerle yapılır.",
  "Yabancılar m.52": "MADDE 52 – (1) Yabancılar, sınır dışı etme kararıyla, menşe ülkesine veya transit gideceği ülkeye ya da üçüncü bir ülkeye sınır dışı edilebilir.",
  "Yabancılar m.53": "MADDE 53 – (1) Sınır dışı etme kararı, Genel Müdürlüğün talimatı üzerine veya resen valiliklerce alınır. (...) (3) (Değişik:21/11/2024-7533/36 md.) Yabancı veya yasal temsilcisi ya da avukatı, sınır dışı etme kararına karşı, kararın tebliğinden itibaren yedi gün içinde idare mahkemesine başvurabilir. Mahkemeye başvuran kişi, sınır dışı etme kararını veren makama da başvurusunu bildirir. (...) Başvurular dosyanın tekemmülünden veya ara karar ya da duruşma yapılması gereken hâllerde bunların tamamlanmasından itibaren on beş gün içinde sonuçlandırılır. Mahkemenin bu konuda vermiş olduğu karar kesindir. Yabancının rızası saklı kalmak kaydıyla, dava açma süresi içinde veya yargı yoluna başvurulması hâlinde yargılama sonuçlanıncaya kadar yabancı sınır dışı edilmez.",
  "Yabancılar m.54": "MADDE 54 – (1) Aşağıda sayılan yabancılar hakkında sınır dışı etme kararı alınır: a) 5237 sayılı Kanunun 59 uncu maddesi kapsamında sınır dışı edilmesi gerektiği değerlendirilenler b) Terör örgütü yöneticisi, üyesi, destekleyicisi veya çıkar amaçlı suç örgütü yöneticisi, üyesi veya destekleyicisi olanlar c) Türkiye'ye giriş, vize ve ikamet izinleri için yapılan işlemlerde gerçek dışı bilgi ve sahte belge kullananlar ç) Türkiye'de bulunduğu süre zarfında geçimini meşru olmayan yollardan sağlayanlar d) Kamu düzeni veya kamu güvenliği ya da kamu sağlığı açısından tehdit oluşturanlar e) Vize veya vize muafiyeti süresini on günden fazla aşanlar veya vizesi iptal edilenler f) İkamet izinleri iptal edilenler g) İkamet izni bulunup da süresinin sona ermesinden itibaren kabul edilebilir gerekçesi olmadan ikamet izni süresini on günden fazla ihlal edenler ğ) Çalışma izni olmadan çalıştığı tespit edilenler h) Türkiye'ye yasal giriş veya Türkiye'den yasal çıkış hükümlerini ihlal edenler ya da bu hükümleri ihlale teşebbüs edenler ı) Hakkında Türkiye'ye giriş yasağı bulunmasına rağmen Türkiye'ye geldiği tespit edilenler i) Uluslararası koruma başvurusu reddedilen, uluslararası korumadan hariçte tutulan, başvurusu kabul edilemez olarak değerlendirilen, başvurusunu geri çeken, başvurusu geri çekilmiş sayılan, uluslararası koruma statüleri sona eren veya iptal edilenlerden haklarında verilen son karardan sonra bu Kanunun diğer hükümlerine göre Türkiye'de kalma hakkı bulunmayanlar j) İkamet izni uzatma başvuruları reddedilenlerden, on gün içinde Türkiye'den çıkış yapmayanlar k) (...) Uluslararası kurum ve kuruluşlar tarafından tanımlanan terör örgütleriyle ilişkili olduğu değerlendirilenler. (2) (...) Bu maddenin birinci fıkrasının (b), (d) ve (k) bentleri kapsamında oldukları değerlendirilen uluslararası koruma başvuru sahibi veya uluslararası koruma statüsü sahibi kişiler hakkında uluslararası koruma işlemlerinin her aşamasında sınır dışı etme kararı alınabilir.",
  "Yabancılar m.55": "MADDE 55 – (1) 54 üncü madde kapsamında olsalar dahi, aşağıdaki yabancılar hakkında sınır dışı etme kararı alınmaz: a) Sınır dışı edileceği ülkede ölüm cezasına, işkenceye, insanlık dışı ya da onur kırıcı ceza veya muameleye maruz kalacağı konusunda ciddi emare bulunanlar b) Ciddi sağlık sorunları, yaş ve hamilelik durumu nedeniyle seyahat etmesi riskli görülenler c) Hayati tehlike arz eden hastalıkları için tedavisi devam etmekte iken sınır dışı edileceği ülkede tedavi imkânı bulunmayanlar ç) Mağdur destek sürecinden yararlanmakta olan insan ticareti mağdurları d) Tedavileri tamamlanıncaya kadar, psikolojik, fiziksel veya cinsel şiddet mağdurları (2) Birinci fıkra kapsamındaki değerlendirmeler, herkes için ayrı yapılır. Bu kişilerden, belli bir adreste ikamet etmeleri, istenilen şekil ve sürelerde bildirimde bulunmaları istenebilir.",
  "Yabancılar m.56": "MADDE 56 – (1) Sınır dışı etme kararı alınanlara, sınır dışı etme kararında belirtilmek kaydıyla, Türkiye'yi terk edebilmeleri için on beş günden az olmamak üzere otuz güne kadar süre tanınır. Ancak, kaçma ve kaybolma riski bulunanlara, yasal giriş veya yasal çıkış kurallarını ihlal edenlere, sahte belge kullananlara, asılsız belgelerle ikamet izni almaya çalışanlara veya aldığı tespit edilenlere, kamu düzeni, kamu güvenliği veya kamu sağlığı açısından tehdit oluşturanlara bu süre tanınmaz. (2) Türkiye'den çıkış için süre tanınan kişilere, Çıkış İzin Belgesi verilir. Bu belge hiçbir harca tabi değildir. (...)",
  "Yabancılar m.57": "MADDE 57 – (1) 54 üncü madde kapsamındaki yabancılar, kolluk tarafından yakalanmaları hâlinde, haklarında karar verilmek üzere derhâl valiliğe bildirilir. Bu kişilerden, sınır dışı etme kararı alınması gerektiği değerlendirilenler hakkında, sınır dışı etme kararı valilik tarafından alınır. Değerlendirme ve karar süresi kırk sekiz saati geçemez. (2) (Değişik:6/12/2019-7196/77 md.) Hakkında sınır dışı etme kararı alınanlardan; kaçma ve kaybolma riski bulunan, Türkiye'ye giriş veya çıkış kurallarını ihlal eden, sahte ya da asılsız belge kullanan, kabul edilebilir bir mazereti olmaksızın Türkiye'den çıkmaları için tanınan sürede çıkmayan, kamu düzeni, kamu güvenliği veya kamu sağlığı açısından tehdit oluşturanlar hakkında valilik tarafından idari gözetim kararı alınır ya da 57/A maddesi uyarınca idari gözetime alternatif yükümlülükler getirilir. Hakkında idari gözetim kararı alınan yabancılar, yakalamayı yapan kolluk birimince geri gönderme merkezlerine kırk sekiz saat içinde götürülür. (3) Geri gönderme merkezlerindeki idari gözetim süresi altı ayı geçemez. Ancak bu süre, sınır dışı etme işlemlerinin yabancının iş birliği yapmaması veya ülkesiyle ilgili doğru bilgi ya da belgeleri vermemesi nedeniyle tamamlanamaması hâlinde, en fazla altı ay daha uzatılabilir. (4) (Değişik:6/12/2019-7196/77 md.) İdari gözetimin devamında zaruret olup olmadığı, valilik tarafından her ay düzenli olarak değerlendirilir. Gerek görüldüğünde, otuz günlük süre beklenmez. İdari gözetimin devamında zaruret görülmeyen yabancılar için idari gözetim derhâl sonlandırılır. Bu yabancılara, 57/A maddesi uyarınca idari gözetime alternatif yükümlülükler getirilir.\n\nMADDE 57 – (...) (5) İdari gözetim kararı, idari gözetim süresinin uzatılması ve her ay düzenli olarak yapılan değerlendirmelerin sonuçları, gerekçesiyle birlikte yabancıya veya yasal temsilcisine ya da avukatına tebliğ edilir. Aynı zamanda, idari gözetim altına alınan kişi bir avukat tarafından temsil edilmiyorsa, kendisi veya yasal temsilcisi kararın sonucu, itiraz usulleri ve süreleri hakkında bilgilendirilir. (6) İdari gözetim altına alınan kişi veya yasal temsilcisi ya da avukatı, idari gözetim kararına karşı sulh ceza hâkimine başvurabilir. Başvuru idari gözetimi durdurmaz. Dilekçenin idareye verilmesi hâlinde, dilekçe yetkili sulh ceza hâkimine derhâl ulaştırılır. Sulh ceza hâkimi incelemeyi beş gün içinde sonuçlandırır. Sulh ceza hâkiminin kararı kesindir. İdari gözetim altına alınan kişi veya yasal temsilcisi ya da avukatı, idari gözetim şartlarının ortadan kalktığı veya değiştiği iddiasıyla yeniden sulh ceza hâkimine başvurabilir. (7) İdari gözetim işlemine karşı yargı yoluna başvuranlardan, avukatlık ücretlerini karşılama imkânı bulunmayanlara, talepleri hâlinde 1136 sayılı Avukatlık Kanunu hükümlerine göre avukatlık hizmeti sağlanır. (8) (Ek:6/12/2019-7196/77 md.) İdari gözetim altına alınan yabancıların uyruklarının tespit edilmesi amacıyla elektronik ve iletişim cihazları incelenebilir. İnceleme sonucunda elde edilen veriler bu amaç dışında kullanılmaz.",
  "Yabancılar m.57/A": "MADDE 57/A- (Ek:6/12/2019-7196/78 md.) (1) 57 nci maddenin ikinci fıkrasında sayılan yabancılara ya da idari gözetimi sonlandırılan yabancılara aşağıdaki idari gözetime alternatif yükümlülükler getirilebilir: a) Belirli adreste ikamet etme b) Bildirimde bulunma c) Aile temelli geri dönüş ç) Geri dönüş danışmanlığı d) Kamu yararına hizmetlerde gönüllülük esasıyla görev alma e) Teminat f) Elektronik izleme (2) Yabancıya birinci fıkradaki yükümlülüklerden bir ya da birkaçının getirilmesi durumunda, bu süre yirmi dört ayı geçemez. (...) (5) Elektronik izleme yükümlülüğüne tabi tutulan yabancı veya yasal temsilcisi ya da avukatı bu karara karşı sulh ceza hâkimine başvurabilir. Başvuru yabancının tabi tutulduğu idari yükümlülüğü durdurmaz. Sulh ceza hâkimi incelemeyi beş gün içinde sonuçlandırır. Sulh ceza hâkiminin kararı kesindir.",
  "Yabancılar m.58": "MADDE 58 – (1) İdari gözetime alınan yabancılar, geri gönderme merkezlerinde tutulurlar. (2) Geri gönderme merkezleri Bakanlık tarafından işletilir. Bakanlık, kamu kurum ve kuruluşları, Türkiye Kızılay Derneği veya kamu yararına çalışan derneklerden göç alanında uzmanlığı bulunanlarla protokol yaparak bu merkezleri işlettirebilir.",
  "Yabancılar m.59": "MADDE 59 – (1) Geri gönderme merkezlerinde; a) Yabancı tarafından bedeli karşılanamayan acil ve temel sağlık hizmetleri ücretsiz verilir, b) Yabancıya; yakınlarına, notere, yasal temsilciye ve avukata erişme ve bunlarla görüşme yapabilme, ayrıca telefon hizmetlerine erişme imkânı sağlanır, c) Yabancıya; ziyaretçileri, vatandaşı olduğu ülke konsolosluk yetkilisi, Birleşmiş Milletler Mülteciler Yüksek Komiserliği görevlisiyle görüşebilme imkânı sağlanır, ç) Çocukların yüksek yararları gözetilir, aileler ayrı yerlerde barındırılır, d) Çocukların eğitim ve öğretimden yararlandırılmaları hususunda, Millî Eğitim Bakanlığınca gerekli tedbirler alınır. (2) Göç alanında uzmanlığı bulunan ilgili sivil toplum kuruluşu temsilcileri, Genel Müdürlüğün izniyle geri gönderme merkezlerini ziyaret edebilirler.",
  "Yabancılar m.6": "MADDE 6 – (1) Yabancı, pasaport veya pasaport yerine geçen belge ya da belgelerini, Türkiye'ye giriş ve Türkiye'den çıkışlarda görevlilere göstermek zorundadır. (...) (5) Bu maddenin uygulanmasında, kapsamlı kontrole tabi tutulması gerekli görülenler en fazla dört saat bekletilebilir. Yabancı, bu süre içerisinde her an ülkesine dönebileceği gibi dört saatlik süreyle sınırlı kalmaksızın ülkeye kabulle ilgili işlemlerin sonuçlanmasını da bekleyebilir. Kapsamlı kontrol işlemlerine dair usul ve esaslar yönetmelikle düzenlenir.",
  "Yabancılar m.60": "MADDE 60 – (1) Geri gönderme merkezlerindeki yabancılar, kolluk birimi tarafından sınır kapılarına götürülür. (2) Geri gönderme merkezlerine sevk edilmesine gerek kalmadan sınır dışı edilecek olan yabancılar, Genel Müdürlük taşra teşkilatının koordinesinde kolluk birimlerince sınır kapılarına götürülür. (3) (Değişik:6/12/2019-7196/80 md.) Sınır dışı edilecek yabancıların seyahat masrafları kendilerince karşılanır. Seyahat masraflarının karşılanması hususunda aşağıdaki hükümler uygulanır: a) Yabancının mevcut parası sınır dışı seyahat masraflarının tamamını karşılamaya yetiyorsa ... yabancının mevcut parasından karşılanır ve artan tutar kendisine bırakılır. b) Yabancının hiç parası yoksa seyahat masraflarının tamamı Genel Müdürlükçe karşılanır. c) Yabancının mevcut parası seyahat masraflarının tamamını karşılamaya yetmiyorsa; (...) Genel Müdürlükçe karşılanır (...) ç) Masraflar geri ödenmediği sürece, yabancıların Türkiye'ye girişine izin verilmeyebilir. (...) (5) Yabancıların pasaportları veya diğer belgeleri, sınır dışı edilinceye kadar tutulabilir ve sınır dışı işlemlerinde kullanılmak üzere biletleri paraya çevrilebilir.",
  "Yabancılar m.61": "MADDE 61 – (1) Avrupa ülkelerinde meydana gelen olaylar nedeniyle; ırkı, dini, tabiiyeti, belli bir toplumsal gruba mensubiyeti veya siyasi düşüncelerinden dolayı zulme uğrayacağından haklı sebeplerle korktuğu için vatandaşı olduğu ülkenin dışında bulunan (...) yabancıya (...) statü belirleme işlemleri sonrasında mülteci statüsü verilir. MADDE 62 – (1) Avrupa ülkeleri dışında meydana gelen olaylar sebebiyle; (...) statü belirleme işlemleri sonrasında şartlı mülteci statüsü verilir. Üçüncü ülkeye yerleştirilinceye kadar, şartlı mültecinin Türkiye'de kalmasına izin verilir. MADDE 63 – (1) Mülteci veya şartlı mülteci olarak nitelendirilemeyen, ancak menşe ülkesine veya ikamet ülkesine geri gönderildiği takdirde; a) Ölüm cezasına mahkûm olacak veya ölüm cezası infaz edilecek, b) İşkenceye, insanlık dışı ya da onur kırıcı ceza veya muameleye maruz kalacak, c) Uluslararası veya ülke genelindeki silahlı çatışma durumlarında, ayrım gözetmeyen şiddet hareketleri nedeniyle şahsına yönelik ciddi tehditle karşılaşacak, olması nedeniyle (...) statü belirleme işlemleri sonrasında ikincil koruma statüsü verilir.",
  "Yabancılar m.62": "MADDE 62 – (1) Avrupa ülkeleri dışında meydana gelen olaylar sebebiyle; ırkı, dini, tabiiyeti, belli bir toplumsal gruba mensubiyeti veya siyasi düşüncelerinden dolayı zulme uğrayacağından haklı sebeplerle korktuğu için vatandaşı olduğu ülkenin dışında bulunan ve bu ülkenin korumasından yararlanamayan, ya da söz konusu korku nedeniyle yararlanmak istemeyen yabancıya veya bu tür olaylar sonucu önceden yaşadığı ikamet ülkesinin dışında bulunan, oraya dönemeyen veya söz konusu korku nedeniyle dönmek istemeyen vatansız kişiye statü belirleme işlemleri sonrasında şartlı mülteci statüsü verilir. Üçüncü ülkeye yerleştirilinceye kadar, şartlı mültecinin Türkiye'de kalmasına izin verilir.",
  "Yabancılar m.63": "MADDE 63 – (1) Mülteci veya şartlı mülteci olarak nitelendirilemeyen, ancak menşe ülkesine veya ikamet ülkesine geri gönderildiği takdirde; a) Ölüm cezasına mahkûm olacak veya ölüm cezası infaz edilecek, b) İşkenceye, insanlık dışı ya da onur kırıcı ceza veya muameleye maruz kalacak, c) Uluslararası veya ülke genelindeki silahlı çatışma durumlarında, ayrım gözetmeyen şiddet hareketleri nedeniyle şahsına yönelik ciddi tehditle karşılaşacak, olması nedeniyle menşe ülkesinin veya ikamet ülkesinin korumasından yararlanamayan veya söz konusu tehdit nedeniyle yararlanmak istemeyen yabancı ya da vatansız kişiye, statü belirleme işlemleri sonrasında ikincil koruma statüsü verilir.",
  "Yabancılar m.64": "MADDE 64 – (1) Başvuru sahibi; a) Birleşmiş Milletler Mülteciler Yüksek Komiserliği dışında, diğer bir Birleşmiş Milletler organı veya örgütünden hâlen koruma veya yardım görüyorsa, b) İkamet ettiği ülke yetkili makamlarınca, o ülke vatandaşlarının sahip bulundukları hak ve yükümlülüklere sahip olarak tanınıyorsa, c) Sözleşmenin 1 inci maddesinin (F) fıkrasında belirtilen fiillerden suçlu olduğuna dair ciddi kanaat varsa, uluslararası korumadan hariçte tutulur. (...) (6) Başvuru sahibinin uluslararası korumadan hariçte tutulması, hariçte tutma nedenlerinden herhangi birinin diğer aile üyeleri için oluşmaması şartıyla, başvuru sahibinin aile üyelerinin de hariçte tutulmasını gerektirmez.",
  "Yabancılar m.7": "MADDE 7 – (1) Aşağıdaki yabancılar, kabul edilemeyen yolcu kapsamına alınır ve Türkiye'ye girişlerine izin verilmeyerek geri çevrilir: a) Pasaportu, pasaport yerine geçen belgesi, vizesi veya ikamet ya da çalışma izni olmayanlar ile bu belgeleri veya izinleri hileli yollarla edindiği veya sahte olduğu anlaşılanlar b) Vize, vize muafiyeti veya ikamet izin süresinin bitiminden itibaren en az altmış gün süreli pasaport veya pasaport yerine geçen belgesi olmayanlar c) 15 inci maddenin ikinci fıkrası saklı kalmak kaydıyla, vize muafiyeti kapsamında olsalar dahi, 15 inci maddenin birinci fıkrasında sayılan yabancılar (...) (3) (...) Bu madde kapsamındaki yabancılar, işlemleri sonuçlanıncaya kadar sınır kapılarında kendileri için belirlenen alanlarda bekletilir.",
  "Yakalama Yön m.10": "Gözaltı birimine getirilen kişi hakkında aşağıdaki hükümler uygulanır: a) Nezarethaneye veya zorunlu hâllerde bu amaca tahsis edilen yerlere konulmadan önce usulünce aranır. Kadının üst veya vücudunun aranması, bir kadın görevli veya bu amaçla görevlendirilecek diğer bir kadın tarafından yapılır. b) Kendisine zarar verebilecek kemer, kravat, ip, kesici ve delici alet gibi nesnelerden arındırılır. c) Üzerinden çıkan eşya ve para muhafaza altına alınır. Paranın nev'i, seri numarası ve miktarı, eşyanın vasıfları ve markasını belirten bir tutanak düzenlenir ve bu tutanağın bir sureti üstü aranan kişiye verilir.",
  "Yakalama Yön m.11": "a) Aynı suçla ilgisi olanlar, birbirine hasım olanlar, erkek ve kadınlar bir araya konulmazlar, çocuklar yetişkinlerden ayrı tutulurlar. b) Nezarethanede zarurî hâller dışında beşten fazla kişi bir arada bulundurulmaz.",
  "Yakalama Yön m.13": "Gözaltı süresi, yakalama yerine en yakın hâkim veya mahkemeye gönderilmesi için zorunlu süre hariç, yakalama anından itibaren yirmidört saati geçemez. Yakalama yerine en yakın hâkim veya mahkemeye gönderilme için zorunlu süre oniki saatten fazla olamaz.",
  "Yakalama Yön m.14": "Toplu olarak işlenen suçlarda, delillerin toplanmasında güçlük veya şüpheli sayısının çokluğu nedeniyle Cumhuriyet savcısı gözaltı süresini her defasında bir günü geçmemek üzere, üç gün süreyle uzatılmasına yazılı olarak emir verebilir. Gözaltı süresinin uzatılması emri, gözaltına alınana derhâl tebliğ edilir. Kimse, bu süreler geçtikten sonra hâkim kararı olmaksızın hürriyetinden mahrum bırakılamaz. (...) Anayasanın 120 nci maddesi gereğince olağanüstü hâl ilân edilen bölgelerde yakalanan kişiler hakkında, (...) dört gün olarak belirlenen süre, Cumhuriyet savcısının talebi ve hâkim kararı ile yedi güne kadar uzatılabilir.",
  "Yakalama Yön m.15": "Yakalama, gözaltına alma işlemine veya gözaltı süresinin uzatılmasına ilişkin Cumhuriyet savcısının yazılı emrine karşı, yakalanan kişi, müdafi veya kanunî temsilcisi, eşi ya da birinci veya ikinci derecede kan hısımı hemen serbest bırakılmasını sağlamak için sulh ceza hâkimine başvurabilir. Yakalanan kişinin dilekçesi yetkili hâkime en seri şekilde ulaştırılır.",
  "Yakalama Yön m.18": "Gözaltı süresinin dolması veya sulh ceza hâkiminin kararı üzerine, gözaltına alınıp da serbest bırakılan kişi hakkında yakalamaya neden olan fiille ilgili yeni ve yeterli delil elde edilmedikçe ve Cumhuriyet savcısının kararı olmadıkça bir daha aynı nedenle yakalama işlemi uygulanamaz.",
  "Yakalama Yön m.19": "a) Fiili işlediği zaman oniki yaşını doldurmamış olanlar ile onbeş yaşını doldurmamış sağır ve dilsizler; 1) Suç nedeni ile yakalanamaz ve hiçbir suretle suç tespitinde kullanılamaz. 2) Kimlik ve suç tespiti amacı ile yakalama yapılabilir. Kimlik tespitinden hemen sonra serbest bırakılır. (...) b) Oniki yaşını doldurmuş, ancak onsekiz yaşını doldurmamış olanlar suç sebebi ile yakalanabilirler. Bu çocuklar, yakınları ile müdafiye haber verilerek derhâl Cumhuriyet başsavcılığına sevk edilirler (...) 10) Çocuklara kelepçe ve benzeri aletler takılamaz. Ancak, zorunlu hâllerde çocuğun kaçmasını, kendisinin veya başkalarının hayat veya beden bütünlükleri bakımından doğabilecek tehlikeleri önlemek için kolluk tarafından gerekli önlemler alınır.",
  "Yakalama Yön m.20": "Soruşturma evresinde, ifade almada en çok üç müdafi hazır bulunabilir. (...) Şüpheli veya sanık onsekiz yaşını doldurmamış ya da sağır veya dilsiz veya kendisini savunamayacak derecede malûl olur ve bir müdafiî de bulunmazsa talebi aranmaksızın bir müdafi görevlendirilir. Üst sınırı en az beş yıl hapis cezasını gerektiren suçlardan dolayı yapılan soruşturma ve kovuşturmada şüpheli veya sanığın talebi aranmaksızın bir müdafi görevlendirilir.",
  "Yakalama Yön m.22": "Müdafi, soruşturma evresinde dosya içeriğini inceleyebilir ve istediği belgelerin bir örneğini harçsız olarak alabilir. (...) Müdafi, Cumhuriyet başsavcılığınca iddianamenin mahkemeye verildiği tarihten itibaren dosya içeriğini ve muhafaza altına alınmış delilleri inceleyebilir; bütün tutanak ve belgelerin örneklerini harçsız olarak alabilir. Bu maddenin içerdiği haklardan suçtan zarar görenin vekili de yararlanır.\" (Not: birinci fıkradaki \"Kollukta bulunan soruşturma dosyası için yetkili Cumhuriyet savcısının yazılı emri gerekir\" ibaresi Danıştay kararıyla **iptal** edilmiştir; müdafiin dosya incelemesi için savcının yazılı emri **aranmaz**. Müdafiin incelemesini kısıtlayan iki fıkra ise Danıştay 10. D. 9/10/2024 E.:2024/1960 ile **yürütmesi durdurulduğu** için karta alınmamıştır.)",
  "Yakalama Yön m.23": "Şüphelinin ifadesinin alınmasında aşağıdaki hususlara uyulur: a) Şüphelinin kimliği saptanır. Şüpheli, kimliğine ilişkin soruları doğru olarak cevaplandırmakla yükümlüdür. b) Kendisine yüklenen suç anlatılır. c) Müdafi seçme hakkının bulunduğu ve onun hukukî yardımından yararlanabileceği, müdafiîn ifade sırasında hazır bulunabileceği kendisine bildirilir. (...) d) Müdafi sadece hukukî yardımda bulunabilir, şüphelinin ifadesi alınırken şüpheliye sorulan soruya doğrudan cevap veremez, onun yerini aldığı izlenimi veren herhangi bir müdahalede bulunamaz. (...) f) Yüklenen suç hakkında açıklamada bulunmamasının kanunî hakkı olduğu söylenir. (...) j) İfade bir tutanağa bağlanır. (...) İfade esasları bu Yönetmeliğe ekli İfade Tutanağı (EK-D) formatına uygun olarak yerine getirilir.",
  "Yakalama Yön m.24": "İfade veren şüphelinin beyanı, özgür iradesine dayanmalıdır. Bunu engelleyici nitelikte kötü davranma, işkence, ilâç verme, yorma, aldatma, cebir veya tehditte bulunma, bazı araçları kullanma gibi bedensel veya ruhsal müdahaleler yapılamaz. Kanuna aykırı bir yarar vaat edilemez. Yasak usullerle elde edilen ifadeler rıza ile verilmiş olsa da delil olarak değerlendirilemez. Şüphelinin aynı olayla ilgili olarak yeniden ifadesinin alınması ihtiyacı ortaya çıktığında, bu işlem ancak Cumhuriyet savcısı tarafından yapılabilir. Hiç kimse, kendisini veya kanunda gösterilen yakınlarını suçlayan bir beyanda bulunmaya veya bu yolda delil göstermeye zorlanamaz.",
  "Yakalama Yön m.25": "Nezarethaneler en az 7 metrekare genişliğinde, 2,5 metre yüksekliğinde ve duvarlar arasında en az 2 metre mesafe olacak şekilde düzenlenir. Yeterli doğal ışıklandırma ve havalandırma imkânları sağlanır. (...)",
  "Yakalama Yön m.26": "Nezarethane ve ifade alma odalarının standartlara uygunluğunu sağlamak amacı ile kolluk kuvvetlerinin yetkili birimleri tarafından denetleme yapılır. Cumhuriyet başsavcıları veya görevlendirecekleri Cumhuriyet savcıları, adlî görevlerinin gereği olarak, gözaltına alınan kişilerin bulundurulacakları nezarethaneleri, varsa ifade alma odalarını, bu kişilerin durumlarını, gözaltına alınma neden ve sürelerini, gözaltına alınma ile ilgili tüm kayıt ve işlemleri denetler; sonucunu Nezarethaneye Alınanların Kaydına Ait Deftere kaydederler. Yetkili ve görevli mercilerin mevzuatta öngörülen denetim yetkileri saklıdır.",
  "Yakalama Yön m.27": "Suçluluğu bir yargı hükmüne bağlanana kadar kişinin masumiyeti esastır ve soruşturma evresi gizlidir. Bu nedenle, soruşturma evresinde gözaltındaki bir kişinin 'suçlu' olarak kamuoyuna duyurulmasına, basın önüne çıkartılmasına, kişilerin basınla sorulu cevaplı görüştürülmelerine, görüntülerinin alınmasına, teşhir edilmelerine sebebiyet verilmez ve soruşturma evrakı hiçbir şekilde yayımlanamaz.",
  "Yakalama Yön m.28": "Cumhuriyet savcısı, kendisine yüklenen suç hakkında açıklamada bulunmuş olan şüpheliye yer gösterme işlemi yaptırabilir. 5271 sayılı Ceza Muhakemesi Kanununun 250 nci maddesinin birinci fıkrası kapsamına giren suçlar söz konusu olduğunda, adlî kolluk âmiri de yer gösterme işlemi yaptırmaya yetkilidir. Bu suçlar dışında yer gösterme işlemi kolluk âmirleri tarafından yaptırılamaz.",
  "Yakalama Yön m.4": "Yakalama: Kamu güvenliğine, kamu düzenine veya kişinin vücut veya hayatına yönelik var olan bir tehlikenin giderilmesi için denetim altına alınması gereken veya suç işlediği yönünde hakkında kuvvetli iz, eser, emare ve delil bulunan kişinin gözaltına veya muhafaza altına alma işlemlerinden önce özgürlüğünün geçici olarak ve fiilen kısıtlanarak denetim altına alınmasını\"; \"Gözaltına alma: Kanunun verdiği yetkiye göre, yakalanan kişinin hakkındaki işlemlerin tamamlanması amacıyla, yetkili hâkim önüne çıkarılmasına veya serbest bırakılmasına kadar kanunî süre içinde sağlığına zarar vermeyecek şekilde özgürlüğünün geçici olarak kısıtlanıp alıkonulmasını\"; \"Muhafaza altına alma: Kanunun yetki verdiği hâllerde yetkili merci önüne çıkarılması gereken kişilerin ilgili kurumlar veya kişilerce teslim alınana kadar sağlıklarına zarar vermeyecek şekilde ve zorunlu olduğu ölçüde özgürlüklerinin kısıtlanıp alıkonulmasını\" ifade eder.\n\nŞüpheli: Soruşturma evresinde, suç şüphesi altında bulunan kişiyi\"; \"Sanık: Kovuşturmanın başlamasından itibaren hükmün kesinleşmesine kadar, suç şüphesi altında bulunan kişiyi\"; \"Suçüstü: İşlenmekte olan suçu, henüz işlenmiş olan fiil ile fiilin işlenmesinden hemen sonra kolluk, suçtan zarar gören veya başkaları tarafından takip edilerek yakalanan kişinin işlediği suçu, fiilin pek az önce işlendiğini gösteren eşya veya delille yakalanan kimsenin işlediği suçu\"; \"Toplu suç: Aralarında iştirak iradesi bulunmasa da üç veya daha fazla kişi tarafından işlenen suçu\" ifade eder.",
  "Yakalama Yön m.5": "Kolluk görevlileri; a) Gecikmesinde sakınca bulunan ve Cumhuriyet savcısına veya derhâl âmirlerine müracaat imkânı olmayan hâllerde; hakkında yakalama emri düzenlenmesi veya tutuklama kararı verilmesi gereken kişileri ya da suçüstü hâlinde veya gecikmesinde sakınca bulunan diğer hâllerde suç işlendiğine veya suça teşebbüs edildiğine dair haklarında kuvvetli iz, eser, emare ve delil bulunan şüphelileri, (...) yakalayabilir.\n\nKimliğini bir belgeyle veya kolluk kuvvetince tanınmış veya güvenilir kişilerin tanıklığı ile ispat edemeyenlerle, gösterdikleri belgelerin doğruluğundan şüphe edilen kişileri, aranan kişilerden olup olmadıkları anlaşılıncaya veya gerçek kimliği ortaya çıkıncaya kadar yirmidört saati geçmemek üzere, yakalama ve muhafaza altına almaya yetkilidir. Bu kişilere kimliklerini ispatlamaları hususunda gerekli kolaylık gösterilir.\n\nAşağıda belirtilen hâllerde, herkes tarafından geçici olarak yakalama yapılabilir: a) Kişiye suçu işlerken rastlanması, b) Suçüstü bir fiilden dolayı izlenen kişinin kaçması ihtimalinin bulunması veya hemen kimliğini belirleme imkânının bulunmaması.\" · \"Soruşturma ve kovuşturması şikâyete bağlı olmakla birlikte, beden veya akıl hastalığı, malûllük veya güçsüzlükleri nedeniyle kendilerini idareden aciz bulunanlara karşı işlenen suçüstü hâllerinde kişinin yakalanması şikâyete bağlı değildir.\" · \"Soruşturma ve kovuşturması şikâyete bağlı olan suç hakkında 5271 sayılı CMK m.90/3'e göre şikâyetten önce şüpheli yakalanmış olursa şikâyete yetkili olan kimseye ve bunlar birden fazla ise hiç olmazsa birine yakalama bildirilir.\n\nKolluk görevlileri; b) Kolluk kuvvetinin kanun ve usul dairesinde verdiği emre itaatsizlik edenleri ve aldığı tedbirlere uymayanları, c) Görev yaparken mukavemette bulunan veya görevinden alıkoymak maksadıyla kolluk kuvvetine zorla karşı koyan ve yakalanmadıkları takdirde hareketlerine devam etmeleri ihtimali bulunan kişileri, d) Haklarında yetkili mercilerce verilen yakalama emri, yakalama ve tutuklama kararı bulunanları veya kanunla istenilen bir mükellefiyeti yerine getirmedikleri için yakalanması gerekenleri, e) Uyuşturucu ve uyarıcı maddeleri alan, satan, bulunduran veya kullananları, f) Halkın rahatını bozacak veya rezalet çıkaracak derecede sarhoş olanları veya sarhoşluk hâlinde başkalarına saldıranları, g) Halkın huzur ve sükûnunu bozanlardan, yapılan uyarılara rağmen bu hareketlerine devam edenlerle, başkalarına saldırıya yeltenenleri ve kavga edenleri, h) Bir kurumda tedavi, eğitim ve ıslahı için kanunlarla belirtilen esaslara uygun olarak, alınan tedbirlerin yerine getirilmesi amacıyla toplum için tehlike teşkil eden akıl hastası, uyuşturucu ve uyarıcı madde veya alkol tutkunu, serseri veya hastalık bulaştırabilecek kişileri, ı) Haklarında mahkemece çocuk bakım ve yetiştirme yurtlarına veya benzeri resmî veya özel kurumlara yerleştirilmesine veya yetkili merci önüne çıkarılmasına karar verilen çocukları, i) Usulüne aykırı şekilde ülkeye girmek isteyen veya giren veya hakkında sınır dışı etme veya geri verme kararı alınan kişileri, yakalayabilir.",
  "Yakalama Yön m.6": "Yakalanan kişiye, suç ayrımı gözetilmeksizin yakalama sebebi ve hakkındaki iddialar ile susma ve müdafiden yararlanma, yakalanmaya itiraz etme hakları ile diğer kanunî hakları ve itiraz hakkını nasıl kullanacağı, herhâlde yazılı, bunun hemen mümkün olmaması hâlinde sözlü olarak derhâl bildirilir. (...) Kolluk kuvveti tarafından yapılan yakalama hâlinde işlem, yakalanan kişi ve uygulanan tedbirler derhâl Cumhuriyet savcısına bildirilir.",
  "Yakalama Yön m.7": "Yakalanan veya tutuklanarak bir yerden diğer bir yere nakledilen kişilere, kaçacaklarına ya da kendisi veya başkalarının hayat ve beden bütünlükleri bakımından tehlike arz ettiğine ilişkin belirtilerin varlığı hâllerinde kelepçe takılabilir.",
  "Yakalama Yön m.8": "Yakalanan kişinin; a) Kendisi ile birlikte bir kişi varsa bu kişi vasıtasıyla, b) Suçun işlendiği veya yakalandığı yerde ikâmet ediyorsa ve haber vereceği yakınının telefon numarasını biliyorsa ya da kolluk vasıtasıyla sair suretle tespit edilebiliyorsa, telefon ile, c) Haber vereceği yakınının telefon numarasını bilmiyorsa ilgili yer kolluğu vasıtasıyla, d) Konutu suç yeri dışında ise telefonla veya kişinin adresinin bulunduğu yerle ilişki kurulmak suretiyle, yakalandığı, gözaltına alındığı veya gözaltı süresinin uzatıldığı Cumhuriyet savcısının emriyle gecikmeksizin bir yakınına veya belirlediği bir kişiye haber verilir. Yakalanan veya gözaltına alınan kişi yabancı ise, yazılı olarak karşı çıkmaması hâlinde, durumu vatandaşı olduğu ülkenin büyükelçiliği veya konsolosluğuna haber verilir. Muhafaza altına alınmak amacıyla kişinin yakalandığı, istediği kanunî yakınlarına derhâl bildirilir.",
  "Yakalama Yön m.9": "Hekim raporu üç nüsha hâlinde düzenlenir. (...) Yakalama veya nezarethaneye giriş raporunun bir nüshası raporu tanzim eden sağlık kuruluşunda saklanır, ikinci nüshası gözaltına alınana, üçüncü nüsha ise soruşturma dosyasına eklenmek üzere ilgili kolluk görevlisine verilir. (...) Gözaltına alınan kişinin ifadesini alan veya soruşturmayı yürüten kolluk görevlisi ile bu kişiyi tıbbî muayeneye götüren kolluk görevlisinin farklı olması zorunludur.",
  "Yardım Toplama m.10": "Madde 10 – Yardım toplama süresinin takdiri, izin veren makama aittir. Bu süre bir yılı geçemez. Ancak, haklı sebeplerin bulunması halinde verilen süre, izin veren makamca (...) uzatılabilir.",
  "Yardım Toplama m.11": "Madde 11 – Gerçek kişiler, yardım toplama faaliyeti için en az üç kişiden ibaret sorumlu kurul oluşturmak zorundadırlar. Tüzelkişilerin sorumlu kurulu, yönetim organlarıdır. Sorumlu kurulda görev alanlar ile değişikliklerin, izin veren makama on gün içinde bildirilmesi gerekir.",
  "Yardım Toplama m.12": "Madde 12 – Gazete ve dergiler tarafından toplanacak para yardımları, bankada açılacak özel bir hesaba yatırılır. Yardıma katılan kişilerin adları ve yardım tutarı, yardımda bulunanın aksi yönde isteği olmadıkça, gazete ve dergide yayımlanır. Faaliyet sonunda toplanan yardımın miktarı, gazete ve dergi ile açıklanır.",
  "Yardım Toplama m.13": "Madde 13 – Kamu görevlileri, vali veya kaymakamdan izin almadıkça yardım toplama faaliyetlerinde çalışamazlar. Çalışması için izin verilen kamu görevlilerine, her ne ad altında olursa olsun ücret verilemez. Ancak, Türk Hava Kurumu tarafından kurban derisi, bağırsak toplamak, fitre ve zekat zarfı dağıtmak suretiyle yardım toplama faaliyetlerinde görevlendirilen kamu personeline Kurumca ücret verilebilir. Silahlı Kuvvetler, adli ve idari yargıda görevli hakim ve savcılar ile güvenlik kuvvetleri mensupları ve özel kolluk görevlileri, yardım toplama faaliyetlerinde çalışamazlar.",
  "Yardım Toplama m.14": "Madde 14 – Yardım toplama faaliyetine girişenler bu faaliyetin düzenli ve verimli bir şekilde yürütülmesinden, süresi içinde sonuçlandırılmasından, toplanan para ve eşyanın korunmasından ve amaca uygun şekilde kullanılmasından sorumludur.",
  "Yardım Toplama m.6": "Madde 6 – Kişiler ve kuruluşlar, yetkili makamdan izin almadan yardım toplayamazlar. Ancak, kamu yararına çalışan dernek, kurum ve vakıflardan hangilerinin izin almadan yardım toplayabilecekleri, Cumhurbaşkanınca belirlenip ilan edilir. İzin alınmadan girişilen yardım toplama faaliyetleri güvenlik kuvvetlerince derhal menedilir ve sorumlular hakkında kovuşturma yapılır.\n\n(Ek fıkra:27/12/2020-7262/7 md.) İzinsiz yardım toplama faaliyetinin internet ortamında yapıldığının tespiti hâlinde ilgili valilik veya İçişleri Bakanlığı tarafından içerik ve/veya yer sağlayıcıya, yardım toplama faaliyetine ilişkin içeriğin çıkarılması için internet sayfalarındaki iletişim araçları, alan adı, IP adresi ve benzeri kaynaklarla elde edilen bilgiler üzerinden elektronik posta veya diğer iletişim araçları ile bildirimde bulunulur. İçeriğin en geç yirmi dört saat içinde içerik ve/veya yer sağlayıcı tarafından çıkarılmaması veya içerik ve yer sağlayıcıya ilişkin bilgilerin edinilememesi ya da teknik nedenlerle bildirimde bulunulamaması hâlinde ilgili valilik veya İçişleri Bakanlığı internet ortamındaki söz konusu içeriğe ilişkin erişimin engellenmesine karar verilmesi için sulh ceza hâkimliğine başvurur. (...)",
  "Yardım Toplama m.7": "Madde 7 – (Değişik: 4/11/2004-5253/38 md.) Yardım toplama faaliyeti bir ilin birden fazla ilçesini kapsıyorsa o ilin valisinden, bir ilçenin sınırları içinde ise o ilçenin kaymakamından izin alınır. Yardım toplama faaliyeti birden fazla ili kapsıyorsa yardım toplama faaliyetine girişecek gerçek veya tüzel kişilerin yerleşim yerinin bulunduğu ilin valisinden izin alınır ve izni veren valilik tarafından ilgili valiliklere ve İçişleri Bakanlığına bilgi verilir. Yardım toplama faaliyetleriyle ilgili işlemler dernekler birimlerince yürütülür.",
  "Yardım Toplama m.8": "Madde 8 – Yardım toplayacak kişi ve kuruluşlar, isteklerini bir dilekçeyle izin vermeye yetkili makama bildirirler. Gazete ve dergiler için dilekçeler sorumlu yazı işleri müdürlerince verilir. Yardım toplama, öğrenim kurumları yararına veya kurum içinde yapılacak ise, başvuru dilekçesine kurum sorumlusunun yazılı izninin eklenmesi zorunludur. Başvuru dilekçelerinde bulunması gereken hususlar ve eklenecek belgeler yönetmelikte gösterilir.",
  "Yardım Toplama m.9": "Madde 9 – İzin vermeye yetkili makamlarca başvuru üzerine; işin önemi, yardım toplama faaliyetine girişeceklerin yeterlikleri, yapılacak hizmetin amaca ve kamu yararına uygunluğu, yardım toplama faaliyetinin başarıya ulaşıp ulaşamayacağı ve gerekli görülen diğer konular üzerinde inceleme yapılır ve sonucu en geç iki ay içinde başvuranlara bildirilir.",
  "Zilyetlik m.10": "Tecavüz veya müdahalesi önlenen kişi, taşınmaz mal üzerinde vücuda getirdiği her türlü ekim, tesis ve değişikliklerden dolayı ancak genel hükümler dairesinde yargı yoluna başvurabilir.\" (Madde 10)",
  "Zilyetlik m.12": "Taşınmaz mala aynı mütecaviz tarafından ikinci defa veya onun yararına başkaları tarafından bilerek ilk defa tecavüz veya müdahalelerle ilgili başvurularda da birinci başvuruda olduğu gibi soruşturma yapılır ve sonucu karara bağlanır. Tecavüz veya müdahale varsa 9 uncu madde hükümlerine göre karar uygulanır, her iki kararla ilgili dosya, karar vermeye yetkili makamlarca, 15 inci maddeye göre işlem yapılmak üzere adli mercilere gönderilir.\" (Madde 12)",
  "Zilyetlik m.15": "Mahkeme kararıyla kendisine teslim edilmeksizin aynı taşınmaz mala ikinci defa yapılan tecavüz veya müdahale, (...) fiil daha ağır bir cezayı gerektiren ayrı bir suç teşkil etmediği takdirde, bu suçu işleyenler hakkında; a) Taşınmaz mal, kamu kurum veya kuruluşlarına ait bulunuyorsa veya Devletin hüküm ve tasarrufu altında bulunan sahipsiz veya umumun menfaatine ait yerlerden ise altı aydan iki yıla kadar; şayet taşınmaz mal diğer tüzelkişilere veya gerçek kişilere ait ise üç aydan bir yıla kadar hapis cezasına hükmolunur. b) Tecavüz veya müdahale silahlı bir kişi veya silahsız olsalar dahi birden fazla kişiler tarafından yapıldığı takdirde (a) bendindeki cezalar bir kat artırılarak hükmolunur. c) Tecavüz veya müdahale taşınmaz malı aralarında paylaşmak veya ortaklaşa kullanmak amacıyla iki veya daha çok kişinin birleşmesiyle işlenirse (b) bendi ile artırılan ceza ayrıca üçte bir oranında artırılır. Bu amaçla birleşen kişilerden en az birisinin silahlı olması halinde ise (b) bendi ile artırılan ceza ayrıca yarı oranında artırılarak hükmolunur.",
  "Zilyetlik m.2": "Taşınmaz mallara tecavüz veya müdahale edilmesi halinde; taşınmaz mal merkez ilçe sınırları içinde ise, il valisi veya görevlendireceği vali yardımcısı, diğer ilçelerde ise kaymakamlar tarafından bu tecavüz veya müdahalenin önlenmesine karar verilir ve taşınmaz mal yerinde zilyedine teslim edilir.",
  "Zilyetlik m.3": "Taşınmaz mala yapılan tecavüz veya müdahalenin önlenmesi için, yetkili makamlara başvurmaya, o taşınmaz malın zilyedi, zilyed birden fazla ise içlerinden biri yetkilidir. Kamu idareleri, kamu kurumları ve kamu kuruluşları ile tüzelkişilerin başvuruları, taşınmaz malın ait olduğu idare, kurum, kuruluş ve tüzelkişinin yetkilisi tarafından yapılır. Köye ait taşınmaz mallara yapılan tecavüz veya müdahalelerde, köy halkından herhangi biri de yetkili makama başvuruda bulunabilir. Vali veya kaymakam görev alanları içinde bulunan kamu idarelerine (...) veya Devletin hüküm ve tasarrufu altında bulunan sahipsiz yerlere veya menfaati umuma ait olan taşınmaz mallara tecavüz veya müdahalede bulunulduğunu öğrendiklerinde, soruşturmayı doğrudan doğruya yaptırırlar ve sonucu karara bağlarlar.",
  "Zilyetlik m.4": "Yetkililerin; tecavüz veya müdahalenin yapıldığını öğrendikleri tarihten altmış gün içinde, idari makama başvuruda bulunmaları gerekir. Ancak, tecavüz veya müdahalenin oluşundan itibaren bir yıl geçtikten sonra bu makamlara başvuruda bulunulamaz. Devletin hüküm ve tasarrufu altında bulunan yerlerle menfaati umuma ait olan taşınmaz mallara yapılan tecavüz veya müdahalelerde süre aranmaz.",
  "Zilyetlik m.5": "Başvuru üzerine, karar vermeye yetkili kişiler veya bunların görevlendireceği bir veya birkaç memur tarafından yerinde soruşturma yapılır. Soruşturmayı yapan kişilere gerektiğinde teknik eleman ve yardımcı verilir. Bu Kanun kapsamı dışında kaldığı dilekçeden açıkça ve kesinlikle anlaşılan başvurular, yerinde soruşturma yapılmadan yazılı olarak reddedilebilir. Taşınmaz mal, aynı il'e bağlı ilçelerarası sınır anlaşmazlığı bulunan bir yerde ise yetkili kaymakamlığı vali; illerarası sınır anlaşmazlığı bulunan bir yerde ise yetkili valiliği veya kaymakamlığı İçişleri Bakanlığı belirler.\" (Madde 5)",
  "Zilyetlik m.6": "Soruşturma memuru, tarafların şahitlerini dinledikten sonra gerekli gördüğü takdirde tarafsız kişileri ve ilgisine göre hazine, özel idare ve belediye temsilcilerini, köy muhtar ve ihtiyar kurulu üyelerini de dinleyebilir. İfadeler, Ceza Muhakemesi Kanunundaki hükümler dairesinde yeminli olarak alınır. Soruşturma en geç 15 gün içinde tamamlanarak karara bağlanır.",
  "Zilyetlik m.7": "Bu Kanuna göre verilen kararlar idari yargı yolu açık olmak üzere kesindir. Ancak, açık olan yazı ve hesap hataları karar veren yetkili makamca kendiliğinden düzeltilir. Taşınmaz mal üzerinde üstün sayılabilecek bir hakkı olduğunu iddia edenlerin yargı yoluna başvurması gerektiği kararda belirtilir.",
  "Zilyetlik m.8": "Soruşturmanın yapılacağı, kararın yerine getirileceği yer, tarih ve saat taraflara tebliğ edilir. (...) Mütecavize tebligat yapılamaması halinde soruşturmanın yapılacağı veya kararın yerine getirileceği yer, tarih ve saat 3 gün önceden alışılmış usullerle taşınmaz malın bulunduğu köy veya beldede ilan edilir. Mütecaviz gelmezse soruşturma ve kararın yerine getirilmesi yokluğunda yapılır. Yetkili makamların, talebin esastan veya süreden reddine ilişkin karar ve işlemleri, 7201 sayılı Tebligat Kanunu hükümlerine göre ilgililere duyurulur.",
  "Zilyetlik m.9": "Tecavüz veya müdahalenin önlenmesi hakkındaki kararlar, karar vermeye yetkili amirce görevlendirilecek infaz memuru tarafından, taşınmaz malın yerinde ve o andaki durumu ile zilyedine, tüzelkişiliğe veya kamu idareleri, kamu kurumları ve kuruluşlarına teslim edilmesi suretiyle yerine getirilir. Karar gereğinin, kararın infaz memuruna geldiği tarihten itibaren en geç 5 gün içinde yerine getirilmesi zorunludur. (...) Mahallin en büyük mülki idare amirinin yazılı emri ile güvenlik kuvvetlerince, gerek soruşturma, gerekse kararın yerine getirilmesi sırasında mahallinde, gerekli önlemler alınır.",
};
